INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (3385,'黑市交易','他们把自己称为黑市成员，他们都是些贪财如命的杂碎，只要有利可图，他们什么都会倒卖！$B$B现在情况变得更加糟糕了，$N。他们在灼热峡谷建立了一个基地，贸易首领考维克在那里策划着所有的行动，并且和该地区的黑铁矮人保持着密切的关系。$B$B我们必须对这种行为进行严厉打击，给他们一个严厉的警告。去杀掉贸易首领考维克和他的同伙科朗克，把他的商人的背包给我拿回来，你的任务就算完成了。$B$B向大熔炉进发！','杀了贸易首领考维克和他的同伙科朗克。从他的尸体上拿回商人的背包，把它交给尼莉丝。','你对黑市进行了一次致命的打击。他们的领袖在派更多人进入灼热峡谷之前一定会考虑再三的。$B$B哦，我在这个商人的背包里没找到什么有用的东西，你可以随便把它处理掉了。$B','那家伙还活着吗?') ON DUPLICATE KEY UPDATE Title_loc4='黑市交易',Details_loc4='他们把自己称为黑市成员，他们都是些贪财如命的杂碎，只要有利可图，他们什么都会倒卖！$B$B现在情况变得更加糟糕了，$N。他们在灼热峡谷建立了一个基地，贸易首领考维克在那里策划着所有的行动，并且和该地区的黑铁矮人保持着密切的关系。$B$B我们必须对这种行为进行严厉打击，给他们一个严厉的警告。去杀掉贸易首领考维克和他的同伙科朗克，把他的商人的背包给我拿回来，你的任务就算完成了。$B$B向大熔炉进发！',Objectives_loc4='杀了贸易首领考维克和他的同伙科朗克。从他的尸体上拿回商人的背包，把它交给尼莉丝。',OfferRewardText_loc4='你对黑市进行了一次致命的打击。他们的领袖在派更多人进入灼热峡谷之前一定会考虑再三的。$B$B哦，我在这个商人的背包里没找到什么有用的东西，你可以随便把它处理掉了。$B',RequestItemsText_loc4='那家伙还活着吗?';
INSERT INTO locales_quest(entry,Title_loc4) VALUES (3401,'<UNUSED>') ON DUPLICATE KEY UPDATE Title_loc4='<UNUSED>';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (3402,'黑市交易','我要你把考维克被干掉的消息亲自带给加基森的维兹格里克，他知道考维克死亡的消息一定会很高兴的，我敢说他肯定会为此给你丰厚的奖励。','和加基森的维兹格里克谈一谈。','考维克被干掉了?真是让人兴奋的一天啊，$N!这些年来，这个恶棍一直都在从事黑市交易，欺压全世界老实交易的辛苦商人。$B$B你理应为这个成就获得一份奖励!一份丰厚的奖励!$B','想要看看我的商品吗?') ON DUPLICATE KEY UPDATE Title_loc4='黑市交易',Details_loc4='我要你把考维克被干掉的消息亲自带给加基森的维兹格里克，他知道考维克死亡的消息一定会很高兴的，我敢说他肯定会为此给你丰厚的奖励。',Objectives_loc4='和加基森的维兹格里克谈一谈。',OfferRewardText_loc4='考维克被干掉了?真是让人兴奋的一天啊，$N!这些年来，这个恶棍一直都在从事黑市交易，欺压全世界老实交易的辛苦商人。$B$B你理应为这个成就获得一份奖励!一份丰厚的奖励!$B',RequestItemsText_loc4='想要看看我的商品吗?';
