INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4) VALUES (3421,'回程','我现在会把你送回萨纳斯的营地里。$B$B不要理会他的坏脾气—除了主人之外，他对所有人都很粗鲁，迟早他要为此吃苦头的。$B') ON DUPLICATE KEY UPDATE Title_loc4='回程',OfferRewardText_loc4='我现在会把你送回萨纳斯的营地里。$B$B不要理会他的坏脾气—除了主人之外，他对所有人都很粗鲁，迟早他要为此吃苦头的。$B';
