INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8041,'穆贾巴之力','我们会再见面的，$C。','见到你身体健康真好，$N。这场显赫的战斗影响着这个星球上的所有生物。绝不能让哈卡离开祖尔格拉布，否则世界将会毁在他无尽的欲望中。$B$B把坠饰给我吧，我会强化它的力量。运用穆贾巴之力惩罚我们的敌人吧!') ON DUPLICATE KEY UPDATE Title_loc4='穆贾巴之力',OfferRewardText_loc4='我们会再见面的，$C。',RequestItemsText_loc4='见到你身体健康真好，$N。这场显赫的战斗影响着这个星球上的所有生物。绝不能让哈卡离开祖尔格拉布，否则世界将会毁在他无尽的欲望中。$B$B把坠饰给我吧，我会强化它的力量。运用穆贾巴之力惩罚我们的敌人吧!';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8042,'穆贾巴之力','我们会再见面的，$C。','见到你身体健康真好，$N。这场显赫的战斗影响着这个星球上的所有生物。绝不能让哈卡离开祖尔格拉布，否则世界将会毁在他无尽的欲望中。$B$B把坠饰给我吧，我会强化它的力量。运用穆贾巴之力惩罚我们的敌人吧!') ON DUPLICATE KEY UPDATE Title_loc4='穆贾巴之力',OfferRewardText_loc4='我们会再见面的，$C。',RequestItemsText_loc4='见到你身体健康真好，$N。这场显赫的战斗影响着这个星球上的所有生物。绝不能让哈卡离开祖尔格拉布，否则世界将会毁在他无尽的欲望中。$B$B把坠饰给我吧，我会强化它的力量。运用穆贾巴之力惩罚我们的敌人吧!';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8043,'穆贾巴之力','我们会再见面的，$C。','见到你身体健康真好，$N。这场显赫的战斗影响着这个星球上的所有生物。绝不能让哈卡离开祖尔格拉布，否则世界将会毁在他无尽的欲望中。$B$B把坠饰给我吧，我会强化它的力量。运用穆贾巴之力惩罚我们的敌人吧!') ON DUPLICATE KEY UPDATE Title_loc4='穆贾巴之力',OfferRewardText_loc4='我们会再见面的，$C。',RequestItemsText_loc4='见到你身体健康真好，$N。这场显赫的战斗影响着这个星球上的所有生物。绝不能让哈卡离开祖尔格拉布，否则世界将会毁在他无尽的欲望中。$B$B把坠饰给我吧，我会强化它的力量。运用穆贾巴之力惩罚我们的敌人吧!';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8044,'穆贾巴的怒火','祖尔金都会羡慕的，战士。去吧，征服你的敌人!','拉斯塔哈向你致敬，$N。这样的荣誉对非赞达拉部族的成员来说还是头一次。$B$B<金罗克向你鞠躬。>$B$B把坠饰给我吧，我会再次强化它的力量。穆贾巴的怒火已经与你的灵魂连在了一起。') ON DUPLICATE KEY UPDATE Title_loc4='穆贾巴的怒火',OfferRewardText_loc4='祖尔金都会羡慕的，战士。去吧，征服你的敌人!',RequestItemsText_loc4='拉斯塔哈向你致敬，$N。这样的荣誉对非赞达拉部族的成员来说还是头一次。$B$B<金罗克向你鞠躬。>$B$B把坠饰给我吧，我会再次强化它的力量。穆贾巴的怒火已经与你的灵魂连在了一起。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8045,'异教徒的烙印','去吧，你必须打败我们的敌人，$C。即使这意味着要借助圣光的力量。$B$B<金罗克浑身战栗。>','我的判断看来有些草率，$C。似乎你对圣光的盲目信仰还有些用处。$B$B把烙印给我吧，我会强化它的力量。') ON DUPLICATE KEY UPDATE Title_loc4='异教徒的烙印',OfferRewardText_loc4='去吧，你必须打败我们的敌人，$C。即使这意味着要借助圣光的力量。$B$B<金罗克浑身战栗。>',RequestItemsText_loc4='我的判断看来有些草率，$C。似乎你对圣光的盲目信仰还有些用处。$B$B把烙印给我吧，我会强化它的力量。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8046,'异教徒的烙印','去吧，你必须打败我们的敌人，$C。即使这意味着要借助圣光的力量。$B$B<金罗克浑身战栗。>','我的判断看来有些草率，$C。似乎你对圣光的盲目信仰还有些用处。$B$B把烙印给我吧，我会强化它的力量。') ON DUPLICATE KEY UPDATE Title_loc4='异教徒的烙印',OfferRewardText_loc4='去吧，你必须打败我们的敌人，$C。即使这意味着要借助圣光的力量。$B$B<金罗克浑身战栗。>',RequestItemsText_loc4='我的判断看来有些草率，$C。似乎你对圣光的盲目信仰还有些用处。$B$B把烙印给我吧，我会强化它的力量。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8047,'异教徒的烙印','去吧，你必须打败我们的敌人，$C。即使这意味着要借助圣光的力量。$B$B<金罗克浑身战栗。>','我的判断看来有些草率，$C。似乎你对圣光的盲目信仰还有些用处。$B$B把烙印给我吧，我会强化它的力量。') ON DUPLICATE KEY UPDATE Title_loc4='异教徒的烙印',OfferRewardText_loc4='去吧，你必须打败我们的敌人，$C。即使这意味着要借助圣光的力量。$B$B<金罗克浑身战栗。>',RequestItemsText_loc4='我的判断看来有些草率，$C。似乎你对圣光的盲目信仰还有些用处。$B$B把烙印给我吧，我会强化它的力量。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8048,'英雄的烙印','警觉、荣誉、忠诚、勇敢……你拥有所有的优点，你的烙印也应如此。$B','你获得了国王的认可，$C。拉斯塔哈承认你是赞达拉真正的盟友，这在你的族人中还是头一次呢。$B$B你将收到丰厚的奖励。把烙印给我吧，我会最后一次强化它。') ON DUPLICATE KEY UPDATE Title_loc4='英雄的烙印',OfferRewardText_loc4='警觉、荣誉、忠诚、勇敢……你拥有所有的优点，你的烙印也应如此。$B',RequestItemsText_loc4='你获得了国王的认可，$C。拉斯塔哈承认你是赞达拉真正的盟友，这在你的族人中还是头一次呢。$B$B你将收到丰厚的奖励。把烙印给我吧，我会最后一次强化它。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8049,'祖达萨之眼','$N，你要坚持不懈地奋力战斗。夺魂者会试图汲取你求生的意志。$B','牧师，你与古拉巴什一族作战的英勇事蹟早已家喻户晓，就连皇室成员也开始谈论你的故事。据说拉斯塔哈甚至提到了你的名字。$B$B现在是为祖达萨之眼注入魔法的时候了。把坠饰交给我吧。') ON DUPLICATE KEY UPDATE Title_loc4='祖达萨之眼',OfferRewardText_loc4='$N，你要坚持不懈地奋力战斗。夺魂者会试图汲取你求生的意志。$B',RequestItemsText_loc4='牧师，你与古拉巴什一族作战的英勇事蹟早已家喻户晓，就连皇室成员也开始谈论你的故事。据说拉斯塔哈甚至提到了你的名字。$B$B现在是为祖达萨之眼注入魔法的时候了。把坠饰交给我吧。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8050,'祖达萨之眼','$N，你要坚持不懈地奋力战斗。夺魂者会试图汲取你求生的意志。$B','牧师，你与古拉巴什一族作战的英勇事蹟早已家喻户晓，就连皇室成员也开始谈论你的故事。据说拉斯塔哈甚至提到了你的名字。$B$B现在是为祖达萨之眼注入魔法的时候了。把坠饰交给我吧。') ON DUPLICATE KEY UPDATE Title_loc4='祖达萨之眼',OfferRewardText_loc4='$N，你要坚持不懈地奋力战斗。夺魂者会试图汲取你求生的意志。$B',RequestItemsText_loc4='牧师，你与古拉巴什一族作战的英勇事蹟早已家喻户晓，就连皇室成员也开始谈论你的故事。据说拉斯塔哈甚至提到了你的名字。$B$B现在是为祖达萨之眼注入魔法的时候了。把坠饰交给我吧。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8051,'祖达萨之眼','$N，你要坚持不懈地奋力战斗。夺魂者会试图汲取你求生的意志。$B','牧师，你与古拉巴什一族作战的英勇事蹟早已家喻户晓，就连皇室成员也开始谈论你的故事。据说拉斯塔哈甚至提到了你的名字。$B$B现在是为祖达萨之眼注入魔法的时候了。把坠饰交给我吧。') ON DUPLICATE KEY UPDATE Title_loc4='祖达萨之眼',OfferRewardText_loc4='$N，你要坚持不懈地奋力战斗。夺魂者会试图汲取你求生的意志。$B',RequestItemsText_loc4='牧师，你与古拉巴什一族作战的英勇事蹟早已家喻户晓，就连皇室成员也开始谈论你的故事。据说拉斯塔哈甚至提到了你的名字。$B$B现在是为祖达萨之眼注入魔法的时候了。把坠饰交给我吧。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8052,'祖达萨全视之眼','给他们迎头痛击，让哈卡尝尝失败的滋味……','$N，如果我们有上万名像你这样的人物，哈卡的军队将在瞬间灰飞烟灭。$B$B<阿塔比姆发出了一声叹息。>$B$B唉，祖达萨之眼就要发挥它所有的潜能了。把它给我。') ON DUPLICATE KEY UPDATE Title_loc4='祖达萨全视之眼',OfferRewardText_loc4='给他们迎头痛击，让哈卡尝尝失败的滋味……',RequestItemsText_loc4='$N，如果我们有上万名像你这样的人物，哈卡的军队将在瞬间灰飞烟灭。$B$B<阿塔比姆发出了一声叹息。>$B$B唉，祖达萨之眼就要发挥它所有的潜能了。把它给我。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8053,'权力珍宝：思考者护臂','你是一名异教徒。异教徒在部族中也占有一席之地，他们是赞达拉的思考者。思考者面对压迫，毫不畏惧；他们愿意为自己的信仰而死。我们知道，你也愿意为自己的信仰而死。我会给你一个证明自己实力的机会。$B$B我们必须拿到足够的权力珍宝。去祖尔格拉布吧，去杀死哈卡的爪牙。当你找到权力珍宝后再回到我这儿来。我会奖给你一件赞达拉思考者的战斗装备。$B$B去吧。','从祖尔格拉布把以下权力珍宝带给击碎者金罗克：1条原始哈卡莱护腕。你还必须在赞达拉部族中达到友善或更高的声望。$B$B击碎者金罗克在荆棘谷的尤亚姆巴岛上。','你令我们感到荣耀。你的双手沾满了哈卡爪牙的鲜血。你是部族的朋友。$B$B戴着这些护臂。它们是思考者护臂。这是我所谓真正的力量。$B','你回来了?你带回权力珍宝了吗?你在浪费我时间吗?$B$B我希望不是，异教徒。') ON DUPLICATE KEY UPDATE Title_loc4='权力珍宝：思考者护臂',Details_loc4='你是一名异教徒。异教徒在部族中也占有一席之地，他们是赞达拉的思考者。思考者面对压迫，毫不畏惧；他们愿意为自己的信仰而死。我们知道，你也愿意为自己的信仰而死。我会给你一个证明自己实力的机会。$B$B我们必须拿到足够的权力珍宝。去祖尔格拉布吧，去杀死哈卡的爪牙。当你找到权力珍宝后再回到我这儿来。我会奖给你一件赞达拉思考者的战斗装备。$B$B去吧。',Objectives_loc4='从祖尔格拉布把以下权力珍宝带给击碎者金罗克：1条原始哈卡莱护腕。你还必须在赞达拉部族中达到友善或更高的声望。$B$B击碎者金罗克在荆棘谷的尤亚姆巴岛上。',OfferRewardText_loc4='你令我们感到荣耀。你的双手沾满了哈卡爪牙的鲜血。你是部族的朋友。$B$B戴着这些护臂。它们是思考者护臂。这是我所谓真正的力量。$B',RequestItemsText_loc4='你回来了?你带回权力珍宝了吗?你在浪费我时间吗?$B$B我希望不是，异教徒。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8054,'权力珍宝：思考者腰带','你的信仰与我们大不相同，异教徒。古时的赞达拉部族被称为异教徒。那时古拉巴什帝国还很强大，异教徒冒险挑战哈卡的牧师，但是被杀死了。这些异教徒打败哈卡的信念从未动摇，因此我们对他们表示尊敬。他们是思考者。$B$B杀死祖尔格拉布里面的哈卡的爪牙，找回我需要的权力珍宝。如果你成功的话，就可以得到丰厚的奖励。$B$B去吧。','从祖尔格拉布把以下权力珍宝带给击碎者金罗克：1条原始哈卡莱披肩。你还必须在赞达拉部族中达到尊敬或更高的声望。$B$B击碎者金罗克在荆棘谷的尤亚姆巴岛上。','你将获得部族的尊敬。你血洗了祖尔格拉布。敌人在你的信念前倒下。敌人因你的力量而死。$B$B这是思考者腰带。它是荣誉的象征。它是强大的魔精。现在它属于你了。','你获胜了?你取回权力珍宝了吗?你杀死敌人了吗?') ON DUPLICATE KEY UPDATE Title_loc4='权力珍宝：思考者腰带',Details_loc4='你的信仰与我们大不相同，异教徒。古时的赞达拉部族被称为异教徒。那时古拉巴什帝国还很强大，异教徒冒险挑战哈卡的牧师，但是被杀死了。这些异教徒打败哈卡的信念从未动摇，因此我们对他们表示尊敬。他们是思考者。$B$B杀死祖尔格拉布里面的哈卡的爪牙，找回我需要的权力珍宝。如果你成功的话，就可以得到丰厚的奖励。$B$B去吧。',Objectives_loc4='从祖尔格拉布把以下权力珍宝带给击碎者金罗克：1条原始哈卡莱披肩。你还必须在赞达拉部族中达到尊敬或更高的声望。$B$B击碎者金罗克在荆棘谷的尤亚姆巴岛上。',OfferRewardText_loc4='你将获得部族的尊敬。你血洗了祖尔格拉布。敌人在你的信念前倒下。敌人因你的力量而死。$B$B这是思考者腰带。它是荣誉的象征。它是强大的魔精。现在它属于你了。',RequestItemsText_loc4='你获胜了?你取回权力珍宝了吗?你杀死敌人了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8055,'权力珍宝：思考者胸甲','战争赋予你强大的力量。思考者得到的就是这样的力量，他们都是狂热的家伙，他们在胸甲中浸入魔精——这样，就算他们在面对敌人时动摇了自己的信仰，他们的胸甲也不会有丝毫变化。$B$B你在赞达拉部族中的声望必须达到崇拜才能拥有这样一件胸甲。去祖尔格拉布吧，带回我需要的权力珍宝。给予那儿的蠢货们狠狠一击，取回权力珍宝。证明自己作为思考者的实力。','从祖尔格拉布把以下权力珍宝带给击碎者金罗克：1条原始哈卡莱徽章。你还必须在赞达拉部族中达到崇敬或更高的声望。$B$B击碎者金罗克在荆棘谷的尤亚姆巴岛上。','你做到了很多人永远也无法做到的事情。你打败了哈卡的爪牙，让他们见识到思考者的能力。异教徒在赞达拉部族中也能赢得崇拜。你拥有不可思议的力量，你就是力量的化身。$B$B思考者，拿走属於你的胸甲吧。粉碎那些反对你的家伙。$B','你拿到权力珍宝了吗?那里面有魔精，我们必须得到它。你必须帮助我们。') ON DUPLICATE KEY UPDATE Title_loc4='权力珍宝：思考者胸甲',Details_loc4='战争赋予你强大的力量。思考者得到的就是这样的力量，他们都是狂热的家伙，他们在胸甲中浸入魔精——这样，就算他们在面对敌人时动摇了自己的信仰，他们的胸甲也不会有丝毫变化。$B$B你在赞达拉部族中的声望必须达到崇拜才能拥有这样一件胸甲。去祖尔格拉布吧，带回我需要的权力珍宝。给予那儿的蠢货们狠狠一击，取回权力珍宝。证明自己作为思考者的实力。',Objectives_loc4='从祖尔格拉布把以下权力珍宝带给击碎者金罗克：1条原始哈卡莱徽章。你还必须在赞达拉部族中达到崇敬或更高的声望。$B$B击碎者金罗克在荆棘谷的尤亚姆巴岛上。',OfferRewardText_loc4='你做到了很多人永远也无法做到的事情。你打败了哈卡的爪牙，让他们见识到思考者的能力。异教徒在赞达拉部族中也能赢得崇拜。你拥有不可思议的力量，你就是力量的化身。$B$B思考者，拿走属於你的胸甲吧。粉碎那些反对你的家伙。$B',RequestItemsText_loc4='你拿到权力珍宝了吗?那里面有魔精，我们必须得到它。你必须帮助我们。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8056,'权力珍宝：预言者护腕','预言者以他们超凡的眼界在部族中倍受尊敬。他们不是巫医，他们是通过抛掷骨头或是辨识树叶来进行预言的。作为一名萨满祭司，你已经掌握了预言者的一些能力；赞达拉部族非常重视他们的预言。$B$B去祖尔格拉布，取回我需要的权力珍宝，证明自己的价值。如果你成功的话，我就会送你一副预言者护腕的！','从祖尔格拉布把以下权力珍宝交给祖达萨的梅维克：1条原始哈卡莱护臂。你还必须在赞达拉部族中达到友善或更高的声望。$B$B祖达萨的梅维克在荆棘谷的尤亚姆巴岛上。','看起来你有点赞达拉占兆师的模样了。我们知道你在祖尔格拉布为我们所做的一切。这些权力珍宝将帮助赞达拉部族─或许我应该说，你的朋友。收下这些护腕吧，$N，这是你应得的!$B','你有没有从祖尔格拉布取必我需要的权力珍宝?这些护腕值得你为之付出努力!') ON DUPLICATE KEY UPDATE Title_loc4='权力珍宝：预言者护腕',Details_loc4='预言者以他们超凡的眼界在部族中倍受尊敬。他们不是巫医，他们是通过抛掷骨头或是辨识树叶来进行预言的。作为一名萨满祭司，你已经掌握了预言者的一些能力；赞达拉部族非常重视他们的预言。$B$B去祖尔格拉布，取回我需要的权力珍宝，证明自己的价值。如果你成功的话，我就会送你一副预言者护腕的！',Objectives_loc4='从祖尔格拉布把以下权力珍宝交给祖达萨的梅维克：1条原始哈卡莱护臂。你还必须在赞达拉部族中达到友善或更高的声望。$B$B祖达萨的梅维克在荆棘谷的尤亚姆巴岛上。',OfferRewardText_loc4='看起来你有点赞达拉占兆师的模样了。我们知道你在祖尔格拉布为我们所做的一切。这些权力珍宝将帮助赞达拉部族─或许我应该说，你的朋友。收下这些护腕吧，$N，这是你应得的!$B',RequestItemsText_loc4='你有没有从祖尔格拉布取必我需要的权力珍宝?这些护腕值得你为之付出努力!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8057,'权力珍宝：占卜师护腕','占卜师是我们部族的重要成员，聆听他们的教诲是你明智的选择。通过和动物交流以及在必要的时候把它们献给魂灵，他们将会给我们提供神圣的指引。在过去的岁月中，占卜师的洞察力和智慧帮助我们在和古拉巴什的战争中渡过了难关。$B$B从祖尔格拉布帮我带回权力珍宝来，证明你的价值。只要你带回那些东西，我就会给你赞达拉占卜师梦寐以求的护腕。','从祖尔格拉布把以下权力珍宝带给祖达萨的梅维克：1条原始哈卡莱直柱。你还必须在赞达拉部族中达到友好或更高的声望。$B$B祖达萨的梅维克在荆棘谷的尤亚姆巴岛上。','啊，我能感觉到这些权力珍宝释放的能量，$N。你是我们部族的朋友。按照我们的承诺，$N……占卜师护腕属於你了!$B','你有没有从祖尔格拉布找到权力珍宝?这些护腕价值不菲呢，$N。相信我!') ON DUPLICATE KEY UPDATE Title_loc4='权力珍宝：占卜师护腕',Details_loc4='占卜师是我们部族的重要成员，聆听他们的教诲是你明智的选择。通过和动物交流以及在必要的时候把它们献给魂灵，他们将会给我们提供神圣的指引。在过去的岁月中，占卜师的洞察力和智慧帮助我们在和古拉巴什的战争中渡过了难关。$B$B从祖尔格拉布帮我带回权力珍宝来，证明你的价值。只要你带回那些东西，我就会给你赞达拉占卜师梦寐以求的护腕。',Objectives_loc4='从祖尔格拉布把以下权力珍宝带给祖达萨的梅维克：1条原始哈卡莱直柱。你还必须在赞达拉部族中达到友好或更高的声望。$B$B祖达萨的梅维克在荆棘谷的尤亚姆巴岛上。',OfferRewardText_loc4='啊，我能感觉到这些权力珍宝释放的能量，$N。你是我们部族的朋友。按照我们的承诺，$N……占卜师护腕属於你了!$B',RequestItemsText_loc4='你有没有从祖尔格拉布找到权力珍宝?这些护腕价值不菲呢，$N。相信我!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8058,'权力珍宝：辩护者护臂','复仇便是力量。赞达拉辩护者拥有这样的力量。我们的部族有很多敌人，辩护者要让他们付出代价。对抗我们的愚蠢之人必将受到惩罚，辩护者就是施加惩罚的执行人。敌人害怕复仇，他们永远都会害怕你。$B$B充当起辩护者的角色吧。去祖尔格拉布寻找权力珍宝。杀死哈卡的爪牙，以部族的名义复仇。你会得到奖励的。','从祖尔格拉布把以下权力珍宝带给击碎者金罗克：1条原始哈卡莱护臂。你还必须在赞达拉部族中达到友善或更高的声望。$B$B击碎者金罗克在荆棘谷的尤亚姆巴岛上。','你的复仇行动已经成功了，你也因此而具备了辩护者的资格。你打败了血神哈卡的爪牙。$B$B收下这个吧。它会在今后的复仇行动中帮助你。现在，你是赞达拉部族的朋友了。$B','你取必权力珍宝了吗?你以赞达拉的名义复仇了吗?') ON DUPLICATE KEY UPDATE Title_loc4='权力珍宝：辩护者护臂',Details_loc4='复仇便是力量。赞达拉辩护者拥有这样的力量。我们的部族有很多敌人，辩护者要让他们付出代价。对抗我们的愚蠢之人必将受到惩罚，辩护者就是施加惩罚的执行人。敌人害怕复仇，他们永远都会害怕你。$B$B充当起辩护者的角色吧。去祖尔格拉布寻找权力珍宝。杀死哈卡的爪牙，以部族的名义复仇。你会得到奖励的。',Objectives_loc4='从祖尔格拉布把以下权力珍宝带给击碎者金罗克：1条原始哈卡莱护臂。你还必须在赞达拉部族中达到友善或更高的声望。$B$B击碎者金罗克在荆棘谷的尤亚姆巴岛上。',OfferRewardText_loc4='你的复仇行动已经成功了，你也因此而具备了辩护者的资格。你打败了血神哈卡的爪牙。$B$B收下这个吧。它会在今后的复仇行动中帮助你。现在，你是赞达拉部族的朋友了。$B',RequestItemsText_loc4='你取必权力珍宝了吗?你以赞达拉的名义复仇了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8059,'权力珍宝：恶魔师裹带','术士在和恶魔打交道的过程中冒着极大的危险，但是我们的恶魔师的研究更近一步。通过一个古老的魔法仪式，他们让恶魔进入他们的躯壳。他们从身体内部奴役了恶魔，而不是让恶魔占据他们，这些野兽的力量将永远被他们控制。这种技能只有少数人可以掌握。$B$B为了让你了解恶魔的力量，我必须获得祖尔格拉布的权力珍宝。去那里带回我们所需的东西。','从祖尔格拉布把以下权力珍宝交给全知者阿塔比姆：1条原始哈卡莱直柱。你还必须在赞达拉部族中达到友善或更高的声望。$B$B全知者阿塔比姆在荆棘谷的尤亚姆巴岛上。','干得好……显然他们在交出权力珍宝之前痛苦地挣扎了一番。拿着这个─恶魔师裹带。这是用恶魔祈祷中使用的强大魔精制作而成的，它将在你追求力量的过程中成为有用的工具。$B','你有没有带回权力珍宝?如果你可以击败哈卡的恶魔仆从，那么你不仅向我们证明了自己的实力，而且还证明了你想要学习恶魔之道的意愿。') ON DUPLICATE KEY UPDATE Title_loc4='权力珍宝：恶魔师裹带',Details_loc4='术士在和恶魔打交道的过程中冒着极大的危险，但是我们的恶魔师的研究更近一步。通过一个古老的魔法仪式，他们让恶魔进入他们的躯壳。他们从身体内部奴役了恶魔，而不是让恶魔占据他们，这些野兽的力量将永远被他们控制。这种技能只有少数人可以掌握。$B$B为了让你了解恶魔的力量，我必须获得祖尔格拉布的权力珍宝。去那里带回我们所需的东西。',Objectives_loc4='从祖尔格拉布把以下权力珍宝交给全知者阿塔比姆：1条原始哈卡莱直柱。你还必须在赞达拉部族中达到友善或更高的声望。$B$B全知者阿塔比姆在荆棘谷的尤亚姆巴岛上。',OfferRewardText_loc4='干得好……显然他们在交出权力珍宝之前痛苦地挣扎了一番。拿着这个─恶魔师裹带。这是用恶魔祈祷中使用的强大魔精制作而成的，它将在你追求力量的过程中成为有用的工具。$B',RequestItemsText_loc4='你有没有带回权力珍宝?如果你可以击败哈卡的恶魔仆从，那么你不仅向我们证明了自己的实力，而且还证明了你想要学习恶魔之道的意愿。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8060,'权力珍宝：幻术师裹布','法师在我们的部族中被称为幻术师。他们在咒术中使用了强大的魔精，能迷惑部族的敌人！$B$B<阿塔比姆顽皮地笑起来。>$B$B看到这样一名强大的幻术师全力以赴，击败敌人，真令人兴奋！$B$B如果你要了解幻术师的话，就去祖尔格拉布找回我需要的权力珍宝吧。如果你成功了，我就会送你一件织入幻术师法术的装备。','从祖尔格拉布把以下权力珍宝带给全知者阿塔比姆：1条原始哈卡莱护腕。你还必须在赞达拉部族中达到友善或更高的声望。$B$B全知者阿塔比姆克在荆棘谷的尤亚姆巴岛上。','太令人惊讶了……你能感觉到魔精的力量在这些珍宝中涌动吗?在古拉巴什帝国统治一切的时代，权力珍宝被作为流通货币。现在，赞达拉将利用珍宝中隐藏的魔精对抗哈卡的第二次崛起!
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8061,'权力珍宝：忏悔者裹布','我们赞达拉部族将权力授予那些能和神灵直接沟通的成员。我们的祭司不仅仅是治疗者，也是忏悔者。邪恶不但来自外部的威胁——比如哈卡，也来自部族内部。我们的忏悔者在此担起了法官的职责，避免我们被那股吞噬了古拉巴什帝国的邪恶力量所毁灭。$B$B我需要的权力珍宝就在祖尔格拉布中，去找到那些珍宝，了解忏悔者的职责和精神，保护我们免受邪恶的侵蚀。','从祖尔格拉布把以下权力珍宝交给全知者阿塔比姆：1条原始哈卡莱直柱。你还必须在赞达拉部族中达到友善或更高的声望。$B$B全知者阿塔比姆在荆棘谷的尤亚姆巴岛上。','太好了，$N!你能把这些带给我可真不容易。无疑，你今天成为了我们部族的忏悔者，你帮助我们化解了哈卡的威胁!$B','你从祖尔格拉布回来了?你有没有成功地从哈卡的手下那里获得权力珍宝?') ON DUPLICATE KEY UPDATE Title_loc4='权力珍宝：忏悔者裹布',Details_loc4='我们赞达拉部族将权力授予那些能和神灵直接沟通的成员。我们的祭司不仅仅是治疗者，也是忏悔者。邪恶不但来自外部的威胁——比如哈卡，也来自部族内部。我们的忏悔者在此担起了法官的职责，避免我们被那股吞噬了古拉巴什帝国的邪恶力量所毁灭。$B$B我需要的权力珍宝就在祖尔格拉布中，去找到那些珍宝，了解忏悔者的职责和精神，保护我们免受邪恶的侵蚀。',Objectives_loc4='从祖尔格拉布把以下权力珍宝交给全知者阿塔比姆：1条原始哈卡莱直柱。你还必须在赞达拉部族中达到友善或更高的声望。$B$B全知者阿塔比姆在荆棘谷的尤亚姆巴岛上。',OfferRewardText_loc4='太好了，$N!你能把这些带给我可真不容易。无疑，你今天成为了我们部族的忏悔者，你帮助我们化解了哈卡的威胁!$B',RequestItemsText_loc4='你从祖尔格拉布回来了?你有没有成功地从哈卡的手下那里获得权力珍宝?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8062,'权力珍宝：捕猎者护腕','在古拉巴什帝国毁灭后的黑暗岁月里，赞达拉捕猎者凭借自己的能力维系着部族的生存。猎人跟我们部族的捕猎者很像——狩猎便是捕猎者的基本工作。你在祖尔格拉布的狩猎之旅将证明你有没有资格成为捕猎者中的一员。$B$B从祖尔格拉布取回权力珍宝吧，如果你成功了，那么你就会在成为捕猎者的生涯中迈出第一步。','从祖尔格拉布把以下权力珍宝带给盲眼法希尔克：1条原始哈卡莱护腕。你还必须在赞达拉部族中达到友善或更高的声望。$B$B盲眼法希尔克在荆棘谷的尤亚姆巴岛上。','嗯……我不用眼睛看也能感觉到权力珍宝的存在。你在祖尔格拉布取得的胜利令整个部族都很感动。我们不仅将你看作赞达拉的朋友，还认为你值得拥有捕猎者的护腕 - 一个强大的物品，是捕猎者的象徵。干得好，$N。$B','去祖尔格拉布，打败那些拥有权力珍宝的家伙，$N。他们是你的猎物，他们拥有我们需要的东西。') ON DUPLICATE KEY UPDATE Title_loc4='权力珍宝：捕猎者护腕',Details_loc4='在古拉巴什帝国毁灭后的黑暗岁月里，赞达拉捕猎者凭借自己的能力维系着部族的生存。猎人跟我们部族的捕猎者很像——狩猎便是捕猎者的基本工作。你在祖尔格拉布的狩猎之旅将证明你有没有资格成为捕猎者中的一员。$B$B从祖尔格拉布取回权力珍宝吧，如果你成功了，那么你就会在成为捕猎者的生涯中迈出第一步。',Objectives_loc4='从祖尔格拉布把以下权力珍宝带给盲眼法希尔克：1条原始哈卡莱护腕。你还必须在赞达拉部族中达到友善或更高的声望。$B$B盲眼法希尔克在荆棘谷的尤亚姆巴岛上。',OfferRewardText_loc4='嗯……我不用眼睛看也能感觉到权力珍宝的存在。你在祖尔格拉布取得的胜利令整个部族都很感动。我们不仅将你看作赞达拉的朋友，还认为你值得拥有捕猎者的护腕 - 一个强大的物品，是捕猎者的象徵。干得好，$N。$B',RequestItemsText_loc4='去祖尔格拉布，打败那些拥有权力珍宝的家伙，$N。他们是你的猎物，他们拥有我们需要的东西。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8063,'权力珍宝：狂妄者护腕','赞达拉狂妄者和潜行者很像，但是他们信奉疯狂……混乱……无可预见的存在。狂妄者在战场上是个巨大的威胁，他们在敌人中散播混乱和伤害的种子。$B$B从祖尔格拉布带回我需要的权力珍宝，我就会送你一件狂妄者护甲。拥抱疯狂吧！','从祖尔格拉布把以下权力珍宝带给盲眼法希尔：1条原始哈卡莱护腕。你还必须在赞达拉部族中达到友善或更高的声望。$B$B盲眼法希尔在荆棘谷的尤亚姆巴岛上。','干得好，$N……你在祖尔格拉布取得了成功，赞达拉部族会从此将你视为朋友。现在我要实现对你的承诺，请收下这份奖励!$B','去祖尔格拉布寻找那些发狂的家伙，用你自己的力量征服他们，$N!丰厚的奖励在等待着你，不要让哈卡占了上风!') ON DUPLICATE KEY UPDATE Title_loc4='权力珍宝：狂妄者护腕',Details_loc4='赞达拉狂妄者和潜行者很像，但是他们信奉疯狂……混乱……无可预见的存在。狂妄者在战场上是个巨大的威胁，他们在敌人中散播混乱和伤害的种子。$B$B从祖尔格拉布带回我需要的权力珍宝，我就会送你一件狂妄者护甲。拥抱疯狂吧！',Objectives_loc4='从祖尔格拉布把以下权力珍宝带给盲眼法希尔：1条原始哈卡莱护腕。你还必须在赞达拉部族中达到友善或更高的声望。$B$B盲眼法希尔在荆棘谷的尤亚姆巴岛上。',OfferRewardText_loc4='干得好，$N……你在祖尔格拉布取得了成功，赞达拉部族会从此将你视为朋友。现在我要实现对你的承诺，请收下这份奖励!$B',RequestItemsText_loc4='去祖尔格拉布寻找那些发狂的家伙，用你自己的力量征服他们，$N!丰厚的奖励在等待着你，不要让哈卡占了上风!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8064,'权力珍宝：占卜师腰带','赞达拉部族不了解德鲁伊的行事之道。我们按照自己的需求塑造自然，而不是通过别的方式达到目标。当然，占卜师是我们当中与自然的关系最为和谐的。放弃一头小动物的灵魂是成为占卜师的重要步骤之一，那就是自然的真正力量。$B$B从祖尔格拉布帮我带回权力珍宝，向我们证明你的价值。只要你带回那些东西，我就会给你赞达拉占卜师使用的强大物品，一条腰带。$B$B非常强大！','从祖尔格拉布把以下权力珍宝带给祖达萨的梅维克：1条原始哈卡莱腰带。你还必须在赞达拉部族中达到尊敬或更高的声望。$B$B祖达萨的梅维克在荆棘谷的尤亚姆巴岛上。','你成功地收集到了所需要的权力珍宝，$N;为此我们对你表示感谢。你向我们证明了你是值得赞达拉部族尊敬的$r。按照我们所承诺的，现在它是你的了!$B','从祖尔格拉布带回我需要的权力珍宝了吗?只要你带来那些东西占卜师腰带就是你的了。') ON DUPLICATE KEY UPDATE Title_loc4='权力珍宝：占卜师腰带',Details_loc4='赞达拉部族不了解德鲁伊的行事之道。我们按照自己的需求塑造自然，而不是通过别的方式达到目标。当然，占卜师是我们当中与自然的关系最为和谐的。放弃一头小动物的灵魂是成为占卜师的重要步骤之一，那就是自然的真正力量。$B$B从祖尔格拉布帮我带回权力珍宝，向我们证明你的价值。只要你带回那些东西，我就会给你赞达拉占卜师使用的强大物品，一条腰带。$B$B非常强大！',Objectives_loc4='从祖尔格拉布把以下权力珍宝带给祖达萨的梅维克：1条原始哈卡莱腰带。你还必须在赞达拉部族中达到尊敬或更高的声望。$B$B祖达萨的梅维克在荆棘谷的尤亚姆巴岛上。',OfferRewardText_loc4='你成功地收集到了所需要的权力珍宝，$N;为此我们对你表示感谢。你向我们证明了你是值得赞达拉部族尊敬的$r。按照我们所承诺的，现在它是你的了!$B',RequestItemsText_loc4='从祖尔格拉布带回我需要的权力珍宝了吗?只要你带来那些东西占卜师腰带就是你的了。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8065,'权力珍宝：占卜师外套','衣着是占卜师力量的标志，$N。占卜师的外套象征了他们自己和他们所寻找的神圣智慧之间的联系。通常，外套中织入了用作祭品的小动物的部分肢体，这可以让他们时刻记着自己是如何获得强大的力量的。$B$B从祖尔格拉布帮我带回权力珍宝来，向我们证明你的价值。只要你带回那些东西，我就会给你一件包含占卜师真正力量的外套。','从祖尔格拉布把以下权力珍宝带给祖达萨的梅维克：1条原始哈卡莱徽章。你还必须在赞达拉部族中达到崇敬或更高的声望。$B$B祖达萨的梅维克在荆棘谷的尤亚姆巴岛上。','你成功地收集到了我需要的权力珍宝，$N……这真让我惊讶。你代表赞达拉部族在祖尔格拉布所施行的正义已经成为了传说。从此，你将为整个部族所崇敬。这是你的外套，强大的德鲁伊!$B','从祖尔格拉布带回我需要的权力珍宝了吗?占卜师外套绝对值得你付出那些努力。') ON DUPLICATE KEY UPDATE Title_loc4='权力珍宝：占卜师外套',Details_loc4='衣着是占卜师力量的标志，$N。占卜师的外套象征了他们自己和他们所寻找的神圣智慧之间的联系。通常，外套中织入了用作祭品的小动物的部分肢体，这可以让他们时刻记着自己是如何获得强大的力量的。$B$B从祖尔格拉布帮我带回权力珍宝来，向我们证明你的价值。只要你带回那些东西，我就会给你一件包含占卜师真正力量的外套。',Objectives_loc4='从祖尔格拉布把以下权力珍宝带给祖达萨的梅维克：1条原始哈卡莱徽章。你还必须在赞达拉部族中达到崇敬或更高的声望。$B$B祖达萨的梅维克在荆棘谷的尤亚姆巴岛上。',OfferRewardText_loc4='你成功地收集到了我需要的权力珍宝，$N……这真让我惊讶。你代表赞达拉部族在祖尔格拉布所施行的正义已经成为了传说。从此，你将为整个部族所崇敬。这是你的外套，强大的德鲁伊!$B',RequestItemsText_loc4='从祖尔格拉布带回我需要的权力珍宝了吗?占卜师外套绝对值得你付出那些努力。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8066,'权力珍宝：捕猎者腰带','捕猎者知道如何追踪猎物，而成功的捕猎者知道如何一击解决他的猎物。你必须掌握这两种技能才能在祖尔格拉布生存下来，才有可能具备赞达拉捕猎者的风采……$B$B从祖尔格拉布带回我需要的权力珍宝。我将抽取那些东西的力量，而你会得到赞达拉捕猎者腰带——这是笔好买卖，相信我。','从祖尔格拉布把以下权力珍宝带给盲眼法希尔：1条原始哈卡莱披肩。你还必须在赞达拉部族中达到尊敬或更高的声望。$B$B盲眼法希尔在荆棘谷的尤亚姆巴岛上。','我刚才感觉到了你的存在，$N，但是你的行踪还是让人很难察觉。是你身上的权力珍宝曝露了你的行踪。我不用看见这些小饰物也能感到它们释放的能量;它们蕴含的魔精 - 魔法的原力，如果你愿意 - 去制止血神哈卡残忍的阴谋。$B$B你会因为你的成功而被称赞 - 和奖励。你将因此受到部族的尊敬，并获得捕猎者的腰带。$B','攻击祖尔格拉布那些愚蠢的哈卡爪牙─他们身上有权力珍宝，$N。宣告自己的胜利，向部族证明你的实力。') ON DUPLICATE KEY UPDATE Title_loc4='权力珍宝：捕猎者腰带',Details_loc4='捕猎者知道如何追踪猎物，而成功的捕猎者知道如何一击解决他的猎物。你必须掌握这两种技能才能在祖尔格拉布生存下来，才有可能具备赞达拉捕猎者的风采……$B$B从祖尔格拉布带回我需要的权力珍宝。我将抽取那些东西的力量，而你会得到赞达拉捕猎者腰带——这是笔好买卖，相信我。',Objectives_loc4='从祖尔格拉布把以下权力珍宝带给盲眼法希尔：1条原始哈卡莱披肩。你还必须在赞达拉部族中达到尊敬或更高的声望。$B$B盲眼法希尔在荆棘谷的尤亚姆巴岛上。',OfferRewardText_loc4='我刚才感觉到了你的存在，$N，但是你的行踪还是让人很难察觉。是你身上的权力珍宝曝露了你的行踪。我不用看见这些小饰物也能感到它们释放的能量;它们蕴含的魔精 - 魔法的原力，如果你愿意 - 去制止血神哈卡残忍的阴谋。$B$B你会因为你的成功而被称赞 - 和奖励。你将因此受到部族的尊敬，并获得捕猎者的腰带。$B',RequestItemsText_loc4='攻击祖尔格拉布那些愚蠢的哈卡爪牙─他们身上有权力珍宝，$N。宣告自己的胜利，向部族证明你的实力。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8067,'权力珍宝：捕猎者衬肩','赞达拉部族将衣着视为成就的象征。你无需观察别人的衣着，只需感觉它所散发的力量——力量超越视觉。赞达拉捕猎者的衣服正是如此，他们最珍视的莫过于衬肩了。衬肩能使他们的身形变得模糊……并可以随心所欲地显形。$B$B去祖尔格拉布取回我需要的权力珍宝，捕猎者衬肩就属于你了。','从祖尔格拉布把以下权力珍宝带给盲眼法希尔：1块原始哈卡莱盾牌。你还必须在赞达拉部族中达到崇敬或更高的声望。$B$B盲眼法希尔在荆棘谷的尤亚姆巴岛上。','成功了……你将受到部族的崇拜，$N。找到披肩所需的权力珍宝并不容易，但是你以捕猎者的方式成功地做到了。你在这里赢得了一席之地，并且获得了穿上他们的披肩的权利。$B','你在祖尔格拉布取得胜利了吗，$N?你只有带回我需要的权力珍宝，证明你对部族的价值，才能赢得赞达拉捕猎者披肩。') ON DUPLICATE KEY UPDATE Title_loc4='权力珍宝：捕猎者衬肩',Details_loc4='赞达拉部族将衣着视为成就的象征。你无需观察别人的衣着，只需感觉它所散发的力量——力量超越视觉。赞达拉捕猎者的衣服正是如此，他们最珍视的莫过于衬肩了。衬肩能使他们的身形变得模糊……并可以随心所欲地显形。$B$B去祖尔格拉布取回我需要的权力珍宝，捕猎者衬肩就属于你了。',Objectives_loc4='从祖尔格拉布把以下权力珍宝带给盲眼法希尔：1块原始哈卡莱盾牌。你还必须在赞达拉部族中达到崇敬或更高的声望。$B$B盲眼法希尔在荆棘谷的尤亚姆巴岛上。',OfferRewardText_loc4='成功了……你将受到部族的崇拜，$N。找到披肩所需的权力珍宝并不容易，但是你以捕猎者的方式成功地做到了。你在这里赢得了一席之地，并且获得了穿上他们的披肩的权利。$B',RequestItemsText_loc4='你在祖尔格拉布取得胜利了吗，$N?你只有带回我需要的权力珍宝，证明你对部族的价值，才能赢得赞达拉捕猎者披肩。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8068,'权力珍宝：幻术师衬肩','魔法是供强者随心所欲运用的原始力量。魔精便是这种力量的外延，我们以幻术的形式来操纵这种魔法。谁希望自己打败的敌人并非真实的存在呢？赞达拉部族了解这种魔法，幻术师在部族中倍受尊敬。$B$B从祖尔格拉布带回我需要的权力珍宝吧——如果你成功的话，你就将受到部族的尊敬，并获得幻术师所使用的衬肩！','从祖尔格拉布把以下权力珍宝交给全知者阿塔比姆：1条原始哈卡莱披肩。你还必须在赞达拉部族中达到尊敬或更高的声望。$B$B全知者阿塔比姆克在荆棘谷的尤亚姆巴岛上。','成功了!你从今后将得到整个部族的尊敬!祖尔格拉布的家伙们一定尝到了赞达拉的厉害，谢谢你，$N。$B$B带着部族的祝福，请收下赞达拉幻术师的披肩。愿它助你一臂之力。$B','祖尔格拉布的情况如何?你利用幻术的力量打败敌人了吗?无论如何，他们都得死─从他们那儿取必的权力珍宝将会帮助我们打败哈卡。') ON DUPLICATE KEY UPDATE Title_loc4='权力珍宝：幻术师衬肩',Details_loc4='魔法是供强者随心所欲运用的原始力量。魔精便是这种力量的外延，我们以幻术的形式来操纵这种魔法。谁希望自己打败的敌人并非真实的存在呢？赞达拉部族了解这种魔法，幻术师在部族中倍受尊敬。$B$B从祖尔格拉布带回我需要的权力珍宝吧——如果你成功的话，你就将受到部族的尊敬，并获得幻术师所使用的衬肩！',Objectives_loc4='从祖尔格拉布把以下权力珍宝交给全知者阿塔比姆：1条原始哈卡莱披肩。你还必须在赞达拉部族中达到尊敬或更高的声望。$B$B全知者阿塔比姆克在荆棘谷的尤亚姆巴岛上。',OfferRewardText_loc4='成功了!你从今后将得到整个部族的尊敬!祖尔格拉布的家伙们一定尝到了赞达拉的厉害，谢谢你，$N。$B$B带着部族的祝福，请收下赞达拉幻术师的披肩。愿它助你一臂之力。$B',RequestItemsText_loc4='祖尔格拉布的情况如何?你利用幻术的力量打败敌人了吗?无论如何，他们都得死─从他们那儿取必的权力珍宝将会帮助我们打败哈卡。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8069,'权力珍宝：幻术师长袍','赞达拉部族通过衣着来识别着装者的身份和力量。我们的衣服都是用最好的材料织成的，其中还添加了魔精，这使得我们更加强大。幻术师也不例外，据说他们的长袍中含有自己的幻术精华。传说幻术师的长袍每时每刻都在变化。$B$B我会给你一件幻术师长袍，$N……但是你首先必须赢得部族的崇拜！从祖尔格拉布给我带回权力珍宝来！','从祖尔格拉布把以下权力珍宝交给全知者阿塔比姆：1块原始哈卡莱套索。你还必须在赞达拉部族中达到崇敬或更高的声望。$B$B全知者阿塔比姆在荆棘谷的尤亚姆巴岛上。','终于有人配得上这件幻术师长袍了!你在祖尔格拉布取得了巨大的成功，赞达拉部族的成员将永远崇拜你。骄傲地穿上它吧，$N!$B','你带回我们需要的权力珍宝了吗?我知道这并不容易……但是我早有预言，会有外来者帮助我们打败哈卡。你就是那个预言中的$r!') ON DUPLICATE KEY UPDATE Title_loc4='权力珍宝：幻术师长袍',Details_loc4='赞达拉部族通过衣着来识别着装者的身份和力量。我们的衣服都是用最好的材料织成的，其中还添加了魔精，这使得我们更加强大。幻术师也不例外，据说他们的长袍中含有自己的幻术精华。传说幻术师的长袍每时每刻都在变化。$B$B我会给你一件幻术师长袍，$N……但是你首先必须赢得部族的崇拜！从祖尔格拉布给我带回权力珍宝来！',Objectives_loc4='从祖尔格拉布把以下权力珍宝交给全知者阿塔比姆：1块原始哈卡莱套索。你还必须在赞达拉部族中达到崇敬或更高的声望。$B$B全知者阿塔比姆在荆棘谷的尤亚姆巴岛上。',OfferRewardText_loc4='终于有人配得上这件幻术师长袍了!你在祖尔格拉布取得了巨大的成功，赞达拉部族的成员将永远崇拜你。骄傲地穿上它吧，$N!$B',RequestItemsText_loc4='你带回我们需要的权力珍宝了吗?我知道这并不容易……但是我早有预言，会有外来者帮助我们打败哈卡。你就是那个预言中的$r!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8070,'权力珍宝：忏悔者腰带','在古拉巴什帝国陷落之后，我们赞达拉部族几乎被一股来自部族内部的邪恶力量所击败。这个时候有一些忏悔者挺身而出，将那些对自己同胞下手的败类驱逐了出去。他们不仅让我们精神得到升华，而且还让我们保存了性命。$B$B去祖尔格拉布，亲眼见证哈卡的倒下，也顺便拜访一下古拉巴什帝国吧。从他们那里夺得我们所需的权力珍宝，在成功之后，你就将获得奖励！','从祖尔格拉布把以下权力珍宝交给全知者阿塔比姆：1条原始哈卡莱腰带。你还必须在赞达拉部族中达到尊敬或更高的声望。$B$B全知者阿塔比姆在荆棘谷的尤亚姆巴岛上。','成功了!要对抗哈卡的复苏，我们还有很多事情要做。有了你的帮助，血神就无法将我们完全毁灭了。$B$B你今天赢得了部族的尊敬，$N。拿着这个 - 忏悔者束腕 - 这是我们对你的感谢。$B','权力珍宝……你拿到它们了吗?只有当我们拥有了它们之后，才能使用那些储存在里面的强大能量。如果我们能对血神的仆从发起反攻，就再好不过了……') ON DUPLICATE KEY UPDATE Title_loc4='权力珍宝：忏悔者腰带',Details_loc4='在古拉巴什帝国陷落之后，我们赞达拉部族几乎被一股来自部族内部的邪恶力量所击败。这个时候有一些忏悔者挺身而出，将那些对自己同胞下手的败类驱逐了出去。他们不仅让我们精神得到升华，而且还让我们保存了性命。$B$B去祖尔格拉布，亲眼见证哈卡的倒下，也顺便拜访一下古拉巴什帝国吧。从他们那里夺得我们所需的权力珍宝，在成功之后，你就将获得奖励！',Objectives_loc4='从祖尔格拉布把以下权力珍宝交给全知者阿塔比姆：1条原始哈卡莱腰带。你还必须在赞达拉部族中达到尊敬或更高的声望。$B$B全知者阿塔比姆在荆棘谷的尤亚姆巴岛上。',OfferRewardText_loc4='成功了!要对抗哈卡的复苏，我们还有很多事情要做。有了你的帮助，血神就无法将我们完全毁灭了。$B$B你今天赢得了部族的尊敬，$N。拿着这个 - 忏悔者束腕 - 这是我们对你的感谢。$B',RequestItemsText_loc4='权力珍宝……你拿到它们了吗?只有当我们拥有了它们之后，才能使用那些储存在里面的强大能量。如果我们能对血神的仆从发起反攻，就再好不过了……';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8071,'权力珍宝：忏悔者衬肩','赞达拉的忏悔者都穿着独特的护肩，这可以将他们标示为部族的保护者。这些护肩是用强大的魔精制作的，它会帮助那些为我们部族而战的勇士。作为一个牧师，你也需要这样一副护肩的庇护。$B$B进入祖尔格拉布，和哈卡的爪牙作战，然后把权力珍宝给我带回来，我会给你一副只有最优秀的忏悔者才能获得的护肩。','从祖尔格拉布把以下权力珍宝交给全知者阿塔比姆：1块原始哈卡莱之盾。你还必须在赞达拉部族中达到崇敬或更高的声望。$B$B全知者阿塔比姆在荆棘谷的尤亚姆巴岛上。','干得好，$N - 哈卡的爪牙一定感觉到了赞达拉的复仇，感谢你。你已经赢得了部族永远的崇敬。请接受我们的祝福，并收下这件忏悔者披肩!$B','你拿到祖尔格拉布的权力珍宝了吗?') ON DUPLICATE KEY UPDATE Title_loc4='权力珍宝：忏悔者衬肩',Details_loc4='赞达拉的忏悔者都穿着独特的护肩，这可以将他们标示为部族的保护者。这些护肩是用强大的魔精制作的，它会帮助那些为我们部族而战的勇士。作为一个牧师，你也需要这样一副护肩的庇护。$B$B进入祖尔格拉布，和哈卡的爪牙作战，然后把权力珍宝给我带回来，我会给你一副只有最优秀的忏悔者才能获得的护肩。',Objectives_loc4='从祖尔格拉布把以下权力珍宝交给全知者阿塔比姆：1块原始哈卡莱之盾。你还必须在赞达拉部族中达到崇敬或更高的声望。$B$B全知者阿塔比姆在荆棘谷的尤亚姆巴岛上。',OfferRewardText_loc4='干得好，$N - 哈卡的爪牙一定感觉到了赞达拉的复仇，感谢你。你已经赢得了部族永远的崇敬。请接受我们的祝福，并收下这件忏悔者披肩!$B',RequestItemsText_loc4='你拿到祖尔格拉布的权力珍宝了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8072,'权力珍宝：狂妄者衬肩','卡瓦萨尔是一位声名远播的赞达拉狂妄者。相传他首次对敌作战时穿着一件织入了“疯狂之纹”的特殊衬肩。他以极快的速度挥舞着两把匕首，全身都处于衬肩和匕首的双重保护之下，滴水不漏。今天，狂妄者把衬肩看作自己在整个部族中的地位的标志。$B$B把权力珍宝交给我，我就把衬肩送给你，它会令敌人闻风丧胆。','从祖尔格拉布把以下权力珍宝带给盲眼法希尔：1条原始哈卡莱束带。你还必须在赞达拉部族中达到尊敬或更高的声望。$B$B盲眼法希尔在荆棘谷的尤亚姆巴岛上。','胜利属於我们，谢谢你令我们的敌人发狂!赞达拉部族向你致敬，没有什么比狂妄者的披肩更能表达我们的谢意了!$B','你回来了─你带来了我需要的权力珍宝了吗?$B$B卡瓦萨尔的传说告诉我们，无论敌人有多强大，他们都不是不可战胜的。混乱会使所有人屈服，这点是毫无疑问的……而混乱中那些最有序的因素也可能使所有人屈服。') ON DUPLICATE KEY UPDATE Title_loc4='权力珍宝：狂妄者衬肩',Details_loc4='卡瓦萨尔是一位声名远播的赞达拉狂妄者。相传他首次对敌作战时穿着一件织入了“疯狂之纹”的特殊衬肩。他以极快的速度挥舞着两把匕首，全身都处于衬肩和匕首的双重保护之下，滴水不漏。今天，狂妄者把衬肩看作自己在整个部族中的地位的标志。$B$B把权力珍宝交给我，我就把衬肩送给你，它会令敌人闻风丧胆。',Objectives_loc4='从祖尔格拉布把以下权力珍宝带给盲眼法希尔：1条原始哈卡莱束带。你还必须在赞达拉部族中达到尊敬或更高的声望。$B$B盲眼法希尔在荆棘谷的尤亚姆巴岛上。',OfferRewardText_loc4='胜利属於我们，谢谢你令我们的敌人发狂!赞达拉部族向你致敬，没有什么比狂妄者的披肩更能表达我们的谢意了!$B',RequestItemsText_loc4='你回来了─你带来了我需要的权力珍宝了吗?$B$B卡瓦萨尔的传说告诉我们，无论敌人有多强大，他们都不是不可战胜的。混乱会使所有人屈服，这点是毫无疑问的……而混乱中那些最有序的因素也可能使所有人屈服。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8073,'权力珍宝：狂妄者外套','我的眼睛很早以前就瞎了，但是我一点也不怀念它们。在我们这样的部族中，衣饰代表了着装者的地位和意图，而最强大的衣服所蕴涵的力量不是用肉眼就能看出来的。赞达拉狂妄者外套也不例外，它蕴藏着可任你操控的混乱和疯狂之力。$B$B我需要的权力珍宝就在祖尔格拉布中，去找到那些珍宝，我会奖励你一件传说中的外套……适合狂妄者的外套。','从祖尔格拉布把以下权力珍宝带给盲眼法希尔：1块原始哈卡莱之盾。你还必须在赞达拉部族中达到崇敬或更高的声望。$B$B盲眼法希尔在荆棘谷的尤亚姆巴岛上。','很出色……你做到了很多人无法做到的事情。你获得了部族永远的崇敬，$N。你获得了穿上狂妄者外套的权力 - 带着我们的祝福穿上它吧。$B','欢迎回到尤亚姆巴岛，$N……你成功地取必权力珍宝了吗?') ON DUPLICATE KEY UPDATE Title_loc4='权力珍宝：狂妄者外套',Details_loc4='我的眼睛很早以前就瞎了，但是我一点也不怀念它们。在我们这样的部族中，衣饰代表了着装者的地位和意图，而最强大的衣服所蕴涵的力量不是用肉眼就能看出来的。赞达拉狂妄者外套也不例外，它蕴藏着可任你操控的混乱和疯狂之力。$B$B我需要的权力珍宝就在祖尔格拉布中，去找到那些珍宝，我会奖励你一件传说中的外套……适合狂妄者的外套。',Objectives_loc4='从祖尔格拉布把以下权力珍宝带给盲眼法希尔：1块原始哈卡莱之盾。你还必须在赞达拉部族中达到崇敬或更高的声望。$B$B盲眼法希尔在荆棘谷的尤亚姆巴岛上。',OfferRewardText_loc4='很出色……你做到了很多人无法做到的事情。你获得了部族永远的崇敬，$N。你获得了穿上狂妄者外套的权力 - 带着我们的祝福穿上它吧。$B',RequestItemsText_loc4='欢迎回到尤亚姆巴岛，$N……你成功地取必权力珍宝了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8074,'权力珍宝：预言者腰带','预言者了解元素中蕴含的魔精，他们将其作为指引部族繁荣发展的工具。在古拉巴什帝国毁灭后的黑暗岁月里，他们将我们领回祖尔格拉布的山谷中。$B$B从祖尔格拉布把权力珍宝给我带回来，证明你的实力。如果你能做到的话，我会送你一条预言者使用的腰带——里面有强大的魔精！','从祖尔格拉布把以下权力珍宝带给祖达萨的梅维克：1条原始哈卡莱束带。你还必须在赞达拉部族中达到尊敬或更高的声望。$B$B祖达萨的梅维克在荆棘谷的尤亚姆巴岛上。','我能嗅到你身上散发出击败恶魔的味道，$N。这味道真甜美老兄……我想你很熟悉这味道。$B$B我知道你能取得权力珍宝不是件简单的事。你的壮举不仅让部族倍感荣耀，也让你在整个部族中赢得尊敬。给你—拿着占兆师的腰带并穿上它吧!$B','我需要的正是权力珍宝─在对祖尔格拉布的恶魔作战时，我们可以利用它的力量。你带来权力珍宝了吗?') ON DUPLICATE KEY UPDATE Title_loc4='权力珍宝：预言者腰带',Details_loc4='预言者了解元素中蕴含的魔精，他们将其作为指引部族繁荣发展的工具。在古拉巴什帝国毁灭后的黑暗岁月里，他们将我们领回祖尔格拉布的山谷中。$B$B从祖尔格拉布把权力珍宝给我带回来，证明你的实力。如果你能做到的话，我会送你一条预言者使用的腰带——里面有强大的魔精！',Objectives_loc4='从祖尔格拉布把以下权力珍宝带给祖达萨的梅维克：1条原始哈卡莱束带。你还必须在赞达拉部族中达到尊敬或更高的声望。$B$B祖达萨的梅维克在荆棘谷的尤亚姆巴岛上。',OfferRewardText_loc4='我能嗅到你身上散发出击败恶魔的味道，$N。这味道真甜美老兄……我想你很熟悉这味道。$B$B我知道你能取得权力珍宝不是件简单的事。你的壮举不仅让部族倍感荣耀，也让你在整个部族中赢得尊敬。给你—拿着占兆师的腰带并穿上它吧!$B',RequestItemsText_loc4='我需要的正是权力珍宝─在对祖尔格拉布的恶魔作战时，我们可以利用它的力量。你带来权力珍宝了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8075,'权力珍宝：预言者外套','赞达拉预言者都身着一件与众不同的外套。它是由最好的丝绸和布料织成的，其中还编入了坚韧的锁链。这不仅是神力的象征，也是权力的标志。跟那些用尽毕生精力与灵魂交谈的预言者唱反调绝不是明智之举……$B$B从祖尔格拉布找回我需要的权力珍宝，证明你的价值。如果你成功的话，我就送你一件预言者梦寐以求的外套！','从祖尔格拉布把以下权力珍宝带给祖达萨的梅维克：1条原始哈卡莱徽章。你还必须在赞达拉部族中达到崇敬或更高的声望。$B$B祖达萨的梅维克在荆棘谷的尤亚姆巴岛上。','我明白你历经千辛万苦才为我取必权力珍宝，$N。这不简单，老兄 - 打败一个像淤泥般盘踞在祖尔格拉布的恶魔 - 但毕竟你成功了，你获得了赞达拉部族几世代的崇敬!$B$B来 - 骄傲地穿上占兆师链衫吧!$B','权力珍宝是魔法的关键来源—占兆师链衫中也蕴藏了这样的魔法。把我需要的东西交给我，我就送你一件赞达拉占兆师梦寐以求的链衫。') ON DUPLICATE KEY UPDATE Title_loc4='权力珍宝：预言者外套',Details_loc4='赞达拉预言者都身着一件与众不同的外套。它是由最好的丝绸和布料织成的，其中还编入了坚韧的锁链。这不仅是神力的象征，也是权力的标志。跟那些用尽毕生精力与灵魂交谈的预言者唱反调绝不是明智之举……$B$B从祖尔格拉布找回我需要的权力珍宝，证明你的价值。如果你成功的话，我就送你一件预言者梦寐以求的外套！',Objectives_loc4='从祖尔格拉布把以下权力珍宝带给祖达萨的梅维克：1条原始哈卡莱徽章。你还必须在赞达拉部族中达到崇敬或更高的声望。$B$B祖达萨的梅维克在荆棘谷的尤亚姆巴岛上。',OfferRewardText_loc4='我明白你历经千辛万苦才为我取必权力珍宝，$N。这不简单，老兄 - 打败一个像淤泥般盘踞在祖尔格拉布的恶魔 - 但毕竟你成功了，你获得了赞达拉部族几世代的崇敬!$B$B来 - 骄傲地穿上占兆师链衫吧!$B',RequestItemsText_loc4='权力珍宝是魔法的关键来源—占兆师链衫中也蕴藏了这样的魔法。把我需要的东西交给我，我就送你一件赞达拉占兆师梦寐以求的链衫。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8076,'权力珍宝：恶魔师衬肩','恶魔师的目标是直接吸收所有的能量，而不是简单地占据它。我们的许多恶魔师都在和恶魔战斗的过程中失败了；我们的敌人——尤其是古拉巴什的敌人——在威胁着我们，因此在真正需要牺牲的时候，恶魔师的力量将会倾泻在敌人的头上。我们能否生存取决于能否摧毁那些想要毁灭我们的人；古拉巴什帝国的沦陷让我们学会了这些东西。$B$B去祖尔格拉布，拿回我们所需的权力珍宝。完成了这一任务之后，我们将会奖励你一件珍贵的东西。','从祖尔格拉布把以下权力珍宝交给全知者阿塔比姆：1条原始哈卡莱腰带。你还必须在赞达拉部族中达到尊敬或更高的声望。$B$B全知者阿塔比姆在荆棘谷的尤亚姆巴岛上。','干得好，$N。祖尔格拉布的权利珍宝是一种废弃的力量的纪念。古拉巴什帝国十分强大，但是他们被自己强大的力量反噬了。恶魔师知道他们正在进行类似的游戏，但是释放能量将是生存所必需。$B$B穿上这件披肩吧，成为赞达拉部族尊敬的盟友……它将为你做出很大的贡献。$B','你找到了祖尔格拉布中的权力珍宝?我们将从这些物品中抽取力量并为我们所用，如果你成功了，我们会给你应得的奖励……') ON DUPLICATE KEY UPDATE Title_loc4='权力珍宝：恶魔师衬肩',Details_loc4='恶魔师的目标是直接吸收所有的能量，而不是简单地占据它。我们的许多恶魔师都在和恶魔战斗的过程中失败了；我们的敌人——尤其是古拉巴什的敌人——在威胁着我们，因此在真正需要牺牲的时候，恶魔师的力量将会倾泻在敌人的头上。我们能否生存取决于能否摧毁那些想要毁灭我们的人；古拉巴什帝国的沦陷让我们学会了这些东西。$B$B去祖尔格拉布，拿回我们所需的权力珍宝。完成了这一任务之后，我们将会奖励你一件珍贵的东西。',Objectives_loc4='从祖尔格拉布把以下权力珍宝交给全知者阿塔比姆：1条原始哈卡莱腰带。你还必须在赞达拉部族中达到尊敬或更高的声望。$B$B全知者阿塔比姆在荆棘谷的尤亚姆巴岛上。',OfferRewardText_loc4='干得好，$N。祖尔格拉布的权利珍宝是一种废弃的力量的纪念。古拉巴什帝国十分强大，但是他们被自己强大的力量反噬了。恶魔师知道他们正在进行类似的游戏，但是释放能量将是生存所必需。$B$B穿上这件披肩吧，成为赞达拉部族尊敬的盟友……它将为你做出很大的贡献。$B',RequestItemsText_loc4='你找到了祖尔格拉布中的权力珍宝?我们将从这些物品中抽取力量并为我们所用，如果你成功了，我们会给你应得的奖励……';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8077,'权力珍宝：恶魔师长袍','力量的终极象征就是我们在战斗中穿着的服饰。恶魔师的长袍都是用优良的符文布和强大的魔精制作而成的。长袍的外表会让所有看到他的人感到恐惧……特别是那些恶魔师想要控制的恶魔。$B$B去祖尔格拉布找回我所需要的权力珍宝。这会非常困难……但是你的成功将会为你换来一件无以匹敌的长袍。','从祖尔格拉布把以下权力珍宝交给全知者阿塔比姆：1块原始哈卡莱套索。你还必须在赞达拉部族中达到崇敬或更高的声望。$B$B全知者阿塔比姆在荆棘谷的尤亚姆巴岛上。','太好了─你在祖尔格拉布的胜利向我们，不，是向整个世界作出了保证，哈卡绝对无法为所欲为。你最终将要直接面对血神……你在赞达拉部族中也将获得极高的声望。$B$B哦，这件简单的长袍也能帮你一些忙。$B$B<阿塔比姆意味深长地对你眨了眨眼睛。>$B','权力珍宝……你有没有找到它们?只有我们得到这些东西，你才能获得恶魔力量的终极象徵，$N。') ON DUPLICATE KEY UPDATE Title_loc4='权力珍宝：恶魔师长袍',Details_loc4='力量的终极象征就是我们在战斗中穿着的服饰。恶魔师的长袍都是用优良的符文布和强大的魔精制作而成的。长袍的外表会让所有看到他的人感到恐惧……特别是那些恶魔师想要控制的恶魔。$B$B去祖尔格拉布找回我所需要的权力珍宝。这会非常困难……但是你的成功将会为你换来一件无以匹敌的长袍。',Objectives_loc4='从祖尔格拉布把以下权力珍宝交给全知者阿塔比姆：1块原始哈卡莱套索。你还必须在赞达拉部族中达到崇敬或更高的声望。$B$B全知者阿塔比姆在荆棘谷的尤亚姆巴岛上。',OfferRewardText_loc4='太好了─你在祖尔格拉布的胜利向我们，不，是向整个世界作出了保证，哈卡绝对无法为所欲为。你最终将要直接面对血神……你在赞达拉部族中也将获得极高的声望。$B$B哦，这件简单的长袍也能帮你一些忙。$B$B<阿塔比姆意味深长地对你眨了眨眼睛。>$B',RequestItemsText_loc4='权力珍宝……你有没有找到它们?只有我们得到这些东西，你才能获得恶魔力量的终极象徵，$N。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8078,'权力珍宝：辩护者腰带','祖尔格拉布将再次沐浴在仇恨的洗礼中。哈卡，这个摧毁了古拉巴什帝国的恶魔必须被消灭，无论我们付出多大代价也都在所不惜。现在的巨魔只不过是光芒消退后残存的阴影而已，这都是哈卡造成的！$B$B成为一名辩护者吧，去消灭恶魔的爪牙。祖尔格拉布将要尝到来自赞达拉的复仇。把权力珍宝交给我，我会给你一条辩护者腰带，让你拥有真实的力量。$B$B去吧。','从祖尔格拉布把以下权力珍宝带给击碎者金罗克：1条原始哈卡莱束带。你还必须在赞达拉部族中达到尊敬或更高的声望。$B$B击碎者金罗克在荆棘谷的尤亚姆巴岛上。','你已经了解了辩护者之道。你令部族倍感荣耀。你为自己赢得了尊敬。你让敌人尝到了痛苦的滋味。$B$B辩护者腰带属於你了。你已经具备了成为辩护者的资格。$B','你带回权力珍宝了吗?你打败部族的敌人了吗?必须让哈卡尝到辩护者的愤怒!') ON DUPLICATE KEY UPDATE Title_loc4='权力珍宝：辩护者腰带',Details_loc4='祖尔格拉布将再次沐浴在仇恨的洗礼中。哈卡，这个摧毁了古拉巴什帝国的恶魔必须被消灭，无论我们付出多大代价也都在所不惜。现在的巨魔只不过是光芒消退后残存的阴影而已，这都是哈卡造成的！$B$B成为一名辩护者吧，去消灭恶魔的爪牙。祖尔格拉布将要尝到来自赞达拉的复仇。把权力珍宝交给我，我会给你一条辩护者腰带，让你拥有真实的力量。$B$B去吧。',Objectives_loc4='从祖尔格拉布把以下权力珍宝带给击碎者金罗克：1条原始哈卡莱束带。你还必须在赞达拉部族中达到尊敬或更高的声望。$B$B击碎者金罗克在荆棘谷的尤亚姆巴岛上。',OfferRewardText_loc4='你已经了解了辩护者之道。你令部族倍感荣耀。你为自己赢得了尊敬。你让敌人尝到了痛苦的滋味。$B$B辩护者腰带属於你了。你已经具备了成为辩护者的资格。$B',RequestItemsText_loc4='你带回权力珍宝了吗?你打败部族的敌人了吗?必须让哈卡尝到辩护者的愤怒!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8079,'权力珍宝：辩护者胸甲','胸甲是辩护者力量的象征。它是由魔精制成的。只有那些受到部族崇敬的勇士才能拥有它，这是赞达拉复仇的象征。$B$B要成为辩护者，就必须复仇。从祖尔格拉布取回我们需要的权力珍宝，夺回被盗的魔精。哈卡的爪牙将为此付出代价，而你将因此获得辩护者胸甲。$B$B去吧。成为我们的复仇之神，$N。','从祖尔格拉布把以下权力珍宝带给击碎者金罗克：1条原始哈卡莱套索。你还必须在赞达拉部族中达到崇敬或更高的声望。$B$B击碎者金罗克在荆棘谷的尤亚姆巴岛上。','你将因此受到部族的崇敬。部族也会奖励它的英雄。祖尔格拉布已经尝到了来自赞达拉前所未有的复仇。$B$B你的英勇事蹟将鼓舞后来的勇士，他们会将你视为力量的象徵。他们会视你为复仇之神!$B','你获胜了吗?你取必权力珍宝了吗?告诉我你的复仇经历!') ON DUPLICATE KEY UPDATE Title_loc4='权力珍宝：辩护者胸甲',Details_loc4='胸甲是辩护者力量的象征。它是由魔精制成的。只有那些受到部族崇敬的勇士才能拥有它，这是赞达拉复仇的象征。$B$B要成为辩护者，就必须复仇。从祖尔格拉布取回我们需要的权力珍宝，夺回被盗的魔精。哈卡的爪牙将为此付出代价，而你将因此获得辩护者胸甲。$B$B去吧。成为我们的复仇之神，$N。',Objectives_loc4='从祖尔格拉布把以下权力珍宝带给击碎者金罗克：1条原始哈卡莱套索。你还必须在赞达拉部族中达到崇敬或更高的声望。$B$B击碎者金罗克在荆棘谷的尤亚姆巴岛上。',OfferRewardText_loc4='你将因此受到部族的崇敬。部族也会奖励它的英雄。祖尔格拉布已经尝到了来自赞达拉前所未有的复仇。$B$B你的英勇事蹟将鼓舞后来的勇士，他们会将你视为力量的象徵。他们会视你为复仇之神!$B',RequestItemsText_loc4='你获胜了吗?你取必权力珍宝了吗?告诉我你的复仇经历!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8080,'阿拉希盆地的资源!','我们必须依靠我们的士兵进行战斗，所有的士兵都会这么告诉你的。他们还会告诉你，他们正在使用破烂不堪的装备，饥肠辘辘地开向战场！$B$B这就是阿拉希盆地显得非常重要的原因。金属，武器，食物，木材——所有我们所需要的东西都可以从那里获得。$B$B那就是我需要你发挥作用的地方，$N。进入阿拉希盆地，比敌人占据更多的基地，以此来获得战斗的胜利，然后给我带回一箱资源来。','获得阿拉希盆地战斗的胜利，获取一只阿拉希资源箱，然后向避难谷地的玛克里尔中士复命。','你拿到资源了!干得好!我会把这些资源送到我们的军需官那里，然后让他迅速把它们分配给我们的军队。$B$B谢谢你，$N。事实上，不断地完成这样的任务将是获得最终胜利的关键要素。','你拿到资源木箱了吗，$N?如果没有足够的资源，阿拉索联军的士兵可没有办法好好干一仗……') ON DUPLICATE KEY UPDATE Title_loc4='阿拉希盆地的资源!',Details_loc4='我们必须依靠我们的士兵进行战斗，所有的士兵都会这么告诉你的。他们还会告诉你，他们正在使用破烂不堪的装备，饥肠辘辘地开向战场！$B$B这就是阿拉希盆地显得非常重要的原因。金属，武器，食物，木材——所有我们所需要的东西都可以从那里获得。$B$B那就是我需要你发挥作用的地方，$N。进入阿拉希盆地，比敌人占据更多的基地，以此来获得战斗的胜利，然后给我带回一箱资源来。',Objectives_loc4='获得阿拉希盆地战斗的胜利，获取一只阿拉希资源箱，然后向避难谷地的玛克里尔中士复命。',OfferRewardText_loc4='你拿到资源了!干得好!我会把这些资源送到我们的军需官那里，然后让他迅速把它们分配给我们的军队。$B$B谢谢你，$N。事实上，不断地完成这样的任务将是获得最终胜利的关键要素。',RequestItemsText_loc4='你拿到资源木箱了吗，$N?如果没有足够的资源，阿拉索联军的士兵可没有办法好好干一仗……';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8081,'更多的资源','啊，你抢到了更多的资源木箱!没有资源补给的联盟肯定会一败涂地的!$B$B感谢你，$N。你的努力已经为我们所知，并且也为瓦里玛萨斯所知。','虽然在破坏阿拉索联军的补给线方面，污染者做得已经很不错了，但是联盟还在继续对阿拉希盆地进行攻击。我们必须向盆地增派部队，并夺回更多的资源。') ON DUPLICATE KEY UPDATE Title_loc4='更多的资源',OfferRewardText_loc4='啊，你抢到了更多的资源木箱!没有资源补给的联盟肯定会一败涂地的!$B$B感谢你，$N。你的努力已经为我们所知，并且也为瓦里玛萨斯所知。',RequestItemsText_loc4='虽然在破坏阿拉索联军的补给线方面，污染者做得已经很不错了，但是联盟还在继续对阿拉希盆地进行攻击。我们必须向盆地增派部队，并夺回更多的资源。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8101,'卡亚罗之石','$C，这块坠饰上镶嵌的卡亚罗之石来自南海的卡亚罗山脉。卡亚罗山脉地带分布着许多活火山，那里的地质地形不断发生剧烈的变动。$B$B随着你与赞达拉巨魔的关系日益密切，卡亚罗之石的力量也会增强。利用这块石头的力量打败我们的敌人吧。就像卡亚罗山脉那样:迅速、致命、富有爆炸力……','好消息，$N。莫托尔最近对你赞不绝口，他说你会成为赞达拉真正的英雄。
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8102,'卡亚罗之石','$C，这块坠饰上镶嵌的卡亚罗之石来自南海的卡亚罗山脉。卡亚罗山脉地带分布着许多活火山，那里的地质地形不断发生剧烈的变动。$B$B随着你与赞达拉巨魔的关系日益密切，卡亚罗之石的力量也会增强。利用这块石头的力量打败我们的敌人吧。就像卡亚罗山脉那样:迅速、致命、富有爆炸力……','好消息，$N。莫托尔最近对你赞不绝口，他说你会成为赞达拉真正的英雄。
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8103,'卡亚罗之石','继续追杀祖尔格拉布巨魔。要让哈卡明白，这个世界不会屈从於他的强大意志。$B','哈卡的爪牙畏惧你，$N。他们谈论你的时候露出的那种畏惧的神情，只有在他们面对神灵时才会出现。卡亚罗之石的力量让他们闻风丧胆。$B$B是时候进一步强化卡亚罗之石了，把坠饰给我吧。') ON DUPLICATE KEY UPDATE Title_loc4='卡亚罗之石',OfferRewardText_loc4='继续追杀祖尔格拉布巨魔。要让哈卡明白，这个世界不会屈从於他的强大意志。$B',RequestItemsText_loc4='哈卡的爪牙畏惧你，$N。他们谈论你的时候露出的那种畏惧的神情，只有在他们面对神灵时才会出现。卡亚罗之石的力量让他们闻风丧胆。$B$B是时候进一步强化卡亚罗之石了，把坠饰给我吧。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8104,'卡亚罗的珠宝','<阿塔比姆以你前所未见的强大力量击碎了石头。>$B$B看见了吗?卡亚罗之石便是我们所说的异质晶簇。石头中蕴藏中汲取了潜在能量的水晶，破开石头便能发挥最大潜能。用它来消灭我们的敌人吧。$B','把坠饰给我吧，$N。我要给你看点东西。') ON DUPLICATE KEY UPDATE Title_loc4='卡亚罗的珠宝',OfferRewardText_loc4='<阿塔比姆以你前所未见的强大力量击碎了石头。>$B$B看见了吗?卡亚罗之石便是我们所说的异质晶簇。石头中蕴藏中汲取了潜在能量的水晶，破开石头便能发挥最大潜能。用它来消灭我们的敌人吧。$B',RequestItemsText_loc4='把坠饰给我吧，$N。我要给你看点东西。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4,ObjectiveText2_loc4,ObjectiveText3_loc4,ObjectiveText4_loc4) VALUES (8105,'阿拉希盆地之战！','$N，在阿拉希盆地的战斗是为了资源和领土而进行的战斗。这个地区作战的关键是保证我们军队稀有物资和补给的顺畅运作。我命令你去攻击距离我们在阿拉希盆地中的基地最远的战略设施。$B$B当农场、矿洞、伐木场或铁匠铺被敌人占据时，攻击这些设施，找到敌人的旗帜，然后把它拔掉！$B$B当你完成了夺回这四个点的任务之后，就回到我这里来。','进攻矿洞、伐木场、铁匠铺和农场，然后向避难谷地的奥斯莱特元帅复命。','我收到了你在阿拉希盆地大显神威的报告，$N。做得好!如果有越来越多的像你这样勇敢的$C加入我们，我坚信我们总有一天能夺回我们的家园。$B','$N，你还没有完成对这4个战略要点的攻击。任务完成之后再回到我这里来。','突袭矿坑','突袭伐木场','突袭铁匠铺','突袭农场') ON DUPLICATE KEY UPDATE Title_loc4='阿拉希盆地之战！',Details_loc4='$N，在阿拉希盆地的战斗是为了资源和领土而进行的战斗。这个地区作战的关键是保证我们军队稀有物资和补给的顺畅运作。我命令你去攻击距离我们在阿拉希盆地中的基地最远的战略设施。$B$B当农场、矿洞、伐木场或铁匠铺被敌人占据时，攻击这些设施，找到敌人的旗帜，然后把它拔掉！$B$B当你完成了夺回这四个点的任务之后，就回到我这里来。',Objectives_loc4='进攻矿洞、伐木场、铁匠铺和农场，然后向避难谷地的奥斯莱特元帅复命。',OfferRewardText_loc4='我收到了你在阿拉希盆地大显神威的报告，$N。做得好!如果有越来越多的像你这样勇敢的$C加入我们，我坚信我们总有一天能夺回我们的家园。$B',RequestItemsText_loc4='$N，你还没有完成对这4个战略要点的攻击。任务完成之后再回到我这里来。',ObjectiveText1_loc4='突袭矿坑',ObjectiveText2_loc4='突袭伐木场',ObjectiveText3_loc4='突袭铁匠铺',ObjectiveText4_loc4='突袭农场';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4) VALUES (8106,'科赞的玷污','请收下这块坠饰，$C。运用它的力量消灭我们共同的敌人。$B$B戴在你脖子上的坠饰蕴涵着一段历史。科赞原本是赞达拉帝国的领土。但是哥布林的贸易大亨玷污了此地，将我的兄弟姐妹赶了出来。$B$B科赞现在是哥布林主城幽坑城的属地;
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4) VALUES (8107,'科赞的玷污','请收下这块坠饰，$C。运用它的力量消灭我们共同的敌人。$B$B戴在你脖子上的坠饰蕴涵着一段历史。科赞原本是赞达拉帝国的领土。但是哥布林的贸易大亨玷污了此地，将我的兄弟姐妹赶了出来。$B$B科赞现在是哥布林主城幽坑城的属地;
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4) VALUES (8108,'科赞的玷污','请收下这块坠饰，$C。运用它的力量消灭我们共同的敌人。$B$B戴在你脖子上的坠饰蕴涵着一段历史。科赞原本是赞达拉帝国的领土。但是哥布林的贸易大亨玷污了此地，将我的兄弟姐妹赶了出来。$B$B科赞现在是哥布林主城幽坑城的属地;
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8109,'科赞的强力玷污','剥去他们尸体上的鲜肉。看着黑暗的力量吞噬哈卡，从他们的恐惧中汲取力量，$C。让科赞的玷污再次强化……','召唤恶魔，$C。让它们汲取玷污科赞的黑暗能量。指挥它们大开杀戒!$B$B是的……是时候对科赞的玷污进行最后一次强化了。把它给我吧。') ON DUPLICATE KEY UPDATE Title_loc4='科赞的强力玷污',OfferRewardText_loc4='剥去他们尸体上的鲜肉。看着黑暗的力量吞噬哈卡，从他们的恐惧中汲取力量，$C。让科赞的玷污再次强化……',RequestItemsText_loc4='召唤恶魔，$C。让它们汲取玷污科赞的黑暗能量。指挥它们大开杀戒!$B$B是的……是时候对科赞的玷污进行最后一次强化了。把它给我吧。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4) VALUES (8110,'南海魔化海藻','看到这些海藻了吗?它们产自南海。我们往其中添加了一点魔精和魔法，它就成为一件非常有用的饰品。$B$B你是个德鲁伊，这对你来说相当容易。把它戴在你的脖子上，想像一下大自然、松鼠或是所有你们会喜欢的东西。') ON DUPLICATE KEY UPDATE Title_loc4='南海魔化海藻',OfferRewardText_loc4='看到这些海藻了吗?它们产自南海。我们往其中添加了一点魔精和魔法，它就成为一件非常有用的饰品。$B$B你是个德鲁伊，这对你来说相当容易。把它戴在你的脖子上，想像一下大自然、松鼠或是所有你们会喜欢的东西。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4) VALUES (8111,'南海魔化海藻','看到这些海藻了吗?它们产自南海。我们往其中添加了一点魔精和魔法，它就成为一件非常有用的饰品。$B$B你是个德鲁伊，这对你来说相当容易。把它戴在你的脖子上，想像一下大自然、松鼠或是所有你们会喜欢的东西。') ON DUPLICATE KEY UPDATE Title_loc4='南海魔化海藻',OfferRewardText_loc4='看到这些海藻了吗?它们产自南海。我们往其中添加了一点魔精和魔法，它就成为一件非常有用的饰品。$B$B你是个德鲁伊，这对你来说相当容易。把它戴在你的脖子上，想像一下大自然、松鼠或是所有你们会喜欢的东西。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4) VALUES (8112,'南海魔化海藻','看到这些海藻了吗?它们产自南海。我们往其中添加了一点魔精和魔法，它就成为一件非常有用的饰品。$B$B你是个德鲁伊，这对你来说相当容易。把它戴在你的脖子上，想像一下大自然、松鼠或是所有你们会喜欢的东西。') ON DUPLICATE KEY UPDATE Title_loc4='南海魔化海藻',OfferRewardText_loc4='看到这些海藻了吗?它们产自南海。我们往其中添加了一点魔精和魔法，它就成为一件非常有用的饰品。$B$B你是个德鲁伊，这对你来说相当容易。把它戴在你的脖子上，想像一下大自然、松鼠或是所有你们会喜欢的东西。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8113,'原始南海魔化海藻','$N，旅途愉快。继续取哈卡和他的爪牙的性命吧。','$N!好久不见。拉斯塔哈命令我为你的坠饰加入更多的魔精和魔法，这可是最后一次呢，你知道吗?真的!要不是亲眼所见，我怎么都无法相信呢。把坠饰放在这儿吧。') ON DUPLICATE KEY UPDATE Title_loc4='原始南海魔化海藻',OfferRewardText_loc4='$N，旅途愉快。继续取哈卡和他的爪牙的性命吧。',RequestItemsText_loc4='$N!好久不见。拉斯塔哈命令我为你的坠饰加入更多的魔精和魔法，这可是最后一次呢，你知道吗?真的!要不是亲眼所见，我怎么都无法相信呢。把坠饰放在这儿吧。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,EndText_loc4) VALUES (8114,'控制四座基地','$N，你赢得了在阿拉希盆地的战争，并在战场上证明了自己有资格得到荣耀和尊重。你是一个有价值的$c，你让我们的敌人知道我们绝对不会向他们的暴行屈服！$B$B现在我有一项艰巨的任务要交给你。我需要你进入阿拉希盆地，占领至少四座基地。如果你可以完成这个任务的话，那么我们不仅保证了重要资源的供给，而且还向部落展示了我们的力量！$B$B出发吧，$N，祝你好运。','进入阿拉希盆地，同时占据并控制四座基地，当任务完成之后向避难谷地的奥斯莱特元帅报告。','做得好，$N!一个激动的斥候已经带来了你成功的消息。我们阿拉索联军上下都为你感到欢欣鼓舞!$B$B你已经渐渐变成这个军团的英雄，今天你的事蹟又再一次证明了你的价值。$B','你还没有占据四座基地，$N。回到阿拉希盆地，完成你的任务吧!','控制四座基地。') ON DUPLICATE KEY UPDATE Title_loc4='控制四座基地',Details_loc4='$N，你赢得了在阿拉希盆地的战争，并在战场上证明了自己有资格得到荣耀和尊重。你是一个有价值的$c，你让我们的敌人知道我们绝对不会向他们的暴行屈服！$B$B现在我有一项艰巨的任务要交给你。我需要你进入阿拉希盆地，占领至少四座基地。如果你可以完成这个任务的话，那么我们不仅保证了重要资源的供给，而且还向部落展示了我们的力量！$B$B出发吧，$N，祝你好运。',Objectives_loc4='进入阿拉希盆地，同时占据并控制四座基地，当任务完成之后向避难谷地的奥斯莱特元帅报告。',OfferRewardText_loc4='做得好，$N!一个激动的斥候已经带来了你成功的消息。我们阿拉索联军上下都为你感到欢欣鼓舞!$B$B你已经渐渐变成这个军团的英雄，今天你的事蹟又再一次证明了你的价值。$B',RequestItemsText_loc4='你还没有占据四座基地，$N。回到阿拉希盆地，完成你的任务吧!',EndText_loc4='控制四座基地。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,EndText_loc4) VALUES (8115,'控制五座基地','$N，阿拉希盆地的资源之战是一场血腥的战斗。阿拉索联军需要你的帮助。$B$B我们还有一个任务需要交给你。$B$B联军想要对污染者进行一次大规模攻击。我们要把他们从这个战场中的每个重要战略点里赶出去！$B$B这个任务不简单，但是如果说有人可以完成它的话，那个人就是你。','同时控制阿拉希盆地中的五座基地，然后向避难谷地的奥斯莱特元帅复命。','你成功了!你占据了所有基地!做得好，$N!$B$B以前有人曾怀疑你能否顺利完成，但是我就知道你会成功。感谢你，整个阿拉索联军向你表示致敬，而被遗忘者的污染者每次提到你的名字，必定感到胆战心惊!$B','你还没有完成你的任务，$N。这很困难，但是我深信你的实力。','夺取五座基地。') ON DUPLICATE KEY UPDATE Title_loc4='控制五座基地',Details_loc4='$N，阿拉希盆地的资源之战是一场血腥的战斗。阿拉索联军需要你的帮助。$B$B我们还有一个任务需要交给你。$B$B联军想要对污染者进行一次大规模攻击。我们要把他们从这个战场中的每个重要战略点里赶出去！$B$B这个任务不简单，但是如果说有人可以完成它的话，那个人就是你。',Objectives_loc4='同时控制阿拉希盆地中的五座基地，然后向避难谷地的奥斯莱特元帅复命。',OfferRewardText_loc4='你成功了!你占据了所有基地!做得好，$N!$B$B以前有人曾怀疑你能否顺利完成，但是我就知道你会成功。感谢你，整个阿拉索联军向你表示致敬，而被遗忘者的污染者每次提到你的名字，必定感到胆战心惊!$B',RequestItemsText_loc4='你还没有完成你的任务，$N。这很困难，但是我深信你的实力。',EndText_loc4='夺取五座基地。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8116,'巫毒幻象','当心那些邪恶的哈卡之灵。老实说，它们令人毛骨悚然。$B','好消息，$N。莫托尔最近对你赞不绝口，他说你会成为赞达拉真正的英雄。$B$B他还让梅维克再次帮你磨亮宝珠呢!把它放在这儿吧，梅维克会磨亮幻象。') ON DUPLICATE KEY UPDATE Title_loc4='巫毒幻象',OfferRewardText_loc4='当心那些邪恶的哈卡之灵。老实说，它们令人毛骨悚然。$B',RequestItemsText_loc4='好消息，$N。莫托尔最近对你赞不绝口，他说你会成为赞达拉真正的英雄。$B$B他还让梅维克再次帮你磨亮宝珠呢!把它放在这儿吧，梅维克会磨亮幻象。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8117,'巫毒幻象','当心那些邪恶的哈卡之灵。老实说，它们令人毛骨悚然。$B','好消息，$N。莫托尔最近对你赞不绝口，他说你会成为赞达拉真正的英雄。$B$B他还让梅维克再次帮你磨亮宝珠呢!把它放在这儿吧，梅维克会磨亮幻象。') ON DUPLICATE KEY UPDATE Title_loc4='巫毒幻象',OfferRewardText_loc4='当心那些邪恶的哈卡之灵。老实说，它们令人毛骨悚然。$B',RequestItemsText_loc4='好消息，$N。莫托尔最近对你赞不绝口，他说你会成为赞达拉真正的英雄。$B$B他还让梅维克再次帮你磨亮宝珠呢!把它放在这儿吧，梅维克会磨亮幻象。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8118,'巫毒幻象','看看吧，$N。巫毒的力量更加强大了，不是吗?让原始的力量流遍你吧。','啊哈!梅维基闹了一个笑话!
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8119,'完美巫毒幻象','$N，终有一天你可以使用宝珠直接与我交流。一旦你结束了与哈卡的战争，梅维克就能重返家园。让我们呼唤那些强大的灵魂，让那一天早日到来吧。$B','<梅维克指着你的坠饰。>$B$B看看它，$N!看起来象真的一样。灵魂在围绕着宝珠跳舞。$B$B把它交给梅维克吧，她会进行最后一次调整的。') ON DUPLICATE KEY UPDATE Title_loc4='完美巫毒幻象',OfferRewardText_loc4='$N，终有一天你可以使用宝珠直接与我交流。一旦你结束了与哈卡的战争，梅维克就能重返家园。让我们呼唤那些强大的灵魂，让那一天早日到来吧。$B',RequestItemsText_loc4='<梅维克指着你的坠饰。>$B$B看看它，$N!看起来象真的一样。灵魂在围绕着宝珠跳舞。$B$B把它交给梅维克吧，她会进行最后一次调整的。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4,ObjectiveText2_loc4,ObjectiveText3_loc4,ObjectiveText4_loc4) VALUES (8120,'阿拉希盆地之战！','无疑你已经听说了，阿拉索联军正派大量的军队进驻阿拉西盆地。联盟那帮蠢货想要食物和补给，因此妄图占据这块富饶的土地。我们必须让他们知道阿拉希永远不再会是人类的家园了！$B$B去阿拉希盆地然后进攻那里矿井，伐木场，铁匠铺和马厩。夺下敌人在那里的旗帜，把那里变成部落的领土。$B$B出发吧，$N。当任务完成之后向我复命。','进攻阿拉希盆地的矿洞、伐木场、铁匠铺和兽栏，然后向落锤镇的屠杀者杜维尔复命。','污染者斥候已经向我报告你成功了，$N。做得好。$B$B你慢慢就会知道，想要赢得阿拉希盆地的胜利，我们必须保持警惕，并击败联盟任何想扩张的企图。唯有如此，我们才能确保赢得最后的胜利。$B','你还没有完成你的任务，$N。攻击我提到的所有四处基地，你完成任务之后再回到我这里来!','突袭矿坑','突袭伐木场','突袭铁匠铺','突袭兽栏') ON DUPLICATE KEY UPDATE Title_loc4='阿拉希盆地之战！',Details_loc4='无疑你已经听说了，阿拉索联军正派大量的军队进驻阿拉西盆地。联盟那帮蠢货想要食物和补给，因此妄图占据这块富饶的土地。我们必须让他们知道阿拉希永远不再会是人类的家园了！$B$B去阿拉希盆地然后进攻那里矿井，伐木场，铁匠铺和马厩。夺下敌人在那里的旗帜，把那里变成部落的领土。$B$B出发吧，$N。当任务完成之后向我复命。',Objectives_loc4='进攻阿拉希盆地的矿洞、伐木场、铁匠铺和兽栏，然后向落锤镇的屠杀者杜维尔复命。',OfferRewardText_loc4='污染者斥候已经向我报告你成功了，$N。做得好。$B$B你慢慢就会知道，想要赢得阿拉希盆地的胜利，我们必须保持警惕，并击败联盟任何想扩张的企图。唯有如此，我们才能确保赢得最后的胜利。$B',RequestItemsText_loc4='你还没有完成你的任务，$N。攻击我提到的所有四处基地，你完成任务之后再回到我这里来!',ObjectiveText1_loc4='突袭矿坑',ObjectiveText2_loc4='突袭伐木场',ObjectiveText3_loc4='突袭铁匠铺',ObjectiveText4_loc4='突袭兽栏';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,EndText_loc4) VALUES (8121,'夺取四座基地','$N，随着阿拉希盆地的战事进展，你的事迹已经传遍了战场。你的所做所为让我确信你一定可以完成现在我要给你的任务。$B$B现在是给阿拉索联军一个信号的时候了。我们将会向他们展示，他们在阿拉希盆地的防守是多么脆弱。我们要通过同时占领阿拉希盆地的四个战略点来让他们明白这一点。$B$B如果你可以完成这个任务，$N，你将赢得污染者的尊敬。','同时占据阿拉希盆地中的四座基地，然后向落锤镇的屠杀者杜维尔复命。','做得好，$N!你最近在阿拉希盆地所完成的任务都十分困难，它们的成功值得表扬。阿拉索联军在最近的遭遇战中必定被打得抱头鼠窜，希望他们可以重新考虑一下继续在这里战斗的必要性。$B','回到阿拉希盆地，$N，完成你所肩负的任务!占据四座基地!','占领四座基地。') ON DUPLICATE KEY UPDATE Title_loc4='夺取四座基地',Details_loc4='$N，随着阿拉希盆地的战事进展，你的事迹已经传遍了战场。你的所做所为让我确信你一定可以完成现在我要给你的任务。$B$B现在是给阿拉索联军一个信号的时候了。我们将会向他们展示，他们在阿拉希盆地的防守是多么脆弱。我们要通过同时占领阿拉希盆地的四个战略点来让他们明白这一点。$B$B如果你可以完成这个任务，$N，你将赢得污染者的尊敬。',Objectives_loc4='同时占据阿拉希盆地中的四座基地，然后向落锤镇的屠杀者杜维尔复命。',OfferRewardText_loc4='做得好，$N!你最近在阿拉希盆地所完成的任务都十分困难，它们的成功值得表扬。阿拉索联军在最近的遭遇战中必定被打得抱头鼠窜，希望他们可以重新考虑一下继续在这里战斗的必要性。$B',RequestItemsText_loc4='回到阿拉希盆地，$N，完成你所肩负的任务!占据四座基地!',EndText_loc4='占领四座基地。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,EndText_loc4) VALUES (8122,'夺取五座基地','我们其实已经深深陷入战争之中，只是我们还没有意识到。幸好，我们的探子回报说发现了阿拉索联军的弱点。我们必须利用这一机会对他们造成致命一击！回到阿拉希盆地，和我们的敌人交战吧。诅咒他们，干掉他们，控制所有的五个战略点！让他们的士兵尖叫，流血，从前线仓皇撤退，让他们用抽泣的嘴唇述说你的事迹。$B$B完成这一目标，为污染者带来光辉的胜利。','同时占据阿拉希盆地中的五座基地，然后向落锤镇的屠杀者杜维尔复命。','联盟的哭喊声和你的冲锋号角响彻战场，即使在这里也可以清晰听到，$N。对於他们所遭受的苦痛和你带去的恐惧，我感到遗憾。不过只是一点点而已。$B$B你对於污染者的贡献是毋庸置疑的。你在阿拉希盆地的事蹟让人感到震撼，它已经传到了瓦里玛萨斯大人……甚至是黑暗女王的耳中。$B','你必须迅速出击，$N!不要犹豫!占据阿拉希盆地的五座基地，然后回来向我报告!','占领五座基地。') ON DUPLICATE KEY UPDATE Title_loc4='夺取五座基地',Details_loc4='我们其实已经深深陷入战争之中，只是我们还没有意识到。幸好，我们的探子回报说发现了阿拉索联军的弱点。我们必须利用这一机会对他们造成致命一击！回到阿拉希盆地，和我们的敌人交战吧。诅咒他们，干掉他们，控制所有的五个战略点！让他们的士兵尖叫，流血，从前线仓皇撤退，让他们用抽泣的嘴唇述说你的事迹。$B$B完成这一目标，为污染者带来光辉的胜利。',Objectives_loc4='同时占据阿拉希盆地中的五座基地，然后向落锤镇的屠杀者杜维尔复命。',OfferRewardText_loc4='联盟的哭喊声和你的冲锋号角响彻战场，即使在这里也可以清晰听到，$N。对於他们所遭受的苦痛和你带去的恐惧，我感到遗憾。不过只是一点点而已。$B$B你对於污染者的贡献是毋庸置疑的。你在阿拉希盆地的事蹟让人感到震撼，它已经传到了瓦里玛萨斯大人……甚至是黑暗女王的耳中。$B',RequestItemsText_loc4='你必须迅速出击，$N!不要犹豫!占据阿拉希盆地的五座基地，然后回来向我报告!',EndText_loc4='占领五座基地。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8123,'切断阿拉索补给线','阿拉索联军正在不惜一切代价进攻阿拉希，并妄图夺回这个区域。联盟的各个种族正在全力进军这块遥远的土地，想要将他们的势力从避难谷地扩张到这里。我们必须阻止他们，而最好的方式就是夺取他们的资源。$B$B你可以帮助我们，$N。进入阿拉希盆地，那里遍地都是丰富的矿藏、肥沃的土地和技艺精湛的能工巧匠。占据并控制你找到的所有基地，赢得战斗，然后把你获得的资源给我拿回来。','进入阿拉希盆地，获得一箱阿拉希资源箱，然后将它交给落锤镇的亡灵哨兵莫提斯。','非常感谢，$N。我们会确保这些资源不落入联盟的手中。$B$B你的战斗能力值得表彰，$N，去面对阿拉索联军，赢得更辉煌的胜利吧。','你赢得阿拉希盆地的战斗了吗，$N?你拿到资源木箱了吗?') ON DUPLICATE KEY UPDATE Title_loc4='切断阿拉索补给线',Details_loc4='阿拉索联军正在不惜一切代价进攻阿拉希，并妄图夺回这个区域。联盟的各个种族正在全力进军这块遥远的土地，想要将他们的势力从避难谷地扩张到这里。我们必须阻止他们，而最好的方式就是夺取他们的资源。$B$B你可以帮助我们，$N。进入阿拉希盆地，那里遍地都是丰富的矿藏、肥沃的土地和技艺精湛的能工巧匠。占据并控制你找到的所有基地，赢得战斗，然后把你获得的资源给我拿回来。',Objectives_loc4='进入阿拉希盆地，获得一箱阿拉希资源箱，然后将它交给落锤镇的亡灵哨兵莫提斯。',OfferRewardText_loc4='非常感谢，$N。我们会确保这些资源不落入联盟的手中。$B$B你的战斗能力值得表彰，$N，去面对阿拉索联军，赢得更辉煌的胜利吧。',RequestItemsText_loc4='你赢得阿拉希盆地的战斗了吗，$N?你拿到资源木箱了吗?';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8124,'更多的资源','啊，你抢到了更多的资源木箱!没有资源补给的联盟肯定会一败涂地的!$B$B感谢你，$N。你的努力已经为我们所知，并且也为瓦里玛萨斯所知。','虽然在破坏阿拉索联军的补给线方面，污染者做得已经很不错了，但是联盟还在继续对阿拉希盆地进行攻击。我们必须向盆地增派部队，并夺回更多的资源。') ON DUPLICATE KEY UPDATE Title_loc4='更多的资源',OfferRewardText_loc4='啊，你抢到了更多的资源木箱!没有资源补给的联盟肯定会一败涂地的!$B$B感谢你，$N。你的努力已经为我们所知，并且也为瓦里玛萨斯所知。',RequestItemsText_loc4='虽然在破坏阿拉索联军的补给线方面，污染者做得已经很不错了，但是联盟还在继续对阿拉希盆地进行攻击。我们必须向盆地增派部队，并夺回更多的资源。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8141,'赞达拉暗影坠饰','这块坠饰的只能再强化一次了，$C。时机合适时，我会对它进行强化。$B','了不起，$N。我好些年没遇到你这样的天才杀手啦。就连莫托尔也知道你为赞达拉所做的贡献。现在是时候进一步强化坠饰了，把它给我吧。') ON DUPLICATE KEY UPDATE Title_loc4='赞达拉暗影坠饰',OfferRewardText_loc4='这块坠饰的只能再强化一次了，$C。时机合适时，我会对它进行强化。$B',RequestItemsText_loc4='了不起，$N。我好些年没遇到你这样的天才杀手啦。就连莫托尔也知道你为赞达拉所做的贡献。现在是时候进一步强化坠饰了，把它给我吧。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8142,'赞达拉暗影坠饰','年轻人$C，你进步神速。或许是该让你加入塞拉利卡─赞达拉的精英组织了。数千年来，我们一直充当着赞达拉帝国的刺客，但是长期以来我们都很懒散松懈，这使得哈卡的力量不断扩张。当我们再次面对哈卡大军的时候，却没了巨魔同盟的支持。你和你的盟友必须帮助我们消灭血神和他的爪牙!$B$B带上这个坠饰，它会助你一臂之力的。','了不起，$N。我好些年没遇到你这样的天才杀手啦。就连莫托尔也知道你为赞达拉所做的贡献。现在是时候进一步强化坠饰了，把它给我吧。') ON DUPLICATE KEY UPDATE Title_loc4='赞达拉暗影坠饰',OfferRewardText_loc4='年轻人$C，你进步神速。或许是该让你加入塞拉利卡─赞达拉的精英组织了。数千年来，我们一直充当着赞达拉帝国的刺客，但是长期以来我们都很懒散松懈，这使得哈卡的力量不断扩张。当我们再次面对哈卡大军的时候，却没了巨魔同盟的支持。你和你的盟友必须帮助我们消灭血神和他的爪牙!$B$B带上这个坠饰，它会助你一臂之力的。',RequestItemsText_loc4='了不起，$N。我好些年没遇到你这样的天才杀手啦。就连莫托尔也知道你为赞达拉所做的贡献。现在是时候进一步强化坠饰了，把它给我吧。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8143,'赞达拉暗影坠饰','年轻人$C，你进步神速。或许是该让你加入塞拉利卡─赞达拉的精英组织了。数千年来，我们一直充当着赞达拉帝国的刺客，但是长期以来我们都很懒散松懈，这使得哈卡的力量不断扩张。当我们再次面对哈卡大军的时候，却没了巨魔同盟的支持。你和你的盟友必须帮助我们消灭血神和他的爪牙!$B$B带上这个坠饰，它会助你一臂之力的。','了不起，$N。我好些年没遇到你这样的天才杀手啦。就连莫托尔也知道你为赞达拉所做的贡献。现在是时候进一步强化坠饰了，把它给我吧。') ON DUPLICATE KEY UPDATE Title_loc4='赞达拉暗影坠饰',OfferRewardText_loc4='年轻人$C，你进步神速。或许是该让你加入塞拉利卡─赞达拉的精英组织了。数千年来，我们一直充当着赞达拉帝国的刺客，但是长期以来我们都很懒散松懈，这使得哈卡的力量不断扩张。当我们再次面对哈卡大军的时候，却没了巨魔同盟的支持。你和你的盟友必须帮助我们消灭血神和他的爪牙!$B$B带上这个坠饰，它会助你一臂之力的。',RequestItemsText_loc4='了不起，$N。我好些年没遇到你这样的天才杀手啦。就连莫托尔也知道你为赞达拉所做的贡献。现在是时候进一步强化坠饰了，把它给我吧。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8144,'赞达拉暗影大师坠饰','这是我们最后一次在塞拉利卡的庇护下进行交谈。你已经知道自己该做什么了。带上坠饰继续杀戮吧，绝不能让哈卡离开祖尔格拉布。','$N，它渴望成长。坠饰已经吸取了祖尔格拉布上千具巨魔尸体的能量。把它给我吧，我会对它做最后一次强化。') ON DUPLICATE KEY UPDATE Title_loc4='赞达拉暗影大师坠饰',OfferRewardText_loc4='这是我们最后一次在塞拉利卡的庇护下进行交谈。你已经知道自己该做什么了。带上坠饰继续杀戮吧，绝不能让哈卡离开祖尔格拉布。',RequestItemsText_loc4='$N，它渴望成长。坠饰已经吸取了祖尔格拉布上千具巨魔尸体的能量。把它给我吧，我会对它做最后一次强化。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4) VALUES (8145,'漩涡之藤','在赞达拉，猎人是倍受尊崇的职业。最好的猎人都要前往漩涡边缘接受考验。$B$B他们从海洋中心采摘一种名为漩涡之藤的海藻，然后将其编织成坠饰。这种坠饰在附魔后可以提高猎人狩猎时的准确度和力度。$B$B现在，我将一串漩涡之藤编织成的坠饰交给你。随着你与赞达拉的关系日益密切，我还会进一步强化坠饰。') ON DUPLICATE KEY UPDATE Title_loc4='漩涡之藤',OfferRewardText_loc4='在赞达拉，猎人是倍受尊崇的职业。最好的猎人都要前往漩涡边缘接受考验。$B$B他们从海洋中心采摘一种名为漩涡之藤的海藻，然后将其编织成坠饰。这种坠饰在附魔后可以提高猎人狩猎时的准确度和力度。$B$B现在，我将一串漩涡之藤编织成的坠饰交给你。随着你与赞达拉的关系日益密切，我还会进一步强化坠饰。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4) VALUES (8146,'漩涡之藤','在赞达拉，猎人是倍受尊崇的职业。最好的猎人都要前往漩涡边缘接受考验。$B$B他们从海洋中心采摘一种名为漩涡之藤的海藻，然后将其编织成坠饰。这种坠饰在附魔后可以提高猎人狩猎时的准确度和力度。$B$B现在，我将一串漩涡之藤编织成的坠饰交给你。随着你与赞达拉的关系日益密切，我还会进一步强化坠饰。') ON DUPLICATE KEY UPDATE Title_loc4='漩涡之藤',OfferRewardText_loc4='在赞达拉，猎人是倍受尊崇的职业。最好的猎人都要前往漩涡边缘接受考验。$B$B他们从海洋中心采摘一种名为漩涡之藤的海藻，然后将其编织成坠饰。这种坠饰在附魔后可以提高猎人狩猎时的准确度和力度。$B$B现在，我将一串漩涡之藤编织成的坠饰交给你。随着你与赞达拉的关系日益密切，我还会进一步强化坠饰。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4) VALUES (8147,'漩涡之藤','在赞达拉，猎人是倍受尊崇的职业。最好的猎人都要前往漩涡边缘接受考验。$B$B他们从海洋中心采摘一种名为漩涡之藤的海藻，然后将其编织成坠饰。这种坠饰在附魔后可以提高猎人狩猎时的准确度和力度。$B$B现在，我将一串漩涡之藤编织成的坠饰交给你。随着你与赞达拉的关系日益密切，我还会进一步强化坠饰。') ON DUPLICATE KEY UPDATE Title_loc4='漩涡之藤',OfferRewardText_loc4='在赞达拉，猎人是倍受尊崇的职业。最好的猎人都要前往漩涡边缘接受考验。$B$B他们从海洋中心采摘一种名为漩涡之藤的海藻，然后将其编织成坠饰。这种坠饰在附魔后可以提高猎人狩猎时的准确度和力度。$B$B现在，我将一串漩涡之藤编织成的坠饰交给你。随着你与赞达拉的关系日益密切，我还会进一步强化坠饰。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8148,'漩涡之怒','年轻的$C，旅途才刚刚开始。或许有一天你会去大漩涡看看世界的中心。$B$B愿力量和坚韧与你同在!','莫托尔替拉斯塔哈传话给你，$N。皇室对你全力剿灭哈卡军队的行为倍加赞赏。我会在坠饰中编入最后一根漩涡之藤的。把它给我吧。') ON DUPLICATE KEY UPDATE Title_loc4='漩涡之怒',OfferRewardText_loc4='年轻的$C，旅途才刚刚开始。或许有一天你会去大漩涡看看世界的中心。$B$B愿力量和坚韧与你同在!',RequestItemsText_loc4='莫托尔替拉斯塔哈传话给你，$N。皇室对你全力剿灭哈卡军队的行为倍加赞赏。我会在坠饰中编入最后一根漩涡之藤的。把它给我吧。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8149,'缅怀英雄','在艾泽拉斯收获节上，我们对那些无私奉献英雄们表示感谢，他们中的一些甚至献出了自己的性命。联盟曾涌现出很多的英雄，但是没有谁的光芒能超越光明使者乌瑟尔。$B$B将这些祭品带到西瘟疫之地光明使者乌瑟尔的墓碑那儿，去表达我们的敬意吧。把祭品放在墓碑下，然后回到我们这儿来。收获节结束之前我会一直在这儿，别浪费时间了，出发吧。','前往西瘟疫之地的光明使者乌瑟尔的墓碑，在墓碑前放下他的祭品。在收获节结束之前返回铁炉堡的瓦格纳·巨锤那儿。','乌瑟是英雄中的英雄。我简直难以想像阿萨斯变节时他所承受的痛苦，阿萨斯是他最优秀的学生，他就像疼爱自己的儿子一样疼爱他。他尽了全力去阻止阿萨斯，他永远都是一个真正的圣骑士。乌瑟的战斗已经结束了，想想那些他曾经拯救过的人吧。$B$B谢谢你，$N。你向这位伟大的英雄献上了祭品，以此来纪念了他的精神和收获节的精神。$B','你到达光明使者乌瑟的墓碑，放下他的祭品了吗?$B$B对经验并不丰富的冒险家来说，这是一次危险的旅程;沿着穿越希尔斯布莱德的河流向北进入瘟疫之地是一条相对安全的道路。河流从悔恨岭附近的湖泊发源，往西奔流进入群山，穿过寂静的坟墓……那儿到处都是天灾军团的爪牙。') ON DUPLICATE KEY UPDATE Title_loc4='缅怀英雄',Details_loc4='在艾泽拉斯收获节上，我们对那些无私奉献英雄们表示感谢，他们中的一些甚至献出了自己的性命。联盟曾涌现出很多的英雄，但是没有谁的光芒能超越光明使者乌瑟尔。$B$B将这些祭品带到西瘟疫之地光明使者乌瑟尔的墓碑那儿，去表达我们的敬意吧。把祭品放在墓碑下，然后回到我们这儿来。收获节结束之前我会一直在这儿，别浪费时间了，出发吧。',Objectives_loc4='前往西瘟疫之地的光明使者乌瑟尔的墓碑，在墓碑前放下他的祭品。在收获节结束之前返回铁炉堡的瓦格纳·巨锤那儿。',OfferRewardText_loc4='乌瑟是英雄中的英雄。我简直难以想像阿萨斯变节时他所承受的痛苦，阿萨斯是他最优秀的学生，他就像疼爱自己的儿子一样疼爱他。他尽了全力去阻止阿萨斯，他永远都是一个真正的圣骑士。乌瑟的战斗已经结束了，想想那些他曾经拯救过的人吧。$B$B谢谢你，$N。你向这位伟大的英雄献上了祭品，以此来纪念了他的精神和收获节的精神。$B',RequestItemsText_loc4='你到达光明使者乌瑟的墓碑，放下他的祭品了吗?$B$B对经验并不丰富的冒险家来说，这是一次危险的旅程;沿着穿越希尔斯布莱德的河流向北进入瘟疫之地是一条相对安全的道路。河流从悔恨岭附近的湖泊发源，往西奔流进入群山，穿过寂静的坟墓……那儿到处都是天灾军团的爪牙。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8150,'缅怀英雄','在艾泽拉斯收获节上，我们对那些无私奉献英雄们表示感谢，他们中的一些甚至献出了自己的性命。部落曾涌现出许多英雄，但是没有谁的光芒能超越格罗姆·地狱咆哮。$B$B将这些祭品带到灰谷屠魔峡谷中的格罗姆·地狱咆哮的墓碑那儿，去表达我们的敬意吧。把祭品放在墓碑下，然后回到我们这儿来。收获节结束之前我会一直在这儿，别浪费时间了，出发吧。','前往灰谷屠魔峡谷的格罗姆·地狱咆哮的墓碑，在墓碑前放下他的祭品。在收获节结束之前返回奥格瑞玛的亚尼·纳沙克那儿。','葛罗的全名是葛罗玛什，这个名字的意思是「巨人之心」，他勇敢地与玛诺洛斯抗争。我想，在兽人受到诅咒之后，葛罗与玛诺洛斯同归於尽的壮举是对此最好的诠释。他的牺牲─或者说是赎罪，为部落后来的发展奠定了基础。$B$B谢谢你，$N。你向这位伟大的英雄献上了祭品，纪念了他的精神和收获节的精神。$B','你造访了葛罗·地狱吼的纪念碑，放下他的祭品了吗?$B$B纪念碑的所在地仍然受到燃烧军团的污染。当你接近纪念碑时，一定要多加小心，不要太过冒险了。') ON DUPLICATE KEY UPDATE Title_loc4='缅怀英雄',Details_loc4='在艾泽拉斯收获节上，我们对那些无私奉献英雄们表示感谢，他们中的一些甚至献出了自己的性命。部落曾涌现出许多英雄，但是没有谁的光芒能超越格罗姆·地狱咆哮。$B$B将这些祭品带到灰谷屠魔峡谷中的格罗姆·地狱咆哮的墓碑那儿，去表达我们的敬意吧。把祭品放在墓碑下，然后回到我们这儿来。收获节结束之前我会一直在这儿，别浪费时间了，出发吧。',Objectives_loc4='前往灰谷屠魔峡谷的格罗姆·地狱咆哮的墓碑，在墓碑前放下他的祭品。在收获节结束之前返回奥格瑞玛的亚尼·纳沙克那儿。',OfferRewardText_loc4='葛罗的全名是葛罗玛什，这个名字的意思是「巨人之心」，他勇敢地与玛诺洛斯抗争。我想，在兽人受到诅咒之后，葛罗与玛诺洛斯同归於尽的壮举是对此最好的诠释。他的牺牲─或者说是赎罪，为部落后来的发展奠定了基础。$B$B谢谢你，$N。你向这位伟大的英雄献上了祭品，纪念了他的精神和收获节的精神。$B',RequestItemsText_loc4='你造访了葛罗·地狱吼的纪念碑，放下他的祭品了吗?$B$B纪念碑的所在地仍然受到燃烧军团的污染。当你接近纪念碑时，一定要多加小心，不要太过冒险了。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8151,'猎人的护符','艾萨拉的奥汀克正在召集象你这样经验丰富的猎人。他是一名熊怪猎人，他离开了自己的部族，前来帮助塞纳里奥议会。奥汀克与他人分享自己的智慧，也告诉他们要如何维护平衡。你最好去跟他谈谈。$B$B奥汀克居住在艾萨拉埃达拉斯废墟东北部的悬崖顶部。','跟艾萨拉的奥汀克谈一谈。','打猎再也不是我的目的，教导猎人才是。而那是命运赋予我的。$B$B和我一起制作一个猎人的符咒—那是从倒下的猎物收集的战利品，会提醒你记得过去的试炼和胜利。我会好好保存这个符咒，并提供你另外的奖励。$B','很少人来看望老熊怪了。你也是来看我的吗?') ON DUPLICATE KEY UPDATE Title_loc4='猎人的护符',Details_loc4='艾萨拉的奥汀克正在召集象你这样经验丰富的猎人。他是一名熊怪猎人，他离开了自己的部族，前来帮助塞纳里奥议会。奥汀克与他人分享自己的智慧，也告诉他们要如何维护平衡。你最好去跟他谈谈。$B$B奥汀克居住在艾萨拉埃达拉斯废墟东北部的悬崖顶部。',Objectives_loc4='跟艾萨拉的奥汀克谈一谈。',OfferRewardText_loc4='打猎再也不是我的目的，教导猎人才是。而那是命运赋予我的。$B$B和我一起制作一个猎人的符咒—那是从倒下的猎物收集的战利品，会提醒你记得过去的试炼和胜利。我会好好保存这个符咒，并提供你另外的奖励。$B',RequestItemsText_loc4='很少人来看望老熊怪了。你也是来看我的吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8153,'苔蹄快步者的鹿角','艾萨拉的苔蹄快步者那强劲有力的鹿角是它们发动进攻时的有效武器，可以造成不小的伤害。完好的、自然的鹿角是这种动物的精神和信心的标志。$B$B如果你持有这样的鹿角，你也将拥有同样的自信。$B$B猎杀苔蹄快步者，把完好的鹿角交给我。','将一副完好的苔蹄快步者鹿角交给艾萨拉的奥汀克。奥汀克居住在埃达拉斯废墟东北部的悬崖顶。','只有拥有敏锐视力和无比耐心的人才能得到它们。做得好。$B','你找到鹿角了吗?') ON DUPLICATE KEY UPDATE Title_loc4='苔蹄快步者的鹿角',Details_loc4='艾萨拉的苔蹄快步者那强劲有力的鹿角是它们发动进攻时的有效武器，可以造成不小的伤害。完好的、自然的鹿角是这种动物的精神和信心的标志。$B$B如果你持有这样的鹿角，你也将拥有同样的自信。$B$B猎杀苔蹄快步者，把完好的鹿角交给我。',Objectives_loc4='将一副完好的苔蹄快步者鹿角交给艾萨拉的奥汀克。奥汀克居住在埃达拉斯废墟东北部的悬崖顶。',OfferRewardText_loc4='只有拥有敏锐视力和无比耐心的人才能得到它们。做得好。$B',RequestItemsText_loc4='你找到鹿角了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8154,'阿拉希盆地的资源!','我们必须依靠我们的士兵进行战斗，所有的士兵都会这么告诉你的。他们还会告诉你，他们正在使用破烂不堪的装备，饥肠辘辘地开向战场！$B$B这就是阿拉希盆地显得非常重要的原因。金属，武器，食物，木材——所有我们所需要的东西都可以从那里获得。$B$B那就是我需要你发挥作用的地方，愤怒的灵魂。进入阿拉希盆地，比敌人占据更多的基地，以此来获得战斗的胜利，然后给我带回一箱资源来。','获得阿拉希盆地战斗的胜利，获取一只阿拉希资源箱，然后向避难谷地的玛克里尔中士复命。','你拿到资源了!干得好!我会把这些资源送到我们的军需官那里，然后让他迅速把它们分配给我们的军队。$B$B谢谢你，$N。事实上，不断地完成这样的任务将是获得最终胜利的关键要素。','你拿到资源木箱了吗，$N?如果没有足够的资源，阿拉索联军的士兵可没有办法好好打一仗……') ON DUPLICATE KEY UPDATE Title_loc4='阿拉希盆地的资源!',Details_loc4='我们必须依靠我们的士兵进行战斗，所有的士兵都会这么告诉你的。他们还会告诉你，他们正在使用破烂不堪的装备，饥肠辘辘地开向战场！$B$B这就是阿拉希盆地显得非常重要的原因。金属，武器，食物，木材——所有我们所需要的东西都可以从那里获得。$B$B那就是我需要你发挥作用的地方，愤怒的灵魂。进入阿拉希盆地，比敌人占据更多的基地，以此来获得战斗的胜利，然后给我带回一箱资源来。',Objectives_loc4='获得阿拉希盆地战斗的胜利，获取一只阿拉希资源箱，然后向避难谷地的玛克里尔中士复命。',OfferRewardText_loc4='你拿到资源了!干得好!我会把这些资源送到我们的军需官那里，然后让他迅速把它们分配给我们的军队。$B$B谢谢你，$N。事实上，不断地完成这样的任务将是获得最终胜利的关键要素。',RequestItemsText_loc4='你拿到资源木箱了吗，$N?如果没有足够的资源，阿拉索联军的士兵可没有办法好好打一仗……';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8155,'阿拉希盆地的资源!','我们必须依靠我们的士兵进行战斗，所有的士兵都会这么告诉你的。他们还会告诉你，他们正在使用破烂不堪的装备，饥肠辘辘地开向战场！$B$B这就是阿拉希盆地显得非常重要的原因。金属，武器，食物，木材——所有我们所需要的东西都可以从那里获得。$B$B那就是我需要你发挥作用的地方，$N。进入阿拉希盆地，比敌人占据更多的基地，以此来获得战斗的胜利，然后给我带回一箱资源来。','获得阿拉希盆地战斗的胜利，获取一只阿拉希资源箱，然后向避难谷地的玛克里尔中士复命。','你拿到资源了!干得好!我会把这些资源送到我们的军需官那里，然后让他迅速把它们分配给我们的军队。$B$B谢谢你，$N。事实上，履行这样的任务将是赢得最终胜利的关键要素。','你拿到资源木箱了吗，$N?如果没有足够的资源，阿拉索联军的士兵可没有办法好好打一仗……') ON DUPLICATE KEY UPDATE Title_loc4='阿拉希盆地的资源!',Details_loc4='我们必须依靠我们的士兵进行战斗，所有的士兵都会这么告诉你的。他们还会告诉你，他们正在使用破烂不堪的装备，饥肠辘辘地开向战场！$B$B这就是阿拉希盆地显得非常重要的原因。金属，武器，食物，木材——所有我们所需要的东西都可以从那里获得。$B$B那就是我需要你发挥作用的地方，$N。进入阿拉希盆地，比敌人占据更多的基地，以此来获得战斗的胜利，然后给我带回一箱资源来。',Objectives_loc4='获得阿拉希盆地战斗的胜利，获取一只阿拉希资源箱，然后向避难谷地的玛克里尔中士复命。',OfferRewardText_loc4='你拿到资源了!干得好!我会把这些资源送到我们的军需官那里，然后让他迅速把它们分配给我们的军队。$B$B谢谢你，$N。事实上，履行这样的任务将是赢得最终胜利的关键要素。',RequestItemsText_loc4='你拿到资源木箱了吗，$N?如果没有足够的资源，阿拉索联军的士兵可没有办法好好打一仗……';
