INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8165,'更多的资源','啊，你抢到了更多的资源木箱!没有资源补给的联盟肯定会一败涂地的!$B$B感谢你，$N。你的努力已经为我们所知，并且也为瓦里玛萨斯所知。','虽然在破坏阿拉索联军的补给线方面，污染者做得已经很不错了，但是联盟还在继续对阿拉希盆地进行攻击。我们必须向盆地增派部队，并夺回更多的资源。') ON DUPLICATE KEY UPDATE Title_loc4='更多的资源',OfferRewardText_loc4='啊，你抢到了更多的资源木箱!没有资源补给的联盟肯定会一败涂地的!$B$B感谢你，$N。你的努力已经为我们所知，并且也为瓦里玛萨斯所知。',RequestItemsText_loc4='虽然在破坏阿拉索联军的补给线方面，污染者做得已经很不错了，但是联盟还在继续对阿拉希盆地进行攻击。我们必须向盆地增派部队，并夺回更多的资源。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4,ObjectiveText2_loc4,ObjectiveText3_loc4,ObjectiveText4_loc4) VALUES (8166,'阿拉希盆地之战！','$N，在阿拉希盆地的战斗是为了资源和领土而进行的战斗。这个地区作战的关键是保证我们军队稀有物资和补给的顺畅运作。我命令你去攻击距离我们在阿拉希盆地中的基地最远的战略设施。$B$B当农场、矿洞、伐木场或铁匠铺被敌人占据时，攻击这些设施，找到敌人的旗帜，然后把它拔掉！$B$B当你完成了夺回这四个点的任务之后，就回到我这里来。','进攻矿洞、伐木场、铁匠铺和农场，然后向避难谷地的奥斯莱特元帅复命。','我收到了你在阿拉希盆地大显神威的报告，$N。干得好!如果有越来越多的像你这样勇敢的$C加入我们，我相信我们总有一天能夺回我们的家园。$B','$N，你还没有完成对这4个战略要点的攻击。任务完成之后再回到我这里来。','突袭矿坑','突袭伐木场','突袭铁匠铺','突袭农场') ON DUPLICATE KEY UPDATE Title_loc4='阿拉希盆地之战！',Details_loc4='$N，在阿拉希盆地的战斗是为了资源和领土而进行的战斗。这个地区作战的关键是保证我们军队稀有物资和补给的顺畅运作。我命令你去攻击距离我们在阿拉希盆地中的基地最远的战略设施。$B$B当农场、矿洞、伐木场或铁匠铺被敌人占据时，攻击这些设施，找到敌人的旗帜，然后把它拔掉！$B$B当你完成了夺回这四个点的任务之后，就回到我这里来。',Objectives_loc4='进攻矿洞、伐木场、铁匠铺和农场，然后向避难谷地的奥斯莱特元帅复命。',OfferRewardText_loc4='我收到了你在阿拉希盆地大显神威的报告，$N。干得好!如果有越来越多的像你这样勇敢的$C加入我们，我相信我们总有一天能夺回我们的家园。$B',RequestItemsText_loc4='$N，你还没有完成对这4个战略要点的攻击。任务完成之后再回到我这里来。',ObjectiveText1_loc4='突袭矿坑',ObjectiveText2_loc4='突袭伐木场',ObjectiveText3_loc4='突袭铁匠铺',ObjectiveText4_loc4='突袭农场';
