INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4) VALUES (8271,'雷矛英雄','身为一名雷矛英雄，你必需从近几次的抢劫中选择一项物品……呃，获取宝物。$B') ON DUPLICATE KEY UPDATE Title_loc4='雷矛英雄',OfferRewardText_loc4='身为一名雷矛英雄，你必需从近几次的抢劫中选择一项物品……呃，获取宝物。$B';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4) VALUES (8272,'霜狼英雄','感觉如何$N? 摧毁你的敌人，看着他们的防卫线瓦解感觉如何?感觉很好，不是吗?$B$B你应该为此次英勇行动感到光荣，士兵。$B') ON DUPLICATE KEY UPDATE Title_loc4='霜狼英雄',OfferRewardText_loc4='感觉如何$N? 摧毁你的敌人，看着他们的防卫线瓦解感觉如何?感觉很好，不是吗?$B$B你应该为此次英勇行动感到光荣，士兵。$B';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4) VALUES (8273,'奥兰的感谢','真有趣啊?你说你在辛特兰望海崖一个被遗忘的小岛上发现这个石板，$C?真的非常有趣。<奥兰小心地将石板放下并磨擦她的双手。>$B$B我很感谢你对这件事的付出。我们的黑暗女王一定会对此发现感到相当满意。拿着，这是给你应得的报酬。$B') ON DUPLICATE KEY UPDATE Title_loc4='奥兰的感谢',OfferRewardText_loc4='真有趣啊?你说你在辛特兰望海崖一个被遗忘的小岛上发现这个石板，$C?真的非常有趣。<奥兰小心地将石板放下并磨擦她的双手。>$B$B我很感谢你对这件事的付出。我们的黑暗女王一定会对此发现感到相当满意。拿着，这是给你应得的报酬。$B';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4) VALUES (8274,'Test Kill Quest','Got some time to spare?  Kill me some Murlocs and I''ll give you something shiny!','Kill 5 Murlocs and come back to the test character.') ON DUPLICATE KEY UPDATE Title_loc4='Test Kill Quest',Details_loc4='Got some time to spare?  Kill me some Murlocs and I''ll give you something shiny!',Objectives_loc4='Kill 5 Murlocs and come back to the test character.';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8275,'夺回希利苏斯','注意了，联盟的英雄们！有这样一个威胁，我们长久以来都没能将它消除。希利苏斯地区的虫穴中传来的震颤提醒我们，它们的数量正在不断地增加，它们正在准备更大规模的扩张！$B$B塞纳里奥议会的力量已经聚集在希利苏斯，要及时地阻止那些异种生物！它们绝不能污染我们的土地！$B$B所有符合条件的勇士都去塞纳里奥要塞向唤风者梅恩·长角报告吧！异种生物必须被彻底消灭！','与希利苏斯塞纳里奥要塞的唤风者梅恩·长角谈一谈。','太好了，有新的成员响应号召，加入对抗异种虫类的军队。欢迎来到塞纳里奥城堡，$C。我很高兴看到我们的特使能说服你发挥才干。在这里你会发现有很多帮助我们的机会，我也希望你能快点证明自己对我们的事业是很有价值的。$B','我们正忙於准备进攻对付异种蠍，我希望你能前来协助我们。') ON DUPLICATE KEY UPDATE Title_loc4='夺回希利苏斯',Details_loc4='注意了，联盟的英雄们！有这样一个威胁，我们长久以来都没能将它消除。希利苏斯地区的虫穴中传来的震颤提醒我们，它们的数量正在不断地增加，它们正在准备更大规模的扩张！$B$B塞纳里奥议会的力量已经聚集在希利苏斯，要及时地阻止那些异种生物！它们绝不能污染我们的土地！$B$B所有符合条件的勇士都去塞纳里奥要塞向唤风者梅恩·长角报告吧！异种生物必须被彻底消灭！',Objectives_loc4='与希利苏斯塞纳里奥要塞的唤风者梅恩·长角谈一谈。',OfferRewardText_loc4='太好了，有新的成员响应号召，加入对抗异种虫类的军队。欢迎来到塞纳里奥城堡，$C。我很高兴看到我们的特使能说服你发挥才干。在这里你会发现有很多帮助我们的机会，我也希望你能快点证明自己对我们的事业是很有价值的。$B',RequestItemsText_loc4='我们正忙於准备进攻对付异种蠍，我希望你能前来协助我们。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8276,'夺回希利苏斯','注意了，部落的勇士们！有这样一个威胁，我们长久以来都没能将它消除。希利苏斯地区的虫穴中传来的震颤提醒我们，它们的数量正在不断地增加，它们正在准备更大规模的扩张！$B$B塞纳里奥议会的力量已经聚集在希利苏斯，要及时地阻止那些异种生物！它们绝不能污染我们的土地！$B$B所有符合条件的勇士都去塞纳里奥要塞向唤风者梅恩·长角报告吧！异种生物必须被彻底消灭！','与希利苏斯塞纳里奥要塞的唤风者梅恩·长角谈一谈。','太好了，有新的成员响应号召，加入对抗异种虫类的军队。欢迎来到塞纳里奥城堡，$C。我很高兴看到我们的特使能说服你发挥才干。在这里你会发现有很多帮助我们的机会，我也希望你能快点证明自己对我们的事业是很有价值的。$B','我们正忙於准备进攻对付异种蠍，我希望你能前来协助我们。') ON DUPLICATE KEY UPDATE Title_loc4='夺回希利苏斯',Details_loc4='注意了，部落的勇士们！有这样一个威胁，我们长久以来都没能将它消除。希利苏斯地区的虫穴中传来的震颤提醒我们，它们的数量正在不断地增加，它们正在准备更大规模的扩张！$B$B塞纳里奥议会的力量已经聚集在希利苏斯，要及时地阻止那些异种生物！它们绝不能污染我们的土地！$B$B所有符合条件的勇士都去塞纳里奥要塞向唤风者梅恩·长角报告吧！异种生物必须被彻底消灭！',Objectives_loc4='与希利苏斯塞纳里奥要塞的唤风者梅恩·长角谈一谈。',OfferRewardText_loc4='太好了，有新的成员响应号召，加入对抗异种虫类的军队。欢迎来到塞纳里奥城堡，$C。我很高兴看到我们的特使能说服你发挥才干。在这里你会发现有很多帮助我们的机会，我也希望你能快点证明自己对我们的事业是很有价值的。$B',RequestItemsText_loc4='我们正忙於准备进攻对付异种蠍，我希望你能前来协助我们。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8277,'沙漠中的剧毒','比提克斯·斯巴格为你效劳！我的堂兄诺格在为塞纳里奥要塞的炼金师进行稀有草药的采集工作，好吧，至少以前他在这么做。在他最后一次回来的时候，他的血液中带着一种强力毒液。$B$B我已经设法减缓毒性发作的时间，但是如果想要完全中和它的话，我就需要这种毒液的原始样本。$B$B诺格是从北面回来的，因此我想应该是石鞭蝎或者掠沙蜘蛛干的。带给我一些尖刺和毒牙，然后我就可以制作解毒剂了。','希利苏斯塞纳里奥要塞的比提克斯·斯巴格要求你带8个石鞭蝎之刺和8个掠沙蜘蛛的牙齿给他。','祈祷吧，朋友!希望我们能拯救诺格!$B','你完成了样本收集工作吗?拯救诺格刻不容缓!') ON DUPLICATE KEY UPDATE Title_loc4='沙漠中的剧毒',Details_loc4='比提克斯·斯巴格为你效劳！我的堂兄诺格在为塞纳里奥要塞的炼金师进行稀有草药的采集工作，好吧，至少以前他在这么做。在他最后一次回来的时候，他的血液中带着一种强力毒液。$B$B我已经设法减缓毒性发作的时间，但是如果想要完全中和它的话，我就需要这种毒液的原始样本。$B$B诺格是从北面回来的，因此我想应该是石鞭蝎或者掠沙蜘蛛干的。带给我一些尖刺和毒牙，然后我就可以制作解毒剂了。',Objectives_loc4='希利苏斯塞纳里奥要塞的比提克斯·斯巴格要求你带8个石鞭蝎之刺和8个掠沙蜘蛛的牙齿给他。',OfferRewardText_loc4='祈祷吧，朋友!希望我们能拯救诺格!$B',RequestItemsText_loc4='你完成了样本收集工作吗?拯救诺格刻不容缓!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8278,'诺格的最后一线希望','该死的！解毒剂没有生效。诺格一定是被南边的某种毒性更强的生物蜇了。$B$B我需要你去那里给我带回更多的样品，$N。好消息是因为它们的毒性够强，所以我需要的样品数量不用那么多。坏消息是南部各种有毒生物的种类更多，因此我需要各种各样的样品。','希利苏斯塞纳里奥要塞的比提克斯·斯巴格要求你给他带去3个石鞭巨钳蝎之刺、3个石鞭掠夺者之刺和3个石行蜘蛛的牙齿。','太好了!看来起效果了，诺格正在恢复。我们欠你个大大的人情!$B','这是我们最后一次救诺格的机会!快!') ON DUPLICATE KEY UPDATE Title_loc4='诺格的最后一线希望',Details_loc4='该死的！解毒剂没有生效。诺格一定是被南边的某种毒性更强的生物蜇了。$B$B我需要你去那里给我带回更多的样品，$N。好消息是因为它们的毒性够强，所以我需要的样品数量不用那么多。坏消息是南部各种有毒生物的种类更多，因此我需要各种各样的样品。',Objectives_loc4='希利苏斯塞纳里奥要塞的比提克斯·斯巴格要求你给他带去3个石鞭巨钳蝎之刺、3个石鞭掠夺者之刺和3个石行蜘蛛的牙齿。',OfferRewardText_loc4='太好了!看来起效果了，诺格正在恢复。我们欠你个大大的人情!$B',RequestItemsText_loc4='这是我们最后一次救诺格的机会!快!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8279,'暮光词典','暮光之锤对于敢于侵犯他们的人绝不会手软。他们把我当作野兽一样进行猎捕。不用说，他们的敌人就是我的朋友！$B$B要破译这块石板上的文字，我需要用他们的文字撰写的书籍来破译这些秘密的信息——我需要暮光词典。这么重要的工具被他们分成三章，放在了不同的地方！掌管它们的人被称为暮光守护者，去暮光之锤营地找到他们吧。','把暮光词典的三个章节交给希利苏斯的隐士奥泰尔。','对!就是这几个部分!让我们开始吧，$N。$B$B第三章中每三个字进行一下交换……或者第一章中每两个字进行一下交换……等等，是不是应该恰懊相反?$B','是谁啊?喔，是你!你找到所有的词典章篇了吗?') ON DUPLICATE KEY UPDATE Title_loc4='暮光词典',Details_loc4='暮光之锤对于敢于侵犯他们的人绝不会手软。他们把我当作野兽一样进行猎捕。不用说，他们的敌人就是我的朋友！$B$B要破译这块石板上的文字，我需要用他们的文字撰写的书籍来破译这些秘密的信息——我需要暮光词典。这么重要的工具被他们分成三章，放在了不同的地方！掌管它们的人被称为暮光守护者，去暮光之锤营地找到他们吧。',Objectives_loc4='把暮光词典的三个章节交给希利苏斯的隐士奥泰尔。',OfferRewardText_loc4='对!就是这几个部分!让我们开始吧，$N。$B$B第三章中每三个字进行一下交换……或者第一章中每两个字进行一下交换……等等，是不是应该恰懊相反?$B',RequestItemsText_loc4='是谁啊?喔，是你!你找到所有的词典章篇了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8280,'保护补给线','塞纳里奥要塞具有相当重要的战略意义。我确信只要我们可以控制住它，那么我们对于异种虫类的胜利必定会实现。另外我们还需要保证我们的物资补给可以及时到位。$B$B对于我们的补给商队来说，遍地都是的沙虫比异种虫类威胁还要大。就在今天早上，一大批晨光麦被掘泥打击者袭击并全部损失；我需要你去减少它们的数量，以此来保证我们的物资流通顺畅。','希利苏斯塞纳里奥要塞的唤风者梅恩·长角要求你去杀死15只掘泥打击者。','你赢得了我最诚挚的敬意。你对於塞纳里奥城堡的帮助显示了你真正的勇气。$B','掘泥打击者是一个很严重的威胁，必须马上解决他们!') ON DUPLICATE KEY UPDATE Title_loc4='保护补给线',Details_loc4='塞纳里奥要塞具有相当重要的战略意义。我确信只要我们可以控制住它，那么我们对于异种虫类的胜利必定会实现。另外我们还需要保证我们的物资补给可以及时到位。$B$B对于我们的补给商队来说，遍地都是的沙虫比异种虫类威胁还要大。就在今天早上，一大批晨光麦被掘泥打击者袭击并全部损失；我需要你去减少它们的数量，以此来保证我们的物资流通顺畅。',Objectives_loc4='希利苏斯塞纳里奥要塞的唤风者梅恩·长角要求你去杀死15只掘泥打击者。',OfferRewardText_loc4='你赢得了我最诚挚的敬意。你对於塞纳里奥城堡的帮助显示了你真正的勇气。$B',RequestItemsText_loc4='掘泥打击者是一个很严重的威胁，必须马上解决他们!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8281,'确保安全','迄今为止，你的表现很好地证明了你的实力，$N。然而，我们的补给线还没有完全安全。在解决了掘泥打击者的问题之后，他们南部的亲戚会占据他们留下的空缺。$B$B你需要击杀一些掘泥摧毁者，让它们不敢轻易越雷池一步，我们绝不能视我们的补给线安全为儿戏。','希利苏斯塞纳里奥要塞的唤风者梅恩·长角要求你去杀死20只掘泥摧毁者。','太好了!你已经证明了自己的实力，在和异种虫类作战的过程中，你无疑是个有价值的盟友。$B','掘泥打击者是一个很严重的威胁，必须立即将他们解决!') ON DUPLICATE KEY UPDATE Title_loc4='确保安全',Details_loc4='迄今为止，你的表现很好地证明了你的实力，$N。然而，我们的补给线还没有完全安全。在解决了掘泥打击者的问题之后，他们南部的亲戚会占据他们留下的空缺。$B$B你需要击杀一些掘泥摧毁者，让它们不敢轻易越雷池一步，我们绝不能视我们的补给线安全为儿戏。',Objectives_loc4='希利苏斯塞纳里奥要塞的唤风者梅恩·长角要求你去杀死20只掘泥摧毁者。',OfferRewardText_loc4='太好了!你已经证明了自己的实力，在和异种虫类作战的过程中，你无疑是个有价值的盟友。$B',RequestItemsText_loc4='掘泥打击者是一个很严重的威胁，必须立即将他们解决!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8282,'诺格的背包','我在哪里？我的包在哪里？*气喘吁吁*我一定是在逃脱那只巨蝎“死亡弯钩”的时候把它给弄丢了。我在逃命的时候匆匆忙忙就跑进了一个石鞭掠夺者的巢穴。$B$B那个包里有各种各样的稀有材料。没有了它们，我和比提克斯就没有办法制造塞纳里奥要塞所需要的药剂了。我现在太虚弱，已经没有办法爬起来了，但是如果你可以把我的材料拿回来，那么我就可以帮你制作这些药剂。$B$B我是在南边山中碰到死亡弯钩的，就在铜须营地的后面。','从希利苏斯南部山中找到诺格的背包，然后将它交给塞纳里奥要塞中的诺格。','太好了!你找回我的背包了。所有的稀有材料都在这里!我欠你很大一个人情。$B','还没找到我的包包吗?不过我已经很幸运了，至少毒药已经被净化过。') ON DUPLICATE KEY UPDATE Title_loc4='诺格的背包',Details_loc4='我在哪里？我的包在哪里？*气喘吁吁*我一定是在逃脱那只巨蝎“死亡弯钩”的时候把它给弄丢了。我在逃命的时候匆匆忙忙就跑进了一个石鞭掠夺者的巢穴。$B$B那个包里有各种各样的稀有材料。没有了它们，我和比提克斯就没有办法制造塞纳里奥要塞所需要的药剂了。我现在太虚弱，已经没有办法爬起来了，但是如果你可以把我的材料拿回来，那么我就可以帮你制作这些药剂。$B$B我是在南边山中碰到死亡弯钩的，就在铜须营地的后面。',Objectives_loc4='从希利苏斯南部山中找到诺格的背包，然后将它交给塞纳里奥要塞中的诺格。',OfferRewardText_loc4='太好了!你找回我的背包了。所有的稀有材料都在这里!我欠你很大一个人情。$B',RequestItemsText_loc4='还没找到我的包包吗?不过我已经很幸运了，至少毒药已经被净化过。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8283,'通缉：死亡弯钩','我们相信，可怕的蝎子“死亡弯钩”正在南面的山脉一带活动。对南边的巡逻士兵和远征军而言，她是个极大的威胁。谁能杀掉这个祸害，就将获得价值不菲的奖励。你可以向塞纳里奥要塞了望塔的卫兵队长维斯·库鲁兹询问奖励事宜。','将死亡弯钩的蝎钳交给卫兵队长维斯·库鲁兹。','太棒了!死亡弯钩一死，我们就能利用南部山脉的地势，智取异种虫巢。感谢你为此做出的努力。$B','我需要那个生物的刺针做为证据。没有刺针，没有奖励。') ON DUPLICATE KEY UPDATE Title_loc4='通缉：死亡弯钩',Details_loc4='我们相信，可怕的蝎子“死亡弯钩”正在南面的山脉一带活动。对南边的巡逻士兵和远征军而言，她是个极大的威胁。谁能杀掉这个祸害，就将获得价值不菲的奖励。你可以向塞纳里奥要塞了望塔的卫兵队长维斯·库鲁兹询问奖励事宜。',Objectives_loc4='将死亡弯钩的蝎钳交给卫兵队长维斯·库鲁兹。',OfferRewardText_loc4='太棒了!死亡弯钩一死，我们就能利用南部山脉的地势，智取异种虫巢。感谢你为此做出的努力。$B',RequestItemsText_loc4='我需要那个生物的刺针做为证据。没有刺针，没有奖励。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8284,'暮光的秘密','暮光之锤教徒曾在西北方进行发展。如果你现在去那里，还会发现那个区域到处都是元素生物，四周散落着的木头碎片和帆布可以帮你找到营地所在的地点。$B$B我从那里找回了一些粘土石板碎片，但是数量还不足以拼成有用的东西。如果你可以帮我找到其它的石板碎片，我们也许可以找到暮光之锤出现在希利苏斯的原因。','希利苏斯塞纳里奥要塞的地质学家拉克斯班要你去收集8块暮光石板碎片。','就和我怀疑的一样。我可以解译出石板上的所有文字，但是这些文字之间没有任何逻辑关系或者含义。现在还不知道暮光之锤究竟用了什么样的密码来掩盖这些文字的含义……我们必须找到一些更加了解这方面资讯的人。$B','那个荒芜的营地就在这里的西北方。拿到所有的碎片后再回来。') ON DUPLICATE KEY UPDATE Title_loc4='暮光的秘密',Details_loc4='暮光之锤教徒曾在西北方进行发展。如果你现在去那里，还会发现那个区域到处都是元素生物，四周散落着的木头碎片和帆布可以帮你找到营地所在的地点。$B$B我从那里找回了一些粘土石板碎片，但是数量还不足以拼成有用的东西。如果你可以帮我找到其它的石板碎片，我们也许可以找到暮光之锤出现在希利苏斯的原因。',Objectives_loc4='希利苏斯塞纳里奥要塞的地质学家拉克斯班要你去收集8块暮光石板碎片。',OfferRewardText_loc4='就和我怀疑的一样。我可以解译出石板上的所有文字，但是这些文字之间没有任何逻辑关系或者含义。现在还不知道暮光之锤究竟用了什么样的密码来掩盖这些文字的含义……我们必须找到一些更加了解这方面资讯的人。$B',RequestItemsText_loc4='那个荒芜的营地就在这里的西北方。拿到所有的碎片后再回来。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8285,'沙漠隐士','传说有一个前暮光之锤成员奥泰尔离开了这个团体，听说他现在隐居在南风村。也许你可以在那里寻求关于破译这块石板的帮助。$B$B带上这块拼好的石板，找到奥泰尔吧。','把复原的石板带给希利苏斯的隐士奥泰尔。','看来你对我以前所属的组织十分熟悉，你一定是塞纳里奥议会派来的。$B$B你想要找到对抗暮光之锤的资讯?过来，也许我们可以互帮互助。$B','你!你怎么找到我的?你是谁?没人跟着你来吧，有吗?说话!') ON DUPLICATE KEY UPDATE Title_loc4='沙漠隐士',Details_loc4='传说有一个前暮光之锤成员奥泰尔离开了这个团体，听说他现在隐居在南风村。也许你可以在那里寻求关于破译这块石板的帮助。$B$B带上这块拼好的石板，找到奥泰尔吧。',Objectives_loc4='把复原的石板带给希利苏斯的隐士奥泰尔。',OfferRewardText_loc4='看来你对我以前所属的组织十分熟悉，你一定是塞纳里奥议会派来的。$B$B你想要找到对抗暮光之锤的资讯?过来，也许我们可以互帮互助。$B',RequestItemsText_loc4='你!你怎么找到我的?你是谁?没人跟着你来吧，有吗?说话!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,EndText_loc4) VALUES (8286,'明天的希望','当他出现时，我已经奄奄一息，濒临死亡。他对着我受伤的身体呼了一口气，便耐心地等待着时间的沙砾清理我的伤口。$B$B他说，“如果必须这样的话，你将永远活下去。”这样，我成为了一名守望者。$B$B看那片沙漠，第二场战争就要来临了。你必须找到青铜龙的栖身之所。去时光之穴看看主人回来了没有。我必须确认这一点才能有所行动。','前往塔纳利斯的时光之穴寻找诺兹多姆的子嗣，阿纳克洛斯。$B$B完成任务后回到希利苏斯塞纳里奥要塞的流沙守望者巴里斯托尔斯那儿。','我担心的事情还是发生了。新的危机已经来临。我的守护工作结束了……$B','阿纳克洛斯回来了吗?','发现诺兹多姆的子嗣。') ON DUPLICATE KEY UPDATE Title_loc4='明天的希望',Details_loc4='当他出现时，我已经奄奄一息，濒临死亡。他对着我受伤的身体呼了一口气，便耐心地等待着时间的沙砾清理我的伤口。$B$B他说，“如果必须这样的话，你将永远活下去。”这样，我成为了一名守望者。$B$B看那片沙漠，第二场战争就要来临了。你必须找到青铜龙的栖身之所。去时光之穴看看主人回来了没有。我必须确认这一点才能有所行动。',Objectives_loc4='前往塔纳利斯的时光之穴寻找诺兹多姆的子嗣，阿纳克洛斯。$B$B完成任务后回到希利苏斯塞纳里奥要塞的流沙守望者巴里斯托尔斯那儿。',OfferRewardText_loc4='我担心的事情还是发生了。新的危机已经来临。我的守护工作结束了……$B',RequestItemsText_loc4='阿纳克洛斯回来了吗?',EndText_loc4='发现诺兹多姆的子嗣。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8287,'摆脱困境','嗯，是这样的……我这里有相当有用的信息！我看到塞纳里奥议会的人来到了希利苏斯。他们计划把暮光之锤赶出这个地区，是不是？这很好；$B$B把这块羊皮纸袋给他们的领袖，指挥官玛尔利斯。不久之后暮光之锤就会被消灭，然后我就将永远脱离他们的魔爪！','把解密石板碑文交给指挥官玛尔利斯。','这确实是非常有趣的资讯，$N。它说明了暮光之锤出现在希利苏斯的部分原因，无疑这将帮助我们更好地和他们进行战斗。你的努力将获得丰厚的回报，$C。$B','你带给我的是什么, $N?') ON DUPLICATE KEY UPDATE Title_loc4='摆脱困境',Details_loc4='嗯，是这样的……我这里有相当有用的信息！我看到塞纳里奥议会的人来到了希利苏斯。他们计划把暮光之锤赶出这个地区，是不是？这很好；$B$B把这块羊皮纸袋给他们的领袖，指挥官玛尔利斯。不久之后暮光之锤就会被消灭，然后我就将永远脱离他们的魔爪！',Objectives_loc4='把解密石板碑文交给指挥官玛尔利斯。',OfferRewardText_loc4='这确实是非常有趣的资讯，$N。它说明了暮光之锤出现在希利苏斯的部分原因，无疑这将帮助我们更好地和他们进行战斗。你的努力将获得丰厚的回报，$C。$B',RequestItemsText_loc4='你带给我的是什么, $N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8288,'唯一的领袖','不要浪费时间了!一定要找到一个英雄!我给的任务需要一个军队来完成，但是只有其中一个人会是优胜者，而他将接下身为龙族盟友的重担和责任。$B$B黑石领主的巢穴里有一只最残暴的野兽。勒西雷尔守卫着征战大厅，阻挡通往奈法利安的核心密室之路。杀死那个肮脏的怪物并带着他的头颅回来找我。完成之后你就可以展开旅途的下一步骤。','带着勒西雷尔的头颅回到希利苏斯，到塞纳里奥城堡的流沙之地找巴里斯托尔斯。','你就是千年以来首位赢得青铜龙青睐的凡人吗?$B','你必须赢得诺兹多姆的子嗣的好感。') ON DUPLICATE KEY UPDATE Title_loc4='唯一的领袖',Details_loc4='不要浪费时间了!一定要找到一个英雄!我给的任务需要一个军队来完成，但是只有其中一个人会是优胜者，而他将接下身为龙族盟友的重担和责任。$B$B黑石领主的巢穴里有一只最残暴的野兽。勒西雷尔守卫着征战大厅，阻挡通往奈法利安的核心密室之路。杀死那个肮脏的怪物并带着他的头颅回来找我。完成之后你就可以展开旅途的下一步骤。',Objectives_loc4='带着勒西雷尔的头颅回到希利苏斯，到塞纳里奥城堡的流沙之地找巴里斯托尔斯。',OfferRewardText_loc4='你就是千年以来首位赢得青铜龙青睐的凡人吗?$B',RequestItemsText_loc4='你必须赢得诺兹多姆的子嗣的好感。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8289,'功勋奖章','谢谢你，$N。你在战歌峡谷中的威名已经传遍了灰谷森林。','你已经证明了自己在战歌峡谷中的价值!继续帮助我们作战，并给我带来更多的功勋奖章。我们会因此而更加信任你。') ON DUPLICATE KEY UPDATE Title_loc4='功勋奖章',OfferRewardText_loc4='谢谢你，$N。你在战歌峡谷中的威名已经传遍了灰谷森林。',RequestItemsText_loc4='你已经证明了自己在战歌峡谷中的价值!继续帮助我们作战，并给我带来更多的功勋奖章。我们会因此而更加信任你。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8290,'击败入侵者！ (PvP)','在这个通道的另一端，你会看到一片战火纷飞的土地，年轻的$C。部落不断侵入我们神圣的森林，锯断这里的苍天古树来建造他们的战争机器。$B$B进入战歌峡谷，帮助银翼要塞击败入侵的部落势力，并赢得一枚功勋奖章吧。把这样的奖章给我拿来，你就将获得奖赏。','进入战歌峡谷抵御部落小队的攻击，获得一枚银翼功勋奖章，然后向银翼树林中的哨兵艾蒂亚·轻歌回复。','银翼哨兵部队感谢你的贡献，$C。我们和战歌先遣骑的战斗远未结束，但是你的胜利一定可以减缓他们建造战争机器的速度─即使只是减缓一小会儿。','银翼要塞那边有什么消息吗?你有没有击败战歌氏族的部队?') ON DUPLICATE KEY UPDATE Title_loc4='击败入侵者！ (PvP)',Details_loc4='在这个通道的另一端，你会看到一片战火纷飞的土地，年轻的$C。部落不断侵入我们神圣的森林，锯断这里的苍天古树来建造他们的战争机器。$B$B进入战歌峡谷，帮助银翼要塞击败入侵的部落势力，并赢得一枚功勋奖章吧。把这样的奖章给我拿来，你就将获得奖赏。',Objectives_loc4='进入战歌峡谷抵御部落小队的攻击，获得一枚银翼功勋奖章，然后向银翼树林中的哨兵艾蒂亚·轻歌回复。',OfferRewardText_loc4='银翼哨兵部队感谢你的贡献，$C。我们和战歌先遣骑的战斗远未结束，但是你的胜利一定可以减缓他们建造战争机器的速度─即使只是减缓一小会儿。',RequestItemsText_loc4='银翼要塞那边有什么消息吗?你有没有击败战歌氏族的部队?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8291,'击败入侵者!','在这个通道的另一端，你会看到一片战火纷飞的土地，年轻的$C。部落不断侵入我们神圣的森林，锯断这里的苍天古树来建造他们的战争机器。$B$B进入战歌峡谷，帮助银翼要塞击败入侵的部落势力，并赢得一枚功勋奖章吧。把这样的奖章给我拿来，你就将获得奖赏。','进入战歌峡谷抵御部落小队的攻击，获得一枚银翼功勋奖章，然后向银翼树林中的哨兵艾蒂亚·轻歌回复。','银翼哨兵部队感谢你的贡献，$C。我们和战歌先遣骑的战斗远未结束，但是你的胜利一定可以减缓他们建造战争机器的速度─即使只是减缓一小会儿。','银翼要塞那边有什么消息吗?你有没有击败战歌氏族的部队，拿到你的功勋奖章?') ON DUPLICATE KEY UPDATE Title_loc4='击败入侵者!',Details_loc4='在这个通道的另一端，你会看到一片战火纷飞的土地，年轻的$C。部落不断侵入我们神圣的森林，锯断这里的苍天古树来建造他们的战争机器。$B$B进入战歌峡谷，帮助银翼要塞击败入侵的部落势力，并赢得一枚功勋奖章吧。把这样的奖章给我拿来，你就将获得奖赏。',Objectives_loc4='进入战歌峡谷抵御部落小队的攻击，获得一枚银翼功勋奖章，然后向银翼树林中的哨兵艾蒂亚·轻歌回复。',OfferRewardText_loc4='银翼哨兵部队感谢你的贡献，$C。我们和战歌先遣骑的战斗远未结束，但是你的胜利一定可以减缓他们建造战争机器的速度─即使只是减缓一小会儿。',RequestItemsText_loc4='银翼要塞那边有什么消息吗?你有没有击败战歌氏族的部队，拿到你的功勋奖章?';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8292,'功勋奖章','谢谢你，$N。你在战歌峡谷中的威名已经传遍了灰谷森林。','你已经证明了自己在战歌峡谷中的价值!继续帮助我们作战，并给我带来更多的功勋奖章。我们会因此而更加信任你。') ON DUPLICATE KEY UPDATE Title_loc4='功勋奖章',OfferRewardText_loc4='谢谢你，$N。你在战歌峡谷中的威名已经传遍了灰谷森林。',RequestItemsText_loc4='你已经证明了自己在战歌峡谷中的价值!继续帮助我们作战，并给我带来更多的功勋奖章。我们会因此而更加信任你。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8293,'荣誉奖章','暗夜精灵和他们的盟友听到你的名字就会吓得发抖!为部落而战!','你已经证明了自己在战歌峡谷中的价值!继续攻打银翼要塞的哨兵部队，给我带来更多的功勋奖章!') ON DUPLICATE KEY UPDATE Title_loc4='荣誉奖章',OfferRewardText_loc4='暗夜精灵和他们的盟友听到你的名字就会吓得发抖!为部落而战!',RequestItemsText_loc4='你已经证明了自己在战歌峡谷中的价值!继续攻打银翼要塞的哨兵部队，给我带来更多的功勋奖章!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8294,'镇压银翼部队','灰谷森林将在强大的部落面前屈服，$R。无论暗夜精灵们说什么做什么，都无法阻止我们的推进。卡利姆多属于部落，谁敢阻止我们拿取属于我们的东西，谁就要死！$B$B让你的心中充满荣耀之光，让那些胆敢阻止我们的敌人一个个倒下。摧毁银翼要塞中的哨兵部队，并拿到一枚战歌荣誉奖章。把这样一枚奖章给我拿来，你就可以获得奖赏。','进入战歌峡谷击败联盟小队，获得一枚战歌荣誉奖章，然后向莫尔杉营地的沙塔尔·碎颅复命。','<沙塔尔.碎颅发出兴奋的怒吼。>$B$B他们还能支撑多久?还要牺牲多少联盟的渣滓才能让他们退却?只有时间可以说明一切，$r……','敌人的鲜血就是我们的荣耀，你干得很出色。') ON DUPLICATE KEY UPDATE Title_loc4='镇压银翼部队',Details_loc4='灰谷森林将在强大的部落面前屈服，$R。无论暗夜精灵们说什么做什么，都无法阻止我们的推进。卡利姆多属于部落，谁敢阻止我们拿取属于我们的东西，谁就要死！$B$B让你的心中充满荣耀之光，让那些胆敢阻止我们的敌人一个个倒下。摧毁银翼要塞中的哨兵部队，并拿到一枚战歌荣誉奖章。把这样一枚奖章给我拿来，你就可以获得奖赏。',Objectives_loc4='进入战歌峡谷击败联盟小队，获得一枚战歌荣誉奖章，然后向莫尔杉营地的沙塔尔·碎颅复命。',OfferRewardText_loc4='<沙塔尔.碎颅发出兴奋的怒吼。>$B$B他们还能支撑多久?还要牺牲多少联盟的渣滓才能让他们退却?只有时间可以说明一切，$r……',RequestItemsText_loc4='敌人的鲜血就是我们的荣耀，你干得很出色。';
