INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8383,'铭记奥特兰克！','你为联盟不断带来荣耀，$N。如果我们继续努力的话，部落迟早会被我们击垮的。','奥特兰克山谷的战斗正在激烈地进行中，$N!你有没有完成你应尽的职责，$N?') ON DUPLICATE KEY UPDATE Title_loc4='铭记奥特兰克！',OfferRewardText_loc4='你为联盟不断带来荣耀，$N。如果我们继续努力的话，部落迟早会被我们击垮的。',RequestItemsText_loc4='奥特兰克山谷的战斗正在激烈地进行中，$N!你有没有完成你应尽的职责，$N?';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8384,'占领阿拉希盆地','太棒了，$C!你为联盟提供了急需的战争物资。$B','与部落的激战很快耗尽了我们的资源，$N。掌握阿拉希盆地的控制权对维系战争物资的补给相当重要!你前往阿拉希伸出援手了吗?') ON DUPLICATE KEY UPDATE Title_loc4='占领阿拉希盆地',OfferRewardText_loc4='太棒了，$C!你为联盟提供了急需的战争物资。$B',RequestItemsText_loc4='与部落的激战很快耗尽了我们的资源，$N。掌握阿拉希盆地的控制权对维系战争物资的补给相当重要!你前往阿拉希伸出援手了吗?';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8385,'共同的努力','你的声名远播，$N。如果没有你这样的$C，联盟将无法对抗部落的野蛮攻击。$B','啊，$N。我希望你在各个战场的前线传授你的经验。许多刚刚来到战场上的小夥子和小姑娘都非常尊敬你这样的老兵。') ON DUPLICATE KEY UPDATE Title_loc4='共同的努力',OfferRewardText_loc4='你的声名远播，$N。如果没有你这样的$C，联盟将无法对抗部落的野蛮攻击。$B',RequestItemsText_loc4='啊，$N。我希望你在各个战场的前线传授你的经验。许多刚刚来到战场上的小夥子和小姑娘都非常尊敬你这样的老兵。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8386,'战歌峡谷之战','干得好，$N。感谢你，我们在灰谷的自然屏障又能安稳地度过一天了。$B','不要忘记，在战歌峡谷中进行战斗不止是为了保护森林，更重要的是我们在保护灰谷和贫瘠之地之间的自然屏障。你有没有从战场带回什么消息，$N?') ON DUPLICATE KEY UPDATE Title_loc4='战歌峡谷之战',OfferRewardText_loc4='干得好，$N。感谢你，我们在灰谷的自然屏障又能安稳地度过一天了。$B',RequestItemsText_loc4='不要忘记，在战歌峡谷中进行战斗不止是为了保护森林，更重要的是我们在保护灰谷和贫瘠之地之间的自然屏障。你有没有从战场带回什么消息，$N?';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8387,'奥特兰克的入侵者','干得好，$N!你应该为自己感到骄傲。联盟入侵者必将被赶出奥特兰克!$B','奥特兰克山谷的战斗正在激烈地进行中!你必须回到奥特兰克山谷，把入侵者赶出霜狼氏族的领地，$N!') ON DUPLICATE KEY UPDATE Title_loc4='奥特兰克的入侵者',OfferRewardText_loc4='干得好，$N!你应该为自己感到骄傲。联盟入侵者必将被赶出奥特兰克!$B',RequestItemsText_loc4='奥特兰克山谷的战斗正在激烈地进行中!你必须回到奥特兰克山谷，把入侵者赶出霜狼氏族的领地，$N!';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8388,'无上的荣耀','你继续为部落带来荣耀，$N。我很高兴看到你还是一样的坚强。$B','许多勇敢的士兵都非常尊敬你，$N。你一直是那些和联盟艰苦作战的勇士的榜样。你从旅途中带回了什么消息?') ON DUPLICATE KEY UPDATE Title_loc4='无上的荣耀',OfferRewardText_loc4='你继续为部落带来荣耀，$N。我很高兴看到你还是一样的坚强。$B',RequestItemsText_loc4='许多勇敢的士兵都非常尊敬你，$N。你一直是那些和联盟艰苦作战的勇士的榜样。你从旅途中带回了什么消息?';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8389,'峡谷中的战斗','干得好，$C!在你的帮助下，部落取得了战歌峡谷的胜利!$B','战歌峡谷的战事趋於白热化，$N。尽你的努力将银翼哨兵驱逐出我们的土地!') ON DUPLICATE KEY UPDATE Title_loc4='峡谷中的战斗',OfferRewardText_loc4='干得好，$C!在你的帮助下，部落取得了战歌峡谷的胜利!$B',RequestItemsText_loc4='战歌峡谷的战事趋於白热化，$N。尽你的努力将银翼哨兵驱逐出我们的土地!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8390,'资源竞赛','我们和联盟的冲突已经上升为一场真正的战争，不久之后战争就将全面打响。$B$B对于阿拉希盆地的争夺就是一个很好的开战理由。要么就是联盟占据它，并用其对付我们；或者就是我们占据它，然后用来对付联盟。帮助污染者保持这场资源竞赛上的优势吧，$N！','将3枚阿拉希盆地荣誉奖章交给战场外的部落战争使者。','干得好，$N!只要阿拉希盆地在我们的控制之下，那么我们就可以源源不断地获得补给。$B','我们要对付那些想要抢夺我们资源的联盟废渣，$N!我们不允许战争中有物资短缺的情形。继续努力，确保阿拉希盆地掌握在我们手中!') ON DUPLICATE KEY UPDATE Title_loc4='资源竞赛',Details_loc4='我们和联盟的冲突已经上升为一场真正的战争，不久之后战争就将全面打响。$B$B对于阿拉希盆地的争夺就是一个很好的开战理由。要么就是联盟占据它，并用其对付我们；或者就是我们占据它，然后用来对付联盟。帮助污染者保持这场资源竞赛上的优势吧，$N！',Objectives_loc4='将3枚阿拉希盆地荣誉奖章交给战场外的部落战争使者。',OfferRewardText_loc4='干得好，$N!只要阿拉希盆地在我们的控制之下，那么我们就可以源源不断地获得补给。$B',RequestItemsText_loc4='我们要对付那些想要抢夺我们资源的联盟废渣，$N!我们不允许战争中有物资短缺的情形。继续努力，确保阿拉希盆地掌握在我们手中!';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8391,'占领阿拉希盆地','太棒了，$C!你为联盟提供了急需的战争物资。$B','与部落的激战很快耗尽了我们的资源，$N。掌握阿拉希盆地的控制权对维系战争物资的补给相当重要!你前往阿拉希伸出援手了吗?') ON DUPLICATE KEY UPDATE Title_loc4='占领阿拉希盆地',OfferRewardText_loc4='太棒了，$C!你为联盟提供了急需的战争物资。$B',RequestItemsText_loc4='与部落的激战很快耗尽了我们的资源，$N。掌握阿拉希盆地的控制权对维系战争物资的补给相当重要!你前往阿拉希伸出援手了吗?';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8392,'占领阿拉希盆地','太棒了，$C!你为联盟提供了急需的战争物资。$B','与部落的激战很快耗尽了我们的资源，$N。掌握阿拉希盆地的控制权对维系战争物资的补给相当重要!你前往阿拉希伸出援手了吗?') ON DUPLICATE KEY UPDATE Title_loc4='占领阿拉希盆地',OfferRewardText_loc4='太棒了，$C!你为联盟提供了急需的战争物资。$B',RequestItemsText_loc4='与部落的激战很快耗尽了我们的资源，$N。掌握阿拉希盆地的控制权对维系战争物资的补给相当重要!你前往阿拉希伸出援手了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8393,'战争的动力','要取得战争的胜利，我们要做的并不仅仅是简单地打败敌人，胜利的关键往往取决于双方的战争资源。$B$B阿拉希盆地蕴藏着大量物资，部落和联盟都想抢先夺取这些资源。$B$B如果联盟获胜，我们的军队将获得大量的剑和矛。如果部落获胜，这些武器也一样会被造出来，只不过是由部落的士兵拿在手里，指着我们！去帮助阿拉希盆地的联盟吧，$N。','将3枚阿拉希盆地荣誉奖章交给战场外的联盟准将。','干得好，士兵!继续保持下去，部落终将被我们赶回奥格玛。$B','告诉我，前线那边有什么消息吗?') ON DUPLICATE KEY UPDATE Title_loc4='战争的动力',Details_loc4='要取得战争的胜利，我们要做的并不仅仅是简单地打败敌人，胜利的关键往往取决于双方的战争资源。$B$B阿拉希盆地蕴藏着大量物资，部落和联盟都想抢先夺取这些资源。$B$B如果联盟获胜，我们的军队将获得大量的剑和矛。如果部落获胜，这些武器也一样会被造出来，只不过是由部落的士兵拿在手里，指着我们！去帮助阿拉希盆地的联盟吧，$N。',Objectives_loc4='将3枚阿拉希盆地荣誉奖章交给战场外的联盟准将。',OfferRewardText_loc4='干得好，士兵!继续保持下去，部落终将被我们赶回奥格玛。$B',RequestItemsText_loc4='告诉我，前线那边有什么消息吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8394,'战争的动力','要取得战争的胜利，我们要做的并不仅仅是简单地打败敌人，胜利的关键往往取决于双方的战争资源。$B$B阿拉希盆地蕴藏着大量物资，部落和联盟都想抢先夺取这些资源。$B$B如果联盟获胜，我们的军队将获得大量的剑和矛。如果部落获胜，这些武器也一样会被造出来，只不过是由部落的士兵拿在手里，指着我们！去帮助阿拉希盆地的联盟吧，$N。','将3枚阿拉希盆地荣誉奖章交给战场外的联盟准将。','干得好，士兵!继续保持下去，部落终将被我们赶回奥格玛。$B','告诉我，前线那边有什么消息吗?') ON DUPLICATE KEY UPDATE Title_loc4='战争的动力',Details_loc4='要取得战争的胜利，我们要做的并不仅仅是简单地打败敌人，胜利的关键往往取决于双方的战争资源。$B$B阿拉希盆地蕴藏着大量物资，部落和联盟都想抢先夺取这些资源。$B$B如果联盟获胜，我们的军队将获得大量的剑和矛。如果部落获胜，这些武器也一样会被造出来，只不过是由部落的士兵拿在手里，指着我们！去帮助阿拉希盆地的联盟吧，$N。',Objectives_loc4='将3枚阿拉希盆地荣誉奖章交给战场外的联盟准将。',OfferRewardText_loc4='干得好，士兵!继续保持下去，部落终将被我们赶回奥格玛。$B',RequestItemsText_loc4='告诉我，前线那边有什么消息吗?';
