INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8397,'占领阿拉希盆地','太棒了，$C!你为联盟提供了急需的战争物资。$B','与部落的激战很快耗尽了我们的资源，$N。掌握阿拉希盆地的控制权对维系战争物资的补给相当重要!你前往阿拉希伸出援手了吗?') ON DUPLICATE KEY UPDATE Title_loc4='占领阿拉希盆地',OfferRewardText_loc4='太棒了，$C!你为联盟提供了急需的战争物资。$B',RequestItemsText_loc4='与部落的激战很快耗尽了我们的资源，$N。掌握阿拉希盆地的控制权对维系战争物资的补给相当重要!你前往阿拉希伸出援手了吗?';
