INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8408,'战歌峡谷之战','干得好，$N。感谢你，我们在灰谷的自然屏障又能安稳地度过一天了。$B','不要忘记，在战歌峡谷中进行战斗不止是为了保护森林，更重要的是我们在保护灰谷和贫瘠之地之间的自然屏障。你有没有从战场带回什么消息，$N?') ON DUPLICATE KEY UPDATE Title_loc4='战歌峡谷之战',OfferRewardText_loc4='干得好，$N。感谢你，我们在灰谷的自然屏障又能安稳地度过一天了。$B',RequestItemsText_loc4='不要忘记，在战歌峡谷中进行战斗不止是为了保护森林，更重要的是我们在保护灰谷和贫瘠之地之间的自然屏障。你有没有从战场带回什么消息，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (8409,'恶臭的鸡蛋','腐烂的蛋已经被放进了桶里。以后南海镇旅馆出产的酒肯定都是次品了！$B$B你现在应该回提瑞斯法林地向黑暗召唤者雅恩卡报告你的成功。','向提瑞斯法林地的黑暗召唤者雅恩卡复命。','啊，你成功了!我要说的是，你展现了万鬼节的精神─被遗忘者的精神!$B$B<黑暗召唤者雅恩卡搓着手大笑着。>$B$B现在南海镇没有美味的麦芽酒喝了，我为此要庆祝一番!至于你，收下这些礼物。你会发现其中必定有有用的东西!') ON DUPLICATE KEY UPDATE Title_loc4='恶臭的鸡蛋',Details_loc4='腐烂的蛋已经被放进了桶里。以后南海镇旅馆出产的酒肯定都是次品了！$B$B你现在应该回提瑞斯法林地向黑暗召唤者雅恩卡报告你的成功。',Objectives_loc4='向提瑞斯法林地的黑暗召唤者雅恩卡复命。',OfferRewardText_loc4='啊，你成功了!我要说的是，你展现了万鬼节的精神─被遗忘者的精神!$B$B<黑暗召唤者雅恩卡搓着手大笑着。>$B$B现在南海镇没有美味的麦芽酒喝了，我为此要庆祝一番!至于你，收下这些礼物。你会发现其中必定有有用的东西!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8410,'元素掌握','捕风者巴斯拉需要你这样充满智慧的萨满祭司。他要你带上每种元素的样本，证明你已准备就绪。$B$B你可以沿着塔伦米尔以东的河流往北走，巴斯拉就居住在沿途的一处废墟中。','为捕风者巴斯拉收集一份空气样本、一份火元素样本、一份土元素样本和一份水元素样本。','太棒了。我们谈谈吧。$B','你为我带来了什么东西，$C?') ON DUPLICATE KEY UPDATE Title_loc4='元素掌握',Details_loc4='捕风者巴斯拉需要你这样充满智慧的萨满祭司。他要你带上每种元素的样本，证明你已准备就绪。$B$B你可以沿着塔伦米尔以东的河流往北走，巴斯拉就居住在沿途的一处废墟中。',Objectives_loc4='为捕风者巴斯拉收集一份空气样本、一份火元素样本、一份土元素样本和一份水元素样本。',OfferRewardText_loc4='太棒了。我们谈谈吧。$B',RequestItemsText_loc4='你为我带来了什么东西，$C?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8411,'控制元素','欢迎。把元素交给我，然后我们谈谈。','将土元素、空气元素、火元素和水元素交给捕风者巴斯拉。','这些是我需要的元素。我们谈谈吧。','元素在那?') ON DUPLICATE KEY UPDATE Title_loc4='控制元素',Details_loc4='欢迎。把元素交给我，然后我们谈谈。',Objectives_loc4='将土元素、空气元素、火元素和水元素交给捕风者巴斯拉。',OfferRewardText_loc4='这些是我需要的元素。我们谈谈吧。',RequestItemsText_loc4='元素在那?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8412,'灵魂图腾','这地方的元素灵魂不再欢迎我了。$B$B我们都熟悉图腾，现在我需要灵魂图腾来保护自己。它由四种元素和一些更原始、更接近自然的材料构成。$B$B你可以去西瘟疫之地获取熊爪和蜘蛛的眼球，另外有时食腐的鸟类也会掉落这两种东西中的任何一种，这取决于它们上一顿吃了什么东西……去吧，$N。','将灵魂图腾所需的材料交给捕风者巴斯拉。','太棒了，老兄!我们试试吧……$B','灵魂们很清楚我们在干嘛，他们想要杀了我!我希望你能取得材料。') ON DUPLICATE KEY UPDATE Title_loc4='灵魂图腾',Details_loc4='这地方的元素灵魂不再欢迎我了。$B$B我们都熟悉图腾，现在我需要灵魂图腾来保护自己。它由四种元素和一些更原始、更接近自然的材料构成。$B$B你可以去西瘟疫之地获取熊爪和蜘蛛的眼球，另外有时食腐的鸟类也会掉落这两种东西中的任何一种，这取决于它们上一顿吃了什么东西……去吧，$N。',Objectives_loc4='将灵魂图腾所需的材料交给捕风者巴斯拉。',OfferRewardText_loc4='太棒了，老兄!我们试试吧……$B',RequestItemsText_loc4='灵魂们很清楚我们在干嘛，他们想要杀了我!我希望你能取得材料。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8413,'巫毒羽毛','灵魂图腾还不够。我们还需要一些巫毒魔法来让它发挥效力。$B$B沉没的神庙中的巨魔身上有巫毒羽毛。去杀掉加什尔、米杉、祖罗、胡库、祖罗尔和洛若尔。这样我们就能拥有一个真正的、具有魔法力量的灵魂图腾了。','将巫毒羽毛交给捕风者巴斯拉。','现在，巨魔能好好睡个觉了!灵魂图腾会保护我的。$B$B我花了很多时间才收集到这些东西，或许你也想要一根图腾?$B','羽毛在那?') ON DUPLICATE KEY UPDATE Title_loc4='巫毒羽毛',Details_loc4='灵魂图腾还不够。我们还需要一些巫毒魔法来让它发挥效力。$B$B沉没的神庙中的巨魔身上有巫毒羽毛。去杀掉加什尔、米杉、祖罗、胡库、祖罗尔和洛若尔。这样我们就能拥有一个真正的、具有魔法力量的灵魂图腾了。',Objectives_loc4='将巫毒羽毛交给捕风者巴斯拉。',OfferRewardText_loc4='现在，巨魔能好好睡个觉了!灵魂图腾会保护我的。$B$B我花了很多时间才收集到这些东西，或许你也想要一根图腾?$B',RequestItemsText_loc4='羽毛在那?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8414,'驱散邪恶','你好，$C。在这片荒无人烟的土地上，像你这样的十字军是受到欢迎的。$B$B我们需要借助你神圣的力量来消灭这里无穷无尽的亡灵。更重要的是，我们想让你收集大量的天灾石，将它们交给高阶牧师赛尔丹尼斯。赛尔丹尼斯就在距离此地不远的悔恨岭守护乌瑟尔之墓。$B$B只有佩戴银色黎明委任徽章的人可以找到天灾石，如果你没有徽章的话，就去跟军官普尔哈特谈谈吧。','收集20个爪牙的天灾石，并将它们交给西瘟疫之地的高阶牧师赛尔丹尼斯。','驱散天谴石的邪恶力量是有风险的，就算在万里之遥，它也能跟不死族有所感应。但是你拥有如此强大的力量，$N，我并不你担心……$B','你带给我什么邪恶的东西?') ON DUPLICATE KEY UPDATE Title_loc4='驱散邪恶',Details_loc4='你好，$C。在这片荒无人烟的土地上，像你这样的十字军是受到欢迎的。$B$B我们需要借助你神圣的力量来消灭这里无穷无尽的亡灵。更重要的是，我们想让你收集大量的天灾石，将它们交给高阶牧师赛尔丹尼斯。赛尔丹尼斯就在距离此地不远的悔恨岭守护乌瑟尔之墓。$B$B只有佩戴银色黎明委任徽章的人可以找到天灾石，如果你没有徽章的话，就去跟军官普尔哈特谈谈吧。',Objectives_loc4='收集20个爪牙的天灾石，并将它们交给西瘟疫之地的高阶牧师赛尔丹尼斯。',OfferRewardText_loc4='驱散天谴石的邪恶力量是有风险的，就算在万里之遥，它也能跟不死族有所感应。但是你拥有如此强大的力量，$N，我并不你担心……$B',RequestItemsText_loc4='你带给我什么邪恶的东西?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8415,'冰风岗','指挥官阿什拉姆·瓦罗菲斯特需要你这样纯洁和勇敢的圣骑士，$N。你可以在西瘟疫之地南部的冰风岗找到他。以圣光的名义，去帮助他吧！','与冰风岗的指挥官阿什拉姆·瓦罗菲斯特谈一谈。','很好，$C!让我们看看你的力量。','只有圣骑士能承担我给予的任务。你就是我要找的人吗? ') ON DUPLICATE KEY UPDATE Title_loc4='冰风岗',Details_loc4='指挥官阿什拉姆·瓦罗菲斯特需要你这样纯洁和勇敢的圣骑士，$N。你可以在西瘟疫之地南部的冰风岗找到他。以圣光的名义，去帮助他吧！',Objectives_loc4='与冰风岗的指挥官阿什拉姆·瓦罗菲斯特谈一谈。',OfferRewardText_loc4='很好，$C!让我们看看你的力量。',RequestItemsText_loc4='只有圣骑士能承担我给予的任务。你就是我要找的人吗? ';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8416,'惰性天灾石','天灾石上的邪恶力量已经被清除了，$N。$B$B我了解指挥官阿什拉姆的计划，他还需要一块惰性天灾石。把惰性天灾石带给他，或许我们就能以正义之火消灭亡灵天灾。','将惰性天灾石交给冰风岗的指挥官阿什拉姆·瓦罗菲斯特。','你成功地完成了我交给你的任务，$N。$B$B你赢得了我的信任。或许现在我可以告诉你更多计划的详细信息了。$B','赛尔丹尼斯净化了天灾石吗?') ON DUPLICATE KEY UPDATE Title_loc4='惰性天灾石',Details_loc4='天灾石上的邪恶力量已经被清除了，$N。$B$B我了解指挥官阿什拉姆的计划，他还需要一块惰性天灾石。把惰性天灾石带给他，或许我们就能以正义之火消灭亡灵天灾。',Objectives_loc4='将惰性天灾石交给冰风岗的指挥官阿什拉姆·瓦罗菲斯特。',OfferRewardText_loc4='你成功地完成了我交给你的任务，$N。$B$B你赢得了我的信任。或许现在我可以告诉你更多计划的详细信息了。$B',RequestItemsText_loc4='赛尔丹尼斯净化了天灾石吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8417,'困扰的灵魂','在诅咒之地中有个受到困扰的灵魂，他生前曾是部落的一位伟大的英雄。战士的荣耀绝不会随着肉体的毁灭而消逝，如果可能的话，我希望你能帮帮他。','到诅咒之地的入口去，与部落英雄的灵魂谈一谈。','这么说，你是来解除我的痛苦的。希望这和打败我一样简单，但显然它不是……$B','我对你很感兴趣，$C。你为什么来到这里?') ON DUPLICATE KEY UPDATE Title_loc4='困扰的灵魂',Details_loc4='在诅咒之地中有个受到困扰的灵魂，他生前曾是部落的一位伟大的英雄。战士的荣耀绝不会随着肉体的毁灭而消逝，如果可能的话，我希望你能帮帮他。',Objectives_loc4='到诅咒之地的入口去，与部落英雄的灵魂谈一谈。',OfferRewardText_loc4='这么说，你是来解除我的痛苦的。希望这和打败我一样简单，但显然它不是……$B',RequestItemsText_loc4='我对你很感兴趣，$C。你为什么来到这里?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8418,'铸造力量之石','现在我们必须把惰性天灾石组合起来，制造一件可以击溃亡灵的武器。这不是一件轻松的任务，$n。只有沉没的神庙中的那些巨魔身上携带着的魔法才拥有这种力量，正所谓以毒攻毒。。$B$B我需要沉没的神庙里那些巨魔的巫毒羽毛。加什尔、米杉、祖罗、胡库、祖罗尔和洛若尔会掉落巫毒羽毛。不要为他们感到难过……他们是极端邪恶的存在。','前往沉没的神庙，从巨魔守护者们身上取得巫毒羽毛，然后把它们交给阿什拉姆·瓦罗菲斯特。','太好了，$N。我有些吃惊，不过我知道你不会让我失望的。$B$B我很荣幸地将这块神圣力量之石交给你，好好使用它吧。$B','你把那些邪恶的巨魔杀死了吗?') ON DUPLICATE KEY UPDATE Title_loc4='铸造力量之石',Details_loc4='现在我们必须把惰性天灾石组合起来，制造一件可以击溃亡灵的武器。这不是一件轻松的任务，$n。只有沉没的神庙中的那些巨魔身上携带着的魔法才拥有这种力量，正所谓以毒攻毒。。$B$B我需要沉没的神庙里那些巨魔的巫毒羽毛。加什尔、米杉、祖罗、胡库、祖罗尔和洛若尔会掉落巫毒羽毛。不要为他们感到难过……他们是极端邪恶的存在。',Objectives_loc4='前往沉没的神庙，从巨魔守护者们身上取得巫毒羽毛，然后把它们交给阿什拉姆·瓦罗菲斯特。',OfferRewardText_loc4='太好了，$N。我有些吃惊，不过我知道你不会让我失望的。$B$B我很荣幸地将这块神圣力量之石交给你，好好使用它吧。$B',RequestItemsText_loc4='你把那些邪恶的巨魔杀死了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8419,'小鬼的要求','$N，费伍德森林有个名叫伊普斯的小鬼让你去见他。这听上去有些奇怪，因为他让你带上一块恶魔布作为忠实的象征。既然你已经是个强大的术士了，那我想不用说你也知道费伍德的萨特身上有时会带着恶魔布吧？$B$B你可以在血毒瀑布以北找到伊普斯，我听说这个季节血毒瀑布非常漂亮。','将一块恶魔布交给费伍德森林的伊普斯。','你是个很棒的$C!$B$B<伊普斯将恶魔布贴在脸上。>$B$B哦，我喜欢这感觉，那种轻微灼烧皮肤的感觉，那种往你的心灵注入邪恶力量的感觉……$B','你带来恶魔布了吗?') ON DUPLICATE KEY UPDATE Title_loc4='小鬼的要求',Details_loc4='$N，费伍德森林有个名叫伊普斯的小鬼让你去见他。这听上去有些奇怪，因为他让你带上一块恶魔布作为忠实的象征。既然你已经是个强大的术士了，那我想不用说你也知道费伍德的萨特身上有时会带着恶魔布吧？$B$B你可以在血毒瀑布以北找到伊普斯，我听说这个季节血毒瀑布非常漂亮。',Objectives_loc4='将一块恶魔布交给费伍德森林的伊普斯。',OfferRewardText_loc4='你是个很棒的$C!$B$B<伊普斯将恶魔布贴在脸上。>$B$B哦，我喜欢这感觉，那种轻微灼烧皮肤的感觉，那种往你的心灵注入邪恶力量的感觉……$B',RequestItemsText_loc4='你带来恶魔布了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8420,'灼热的疼痛','或许一个小鬼说这话有些奇怪，但是我希望拥有自己的宠物。尼比把我当作宠物，我却没有宠物，这不公平!$B$B事实上，我并不需要什么活的宠物。如果你能给我一块恶魔布的话，我就能制造一个宠物。这周围的萨特身上经常带着恶魔布，所以你可以去跟他们打打交道，你觉得如何?','将1块恶魔布交给费伍德森林的伊普斯。','啊!你真是太好了，尤其是对一个术士来说!$B$B<伊普斯将恶魔布贴在脸上。>$B$B哦，我喜欢这感觉，那种轻微灼烧皮肤的感觉，那种往你的心灵注入邪恶力量的感觉……$B','你带恶魔布来了吗?') ON DUPLICATE KEY UPDATE Title_loc4='灼热的疼痛',Details_loc4='或许一个小鬼说这话有些奇怪，但是我希望拥有自己的宠物。尼比把我当作宠物，我却没有宠物，这不公平!$B$B事实上，我并不需要什么活的宠物。如果你能给我一块恶魔布的话，我就能制造一个宠物。这周围的萨特身上经常带着恶魔布，所以你可以去跟他们打打交道，你觉得如何?',Objectives_loc4='将1块恶魔布交给费伍德森林的伊普斯。',OfferRewardText_loc4='啊!你真是太好了，尤其是对一个术士来说!$B$B<伊普斯将恶魔布贴在脸上。>$B$B哦，我喜欢这感觉，那种轻微灼烧皮肤的感觉，那种往你的心灵注入邪恶力量的感觉……$B',RequestItemsText_loc4='你带恶魔布来了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8421,'奇怪的材料','我已经有恶魔布啦，现在我可以开始制造*我的*宠物了。$B$B但是我还需要一些东西来制造宠物的眼睛。你能不能帮我从铁树上剥些腐烂的木头来？这样我才能雕刻出可爱的眼睛。我还需要血毒精华，让我的宠物具有恶魔的气息。被污染的软泥怪具有这种精华，他们就在我们附近出没。','将10块腐烂的木头和4个血毒精华交给费伍德森林的伊普斯。','这真是个好东西。$B','我要的东西你带来了吗?') ON DUPLICATE KEY UPDATE Title_loc4='奇怪的材料',Details_loc4='我已经有恶魔布啦，现在我可以开始制造*我的*宠物了。$B$B但是我还需要一些东西来制造宠物的眼睛。你能不能帮我从铁树上剥些腐烂的木头来？这样我才能雕刻出可爱的眼睛。我还需要血毒精华，让我的宠物具有恶魔的气息。被污染的软泥怪具有这种精华，他们就在我们附近出没。',Objectives_loc4='将10块腐烂的木头和4个血毒精华交给费伍德森林的伊普斯。',OfferRewardText_loc4='这真是个好东西。$B',RequestItemsText_loc4='我要的东西你带来了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8422,'巨魔的羽毛','我的宠物差不多要制作完成了。现在我需要一些填充物。$B$B我需要沉没的神庙里那些巨魔的巫毒羽毛。加什尔、米杉、祖罗、胡库、祖罗尔和洛若尔会掉落巫毒羽毛。干掉他们。全部。$B$B这项任务可不简单，$N，我会送你一些尼比的东西——反正他似乎也用不着。','到沉没的神庙去，从巨魔们身上获得6支巫毒羽毛。','太好了，我的宠物制作完成了!$B$B<伊普斯很快将玩偶填充好，紧紧抱住它。>$B$B啊，这些巫毒羽毛拥有多么神奇的力量啊……$B','你把羽毛带来了吗?这个玩偶需要填充物!') ON DUPLICATE KEY UPDATE Title_loc4='巨魔的羽毛',Details_loc4='我的宠物差不多要制作完成了。现在我需要一些填充物。$B$B我需要沉没的神庙里那些巨魔的巫毒羽毛。加什尔、米杉、祖罗、胡库、祖罗尔和洛若尔会掉落巫毒羽毛。干掉他们。全部。$B$B这项任务可不简单，$N，我会送你一些尼比的东西——反正他似乎也用不着。',Objectives_loc4='到沉没的神庙去，从巨魔们身上获得6支巫毒羽毛。',OfferRewardText_loc4='太好了，我的宠物制作完成了!$B$B<伊普斯很快将玩偶填充好，紧紧抱住它。>$B$B啊，这些巫毒羽毛拥有多么神奇的力量啊……$B',RequestItemsText_loc4='你把羽毛带来了吗?这个玩偶需要填充物!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8423,'战士的血脉','<英雄注视着你。>$B$B毫无疑问，你是一位$C。我要给你一项光荣的任务，但是首先，你必须证明自己的力量。$B$B据说雷克萨检验他的战斧是否锋利的标准，乃是它能否一下斩杀一头地狱野猪。现在，我要通过让你杀死它们来证明你拥有足够的力量。','杀死7头地狱野猪，然后回到部落英雄的灵魂那儿。','我不需要你给我任何证据来证明你的所作所为，$C。我可以从你的行为看到决心。$B','地狱野猪浑身都是令人毛骨悚然的伤疤。不要害怕疼痛和缺陷，$C，跟我现在所遭受的永恒痛苦相比，它们根本不算什么。') ON DUPLICATE KEY UPDATE Title_loc4='战士的血脉',Details_loc4='<英雄注视着你。>$B$B毫无疑问，你是一位$C。我要给你一项光荣的任务，但是首先，你必须证明自己的力量。$B$B据说雷克萨检验他的战斧是否锋利的标准，乃是它能否一下斩杀一头地狱野猪。现在，我要通过让你杀死它们来证明你拥有足够的力量。',Objectives_loc4='杀死7头地狱野猪，然后回到部落英雄的灵魂那儿。',OfferRewardText_loc4='我不需要你给我任何证据来证明你的所作所为，$C。我可以从你的行为看到决心。$B',RequestItemsText_loc4='地狱野猪浑身都是令人毛骨悚然的伤疤。不要害怕疼痛和缺陷，$C，跟我现在所遭受的永恒痛苦相比，它们根本不算什么。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8424,'魔誓者之战','我的存在本身就是个苦难，魔誓者更是为我带来了无穷无尽的痛苦，他们的黑暗仪式让我感到了比死亡还要可怕的苦楚。$B$B现在你可以帮我把痛苦带给他们。去吧，成为我的愤怒的象征。','杀死诅咒之地的魔誓者，然后回到部落英雄的灵魂那儿。','你减轻了我的痛苦并给予我荣耀，谢谢你，$C。$B','要打败影誓者并不容易，是吗?但是你是个战士，要嘛获胜，要嘛死去。') ON DUPLICATE KEY UPDATE Title_loc4='魔誓者之战',Details_loc4='我的存在本身就是个苦难，魔誓者更是为我带来了无穷无尽的痛苦，他们的黑暗仪式让我感到了比死亡还要可怕的苦楚。$B$B现在你可以帮我把痛苦带给他们。去吧，成为我的愤怒的象征。',Objectives_loc4='杀死诅咒之地的魔誓者，然后回到部落英雄的灵魂那儿。',OfferRewardText_loc4='你减轻了我的痛苦并给予我荣耀，谢谢你，$C。$B',RequestItemsText_loc4='要打败影誓者并不容易，是吗?但是你是个战士，要嘛获胜，要嘛死去。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8425,'巫毒羽毛','你为我带来一丝平静。我得给你点什么作为回报。$B$B我的武器和护甲陪我度过了光辉的岁月，现在它们对我来说都没什么用处了。还是送给你吧。$B$B去沉没的神庙，杀死巨魔守卫加什尔、米杉、祖罗、胡库、祖罗尔和洛若尔。他们的巫毒羽毛能使我的肉身重现一段时间，足够给你奖励了。将巫毒羽毛带给我吧。','将你从沉没的神庙的巨魔身上得到的巫毒羽毛交给部落英雄的灵魂。','我终于又能感受到冰冷的钢铁了，尽管只有一下下而已。$B','你这么快就回来了?时间对我的意义不太一样，或许对你而言，这是一次相当长的旅途……') ON DUPLICATE KEY UPDATE Title_loc4='巫毒羽毛',Details_loc4='你为我带来一丝平静。我得给你点什么作为回报。$B$B我的武器和护甲陪我度过了光辉的岁月，现在它们对我来说都没什么用处了。还是送给你吧。$B$B去沉没的神庙，杀死巨魔守卫加什尔、米杉、祖罗、胡库、祖罗尔和洛若尔。他们的巫毒羽毛能使我的肉身重现一段时间，足够给你奖励了。将巫毒羽毛带给我吧。',Objectives_loc4='将你从沉没的神庙的巨魔身上得到的巫毒羽毛交给部落英雄的灵魂。',OfferRewardText_loc4='我终于又能感受到冰冷的钢铁了，尽管只有一下下而已。$B',RequestItemsText_loc4='你这么快就回来了?时间对我的意义不太一样，或许对你而言，这是一次相当长的旅途……';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8426,'峡谷中的战斗','我们在战歌峡谷对银翼哨兵展开攻势，这一战役至关重要。联盟以保护这片不属于他们的森林为由，妄图从部落手中夺取我们最大的伐木场。$B$B别让他们的妄想成为事实，$N！为了部落，证明你的价值！成功之后再回到我这儿来。','将3枚战歌荣誉奖章交给战场外的部落战争使者。','棒极了!你在战歌峡谷保卫战中表现很出色!愿你的英雄事蹟在我们的土地上流传开来。$B','你有战歌峡谷的消息吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='峡谷中的战斗',Details_loc4='我们在战歌峡谷对银翼哨兵展开攻势，这一战役至关重要。联盟以保护这片不属于他们的森林为由，妄图从部落手中夺取我们最大的伐木场。$B$B别让他们的妄想成为事实，$N！为了部落，证明你的价值！成功之后再回到我这儿来。',Objectives_loc4='将3枚战歌荣誉奖章交给战场外的部落战争使者。',OfferRewardText_loc4='棒极了!你在战歌峡谷保卫战中表现很出色!愿你的英雄事蹟在我们的土地上流传开来。$B',RequestItemsText_loc4='你有战歌峡谷的消息吗，$N?';
