INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8436,'资源竞赛','我们和联盟的冲突已经上升为一场真正的战争，不久之后战争就将全面打响。$B$B对于阿拉希盆地的争夺就是一个很好的开战理由。要么就是联盟占据它，并用其对付我们；或者就是我们占据它，然后用来对付联盟。帮助污染者保持这场资源竞赛上的优势吧，$N！','将3枚阿拉希盆地荣誉奖章交给战场外的部落战争使者。','保护我们在阿拉希盆地的资源是一个非常重要的任务!你做得很好，$N。$B','你带来阿拉希盆地的消息了吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='资源竞赛',Details_loc4='我们和联盟的冲突已经上升为一场真正的战争，不久之后战争就将全面打响。$B$B对于阿拉希盆地的争夺就是一个很好的开战理由。要么就是联盟占据它，并用其对付我们；或者就是我们占据它，然后用来对付联盟。帮助污染者保持这场资源竞赛上的优势吧，$N！',Objectives_loc4='将3枚阿拉希盆地荣誉奖章交给战场外的部落战争使者。',OfferRewardText_loc4='保护我们在阿拉希盆地的资源是一个非常重要的任务!你做得很好，$N。$B',RequestItemsText_loc4='你带来阿拉希盆地的消息了吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8437,'资源竞赛','我们与联盟的冲突已经升级为真正的战争。在这个节骨眼上，双方都不愿意轻易开战。$B$B阿拉希盆地的战争就是资源争夺战。不是联盟夺得资源战胜我们，就是我们夺得资源保持军需供给。帮助污染者保护我们所需的战争资源，$N！','将3枚阿拉希盆地荣誉奖章交给战场外的部落战争使者。','保护我们在阿拉希盆地的资源是一个非常重要的任务!你做得很好，$N。$B','你带来阿拉希盆地的消息了吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='资源竞赛',Details_loc4='我们与联盟的冲突已经升级为真正的战争。在这个节骨眼上，双方都不愿意轻易开战。$B$B阿拉希盆地的战争就是资源争夺战。不是联盟夺得资源战胜我们，就是我们夺得资源保持军需供给。帮助污染者保护我们所需的战争资源，$N！',Objectives_loc4='将3枚阿拉希盆地荣誉奖章交给战场外的部落战争使者。',OfferRewardText_loc4='保护我们在阿拉希盆地的资源是一个非常重要的任务!你做得很好，$N。$B',RequestItemsText_loc4='你带来阿拉希盆地的消息了吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8438,'征服阿拉希盆地','我们和联盟的冲突已经上升为一场真正的战争，不久之后战争就将全面打响。$B$B对于阿拉希盆地的争夺就是一个很好的开战理由。要么就是联盟占据它，并用其对付我们；或者就是我们占据它，然后用来对付联盟。帮助污染者保持这场资源竞赛上的优势吧，$N！','将3枚阿拉希盆地荣誉奖章交给战场外的部落战争使者。','保护我们在阿拉希盆地的资源是一个非常重要的任务!你做得很好，$N。$B','你带来阿拉希盆地的消息了吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='征服阿拉希盆地',Details_loc4='我们和联盟的冲突已经上升为一场真正的战争，不久之后战争就将全面打响。$B$B对于阿拉希盆地的争夺就是一个很好的开战理由。要么就是联盟占据它，并用其对付我们；或者就是我们占据它，然后用来对付联盟。帮助污染者保持这场资源竞赛上的优势吧，$N！',Objectives_loc4='将3枚阿拉希盆地荣誉奖章交给战场外的部落战争使者。',OfferRewardText_loc4='保护我们在阿拉希盆地的资源是一个非常重要的任务!你做得很好，$N。$B',RequestItemsText_loc4='你带来阿拉希盆地的消息了吗，$N?';
