INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8569,'往日的贡献：战歌峡谷','这是你该得到的，$N!','当然胜利不是唯一重要的事情，英雄的努力是一切的精神所在!') ON DUPLICATE KEY UPDATE Title_loc4='往日的贡献：战歌峡谷',OfferRewardText_loc4='这是你该得到的，$N!',RequestItemsText_loc4='当然胜利不是唯一重要的事情，英雄的努力是一切的精神所在!';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8570,'往日的贡献：战歌峡谷','这是你该得到的，$N!','当然胜利不是唯一重要的事情，英雄的努力是一切的精神所在!') ON DUPLICATE KEY UPDATE Title_loc4='往日的贡献：战歌峡谷',OfferRewardText_loc4='这是你该得到的，$N!',RequestItemsText_loc4='当然胜利不是唯一重要的事情，英雄的努力是一切的精神所在!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8572,'精兵的装备','$N，你在与敌人作战、提供后勤补给和执行战略任务之后获得的徽章并不只是用来炫耀的。$B$B希望你还保留着它们。作为对你的鼓励，我想要奖励你一些只有塞纳里奥议会最亲近的盟友才能获得的东西。','把5枚后勤徽章、10枚战术徽章和10枚作战徽章交给塞纳里奥要塞的瓦古斯。你必须在塞纳里奥议会中达到友善声望才能完成这个任务。','做的好，$N。请接受这个代表塞纳里奥议会的象徵。这是你应得的，朋友!$B','你完成必要的任务了吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='精兵的装备',Details_loc4='$N，你在与敌人作战、提供后勤补给和执行战略任务之后获得的徽章并不只是用来炫耀的。$B$B希望你还保留着它们。作为对你的鼓励，我想要奖励你一些只有塞纳里奥议会最亲近的盟友才能获得的东西。',Objectives_loc4='把5枚后勤徽章、10枚战术徽章和10枚作战徽章交给塞纳里奥要塞的瓦古斯。你必须在塞纳里奥议会中达到友善声望才能完成这个任务。',OfferRewardText_loc4='做的好，$N。请接受这个代表塞纳里奥议会的象徵。这是你应得的，朋友!$B',RequestItemsText_loc4='你完成必要的任务了吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8573,'勇士的装备','$N，你在与敌人作战、提供后勤补给和执行战略任务之后获得的徽章并不只是用来炫耀的。$B$B希望你还保留着它们。作为对你的鼓励，我想要奖励你一些只有塞纳里奥议会最亲近的盟友才能获得的东西。','把15枚作战徽章、20枚后勤徽章、20枚战术徽章和1枚塞纳留斯印记交给塞纳里奥要塞的瓦古斯。你必须在塞纳里奥议会中达到崇拜声望才能完成这个任务。','做的好，$N。请接受这个代表塞纳里奥议会的象徵。这是你应得的，朋友!$B','你完成必要的任务了吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='勇士的装备',Details_loc4='$N，你在与敌人作战、提供后勤补给和执行战略任务之后获得的徽章并不只是用来炫耀的。$B$B希望你还保留着它们。作为对你的鼓励，我想要奖励你一些只有塞纳里奥议会最亲近的盟友才能获得的东西。',Objectives_loc4='把15枚作战徽章、20枚后勤徽章、20枚战术徽章和1枚塞纳留斯印记交给塞纳里奥要塞的瓦古斯。你必须在塞纳里奥议会中达到崇拜声望才能完成这个任务。',OfferRewardText_loc4='做的好，$N。请接受这个代表塞纳里奥议会的象徵。这是你应得的，朋友!$B',RequestItemsText_loc4='你完成必要的任务了吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8574,'忠诚者的装备','$N，你在与敌人作战、提供后勤补给和执行战略任务之后获得的徽章并不只是用来炫耀的。$B$B希望你还保留着它们。作为对你的鼓励，我想要奖励你一些只有塞纳里奥议会最亲近的盟友才能获得的东西。','干得好，$n。请接受这份来自塞纳里奥议会的礼物，朋友！','做的好，$N。请接受这个代表塞纳里奥议会的象徵。这是你应得的，朋友!$B','你完成必要的任务了吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='忠诚者的装备',Details_loc4='$N，你在与敌人作战、提供后勤补给和执行战略任务之后获得的徽章并不只是用来炫耀的。$B$B希望你还保留着它们。作为对你的鼓励，我想要奖励你一些只有塞纳里奥议会最亲近的盟友才能获得的东西。',Objectives_loc4='干得好，$n。请接受这份来自塞纳里奥议会的礼物，朋友！',OfferRewardText_loc4='做的好，$N。请接受这个代表塞纳里奥议会的象徵。这是你应得的，朋友!$B',RequestItemsText_loc4='你完成必要的任务了吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8575,'艾索雷葛斯的魔法账本','<你无法理解这上面的字。你甚至不知道这些文字是什么语言！>','把魔法账本交给塔纳利斯的纳瑞安。','<纳里安积极地检视字母。>$B$B太特别了，$r!这是什么?我完全看不懂龙语。$B','喔!魔法跳动的东西!是给我的吗?') ON DUPLICATE KEY UPDATE Title_loc4='艾索雷葛斯的魔法账本',Details_loc4='<你无法理解这上面的字。你甚至不知道这些文字是什么语言！>',Objectives_loc4='把魔法账本交给塔纳利斯的纳瑞安。',OfferRewardText_loc4='<纳里安积极地检视字母。>$B$B太特别了，$r!这是什么?我完全看不懂龙语。$B',RequestItemsText_loc4='喔!魔法跳动的东西!是给我的吗?';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4) VALUES (8576,'翻译龙语','先处理当务之急，$N!我们必须搞清楚艾索雷葛斯到底在石板上写了什么。$B$B你说他叫你做一个奥金浮标而这只是个概要图吗?可是他会用龙语写还真奇怪。那个讨厌的老家伙知道我看不懂这乱七八糟的文字。$B$B如果有用的话，我需要我的水晶球护目镜，一只500磅的鸡和〝龙语傻瓜教程〞第二卷。不需要按照顺序。$B') ON DUPLICATE KEY UPDATE Title_loc4='翻译龙语',OfferRewardText_loc4='先处理当务之急，$N!我们必须搞清楚艾索雷葛斯到底在石板上写了什么。$B$B你说他叫你做一个奥金浮标而这只是个概要图吗?可是他会用龙语写还真奇怪。那个讨厌的老家伙知道我看不懂这乱七八糟的文字。$B$B如果有用的话，我需要我的水晶球护目镜，一只500磅的鸡和〝龙语傻瓜教程〞第二卷。不需要按照顺序。$B';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8577,'斯图沃尔，前任死党','如果我要翻译东西的话，就得戴上我的占卜眼镜。不幸的，很久以前，我的眼镜就被我的前任死党给偷走了，他就是斯图沃尔。他把我打翻在地，然后拿走了眼镜，把我留在了这里。$B$B在我忠实的水晶球的帮助下，我现在找到他了！他要么就在银松森林的格雷迈恩之墙，要么就在遍地传送门的外域，那里现在到处都是燃烧军团的家伙。你要追踪到他，然后把我的眼镜拿回来，$N！','纳瑞安要你找到他的前任死党斯图沃尔，从他那里拿回从纳瑞安那里偷走的占卜眼镜。','真不敢相信他竟找到了我。我还以为我在外域时就与他走失了。我不会回去那里的，$r!不会，绝对不会!我受够了当他兼职的好朋友和全职的佣人。','<箱子里一个高声调的声音回应了你的呼唤>$B$B是谁啊?打扫房间的吗?') ON DUPLICATE KEY UPDATE Title_loc4='斯图沃尔，前任死党',Details_loc4='如果我要翻译东西的话，就得戴上我的占卜眼镜。不幸的，很久以前，我的眼镜就被我的前任死党给偷走了，他就是斯图沃尔。他把我打翻在地，然后拿走了眼镜，把我留在了这里。$B$B在我忠实的水晶球的帮助下，我现在找到他了！他要么就在银松森林的格雷迈恩之墙，要么就在遍地传送门的外域，那里现在到处都是燃烧军团的家伙。你要追踪到他，然后把我的眼镜拿回来，$N！',Objectives_loc4='纳瑞安要你找到他的前任死党斯图沃尔，从他那里拿回从纳瑞安那里偷走的占卜眼镜。',OfferRewardText_loc4='真不敢相信他竟找到了我。我还以为我在外域时就与他走失了。我不会回去那里的，$r!不会，绝对不会!我受够了当他兼职的好朋友和全职的佣人。',RequestItemsText_loc4='<箱子里一个高声调的声音回应了你的呼唤>$B$B是谁啊?打扫房间的吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8578,'占卜眼镜？没问题！','<你听到箱子里面传来一个声音。>$B$B你只需要他的占卜眼镜？很好！这不是问题……给我一分钟……嘿！该死……在哪里！$B$B好吧，我这里有一些坏消息，还有一些更坏的消息。坏消息是我把眼镜给弄丢了。更坏的消息是，我是上个星期在熔火之心里晃悠的时候把它给弄丢的。是的，熔火之心……我想这不是我能搞定的了！再见！','找到纳瑞安的占卜眼镜。','太好了!我把那只500磅的鸡和第二卷的〝龙语傻瓜教程〞放在哪了???喔，这是给你的一点小意思!','熔火之心啊?我希望我的护目镜还完好如初!') ON DUPLICATE KEY UPDATE Title_loc4='占卜眼镜？没问题！',Details_loc4='<你听到箱子里面传来一个声音。>$B$B你只需要他的占卜眼镜？很好！这不是问题……给我一分钟……嘿！该死……在哪里！$B$B好吧，我这里有一些坏消息，还有一些更坏的消息。坏消息是我把眼镜给弄丢了。更坏的消息是，我是上个星期在熔火之心里晃悠的时候把它给弄丢的。是的，熔火之心……我想这不是我能搞定的了！再见！',Objectives_loc4='找到纳瑞安的占卜眼镜。',OfferRewardText_loc4='太好了!我把那只500磅的鸡和第二卷的〝龙语傻瓜教程〞放在哪了???喔，这是给你的一点小意思!',RequestItemsText_loc4='熔火之心啊?我希望我的护目镜还完好如初!';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8579,'凡人中的勇士','你继续好好的效忠我们吧，$N。我们的协定依然存在。$B','杀死其拉主使者对人类而言是个显着的成就，$N。无论如何，他们拥有强大的能量与数量。继续对抗他们以证明自已成为我们勇士的价值。') ON DUPLICATE KEY UPDATE Title_loc4='凡人中的勇士',OfferRewardText_loc4='你继续好好的效忠我们吧，$N。我们的协定依然存在。$B',RequestItemsText_loc4='杀死其拉主使者对人类而言是个显着的成就，$N。无论如何，他们拥有强大的能量与数量。继续对抗他们以证明自已成为我们勇士的价值。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8580,'部落需要火焰花！','嘿，$c。是你啊！部落认为这次的安其拉之战需要很多的火焰花。或许他们会将它拿来做些好东西。或许他们会拿来当蒸气坦克的燃料再送给联盟？谁知道？比雷凯基也不知道！$B$B 不过比雷凯基知道这件事就是了……他知道你会帮他的忙并带回很多火焰花，对吗？','带20朵火焰花给奥格玛精神谷的蝙蝠骑士比雷凯基。','$C!比雷凯基现在开心了。比雷凯基把所有的火焰花收进盒子里保持新鲜。比雷凯基还告诉首领你的行为，所以大家都会对$N感到很高兴。如果你还有拿到其他的火焰花，就快点去找比雷凯基。比雷凯基还需要更多的花。','你不想让比雷凯基生气吧。要让比雷凯基高兴，你就得快速地带给他很多的火焰花。') ON DUPLICATE KEY UPDATE Title_loc4='部落需要火焰花！',Details_loc4='嘿，$c。是你啊！部落认为这次的安其拉之战需要很多的火焰花。或许他们会将它拿来做些好东西。或许他们会拿来当蒸气坦克的燃料再送给联盟？谁知道？比雷凯基也不知道！$B$B 不过比雷凯基知道这件事就是了……他知道你会帮他的忙并带回很多火焰花，对吗？',Objectives_loc4='带20朵火焰花给奥格玛精神谷的蝙蝠骑士比雷凯基。',OfferRewardText_loc4='$C!比雷凯基现在开心了。比雷凯基把所有的火焰花收进盒子里保持新鲜。比雷凯基还告诉首领你的行为，所以大家都会对$N感到很高兴。如果你还有拿到其他的火焰花，就快点去找比雷凯基。比雷凯基还需要更多的花。',RequestItemsText_loc4='你不想让比雷凯基生气吧。要让比雷凯基高兴，你就得快速地带给他很多的火焰花。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8581,'部落需要更多火焰花！','嘿，$c。就是你！部落需要非常大量的火焰花来支援安其拉之战。也许他们会把火焰花用在一些爆炸物中，也许还会把它们交给联盟来作为蒸汽坦克的燃料？谁知道？但这不是关键！这不关比雷凯基的事情！比雷凯基只知道……只知道你会帮助他收集很多火焰花，对不对？','把20份火焰花交给奥格瑞玛精神谷的蝙蝠骑士比雷凯基。','这不是开玩笑吧，$C?你这么快就帮比雷凯基带火焰花来了吗?比雷凯基现在就要算算它们的数量!你让比雷凯基感到很开心，他会告诉大家$N是有史以来最棒的火焰花收集者。比雷凯基等不及开战了。现在我们真的把希利苏斯的天空点亮了，对吧$g兄弟:姐妹;
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8582,'部落需要紫莲花！','$c，紫莲花是一种试剂，可以拿来做很多药水、药剂和油，有些对我们安其拉战役很有帮助。我们需要为战役制作数量庞大的药水。而且我也要做些实验找出紫莲花更多的功用。但是我需要大量的花才能做这些事。$B$B那是你进来的地方。走出去，采集越多紫莲花越好。这是你能办到的事吗？','带20朵紫莲花给奥格玛精神谷的药剂师耶泽尔。','值得表扬的努力，$C。我会测试这些样本找出它们适合的用途并记下你的贡献。这些紫莲花在我使用之前要先好好储藏起来。至于你，如果你还有空的话我还需要更多的紫莲花。等一会儿再回来找我。','你已经带着我要的紫莲花回来了吗，$C?你一定得尽快做好这件事，否则我这里要做的事全是空谈。') ON DUPLICATE KEY UPDATE Title_loc4='部落需要紫莲花！',Details_loc4='$c，紫莲花是一种试剂，可以拿来做很多药水、药剂和油，有些对我们安其拉战役很有帮助。我们需要为战役制作数量庞大的药水。而且我也要做些实验找出紫莲花更多的功用。但是我需要大量的花才能做这些事。$B$B那是你进来的地方。走出去，采集越多紫莲花越好。这是你能办到的事吗？',Objectives_loc4='带20朵紫莲花给奥格玛精神谷的药剂师耶泽尔。',OfferRewardText_loc4='值得表扬的努力，$C。我会测试这些样本找出它们适合的用途并记下你的贡献。这些紫莲花在我使用之前要先好好储藏起来。至于你，如果你还有空的话我还需要更多的紫莲花。等一会儿再回来找我。',RequestItemsText_loc4='你已经带着我要的紫莲花回来了吗，$C?你一定得尽快做好这件事，否则我这里要做的事全是空谈。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8583,'部落需要更多紫莲花！','紫莲花是很多药水、药剂和精油的重要材料，它对于我们准备发动的安其拉之战很重要。我们正在为这场战争准备许多药剂，而且我还希望能发掘出更多紫莲花的用途。但前提是，我们需要大量的这种花朵。这就是你来这里的目的。去收集尽可能多的紫莲花。你还擅长别的什么事情吗？','把20份紫莲花交给交给奥格瑞玛精神谷的药剂师耶泽尔。','真是杰出又完美的表现，$N。你的努力会被表扬，你的名声也刚被传开。我会亲自监督不让这些紫莲花被浪费掉，而你的名字也将被提及。$B$B再次感谢你，如果你有更多紫莲花，不要犹豫，用最快的速度把它们拿来给我。','事实上我们需要更多的紫莲花，$C。虽然我自己的研究尚未找出草药的新配方，但仍有已被试验和需要的试剂要使用。$B$B我需要你再去帮我收集至少20朵紫莲花样本。把它们交给我。') ON DUPLICATE KEY UPDATE Title_loc4='部落需要更多紫莲花！',Details_loc4='紫莲花是很多药水、药剂和精油的重要材料，它对于我们准备发动的安其拉之战很重要。我们正在为这场战争准备许多药剂，而且我还希望能发掘出更多紫莲花的用途。但前提是，我们需要大量的这种花朵。这就是你来这里的目的。去收集尽可能多的紫莲花。你还擅长别的什么事情吗？',Objectives_loc4='把20份紫莲花交给交给奥格瑞玛精神谷的药剂师耶泽尔。',OfferRewardText_loc4='真是杰出又完美的表现，$N。你的努力会被表扬，你的名声也刚被传开。我会亲自监督不让这些紫莲花被浪费掉，而你的名字也将被提及。$B$B再次感谢你，如果你有更多紫莲花，不要犹豫，用最快的速度把它们拿来给我。',RequestItemsText_loc4='事实上我们需要更多的紫莲花，$C。虽然我自己的研究尚未找出草药的新配方，但仍有已被试验和需要的试剂要使用。$B$B我需要你再去帮我收集至少20朵紫莲花样本。把它们交给我。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8584,'少管闲事','如果说我有一些原则是你应该了解的，那就是：永远不要管我的闲事！我所做的事情都是你无法理解的。比如说：你知道精神电能整流器是什么吗？显然你不知道！这就是为什么我来负责我们的项目规划，而你负责满世界跑腿。$B$B我之前说过，如果你想继续下去的话，那么我们需要一只500磅重的鸡。$B$B到加基森去跟迪尔格·奎克里弗谈谈——他知道如何让你找到合适的品种。','塔纳利斯的纳瑞安让你和加基森的迪尔格·奎克里弗谈一谈。','<戴格抓了抓他的头。>$B$B一只500磅的鸡?哪有这种东西!至少，现在没有了。我知道有这种鸡……死亡的黑鸡…$B$B<戴格的声音变小了。>$B$B但是，没有人可以见过那只鸡还活着讲这个故事。我有个主意能让我们双方获利，孩子。$B','一只什么?') ON DUPLICATE KEY UPDATE Title_loc4='少管闲事',Details_loc4='如果说我有一些原则是你应该了解的，那就是：永远不要管我的闲事！我所做的事情都是你无法理解的。比如说：你知道精神电能整流器是什么吗？显然你不知道！这就是为什么我来负责我们的项目规划，而你负责满世界跑腿。$B$B我之前说过，如果你想继续下去的话，那么我们需要一只500磅重的鸡。$B$B到加基森去跟迪尔格·奎克里弗谈谈——他知道如何让你找到合适的品种。',Objectives_loc4='塔纳利斯的纳瑞安让你和加基森的迪尔格·奎克里弗谈一谈。',OfferRewardText_loc4='<戴格抓了抓他的头。>$B$B一只500磅的鸡?哪有这种东西!至少，现在没有了。我知道有这种鸡……死亡的黑鸡…$B$B<戴格的声音变小了。>$B$B但是，没有人可以见过那只鸡还活着讲这个故事。我有个主意能让我们双方获利，孩子。$B',RequestItemsText_loc4='一只什么?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8585,'恐怖之岛！','传说菲拉斯恐怖之岛的那群名叫奇美洛克的奇美拉族群是最鲜美多汁的食物！现在它们之中出现了一个首领，它的肉在经过巧妙的烹调之后可以变成一盘极品大餐！$B$B去恐怖之岛杀掉拉克麦拉，然后把它的肉带回来。这就可以满足那个侏儒了，而我则需要你带一些奇美洛克的腰肋肉给我。$B$B我会给你那500磅的肉鸡和一些别的什么东西作为交换。','加基森的迪尔格·奎克里弗要你去菲拉斯的恐怖之岛击杀拉克麦拉，获得拉克麦拉的肉，并从岛上收集20份奇美洛克的腰肋肉。','看看那些嫩腰肉!太棒了!$B$B关于那只鸡……嗯，让我看看。我需要几分钟策划食谱。$B','嗯……奇美洛克……') ON DUPLICATE KEY UPDATE Title_loc4='恐怖之岛！',Details_loc4='传说菲拉斯恐怖之岛的那群名叫奇美洛克的奇美拉族群是最鲜美多汁的食物！现在它们之中出现了一个首领，它的肉在经过巧妙的烹调之后可以变成一盘极品大餐！$B$B去恐怖之岛杀掉拉克麦拉，然后把它的肉带回来。这就可以满足那个侏儒了，而我则需要你带一些奇美洛克的腰肋肉给我。$B$B我会给你那500磅的肉鸡和一些别的什么东西作为交换。',Objectives_loc4='加基森的迪尔格·奎克里弗要你去菲拉斯的恐怖之岛击杀拉克麦拉，获得拉克麦拉的肉，并从岛上收集20份奇美洛克的腰肋肉。',OfferRewardText_loc4='看看那些嫩腰肉!太棒了!$B$B关于那只鸡……嗯，让我看看。我需要几分钟策划食谱。$B',RequestItemsText_loc4='嗯……奇美洛克……';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8586,'迪尔格的超美味奇美拉肉片','我的食谱完成了！我还需要一些火箭燃料和石中盐，只要把这些调料和你带给我的肉混合起来就可以了。$B$B如果你带来了我要的东西，纳瑞安想要的那只鸡就可以完成了。','加基森的迪尔格·奎克里弗要你给他带去20份地精火箭燃油和20份石中盐。','准备好了!我要呈现给你我最棒的创作:戴格的超美味奇美拉肉片!$B','快一点，孩子。我们不想让肉坏掉。') ON DUPLICATE KEY UPDATE Title_loc4='迪尔格的超美味奇美拉肉片',Details_loc4='我的食谱完成了！我还需要一些火箭燃料和石中盐，只要把这些调料和你带给我的肉混合起来就可以了。$B$B如果你带来了我要的东西，纳瑞安想要的那只鸡就可以完成了。',Objectives_loc4='加基森的迪尔格·奎克里弗要你给他带去20份地精火箭燃油和20份石中盐。',OfferRewardText_loc4='准备好了!我要呈现给你我最棒的创作:戴格的超美味奇美拉肉片!$B',RequestItemsText_loc4='快一点，孩子。我们不想让肉坏掉。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8587,'向纳瑞安回复','我是一个不会食言的地精，孩子。这是你要的500磅的小鸡。$B$B为什么那侏儒想要一只500磅的小鸡，那我就不知道了……$B$B<迪尔格喃喃自语着。>$B$B也许那家伙想要睡在里面……肮脏的侏儒……','把500磅的小鸡交给塔纳利斯的纳瑞安。','<纳里安将两只拳头伸进那只巨大的鸡里，整张脸塞在戴格美味的佳肴里。>$B$B嗯……这真是不可思议!我吃过最好吃的鸡!$B','是什么味道这么香?') ON DUPLICATE KEY UPDATE Title_loc4='向纳瑞安回复',Details_loc4='我是一个不会食言的地精，孩子。这是你要的500磅的小鸡。$B$B为什么那侏儒想要一只500磅的小鸡，那我就不知道了……$B$B<迪尔格喃喃自语着。>$B$B也许那家伙想要睡在里面……肮脏的侏儒……',Objectives_loc4='把500磅的小鸡交给塔纳利斯的纳瑞安。',OfferRewardText_loc4='<纳里安将两只拳头伸进那只巨大的鸡里，整张脸塞在戴格美味的佳肴里。>$B$B嗯……这真是不可思议!我吃过最好吃的鸡!$B',RequestItemsText_loc4='是什么味道这么香?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8588,'部落需要重皮!','既然我们在准备作战，那么最好事先收集所有需要的东西，你不觉得吗?我们现在制作的主要战争材料之一是重皮。我们会在任何东西上使用到它，从增强材料到护甲，还有好的老旧防水布。$B$B但是首先我们需要弄到多一点重皮。那是你的工作，$c。磨锐你的刀，帮我带回一大堆来。然后我们再谈。','带10张重皮给奥格玛精神谷的剥皮师亚曼尼。','喔，你真的有我要的重皮。你的刀真的很锐利，$C;这些真是好皮!现在既然我们已经有了该有的东西，我一定会将你对事业的贡献让大家都知道。如果你刚好又有更多的重皮，请带来这里给我。$B','如果你只是要来这里碎碎念的话我可没有时间，$C。有太多堆重皮需要保存。等你至少有10张后再回来找我。') ON DUPLICATE KEY UPDATE Title_loc4='部落需要重皮!',Details_loc4='既然我们在准备作战，那么最好事先收集所有需要的东西，你不觉得吗?我们现在制作的主要战争材料之一是重皮。我们会在任何东西上使用到它，从增强材料到护甲，还有好的老旧防水布。$B$B但是首先我们需要弄到多一点重皮。那是你的工作，$c。磨锐你的刀，帮我带回一大堆来。然后我们再谈。',Objectives_loc4='带10张重皮给奥格玛精神谷的剥皮师亚曼尼。',OfferRewardText_loc4='喔，你真的有我要的重皮。你的刀真的很锐利，$C;这些真是好皮!现在既然我们已经有了该有的东西，我一定会将你对事业的贡献让大家都知道。如果你刚好又有更多的重皮，请带来这里给我。$B',RequestItemsText_loc4='如果你只是要来这里碎碎念的话我可没有时间，$C。有太多堆重皮需要保存。等你至少有10张后再回来找我。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8589,'部落需要更多重皮！','我们正在准备进行一场战争，所以我们最好首先把所有的物资准备妥当，你认为不该这样做吗，朋友？我们所需要的一类重要物资就是重皮。我们可以把它用在各个方面，强化护甲和制作防水布都用得到它。我们需要大量的重皮。这就是你的工作，牧师。磨快你的剥皮刀，给我带回大量的重皮吧。做完这件事情，我们再继续谈谈。','把10块重皮交给奥格瑞玛精神谷的剥皮师亚曼尼。','谢谢你的重皮。每一点都让我们离目标更接近。我会好好保存并确定你的名字被写在清单上，这样首领们就会知道你的努力。$B$B再次谢谢你，$N，如果你又有更多的重皮，你知道在哪里可以找的到我。$B','没错，$C，我还需要更多重皮。将军和军需官的需求似乎永无止尽。而这些数量跟齐柏林飞艇大师要求的比起来更微不足道!$B$B我需要收集双倍的配额量。$N，帮我带更多重皮来，越快越好!') ON DUPLICATE KEY UPDATE Title_loc4='部落需要更多重皮！',Details_loc4='我们正在准备进行一场战争，所以我们最好首先把所有的物资准备妥当，你认为不该这样做吗，朋友？我们所需要的一类重要物资就是重皮。我们可以把它用在各个方面，强化护甲和制作防水布都用得到它。我们需要大量的重皮。这就是你的工作，牧师。磨快你的剥皮刀，给我带回大量的重皮吧。做完这件事情，我们再继续谈谈。',Objectives_loc4='把10块重皮交给奥格瑞玛精神谷的剥皮师亚曼尼。',OfferRewardText_loc4='谢谢你的重皮。每一点都让我们离目标更接近。我会好好保存并确定你的名字被写在清单上，这样首领们就会知道你的努力。$B$B再次谢谢你，$N，如果你又有更多的重皮，你知道在哪里可以找的到我。$B',RequestItemsText_loc4='没错，$C，我还需要更多重皮。将军和军需官的需求似乎永无止尽。而这些数量跟齐柏林飞艇大师要求的比起来更微不足道!$B$B我需要收集双倍的配额量。$N，帮我带更多重皮来，越快越好!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8590,'部落需要厚皮!','我很高兴你决定来和我谈这件事，$c。看来部落为即将来临的安其拉之战准备的差不多了。但是你和我仍要尽自己的责任。$B$B我被要求收集大量的厚皮做为战争材料，而我需要你去帮我收集。如果你决定帮忙，那就代表了部落的荣耀和感激。你会帮忙吗?','带10张厚皮给奥格玛精神谷的乌玛拉中士。','做的好，$C。我相信这些厚皮会被拿来做齐柏林飞艇的增援和所有护甲及武器。谢谢你，部落也很感激你。如果你旅途中有更多的厚皮请回来找我。$B','$C，你这么快就带着我们说的10张厚皮回来了吗?') ON DUPLICATE KEY UPDATE Title_loc4='部落需要厚皮!',Details_loc4='我很高兴你决定来和我谈这件事，$c。看来部落为即将来临的安其拉之战准备的差不多了。但是你和我仍要尽自己的责任。$B$B我被要求收集大量的厚皮做为战争材料，而我需要你去帮我收集。如果你决定帮忙，那就代表了部落的荣耀和感激。你会帮忙吗?',Objectives_loc4='带10张厚皮给奥格玛精神谷的乌玛拉中士。',OfferRewardText_loc4='做的好，$C。我相信这些厚皮会被拿来做齐柏林飞艇的增援和所有护甲及武器。谢谢你，部落也很感激你。如果你旅途中有更多的厚皮请回来找我。$B',RequestItemsText_loc4='$C，你这么快就带着我们说的10张厚皮回来了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8591,'部落需要更多厚皮！','我很高兴你决定和我谈谈这个，$c。部落方面已经着手为即将开始的安其拉之战做准备了，你我都要做好自己该做的事情。我被指派来收集大量的厚皮，我需要你帮忙去收集这些东西。这项工作是你的荣耀，也是表示你对部落的忠诚的好机会。你愿意帮忙吗？','把10块厚皮交给奥格瑞玛精神谷的乌玛拉中士。','你办到了，$N，我就知道你可以。我再一次代表整个部落谢谢你。你的努力会被大家知道并获得诚挚的谢意。如果你找到更多厚皮愿意贡献，把它们带来这里给我吧。$B$B部落的荣耀!$B','$C，你可以看见我仍需要收集更多厚皮。我再次要求你协助这个任务，并且保证，如果你完成任务我们会肯定你的努力。$B$B时间就是金钱!带着厚皮回来找我，我们就能完成准备去打仗!') ON DUPLICATE KEY UPDATE Title_loc4='部落需要更多厚皮！',Details_loc4='我很高兴你决定和我谈谈这个，$c。部落方面已经着手为即将开始的安其拉之战做准备了，你我都要做好自己该做的事情。我被指派来收集大量的厚皮，我需要你帮忙去收集这些东西。这项工作是你的荣耀，也是表示你对部落的忠诚的好机会。你愿意帮忙吗？',Objectives_loc4='把10块厚皮交给奥格瑞玛精神谷的乌玛拉中士。',OfferRewardText_loc4='你办到了，$N，我就知道你可以。我再一次代表整个部落谢谢你。你的努力会被大家知道并获得诚挚的谢意。如果你找到更多厚皮愿意贡献，把它们带来这里给我吧。$B$B部落的荣耀!$B',RequestItemsText_loc4='$C，你可以看见我仍需要收集更多厚皮。我再次要求你协助这个任务，并且保证，如果你完成任务我们会肯定你的努力。$B$B时间就是金钱!带着厚皮回来找我，我们就能完成准备去打仗!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8592,'神谕者的皇冠','双子皇帝……他们正向我轻声密语，这折磨着我的神志。他们嘲笑我，他们知道我无法进入神殿的深处去拯救我的兄弟亚雷戈斯。$B$B我可以看见他们狰狞的脸庞，他们头上戴着具有无穷力量的皇冠。但是我必须要报仇……我会把这种代表其拉虫人力量的饰品转化成对我们有利的东西。$B$B把我需要的材料交给我，$N。我会为你制作一顶具有超凡力量的头盔。','把维克尼拉斯的头饰、2个先知塑像、5个银质甲虫和5个白骨甲虫交给安其拉的安多葛斯。你必须首先在诺兹多姆的子嗣中达到友善声望才可以完成这个任务。','你成功了!双子帝王的耳语停止了。$B$B收下这个奖励。看它一眼就会在其拉的心中注入恐惧…这会让他们想起死去的领导者还有杀死他们的人类。$B','你带回我要求的材料了吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='神谕者的皇冠',Details_loc4='双子皇帝……他们正向我轻声密语，这折磨着我的神志。他们嘲笑我，他们知道我无法进入神殿的深处去拯救我的兄弟亚雷戈斯。$B$B我可以看见他们狰狞的脸庞，他们头上戴着具有无穷力量的皇冠。但是我必须要报仇……我会把这种代表其拉虫人力量的饰品转化成对我们有利的东西。$B$B把我需要的材料交给我，$N。我会为你制作一顶具有超凡力量的头盔。',Objectives_loc4='把维克尼拉斯的头饰、2个先知塑像、5个银质甲虫和5个白骨甲虫交给安其拉的安多葛斯。你必须首先在诺兹多姆的子嗣中达到友善声望才可以完成这个任务。',OfferRewardText_loc4='你成功了!双子帝王的耳语停止了。$B$B收下这个奖励。看它一眼就会在其拉的心中注入恐惧…这会让他们想起死去的领导者还有杀死他们的人类。$B',RequestItemsText_loc4='你带回我要求的材料了吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8593,'神谕者的长裤','你想要向我们证明你的价值吗，凡人？很好，也许我们可以互相帮助。$B$B在传说中，古老的沙虫奥罗是一个非常强大的存在。据说是上古把它创造出来的原因是为了嘲笑生命的软弱。$B$B它的皮肤非常特殊……异常结实，甚至是无法击破的，而它本身的移动速度却不会因此而受到任何妨碍，它和那些小型生物一样动作灵敏。$B$B把它的皮肤样品和其它一些原材料都交给我，我会给你制作一条具有强大力量的护腿。','把巨型沙虫的皮、2个重生塑像、5个黄金甲虫和5个陶土甲虫交给安其拉的坎多斯特拉兹。你必须首先在诺兹多姆的子嗣中达到友善声望才可以完成这个任务。','太好了……这块虫的皮肤会是很棒的保护层。和我们在路上摧毁的其拉材料结合，这会是个令人畏惧的护甲。愿它协助你面对里面难以言喻的恐怖。$B','你把我需要的材料带来了吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='神谕者的长裤',Details_loc4='你想要向我们证明你的价值吗，凡人？很好，也许我们可以互相帮助。$B$B在传说中，古老的沙虫奥罗是一个非常强大的存在。据说是上古把它创造出来的原因是为了嘲笑生命的软弱。$B$B它的皮肤非常特殊……异常结实，甚至是无法击破的，而它本身的移动速度却不会因此而受到任何妨碍，它和那些小型生物一样动作灵敏。$B$B把它的皮肤样品和其它一些原材料都交给我，我会给你制作一条具有强大力量的护腿。',Objectives_loc4='把巨型沙虫的皮、2个重生塑像、5个黄金甲虫和5个陶土甲虫交给安其拉的坎多斯特拉兹。你必须首先在诺兹多姆的子嗣中达到友善声望才可以完成这个任务。',OfferRewardText_loc4='太好了……这块虫的皮肤会是很棒的保护层。和我们在路上摧毁的其拉材料结合，这会是个令人畏惧的护甲。愿它协助你面对里面难以言喻的恐怖。$B',RequestItemsText_loc4='你把我需要的材料带来了吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8594,'神谕者的衬肩','据说凡人所穿着的绚丽护肩是他们用来模仿龙翼的。$B$B把其拉虫人的最高领袖所佩戴的腕轮交给我，我会用它来制作一副比奈法利安的双翼还要可怕的护肩！','把其拉命令腕轮、2个重生塑像、5个银质甲虫和5个象牙甲虫交给安其拉的安多葛斯。你必须首先在诺兹多姆的子嗣中达到中立声望才可以完成这个任务。','我用你带来的材料和其拉虫人的鳞片制成了这套肩铠，凡人。希望它们能给你需要的保护也能让我们的敌人尝到恐惧的滋味。$B','你收集好我要的材料了吗?') ON DUPLICATE KEY UPDATE Title_loc4='神谕者的衬肩',Details_loc4='据说凡人所穿着的绚丽护肩是他们用来模仿龙翼的。$B$B把其拉虫人的最高领袖所佩戴的腕轮交给我，我会用它来制作一副比奈法利安的双翼还要可怕的护肩！',Objectives_loc4='把其拉命令腕轮、2个重生塑像、5个银质甲虫和5个象牙甲虫交给安其拉的安多葛斯。你必须首先在诺兹多姆的子嗣中达到中立声望才可以完成这个任务。',OfferRewardText_loc4='我用你带来的材料和其拉虫人的鳞片制成了这套肩铠，凡人。希望它们能给你需要的保护也能让我们的敌人尝到恐惧的滋味。$B',RequestItemsText_loc4='你收集好我要的材料了吗?';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8595,'凡人中的勇士','你继续好好的效忠我们吧，$N。我们的协定依然存在。$B','杀死其拉主使者对人类而言是个显着的成就，$N。无论如何，他们拥有强大的能量与数量。继续对抗他们以证明自已成为我们勇士的价值。') ON DUPLICATE KEY UPDATE Title_loc4='凡人中的勇士',OfferRewardText_loc4='你继续好好的效忠我们吧，$N。我们的协定依然存在。$B',RequestItemsText_loc4='杀死其拉主使者对人类而言是个显着的成就，$N。无论如何，他们拥有强大的能量与数量。继续对抗他们以证明自已成为我们勇士的价值。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8596,'神谕者的裹足','其拉虫人的魔法古老而又强大，它们最强大的武器甚至可以与龙抗衡。$B$B把其拉统御腕轮和其它辅助材料交给我，我将为你制作一双威力无比的靴子。$B$B你会在与敌人作战的时候发现它所蕴含的力量。','把其拉命令腕轮、2个死亡塑像、5个青铜甲虫和5个黄金甲虫交给安其拉的坎多斯特拉兹。你必须首先在诺兹多姆的子嗣中达到中立声望才可以完成这个任务。','你做的很好，$N。你已证明你不是普通的人类。$B$B我把这些东西给你，相信它们可以帮助你击败万恶的其拉虫人。$B','你把我要的东西都带来了吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='神谕者的裹足',Details_loc4='其拉虫人的魔法古老而又强大，它们最强大的武器甚至可以与龙抗衡。$B$B把其拉统御腕轮和其它辅助材料交给我，我将为你制作一双威力无比的靴子。$B$B你会在与敌人作战的时候发现它所蕴含的力量。',Objectives_loc4='把其拉命令腕轮、2个死亡塑像、5个青铜甲虫和5个黄金甲虫交给安其拉的坎多斯特拉兹。你必须首先在诺兹多姆的子嗣中达到中立声望才可以完成这个任务。',OfferRewardText_loc4='你做的很好，$N。你已证明你不是普通的人类。$B$B我把这些东西给你，相信它们可以帮助你击败万恶的其拉虫人。$B',RequestItemsText_loc4='你把我要的东西都带来了吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8597,'龙语傻瓜教程','我就知道总有一天这本书会有用的！幸运的是，我已经学聪明了！我把它藏了起来。$B$B不要担心，它被放在谁都找不到的地方！嗯，我需要搭乘一架直升飞机才可以到那里去。不幸的是，在我回来的路上，飞机坠毁了。就是因为这次事故，我才获得了超级侏儒精神力量！$B$B到天涯海滩那边去寻找坠毁的直升飞机，然后往南边游！你到了那里就会看到的！','寻找纳瑞安埋在南海的某座小岛上的书。','书不见了!在土石堆上的是一张纸条。$B','那个地方有一个X标记……') ON DUPLICATE KEY UPDATE Title_loc4='龙语傻瓜教程',Details_loc4='我就知道总有一天这本书会有用的！幸运的是，我已经学聪明了！我把它藏了起来。$B$B不要担心，它被放在谁都找不到的地方！嗯，我需要搭乘一架直升飞机才可以到那里去。不幸的是，在我回来的路上，飞机坠毁了。就是因为这次事故，我才获得了超级侏儒精神力量！$B$B到天涯海滩那边去寻找坠毁的直升飞机，然后往南边游！你到了那里就会看到的！',Objectives_loc4='寻找纳瑞安埋在南海的某座小岛上的书。',OfferRewardText_loc4='书不见了!在土石堆上的是一张纸条。$B',RequestItemsText_loc4='那个地方有一个X标记……';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8598,'敲诈','<便笺上用不同的字体拼凑出一段话。>$B$B我们已经拿到了你宝贵的书，侏儒。如果你想再见到它的话，那么你就必须按照我们说的来做。$B$B<以下是长达3页的具体指示说明。>$B$B把钱带来，只需你一个人来！','把勒索信交给塔纳利斯的纳瑞安。','<纳里安的脸愤怒而发红。>$B$B他们绑架我的……书，是吗?我会让他们知道玩弄超自然地精的下场!$B','嘿，有什么事吗?') ON DUPLICATE KEY UPDATE Title_loc4='敲诈',Details_loc4='<便笺上用不同的字体拼凑出一段话。>$B$B我们已经拿到了你宝贵的书，侏儒。如果你想再见到它的话，那么你就必须按照我们说的来做。$B$B<以下是长达3页的具体指示说明。>$B$B把钱带来，只需你一个人来！',Objectives_loc4='把勒索信交给塔纳利斯的纳瑞安。',OfferRewardText_loc4='<纳里安的脸愤怒而发红。>$B$B他们绑架我的……书，是吗?我会让他们知道玩弄超自然地精的下场!$B',RequestItemsText_loc4='嘿，有什么事吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8599,'唱给纳瑞安的情歌','并不是总是有人来拜访我。上一次有人来拜访，还是那次我把那个可爱的侏儒从坠毁的机器中救出来的时候。$B$B<米莉蒂丝若有所思。>$B$B你认识他吗？他叫纳瑞安……哦，如果有人可以替我给他传个话，那就太好了。我一定要告诉他我的感觉！我知道这就是爱！就是这样的！$B$B你可以帮我传话给纳瑞安吗？我永远都不会忘记你的！','把米莉蒂丝的情书交给塔纳利斯的纳瑞安。','什么!?$B$B<纳里安开始坐立不安。>$B$B嗯……你要我怎么做???她是一条鱼!我告诉你是一条鱼!而且我是个地精。我们是不可能在一起的。$B','你身上都是鱼腥味!') ON DUPLICATE KEY UPDATE Title_loc4='唱给纳瑞安的情歌',Details_loc4='并不是总是有人来拜访我。上一次有人来拜访，还是那次我把那个可爱的侏儒从坠毁的机器中救出来的时候。$B$B<米莉蒂丝若有所思。>$B$B你认识他吗？他叫纳瑞安……哦，如果有人可以替我给他传个话，那就太好了。我一定要告诉他我的感觉！我知道这就是爱！就是这样的！$B$B你可以帮我传话给纳瑞安吗？我永远都不会忘记你的！',Objectives_loc4='把米莉蒂丝的情书交给塔纳利斯的纳瑞安。',OfferRewardText_loc4='什么!?$B$B<纳里安开始坐立不安。>$B$B嗯……你要我怎么做???她是一条鱼!我告诉你是一条鱼!而且我是个地精。我们是不可能在一起的。$B',RequestItemsText_loc4='你身上都是鱼腥味!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8600,'部落需要硬甲皮!','我发现刀子握在掌心的适合度远比刀口的锋利重要。即使是最钝的刀剑也能在危急时发挥作用。但是你和我没有这种问题，毕竟我们总会让刀锋维持在最利的状态。$B$B对吧?嗯，不重要。我有个任务要给你，$c。为了部落，还有你对安其拉之战该尽的职责，我要你去收集很多硬甲皮给我。你能做到吗?','带10张硬甲皮给奥格玛精神谷的塞拉图斯。','很好，这算是及格的工作了，虽然有些皮看起来切割的参差不齐。没关系，任务完成了，你获得了你的奖励。我会把你的名字写在皮革旁边;我肯定部落会很感谢你的努力。如果你又有了另一批硬甲皮，请尽快将它们带来给我。$B','帮我切割10张硬甲皮不需要这么久的时间吧!你是不是应该磨锐你的剥皮小刀了呢?') ON DUPLICATE KEY UPDATE Title_loc4='部落需要硬甲皮!',Details_loc4='我发现刀子握在掌心的适合度远比刀口的锋利重要。即使是最钝的刀剑也能在危急时发挥作用。但是你和我没有这种问题，毕竟我们总会让刀锋维持在最利的状态。$B$B对吧?嗯，不重要。我有个任务要给你，$c。为了部落，还有你对安其拉之战该尽的职责，我要你去收集很多硬甲皮给我。你能做到吗?',Objectives_loc4='带10张硬甲皮给奥格玛精神谷的塞拉图斯。',OfferRewardText_loc4='很好，这算是及格的工作了，虽然有些皮看起来切割的参差不齐。没关系，任务完成了，你获得了你的奖励。我会把你的名字写在皮革旁边;我肯定部落会很感谢你的努力。如果你又有了另一批硬甲皮，请尽快将它们带来给我。$B',RequestItemsText_loc4='帮我切割10张硬甲皮不需要这么久的时间吧!你是不是应该磨锐你的剥皮小刀了呢?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8601,'部落需要更多硬甲皮！','我发现刀子握在掌心的适合度远比刀口的锋利重要。即使是最钝的刀剑也能在危急时发挥作用。但是你和我没有这种问题，毕竟我们总会让刀锋维持在最利的状态。$b$b对吧？嗯，不重要。我有个任务要给你，$c。为了部落，还有你对安其拉之战该尽的职责，我要你去收集很多硬甲皮给我。你能做到吗？','带10张硬甲皮给奥格玛精神谷的塞拉图斯。','练习，练习，练习。一把磨锐的好刀和使用它的技能会让你所向披靡，$N。看来这次的皮革边缘比上次切割的好。你买了新的小刀吗?$B$B我们感谢你的努力。你的捐献会被记录下来，而你的名声会远播至关心这类事情的人那里。如果你又获得了更多硬甲皮，请务必回来与我交谈，因为我可能会需要它。$B','为安其拉之战做的准备继续进行，$C。但是，要确定我们没有落后，或至少不要成为造成落后的人，我要你再带回另一批硬甲皮给我。这一次，尽量切割的乾净一点，知道吗?我还要浪费时间清理你上次给我的那批货。') ON DUPLICATE KEY UPDATE Title_loc4='部落需要更多硬甲皮！',Details_loc4='我发现刀子握在掌心的适合度远比刀口的锋利重要。即使是最钝的刀剑也能在危急时发挥作用。但是你和我没有这种问题，毕竟我们总会让刀锋维持在最利的状态。$b$b对吧？嗯，不重要。我有个任务要给你，$c。为了部落，还有你对安其拉之战该尽的职责，我要你去收集很多硬甲皮给我。你能做到吗？',Objectives_loc4='带10张硬甲皮给奥格玛精神谷的塞拉图斯。',OfferRewardText_loc4='练习，练习，练习。一把磨锐的好刀和使用它的技能会让你所向披靡，$N。看来这次的皮革边缘比上次切割的好。你买了新的小刀吗?$B$B我们感谢你的努力。你的捐献会被记录下来，而你的名声会远播至关心这类事情的人那里。如果你又获得了更多硬甲皮，请务必回来与我交谈，因为我可能会需要它。$B',RequestItemsText_loc4='为安其拉之战做的准备继续进行，$C。但是，要确定我们没有落后，或至少不要成为造成落后的人，我要你再带回另一批硬甲皮给我。这一次，尽量切割的乾净一点，知道吗?我还要浪费时间清理你上次给我的那批货。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8602,'风暴召唤者的肩甲','据说凡人所穿着的绚丽护肩是他们用来模仿龙翼的。$B$B把其拉虫人的最高领袖所佩戴的腕轮交给我，我会用它来制作一副比奈法利安的双翼还要可怕的护肩！','把其拉统御腕轮、2个生命塑像、5个黄金甲虫和5个水晶甲虫交给安其拉的安多葛斯。你必须首先在诺兹多姆的子嗣中达到中立声望才可以完成这个任务。','我用你带来的材料和其拉虫人的鳞片制成了这套肩铠，人类。希望它们能给你需要的保护也能让我们的敌人尝到恐惧的滋味。$B','你收集好我要的材料了吗?') ON DUPLICATE KEY UPDATE Title_loc4='风暴召唤者的肩甲',Details_loc4='据说凡人所穿着的绚丽护肩是他们用来模仿龙翼的。$B$B把其拉虫人的最高领袖所佩戴的腕轮交给我，我会用它来制作一副比奈法利安的双翼还要可怕的护肩！',Objectives_loc4='把其拉统御腕轮、2个生命塑像、5个黄金甲虫和5个水晶甲虫交给安其拉的安多葛斯。你必须首先在诺兹多姆的子嗣中达到中立声望才可以完成这个任务。',OfferRewardText_loc4='我用你带来的材料和其拉虫人的鳞片制成了这套肩铠，人类。希望它们能给你需要的保护也能让我们的敌人尝到恐惧的滋味。$B',RequestItemsText_loc4='你收集好我要的材料了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8603,'神谕者的外套','最令人恐怖的上古之神正在从安其拉的休眠之中慢慢醒来。艾泽拉斯世界不久之后即将面对这股恐怖的力量，时间对于如此强大的存在来说毫无意义。$B$B当星辰的位置合适的时候，他将让恐怖的力量席卷所有的一切。你必须在此之前找到他，消灭他。$B$B完成这个任务，把他的外壳交给我。我会奖励你一件凡人从未见到过的护甲……一件只有弑神者才有资格获得的护甲！','把上古之神的外鞘、2个死亡塑像、5个岩石甲虫和5个水晶甲虫交给安其拉的温瑟拉。你必须在诺兹多姆的子嗣中达到尊敬声望才能完成这个任务。','我没想到你会回来，$N。$B$B你已达到比最不朽的生物还伟大的命运。$B$B杀死克苏恩不只拯救了整个艾泽拉斯，你还削弱了超乎你能理解的宇宙大事。$B$B收下这个外衣做为光荣的象徵和伴随你行为而来的重担。$B$B愿它的力量能在等待着你的挑战中协助你，弑神者!$B','在安其拉的住所里，可怕的克苏恩在睡眠中等待着。') ON DUPLICATE KEY UPDATE Title_loc4='神谕者的外套',Details_loc4='最令人恐怖的上古之神正在从安其拉的休眠之中慢慢醒来。艾泽拉斯世界不久之后即将面对这股恐怖的力量，时间对于如此强大的存在来说毫无意义。$B$B当星辰的位置合适的时候，他将让恐怖的力量席卷所有的一切。你必须在此之前找到他，消灭他。$B$B完成这个任务，把他的外壳交给我。我会奖励你一件凡人从未见到过的护甲……一件只有弑神者才有资格获得的护甲！',Objectives_loc4='把上古之神的外鞘、2个死亡塑像、5个岩石甲虫和5个水晶甲虫交给安其拉的温瑟拉。你必须在诺兹多姆的子嗣中达到尊敬声望才能完成这个任务。',OfferRewardText_loc4='我没想到你会回来，$N。$B$B你已达到比最不朽的生物还伟大的命运。$B$B杀死克苏恩不只拯救了整个艾泽拉斯，你还削弱了超乎你能理解的宇宙大事。$B$B收下这个外衣做为光荣的象徵和伴随你行为而来的重担。$B$B愿它的力量能在等待着你的挑战中协助你，弑神者!$B',RequestItemsText_loc4='在安其拉的住所里，可怕的克苏恩在睡眠中等待着。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8604,'部落需要绒线绷带！','你好，$c。为了准备安其拉之战，我在这里帮助部落协调收集绒线绷带。在战场上，士兵们不能指望总有医师跟着他们，所以我们要为他们准备急救包。$B$B如果你有时间的话，我需要很多绒线绷带，请把绷带交给我，我会奖励你的。','把20卷绒线绷带交给奥格瑞玛精神谷的医师朗兰纳。','谢谢你，$C，部落也很感激你。如果你有更多的绒线绷带，又希望对战事做更多贡献的话，请带到这边给我。在那之前，愿你的祖先守护着你!$B','啊，$C，你这么快就带着绒线绷带回来了吗?') ON DUPLICATE KEY UPDATE Title_loc4='部落需要绒线绷带！',Details_loc4='你好，$c。为了准备安其拉之战，我在这里帮助部落协调收集绒线绷带。在战场上，士兵们不能指望总有医师跟着他们，所以我们要为他们准备急救包。$B$B如果你有时间的话，我需要很多绒线绷带，请把绷带交给我，我会奖励你的。',Objectives_loc4='把20卷绒线绷带交给奥格瑞玛精神谷的医师朗兰纳。',OfferRewardText_loc4='谢谢你，$C，部落也很感激你。如果你有更多的绒线绷带，又希望对战事做更多贡献的话，请带到这边给我。在那之前，愿你的祖先守护着你!$B',RequestItemsText_loc4='啊，$C，你这么快就带着绒线绷带回来了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8605,'部落需要更多绒线绷带！','你好，$c。为了准备安其拉之战，我在这里帮助部落协调收集绒线绷带。在战场上，士兵们不能指望总有医师跟着他们，所以我们要为他们准备急救包。$b$b如果你有时间的话，我需要很多绒线绷带，请把绷带交给我，我会奖励你的。 ','把20卷绒线绷带交给奥格瑞玛精神谷的医师朗兰纳。','你是个高尚的$C，$N!我会代表部落确实记录你的贡献并让负责的人都知道你的努力。平静的走吧，如果你又找到多余的绒线绷带再回来找我。','能再见到你真好，$C。我们仍在为战事做准备，所以我仍然需要你协助我收集绒线绷带。我们非常感谢你能提供的任何协助。') ON DUPLICATE KEY UPDATE Title_loc4='部落需要更多绒线绷带！',Details_loc4='你好，$c。为了准备安其拉之战，我在这里帮助部落协调收集绒线绷带。在战场上，士兵们不能指望总有医师跟着他们，所以我们要为他们准备急救包。$b$b如果你有时间的话，我需要很多绒线绷带，请把绷带交给我，我会奖励你的。 ',Objectives_loc4='把20卷绒线绷带交给奥格瑞玛精神谷的医师朗兰纳。',OfferRewardText_loc4='你是个高尚的$C，$N!我会代表部落确实记录你的贡献并让负责的人都知道你的努力。平静的走吧，如果你又找到多余的绒线绷带再回来找我。',RequestItemsText_loc4='能再见到你真好，$C。我们仍在为战事做准备，所以我仍然需要你协助我收集绒线绷带。我们非常感谢你能提供的任何协助。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4) VALUES (8606,'螳螂捕蝉！','我终于想到了！我们应该这样做。我要给袋子里装满石头，然后你来负责送货。我知道他们说应该由我亲自送去之类的。$B$B<纳瑞安上下打量着你。>$B$B嗯，你也可以完成这个任务。戴上这条头巾，穿上这件长袍，拿着这袋石头，去冬泉谷的交货地点吧。$B$B我在这个工具包中帮你准备了所有必需的东西。当他们冒出来拿货的时候，就干掉他们！让他们知道惹毛了纳瑞安的下场！','塔纳利斯的纳瑞安要你去冬泉谷，把一袋金子放在绑匪的勒索信上所写的位置。他还要求你教训一下那些家伙！','我想我低估了这些绑架书的人。$B','快，$N!不知道他们对我的书有什么病态疯狂的计划!','二号是替谁工作的?') ON DUPLICATE KEY UPDATE Title_loc4='螳螂捕蝉！',Details_loc4='我终于想到了！我们应该这样做。我要给袋子里装满石头，然后你来负责送货。我知道他们说应该由我亲自送去之类的。$B$B<纳瑞安上下打量着你。>$B$B嗯，你也可以完成这个任务。戴上这条头巾，穿上这件长袍，拿着这袋石头，去冬泉谷的交货地点吧。$B$B我在这个工具包中帮你准备了所有必需的东西。当他们冒出来拿货的时候，就干掉他们！让他们知道惹毛了纳瑞安的下场！',Objectives_loc4='塔纳利斯的纳瑞安要你去冬泉谷，把一袋金子放在绑匪的勒索信上所写的位置。他还要求你教训一下那些家伙！',OfferRewardText_loc4='我想我低估了这些绑架书的人。$B',RequestItemsText_loc4='快，$N!不知道他们对我的书有什么病态疯狂的计划!',ObjectiveText1_loc4='二号是替谁工作的?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8607,'部落需要魔纹布绷带！','我相信你来找我是想要帮助我收集东西？很好！不管怎么样，我接受所有的帮助，并且我需要你帮忙去收集厚魔纹绷带。最好是新做的，但不是必须。把它们交给我，$c，我会给你适当的奖励的。','把20卷魔纹绷带交给奥格瑞玛精神谷的卡隆。','很惊讶，但是差强人意。或许我低估了你的「…能力」…$C。或许吧。你完成了一个非常简单的任务，因此你会获得不成比例的奖励。但是不要让它影响到你。如果你真的想证明自己就再去帮我带回另一堆魔纹布绷带吧。$B','不许失败让我颜面扫地，$C!尽快带着我们讨论的魔纹布绷带回到这里。') ON DUPLICATE KEY UPDATE Title_loc4='部落需要魔纹布绷带！',Details_loc4='我相信你来找我是想要帮助我收集东西？很好！不管怎么样，我接受所有的帮助，并且我需要你帮忙去收集厚魔纹绷带。最好是新做的，但不是必须。把它们交给我，$c，我会给你适当的奖励的。',Objectives_loc4='把20卷魔纹绷带交给奥格瑞玛精神谷的卡隆。',OfferRewardText_loc4='很惊讶，但是差强人意。或许我低估了你的「…能力」…$C。或许吧。你完成了一个非常简单的任务，因此你会获得不成比例的奖励。但是不要让它影响到你。如果你真的想证明自己就再去帮我带回另一堆魔纹布绷带吧。$B',RequestItemsText_loc4='不许失败让我颜面扫地，$C!尽快带着我们讨论的魔纹布绷带回到这里。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8608,'部落需要更多魔纹布绷带！','真是太惊讶了，$C，你真的又完成了。嗯，他们都说我很会选人做事。很好，我会将你的名字记录在你的贡献旁边，这样你就能获得这项努力应得的社会利益。如果你真的想证明自己的价值，我建议你再出去收集另一堆魔纹布绷带。$B','你回来了?真有趣。你看我还在收集安其拉战役要用的东西。这表示我需要你再次为我收集一堆魔纹布绷带。如果你能再做一次会相当令人惊讶的$C。') ON DUPLICATE KEY UPDATE Title_loc4='部落需要更多魔纹布绷带！',OfferRewardText_loc4='真是太惊讶了，$C，你真的又完成了。嗯，他们都说我很会选人做事。很好，我会将你的名字记录在你的贡献旁边，这样你就能获得这项努力应得的社会利益。如果你真的想证明自己的价值，我建议你再出去收集另一堆魔纹布绷带。$B',RequestItemsText_loc4='你回来了?真有趣。你看我还在收集安其拉战役要用的东西。这表示我需要你再次为我收集一堆魔纹布绷带。如果你能再做一次会相当令人惊讶的$C。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8609,'部落需要符文布绷带!','看来安其拉战役会造成部落和联盟间不可避免的冲突。但令人惊讶的是，这不是场双方间的战争，而是对抗异种蝎和控制他们的力量。双方都在收集打一场胜仗所需的资源。$B$B我在收集要分配给士兵们的符文布绷带。但是我没有协助是不会成功的。你能帮我这个忙吗，$c?','带20个符文布绷带给奥格玛精神谷的尼根·陶蹄。','你对部落而言是个荣耀，$C。谢谢你的努力;我们很感谢!我要把这些新鲜的绷带打包好并算算我们离目标还差多少。如果你愿意，可以帮我收集更多符文布绷带再回来这里。$B','战争很快就来了，$C。你取得了我们之前说的符文布绷带吗?') ON DUPLICATE KEY UPDATE Title_loc4='部落需要符文布绷带!',Details_loc4='看来安其拉战役会造成部落和联盟间不可避免的冲突。但令人惊讶的是，这不是场双方间的战争，而是对抗异种蝎和控制他们的力量。双方都在收集打一场胜仗所需的资源。$B$B我在收集要分配给士兵们的符文布绷带。但是我没有协助是不会成功的。你能帮我这个忙吗，$c?',Objectives_loc4='带20个符文布绷带给奥格玛精神谷的尼根·陶蹄。',OfferRewardText_loc4='你对部落而言是个荣耀，$C。谢谢你的努力;我们很感谢!我要把这些新鲜的绷带打包好并算算我们离目标还差多少。如果你愿意，可以帮我收集更多符文布绷带再回来这里。$B',RequestItemsText_loc4='战争很快就来了，$C。你取得了我们之前说的符文布绷带吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8610,'部落需要更多符文布绷带！','毫无疑问，部落和联盟在准备安其拉之战的过程中会发生摩擦。奇怪的是，这场战争居然不是在部落和联盟之间进行的，双方的敌人都是异种虫类和控制这些虫子的幕后黑手。部落和联盟都在积极收集资源来发动这场战争。$b$b我负责收集符文布绷带，但是如果我得不到帮助的话就不会成功。你能帮助我吗，$c？ ','把20卷符文布绷带交给奥格瑞玛精神谷的尼根·陶蹄。','你的付出相当地无私，$N。你解救了安其拉战士。非常感谢你对部落的慷慨解囊。如果你能制作、或是遇到更多的符文布绷带，请考虑带回来这里给我。$B','时间越来越接近我们一头栽进安其拉战火的时候了，$C。但是首先我们必须聚集我们的力量并准备好一切，这样我们才能在那些昆虫和他们的首领猛攻下生存。$B$B如果你可以的话，就再贡献另一批符文布绷带吧。请尽快完成并再次回到我这里。') ON DUPLICATE KEY UPDATE Title_loc4='部落需要更多符文布绷带！',Details_loc4='毫无疑问，部落和联盟在准备安其拉之战的过程中会发生摩擦。奇怪的是，这场战争居然不是在部落和联盟之间进行的，双方的敌人都是异种虫类和控制这些虫子的幕后黑手。部落和联盟都在积极收集资源来发动这场战争。$b$b我负责收集符文布绷带，但是如果我得不到帮助的话就不会成功。你能帮助我吗，$c？ ',Objectives_loc4='把20卷符文布绷带交给奥格瑞玛精神谷的尼根·陶蹄。',OfferRewardText_loc4='你的付出相当地无私，$N。你解救了安其拉战士。非常感谢你对部落的慷慨解囊。如果你能制作、或是遇到更多的符文布绷带，请考虑带回来这里给我。$B',RequestItemsText_loc4='时间越来越接近我们一头栽进安其拉战火的时候了，$C。但是首先我们必须聚集我们的力量并准备好一切，这样我们才能在那些昆虫和他们的首领猛攻下生存。$B$B如果你可以的话，就再贡献另一批符文布绷带吧。请尽快完成并再次回到我这里。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8611,'部落需要瘦狼排!','我站在这里不是为了晒成好看的小麦色，$c。是为了战争作准备。如果我们要消灭安其拉那些虫子，那么我们就要准备好，包括食物!$B$B他们要我为即将来临的战争收集并腌制瘦狼排。但是我必须留在这里处理事情，所以我需要你去杀一些狼，并将它们的肉烹煮成瘦狼排再带来给我。你听懂了吗?','带20块瘦狼排给奥格玛精神谷的血卫士拉尔塔。','嗯，这堆肉看起来很好。我会用盐腌制它们并打包好，希望能一直保持新鲜到要吃的时候。$B$B谢谢你将它们带来给我;我会确认你的烹饪工作被记录下来。你还能再带给我另一批吗?$B','这么快就带着瘦狼排回来了吗，$C?我不在乎它们烤太熟或沾了塔塔酱，只要它们是美味的就快点带来给我!') ON DUPLICATE KEY UPDATE Title_loc4='部落需要瘦狼排!',Details_loc4='我站在这里不是为了晒成好看的小麦色，$c。是为了战争作准备。如果我们要消灭安其拉那些虫子，那么我们就要准备好，包括食物!$B$B他们要我为即将来临的战争收集并腌制瘦狼排。但是我必须留在这里处理事情，所以我需要你去杀一些狼，并将它们的肉烹煮成瘦狼排再带来给我。你听懂了吗?',Objectives_loc4='带20块瘦狼排给奥格玛精神谷的血卫士拉尔塔。',OfferRewardText_loc4='嗯，这堆肉看起来很好。我会用盐腌制它们并打包好，希望能一直保持新鲜到要吃的时候。$B$B谢谢你将它们带来给我;我会确认你的烹饪工作被记录下来。你还能再带给我另一批吗?$B',RequestItemsText_loc4='这么快就带着瘦狼排回来了吗，$C?我不在乎它们烤太熟或沾了塔塔酱，只要它们是美味的就快点带来给我!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8612,'部落需要更多瘦狼排！','我站在这里可不是为了把自己皮肤晒成健康色的，$c。我们必须为战争做好准备。如果我们想要把那些安其拉的虫子都碾碎的话，那么我们现在就得好好准备一下了，这当然包括食物的储备工作！$B$B我们需要收集足够的狼肉来为战争做好准备。我要待在这里进行整理工作，所以我要委托你去杀几条狼，然后把它们的肉烧成瘦狼排给我。你知道该怎么做了吗？ ','把20块瘦狼排交给奥格瑞玛精神谷的血卫士拉尔塔。','你真是个好厨师，$N。那些瘦狼排让我口水直流;
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8613,'部落需要斑点黄尾鱼!','今天是个钓鱼的好日子，你不觉得吗?这样很好，因为我正需要很多的鱼。部落要我负责收集一吨有斑点的黄尾鱼。他们说是安其拉战役需要的。我说我会尽力而为。所以我需要一些帮忙。你会帮我吧，$c?','带20条有斑点的黄尾鱼给奥格玛精神谷的渔夫林度。','喔耶，这真是好东西。我会把它们收好，不会浪费。谢谢你帮我们这样的忙。我想你是个一流的渔夫$g先生:小姐;能钓到这些斑点黄尾鱼。如果你刚好钓到并煮好更多鱼，拿到这里给我;我要让大家都知道你的表现!$B','这么快就带着斑点黄尾鱼回来了吗，$C?你有把它们煮好吧?我们可不想在炎热的沙漠艳阳下给士兵们生鱼吃。') ON DUPLICATE KEY UPDATE Title_loc4='部落需要斑点黄尾鱼!',Details_loc4='今天是个钓鱼的好日子，你不觉得吗?这样很好，因为我正需要很多的鱼。部落要我负责收集一吨有斑点的黄尾鱼。他们说是安其拉战役需要的。我说我会尽力而为。所以我需要一些帮忙。你会帮我吧，$c?',Objectives_loc4='带20条有斑点的黄尾鱼给奥格玛精神谷的渔夫林度。',OfferRewardText_loc4='喔耶，这真是好东西。我会把它们收好，不会浪费。谢谢你帮我们这样的忙。我想你是个一流的渔夫$g先生:小姐;能钓到这些斑点黄尾鱼。如果你刚好钓到并煮好更多鱼，拿到这里给我;我要让大家都知道你的表现!$B',RequestItemsText_loc4='这么快就带着斑点黄尾鱼回来了吗，$C?你有把它们煮好吧?我们可不想在炎热的沙漠艳阳下给士兵们生鱼吃。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8614,'部落需要更多斑点黄尾鱼！','真是钓鱼的好天气，你不这么认为吗，小伙子？这天气真好，我正好需要很多的鱼。部落让我负责收集大量的斑点黄尾鱼。这是为了即将开始的安其拉之战做准备。我告诉他们我会尽力而为的，所以我现在需要一些帮助。你可以帮帮我吗，$c？ ','把20条斑点黄尾鱼交给奥格瑞玛精神谷的渔夫林度。','这是最好的捕获量，$N!很好，很认真的工作。而且也没有骨头。谢谢你为这些斑点黄尾鱼到外面去。如果你又煮了更多的黄尾鱼请快点回到我这里!$B','如你所见，我们仍然需要很多的鱼。安其拉的战士们需要很多食物，所以我要尽所能的弄到所有斑点黄尾鱼。你抓到、煮好它们并带来给我，我会表达我的谢意，还有部落的谢意。') ON DUPLICATE KEY UPDATE Title_loc4='部落需要更多斑点黄尾鱼！',Details_loc4='真是钓鱼的好天气，你不这么认为吗，小伙子？这天气真好，我正好需要很多的鱼。部落让我负责收集大量的斑点黄尾鱼。这是为了即将开始的安其拉之战做准备。我告诉他们我会尽力而为的，所以我现在需要一些帮助。你可以帮帮我吗，$c？ ',Objectives_loc4='把20条斑点黄尾鱼交给奥格瑞玛精神谷的渔夫林度。',OfferRewardText_loc4='这是最好的捕获量，$N!很好，很认真的工作。而且也没有骨头。谢谢你为这些斑点黄尾鱼到外面去。如果你又煮了更多的黄尾鱼请快点回到我这里!$B',RequestItemsText_loc4='如你所见，我们仍然需要很多的鱼。安其拉的战士们需要很多食物，所以我要尽所能的弄到所有斑点黄尾鱼。你抓到、煮好它们并带来给我，我会表达我的谢意，还有部落的谢意。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8615,'部落需要烤鲑鱼!','安其拉之战是一项浩大的工程，$c。这里收集的所有材料，不管是武器要用的金属，还是要吃的食物，所有的东西都一样重要。如果你好几天没吃东西就会没有力气在必要时举起你的斧头。$B$B因此，我们尽量收集食物。我正在收集烤鲑鱼，好保存又营养。你可以帮我这个忙吗，$c?','带20条烤鲑鱼给奥格玛精神谷的图拉·利爪。','谢谢你为战事提供帮忙，$C。很多人都会忽略我们的需要，选择赚取利润。但是他们无法获得部落的感谢，无法像你现在所做的一样。他们的心不是丰盈的，不像你现在的心一样，因为无私的奉献充满骄傲。$B$B我再一次的感谢你。如果你能在我们的准备完成前再次帮助我们，我会在这里等你。$B','你带着烤鲑鱼回来了吗，$C?记住，一定要煮熟的;我们不能用生的鱼。') ON DUPLICATE KEY UPDATE Title_loc4='部落需要烤鲑鱼!',Details_loc4='安其拉之战是一项浩大的工程，$c。这里收集的所有材料，不管是武器要用的金属，还是要吃的食物，所有的东西都一样重要。如果你好几天没吃东西就会没有力气在必要时举起你的斧头。$B$B因此，我们尽量收集食物。我正在收集烤鲑鱼，好保存又营养。你可以帮我这个忙吗，$c?',Objectives_loc4='带20条烤鲑鱼给奥格玛精神谷的图拉·利爪。',OfferRewardText_loc4='谢谢你为战事提供帮忙，$C。很多人都会忽略我们的需要，选择赚取利润。但是他们无法获得部落的感谢，无法像你现在所做的一样。他们的心不是丰盈的，不像你现在的心一样，因为无私的奉献充满骄傲。$B$B我再一次的感谢你。如果你能在我们的准备完成前再次帮助我们，我会在这里等你。$B',RequestItemsText_loc4='你带着烤鲑鱼回来了吗，$C?记住，一定要煮熟的;我们不能用生的鱼。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8616,'部落需要更多烤鲑鱼！','安其拉之战的准备工作是一项浩大的工程，战士。所有的物资都将在这里进行收集，无论是铸造武器所需的金属，还是士兵日常生活所需的食物都非常重要。比如说，如果你几天没有吃东西，那么你一定没有力气挥舞战斧。$B$B因此我们需要收集尽可能多的食物。我在这里负责收集烤鲑鱼，它的口味和营养都非常适合我们的士兵。你能帮帮我吗，战士？  ','把20份烤鲑鱼交给奥格瑞玛精神谷的图拉·利爪。','你为战争奉献的时间和心血难以言喻，$N。我保证你的努力不会白费。致上我的谢意，还有部落的感谢。如果你又烤了另一批鱼，请再次回到我这里。','你捐赠的最后一批烤鲑鱼看起来非常好吃，$C。我承认我真的很想偷留几条。你也看到了，我们尚未达到需要的配额。我希望你快点回来，因为你还要收集另一批烤鲑鱼。') ON DUPLICATE KEY UPDATE Title_loc4='部落需要更多烤鲑鱼！',Details_loc4='安其拉之战的准备工作是一项浩大的工程，战士。所有的物资都将在这里进行收集，无论是铸造武器所需的金属，还是士兵日常生活所需的食物都非常重要。比如说，如果你几天没有吃东西，那么你一定没有力气挥舞战斧。$B$B因此我们需要收集尽可能多的食物。我在这里负责收集烤鲑鱼，它的口味和营养都非常适合我们的士兵。你能帮帮我吗，战士？  ',Objectives_loc4='把20份烤鲑鱼交给奥格瑞玛精神谷的图拉·利爪。',OfferRewardText_loc4='你为战争奉献的时间和心血难以言喻，$N。我保证你的努力不会白费。致上我的谢意，还有部落的感谢。如果你又烤了另一批鱼，请再次回到我这里。',RequestItemsText_loc4='你捐赠的最后一批烤鲑鱼看起来非常好吃，$C。我承认我真的很想偷留几条。你也看到了，我们尚未达到需要的配额。我希望你快点回来，因为你还要收集另一批烤鲑鱼。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4) VALUES (8617,'部落需要熔火之石！','是时候让你为安其拉之战做出贡献了，$c。你不能继续这样游手好闲下去。现在是你为我和部落效劳的时候，而且我可不想酋长那样宽大仁慈。$B$B你必须组织起强大的力量，最好是整个公会的力量，深入熔火之心。在那里，你可以找到很多被称为熔火之石的东西。把它们都交给我。','把50块熔火之石交给奥格瑞玛精神谷的佐格将军。') ON DUPLICATE KEY UPDATE Title_loc4='部落需要熔火之石！',Details_loc4='是时候让你为安其拉之战做出贡献了，$c。你不能继续这样游手好闲下去。现在是你为我和部落效劳的时候，而且我可不想酋长那样宽大仁慈。$B$B你必须组织起强大的力量，最好是整个公会的力量，深入熔火之心。在那里，你可以找到很多被称为熔火之石的东西。把它们都交给我。',Objectives_loc4='把50块熔火之石交给奥格瑞玛精神谷的佐格将军。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8618,'部落需要更多熔火之石！','你再次排除万难证明了自己的价值，$N。很好，我想我会给你另一个机会获得部落的尊敬。给我一些时间清点这些核心石，然后再回来找我。我想叫你再去收集更多的石头。','如果大家都在增加军备，我们早该完成这个任务了。幸好你已经证明了你的能力。部落需要更多像你一样的$C，$N。$B$B你很清楚的看到，我们仍需要更多烧焦的核心石。重新召集你的公会，或是任何人，再次进军熔火之心。没有弄到另一大批烧焦的核心石之前就不要回来找我。') ON DUPLICATE KEY UPDATE Title_loc4='部落需要更多熔火之石！',OfferRewardText_loc4='你再次排除万难证明了自己的价值，$N。很好，我想我会给你另一个机会获得部落的尊敬。给我一些时间清点这些核心石，然后再回来找我。我想叫你再去收集更多的石头。',RequestItemsText_loc4='如果大家都在增加军备，我们早该完成这个任务了。幸好你已经证明了你的能力。部落需要更多像你一样的$C，$N。$B$B你很清楚的看到，我们仍需要更多烧焦的核心石。重新召集你的公会，或是任何人，再次进军熔火之心。没有弄到另一大批烧焦的核心石之前就不要回来找我。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4) VALUES (8619,'黎明长者','很庆幸本地子民仍效忠於古老种族。祝你平安，$N，这是你应有的奖赏……$B') ON DUPLICATE KEY UPDATE Title_loc4='黎明长者',OfferRewardText_loc4='很庆幸本地子民仍效忠於古老种族。祝你平安，$N，这是你应有的奖赏……$B';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8620,'唯一的方案','我就知道，我最大的敌人，维维尔博士又开始玩他那老一套了！现在，由于你在冬泉谷的失败，维维尔把我的书给毁掉了！你现在还怎么拯救世界，大英雄？$B$B我收集到的仅存的《龙语傻瓜教程：第二卷》被撕成8份，散落在世界各地！如果你可以收集到这些遗失的章节，那么就用这个魔法书封面把它们合在一起，然后给我带回来。','把8章《龙语傻瓜教程》的章节用魔法书封面合起来，然后把完整的《龙语傻瓜教程：第二卷》交给塔纳利斯的纳瑞安。','太棒了!真不敢相信你真的突破了那个难题!你是机器吗?换作是我，我可能会让整个世界爆炸。$B$B告诉你，$g先生:女士; 。英勇的行为一定会得到奖励的。$B','我和你一样把裤子穿上 - 一次穿一条腿进去。只不过等你穿好了，我已经在制作奥金浮标了。奥金浮标啊，宝贝!') ON DUPLICATE KEY UPDATE Title_loc4='唯一的方案',Details_loc4='我就知道，我最大的敌人，维维尔博士又开始玩他那老一套了！现在，由于你在冬泉谷的失败，维维尔把我的书给毁掉了！你现在还怎么拯救世界，大英雄？$B$B我收集到的仅存的《龙语傻瓜教程：第二卷》被撕成8份，散落在世界各地！如果你可以收集到这些遗失的章节，那么就用这个魔法书封面把它们合在一起，然后给我带回来。',Objectives_loc4='把8章《龙语傻瓜教程》的章节用魔法书封面合起来，然后把完整的《龙语傻瓜教程：第二卷》交给塔纳利斯的纳瑞安。',OfferRewardText_loc4='太棒了!真不敢相信你真的突破了那个难题!你是机器吗?换作是我，我可能会让整个世界爆炸。$B$B告诉你，$g先生:女士; 。英勇的行为一定会得到奖励的。$B',RequestItemsText_loc4='我和你一样把裤子穿上 - 一次穿一条腿进去。只不过等你穿好了，我已经在制作奥金浮标了。奥金浮标啊，宝贝!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8621,'风暴召唤者的足甲','其拉虫人的魔法古老而又强大，它们最强大的武器甚至可以与龙抗衡。$B$B把其拉统御腕轮和其它辅助材料交给我，我将为你制作一双威力无比的靴子。$B$B你会在与敌人作战的时候发现它所蕴含的力量。','把其拉统御腕轮、2个先知塑像、5个青铜甲虫和5个陶土甲虫交给安其拉的坎多斯特拉兹。你必须首先在诺兹多姆的子嗣中达到中立声望才可以完成这个任务。','你做的很好，$N。你已证明你不是普通的人类。$B$B我把这些东西给你，相信它们可以帮助你击败万恶的其拉虫人。$B','你拿到我所需要的东西了吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='风暴召唤者的足甲',Details_loc4='其拉虫人的魔法古老而又强大，它们最强大的武器甚至可以与龙抗衡。$B$B把其拉统御腕轮和其它辅助材料交给我，我将为你制作一双威力无比的靴子。$B$B你会在与敌人作战的时候发现它所蕴含的力量。',Objectives_loc4='把其拉统御腕轮、2个先知塑像、5个青铜甲虫和5个陶土甲虫交给安其拉的坎多斯特拉兹。你必须首先在诺兹多姆的子嗣中达到中立声望才可以完成这个任务。',OfferRewardText_loc4='你做的很好，$N。你已证明你不是普通的人类。$B$B我把这些东西给你，相信它们可以帮助你击败万恶的其拉虫人。$B',RequestItemsText_loc4='你拿到我所需要的东西了吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8622,'风暴召唤者的护甲','最令人恐怖的上古之神正在从安其拉的休眠之中慢慢醒来。艾泽拉斯世界不久之后即将面对这股恐怖的力量，时间对于如此强大的存在来说毫无意义。$B$B当星辰的位置合适的时候，他将让恐怖的力量席卷所有的一切。你必须在此之前找到他，消灭他。$B$B完成这个任务，把他的外壳交给我。我会奖励你一件凡人从未见到过的护甲……一件只有弑神者才有资格获得的护甲！','把上古之神的外鞘、2个先知塑像、5个银质甲虫和5个白骨甲虫交给安其拉的温瑟拉。你必须在诺兹多姆的子嗣中达到尊敬声望才能完成这个任务。','我没想到你会回来，$N。$B$B你已达到比最不朽的生物还伟大的命运。$B$B杀死克苏恩不只拯救了整个艾泽拉斯，你还削弱了超乎你能理解的宇宙大事。$B$B收下这个胸部铠甲做为光荣的象徵和伴随你行为而来的重担。$B$B愿它的力量能在等待着你的挑战中协助你，弑神者!$B','在安其拉的住所里，可怕的克苏恩在睡眠中等待着。') ON DUPLICATE KEY UPDATE Title_loc4='风暴召唤者的护甲',Details_loc4='最令人恐怖的上古之神正在从安其拉的休眠之中慢慢醒来。艾泽拉斯世界不久之后即将面对这股恐怖的力量，时间对于如此强大的存在来说毫无意义。$B$B当星辰的位置合适的时候，他将让恐怖的力量席卷所有的一切。你必须在此之前找到他，消灭他。$B$B完成这个任务，把他的外壳交给我。我会奖励你一件凡人从未见到过的护甲……一件只有弑神者才有资格获得的护甲！',Objectives_loc4='把上古之神的外鞘、2个先知塑像、5个银质甲虫和5个白骨甲虫交给安其拉的温瑟拉。你必须在诺兹多姆的子嗣中达到尊敬声望才能完成这个任务。',OfferRewardText_loc4='我没想到你会回来，$N。$B$B你已达到比最不朽的生物还伟大的命运。$B$B杀死克苏恩不只拯救了整个艾泽拉斯，你还削弱了超乎你能理解的宇宙大事。$B$B收下这个胸部铠甲做为光荣的象徵和伴随你行为而来的重担。$B$B愿它的力量能在等待着你的挑战中协助你，弑神者!$B',RequestItemsText_loc4='在安其拉的住所里，可怕的克苏恩在睡眠中等待着。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8623,'风暴召唤者的王冠','双子皇帝……他们正向我轻声密语，这折磨着我的神志。他们嘲笑我，他们知道我无法进入神殿的深处去拯救我的兄弟亚雷戈斯。$B$B我可以看见他们狰狞的脸庞，他们头上戴着具有无穷力量的皇冠。但是我必须要报仇……我会把这种代表其拉虫人力量的饰品转化成对我们有利的东西。$B$B把我需要的材料交给我，$N。我会为你制作一顶具有超凡力量的头盔。','把维克洛尔的王冠、2个重生塑像、5个岩石甲虫和5个水晶甲虫交给安其拉的安多葛斯。你必须首先在诺兹多姆的子嗣中达到友善声望才可以完成这个任务。','你成功了!双子帝王的耳语停止了。$B$B收下这个奖励。看它一眼就会在其拉的心中注入恐惧…这会让他们想起死去的领导者还有杀死他们的人类。$B','你把我所要求的材料都带回来了吗， $N?') ON DUPLICATE KEY UPDATE Title_loc4='风暴召唤者的王冠',Details_loc4='双子皇帝……他们正向我轻声密语，这折磨着我的神志。他们嘲笑我，他们知道我无法进入神殿的深处去拯救我的兄弟亚雷戈斯。$B$B我可以看见他们狰狞的脸庞，他们头上戴着具有无穷力量的皇冠。但是我必须要报仇……我会把这种代表其拉虫人力量的饰品转化成对我们有利的东西。$B$B把我需要的材料交给我，$N。我会为你制作一顶具有超凡力量的头盔。',Objectives_loc4='把维克洛尔的王冠、2个重生塑像、5个岩石甲虫和5个水晶甲虫交给安其拉的安多葛斯。你必须首先在诺兹多姆的子嗣中达到友善声望才可以完成这个任务。',OfferRewardText_loc4='你成功了!双子帝王的耳语停止了。$B$B收下这个奖励。看它一眼就会在其拉的心中注入恐惧…这会让他们想起死去的领导者还有杀死他们的人类。$B',RequestItemsText_loc4='你把我所要求的材料都带回来了吗， $N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8624,'风暴召唤者的护腿','你想要向我们证明你的价值吗，凡人？很好，也许我们可以互相帮助。$B$B在传说中，古老的沙虫奥罗是一个非常强大的存在。据说是上古把它创造出来的原因是为了嘲笑生命的软弱。$B$B它的皮肤非常特殊……异常结实，甚至是无法击破的，而它本身的移动速度却不会因此而受到任何妨碍，它和那些小型生物一样动作灵敏。$B$B把它的皮肤样品和其它一些原材料都交给我，我会给你制作一条具有强大力量的护腿。','把巨型沙虫的皮、2个征战塑像、5个青铜甲虫和5个象牙甲虫交给安其拉的坎多斯特拉兹。你必须首先在诺兹多姆的子嗣中达到友善声望才可以完成这个任务。','太好了……虫的皮肤会是很棒的保护层。和我们在路上摧毁的其拉材料结合，这会是个令人畏惧的护甲。愿它协助你面对里面难以言喻的恐怖。$B','你把我需要的材料带来了吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='风暴召唤者的护腿',Details_loc4='你想要向我们证明你的价值吗，凡人？很好，也许我们可以互相帮助。$B$B在传说中，古老的沙虫奥罗是一个非常强大的存在。据说是上古把它创造出来的原因是为了嘲笑生命的软弱。$B$B它的皮肤非常特殊……异常结实，甚至是无法击破的，而它本身的移动速度却不会因此而受到任何妨碍，它和那些小型生物一样动作灵敏。$B$B把它的皮肤样品和其它一些原材料都交给我，我会给你制作一条具有强大力量的护腿。',Objectives_loc4='把巨型沙虫的皮、2个征战塑像、5个青铜甲虫和5个象牙甲虫交给安其拉的坎多斯特拉兹。你必须首先在诺兹多姆的子嗣中达到友善声望才可以完成这个任务。',OfferRewardText_loc4='太好了……虫的皮肤会是很棒的保护层。和我们在路上摧毁的其拉材料结合，这会是个令人畏惧的护甲。愿它协助你面对里面难以言喻的恐怖。$B',RequestItemsText_loc4='你把我需要的材料带来了吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8625,'神秘肩垫','据说凡人所穿着的绚丽护肩是他们用来模仿龙翼的。$B$B把其拉虫人的最高领袖所佩戴的腕轮交给我，我会用它来制作一副比奈法利安的双翼还要可怕的护肩！','把其拉命令腕轮、2个死亡塑像、5个岩石甲虫和5个青铜甲虫交给安其拉的安多葛斯。你必须首先在诺兹多姆的子嗣中达到中立声望才可以完成这个任务。','我用你带来的材料和其拉虫人的鳞片制成了这套肩铠，凡人。希望它们能给你适时的保护也能让我们的敌人尝到恐惧的滋味。$B','你收集好我要的材料了吗?') ON DUPLICATE KEY UPDATE Title_loc4='神秘肩垫',Details_loc4='据说凡人所穿着的绚丽护肩是他们用来模仿龙翼的。$B$B把其拉虫人的最高领袖所佩戴的腕轮交给我，我会用它来制作一副比奈法利安的双翼还要可怕的护肩！',Objectives_loc4='把其拉命令腕轮、2个死亡塑像、5个岩石甲虫和5个青铜甲虫交给安其拉的安多葛斯。你必须首先在诺兹多姆的子嗣中达到中立声望才可以完成这个任务。',OfferRewardText_loc4='我用你带来的材料和其拉虫人的鳞片制成了这套肩铠，凡人。希望它们能给你适时的保护也能让我们的敌人尝到恐惧的滋味。$B',RequestItemsText_loc4='你收集好我要的材料了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8626,'攻击者的足甲','其拉虫人的魔法古老而又强大，它们最强大的武器甚至可以与龙抗衡。$B$B把其拉统御腕轮和其它辅助材料交给我，我将为你制作一双威力无比的靴子。$B$B你会在与敌人作战的时候发现它所蕴含的力量。','把其拉命令腕轮、2个生命塑像、5个岩石甲虫和5个白骨甲虫交给安其拉的坎多斯特拉兹。你必须首先在诺兹多姆的子嗣中达到中立声望才可以完成这个任务。','你做的很好，$N。你已证明你不是普通的人类。$B$B我把这些东西给你，相信它们可以帮助你击败万恶的其拉虫人。','你拿到我所需要的东西了吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='攻击者的足甲',Details_loc4='其拉虫人的魔法古老而又强大，它们最强大的武器甚至可以与龙抗衡。$B$B把其拉统御腕轮和其它辅助材料交给我，我将为你制作一双威力无比的靴子。$B$B你会在与敌人作战的时候发现它所蕴含的力量。',Objectives_loc4='把其拉命令腕轮、2个生命塑像、5个岩石甲虫和5个白骨甲虫交给安其拉的坎多斯特拉兹。你必须首先在诺兹多姆的子嗣中达到中立声望才可以完成这个任务。',OfferRewardText_loc4='你做的很好，$N。你已证明你不是普通的人类。$B$B我把这些东西给你，相信它们可以帮助你击败万恶的其拉虫人。',RequestItemsText_loc4='你拿到我所需要的东西了吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8627,'复仇者的胸甲','最令人恐怖的上古之神正在从安其拉的休眠之中慢慢醒来。艾泽拉斯世界不久之后即将面对这股恐怖的力量，时间对于如此强大的存在来说毫无意义。$B$B当星辰的位置合适的时候，他将让恐怖的力量席卷所有的一切。你必须在此之前找到他，消灭他。$B$B完成这个任务，把他的外壳交给我。我会奖励你一件凡人从未见到过的护甲……一件只有弑神者才有资格获得的护甲！','把上古之神的外鞘、2个先知塑像、5个银质甲虫和5个白骨甲虫交给安其拉的温瑟拉。','我没想到你会回来，$N。$B$B你已达到比最不朽的生物还伟大的命运。$B$B杀死克苏恩不只拯救了整个艾泽拉斯，你还削弱了超乎你能理解的宇宙大事。$B$B收下这个胸部铠甲做为光荣的象徵和伴随你行为而来的重担。$B$B愿它的力量能在等待着你的挑战中协助你，弑神者!$B','在安其拉的住所里，可怕的克苏恩在睡眠中等待着。') ON DUPLICATE KEY UPDATE Title_loc4='复仇者的胸甲',Details_loc4='最令人恐怖的上古之神正在从安其拉的休眠之中慢慢醒来。艾泽拉斯世界不久之后即将面对这股恐怖的力量，时间对于如此强大的存在来说毫无意义。$B$B当星辰的位置合适的时候，他将让恐怖的力量席卷所有的一切。你必须在此之前找到他，消灭他。$B$B完成这个任务，把他的外壳交给我。我会奖励你一件凡人从未见到过的护甲……一件只有弑神者才有资格获得的护甲！',Objectives_loc4='把上古之神的外鞘、2个先知塑像、5个银质甲虫和5个白骨甲虫交给安其拉的温瑟拉。',OfferRewardText_loc4='我没想到你会回来，$N。$B$B你已达到比最不朽的生物还伟大的命运。$B$B杀死克苏恩不只拯救了整个艾泽拉斯，你还削弱了超乎你能理解的宇宙大事。$B$B收下这个胸部铠甲做为光荣的象徵和伴随你行为而来的重担。$B$B愿它的力量能在等待着你的挑战中协助你，弑神者!$B',RequestItemsText_loc4='在安其拉的住所里，可怕的克苏恩在睡眠中等待着。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8628,'复仇者的王冠','双子皇帝……他们正向我轻声密语，这折磨着我的神志。他们嘲笑我，他们知道我无法进入神殿的深处去拯救我的兄弟亚雷戈斯。$B$B我可以看见他们狰狞的脸庞，他们头上戴着具有无穷力量的皇冠。但是我必须要报仇……我会把这种代表其拉虫人力量的饰品转化成对我们有利的东西。$B$B把我需要的材料交给我，$N。我会为你制作一顶具有超凡力量的头盔。','把维克洛尔的王冠、2个重生塑像、5个岩石甲虫和5个水晶甲虫交给安其拉的安多葛斯。你必须首先在诺兹多姆的子嗣中达到友善声望才可以完成这个任务。','你成功了!双子帝王的耳语停止了。$B$B收下这个奖励。看它一眼就会在其拉的心中注入恐惧…这会让他们想起死去的领导者还有杀死他们的人类。$B','你把我所要求的材料都带回来了吗， $N?') ON DUPLICATE KEY UPDATE Title_loc4='复仇者的王冠',Details_loc4='双子皇帝……他们正向我轻声密语，这折磨着我的神志。他们嘲笑我，他们知道我无法进入神殿的深处去拯救我的兄弟亚雷戈斯。$B$B我可以看见他们狰狞的脸庞，他们头上戴着具有无穷力量的皇冠。但是我必须要报仇……我会把这种代表其拉虫人力量的饰品转化成对我们有利的东西。$B$B把我需要的材料交给我，$N。我会为你制作一顶具有超凡力量的头盔。',Objectives_loc4='把维克洛尔的王冠、2个重生塑像、5个岩石甲虫和5个水晶甲虫交给安其拉的安多葛斯。你必须首先在诺兹多姆的子嗣中达到友善声望才可以完成这个任务。',OfferRewardText_loc4='你成功了!双子帝王的耳语停止了。$B$B收下这个奖励。看它一眼就会在其拉的心中注入恐惧…这会让他们想起死去的领导者还有杀死他们的人类。$B',RequestItemsText_loc4='你把我所要求的材料都带回来了吗， $N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8629,'复仇者的护腿','你想要向我们证明你的价值吗，凡人？很好，也许我们可以互相帮助。$B$B在传说中，古老的沙虫奥罗是一个非常强大的存在。据说是上古把它创造出来的原因是为了嘲笑生命的软弱。$B$B它的皮肤非常特殊……异常结实，甚至是无法击破的，而它本身的移动速度却不会因此而受到任何妨碍，它和那些小型生物一样动作灵敏。$B$B把它的皮肤样品和其它一些原材料都交给我，我会给你制作一条具有强大力量的护腿。','把巨型沙虫的皮、2个征战塑像、5个青铜甲虫和5个象牙甲虫交给安其拉的坎多斯特拉兹。你必须首先在诺兹多姆的子嗣中达到友善声望才可以完成这个任务。','太好了……虫的皮肤会是很棒的保护层。和我们在路上摧毁的其拉材料结合，这会是个令人畏惧的护甲。愿它协助你面对里面难以言喻的恐怖。$B','你把我需要的材料带来了吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='复仇者的护腿',Details_loc4='你想要向我们证明你的价值吗，凡人？很好，也许我们可以互相帮助。$B$B在传说中，古老的沙虫奥罗是一个非常强大的存在。据说是上古把它创造出来的原因是为了嘲笑生命的软弱。$B$B它的皮肤非常特殊……异常结实，甚至是无法击破的，而它本身的移动速度却不会因此而受到任何妨碍，它和那些小型生物一样动作灵敏。$B$B把它的皮肤样品和其它一些原材料都交给我，我会给你制作一条具有强大力量的护腿。',Objectives_loc4='把巨型沙虫的皮、2个征战塑像、5个青铜甲虫和5个象牙甲虫交给安其拉的坎多斯特拉兹。你必须首先在诺兹多姆的子嗣中达到友善声望才可以完成这个任务。',OfferRewardText_loc4='太好了……虫的皮肤会是很棒的保护层。和我们在路上摧毁的其拉材料结合，这会是个令人畏惧的护甲。愿它协助你面对里面难以言喻的恐怖。$B',RequestItemsText_loc4='你把我需要的材料带来了吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8630,'复仇者的护肩','据说凡人所穿着的绚丽护肩是他们用来模仿龙翼的。$B$B把其拉虫人的最高领袖所佩戴的腕轮交给我，我会用它来制作一副比奈法利安的双翼还要可怕的护肩！','把其拉统御腕轮、2个生命塑像、5个水晶甲虫和5个黄金甲虫交给安其拉的安多葛斯。你必须首先在诺兹多姆的子嗣中达到中立声望才可以完成这个任务。','我用你带来的材料和其拉虫人的鳞片制成了这套肩铠，凡人。希望它们能给你适时的保护也能让我们的敌人尝到恐惧的滋味。$B','你收集好我要的材料了吗?') ON DUPLICATE KEY UPDATE Title_loc4='复仇者的护肩',Details_loc4='据说凡人所穿着的绚丽护肩是他们用来模仿龙翼的。$B$B把其拉虫人的最高领袖所佩戴的腕轮交给我，我会用它来制作一副比奈法利安的双翼还要可怕的护肩！',Objectives_loc4='把其拉统御腕轮、2个生命塑像、5个水晶甲虫和5个黄金甲虫交给安其拉的安多葛斯。你必须首先在诺兹多姆的子嗣中达到中立声望才可以完成这个任务。',OfferRewardText_loc4='我用你带来的材料和其拉虫人的鳞片制成了这套肩铠，凡人。希望它们能给你适时的保护也能让我们的敌人尝到恐惧的滋味。$B',RequestItemsText_loc4='你收集好我要的材料了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8631,'神秘护腿','你想要向我们证明你的价值吗，凡人？很好，也许我们可以互相帮助。$B$B在传说中，古老的沙虫奥罗是一个非常强大的存在。据说是上古把它创造出来的原因是为了嘲笑生命的软弱。$B$B它的皮肤非常特殊……异常结实，甚至是无法击破的，而它本身的移动速度却不会因此而受到任何妨碍，它和那些小型生物一样动作灵敏。$B$B把它的皮肤样品和其它一些原材料都交给我，我会给你制作一条具有强大力量的护腿。','把奥罗的外皮、2个先知塑像、5个银质甲虫和5个白骨甲虫交给安其拉的坎多斯特拉兹。你必须首先在诺兹多姆的子嗣中达到友善声望才可以完成这个任务。','太好了……虫的皮肤会是很棒的保护层。和我们在路上摧毁的其拉材料结合，这会是个令人畏惧的护甲。愿它协助你面对里面难以言喻的恐怖。$B','你把我需要的材料带来了吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='神秘护腿',Details_loc4='你想要向我们证明你的价值吗，凡人？很好，也许我们可以互相帮助。$B$B在传说中，古老的沙虫奥罗是一个非常强大的存在。据说是上古把它创造出来的原因是为了嘲笑生命的软弱。$B$B它的皮肤非常特殊……异常结实，甚至是无法击破的，而它本身的移动速度却不会因此而受到任何妨碍，它和那些小型生物一样动作灵敏。$B$B把它的皮肤样品和其它一些原材料都交给我，我会给你制作一条具有强大力量的护腿。',Objectives_loc4='把奥罗的外皮、2个先知塑像、5个银质甲虫和5个白骨甲虫交给安其拉的坎多斯特拉兹。你必须首先在诺兹多姆的子嗣中达到友善声望才可以完成这个任务。',OfferRewardText_loc4='太好了……虫的皮肤会是很棒的保护层。和我们在路上摧毁的其拉材料结合，这会是个令人畏惧的护甲。愿它协助你面对里面难以言喻的恐怖。$B',RequestItemsText_loc4='你把我需要的材料带来了吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8632,'神秘头饰','双子皇帝……他们正向我轻声密语，这折磨着我的神志。他们嘲笑我，他们知道我无法进入神殿的深处去拯救我的兄弟亚雷戈斯。$B$B我可以看见他们狰狞的脸庞，他们头上戴着具有无穷力量的皇冠。但是我必须要报仇……我会把这种代表其拉虫人力量的饰品转化成对我们有利的东西。$B$B把我需要的材料交给我，$N。我会为你制作一顶具有超凡力量的头盔。','把维克尼拉斯的头饰、2个夜晚塑像、5个青铜甲虫和5个象牙甲虫交给安其拉的安多葛斯。你必须首先在诺兹多姆的子嗣中达到友善声望才可以完成这个任务。','你成功了!双子帝王的耳语停止了。$B$B收下这个奖励。看它一眼就会在其拉的心中注入恐惧…这会让他们想起死去的领导者还有杀死他们的人类。$B','你把我所要求的材料都带回来了吗， $N?') ON DUPLICATE KEY UPDATE Title_loc4='神秘头饰',Details_loc4='双子皇帝……他们正向我轻声密语，这折磨着我的神志。他们嘲笑我，他们知道我无法进入神殿的深处去拯救我的兄弟亚雷戈斯。$B$B我可以看见他们狰狞的脸庞，他们头上戴着具有无穷力量的皇冠。但是我必须要报仇……我会把这种代表其拉虫人力量的饰品转化成对我们有利的东西。$B$B把我需要的材料交给我，$N。我会为你制作一顶具有超凡力量的头盔。',Objectives_loc4='把维克尼拉斯的头饰、2个夜晚塑像、5个青铜甲虫和5个象牙甲虫交给安其拉的安多葛斯。你必须首先在诺兹多姆的子嗣中达到友善声望才可以完成这个任务。',OfferRewardText_loc4='你成功了!双子帝王的耳语停止了。$B$B收下这个奖励。看它一眼就会在其拉的心中注入恐惧…这会让他们想起死去的领导者还有杀死他们的人类。$B',RequestItemsText_loc4='你把我所要求的材料都带回来了吗， $N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8633,'神秘长袍','最令人恐怖的上古之神正在从安其拉的休眠之中慢慢醒来。艾泽拉斯世界不久之后即将面对这股恐怖的力量，时间对于如此强大的存在来说毫无意义。$B$B当星辰的位置合适的时候，他将让恐怖的力量席卷所有的一切。你必须在此之前找到他，消灭他。$B$B完成这个任务，把他的外壳交给我。我会奖励你一件凡人从未见到过的护甲……一件只有弑神者才有资格获得的护甲！','把上古之神的外鞘、2个太阳塑像、5个黄金甲虫和5个陶土甲虫交给安其拉的温瑟拉。你必须在诺兹多姆的子嗣中达到尊敬声望才能完成这个任务。','我没想到你会回来，$N。$B$B你已达到比最不朽的生物还伟大的命运。$B$B杀死克苏恩不只拯救了整个艾泽拉斯，你还削弱了超乎你能理解的宇宙大事。$B$B收下这个长袍做为光荣的象徵和伴随你行为而来的重担。$B$B愿它的力量能在等待着你的挑战中协助你，弑神者!$B','在安其拉的住所里，可怕的克苏恩在睡眠中等待着。') ON DUPLICATE KEY UPDATE Title_loc4='神秘长袍',Details_loc4='最令人恐怖的上古之神正在从安其拉的休眠之中慢慢醒来。艾泽拉斯世界不久之后即将面对这股恐怖的力量，时间对于如此强大的存在来说毫无意义。$B$B当星辰的位置合适的时候，他将让恐怖的力量席卷所有的一切。你必须在此之前找到他，消灭他。$B$B完成这个任务，把他的外壳交给我。我会奖励你一件凡人从未见到过的护甲……一件只有弑神者才有资格获得的护甲！',Objectives_loc4='把上古之神的外鞘、2个太阳塑像、5个黄金甲虫和5个陶土甲虫交给安其拉的温瑟拉。你必须在诺兹多姆的子嗣中达到尊敬声望才能完成这个任务。',OfferRewardText_loc4='我没想到你会回来，$N。$B$B你已达到比最不朽的生物还伟大的命运。$B$B杀死克苏恩不只拯救了整个艾泽拉斯，你还削弱了超乎你能理解的宇宙大事。$B$B收下这个长袍做为光荣的象徵和伴随你行为而来的重担。$B$B愿它的力量能在等待着你的挑战中协助你，弑神者!$B',RequestItemsText_loc4='在安其拉的住所里，可怕的克苏恩在睡眠中等待着。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8634,'神秘长靴','其拉虫人的魔法古老而又强大，它们最强大的武器甚至可以与龙抗衡。$B$B把其拉统御腕轮和其它辅助材料交给我，我将为你制作一双威力无比的靴子。$B$B你会在与敌人作战的时候发现它所蕴含的力量。','把其拉统御腕轮、2个太阳塑像、5个银质甲虫和5个青铜甲虫交给安其拉的坎多斯特拉兹。你必须首先在诺兹多姆的子嗣中达到中立声望才可以完成这个任务。','你做的很好，$N。你已证明你不是普通的人类。$B$B我把这些东西给你，相信你可以帮助我们击败万恶的其拉虫人。$B','你拿到我所需要的东西了吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='神秘长靴',Details_loc4='其拉虫人的魔法古老而又强大，它们最强大的武器甚至可以与龙抗衡。$B$B把其拉统御腕轮和其它辅助材料交给我，我将为你制作一双威力无比的靴子。$B$B你会在与敌人作战的时候发现它所蕴含的力量。',Objectives_loc4='把其拉统御腕轮、2个太阳塑像、5个银质甲虫和5个青铜甲虫交给安其拉的坎多斯特拉兹。你必须首先在诺兹多姆的子嗣中达到中立声望才可以完成这个任务。',OfferRewardText_loc4='你做的很好，$N。你已证明你不是普通的人类。$B$B我把这些东西给你，相信你可以帮助我们击败万恶的其拉虫人。$B',RequestItemsText_loc4='你拿到我所需要的东西了吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4) VALUES (8635,'碎石长者','战争的历史是传奇茁壮的种子。你正处于英雄的时代，年轻人。愿你的英勇传奇深植人心、源远流长。$B$B祝你平安， $N，这是你应有的奖赏……$B') ON DUPLICATE KEY UPDATE Title_loc4='碎石长者',OfferRewardText_loc4='战争的历史是传奇茁壮的种子。你正处于英雄的时代，年轻人。愿你的英勇传奇深植人心、源远流长。$B$B祝你平安， $N，这是你应有的奖赏……$B';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4) VALUES (8636,'巨石长者','万物皆难逃一死，但精神却永垂不朽。祝你平安， $N，这是给你的奖赏……') ON DUPLICATE KEY UPDATE Title_loc4='巨石长者',OfferRewardText_loc4='万物皆难逃一死，但精神却永垂不朽。祝你平安， $N，这是给你的奖赏……';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8637,'死亡执行者的长靴','其拉虫人的魔法古老而又强大，它们最强大的武器甚至可以与龙抗衡。$B$B把其拉统御腕轮和其它辅助材料交给我，我将为你制作一双威力无比的靴子。$B$B你会在与敌人作战的时候发现它所蕴含的力量。','把其拉统御腕轮、2个先知塑像、5个水晶甲虫和5个白骨甲虫交给安其拉的坎多斯特拉兹。你必须首先在诺兹多姆的子嗣中达到中立声望才可以完成这个任务。','你做的很好，$N。你已证明你不是普通的人类。$B$B我把这些东西给你，相信你可以帮助我们击败万恶的其拉虫人。$B','你拿到我所需要的东西了吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='死亡执行者的长靴',Details_loc4='其拉虫人的魔法古老而又强大，它们最强大的武器甚至可以与龙抗衡。$B$B把其拉统御腕轮和其它辅助材料交给我，我将为你制作一双威力无比的靴子。$B$B你会在与敌人作战的时候发现它所蕴含的力量。',Objectives_loc4='把其拉统御腕轮、2个先知塑像、5个水晶甲虫和5个白骨甲虫交给安其拉的坎多斯特拉兹。你必须首先在诺兹多姆的子嗣中达到中立声望才可以完成这个任务。',OfferRewardText_loc4='你做的很好，$N。你已证明你不是普通的人类。$B$B我把这些东西给你，相信你可以帮助我们击败万恶的其拉虫人。$B',RequestItemsText_loc4='你拿到我所需要的东西了吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8638,'死亡执行者的胸甲','最令人恐怖的上古之神正在从安其拉的休眠之中慢慢醒来。艾泽拉斯世界不久之后即将面对这股恐怖的力量，时间对于如此强大的存在来说毫无意义。$B$B当星辰的位置合适的时候，他将让恐怖的力量席卷所有的一切。你必须在此之前找到他，消灭他。$B$B完成这个任务，把他的外壳交给我。我会奖励你一件凡人从未见到过的护甲……一件只有弑神者才有资格获得的护甲！','把上古之神的外鞘、2个征战塑像、5个青铜甲虫和5个象牙甲虫交给安其拉的温瑟拉。','我没想到你会回来，$N。$B$B你已达到比最不朽的生物还伟大的命运。$B$B杀死克苏恩不只拯救了整个艾泽拉斯，你还削弱了超乎你能理解的宇宙大事。$B$B收下这个胸部铠甲做为光荣的象徵和伴随你行为而来的重担。$B$B愿它的力量能在等待着你的挑战中协助你，弑神者!$B','在安其拉的住所里，可怕的克苏恩在睡眠中等待着。') ON DUPLICATE KEY UPDATE Title_loc4='死亡执行者的胸甲',Details_loc4='最令人恐怖的上古之神正在从安其拉的休眠之中慢慢醒来。艾泽拉斯世界不久之后即将面对这股恐怖的力量，时间对于如此强大的存在来说毫无意义。$B$B当星辰的位置合适的时候，他将让恐怖的力量席卷所有的一切。你必须在此之前找到他，消灭他。$B$B完成这个任务，把他的外壳交给我。我会奖励你一件凡人从未见到过的护甲……一件只有弑神者才有资格获得的护甲！',Objectives_loc4='把上古之神的外鞘、2个征战塑像、5个青铜甲虫和5个象牙甲虫交给安其拉的温瑟拉。',OfferRewardText_loc4='我没想到你会回来，$N。$B$B你已达到比最不朽的生物还伟大的命运。$B$B杀死克苏恩不只拯救了整个艾泽拉斯，你还削弱了超乎你能理解的宇宙大事。$B$B收下这个胸部铠甲做为光荣的象徵和伴随你行为而来的重担。$B$B愿它的力量能在等待着你的挑战中协助你，弑神者!$B',RequestItemsText_loc4='在安其拉的住所里，可怕的克苏恩在睡眠中等待着。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8639,'死亡执行者的头盔','双子皇帝……他们正向我轻声密语，这折磨着我的神志。他们嘲笑我，他们知道我无法进入神殿的深处去拯救我的兄弟亚雷戈斯。$B$B我可以看见他们狰狞的脸庞，他们头上戴着具有无穷力量的皇冠。但是我必须要报仇……我会把这种代表其拉虫人力量的饰品转化成对我们有利的东西。$B$B把我需要的材料交给我，$N。我会为你制作一顶具有超凡力量的头盔。','把维克洛尔的王冠、2个战争塑像、5个黄金甲虫和5个陶土甲虫交给安其拉的安多葛斯。你必须首先在诺兹多姆的子嗣中达到友善声望才可以完成这个任务。','你成功了!双子帝王的耳语停止了。$B$B收下这个奖励。看它一眼就会在其拉的心中注入恐惧…这会让他们想起死去的领导者还有杀死他们的人类。$B','你把我所要求的材料都带回来了吗， $N?') ON DUPLICATE KEY UPDATE Title_loc4='死亡执行者的头盔',Details_loc4='双子皇帝……他们正向我轻声密语，这折磨着我的神志。他们嘲笑我，他们知道我无法进入神殿的深处去拯救我的兄弟亚雷戈斯。$B$B我可以看见他们狰狞的脸庞，他们头上戴着具有无穷力量的皇冠。但是我必须要报仇……我会把这种代表其拉虫人力量的饰品转化成对我们有利的东西。$B$B把我需要的材料交给我，$N。我会为你制作一顶具有超凡力量的头盔。',Objectives_loc4='把维克洛尔的王冠、2个战争塑像、5个黄金甲虫和5个陶土甲虫交给安其拉的安多葛斯。你必须首先在诺兹多姆的子嗣中达到友善声望才可以完成这个任务。',OfferRewardText_loc4='你成功了!双子帝王的耳语停止了。$B$B收下这个奖励。看它一眼就会在其拉的心中注入恐惧…这会让他们想起死去的领导者还有杀死他们的人类。$B',RequestItemsText_loc4='你把我所要求的材料都带回来了吗， $N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8640,'死亡执行者的护腿','你想要向我们证明你的价值吗，凡人？很好，也许我们可以互相帮助。$B$B在传说中，古老的沙虫奥罗是一个非常强大的存在。据说是上古把它创造出来的原因是为了嘲笑生命的软弱。$B$B它的皮肤非常特殊……异常结实，甚至是无法击破的，而它本身的移动速度却不会因此而受到任何妨碍，它和那些小型生物一样动作灵敏。$B$B把它的皮肤样品和其它一些原材料都交给我，我会给你制作一条具有强大力量的护腿。','把奥罗的外皮、2个夜晚塑像、5个岩石甲虫和5个水晶甲虫交给安其拉的坎多斯特拉兹。你必须首先在诺兹多姆的子嗣中达到友善声望才可以完成这个任务。','太好了……虫的皮肤会是很棒的保护层。和我们在路上摧毁的其拉材料结合，这会是个令人畏惧的护甲。愿它协助你面对里面难以言喻的恐怖。$B','你把我需要的材料带来了吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='死亡执行者的护腿',Details_loc4='你想要向我们证明你的价值吗，凡人？很好，也许我们可以互相帮助。$B$B在传说中，古老的沙虫奥罗是一个非常强大的存在。据说是上古把它创造出来的原因是为了嘲笑生命的软弱。$B$B它的皮肤非常特殊……异常结实，甚至是无法击破的，而它本身的移动速度却不会因此而受到任何妨碍，它和那些小型生物一样动作灵敏。$B$B把它的皮肤样品和其它一些原材料都交给我，我会给你制作一条具有强大力量的护腿。',Objectives_loc4='把奥罗的外皮、2个夜晚塑像、5个岩石甲虫和5个水晶甲虫交给安其拉的坎多斯特拉兹。你必须首先在诺兹多姆的子嗣中达到友善声望才可以完成这个任务。',OfferRewardText_loc4='太好了……虫的皮肤会是很棒的保护层。和我们在路上摧毁的其拉材料结合，这会是个令人畏惧的护甲。愿它协助你面对里面难以言喻的恐怖。$B',RequestItemsText_loc4='你把我需要的材料带来了吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8641,'死亡执行者的护肩','据说凡人所穿着的绚丽护肩是他们用来模仿龙翼的。$B$B把其拉虫人的最高领袖所佩戴的腕轮交给我，我会用它来制作一副比奈法利安的双翼还要可怕的护肩！','把其拉命令腕轮、2个太阳塑像、5个银质甲虫和5个陶土甲虫交给安其拉的安多葛斯。你必须首先在诺兹多姆的子嗣中达到中立声望才可以完成这个任务。','我用你带来的材料和其拉虫人的鳞片制成了这套肩铠，凡人。希望它们能给你适时的保护也能让我们的敌人尝到恐惧的滋味。$B','你收集好我要的材料了吗?') ON DUPLICATE KEY UPDATE Title_loc4='死亡执行者的护肩',Details_loc4='据说凡人所穿着的绚丽护肩是他们用来模仿龙翼的。$B$B把其拉虫人的最高领袖所佩戴的腕轮交给我，我会用它来制作一副比奈法利安的双翼还要可怕的护肩！',Objectives_loc4='把其拉命令腕轮、2个太阳塑像、5个银质甲虫和5个陶土甲虫交给安其拉的安多葛斯。你必须首先在诺兹多姆的子嗣中达到中立声望才可以完成这个任务。',OfferRewardText_loc4='我用你带来的材料和其拉虫人的鳞片制成了这套肩铠，凡人。希望它们能给你适时的保护也能让我们的敌人尝到恐惧的滋味。$B',RequestItemsText_loc4='你收集好我要的材料了吗?';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4) VALUES (8642,'银脉长者','很庆幸本地子民仍效忠於古老种族。祝你平安，$N，这是你应有的奖赏……$B') ON DUPLICATE KEY UPDATE Title_loc4='银脉长者',OfferRewardText_loc4='很庆幸本地子民仍效忠於古老种族。祝你平安，$N，这是你应有的奖赏……$B';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4) VALUES (8643,'雪峰长者','很庆幸这片大地的居民仍然会对古老的种族表达敬意。我祝你平安，$N，并且送你这个硬币……') ON DUPLICATE KEY UPDATE Title_loc4='雪峰长者',OfferRewardText_loc4='很庆幸这片大地的居民仍然会对古老的种族表达敬意。我祝你平安，$N，并且送你这个硬币……';
