INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8687,'目标：佐拉坑道蝎','我们需要援军进攻佐拉虫巢。你的主要目标是那些佐拉坑道蝎，当你的任务完成之后就去向指挥官玛尔利斯报告。','击杀40只佐拉坑道蝎。','做的好，$N。少了他们的坑道蠍，异种蠍就很难修补他们虫巢结构所受的伤害。我猜你想要一个新任务。$B','你有事要告诉我吗，$C?') ON DUPLICATE KEY UPDATE Title_loc4='目标：佐拉坑道蝎',Details_loc4='我们需要援军进攻佐拉虫巢。你的主要目标是那些佐拉坑道蝎，当你的任务完成之后就去向指挥官玛尔利斯报告。',Objectives_loc4='击杀40只佐拉坑道蝎。',OfferRewardText_loc4='做的好，$N。少了他们的坑道蠍，异种蠍就很难修补他们虫巢结构所受的伤害。我猜你想要一个新任务。$B',RequestItemsText_loc4='你有事要告诉我吗，$C?';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4) VALUES (8688,'风路长者','天堂，在他们数不尽的星星中有着世间神秘事物的答案，$N。强大，有智慧，幸运的人，能够抬头盯着天空找到答案?$B') ON DUPLICATE KEY UPDATE Title_loc4='风路长者',OfferRewardText_loc4='天堂，在他们数不尽的星星中有着世间神秘事物的答案，$N。强大，有智慧，幸运的人，能够抬头盯着天空找到答案?$B';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8689,'无尽智慧披风','我很高兴听说你愿意帮助我们进攻安其拉，$N。我可以制作一件装备，让你在作战时获得一些保护，$c。$B$B我需要一件其拉斗篷，然后把它按照你的体型进行修改。我还需要其拉塑像和圣甲虫，这样我才能制作合适的扣子。$B$B我保证你一定不会失望的。','将1件其拉军用披风、2个翠玉雕像、5个黄金甲虫和5个陶土甲虫交给凯伊·迅爪。你必须在塞纳里奥议会中达到崇敬声望才能完成这个任务。','啊，太好了……这件披氅非常完美。$B$B拿着这个披氅，$N。愿它保护你对抗其拉虫人的邪恶魔法。$B','你帮我带来了披风的材料吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='无尽智慧披风',Details_loc4='我很高兴听说你愿意帮助我们进攻安其拉，$N。我可以制作一件装备，让你在作战时获得一些保护，$c。$B$B我需要一件其拉斗篷，然后把它按照你的体型进行修改。我还需要其拉塑像和圣甲虫，这样我才能制作合适的扣子。$B$B我保证你一定不会失望的。',Objectives_loc4='将1件其拉军用披风、2个翠玉雕像、5个黄金甲虫和5个陶土甲虫交给凯伊·迅爪。你必须在塞纳里奥议会中达到崇敬声望才能完成这个任务。',OfferRewardText_loc4='啊，太好了……这件披氅非常完美。$B$B拿着这个披氅，$N。愿它保护你对抗其拉虫人的邪恶魔法。$B',RequestItemsText_loc4='你帮我带来了披风的材料吗，$N?';
