INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8756,'其拉虫人的征服者','起身吧，其拉的征服者!让世人看到你的力量!$B','我从没看过这样不屈不挠的人!青铜龙军团将给你最后的附魔强化。这是永恒之王本人的希望!$B$B将你的徽记之戒交给我，这样我才能做些必要的调整。') ON DUPLICATE KEY UPDATE Title_loc4='其拉虫人的征服者',OfferRewardText_loc4='起身吧，其拉的征服者!让世人看到你的力量!$B',RequestItemsText_loc4='我从没看过这样不屈不挠的人!青铜龙军团将给你最后的附魔强化。这是永恒之王本人的希望!$B$B将你的徽记之戒交给我，这样我才能做些必要的调整。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4) VALUES (8757,'祈求者之路','相当出色，小家伙。你吃了不少苦才获得青铜龙军团的青睐。你的奉献令人印象深刻。$B$B塑能师的徽记之戒将会大大提升你的魔法和自然能力。$B$B提高警觉，一旦你选择了你的道路，就无法回头了。') ON DUPLICATE KEY UPDATE Title_loc4='祈求者之路',OfferRewardText_loc4='相当出色，小家伙。你吃了不少苦才获得青铜龙军团的青睐。你的奉献令人印象深刻。$B$B塑能师的徽记之戒将会大大提升你的魔法和自然能力。$B$B提高警觉，一旦你选择了你的道路，就无法回头了。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4) VALUES (8758,'祈求者之路','相当出色，小家伙。你吃了不少苦才获得青铜龙军团的青睐。你的奉献令人印象深刻。$B$B塑能师的徽记之戒将会大大提升你的魔法和自然能力。$B$B提高警觉，一旦你选择了你的道路，就无法回头了。') ON DUPLICATE KEY UPDATE Title_loc4='祈求者之路',OfferRewardText_loc4='相当出色，小家伙。你吃了不少苦才获得青铜龙军团的青睐。你的奉献令人印象深刻。$B$B塑能师的徽记之戒将会大大提升你的魔法和自然能力。$B$B提高警觉，一旦你选择了你的道路，就无法回头了。';
