INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4) VALUES (8760,'祈求者之路','相当出色，小家伙。你吃了不少苦才获得青铜龙军团的青睐。你的奉献令人印象深刻。$B$B塑能师的徽记之戒将会大大提升你的魔法和自然能力。$B$B提高警觉，一旦你选择了你的道路，就无法回头了。') ON DUPLICATE KEY UPDATE Title_loc4='祈求者之路',OfferRewardText_loc4='相当出色，小家伙。你吃了不少苦才获得青铜龙军团的青睐。你的奉献令人印象深刻。$B$B塑能师的徽记之戒将会大大提升你的魔法和自然能力。$B$B提高警觉，一旦你选择了你的道路，就无法回头了。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8761,'虔诚的祈求者','起身吧，大塑能师!让世人看到你的力量!','我从没看过这样不屈不挠的人!青铜龙军团给了你最后一个附魔。永恒之王一直以来想要的永恒之宝!$B$B将你的徽记之戒交给我，这样我才能做些必要的调整。') ON DUPLICATE KEY UPDATE Title_loc4='虔诚的祈求者',OfferRewardText_loc4='起身吧，大塑能师!让世人看到你的力量!',RequestItemsText_loc4='我从没看过这样不屈不挠的人!青铜龙军团给了你最后一个附魔。永恒之王一直以来想要的永恒之宝!$B$B将你的徽记之戒交给我，这样我才能做些必要的调整。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4) VALUES (8762,'驯鹿梅森','出大事啦！驯鹿梅森被绑架了！$B$B冬天爷爷有八头驯鹿，梅森是其中的一头，也是烟林牧场的财产。我们收到了宣称对此次绑架事件负责的组织寄来的勒索信，而且不是一封，是两封！两封，你明白吗？节日即将来临，我们早已经穷得叮当响啦！帮帮忙吧，帮我们找到梅森，把它救回来！$B$B你可以看看这些勒索信里面有什么线索，找到梅森之后，把驯鹿之尘洒在它身上，这样就可以让它摆脱一切束缚！$B$B事不宜迟！','找到驯鹿梅森。在你手头上的便笺中查找有关梅森下落的线索。$B$B当你找到它之后，往它身上洒一些驯鹿之尘，这样就可以让它摆脱任何束缚。$B$B解救梅森之后，把驯鹿之尘还给铁炉堡的乌莫尔特。','你办到了!万岁!$B$B梅特森已经飞回去冬天爷爷的兽栏里了－－是的，梅特森是会飞的－－就在不久之前!这个尘土有点像是个符咒;我知道它可以的。你拯救了冬幕节还有燻木牧场免於疾病的侵袭。谢谢你，$N。$B$B听着……因为你对这里的贡献，我希望你可以拿着这个。这是一个非常特别的东西;如果你有坐骑的话，我想你可以好好的试试它。冬幕节快乐!$B','$N!我给你的背包里面的信息有没有包含什么有用的线索?我简直不敢去想那些恶棍会对梅特森做些什么……但我们绝对不可能付得出这么过份的赎金!','寻找麋鹿梅特森并且解救它') ON DUPLICATE KEY UPDATE Title_loc4='驯鹿梅森',Details_loc4='出大事啦！驯鹿梅森被绑架了！$B$B冬天爷爷有八头驯鹿，梅森是其中的一头，也是烟林牧场的财产。我们收到了宣称对此次绑架事件负责的组织寄来的勒索信，而且不是一封，是两封！两封，你明白吗？节日即将来临，我们早已经穷得叮当响啦！帮帮忙吧，帮我们找到梅森，把它救回来！$B$B你可以看看这些勒索信里面有什么线索，找到梅森之后，把驯鹿之尘洒在它身上，这样就可以让它摆脱一切束缚！$B$B事不宜迟！',Objectives_loc4='找到驯鹿梅森。在你手头上的便笺中查找有关梅森下落的线索。$B$B当你找到它之后，往它身上洒一些驯鹿之尘，这样就可以让它摆脱任何束缚。$B$B解救梅森之后，把驯鹿之尘还给铁炉堡的乌莫尔特。',OfferRewardText_loc4='你办到了!万岁!$B$B梅特森已经飞回去冬天爷爷的兽栏里了－－是的，梅特森是会飞的－－就在不久之前!这个尘土有点像是个符咒;我知道它可以的。你拯救了冬幕节还有燻木牧场免於疾病的侵袭。谢谢你，$N。$B$B听着……因为你对这里的贡献，我希望你可以拿着这个。这是一个非常特别的东西;如果你有坐骑的话，我想你可以好好的试试它。冬幕节快乐!$B',RequestItemsText_loc4='$N!我给你的背包里面的信息有没有包含什么有用的线索?我简直不敢去想那些恶棍会对梅特森做些什么……但我们绝对不可能付得出这么过份的赎金!',ObjectiveText1_loc4='寻找麋鹿梅特森并且解救它';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8763,'大英雄！','听着……我本不该告诉你这些，不过既然你是个大英雄……$B$B今年到处都有新鲜的冬青树茁壮成长，不过它们很快就会枯萎。我们弄了一台机器，可以储藏冬青树，然后在夏天拿出来热卖！$B$B我可以让你使用我们储藏的冬青树，不过你必须得是个够资格的大厨！给我带来一些石中盐，还有两个，不，三个，我是说五个金币。你觉得怎么样？够划算吧？','将1份石中盐和5个金币交给冬青树储藏器，以换取5棵冬青树。','这个机器开始运作时发出微微的隆隆声和小量的蒸汽。不久后它停了下来，喷出了另一团少量蒸汽。机器的门打开了，出现了一批保存好的冬青!$B','这台「冬青保存机」第一眼看起来还满坚固的，但是经过仔细的检查之后，你发现它上面有些哥布林式的改造。不过，你的烹饪技能使得你可以理解它这台机器是如何运作的。$B$B机器里面已经有了新鲜的冬青了－－你只需要提供一些石中盐跟5个金币就可以让这台机器运作起来。') ON DUPLICATE KEY UPDATE Title_loc4='大英雄！',Details_loc4='听着……我本不该告诉你这些，不过既然你是个大英雄……$B$B今年到处都有新鲜的冬青树茁壮成长，不过它们很快就会枯萎。我们弄了一台机器，可以储藏冬青树，然后在夏天拿出来热卖！$B$B我可以让你使用我们储藏的冬青树，不过你必须得是个够资格的大厨！给我带来一些石中盐，还有两个，不，三个，我是说五个金币。你觉得怎么样？够划算吧？',Objectives_loc4='将1份石中盐和5个金币交给冬青树储藏器，以换取5棵冬青树。',OfferRewardText_loc4='这个机器开始运作时发出微微的隆隆声和小量的蒸汽。不久后它停了下来，喷出了另一团少量蒸汽。机器的门打开了，出现了一批保存好的冬青!$B',RequestItemsText_loc4='这台「冬青保存机」第一眼看起来还满坚固的，但是经过仔细的检查之后，你发现它上面有些哥布林式的改造。不过，你的烹饪技能使得你可以理解它这台机器是如何运作的。$B$B机器里面已经有了新鲜的冬青了－－你只需要提供一些石中盐跟5个金币就可以让这台机器运作起来。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8764,'远离保护者之路','很好，$N。如果你改变心意，我会在这里帮助你。$B','勇士，如果你决定走上另一条道路，请将你的徽记之戒交给我并从我们的安其拉敌人那里带回一堆甲虫。') ON DUPLICATE KEY UPDATE Title_loc4='远离保护者之路',OfferRewardText_loc4='很好，$N。如果你改变心意，我会在这里帮助你。$B',RequestItemsText_loc4='勇士，如果你决定走上另一条道路，请将你的徽记之戒交给我并从我们的安其拉敌人那里带回一堆甲虫。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8765,'远离祈求者之路','很好，$N。如果你改变心意，我会在这里帮助你。','勇士，如果你决定走上另一条道路，请将你的徽记之戒交给我并从我们的安其拉敌人那里带回一堆甲虫。') ON DUPLICATE KEY UPDATE Title_loc4='远离祈求者之路',OfferRewardText_loc4='很好，$N。如果你改变心意，我会在这里帮助你。',RequestItemsText_loc4='勇士，如果你决定走上另一条道路，请将你的徽记之戒交给我并从我们的安其拉敌人那里带回一堆甲虫。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8766,'远离征服者之路','很好，$N。如果你改变心意，我会在这里帮助你。','勇士，如果你决定走上另一条道路，请将你的徽记之戒交给我并从我们的安其拉敌人那里带回一堆甲虫。') ON DUPLICATE KEY UPDATE Title_loc4='远离征服者之路',OfferRewardText_loc4='很好，$N。如果你改变心意，我会在这里帮助你。',RequestItemsText_loc4='勇士，如果你决定走上另一条道路，请将你的徽记之戒交给我并从我们的安其拉敌人那里带回一堆甲虫。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4) VALUES (8767,'轻轻摇晃过的礼品','这个礼物看起来好像已经被稍微摇晃过了几次。上面的标签写着:$B$B给最特别的$r$C。') ON DUPLICATE KEY UPDATE Title_loc4='轻轻摇晃过的礼品',OfferRewardText_loc4='这个礼物看起来好像已经被稍微摇晃过了几次。上面的标签写着:$B$B给最特别的$r$C。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4) VALUES (8768,'华丽的礼物','这件礼物上面写着你的名字。$B$B等等，它刚才好像动了一下?$B') ON DUPLICATE KEY UPDATE Title_loc4='华丽的礼物',OfferRewardText_loc4='这件礼物上面写着你的名字。$B$B等等，它刚才好像动了一下?$B';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4) VALUES (8769,'条纹礼物盒','燻木牧场祝你冬幕节快乐!$B') ON DUPLICATE KEY UPDATE Title_loc4='条纹礼物盒',OfferRewardText_loc4='燻木牧场祝你冬幕节快乐!$B';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8770,'目标：亚什工蝎','我们需要援军进攻亚什虫巢。你的主要目标是那些亚什工蝎。当你的任务完成之后向指挥官玛尔利斯报告。','击杀25只亚什工蝎和40只亚什雄蝎。','干得好，$N。你的表现一如以往地出色。$B','你有什么要和我说的，$C?') ON DUPLICATE KEY UPDATE Title_loc4='目标：亚什工蝎',Details_loc4='我们需要援军进攻亚什虫巢。你的主要目标是那些亚什工蝎。当你的任务完成之后向指挥官玛尔利斯报告。',Objectives_loc4='击杀25只亚什工蝎和40只亚什雄蝎。',OfferRewardText_loc4='干得好，$N。你的表现一如以往地出色。$B',RequestItemsText_loc4='你有什么要和我说的，$C?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8771,'目标：亚什沙行者','这一地区猖獗的异种虫类对我们来说是个巨大的威胁。你被指派负责对亚什虫巢发动攻击，主要目标是亚什沙行者。$B$B在你的任务完成之后，向指挥官玛尔利斯汇报。','击杀30只亚什沙行者，然后向塞纳里奥要塞的指挥官玛尔利斯复命。你还必须带着作战任务简报 II才能完成这个任务。','干得好，$N。你在亚什虫巢攻击行动中的卓越表现已经引起了关注。$B','你有什么要和我说的，$C?') ON DUPLICATE KEY UPDATE Title_loc4='目标：亚什沙行者',Details_loc4='这一地区猖獗的异种虫类对我们来说是个巨大的威胁。你被指派负责对亚什虫巢发动攻击，主要目标是亚什沙行者。$B$B在你的任务完成之后，向指挥官玛尔利斯汇报。',Objectives_loc4='击杀30只亚什沙行者，然后向塞纳里奥要塞的指挥官玛尔利斯复命。你还必须带着作战任务简报 II才能完成这个任务。',OfferRewardText_loc4='干得好，$N。你在亚什虫巢攻击行动中的卓越表现已经引起了关注。$B',RequestItemsText_loc4='你有什么要和我说的，$C?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8772,'目标：佐拉守卫','我们需要援军进攻佐拉虫巢。你的主要目标是那些佐拉守卫，当你的任务完成之后就去向指挥官玛尔利斯报告。','击杀30只佐拉守卫，然后向塞纳里奥要塞的指挥官玛尔利斯复命。你还必须带着作战任务简报 VI才能完成这个任务。','干得好，$N。你在佐拉虫巢攻击行动中的卓越表现已经引起了关注。$B','你有什么要和我说的，$C?') ON DUPLICATE KEY UPDATE Title_loc4='目标：佐拉守卫',Details_loc4='我们需要援军进攻佐拉虫巢。你的主要目标是那些佐拉守卫，当你的任务完成之后就去向指挥官玛尔利斯报告。',Objectives_loc4='击杀30只佐拉守卫，然后向塞纳里奥要塞的指挥官玛尔利斯复命。你还必须带着作战任务简报 VI才能完成这个任务。',OfferRewardText_loc4='干得好，$N。你在佐拉虫巢攻击行动中的卓越表现已经引起了关注。$B',RequestItemsText_loc4='你有什么要和我说的，$C?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8773,'目标：佐拉掠夺者','我们需要援军进攻佐拉虫巢。你的主要目标是那些佐拉掠夺者，当你的任务完成之后就去向指挥官玛尔利斯报告。','击杀40只佐拉掠夺者。','我听说了你在佐拉虫巢的事蹟。继续努力，胜利必将属於我们。$B','你有什么要和我说的，$C?') ON DUPLICATE KEY UPDATE Title_loc4='目标：佐拉掠夺者',Details_loc4='我们需要援军进攻佐拉虫巢。你的主要目标是那些佐拉掠夺者，当你的任务完成之后就去向指挥官玛尔利斯报告。',Objectives_loc4='击杀40只佐拉掠夺者。',OfferRewardText_loc4='我听说了你在佐拉虫巢的事蹟。继续努力，胜利必将属於我们。$B',RequestItemsText_loc4='你有什么要和我说的，$C?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (8774,'目标：雷戈伏击者','这一地区猖獗的异种虫类对我们来说是个巨大的威胁。你被指派负责对雷戈虫巢发动攻击，主要目标是雷戈伏击者。$B$B在你的任务完成之后，向指挥官玛尔利斯汇报。','击杀30只雷戈伏击者，然后向塞纳里奥要塞的指挥官玛尔利斯复命。你还必须带着作战任务简报 VIII才能完成这个任务。','干得好，$N。你在佐拉虫巢攻击行动中的卓越表现已经引起了关注。$B','你有什么事吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='目标：雷戈伏击者',Details_loc4='这一地区猖獗的异种虫类对我们来说是个巨大的威胁。你被指派负责对雷戈虫巢发动攻击，主要目标是雷戈伏击者。$B$B在你的任务完成之后，向指挥官玛尔利斯汇报。',Objectives_loc4='击杀30只雷戈伏击者，然后向塞纳里奥要塞的指挥官玛尔利斯复命。你还必须带着作战任务简报 VIII才能完成这个任务。',OfferRewardText_loc4='干得好，$N。你在佐拉虫巢攻击行动中的卓越表现已经引起了关注。$B',RequestItemsText_loc4='你有什么事吗，$N?';
