INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10074,'沃舒古水晶尘','哈兰曾经是德莱尼人研究纳鲁水晶的重要基地。$B$B我们发现，产自“钻石山”沃舒古的水晶具有极高的研究价值，而且这个区域的所有生物体内似乎都残留着这种水晶尘。如果你在探险途中找到水晶尘的话，就把它们统统拿来给我吧。我会奖励你一枚勋章，你可以用它向军需官购买东西。','将10份沃舒古水晶尘样本交给哈兰的主研究员阿米蒂恩。','太棒了，$N。这将会帮助我们与外域中出现的联盟垃圾们对抗。','从山上来的结晶粉末充满着这个区域的地心。') ON DUPLICATE KEY UPDATE Title_loc4='沃舒古水晶尘',Details_loc4='哈兰曾经是德莱尼人研究纳鲁水晶的重要基地。$B$B我们发现，产自“钻石山”沃舒古的水晶具有极高的研究价值，而且这个区域的所有生物体内似乎都残留着这种水晶尘。如果你在探险途中找到水晶尘的话，就把它们统统拿来给我吧。我会奖励你一枚勋章，你可以用它向军需官购买东西。',Objectives_loc4='将10份沃舒古水晶尘样本交给哈兰的主研究员阿米蒂恩。',OfferRewardText_loc4='太棒了，$N。这将会帮助我们与外域中出现的联盟垃圾们对抗。',RequestItemsText_loc4='从山上来的结晶粉末充满着这个区域的地心。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10075,'沃舒古水晶尘','我一直都接受水晶粉末的捐献，$N。你每捐献一组发现的样本都将会得到补偿的。','这地方就是德莱尼研究纳鲁水晶的主要研究场所。$B$B我们所发现的是与来自“') ON DUPLICATE KEY UPDATE Title_loc4='沃舒古水晶尘',OfferRewardText_loc4='我一直都接受水晶粉末的捐献，$N。你每捐献一组发现的样本都将会得到补偿的。',RequestItemsText_loc4='这地方就是德莱尼研究纳鲁水晶的主要研究场所。$B$B我们所发现的是与来自“';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10076,'沃舒古水晶尘','哈兰曾经是德莱尼人研究纳鲁水晶的重要基地。$B$B我们发现，产自“钻石山”沃舒古的水晶具有极高的研究价值，而且这个区域的所有生物体内似乎都残留着这种水晶尘。如果你在探险途中找到水晶尘的话，就把它们统统拿来给我吧。我会奖励你一枚勋章，你可以用它向军需官购买东西。','将10份沃舒古水晶尘样本交给哈兰的主研究员卡托斯。','太棒了，$N。这将会帮助我们与外域中出现的联盟垃圾们对抗。','从山上来的结晶粉末充满着这个区域的地心。') ON DUPLICATE KEY UPDATE Title_loc4='沃舒古水晶尘',Details_loc4='哈兰曾经是德莱尼人研究纳鲁水晶的重要基地。$B$B我们发现，产自“钻石山”沃舒古的水晶具有极高的研究价值，而且这个区域的所有生物体内似乎都残留着这种水晶尘。如果你在探险途中找到水晶尘的话，就把它们统统拿来给我吧。我会奖励你一枚勋章，你可以用它向军需官购买东西。',Objectives_loc4='将10份沃舒古水晶尘样本交给哈兰的主研究员卡托斯。',OfferRewardText_loc4='太棒了，$N。这将会帮助我们与外域中出现的联盟垃圾们对抗。',RequestItemsText_loc4='从山上来的结晶粉末充满着这个区域的地心。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10077,'沃舒古水晶尘样本','我一直都接受水晶粉末的捐献，$N。你每捐献一组发现的样本都将会得到补偿的。','这地方就是德莱尼研究纳鲁水晶的主要研究场所。$B$B我们所发现的是与来自“') ON DUPLICATE KEY UPDATE Title_loc4='沃舒古水晶尘样本',OfferRewardText_loc4='我一直都接受水晶粉末的捐献，$N。你每捐献一组发现的样本都将会得到补偿的。',RequestItemsText_loc4='这地方就是德莱尼研究纳鲁水晶的主要研究场所。$B$B我们所发现的是与来自“';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4,ObjectiveText2_loc4,ObjectiveText3_loc4,ObjectiveText4_loc4) VALUES (10078,'烧毁掷刀车','既然我们的营救计划已经取得了进展，是时候准备进行第二步计划了。$B$B在荣耀之路的另一边，部落仍旧在利用他们古老的掷刀车对付我们。$N，别被它们的年龄蒙骗，这些武器仍然非常危险。我们要继续夺回一切可用的东西，同样我们也不能指望部落会毁掉他们的武器。$B$B带上这个火把，烧毁那些残馀的攻城器械，我必须尽力保证荣耀堡的安全。','使用燃烧的火把烧毁分布在荣耀之路周围的部落掷刀车，然后将燃烧的火把交给荣耀堡的达姆菲。','就是这股精神!$B$B我很高兴我们终于有了援军，但我不太确定他们对部落的想法。我来的地方，任何用武器指着你的都是敌人而且需要像个敌人一样的解决掉!','你看起来精神很好。烧了部落攻城器械让你回复了活力吗?','烧毁东部的掷刀车','烧毁中部偏东的掷刀车','烧毁中部偏西的掷刀车','烧毁西部的掷刀车') ON DUPLICATE KEY UPDATE Title_loc4='烧毁掷刀车',Details_loc4='既然我们的营救计划已经取得了进展，是时候准备进行第二步计划了。$B$B在荣耀之路的另一边，部落仍旧在利用他们古老的掷刀车对付我们。$N，别被它们的年龄蒙骗，这些武器仍然非常危险。我们要继续夺回一切可用的东西，同样我们也不能指望部落会毁掉他们的武器。$B$B带上这个火把，烧毁那些残馀的攻城器械，我必须尽力保证荣耀堡的安全。',Objectives_loc4='使用燃烧的火把烧毁分布在荣耀之路周围的部落掷刀车，然后将燃烧的火把交给荣耀堡的达姆菲。',OfferRewardText_loc4='就是这股精神!$B$B我很高兴我们终于有了援军，但我不太确定他们对部落的想法。我来的地方，任何用武器指着你的都是敌人而且需要像个敌人一样的解决掉!',RequestItemsText_loc4='你看起来精神很好。烧了部落攻城器械让你回复了活力吗?',ObjectiveText1_loc4='烧毁东部的掷刀车',ObjectiveText2_loc4='烧毁中部偏东的掷刀车',ObjectiveText3_loc4='烧毁中部偏西的掷刀车',ObjectiveText4_loc4='烧毁西部的掷刀车';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10079,'乱糟糟的矿洞','那帮该死的甘尔葛小恶魔竟然占领了矿井！$B$B他们不但赶走了我派去的所有工人，还日日夜夜敲打个不停，要把所有的矿石都采光！更糟糕的是，现在达纳斯又开始唠叨个没完！他说如果我不能尽快地解决这件事，他就要拿走我的麦酒！$B$B但是，没有一个矿工愿意帮忙，我的卫兵们也正喝得晕头转向。$B$B$N，我求你了，帮帮我。达纳斯可以夺走我的尊严，但绝不能他拿走我的麦酒！','杀死12个甘尔葛工兵，然后向工头比格姆斯复命。','铜须的铜……须，你做到了!你是个英雄，$N。','告诉我震摇已经结束了而我的人能够回去工作了……拜托?') ON DUPLICATE KEY UPDATE Title_loc4='乱糟糟的矿洞',Details_loc4='那帮该死的甘尔葛小恶魔竟然占领了矿井！$B$B他们不但赶走了我派去的所有工人，还日日夜夜敲打个不停，要把所有的矿石都采光！更糟糕的是，现在达纳斯又开始唠叨个没完！他说如果我不能尽快地解决这件事，他就要拿走我的麦酒！$B$B但是，没有一个矿工愿意帮忙，我的卫兵们也正喝得晕头转向。$B$B$N，我求你了，帮帮我。达纳斯可以夺走我的尊严，但绝不能他拿走我的麦酒！',Objectives_loc4='杀死12个甘尔葛工兵，然后向工头比格姆斯复命。',OfferRewardText_loc4='铜须的铜……须，你做到了!你是个英雄，$N。',RequestItemsText_loc4='告诉我震摇已经结束了而我的人能够回去工作了……拜托?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10081,'拜访卡舒尔宗母','药水生效后，无论你看见了什么都不要惊惶失措！这些鬼魂一直在我们身边。药水开拓了你的心智，你不仅可以亲眼目睹灵魂的存在，还可以与他们沟通和交流。只有在药水的作用之下，你才能与卡舒尔宗母交谈。$B$B遥远的西南方有一处名叫先祖之地的圣地，去那儿找她吧。','盖亚安祖母要你去跟卡舒尔宗母谈一谈。','你所喝的那瓶药剂并没有真正的效果。你只能看到自己愿意现身的灵魂。这瓶药剂只是证明你的信念及奉献而已。这是个考验而且你通过了……','所以你就是那个灵魂们提到的人吗?') ON DUPLICATE KEY UPDATE Title_loc4='拜访卡舒尔宗母',Details_loc4='药水生效后，无论你看见了什么都不要惊惶失措！这些鬼魂一直在我们身边。药水开拓了你的心智，你不仅可以亲眼目睹灵魂的存在，还可以与他们沟通和交流。只有在药水的作用之下，你才能与卡舒尔宗母交谈。$B$B遥远的西南方有一处名叫先祖之地的圣地，去那儿找她吧。',Objectives_loc4='盖亚安祖母要你去跟卡舒尔宗母谈一谈。',OfferRewardText_loc4='你所喝的那瓶药剂并没有真正的效果。你只能看到自己愿意现身的灵魂。这瓶药剂只是证明你的信念及奉献而已。这是个考验而且你通过了……',RequestItemsText_loc4='所以你就是那个灵魂们提到的人吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10082,'激动的灵魂','瞧见那些游荡在先祖之地的灵魂了吗？这儿本是一块祥和安宁的净土。$B$B最近，不知道为什么，原本沉睡在宁静之中的先祖灵魂突然复苏，变得躁动不安起来。我们必须揭开滋扰这片净土的根源，不过，更首要的问题是眼前的混乱。$B$B徘徊在先祖之地的鬼魂并不是兽人先祖的灵魂本身，他们只是先祖意识形态的某种存在方式。消灭那些激动的兽人灵魂，完成任务后回来向我复命。','卡舒尔宗母要求你让8个激动的兽人灵魂再次安息。','没有用。他们还是继续出现。一定是有某种更加邪恶的事物暗中进行着。','你不需要药剂就可以看到灵魂了，$N。') ON DUPLICATE KEY UPDATE Title_loc4='激动的灵魂',Details_loc4='瞧见那些游荡在先祖之地的灵魂了吗？这儿本是一块祥和安宁的净土。$B$B最近，不知道为什么，原本沉睡在宁静之中的先祖灵魂突然复苏，变得躁动不安起来。我们必须揭开滋扰这片净土的根源，不过，更首要的问题是眼前的混乱。$B$B徘徊在先祖之地的鬼魂并不是兽人先祖的灵魂本身，他们只是先祖意识形态的某种存在方式。消灭那些激动的兽人灵魂，完成任务后回来向我复命。',Objectives_loc4='卡舒尔宗母要求你让8个激动的兽人灵魂再次安息。',OfferRewardText_loc4='没有用。他们还是继续出现。一定是有某种更加邪恶的事物暗中进行着。',RequestItemsText_loc4='你不需要药剂就可以看到灵魂了，$N。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10084,'袭击黑色祭坛','拥有莫阿格工程师的技术及无止尽供应的甘纳格部属，他们会在我们将信送到守望堡前就开始大量生产恶魔劫夺者。
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4,ObjectiveText2_loc4,ObjectiveText3_loc4,ObjectiveText4_loc4) VALUES (10085,'拜访先祖之魂','$N，我要你调查几座曾有先祖灵魂出没的村落，看看那里是否还有他们的踪迹。$B$B前往此地以北的日泉岗哨，更北处山脚下的嘲颅废墟，东北方的加拉达尔，以及位于纳格兰和泰罗卡森林交界处的血环废墟，调查这四座村落的情况。$B$B完成任务后回来向我复命。','纳格兰先祖之地的卡舒尔宗母要你去拜访日泉岗哨、嘲颅废墟、加拉达尔和血环废墟。','这非常的麻烦。你说这些村落中的先祖都不在吗?他们全都往南方去了?','像风一样快速的动身吧，$N。','拜访日泉岗哨','拜访嘲颅废墟','拜访加拉达尔','拜访血环废墟') ON DUPLICATE KEY UPDATE Title_loc4='拜访先祖之魂',Details_loc4='$N，我要你调查几座曾有先祖灵魂出没的村落，看看那里是否还有他们的踪迹。$B$B前往此地以北的日泉岗哨，更北处山脚下的嘲颅废墟，东北方的加拉达尔，以及位于纳格兰和泰罗卡森林交界处的血环废墟，调查这四座村落的情况。$B$B完成任务后回来向我复命。',Objectives_loc4='纳格兰先祖之地的卡舒尔宗母要你去拜访日泉岗哨、嘲颅废墟、加拉达尔和血环废墟。',OfferRewardText_loc4='这非常的麻烦。你说这些村落中的先祖都不在吗?他们全都往南方去了?',RequestItemsText_loc4='像风一样快速的动身吧，$N。',ObjectiveText1_loc4='拜访日泉岗哨',ObjectiveText2_loc4='拜访嘲颅废墟',ObjectiveText3_loc4='拜访加拉达尔',ObjectiveText4_loc4='拜访血环废墟';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10086,'我为部落工作！','你相信吗？这些兽人居然雇佣我帮他们制造炸药来炸毁要塞。这是我梦想已久的工作！糟糕的是我们的材料已经不够了，不过像我这样聪明的地精知道该怎样去做！$B$B你愿意帮帮我吗？我需要荣耀之路两边的攻城器械周围散落的木材和金属，一定要小心那些红皮肤的兽人！$B$B任务完成后，你会得到丰厚的奖赏！','给萨尔玛的泽格·纳克布斯带去8块回收的金属和8块回收的木材。','这些东西简直是太棒了!虽然有点弯曲以及烧过的焦痕，但是我一向都可以把粗糙的材料做成高度精密的爆裂物。
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4,ObjectiveText2_loc4) VALUES (10087,'为了部落，烧！','我是一个非常非常幸运的地精。我要制作的炸弹和工程装备很快就能在重要的任务中派上用场了！$B$B说到任务，我刚收到来自萨尔玛的一条命令：毁掉在荣耀之路附近的联盟火炮……这些设施令部落的要塞时刻处于危险中。带上这只火把，去毁掉你看到的每一座火炮。点燃火把就行啦！','利用燃烧的火把烧毁东部联盟火炮和西部联盟火炮，然后返回萨尔玛向泽格·纳克布斯复命。','我就知道!从这边我不能辨识摧毁的情形，但是我可以想象它的惨状。太棒了!$B$B做的好，$N。萨尔玛指挥官将会很高兴听到你的捷报。','我一直在找火炮被烧毁的明显迹象-燃烧的烟云或者着火的邪兽人的哀号声……$B$B你的任务成功了吗?','烧毁东部火炮','烧毁西部火炮') ON DUPLICATE KEY UPDATE Title_loc4='为了部落，烧！',Details_loc4='我是一个非常非常幸运的地精。我要制作的炸弹和工程装备很快就能在重要的任务中派上用场了！$B$B说到任务，我刚收到来自萨尔玛的一条命令：毁掉在荣耀之路附近的联盟火炮……这些设施令部落的要塞时刻处于危险中。带上这只火把，去毁掉你看到的每一座火炮。点燃火把就行啦！',Objectives_loc4='利用燃烧的火把烧毁东部联盟火炮和西部联盟火炮，然后返回萨尔玛向泽格·纳克布斯复命。',OfferRewardText_loc4='我就知道!从这边我不能辨识摧毁的情形，但是我可以想象它的惨状。太棒了!$B$B做的好，$N。萨尔玛指挥官将会很高兴听到你的捷报。',RequestItemsText_loc4='我一直在找火炮被烧毁的明显迹象-燃烧的烟云或者着火的邪兽人的哀号声……$B$B你的任务成功了吗?',ObjectiveText1_loc4='烧毁东部火炮',ObjectiveText2_loc4='烧毁西部火炮';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10088,'矿场的骚动','矿井遭遇了甘纳格之灾，而苦工们却认为这是一个小憩的好时机！我不明白为什么在矿井被扰乱时他们居然还睡得着，但这不是关键问题。如果我们不能尽快地干掉那些该死的甘纳格，萨尔玛将会面临矿石和其它矿物供应不足的危机。我已经向警备队长克朗克请求帮助了，但是他说城镇遭到了持续不断地攻击，他没有办法派出多馀的人手来帮助我。你愿意帮帮我吗？','杀掉12个甘纳格工人后回报工头拉泽克拉兹。','终于!现在，我不认为你愿意去敲敲几个矿工的头，还是这需要额外的收费呢?','那么，你在矿坑中有任何进展吗?') ON DUPLICATE KEY UPDATE Title_loc4='矿场的骚动',Details_loc4='矿井遭遇了甘纳格之灾，而苦工们却认为这是一个小憩的好时机！我不明白为什么在矿井被扰乱时他们居然还睡得着，但这不是关键问题。如果我们不能尽快地干掉那些该死的甘纳格，萨尔玛将会面临矿石和其它矿物供应不足的危机。我已经向警备队长克朗克请求帮助了，但是他说城镇遭到了持续不断地攻击，他没有办法派出多馀的人手来帮助我。你愿意帮帮我吗？',Objectives_loc4='杀掉12个甘纳格工人后回报工头拉泽克拉兹。',OfferRewardText_loc4='终于!现在，我不认为你愿意去敲敲几个矿工的头，还是这需要额外的收费呢?',RequestItemsText_loc4='那么，你在矿坑中有任何进展吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10089,'军团的炼冶场','自萨尔玛创建后，遭到了燃烧军团炮击。我们一直在努力抵抗，但形势变得越来越糟糕。$B$B影子猎人泰巾曾多次尝试了解更多敌人的情况，但他派出的侦察员没有一个能回来。$B$B时间不知不觉地过去了，$N。想办法混进铸魔营地：狂乱，看看燃烧军团到底在干什么。','杀掉10个甘纳格仆人，5个炼冶场军团士兵，和5个悲痛之女，然后搜寻炼冶场:狂怒找出军团意图的证据。','仔细检查计划书，你发现它们似乎是什么机械学的指示说明。只有大约一半的计划还在。$B$B没有整个图表，就不可能知道军团正在建造什么。或许剩下的计划书可以在西边的炼冶场:泄愤找到。','你检视着这个雕纹，发现一份计划书。') ON DUPLICATE KEY UPDATE Title_loc4='军团的炼冶场',Details_loc4='自萨尔玛创建后，遭到了燃烧军团炮击。我们一直在努力抵抗，但形势变得越来越糟糕。$B$B影子猎人泰巾曾多次尝试了解更多敌人的情况，但他派出的侦察员没有一个能回来。$B$B时间不知不觉地过去了，$N。想办法混进铸魔营地：狂乱，看看燃烧军团到底在干什么。',Objectives_loc4='杀掉10个甘纳格仆人，5个炼冶场军团士兵，和5个悲痛之女，然后搜寻炼冶场:狂怒找出军团意图的证据。',OfferRewardText_loc4='仔细检查计划书，你发现它们似乎是什么机械学的指示说明。只有大约一半的计划还在。$B$B没有整个图表，就不可能知道军团正在建造什么。或许剩下的计划书可以在西边的炼冶场:泄愤找到。',RequestItemsText_loc4='你检视着这个雕纹，发现一份计划书。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10090,'军团的计划','你虽然复制了蚀刻在地面上闪光的符号，但缺少另外一半这个图表没有任何意义。$B$B这些符号显示西边的 炼冶场:怨恨 也参与到了这个计划。燃烧军团会不会把图表的剩馀部分藏在那里？$B$B如果燃烧军团想要制造某种丑陋的巨型怪物，那他们所有的营地都会参与进去的。','取得炼冶场:泄愤计划再将它们交给劫夺者荒野的霸主残拳。','做的好，$N。你成功的到达了连我手下最优良的斥候都到不了的地方。$B$B<霸主从你手上接过计划书并阅读。>$B$B这不可能的!这是恶魔劫夺者的设计图，我们都非常熟悉的内容。但这些计划谈到大量制造!我们得花费极大的力量才有办法击倒一只。想想看军团能用上百只来做些什么事!','我知道你刚从燃烧军团的营地回来。你知道什么了吗?') ON DUPLICATE KEY UPDATE Title_loc4='军团的计划',Details_loc4='你虽然复制了蚀刻在地面上闪光的符号，但缺少另外一半这个图表没有任何意义。$B$B这些符号显示西边的 炼冶场:怨恨 也参与到了这个计划。燃烧军团会不会把图表的剩馀部分藏在那里？$B$B如果燃烧军团想要制造某种丑陋的巨型怪物，那他们所有的营地都会参与进去的。',Objectives_loc4='取得炼冶场:泄愤计划再将它们交给劫夺者荒野的霸主残拳。',OfferRewardText_loc4='做的好，$N。你成功的到达了连我手下最优良的斥候都到不了的地方。$B$B<霸主从你手上接过计划书并阅读。>$B$B这不可能的!这是恶魔劫夺者的设计图，我们都非常熟悉的内容。但这些计划谈到大量制造!我们得花费极大的力量才有办法击倒一只。想想看军团能用上百只来做些什么事!',RequestItemsText_loc4='我知道你刚从燃烧军团的营地回来。你知道什么了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10091,'灵魂装置','啊！他们一直在拷问我，想让我吐露所有的秘密。$B$B我屈服了……他们竟然将别的间谍喂给赫尔默吃，还说我就是下一个。但是我没有泄露任何重要的信息！$B$B这帮疯子！他们试图召唤自己根本无力控制的恶魔力量！$B$B他们利用某种特殊的装置制造灵魂碎片，以此强化召唤能力，你必须偷走这些装置！$B$B我原本打算和你一起去的，但我必须先返回沙塔斯城，向贫民窟的间谍女王报告。','偷取5个灵魂装置，将它们交给沙塔斯城圣光广场的间谍女王梅丽萨·海克隆。','吐刚先前才来这里将他的报告交给我。他应该和你一起留下帮忙的!$B$B我派他出去协助葛瑞克萨了。我想他们会是很适合的一对。$B$B所以，这些就是暗影议会用来提升他们召唤力量的灵魂仪器?它们看起来很危险 - 或许占星者能好好利用它们?$B$B来，选择一个做为奖励，这是你削弱暗影议会在迷宫的运作应得的。','嗯恩?我能为你做什么呢，$C?') ON DUPLICATE KEY UPDATE Title_loc4='灵魂装置',Details_loc4='啊！他们一直在拷问我，想让我吐露所有的秘密。$B$B我屈服了……他们竟然将别的间谍喂给赫尔默吃，还说我就是下一个。但是我没有泄露任何重要的信息！$B$B这帮疯子！他们试图召唤自己根本无力控制的恶魔力量！$B$B他们利用某种特殊的装置制造灵魂碎片，以此强化召唤能力，你必须偷走这些装置！$B$B我原本打算和你一起去的，但我必须先返回沙塔斯城，向贫民窟的间谍女王报告。',Objectives_loc4='偷取5个灵魂装置，将它们交给沙塔斯城圣光广场的间谍女王梅丽萨·海克隆。',OfferRewardText_loc4='吐刚先前才来这里将他的报告交给我。他应该和你一起留下帮忙的!$B$B我派他出去协助葛瑞克萨了。我想他们会是很适合的一对。$B$B所以，这些就是暗影议会用来提升他们召唤力量的灵魂仪器?它们看起来很危险 - 或许占星者能好好利用它们?$B$B来，选择一个做为奖励，这是你削弱暗影议会在迷宫的运作应得的。',RequestItemsText_loc4='嗯恩?我能为你做什么呢，$C?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10092,'袭击黑色祭坛','有了莫阿格工程师的技术和数也数不清的甘纳格爪牙，在我们将消息通知奥格瑞玛之前他们就能大量地制造出恶魔劫夺者。$B$B除了尽快地铲除他们我们别无选择。我不能调派萨尔玛驻军去帮助你，那样的话我们易失于防守而遭到攻击的。$B$B还有许多在等待机会的敌人，联盟仍在盼望着向我们疏于防范的前哨发起猛攻。千万不要失败，$N。一切都靠你了。','杀掉炼冶场:黑暗祭坛的黑夜领主玛法斯，然后回到劫夺者荒野找霸主残拳。','告诉你我放心了是比较保守的说法。你杀掉黑夜领主玛法斯为我们在这场对抗军团的战斗中带来非常宝贵的时刻。$B$B让我们不用欺骗自己想象我们已经击倒军团使他们全部撤退了，不过我们不再需要胆颤心惊了。','你完成了我交付的任务杀掉领导者了吗?') ON DUPLICATE KEY UPDATE Title_loc4='袭击黑色祭坛',Details_loc4='有了莫阿格工程师的技术和数也数不清的甘纳格爪牙，在我们将消息通知奥格瑞玛之前他们就能大量地制造出恶魔劫夺者。$B$B除了尽快地铲除他们我们别无选择。我不能调派萨尔玛驻军去帮助你，那样的话我们易失于防守而遭到攻击的。$B$B还有许多在等待机会的敌人，联盟仍在盼望着向我们疏于防范的前哨发起猛攻。千万不要失败，$N。一切都靠你了。',Objectives_loc4='杀掉炼冶场:黑暗祭坛的黑夜领主玛法斯，然后回到劫夺者荒野找霸主残拳。',OfferRewardText_loc4='告诉你我放心了是比较保守的说法。你杀掉黑夜领主玛法斯为我们在这场对抗军团的战斗中带来非常宝贵的时刻。$B$B让我们不用欺骗自己想象我们已经击倒军团使他们全部撤退了，不过我们不再需要胆颤心惊了。',RequestItemsText_loc4='你完成了我交付的任务杀掉领导者了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10093,'塔哈玛特神殿','幸运的是，荣耀之路不是我的族人们唯一留下过足迹的地方。在西边，虽然有些地方已经被占领，仍有部分圣地幸运地逃过了浩劫，被保留了下来。$B$B维伦大人准备前往艾泽拉斯世界时，一些决定留下来的族人在那些圣地重建了家园。$B$B在地狱火半岛西边的塔哈玛特神殿中，你可以找到由智者阿曼恩所带领的一小支德莱尼人，我敢肯定他一定很想见见你。','前往地狱火半岛西部的塔哈玛特神殿，与智者阿曼恩谈一谈。','阿，所以你见过先知克里了。他是个睿智且受到眷顾的人而任何$r他提过的朋友就也是我的朋友。$B$B放松你自己并向其它称呼神庙为家的人介绍你自己。','欢迎来到特尔哈曼神庙，旅人。') ON DUPLICATE KEY UPDATE Title_loc4='塔哈玛特神殿',Details_loc4='幸运的是，荣耀之路不是我的族人们唯一留下过足迹的地方。在西边，虽然有些地方已经被占领，仍有部分圣地幸运地逃过了浩劫，被保留了下来。$B$B维伦大人准备前往艾泽拉斯世界时，一些决定留下来的族人在那些圣地重建了家园。$B$B在地狱火半岛西边的塔哈玛特神殿中，你可以找到由智者阿曼恩所带领的一小支德莱尼人，我敢肯定他一定很想见见你。',Objectives_loc4='前往地狱火半岛西部的塔哈玛特神殿，与智者阿曼恩谈一谈。',OfferRewardText_loc4='阿，所以你见过先知克里了。他是个睿智且受到眷顾的人而任何$r他提过的朋友就也是我的朋友。$B$B放松你自己并向其它称呼神庙为家的人介绍你自己。',RequestItemsText_loc4='欢迎来到特尔哈曼神庙，旅人。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10094,'鲜血法典','两年前，暗影议会在奥金顿的召唤仪式导致了这座宏伟陵墓的爆炸，并由此形成了白骨荒野。$B$B如今，在奥金顿里面，暗影议会与某种强大得令人难以置信的势力正在激烈地战斗着。$B$B$N，你必须进入暗影迷宫，探察究竟是什么在与暗影议会交战，看看这场战争是否会对我们构成威胁。间谍们曾提起一本名叫鲜血法典的禁断之书，据说暗影议会用它启动某种邪恶的召唤仪式。$B$B看看书中是否提到什么线索吧。','阅读奥金顿暗影迷宫中的鲜血法典。','打开这本因魔法而悬浮的书册，一股恐惧席卷而来。$B$B一定有什么不对劲!$B$B你持续读着，但你所看到的内容似乎非常惊人!') ON DUPLICATE KEY UPDATE Title_loc4='鲜血法典',Details_loc4='两年前，暗影议会在奥金顿的召唤仪式导致了这座宏伟陵墓的爆炸，并由此形成了白骨荒野。$B$B如今，在奥金顿里面，暗影议会与某种强大得令人难以置信的势力正在激烈地战斗着。$B$B$N，你必须进入暗影迷宫，探察究竟是什么在与暗影议会交战，看看这场战争是否会对我们构成威胁。间谍们曾提起一本名叫鲜血法典的禁断之书，据说暗影议会用它启动某种邪恶的召唤仪式。$B$B看看书中是否提到什么线索吧。',Objectives_loc4='阅读奥金顿暗影迷宫中的鲜血法典。',OfferRewardText_loc4='打开这本因魔法而悬浮的书册，一股恐惧席卷而来。$B$B一定有什么不对劲!$B$B你持续读着，但你所看到的内容似乎非常惊人!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10095,'深入迷宫','暗影议会两年前召唤出的庞然大物已经摆脱了他们的控制！那场召唤仪式导致了奥金顿大爆炸，并由此形成了白骨荒野。$B$B这只名叫摩摩尔的生物想要颠复暗影议会，逃离奥金顿，在我们的世界重获自由！$B$B沃匹尔大师和暗影议会的其它领袖都已经丧命，现在只有你能消灭那只怪物了，你将是外域唯一的希望！$B$B$N，你应该很清楚，你和你的同伴绝不能失败！','杀死摩摩尔，然后返回沙塔斯城的圣光广场，将暗影迷宫的秘密告诉间谍女王梅丽萨·海克隆。','摩摩尔已经快要获得自由了?!他们已经控制它两年了……我怀疑是什么使他们在这么久的时间后失去对它的控制?$B$B$N，打倒那个怪物你就能拯救我们所有人!我不禁害怕要是那怪物获得自由了，那沙塔斯城及外域其它地方会变成怎样!$B$B我很高兴你帮我们取得了事情的掌控权并对付奥齐顿的暗影议会威胁。我们要怎么奖励你呢?','$N，你从暗影迷宫带回了什么消息阿?') ON DUPLICATE KEY UPDATE Title_loc4='深入迷宫',Details_loc4='暗影议会两年前召唤出的庞然大物已经摆脱了他们的控制！那场召唤仪式导致了奥金顿大爆炸，并由此形成了白骨荒野。$B$B这只名叫摩摩尔的生物想要颠复暗影议会，逃离奥金顿，在我们的世界重获自由！$B$B沃匹尔大师和暗影议会的其它领袖都已经丧命，现在只有你能消灭那只怪物了，你将是外域唯一的希望！$B$B$N，你应该很清楚，你和你的同伴绝不能失败！',Objectives_loc4='杀死摩摩尔，然后返回沙塔斯城的圣光广场，将暗影迷宫的秘密告诉间谍女王梅丽萨·海克隆。',OfferRewardText_loc4='摩摩尔已经快要获得自由了?!他们已经控制它两年了……我怀疑是什么使他们在这么久的时间后失去对它的控制?$B$B$N，打倒那个怪物你就能拯救我们所有人!我不禁害怕要是那怪物获得自由了，那沙塔斯城及外域其它地方会变成怎样!$B$B我很高兴你帮我们取得了事情的掌控权并对付奥齐顿的暗影议会威胁。我们要怎么奖励你呢?',RequestItemsText_loc4='$N，你从暗影迷宫带回了什么消息阿?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10096,'拯救孢子人','伊卡因反复跟我描述他在洞穴中的遭遇，真是恐怖的经历！$B$B或许我们应该帮帮那些可怜的孢子人。伊卡因说他们原本居住蘑菇洞中，最近却被沼泽生物侵占了家园。$B$B前往西南方的蘑菇洞，帮孢子人干掉一些沼泽生物怎么样？','杀死10个沼泽掘泥者和10个沼泽潜伏者，然后向塞纳里奥庇护所的劳兰娜·萨维尔复命。','太好了!那些沼泽怪物们没有权利去侵犯斯柏路克的家!$B$B要是这些生物们能够学着和平共处会更好，不过那是不可能的，所以我们会在这关切情况!$B$B这里，请从中挑选一样做为你提供帮助的酬谢。','什么?这么快就回来了?变怎样了?') ON DUPLICATE KEY UPDATE Title_loc4='拯救孢子人',Details_loc4='伊卡因反复跟我描述他在洞穴中的遭遇，真是恐怖的经历！$B$B或许我们应该帮帮那些可怜的孢子人。伊卡因说他们原本居住蘑菇洞中，最近却被沼泽生物侵占了家园。$B$B前往西南方的蘑菇洞，帮孢子人干掉一些沼泽生物怎么样？',Objectives_loc4='杀死10个沼泽掘泥者和10个沼泽潜伏者，然后向塞纳里奥庇护所的劳兰娜·萨维尔复命。',OfferRewardText_loc4='太好了!那些沼泽怪物们没有权利去侵犯斯柏路克的家!$B$B要是这些生物们能够学着和平共处会更好，不过那是不可能的，所以我们会在这关切情况!$B$B这里，请从中挑选一样做为你提供帮助的酬谢。',RequestItemsText_loc4='什么?这么快就回来了?变怎样了?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText2_loc4) VALUES (10097,'兄弟反目','塞泰克在奥金顿爆炸后便离开了斯克提斯，此事的起因源于我们的主人终将降临的预言。$B$B我的兄弟塞斯是他们的领袖之一，他说我们必须进入神庙遗迹，迎接我们的神。$B$B我们在神庙废墟创建了定居点，并将它命名为塞泰克大厅；但这时，我对塞斯和他的盟友艾吉斯起了疑心。$B$B不久，塞斯就将我逐出塞泰克大厅，但是他拒绝让我带走我的妹妹拉卡。你愿意帮我救出她吗？','进入塞泰克大厅，杀死黑暗编织者塞斯，然后解救被囚禁的拉卡。完成任务后向塞泰克大厅外的伊斯法尔复命。','我没办法充分表达出我的感谢，$N。知道拉卡已经获得自由表示我能够斩断与塞泰克剩下的关联了。$B$B一部份的我对于希斯的死无法原谅我自己，但却不得不这么做。在我到达司凯堤斯后，我会为他举行葬礼。也许他的灵魂会在为将我们人民误导入歧途这件事赎罪后找到安息。','你有找到她吗，$N?她还被扣留在大厅里吗?','解救拉卡') ON DUPLICATE KEY UPDATE Title_loc4='兄弟反目',Details_loc4='塞泰克在奥金顿爆炸后便离开了斯克提斯，此事的起因源于我们的主人终将降临的预言。$B$B我的兄弟塞斯是他们的领袖之一，他说我们必须进入神庙遗迹，迎接我们的神。$B$B我们在神庙废墟创建了定居点，并将它命名为塞泰克大厅；但这时，我对塞斯和他的盟友艾吉斯起了疑心。$B$B不久，塞斯就将我逐出塞泰克大厅，但是他拒绝让我带走我的妹妹拉卡。你愿意帮我救出她吗？',Objectives_loc4='进入塞泰克大厅，杀死黑暗编织者塞斯，然后解救被囚禁的拉卡。完成任务后向塞泰克大厅外的伊斯法尔复命。',OfferRewardText_loc4='我没办法充分表达出我的感谢，$N。知道拉卡已经获得自由表示我能够斩断与塞泰克剩下的关联了。$B$B一部份的我对于希斯的死无法原谅我自己，但却不得不这么做。在我到达司凯堤斯后，我会为他举行葬礼。也许他的灵魂会在为将我们人民误导入歧途这件事赎罪后找到安息。',RequestItemsText_loc4='你有找到她吗，$N?她还被扣留在大厅里吗?',ObjectiveText2_loc4='解救拉卡';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10098,'泰罗克的传说','我的族人崇拜一位名叫泰罗克的远古英雄。小鸦人听着他的故事长大，幻想能拥有他那样漂亮的羽毛。$B$B他曾与族人们共同生活达数百年之久，却在某一天突然神秘消失，只留下了他的面具、羽毛和手稿。$B$B鸦人氏族非常珍视这些圣物。当塞泰克从斯克提斯分裂出去时，他们掳走了这几件东西，我们为此心碎不已。$B$B对于塞泰克大厅的情况，我只是略知一二，不过我把它们都写下来了，应该对你有些用处。','将泰罗克的面具、泰罗克的羽毛和泰罗克的传说交给塞泰克大厅外的伊斯法尔。','我也许永远都无法原谅自己在这场塞泰克的罪行中所扮演的脚色，但也许透过归还泰洛克的遗物这件事，我可以开始解放我自己。$B$B感谢你在这件事上的帮忙，$N。你不知道今日你所做的事是有多么的重要。','泰洛克的遗物已经从司凯堤斯离开太久了。你能把他们从塞泰克带回来吗?') ON DUPLICATE KEY UPDATE Title_loc4='泰罗克的传说',Details_loc4='我的族人崇拜一位名叫泰罗克的远古英雄。小鸦人听着他的故事长大，幻想能拥有他那样漂亮的羽毛。$B$B他曾与族人们共同生活达数百年之久，却在某一天突然神秘消失，只留下了他的面具、羽毛和手稿。$B$B鸦人氏族非常珍视这些圣物。当塞泰克从斯克提斯分裂出去时，他们掳走了这几件东西，我们为此心碎不已。$B$B对于塞泰克大厅的情况，我只是略知一二，不过我把它们都写下来了，应该对你有些用处。',Objectives_loc4='将泰罗克的面具、泰罗克的羽毛和泰罗克的传说交给塞泰克大厅外的伊斯法尔。',OfferRewardText_loc4='我也许永远都无法原谅自己在这场塞泰克的罪行中所扮演的脚色，但也许透过归还泰洛克的遗物这件事，我可以开始解放我自己。$B$B感谢你在这件事上的帮忙，$N。你不知道今日你所做的事是有多么的重要。',RequestItemsText_loc4='泰洛克的遗物已经从司凯堤斯离开太久了。你能把他们从塞泰克带回来吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10099,'主谋','那些可恶的甘尔葛仍然在不断地涌入矿井！你刚杀掉一个，马上就会又出现更多！$B$B一定有人在矿井的最深处指挥着这次入侵。上一次的战斗中你表现非常出色，圣光告诉我，恐怕你是唯一一个敢于深入矿井探险的勇士了。拜托你，找出这次入侵事件的指挥者，让他付出应有的代价！','进入荣耀堡的地下矿洞，找到并杀死兹克拉，然后向工头比格姆斯复命。','我很开心你试着去处里这个，这个……你说他叫他自己什么来着?希卡洛?$B$B从你的描述中，听起来比较像是“它”而不是“他”不过无论怎样结果就是它死了。','我几乎不敢问。看到你安好的从矿坑里走出来代表着有两种可能:要不就是你杀了那怪物，要不就是你失去了你的胆量。那么，是哪一个呢?') ON DUPLICATE KEY UPDATE Title_loc4='主谋',Details_loc4='那些可恶的甘尔葛仍然在不断地涌入矿井！你刚杀掉一个，马上就会又出现更多！$B$B一定有人在矿井的最深处指挥着这次入侵。上一次的战斗中你表现非常出色，圣光告诉我，恐怕你是唯一一个敢于深入矿井探险的勇士了。拜托你，找出这次入侵事件的指挥者，让他付出应有的代价！',Objectives_loc4='进入荣耀堡的地下矿洞，找到并杀死兹克拉，然后向工头比格姆斯复命。',OfferRewardText_loc4='我很开心你试着去处里这个，这个……你说他叫他自己什么来着?希卡洛?$B$B从你的描述中，听起来比较像是“它”而不是“他”不过无论怎样结果就是它死了。',RequestItemsText_loc4='我几乎不敢问。看到你安好的从矿坑里走出来代表着有两种可能:要不就是你杀了那怪物，要不就是你失去了你的胆量。那么，是哪一个呢?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10100,'幕后的黑手','不要误会我的意思，$N，我当然会很高兴有你来帮助我们解决矿井的问题，但是你每杀掉一个隧道矿工，马上会有成双成倍的出现在你面前。$B$B我已经向警备队长克朗克说过了，但是他仍然拒绝向我提供任何帮助。他一直在暗自抱怨地狱野猪。如果我能肯定他不会打我的话，我一定会告诉他已经没有时间再去想这个微不足道的事了！$B$B不管怎样，看上去已经有人进驻到矿井中去指挥所有的事情了。把他找出来，杀掉他！','找到萨尔玛矿井中的乌尔卡斯，杀掉他。然后返回向工头拉泽克拉兹复命。','但愿，除掉他们的监督者后能够使其它残馀者惊慌四散。这样我的人应该可以很容易得清掉他们，一旦我找到让他们清醒过来的方法。','你有办法从这所有线索中找到这个罪人吗?') ON DUPLICATE KEY UPDATE Title_loc4='幕后的黑手',Details_loc4='不要误会我的意思，$N，我当然会很高兴有你来帮助我们解决矿井的问题，但是你每杀掉一个隧道矿工，马上会有成双成倍的出现在你面前。$B$B我已经向警备队长克朗克说过了，但是他仍然拒绝向我提供任何帮助。他一直在暗自抱怨地狱野猪。如果我能肯定他不会打我的话，我一定会告诉他已经没有时间再去想这个微不足道的事了！$B$B不管怎样，看上去已经有人进驻到矿井中去指挥所有的事情了。把他找出来，杀掉他！',Objectives_loc4='找到萨尔玛矿井中的乌尔卡斯，杀掉他。然后返回向工头拉泽克拉兹复命。',OfferRewardText_loc4='但愿，除掉他们的监督者后能够使其它残馀者惊慌四散。这样我的人应该可以很容易得清掉他们，一旦我找到让他们清醒过来的方法。',RequestItemsText_loc4='你有办法从这所有线索中找到这个罪人吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10101,'灵魂之语','巨大的钻石山——沃舒古，曾是兽人一族的圣地。每年春天，各个氏族都会聚集在沃舒古，欢庆万物的复苏。萨满祭司在那里与先祖的灵魂进行沟通。在黑暗侵袭我们之前，沃舒古一直是我们兽人文化的核心。但是，自从兽人氏族联合起来成为部落之后，沃舒古的先祖灵魂便陷入了沉寂，不再理会我们。$B$B现在，不知是什么惊扰了他们的长眠。前往沃舒古，查明是什么在滋扰那些灵魂。','纳格兰先祖之地的卡舒尔宗母要求你前往沃舒古寻找克乌雷。','<一股温和，优美的声音充满你的内心。>$B$B我是纳鲁的库尔，$N。你正站在我先祖的船舰中央。$B$B欧夏刚，兽人如此称呼它，是第一艘将德莱尼带来这世界的船舰。虽然我们几百年前从天堂墬毁在这，我衰弱的能量持续困在这个残骸里。很遗憾的，我就是兽人灵魂烦恼的来源。','<库尔的手脚随着身体的光源振动同时的移动起伏。>') ON DUPLICATE KEY UPDATE Title_loc4='灵魂之语',Details_loc4='巨大的钻石山——沃舒古，曾是兽人一族的圣地。每年春天，各个氏族都会聚集在沃舒古，欢庆万物的复苏。萨满祭司在那里与先祖的灵魂进行沟通。在黑暗侵袭我们之前，沃舒古一直是我们兽人文化的核心。但是，自从兽人氏族联合起来成为部落之后，沃舒古的先祖灵魂便陷入了沉寂，不再理会我们。$B$B现在，不知是什么惊扰了他们的长眠。前往沃舒古，查明是什么在滋扰那些灵魂。',Objectives_loc4='纳格兰先祖之地的卡舒尔宗母要求你前往沃舒古寻找克乌雷。',OfferRewardText_loc4='<一股温和，优美的声音充满你的内心。>$B$B我是纳鲁的库尔，$N。你正站在我先祖的船舰中央。$B$B欧夏刚，兽人如此称呼它，是第一艘将德莱尼带来这世界的船舰。虽然我们几百年前从天堂墬毁在这，我衰弱的能量持续困在这个残骸里。很遗憾的，我就是兽人灵魂烦恼的来源。',RequestItemsText_loc4='<库尔的手脚随着身体的光源振动同时的移动起伏。>';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10102,'谜底揭晓','数百年来，我体内的能量不断衰减，这导致沃舒古的中心渐渐形成了一处虚空，开始吞噬附近的灵魂。我眼睁睁地看着这么多兽人的灵魂被吸入漩涡却无能为力。最近，我的敌人又利用虚空漩涡召唤出大量恶魔，把它们编入燃烧军团。$B$B只有阿达尔能封印我的虚空漩涡，解放兽人的灵魂。去泰罗卡森林的沙塔斯城找他吧，我感觉得到，他就在那里。','与沙塔斯城的阿达尔谈一谈。','库尔派你来是明智之举。虽然我们无法协助你和那些受苦的兽人祖先，但有一个人可以。$B$B那个人即将随着圣光而重生……','<阿达尔的身体旋转和律动如同舒服的声音充满你的心里。>$B$B我们没有办法去解决玛格汉的困境。') ON DUPLICATE KEY UPDATE Title_loc4='谜底揭晓',Details_loc4='数百年来，我体内的能量不断衰减，这导致沃舒古的中心渐渐形成了一处虚空，开始吞噬附近的灵魂。我眼睁睁地看着这么多兽人的灵魂被吸入漩涡却无能为力。最近，我的敌人又利用虚空漩涡召唤出大量恶魔，把它们编入燃烧军团。$B$B只有阿达尔能封印我的虚空漩涡，解放兽人的灵魂。去泰罗卡森林的沙塔斯城找他吧，我感觉得到，他就在那里。',Objectives_loc4='与沙塔斯城的阿达尔谈一谈。',OfferRewardText_loc4='库尔派你来是明智之举。虽然我们无法协助你和那些受苦的兽人祖先，但有一个人可以。$B$B那个人即将随着圣光而重生……',RequestItemsText_loc4='<阿达尔的身体旋转和律动如同舒服的声音充满你的心里。>$B$B我们没有办法去解决玛格汉的困境。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10103,'向祖莱报到','随着战地指挥官洛姆斯和他麾下军队的到达，联盟和他们的德莱尼朋友们现在变得越来越大胆了。他们将这里一直到沙塔斯城的每一个旧德莱尼废墟都占据并武装了起来。$B$B相应的，巨魔们也在赞加沼泽东边的死亡泥潭南侧创建了一处新的前哨站，似乎是叫沼泽鼠岗哨。我很高兴他们居然能适应那里的艰难环境，反正我是无法忍受的。$B$B最近，岗哨的指挥官要我派些多馀的人手过去，你过去看看吧。','前往赞加沼泽的沼泽鼠岗哨，向祖莱报到。','老实说，我本来期待的更多，不过你都得去做。欢迎到斯温派特岗哨来。','你是从猎鹰哨站来的援军吗?') ON DUPLICATE KEY UPDATE Title_loc4='向祖莱报到',Details_loc4='随着战地指挥官洛姆斯和他麾下军队的到达，联盟和他们的德莱尼朋友们现在变得越来越大胆了。他们将这里一直到沙塔斯城的每一个旧德莱尼废墟都占据并武装了起来。$B$B相应的，巨魔们也在赞加沼泽东边的死亡泥潭南侧创建了一处新的前哨站，似乎是叫沼泽鼠岗哨。我很高兴他们居然能适应那里的艰难环境，反正我是无法忍受的。$B$B最近，岗哨的指挥官要我派些多馀的人手过去，你过去看看吧。',Objectives_loc4='前往赞加沼泽的沼泽鼠岗哨，向祖莱报到。',OfferRewardText_loc4='老实说，我本来期待的更多，不过你都得去做。欢迎到斯温派特岗哨来。',RequestItemsText_loc4='你是从猎鹰哨站来的援军吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10104,'图雷姆的事务','来自图雷姆的传闻令人不安。据说疯狂的破碎者和失落者占据了城镇的废墟，猎人们则趁机盗取德莱尼氏族的圣物。$B$B很难确定这消息是真是假，但是我们有责任保卫图雷姆。前往泰罗卡森林的奥蕾莉亚要塞，与安达尔谈谈。他似乎是研究圣物的学者，应该比别人更清楚图雷姆的现状。','与泰罗卡森林奥蕾莉亚要塞的安达尔谈一谈。','我很高兴你的破碎者朋友觉得我是他们圣物的专家，但老实说，自从到达这里后我还没有多馀的时间去研究它们。那绝对是我的目的，但是在我抵达后，我发现有其它的东西吸引了我的注意力。','我不认为我之前曾在这见过你，$C。我可以怎么帮你呢?') ON DUPLICATE KEY UPDATE Title_loc4='图雷姆的事务',Details_loc4='来自图雷姆的传闻令人不安。据说疯狂的破碎者和失落者占据了城镇的废墟，猎人们则趁机盗取德莱尼氏族的圣物。$B$B很难确定这消息是真是假，但是我们有责任保卫图雷姆。前往泰罗卡森林的奥蕾莉亚要塞，与安达尔谈谈。他似乎是研究圣物的学者，应该比别人更清楚图雷姆的现状。',Objectives_loc4='与泰罗卡森林奥蕾莉亚要塞的安达尔谈一谈。',OfferRewardText_loc4='我很高兴你的破碎者朋友觉得我是他们圣物的专家，但老实说，自从到达这里后我还没有多馀的时间去研究它们。那绝对是我的目的，但是在我抵达后，我发现有其它的东西吸引了我的注意力。',RequestItemsText_loc4='我不认为我之前曾在这见过你，$C。我可以怎么帮你呢?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10105,'给拉克妮亚的消息','沼泽鼠岗哨已经建成，但是我们对赞加沼泽进出道路的控制依然非常薄弱。泰罗克森林也不甚安全。尽管如此，裂石堡的拉克妮亚还是希望获得岗哨建设进展的消息。$B$B$N，她是个精明能干的人，跟她打交道一定要多加小心。拉克妮亚希望利用这些道路运输货物，但是别指望她会考虑到我们的利益。哪儿有钱赚，她就往哪儿钻。','与泰罗卡森林裂石堡的拉克妮亚谈一谈。','我希望他的人可以尽快将岗哨完成，但是不是花他的钱。尽管如此，仍在进行中。','你从祖瑞伊那带来了什么消息吗?') ON DUPLICATE KEY UPDATE Title_loc4='给拉克妮亚的消息',Details_loc4='沼泽鼠岗哨已经建成，但是我们对赞加沼泽进出道路的控制依然非常薄弱。泰罗克森林也不甚安全。尽管如此，裂石堡的拉克妮亚还是希望获得岗哨建设进展的消息。$B$B$N，她是个精明能干的人，跟她打交道一定要多加小心。拉克妮亚希望利用这些道路运输货物，但是别指望她会考虑到我们的利益。哪儿有钱赚，她就往哪儿钻。',Objectives_loc4='与泰罗卡森林裂石堡的拉克妮亚谈一谈。',OfferRewardText_loc4='我希望他的人可以尽快将岗哨完成，但是不是花他的钱。尽管如此，仍在进行中。',RequestItemsText_loc4='你从祖瑞伊那带来了什么消息吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4,ObjectiveText2_loc4,ObjectiveText3_loc4) VALUES (10106,'地狱火半岛的工事','地狱火堡垒与我们的军队一直有着小规模的冲突与交战。目前，我们自己的领地大多守备稳固，但一直没能对他们发动真正的进攻。为了筹备进攻，我们要首先占领地狱火堡垒外围的战略要地。$B$B我们的斥候目前确定了三处互成犄角之势的工事，希望你能协助这三处的防守。占领所有工事之后回来向我报告。$B$B愿你能在接下来的战斗中有好运气，$N，毫无疑问，你得面对部落的威胁，他们也同样想占领这三处重要的工事。','占领了望台、竞赛场和碎石岭，然后向地狱火半岛上荣耀堡内的委任官翠希·普罗维尔复命。','做的好，$N。你这次的行动有助于我们在地狱火半岛的战斗。','$N，等你协助完每一个堡垒的占领行动后回来找我!','占领了望台','占领竞赛场','占领碎石岭') ON DUPLICATE KEY UPDATE Title_loc4='地狱火半岛的工事',Details_loc4='地狱火堡垒与我们的军队一直有着小规模的冲突与交战。目前，我们自己的领地大多守备稳固，但一直没能对他们发动真正的进攻。为了筹备进攻，我们要首先占领地狱火堡垒外围的战略要地。$B$B我们的斥候目前确定了三处互成犄角之势的工事，希望你能协助这三处的防守。占领所有工事之后回来向我报告。$B$B愿你能在接下来的战斗中有好运气，$N，毫无疑问，你得面对部落的威胁，他们也同样想占领这三处重要的工事。',Objectives_loc4='占领了望台、竞赛场和碎石岭，然后向地狱火半岛上荣耀堡内的委任官翠希·普罗维尔复命。',OfferRewardText_loc4='做的好，$N。你这次的行动有助于我们在地狱火半岛的战斗。',RequestItemsText_loc4='$N，等你协助完每一个堡垒的占领行动后回来找我!',ObjectiveText1_loc4='占领了望台',ObjectiveText2_loc4='占领竞赛场',ObjectiveText3_loc4='占领碎石岭';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,EndText_loc4) VALUES (10107,'外交手段','根据吉尔拉斯的最新情报，石拳食人魔的首领居然是个兽人！这位兽人长者曾经与我们的父辈一起跨越黑暗之门作战，回来后便一直居住在火刃废墟中。我想派你去寻找这位兽人的下落，并试着说服他召回石拳食人魔。此地东南方，纳格兰与泰罗卡森林交界处便是火刃废墟，他就居住在废墟的上层平台。$N，祝你好运！$B$B当心，他是位剑圣……','加拉达尔的约林·死眼要你前往火刃废墟，找兰特瑞索·火刃谈一谈。','所以你的决定是什么?是要战斗还是提供你的协助?','说吧。','聆听剑圣的故事') ON DUPLICATE KEY UPDATE Title_loc4='外交手段',Details_loc4='根据吉尔拉斯的最新情报，石拳食人魔的首领居然是个兽人！这位兽人长者曾经与我们的父辈一起跨越黑暗之门作战，回来后便一直居住在火刃废墟中。我想派你去寻找这位兽人的下落，并试着说服他召回石拳食人魔。此地东南方，纳格兰与泰罗卡森林交界处便是火刃废墟，他就居住在废墟的上层平台。$N，祝你好运！$B$B当心，他是位剑圣……',Objectives_loc4='加拉达尔的约林·死眼要你前往火刃废墟，找兰特瑞索·火刃谈一谈。',OfferRewardText_loc4='所以你的决定是什么?是要战斗还是提供你的协助?',RequestItemsText_loc4='说吧。',EndText_loc4='聆听剑圣的故事';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,EndText_loc4) VALUES (10108,'外交手段','据女猎手的密探汇报，石拳部族的领主是位兽人！这位生活在我们父辈那个年代的兽人长者曾经跨越黑暗之门作战，回来后便一直居住在火刃废墟中。我想派你去寻找这位兽人的下落，并试着说服他召回石拳食人魔。此地东方就是火刃废墟，他就居住在废墟的上层平台。$N，祝你好运！$B$B当心，他是位剑圣……','塔拉的击碎者姆摩尔要你去跟火刃废墟的兰特瑞索·火刃谈一谈。','所以你的决定是什么?是要战斗还是提供你的协助?','说吧。','聆听剑圣的故事') ON DUPLICATE KEY UPDATE Title_loc4='外交手段',Details_loc4='据女猎手的密探汇报，石拳部族的领主是位兽人！这位生活在我们父辈那个年代的兽人长者曾经跨越黑暗之门作战，回来后便一直居住在火刃废墟中。我想派你去寻找这位兽人的下落，并试着说服他召回石拳食人魔。此地东方就是火刃废墟，他就居住在废墟的上层平台。$N，祝你好运！$B$B当心，他是位剑圣……',Objectives_loc4='塔拉的击碎者姆摩尔要你去跟火刃废墟的兰特瑞索·火刃谈一谈。',OfferRewardText_loc4='所以你的决定是什么?是要战斗还是提供你的协助?',RequestItemsText_loc4='说吧。',EndText_loc4='聆听剑圣的故事';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10109,'我想要这些鸟蛋！','瞧见那些鸟蛋了吗？以口臭的加兹鲁维的名义发誓，我一定要搞到这些蛋！唔，你看上去很能打的样子。$B$B$r，如果你能为我收集一样东西，等我调试好超级蹦床4000型，我就送你一把启动这玩意的钥匙！你想知道超级蹦床4000型有什么用处？有了这宝贝，你几乎什么都能做……$B$B我要你从纳格兰的大气元素身上收集气元素实体。别跟我说你找不到气元素，它们遍布整个纳格兰！','将3份气元素实体交给纳格兰南部氏族岗哨对面的瓦萨特。','太棒了!现在只要些许的调整这个东西就会像新的一样棒了。喔对了，你的钥匙!拿去吧。$B$B顺带一提，这个装置还是有一些技术性问题需要解决。呃，小心一点就是了。','拿到气体了吗?') ON DUPLICATE KEY UPDATE Title_loc4='我想要这些鸟蛋！',Details_loc4='瞧见那些鸟蛋了吗？以口臭的加兹鲁维的名义发誓，我一定要搞到这些蛋！唔，你看上去很能打的样子。$B$B$r，如果你能为我收集一样东西，等我调试好超级蹦床4000型，我就送你一把启动这玩意的钥匙！你想知道超级蹦床4000型有什么用处？有了这宝贝，你几乎什么都能做……$B$B我要你从纳格兰的大气元素身上收集气元素实体。别跟我说你找不到气元素，它们遍布整个纳格兰！',Objectives_loc4='将3份气元素实体交给纳格兰南部氏族岗哨对面的瓦萨特。',OfferRewardText_loc4='太棒了!现在只要些许的调整这个东西就会像新的一样棒了。喔对了，你的钥匙!拿去吧。$B$B顺带一提，这个装置还是有一些技术性问题需要解决。呃，小心一点就是了。',RequestItemsText_loc4='拿到气体了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4,ObjectiveText2_loc4,ObjectiveText3_loc4) VALUES (10110,'地狱火半岛的工事','在我们的故乡肆虐的所有地狱火堡垒邪兽人都必须要消灭干净！但要想攻击地狱火堡垒，我们必须首先占领堡垒外围的几处战略要地。$B$B巡逻队发现有三处工事正好适合我们的目的。但联盟竟与我们不谋而合，现在已经派出部队占领了那里！$B$B我要求你立刻阻止联盟的行动，并占领这些工事。协助我军占领工事之后，立刻回来向我报告。$B$B为了部落！','占领了望台、竞赛场和碎石岭，然后向地狱火半岛上萨尔玛的传令官布莱肯·黑眼复命。','做的好，$N。我几乎可以听到在那些堡垒战斗的声音。我真希望在那里看见他们!','在你协助占领完每一个堡垒后回来找我吧!','占领了望台','占领竞赛场','占领碎石岭') ON DUPLICATE KEY UPDATE Title_loc4='地狱火半岛的工事',Details_loc4='在我们的故乡肆虐的所有地狱火堡垒邪兽人都必须要消灭干净！但要想攻击地狱火堡垒，我们必须首先占领堡垒外围的几处战略要地。$B$B巡逻队发现有三处工事正好适合我们的目的。但联盟竟与我们不谋而合，现在已经派出部队占领了那里！$B$B我要求你立刻阻止联盟的行动，并占领这些工事。协助我军占领工事之后，立刻回来向我报告。$B$B为了部落！',Objectives_loc4='占领了望台、竞赛场和碎石岭，然后向地狱火半岛上萨尔玛的传令官布莱肯·黑眼复命。',OfferRewardText_loc4='做的好，$N。我几乎可以听到在那些堡垒战斗的声音。我真希望在那里看见他们!',RequestItemsText_loc4='在你协助占领完每一个堡垒后回来找我吧!',ObjectiveText1_loc4='占领了望台',ObjectiveText2_loc4='占领竞赛场',ObjectiveText3_loc4='占领碎石岭';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4) VALUES (10111,'给我鸟蛋！','你已经拿到了钥匙，现在我要你从树上给我取一枚鸟蛋来！使用超级蹦床4000型跳上鸟巢。要小心！跳得不好的话难免会受伤流血，甚至可能永久残废呢。','纳格兰的瓦萨特要你利用超级蹦床4000型从附近树上的鸟巢中偷取神秘的鸟蛋。','嗯，这不是蛋……嘿!我也爱鸡!我只要拿菜刀从它的鸡爪中间切下去就可以了!感谢你!','我有跟你说我对蛋的爱恋程度吗?','尝试偷取鸟蛋') ON DUPLICATE KEY UPDATE Title_loc4='给我鸟蛋！',Details_loc4='你已经拿到了钥匙，现在我要你从树上给我取一枚鸟蛋来！使用超级蹦床4000型跳上鸟巢。要小心！跳得不好的话难免会受伤流血，甚至可能永久残废呢。',Objectives_loc4='纳格兰的瓦萨特要你利用超级蹦床4000型从附近树上的鸟巢中偷取神秘的鸟蛋。',OfferRewardText_loc4='嗯，这不是蛋……嘿!我也爱鸡!我只要拿菜刀从它的鸡爪中间切下去就可以了!感谢你!',RequestItemsText_loc4='我有跟你说我对蛋的爱恋程度吗?',ObjectiveText1_loc4='尝试偷取鸟蛋';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10112,'私人事务','嗯？你说的是一盒东西？还是好几盒？你知道盒子是用什么材制成的吗？$B$B还有，这名商人叫什么来着？埃博尔？你确定他是个破碎者吗？我跟破碎者很少有贸易往来。$B$B如果你能帮我个忙，我或许能想起点什么。$B$B基斯鸦人是一群远古的施法者，最近他们从我这儿偷走了一批珍奇的货物。我要找回那批货物！$B$B基斯鸦人就聚集在沙塔斯城以南的基斯鸦巢。','将5箱拉斯莱的货物交给沙塔斯城贫民窟天涯旅店附近的星界商人拉斯莱。','是的，没错，我真的确定现在都想起来了。$B$B而我认为你在这件事上的努力值得比得到你所需要的消息来的更多。','嗯，我的记忆有增进吗?') ON DUPLICATE KEY UPDATE Title_loc4='私人事务',Details_loc4='嗯？你说的是一盒东西？还是好几盒？你知道盒子是用什么材制成的吗？$B$B还有，这名商人叫什么来着？埃博尔？你确定他是个破碎者吗？我跟破碎者很少有贸易往来。$B$B如果你能帮我个忙，我或许能想起点什么。$B$B基斯鸦人是一群远古的施法者，最近他们从我这儿偷走了一批珍奇的货物。我要找回那批货物！$B$B基斯鸦人就聚集在沙塔斯城以南的基斯鸦巢。',Objectives_loc4='将5箱拉斯莱的货物交给沙塔斯城贫民窟天涯旅店附近的星界商人拉斯莱。',OfferRewardText_loc4='是的，没错，我真的确定现在都想起来了。$B$B而我认为你在这件事上的努力值得比得到你所需要的消息来的更多。',RequestItemsText_loc4='嗯，我的记忆有增进吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10113,'奈辛瓦里狩猎队','他说，“出去给我们搞些物资来。”我15次死里逃生，历尽艰辛，终于找到了这块地方！这些破碎者虽然不甚好客，可至少不会剥了我的皮。$B$B我说什么都不会回去的，狩猎为生的岁月已经结束了！如果你打算前往东北方的赞加沼泽，就替我向奈辛瓦里狩猎队营地的那帮家伙传个话，告诉他们，我“猎枪”不干了。$B$B嗨，说不定你能顶替我的位置！陌生人，祝你好运。','“猎枪”琼斯要你前往纳格兰东北边界的奈辛瓦里狩猎队营地，找赫米特·奈辛瓦里谈一谈。','我想我们得找一个替换的助理。喂，你看起来挺有力的$C。有没有兴趣找个工作啊?或者你是来打猎的?','我就知道他是最没用的那一个。') ON DUPLICATE KEY UPDATE Title_loc4='奈辛瓦里狩猎队',Details_loc4='他说，“出去给我们搞些物资来。”我15次死里逃生，历尽艰辛，终于找到了这块地方！这些破碎者虽然不甚好客，可至少不会剥了我的皮。$B$B我说什么都不会回去的，狩猎为生的岁月已经结束了！如果你打算前往东北方的赞加沼泽，就替我向奈辛瓦里狩猎队营地的那帮家伙传个话，告诉他们，我“猎枪”不干了。$B$B嗨，说不定你能顶替我的位置！陌生人，祝你好运。',Objectives_loc4='“猎枪”琼斯要你前往纳格兰东北边界的奈辛瓦里狩猎队营地，找赫米特·奈辛瓦里谈一谈。',OfferRewardText_loc4='我想我们得找一个替换的助理。喂，你看起来挺有力的$C。有没有兴趣找个工作啊?或者你是来打猎的?',RequestItemsText_loc4='我就知道他是最没用的那一个。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10114,'奈辛瓦里狩猎队','这帮兽人从来没有见过牛头人，你相信吗？要不是克洛坎上尉，他们恐怕早就把我给做成牛排给吃了。$B$B啊，忘记自我介绍了，真是失礼！我是杰出的猎手欧洛恩·远行者！身为奈辛瓦里狩猎队的成员，我从艾泽拉斯世界来到这儿探险。如果你对狩猎感兴趣的话，可以前往东边奈辛瓦里狩猎队营地碰碰运气，营地就在纳格兰和赞加沼泽的边界附近。','欧洛恩·远行者要你前往纳格兰的奈辛瓦里狩猎队营地，跟“好儿子”沙度·远行者谈一谈。','听到他还安好让我松了口气。你有参加狩猎吗?','你找到我兄弟吗?真棒的消息啊!') ON DUPLICATE KEY UPDATE Title_loc4='奈辛瓦里狩猎队',Details_loc4='这帮兽人从来没有见过牛头人，你相信吗？要不是克洛坎上尉，他们恐怕早就把我给做成牛排给吃了。$B$B啊，忘记自我介绍了，真是失礼！我是杰出的猎手欧洛恩·远行者！身为奈辛瓦里狩猎队的成员，我从艾泽拉斯世界来到这儿探险。如果你对狩猎感兴趣的话，可以前往东边奈辛瓦里狩猎队营地碰碰运气，营地就在纳格兰和赞加沼泽的边界附近。',Objectives_loc4='欧洛恩·远行者要你前往纳格兰的奈辛瓦里狩猎队营地，跟“好儿子”沙度·远行者谈一谈。',OfferRewardText_loc4='听到他还安好让我松了口气。你有参加狩猎吗?',RequestItemsText_loc4='你找到我兄弟吗?真棒的消息啊!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10115,'匕潭的威胁','库雷尼人和德莱尼人常常会出现意见分歧，尤其是在对待失落者的问题上。我们乐意去帮助那些向我们求助的失落者，但不会主动伸出援手。德莱尼人则想要使所有的失落者得到“救赎”。$B$B但是，某些失落者部族已经偏离了正道，例如匕潭失落者。此地西边就是他们的村落，匕潭失落者滥用毒药、善于欺诈，他们的恶行已经到了难以容忍的地步。$B$B我们必须好好教训这帮渣滓，不能任由他们胡作非为。','杀死3个匕潭刺客和15个匕潭泥居者。','你做的很好，$N。匕首沼地者远在任何的正常规范之外，不过我不确定德莱尼会在这状况中适当的采取行动。','你有看到这些匕首沼地者做了什么吗?现在你了解为什么我们必须将他们与其它失落者隔离了吧。') ON DUPLICATE KEY UPDATE Title_loc4='匕潭的威胁',Details_loc4='库雷尼人和德莱尼人常常会出现意见分歧，尤其是在对待失落者的问题上。我们乐意去帮助那些向我们求助的失落者，但不会主动伸出援手。德莱尼人则想要使所有的失落者得到“救赎”。$B$B但是，某些失落者部族已经偏离了正道，例如匕潭失落者。此地西边就是他们的村落，匕潭失落者滥用毒药、善于欺诈，他们的恶行已经到了难以容忍的地步。$B$B我们必须好好教训这帮渣滓，不能任由他们胡作非为。',Objectives_loc4='杀死3个匕潭刺客和15个匕潭泥居者。',OfferRewardText_loc4='你做的很好，$N。匕首沼地者远在任何的正常规范之外，不过我不确定德莱尼会在这状况中适当的采取行动。',RequestItemsText_loc4='你有看到这些匕首沼地者做了什么吗?现在你了解为什么我们必须将他们与其它失落者隔离了吧。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10116,'通缉：穆玛基酋长','通缉：穆玛基酋长！邪恶堕落的匕潭部族首领因对奥雷柏尔营地犯下的罪行而被通缉。$B$B穆玛基和他的同党必须为数起谋杀库雷尼和德莱尼的行径付出代价。只有经验丰富的勇士才能击败他。$B$B旅行者应该尽量避免在奥雷柏尔营地西边的匕潭村区域行走。$B$B领取奖赏者必须向伊库提出示足以证明自己杀掉穆玛基酋长的证据。','将穆玛基酋长的图腾交给奥雷柏尔营地的伊库提。','太棒了!有许多人想要领取这份奖赏，但都没有回来过。不难了解他们发生了什么事。
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10117,'通缉：穆玛基酋长','通缉：穆玛基酋长！邪恶堕落的匕潭部族首领因对萨布拉金犯下的罪行而被通缉。$B$B穆玛基和他的同党必须为数起谋杀信使和斥候的行径付出代价。只有经验丰富的勇士才能击败他。$B$B旅行者应该尽量避免在萨布拉金西北边的匕潭村区域行走。$B$B领取奖赏者必须向暗影猎手德恩加出示足以证明自己杀掉穆玛基酋长的证据。','将穆玛基酋长的图腾交给暗影猎手德恩加。','你拥有我的感激，$N。我都已经开始打算我必须自己带领大批的军力去那里解决掉姆玛奇。当然，就没有办法知道之后萨布拉金会发生什么事了。$B','你想要领取姆玛奇酋长的奖赏吗?') ON DUPLICATE KEY UPDATE Title_loc4='通缉：穆玛基酋长',Details_loc4='通缉：穆玛基酋长！邪恶堕落的匕潭部族首领因对萨布拉金犯下的罪行而被通缉。$B$B穆玛基和他的同党必须为数起谋杀信使和斥候的行径付出代价。只有经验丰富的勇士才能击败他。$B$B旅行者应该尽量避免在萨布拉金西北边的匕潭村区域行走。$B$B领取奖赏者必须向暗影猎手德恩加出示足以证明自己杀掉穆玛基酋长的证据。',Objectives_loc4='将穆玛基酋长的图腾交给暗影猎手德恩加。',OfferRewardText_loc4='你拥有我的感激，$N。我都已经开始打算我必须自己带领大批的军力去那里解决掉姆玛奇。当然，就没有办法知道之后萨布拉金会发生什么事了。$B',RequestItemsText_loc4='你想要领取姆玛奇酋长的奖赏吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10118,'警告匕潭失落者','在赞加沼泽的所有失落者部族中，匕潭失落者以狡猾和侵略性着称。他们的组织性极强，从不掩饰想控制沼泽地中其它失落者的野心。$B$B死在他们手中的斥候和信使已经不计其数，我再也经不起任何人员伤亡了。$B$B如果我们不赶快采取行动的话，他们就会完全控制萨布拉金附近的所有通道。','杀死3个匕潭刺客和15个匕潭泥居者，然后返回萨布拉金向暗影猎手德恩加复命。','我认为你可以试着传送一则相当强烈的讯息给他们。也许现在，剩下的其它人就不会如此害怕与匕首沼地者对战。或者，要是他们会怕，他们会因缺乏勇气而觉得羞耻。','匕首沼地者唯一了解的事就是快速又残暴的攻击。他们应该知道我们不会让他们任意妄为。') ON DUPLICATE KEY UPDATE Title_loc4='警告匕潭失落者',Details_loc4='在赞加沼泽的所有失落者部族中，匕潭失落者以狡猾和侵略性着称。他们的组织性极强，从不掩饰想控制沼泽地中其它失落者的野心。$B$B死在他们手中的斥候和信使已经不计其数，我再也经不起任何人员伤亡了。$B$B如果我们不赶快采取行动的话，他们就会完全控制萨布拉金附近的所有通道。',Objectives_loc4='杀死3个匕潭刺客和15个匕潭泥居者，然后返回萨布拉金向暗影猎手德恩加复命。',OfferRewardText_loc4='我认为你可以试着传送一则相当强烈的讯息给他们。也许现在，剩下的其它人就不会如此害怕与匕首沼地者对战。或者，要是他们会怕，他们会因缺乏勇气而觉得羞耻。',RequestItemsText_loc4='匕首沼地者唯一了解的事就是快速又残暴的攻击。他们应该知道我们不会让他们任意妄为。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10119,'跨越黑暗之门','20年来，黑暗之门一直是一座无声的纪念碑，对一段早已被忘却的历史的纪念。$B$B<雷索恩环视四周。>$B$B我从未想到过自己会看到这一天的到来，但是我们就站在这里，望向无底的深渊。$B$B我们的军队在黑暗之门的另一侧陷入混战，如果得不到支持的话，我们很可能会输掉这场残酷的战争。$C，你必须跨越黑暗之门，伸出援手。$B$B立即向指挥官杜隆报到吧。他就在外域等着你……','穿越黑暗之门，找到指挥官杜隆。他就在黑暗之门另一侧的外域等你。','欢迎来到外域，$N - 欢迎来到梦魇里。虽然最初的远征军使它未受损伤，但燃烧军团企图将黑暗之门重新拿下以阻止我们的援兵抵达。
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10120,'抵达外域','我手下的部队目前在联盟的帮助下正坚守着这里的防线，不过，我需要你帮助我送一份报告到萨尔玛去，递交给克拉库克将军。有了他的帮助，我们就可以把这些恶魔一扫而空，彻底赶回他们的深渊老家去！跟后面平台上的维拉加·乱羽谈谈吧。她会送你尽快过去的。','地狱火半岛上黑暗之门旁的沃雷恩中将要求你将沃雷恩的报告交给维拉加·乱羽。','所以你是欧莱恩新的传令员吗?我祈祷你的遭遇会比上次他派来的那个好一点，$C。随着军团的逼近，你绝对没有办法徒步送回萨尔玛的。说吧，我的双足翼龙会将你安全送达那里。','我看到你在跟欧莱恩谈话 - 一定是很重要的事吧……') ON DUPLICATE KEY UPDATE Title_loc4='抵达外域',Details_loc4='我手下的部队目前在联盟的帮助下正坚守着这里的防线，不过，我需要你帮助我送一份报告到萨尔玛去，递交给克拉库克将军。有了他的帮助，我们就可以把这些恶魔一扫而空，彻底赶回他们的深渊老家去！跟后面平台上的维拉加·乱羽谈谈吧。她会送你尽快过去的。',Objectives_loc4='地狱火半岛上黑暗之门旁的沃雷恩中将要求你将沃雷恩的报告交给维拉加·乱羽。',OfferRewardText_loc4='所以你是欧莱恩新的传令员吗?我祈祷你的遭遇会比上次他派来的那个好一点，$C。随着军团的逼近，你绝对没有办法徒步送回萨尔玛的。说吧，我的双足翼龙会将你安全送达那里。',RequestItemsText_loc4='我看到你在跟欧莱恩谈话 - 一定是很重要的事吧……';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10121,'消灭燃烧军团','这里到处都是新的敌人，但燃烧军团仍旧是我们远征军最大的威胁。我最信赖的一位军官——斯古尔·碎颅者中士最近一直在研究燃烧军团的战术，也试图了解他们来到这里的真正目的。去南墙外的补给车队那里找他吧。$B$B$N，一定要小心燃烧军团。千万别低估了这群阴险狡诈的东西。','前往萨尔玛以东的补给车队，与斯古尔·碎颅者中士谈一谈。','毫无疑问的在你从黑暗之门来的飞行途中可以看到岛上遍布着军团的士兵。虽然我们在约五年前的海加尔山战役中击败了他们，这些邪恶的恶魔还是不停的回来。如果这是他们所渴望的挑战，那么部落也会相同的回应他们!$B$B我们兽人有许多消灭军团的理由。你呢，$N?我该不该告诉你有关我们敌人的事呢?','<碎颅中士没有注意到你。他看起来有点疲惫。>') ON DUPLICATE KEY UPDATE Title_loc4='消灭燃烧军团',Details_loc4='这里到处都是新的敌人，但燃烧军团仍旧是我们远征军最大的威胁。我最信赖的一位军官——斯古尔·碎颅者中士最近一直在研究燃烧军团的战术，也试图了解他们来到这里的真正目的。去南墙外的补给车队那里找他吧。$B$B$N，一定要小心燃烧军团。千万别低估了这群阴险狡诈的东西。',Objectives_loc4='前往萨尔玛以东的补给车队，与斯古尔·碎颅者中士谈一谈。',OfferRewardText_loc4='毫无疑问的在你从黑暗之门来的飞行途中可以看到岛上遍布着军团的士兵。虽然我们在约五年前的海加尔山战役中击败了他们，这些邪恶的恶魔还是不停的回来。如果这是他们所渴望的挑战，那么部落也会相同的回应他们!$B$B我们兽人有许多消灭军团的理由。你呢，$N?我该不该告诉你有关我们敌人的事呢?',RequestItemsText_loc4='<碎颅中士没有注意到你。他看起来有点疲惫。>';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10122,'堡垒的外围','每天，地狱火堡垒都会打开它的大门，无数的邪兽人会在此时涌出那个巨大的堡垒，如洪流一般分布到沿着要塞的南侧城墙周围所设立的各个营地去。$B$B我已经派了一名最优秀的侦察人员列兵伊玛里恩去侦察这些邪兽人的活动状况、装备情况和数量分布等等情报。但是，他至今还没有向我发回任何报告或是其它什么信息。$B$B伊玛里恩应该主要是在南部城墙最北侧营地一带，也就是靠近地狱火堡垒的地方进行侦察。找到他，$N。若是没有他带回来的消息，我们就只能坐以待毙。','前往南部城墙外最北侧的营地寻找列兵伊玛里恩的下落。','在一堆的其它事物中，这些命令提及一个人类囚犯。如果士兵艾玛伦的确就是纪录中所提及的囚犯，那他可能还活着。','伏倒，你要在被抓到前快去检查这些计划。') ON DUPLICATE KEY UPDATE Title_loc4='堡垒的外围',Details_loc4='每天，地狱火堡垒都会打开它的大门，无数的邪兽人会在此时涌出那个巨大的堡垒，如洪流一般分布到沿着要塞的南侧城墙周围所设立的各个营地去。$B$B我已经派了一名最优秀的侦察人员列兵伊玛里恩去侦察这些邪兽人的活动状况、装备情况和数量分布等等情报。但是，他至今还没有向我发回任何报告或是其它什么信息。$B$B伊玛里恩应该主要是在南部城墙最北侧营地一带，也就是靠近地狱火堡垒的地方进行侦察。找到他，$N。若是没有他带回来的消息，我们就只能坐以待毙。',Objectives_loc4='前往南部城墙外最北侧的营地寻找列兵伊玛里恩的下落。',OfferRewardText_loc4='在一堆的其它事物中，这些命令提及一个人类囚犯。如果士兵艾玛伦的确就是纪录中所提及的囚犯，那他可能还活着。',RequestItemsText_loc4='伏倒，你要在被抓到前快去检查这些计划。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10123,'魔火峡谷','末日领主卡扎克是外域一带燃烧军团的最高指挥官。虽然我们现在还没有办法直接去挑战卡扎克，但我们可以先斩除他的左臂右膀——那些燃烧军团的高级军官。$B$B目前，有一队恐惧魔王驻扎在东边的魔火峡谷，他们负责指挥和制造那些在我们头顶上飞来飞去的地狱火。去干掉他们和他们的手下，燃烧军团会因此受到重创。','萨尔玛东侧补给车队的斯古尔·碎颅者中士要求你杀死4个唤火小鬼、6个地狱火战争使者和1个恐惧召唤者。','表现的太好了，士兵。攻击的频率一定会减低 - 至少在他们招来更多的惊惧领主前。$B$B现在有个坏消息:我收到了有关你的最新命令……','只要秘法师和他的血法师们持续在前线，萨尔玛就安全了。') ON DUPLICATE KEY UPDATE Title_loc4='魔火峡谷',Details_loc4='末日领主卡扎克是外域一带燃烧军团的最高指挥官。虽然我们现在还没有办法直接去挑战卡扎克，但我们可以先斩除他的左臂右膀——那些燃烧军团的高级军官。$B$B目前，有一队恐惧魔王驻扎在东边的魔火峡谷，他们负责指挥和制造那些在我们头顶上飞来飞去的地狱火。去干掉他们和他们的手下，燃烧军团会因此受到重创。',Objectives_loc4='萨尔玛东侧补给车队的斯古尔·碎颅者中士要求你杀死4个唤火小鬼、6个地狱火战争使者和1个恐惧召唤者。',OfferRewardText_loc4='表现的太好了，士兵。攻击的频率一定会减低 - 至少在他们招来更多的惊惧领主前。$B$B现在有个坏消息:我收到了有关你的最新命令……',RequestItemsText_loc4='只要秘法师和他的血法师们持续在前线，萨尔玛就安全了。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10124,'机甲残骸','最高统帅部已经注意到了你最近在战斗中的英勇表现，$c。他们想派你去前线与大督军霍恩·重拳阁下领导着的分队会合。那支分队作战非常积极，决心彻底消灭燃烧军团，所以你应该很容易就可以融入那里……$B$B往东边走前进两百步，然后在路的分叉口转向南边继续前进。不久之后，你就会在路边看到机甲残骸，那里曾经是一座老农场。到达那里之后，你要向前线指挥官托尔克报告。$B$B现在就出发吧！','前往机甲残骸，向前线指挥官托尔克报到。','所以你是那个负责把魔焰解决掉的人，是吗?真是个好消息 - 我们需要像你这种能够解决这些恶魔的士兵!$B') ON DUPLICATE KEY UPDATE Title_loc4='机甲残骸',Details_loc4='最高统帅部已经注意到了你最近在战斗中的英勇表现，$c。他们想派你去前线与大督军霍恩·重拳阁下领导着的分队会合。那支分队作战非常积极，决心彻底消灭燃烧军团，所以你应该很容易就可以融入那里……$B$B往东边走前进两百步，然后在路的分叉口转向南边继续前进。不久之后，你就会在路边看到机甲残骸，那里曾经是一座老农场。到达那里之后，你要向前线指挥官托尔克报告。$B$B现在就出发吧！',Objectives_loc4='前往机甲残骸，向前线指挥官托尔克报到。',OfferRewardText_loc4='所以你是那个负责把魔焰解决掉的人，是吗?真是个好消息 - 我们需要像你这种能够解决这些恶魔的士兵!$B';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4,ObjectiveText2_loc4,ObjectiveText3_loc4,ObjectiveText4_loc4) VALUES (10125,'任务:中断联系','这里东边不远的地方就是军团前线。军团前线可以说是燃烧军团在这里设立的一个移动司令中心。只要走近，你就能看见那里四处嶙立着的军团天线。燃烧军团的士兵就是使用这些东西与外域的其它营地联络的。它们同时也是屏蔽一切外来魔法干扰和监听的屏障，使军团的通信安全得到了保障。$B$B我要求你立刻带上这些爆炸物去摧毁那些天线。一定要全部清除，$N。军团前线南部和北部的边界上都安装了这种装置。','地狱火半岛上劫夺者荒野的前线指挥官吐阿奇要你使用吐阿奇的爆裂物摧毁军团天线:泄愤、军团天线:狂怒、军团天线:仇恨以及军团天线:恐惧。','你在前线时有看到军团传令者吗?$B$B<吐阿奇点头。>$B$B我们得赶走他们。','完成这两个任务后我会给你一项特别的任务。','摧毁军团感应器：敌意','摧毁军团感应器：狂乱','摧毁军团感应器：仇恨','摧毁军团感应器：畏惧') ON DUPLICATE KEY UPDATE Title_loc4='任务:中断联系',Details_loc4='这里东边不远的地方就是军团前线。军团前线可以说是燃烧军团在这里设立的一个移动司令中心。只要走近，你就能看见那里四处嶙立着的军团天线。燃烧军团的士兵就是使用这些东西与外域的其它营地联络的。它们同时也是屏蔽一切外来魔法干扰和监听的屏障，使军团的通信安全得到了保障。$B$B我要求你立刻带上这些爆炸物去摧毁那些天线。一定要全部清除，$N。军团前线南部和北部的边界上都安装了这种装置。',Objectives_loc4='地狱火半岛上劫夺者荒野的前线指挥官吐阿奇要你使用吐阿奇的爆裂物摧毁军团天线:泄愤、军团天线:狂怒、军团天线:仇恨以及军团天线:恐惧。',OfferRewardText_loc4='你在前线时有看到军团传令者吗?$B$B<吐阿奇点头。>$B$B我们得赶走他们。',RequestItemsText_loc4='完成这两个任务后我会给你一项特别的任务。',ObjectiveText1_loc4='摧毁军团感应器：敌意',ObjectiveText2_loc4='摧毁军团感应器：狂乱',ObjectiveText3_loc4='摧毁军团感应器：仇恨',ObjectiveText4_loc4='摧毁军团感应器：畏惧';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10126,'指挥官奈克罗格的命令','这些命令是由指挥官奈克罗格下达的，他命令营地中的邪兽人巡逻兵将这个人类囚犯带到南边去进行审讯。$B$B阿曼蒂中尉曾说过，南部城墙附近到处都有邪兽人的营地，因此他们将列兵伊玛里恩带到南部城墙附近的任何一个营地之中都是有可能的。$B$B此外，从信中提到的审讯来看，捕捉到他的邪兽人一定认为暂时留着他的性命会有什么好处。因此，你最好趁这他们还没有改变主意之前，赶紧找到列兵伊玛里恩的下落。','沿着南部城墙的西侧往南搜索，在下一个营地中寻找列兵伊玛里恩的下落。','艾玛利安的盾、剑和其它贵重物品似乎被随便扔到一旁。囚犯似乎在被解装之后没多久就被押解走了。','这个盾跟剑看起来好像是联盟斥候的旧版标准装备。') ON DUPLICATE KEY UPDATE Title_loc4='指挥官奈克罗格的命令',Details_loc4='这些命令是由指挥官奈克罗格下达的，他命令营地中的邪兽人巡逻兵将这个人类囚犯带到南边去进行审讯。$B$B阿曼蒂中尉曾说过，南部城墙附近到处都有邪兽人的营地，因此他们将列兵伊玛里恩带到南部城墙附近的任何一个营地之中都是有可能的。$B$B此外，从信中提到的审讯来看，捕捉到他的邪兽人一定认为暂时留着他的性命会有什么好处。因此，你最好趁这他们还没有改变主意之前，赶紧找到列兵伊玛里恩的下落。',Objectives_loc4='沿着南部城墙的西侧往南搜索，在下一个营地中寻找列兵伊玛里恩的下落。',OfferRewardText_loc4='艾玛利安的盾、剑和其它贵重物品似乎被随便扔到一旁。囚犯似乎在被解装之后没多久就被押解走了。',RequestItemsText_loc4='这个盾跟剑看起来好像是联盟斥候的旧版标准装备。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10127,'任务:切断联系','要是我没有让你去清除掉东边军团前线里的那些恶魔的话，那我可就真该被判成玩忽职守罪了。$B$B燃烧军团在两侧的前线都布置了同样的防御体系：恶魔劫夺者轮班守备各军团驻营地，而愤怒守卫则在各营地之间巡逻，而一名希樊征服者则负责监视整个防御体系。去把他们都杀光，让卡扎克好好头疼一番去吧。$B$B噢，对了，小心外围的恶魔劫夺者。我知道你很厉害，但碰上这些东西会耽误上你不少的时间。','地狱火半岛上劫夺者荒野的前线指挥官吐阿奇要你杀掉4个恶魔处理者，8个愤怒守卫，以及征服者薛艾希。','纳兹格雷尔将得知你在劫夺者荒野为部落所做的事情，$N。','他们不会知道是谁攻击他们的!') ON DUPLICATE KEY UPDATE Title_loc4='任务:切断联系',Details_loc4='要是我没有让你去清除掉东边军团前线里的那些恶魔的话，那我可就真该被判成玩忽职守罪了。$B$B燃烧军团在两侧的前线都布置了同样的防御体系：恶魔劫夺者轮班守备各军团驻营地，而愤怒守卫则在各营地之间巡逻，而一名希樊征服者则负责监视整个防御体系。去把他们都杀光，让卡扎克好好头疼一番去吧。$B$B噢，对了，小心外围的恶魔劫夺者。我知道你很厉害，但碰上这些东西会耽误上你不少的时间。',Objectives_loc4='地狱火半岛上劫夺者荒野的前线指挥官吐阿奇要你杀掉4个恶魔处理者，8个愤怒守卫，以及征服者薛艾希。',OfferRewardText_loc4='纳兹格雷尔将得知你在劫夺者荒野为部落所做的事情，$N。',RequestItemsText_loc4='他们不会知道是谁攻击他们的!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10128,'拯救大兵伊玛里恩','伊玛里恩散落着的装备和物品略略向南方扩展了几十码，这大致上显示出他似乎是被带去了南部城墙正南方的某处。而从地面上浅而凌乱的车轮印迹看得出，押解伊玛里恩的那些邪兽人都没来得及带走什么东西，走得十分匆忙。这是为什么呢？$B$B难道是有人在那边等着审讯他？难道就是指挥官奈克罗格，你在信中了解到的那个应该驻扎在最北边的邪兽人首领？$B$B总之，这面盾牌，以及这些车轮印迹给你带来了更多的疑问，但无论如何，你已经大致知道列兵伊玛里恩在什么地方了，说不定你还可以在那里找到指挥官奈克罗格。','沿着南部城墙继续往南前进，找到指挥官奈克罗格囚禁列兵伊玛里恩的地方。','你必须让我离开这里，但并不容易。战王奈克罗格的手下个个凶猛且训练有素。','感谢圣光你找到我了!') ON DUPLICATE KEY UPDATE Title_loc4='拯救大兵伊玛里恩',Details_loc4='伊玛里恩散落着的装备和物品略略向南方扩展了几十码，这大致上显示出他似乎是被带去了南部城墙正南方的某处。而从地面上浅而凌乱的车轮印迹看得出，押解伊玛里恩的那些邪兽人都没来得及带走什么东西，走得十分匆忙。这是为什么呢？$B$B难道是有人在那边等着审讯他？难道就是指挥官奈克罗格，你在信中了解到的那个应该驻扎在最北边的邪兽人首领？$B$B总之，这面盾牌，以及这些车轮印迹给你带来了更多的疑问，但无论如何，你已经大致知道列兵伊玛里恩在什么地方了，说不定你还可以在那里找到指挥官奈克罗格。',Objectives_loc4='沿着南部城墙继续往南前进，找到指挥官奈克罗格囚禁列兵伊玛里恩的地方。',OfferRewardText_loc4='你必须让我离开这里，但并不容易。战王奈克罗格的手下个个凶猛且训练有素。',RequestItemsText_loc4='感谢圣光你找到我了!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4,ObjectiveText2_loc4) VALUES (10129,'任务：穆尔凯斯和沙德拉兹之门','我们已经找到了燃烧军团目前所使用的两条运输增援军的主要线路：穆尔凯斯和沙德拉兹之门。$B$B如果你沿着荣耀之路一直向西走，就可以在路边看见它们了。而我要你做的，就是把它们都给我炸上天！$B$B这是你要用的炸弹，是我请52区的一个地精技师特别设计的。现在，去和空军指挥官布拉克谈一谈，他会给你配置一只双足飞龙的。','与空军指挥官布拉克谈谈，轰炸穆尔凯斯之门和沙德拉兹之门，然后向机甲残骸处的前线指挥官托尔克复命。','他们需要数周的时间才能恢复!了不起的工作，$N。燃烧军团从未预期过如此严重的反击。','假如你在第一次操作的时候失败了，这里是第二个炸弹……','摧毁穆尔凯斯之门','摧毁沙德拉兹之门') ON DUPLICATE KEY UPDATE Title_loc4='任务：穆尔凯斯和沙德拉兹之门',Details_loc4='我们已经找到了燃烧军团目前所使用的两条运输增援军的主要线路：穆尔凯斯和沙德拉兹之门。$B$B如果你沿着荣耀之路一直向西走，就可以在路边看见它们了。而我要你做的，就是把它们都给我炸上天！$B$B这是你要用的炸弹，是我请52区的一个地精技师特别设计的。现在，去和空军指挥官布拉克谈一谈，他会给你配置一只双足飞龙的。',Objectives_loc4='与空军指挥官布拉克谈谈，轰炸穆尔凯斯之门和沙德拉兹之门，然后向机甲残骸处的前线指挥官托尔克复命。',OfferRewardText_loc4='他们需要数周的时间才能恢复!了不起的工作，$N。燃烧军团从未预期过如此严重的反击。',RequestItemsText_loc4='假如你在第一次操作的时候失败了，这里是第二个炸弹……',ObjectiveText1_loc4='摧毁穆尔凯斯之门',ObjectiveText2_loc4='摧毁沙德拉兹之门';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10130,'西侧的威胁','除了其它指示之外，命令书中还提到要让邪兽人们准备好武器和装备，随时准备发动下一次进攻。$B$B依照这份计划，指挥官奈克罗格的军队将从西边进攻荣耀堡，与东边的军队形成一个钳形攻击战略。$B$B而当荣耀堡的主要军力都集中在东部城墙的时候，来自西边的袭击将是极具杀伤力的。只有让西边的军队无法发起袭击，荣耀堡才有希望逃脱危险。','杀死10名碎手卫兵、10名碎手狂战士和5名碎手侍僧，然后向荣耀堡西部哨塔的阿曼蒂中尉报到。','你是对的，$N。如果他们成功与萨斯葛尔的部队协力进行他们的攻击，荣耀堡就会被占领。$B$B幸好你有先见之明，在一切太迟之前阻止了战王奈克罗格的部队。','你看起来很不安。有什么发现吗?') ON DUPLICATE KEY UPDATE Title_loc4='西侧的威胁',Details_loc4='除了其它指示之外，命令书中还提到要让邪兽人们准备好武器和装备，随时准备发动下一次进攻。$B$B依照这份计划，指挥官奈克罗格的军队将从西边进攻荣耀堡，与东边的军队形成一个钳形攻击战略。$B$B而当荣耀堡的主要军力都集中在东部城墙的时候，来自西边的袭击将是极具杀伤力的。只有让西边的军队无法发起袭击，荣耀堡才有希望逃脱危险。',Objectives_loc4='杀死10名碎手卫兵、10名碎手狂战士和5名碎手侍僧，然后向荣耀堡西部哨塔的阿曼蒂中尉报到。',OfferRewardText_loc4='你是对的，$N。如果他们成功与萨斯葛尔的部队协力进行他们的攻击，荣耀堡就会被占领。$B$B幸好你有先见之明，在一切太迟之前阻止了战王奈克罗格的部队。',RequestItemsText_loc4='你看起来很不安。有什么发现吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10131,'逃脱计划','就像我说的那样，要想从这里逃出去不是件容易的事情。指挥官奈克罗格虽然看上去像是个只有一身蛮力的家伙，但实际上他一点也不笨。$B$B事实上，牢房的钥匙一直都在他身上，从没有离开过他的视线之外。而且，他根本不会轻易从塔顶上下来，除非准备审讯我或者另外一个兽人俘虏。$B$B总之，想让他从塔顶上下来得花费点工夫，不过，我已经有个办法了。找个在南部城墙边巡逻的士兵，把他身上的炸药给我带回来。','杀死一名碎手掷弹兵，将他携带的劣质炸弹交给高加兹前哨的列兵伊玛里恩。','我看见过那些掷弹兵在战斗中使用这些东西。这种炸药好像大多数时候都可以确实引爆，并且造成相当的爆炸力!让我们测试它们。','你拿到爆裂物了吗?') ON DUPLICATE KEY UPDATE Title_loc4='逃脱计划',Details_loc4='就像我说的那样，要想从这里逃出去不是件容易的事情。指挥官奈克罗格虽然看上去像是个只有一身蛮力的家伙，但实际上他一点也不笨。$B$B事实上，牢房的钥匙一直都在他身上，从没有离开过他的视线之外。而且，他根本不会轻易从塔顶上下来，除非准备审讯我或者另外一个兽人俘虏。$B$B总之，想让他从塔顶上下来得花费点工夫，不过，我已经有个办法了。找个在南部城墙边巡逻的士兵，把他身上的炸药给我带回来。',Objectives_loc4='杀死一名碎手掷弹兵，将他携带的劣质炸弹交给高加兹前哨的列兵伊玛里恩。',OfferRewardText_loc4='我看见过那些掷弹兵在战斗中使用这些东西。这种炸药好像大多数时候都可以确实引爆，并且造成相当的爆炸力!让我们测试它们。',RequestItemsText_loc4='你拿到爆裂物了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10132,'巨人的威胁','你看见北边那块巨大的红色水晶了吗？那是不久前从空中掉下来的，还引起了这周围的大规模地震。$B$B后来，我们过去调查它的时候，发现有许多以前从未见过的巨人徘徊在四周。$B$B这块水晶一定有古怪，它散发出的能量也非常奇异。但是，我没有时间去处理这件事情，我必须时刻提防着那些山丘巨人。$B$B如果可能的话，我希望你能带上你的朋友们，一起去坠星山帮我解决掉那些山丘巨人。','杀死5个暴怒的巨人，然后返回地狱火半岛的塞纳里奥哨站，向图拉希恩复命。','做的好。$B$B假如你问我，所有我们必须做的是杀死足够的那些戈罗西，然后我们就不必再担心那片山脊或位在山脊中间的那颗奇怪水晶。$B$B来，从这些物品之中选取一个作为塞纳里奥远征队送给你的礼物。','你已经消灭了这个巨大的威胁了吗?') ON DUPLICATE KEY UPDATE Title_loc4='巨人的威胁',Details_loc4='你看见北边那块巨大的红色水晶了吗？那是不久前从空中掉下来的，还引起了这周围的大规模地震。$B$B后来，我们过去调查它的时候，发现有许多以前从未见过的巨人徘徊在四周。$B$B这块水晶一定有古怪，它散发出的能量也非常奇异。但是，我没有时间去处理这件事情，我必须时刻提防着那些山丘巨人。$B$B如果可能的话，我希望你能带上你的朋友们，一起去坠星山帮我解决掉那些山丘巨人。',Objectives_loc4='杀死5个暴怒的巨人，然后返回地狱火半岛的塞纳里奥哨站，向图拉希恩复命。',OfferRewardText_loc4='做的好。$B$B假如你问我，所有我们必须做的是杀死足够的那些戈罗西，然后我们就不必再担心那片山脊或位在山脊中间的那颗奇怪水晶。$B$B来，从这些物品之中选取一个作为塞纳里奥远征队送给你的礼物。',RequestItemsText_loc4='你已经消灭了这个巨大的威胁了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10133,'任务:杀死信差','你的行动已经开始令军团感到不安了，$N。我的斥候刚刚通知我说，军团被迫重新开始利用信使来传递信件，完成通讯。这下我们就有了将他们彻底铲除出这片大陆的机会！$B$B接下来我要你做的事，要求你拥有远远超出一般的士兵的机敏和战力。$B$B军团的信使目前往返于北方的阿苟纳之池与铸魔营地：暴虐之间。你必须在铸魔营地：暴虐外截住并干掉他，并带着他身上的Legion missive回来见我。','地狱火半岛劫夺者荒野的前线指挥官吐阿奇要你杀死阿瑞克斯玛里达许并且取回军团公文。','<吐阿奇读着公文。>$B$B我被赋予的权力并不足以应付这么重大的军情。你必须立刻带着这份公文到纳兹格雷尔那里!','我对你的能力有信心，$N。') ON DUPLICATE KEY UPDATE Title_loc4='任务:杀死信差',Details_loc4='你的行动已经开始令军团感到不安了，$N。我的斥候刚刚通知我说，军团被迫重新开始利用信使来传递信件，完成通讯。这下我们就有了将他们彻底铲除出这片大陆的机会！$B$B接下来我要你做的事，要求你拥有远远超出一般的士兵的机敏和战力。$B$B军团的信使目前往返于北方的阿苟纳之池与铸魔营地：暴虐之间。你必须在铸魔营地：暴虐外截住并干掉他，并带着他身上的Legion missive回来见我。',Objectives_loc4='地狱火半岛劫夺者荒野的前线指挥官吐阿奇要你杀死阿瑞克斯玛里达许并且取回军团公文。',OfferRewardText_loc4='<吐阿奇读着公文。>$B$B我被赋予的权力并不足以应付这么重大的军情。你必须立刻带着这份公文到纳兹格雷尔那里!',RequestItemsText_loc4='我对你的能力有信心，$N。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10134,'火红水晶中的线索','当这个巨人在你面前缓缓倒下时，突然一小块水晶碎片从它身上掉了下来。$B$B尽管这块碎片映衬在山丘巨人那庞大身躯旁是那么的渺小，但你还注意到了它。拾起它之后，你感到它非常的沉重。似乎它是从坠星山那块巨大的水晶上的散落下来的碎片。$B$B这显然是一个线索，能使大家了解清楚这里为什么会发生那么多奇怪的事。你认为南边塞纳里奥哨站的德鲁伊一定会想研究研究这块碎片。','将火红水晶碎片交给地狱火半岛塞纳里奥哨站的图拉希恩。','嗯。对我来说，看起来就像是一大块尚未提炼的水晶。$B$B我能清楚的感觉到它散发出一股令人厌恶、邪恶的气息，但那究竟不在我职责的范围内。我到这里是来结束山岳巨人的威胁的。','你手中的水晶还真大。那是你到山脊杀死戈罗西时得到的吗?$B$B让我看看。') ON DUPLICATE KEY UPDATE Title_loc4='火红水晶中的线索',Details_loc4='当这个巨人在你面前缓缓倒下时，突然一小块水晶碎片从它身上掉了下来。$B$B尽管这块碎片映衬在山丘巨人那庞大身躯旁是那么的渺小，但你还注意到了它。拾起它之后，你感到它非常的沉重。似乎它是从坠星山那块巨大的水晶上的散落下来的碎片。$B$B这显然是一个线索，能使大家了解清楚这里为什么会发生那么多奇怪的事。你认为南边塞纳里奥哨站的德鲁伊一定会想研究研究这块碎片。',Objectives_loc4='将火红水晶碎片交给地狱火半岛塞纳里奥哨站的图拉希恩。',OfferRewardText_loc4='嗯。对我来说，看起来就像是一大块尚未提炼的水晶。$B$B我能清楚的感觉到它散发出一股令人厌恶、邪恶的气息，但那究竟不在我职责的范围内。我到这里是来结束山岳巨人的威胁的。',RequestItemsText_loc4='你手中的水晶还真大。那是你到山脊杀死戈罗西时得到的吗?$B$B让我看看。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10135,'任务:充当信差','我仅仅是一名前线的战地指挥官，$c。对于这样重要的情报，我们该采取什么样的行动……，决定权限只能属于我们的领袖纳兹格雷尔大人。你必须马上把这些信件带到萨尔玛呈现给他。士兵，搭乘双足飞龙吧，愿你一路上不会受到任何阻碍！','将军团公文带给地狱火半岛上萨尔玛的纳兹格雷尔。','<当纳兹格雷尔读公文时，他仔细咀嚼着烟斗的末端。>$B$B没错……没错!这将是阿拉萨尔斯亲手写的最后一封公文。','你有军团动静的消息吗?') ON DUPLICATE KEY UPDATE Title_loc4='任务:充当信差',Details_loc4='我仅仅是一名前线的战地指挥官，$c。对于这样重要的情报，我们该采取什么样的行动……，决定权限只能属于我们的领袖纳兹格雷尔大人。你必须马上把这些信件带到萨尔玛呈现给他。士兵，搭乘双足飞龙吧，愿你一路上不会受到任何阻碍！',Objectives_loc4='将军团公文带给地狱火半岛上萨尔玛的纳兹格雷尔。',OfferRewardText_loc4='<当纳兹格雷尔读公文时，他仔细咀嚼着烟斗的末端。>$B$B没错……没错!这将是阿拉萨尔斯亲手写的最后一封公文。',RequestItemsText_loc4='你有军团动静的消息吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10136,'阿拉修斯的意图','魔导师文森特·血鹰破译了你之前找到的燃烧军团信件。看来这份计划书是卡扎克麾下的军官阿拉修斯所拟。很明显阿拉修斯统领着燃烧军团部署在地狱火半岛的陆军。是时候解决这个麻烦了，$N。用武力去结束这一切。$B$B到西边的阿苟纳之池去，干掉这个所谓的“燃烧军团领主”。今天，部落将要夺回地狱火半岛，让燃烧军团见鬼去吧！','除掉残酷的阿拉修斯，然后返回萨尔玛向纳兹格雷尔复命。','将来部落的后代们，会流传歌颂今日发生的壮举，$N-关于你英勇事迹的歌曲。我希望萨尔可以在这边跟我们一起庆祝。燃烧军团已经玩完了-而地狱火半岛如今再次回到我们部落的手中啦!这个充满破坏与蹂躏的世界看起来还是存有希望-而我们部落在其中还可以拥有一席之地。$B$B为了部落!','命运来的时候谁都挡不住，$N。残忍的阿拉萨尔斯已经逃避他的命运够久了。把他的死讯告诉那些胆敢反抗部落之人。而你就是下一个。') ON DUPLICATE KEY UPDATE Title_loc4='阿拉修斯的意图',Details_loc4='魔导师文森特·血鹰破译了你之前找到的燃烧军团信件。看来这份计划书是卡扎克麾下的军官阿拉修斯所拟。很明显阿拉修斯统领着燃烧军团部署在地狱火半岛的陆军。是时候解决这个麻烦了，$N。用武力去结束这一切。$B$B到西边的阿苟纳之池去，干掉这个所谓的“燃烧军团领主”。今天，部落将要夺回地狱火半岛，让燃烧军团见鬼去吧！',Objectives_loc4='除掉残酷的阿拉修斯，然后返回萨尔玛向纳兹格雷尔复命。',OfferRewardText_loc4='将来部落的后代们，会流传歌颂今日发生的壮举，$N-关于你英勇事迹的歌曲。我希望萨尔可以在这边跟我们一起庆祝。燃烧军团已经玩完了-而地狱火半岛如今再次回到我们部落的手中啦!这个充满破坏与蹂躏的世界看起来还是存有希望-而我们部落在其中还可以拥有一席之地。$B$B为了部落!',RequestItemsText_loc4='命运来的时候谁都挡不住，$N。残忍的阿拉萨尔斯已经逃避他的命运够久了。把他的死讯告诉那些胆敢反抗部落之人。而你就是下一个。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText3_loc4) VALUES (10137,'挑衅指挥官','计划是成功还是失败，就全靠这些炸弹了……$B$B尽管我非常讨厌使用兽人制造的东西，但现在这可能是我活着逃出去的唯一机会。带上这个，将它扔向塔上悬挂着的旗帜。$B$B听到爆炸的声音之后，指挥官奈克罗格一定会从塔顶上走下来调查原因，寻找是谁在捣乱。你就要趁这个机会杀掉他，并且拿到钥匙，然后回来帮我把牢房的门打开。祝你好运，$N。','引爆劣质炸弹制造混乱，诱使指挥官奈克罗格离开哨塔。从他手中夺得奈克罗格的钥匙，打开囚禁列兵伊玛里恩的牢笼。救出列兵伊玛里恩之后向阿曼蒂中尉复命。','真是令人高兴的好消息。我本来开始怀疑我们再也看不到士兵艾玛伦，但是你已经证明我错了。$B$B在你告诉我燃烧军团的计划后，恐怕我们没有太多时间可以庆祝了。你已经在截断他们西边部队上做的很好，但是燃烧军团仍然有相当大的主力部队集结在萨斯葛尔。','<阿玛迪中尉看起来很紧张。>$B$B那么，你找到他了吗?','营救大兵伊玛里恩') ON DUPLICATE KEY UPDATE Title_loc4='挑衅指挥官',Details_loc4='计划是成功还是失败，就全靠这些炸弹了……$B$B尽管我非常讨厌使用兽人制造的东西，但现在这可能是我活着逃出去的唯一机会。带上这个，将它扔向塔上悬挂着的旗帜。$B$B听到爆炸的声音之后，指挥官奈克罗格一定会从塔顶上走下来调查原因，寻找是谁在捣乱。你就要趁这个机会杀掉他，并且拿到钥匙，然后回来帮我把牢房的门打开。祝你好运，$N。',Objectives_loc4='引爆劣质炸弹制造混乱，诱使指挥官奈克罗格离开哨塔。从他手中夺得奈克罗格的钥匙，打开囚禁列兵伊玛里恩的牢笼。救出列兵伊玛里恩之后向阿曼蒂中尉复命。',OfferRewardText_loc4='真是令人高兴的好消息。我本来开始怀疑我们再也看不到士兵艾玛伦，但是你已经证明我错了。$B$B在你告诉我燃烧军团的计划后，恐怕我们没有太多时间可以庆祝了。你已经在截断他们西边部队上做的很好，但是燃烧军团仍然有相当大的主力部队集结在萨斯葛尔。',RequestItemsText_loc4='<阿玛迪中尉看起来很紧张。>$B$B那么，你找到他了吗?',ObjectiveText3_loc4='营救大兵伊玛里恩';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10138,'谁的命令？','现在，$N，至少有一件事已经明确了，那就是：我们不能让状况继续恶化下去。邪兽人数量增长的速度与我们消灭他们的速度几乎一样快，现在几乎已经将我们包围了。如果只是这样躲在荣耀堡的城墙之后，整天算着日子，等待邪兽人或是燃烧军团过来把我们完全杀光的话，我们是无法赢得这场战争的。$B$B你最近表现得非常出色，已经使我们避免了多次邪兽人凶残的进犯，但是，这还不够，你现在必须想办法攻进荣耀之路，并找出在幕后策划了这几次袭击的那个幕后黑手。','杀死20名碎手步兵和10名碎手术士，并夺得教官祖罗克的命令，然后向荣耀堡西部哨塔的阿曼蒂中尉复命。','做得好，$N。这些公文终于可揭露出这些攻击之后的策划者身分。','我们离目标愈来愈近了，$N。你发现了什么吗?') ON DUPLICATE KEY UPDATE Title_loc4='谁的命令？',Details_loc4='现在，$N，至少有一件事已经明确了，那就是：我们不能让状况继续恶化下去。邪兽人数量增长的速度与我们消灭他们的速度几乎一样快，现在几乎已经将我们包围了。如果只是这样躲在荣耀堡的城墙之后，整天算着日子，等待邪兽人或是燃烧军团过来把我们完全杀光的话，我们是无法赢得这场战争的。$B$B你最近表现得非常出色，已经使我们避免了多次邪兽人凶残的进犯，但是，这还不够，你现在必须想办法攻进荣耀之路，并找出在幕后策划了这几次袭击的那个幕后黑手。',Objectives_loc4='杀死20名碎手步兵和10名碎手术士，并夺得教官祖罗克的命令，然后向荣耀堡西部哨塔的阿曼蒂中尉复命。',OfferRewardText_loc4='做得好，$N。这些公文终于可揭露出这些攻击之后的策划者身分。',RequestItemsText_loc4='我们离目标愈来愈近了，$N。你发现了什么吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10139,'刺杀指挥官','根据我目前所掌握的情报，教官祖罗克应该是为地狱火半岛上所有邪兽人首领指挥官戈拉克斯效力的，是他的心腹，他的左右臂膀。$B$B这个戈拉克斯明显不是个典型的邪兽人蛮夷，尽管他是我们的敌人，我仍不得不佩服他，是他让我们在如此长的时间内都被迫陷入被动的境地。$B$B祖罗克的命令书中显示出戈拉克斯的指挥部位于荣耀之路末端，靠近要塞城墙与北部城墙相接的地方，你要立刻去刺杀他。不过，面对这样一个强大的邪兽人，说不准会发生什么事情，$N，你最好能带些同伴一起去。','杀死指挥官戈拉克斯，然后向荣耀堡西部哨塔的阿曼蒂中尉复命。','杰出的表现，$N!就在不久前，洛萨之子只能从荣耀堡的城墙内担心的挑望那些集结中的邪兽人部队。$B$B葛洛克斯的死亡是一次伟大的胜利，而你已经真正的在洛萨之子中赢得一席荣誉之地。','自从你离开后变得安静多了，$N。你有什么事要报告的吗?') ON DUPLICATE KEY UPDATE Title_loc4='刺杀指挥官',Details_loc4='根据我目前所掌握的情报，教官祖罗克应该是为地狱火半岛上所有邪兽人首领指挥官戈拉克斯效力的，是他的心腹，他的左右臂膀。$B$B这个戈拉克斯明显不是个典型的邪兽人蛮夷，尽管他是我们的敌人，我仍不得不佩服他，是他让我们在如此长的时间内都被迫陷入被动的境地。$B$B祖罗克的命令书中显示出戈拉克斯的指挥部位于荣耀之路末端，靠近要塞城墙与北部城墙相接的地方，你要立刻去刺杀他。不过，面对这样一个强大的邪兽人，说不准会发生什么事情，$N，你最好能带些同伴一起去。',Objectives_loc4='杀死指挥官戈拉克斯，然后向荣耀堡西部哨塔的阿曼蒂中尉复命。',OfferRewardText_loc4='杰出的表现，$N!就在不久前，洛萨之子只能从荣耀堡的城墙内担心的挑望那些集结中的邪兽人部队。$B$B葛洛克斯的死亡是一次伟大的胜利，而你已经真正的在洛萨之子中赢得一席荣誉之地。',RequestItemsText_loc4='自从你离开后变得安静多了，$N。你有什么事要报告的吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10140,'荣耀堡之旅','如果你准备好了的话，我就要为你安排一次直接到荣耀堡的飞行了。$B$B到了那边以后，和伊斯多尔元帅谈谈，然后把杜隆的报告交给他。看到又一位来自故乡的新兵，他一定会很高兴的。而且，我得说，这份报告也非常重要！','乘座狮鹫前往荣耀堡，将杜隆的报告交给伊斯多尔元帅。','我们对这个被遗弃，残破的世界的远征已经几乎裹足不前了。$N。我们遇到了超乎我们估计的阻碍。$B$B好像我们单单对抗燃烧军团的处境还不够恶劣一样-这片土地上还存在着我们以前从未遇过的邪恶事物。','感谢圣光你安全的将它送达这里。荣耀堡需要集合所有经验丰富的战士。') ON DUPLICATE KEY UPDATE Title_loc4='荣耀堡之旅',Details_loc4='如果你准备好了的话，我就要为你安排一次直接到荣耀堡的飞行了。$B$B到了那边以后，和伊斯多尔元帅谈谈，然后把杜隆的报告交给他。看到又一位来自故乡的新兵，他一定会很高兴的。而且，我得说，这份报告也非常重要！',Objectives_loc4='乘座狮鹫前往荣耀堡，将杜隆的报告交给伊斯多尔元帅。',OfferRewardText_loc4='我们对这个被遗弃，残破的世界的远征已经几乎裹足不前了。$N。我们遇到了超乎我们估计的阻碍。$B$B好像我们单单对抗燃烧军团的处境还不够恶劣一样-这片土地上还存在着我们以前从未遇过的邪恶事物。',RequestItemsText_loc4='感谢圣光你安全的将它送达这里。荣耀堡需要集合所有经验丰富的战士。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10141,'重生的军团','当燃烧军团入侵艾泽拉斯世界时，他们在外域这里也没闲着。多年来，我们都在追踪着他们的活动。但是，$c，这次他们最新的行动却是我们以前完全没有见过的。$B$B立刻到东补给车队去，找沃图姆斯中士报到。她负责对那些入侵者执行具体的监视行动，并分析他们的行动目的。$B$B你要快一点行动，同时也要注意安全，$n，绝对不要低估燃烧军团。','与荣耀堡外面的东补给车队的沃图姆斯中士谈一谈。','军队指挥官达纳斯可能误会了我对增援部队的要求。你看起来很有能力，但是……我要求的是一整营的部队!$B$B你看，我们有一些恶魔泛滥的问题……','<阿图玛斯中士没有注意到你。她看起来有点疲惫。>') ON DUPLICATE KEY UPDATE Title_loc4='重生的军团',Details_loc4='当燃烧军团入侵艾泽拉斯世界时，他们在外域这里也没闲着。多年来，我们都在追踪着他们的活动。但是，$c，这次他们最新的行动却是我们以前完全没有见过的。$B$B立刻到东补给车队去，找沃图姆斯中士报到。她负责对那些入侵者执行具体的监视行动，并分析他们的行动目的。$B$B你要快一点行动，同时也要注意安全，$n，绝对不要低估燃烧军团。',Objectives_loc4='与荣耀堡外面的东补给车队的沃图姆斯中士谈一谈。',OfferRewardText_loc4='军队指挥官达纳斯可能误会了我对增援部队的要求。你看起来很有能力，但是……我要求的是一整营的部队!$B$B你看，我们有一些恶魔泛滥的问题……',RequestItemsText_loc4='<阿图玛斯中士没有注意到你。她看起来有点疲惫。>';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10142,'苦痛之路','末日领主卡扎克指挥着外域所有的燃烧军团部队。当然，我们目前还不能直接和卡扎克对抗，但我们可以——而且必须——开始铲除他军团中的军官，彻底扰乱他们的指挥体系。$B$B他们在东边的苦痛之路派驻了一批恐惧魔王。正是这些恐惧魔王负责着在我们头顶上不停地降下地狱火之雨。立刻清除他们，还有他们的手下，这样燃烧军团就将遭受重大的损失。','荣耀堡外面的东补给车队的沃图姆斯中士要求你杀死4只唤火小鬼、6只地狱火战争使者和1只恐惧召唤者。','杰出的表现，士兵。他们攻击的频率必定会降低 - 至少直到他们运送新的惊惧领主前来战线。$B$B现在宣布坏消息:我要下新的命令给你……','只要弓箭手看守着我们的领空，荣耀堡就会很安全。') ON DUPLICATE KEY UPDATE Title_loc4='苦痛之路',Details_loc4='末日领主卡扎克指挥着外域所有的燃烧军团部队。当然，我们目前还不能直接和卡扎克对抗，但我们可以——而且必须——开始铲除他军团中的军官，彻底扰乱他们的指挥体系。$B$B他们在东边的苦痛之路派驻了一批恐惧魔王。正是这些恐惧魔王负责着在我们头顶上不停地降下地狱火之雨。立刻清除他们，还有他们的手下，这样燃烧军团就将遭受重大的损失。',Objectives_loc4='荣耀堡外面的东补给车队的沃图姆斯中士要求你杀死4只唤火小鬼、6只地狱火战争使者和1只恐惧召唤者。',OfferRewardText_loc4='杰出的表现，士兵。他们攻击的频率必定会降低 - 至少直到他们运送新的惊惧领主前来战线。$B$B现在宣布坏消息:我要下新的命令给你……',RequestItemsText_loc4='只要弓箭手看守着我们的领空，荣耀堡就会很安全。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10143,'远征军岗哨','你在之前数次作战之中所体现出的战斗力，已经被所有的高级指挥官注意到了，$c。他们希望能派你去前线与罗哈姆斯的小分队会合。那是一群激进分子，对毁灭燃烧军团的事业非常狂热。或许……你在他们那里会感觉比较自在一点……$B$B向东前进大约400步的距离，穿越白骨之谷，走到一处被毁坏的魔能机甲旁，远征军岗哨就矗立在那边的一处燃烧军团基地旧址上。到达那里之后，立刻向前线指挥官金斯顿报到。$B$B去吧！','向远征军岗哨的前线指挥官金斯顿报到。','很高兴见到你，士兵。$B$B聊够了……现在听着 - 我要给你一项非常重要的任务，而且只许成功……并且存活下来!','所以你就是清除苦痛之路的那个人，是吗?') ON DUPLICATE KEY UPDATE Title_loc4='远征军岗哨',Details_loc4='你在之前数次作战之中所体现出的战斗力，已经被所有的高级指挥官注意到了，$c。他们希望能派你去前线与罗哈姆斯的小分队会合。那是一群激进分子，对毁灭燃烧军团的事业非常狂热。或许……你在他们那里会感觉比较自在一点……$B$B向东前进大约400步的距离，穿越白骨之谷，走到一处被毁坏的魔能机甲旁，远征军岗哨就矗立在那边的一处燃烧军团基地旧址上。到达那里之后，立刻向前线指挥官金斯顿报到。$B$B去吧！',Objectives_loc4='向远征军岗哨的前线指挥官金斯顿报到。',OfferRewardText_loc4='很高兴见到你，士兵。$B$B聊够了……现在听着 - 我要给你一项非常重要的任务，而且只许成功……并且存活下来!',RequestItemsText_loc4='所以你就是清除苦痛之路的那个人，是吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4,ObjectiveText2_loc4) VALUES (10144,'阻断援军','你从这里一直向西北方走，就可以到达军团前线。那里部署着许多通向外域各地的传送门，使这里的燃烧军团能够随时得到增援。$n，我们决定摧毁所有的传送门！$B$B带上这捆雷管，它是由52区的技师设计的，可以利用恶魔自身的力量产生强大的爆炸！首先你要杀死格雷姆传送门和凯勒兹传送门旁边的那些军团士兵，收集他们身上的恶魔符文石，然后在传送门内使用雷管去引爆这些符文石……接下来，我们就可以看烟火表演了！！$B$B快去吧，$n，完成任务之后向我复命。','消灭格雷姆传送门和凯勒兹传送门附近的敌人，收集它们身上的恶魔符文石。$B$B然后在格雷姆传送门和凯勒兹传送门内使用金斯顿的雷管。$B$B完成任务后，将剩馀的炸药还给前线指挥官金斯顿。','做的好，$N。瘫痪那些传送门将会好一段时间的切断燃烧军团源源不绝的援军!$B$B但是我们还不能休息……','真希望我能到那里观赏烟火展示。那些爆裂物的威力强大!','破坏格雷姆传送门','破坏凯勒兹传送门') ON DUPLICATE KEY UPDATE Title_loc4='阻断援军',Details_loc4='你从这里一直向西北方走，就可以到达军团前线。那里部署着许多通向外域各地的传送门，使这里的燃烧军团能够随时得到增援。$n，我们决定摧毁所有的传送门！$B$B带上这捆雷管，它是由52区的技师设计的，可以利用恶魔自身的力量产生强大的爆炸！首先你要杀死格雷姆传送门和凯勒兹传送门旁边的那些军团士兵，收集他们身上的恶魔符文石，然后在传送门内使用雷管去引爆这些符文石……接下来，我们就可以看烟火表演了！！$B$B快去吧，$n，完成任务之后向我复命。',Objectives_loc4='消灭格雷姆传送门和凯勒兹传送门附近的敌人，收集它们身上的恶魔符文石。$B$B然后在格雷姆传送门和凯勒兹传送门内使用金斯顿的雷管。$B$B完成任务后，将剩馀的炸药还给前线指挥官金斯顿。',OfferRewardText_loc4='做的好，$N。瘫痪那些传送门将会好一段时间的切断燃烧军团源源不绝的援军!$B$B但是我们还不能休息……',RequestItemsText_loc4='真希望我能到那里观赏烟火展示。那些爆裂物的威力强大!',ObjectiveText1_loc4='破坏格雷姆传送门',ObjectiveText2_loc4='破坏凯勒兹传送门';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10145,'任务:切断联系','假如我没命令你杀死驻扎于基地东方军团前线的恶魔们，这将是疏忽职守。
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4,ObjectiveText2_loc4) VALUES (10146,'任务：穆尔凯斯和沙德拉兹之门','就在黑暗之门的西边，有两处巨大的传送装置，它们分别被称作穆尔凯斯之门和沙德拉兹之门。$B$B如果你沿着荣耀之路一直向西走，就可以在路边看见它们了。而我要你做的，就是把它们都给我炸上天！$B$B这是你要用的炸弹，是我请52区的一个地精技师特别设计的。现在，去和空军指挥官达比利谈谈吧，他会用狮鹫把你一路送过去的。','与空军指挥官达比利谈谈，轰炸穆尔凯斯之门和沙德拉兹之门，然后向远征军岗哨的前线指挥官金斯顿复命。','毫无疑问的，那将减缓他们的行动!我想你让我的心情变得异常的好，$N!','这是个非常重要的任务，$N。是个我不会轻易相信随便任何人的任务。','摧毁穆尔凯斯之门','摧毁沙德拉兹之门') ON DUPLICATE KEY UPDATE Title_loc4='任务：穆尔凯斯和沙德拉兹之门',Details_loc4='就在黑暗之门的西边，有两处巨大的传送装置，它们分别被称作穆尔凯斯之门和沙德拉兹之门。$B$B如果你沿着荣耀之路一直向西走，就可以在路边看见它们了。而我要你做的，就是把它们都给我炸上天！$B$B这是你要用的炸弹，是我请52区的一个地精技师特别设计的。现在，去和空军指挥官达比利谈谈吧，他会用狮鹫把你一路送过去的。',Objectives_loc4='与空军指挥官达比利谈谈，轰炸穆尔凯斯之门和沙德拉兹之门，然后向远征军岗哨的前线指挥官金斯顿复命。',OfferRewardText_loc4='毫无疑问的，那将减缓他们的行动!我想你让我的心情变得异常的好，$N!',RequestItemsText_loc4='这是个非常重要的任务，$N。是个我不会轻易相信随便任何人的任务。',ObjectiveText1_loc4='摧毁穆尔凯斯之门',ObjectiveText2_loc4='摧毁沙德拉兹之门';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10147,'任务:杀死信差','你的行动已经开始令军团感到不安了，$N。我的斥候刚刚通知我说，军团被迫重新开始利用信使来传递信件，完成通讯。这下我们就有了将他们彻底铲除出这片大陆的机会！$B$B接下来我要你做的事，要求你拥有远远超出一般的士兵的机敏和战力。$B$B军团的信使目前往返于最北方的阿苟纳之池与铸魔营地：暴虐之间。你必须在铸魔营地：暴虐外截住并干掉他，并带着他身上的军团公文回来见我。','地狱火半岛上远征军岗哨的前线指挥官金斯顿要求你找到并杀死阿瑞克斯玛里达许，夺回军团公文。','<金斯顿读着公文。>$B$B我被赋予的权力并不足以应付这么重大的军情。你必须立刻带着这份公文到达纳斯.托尔贝恩那里!','我对你的能力有信心，$N。') ON DUPLICATE KEY UPDATE Title_loc4='任务:杀死信差',Details_loc4='你的行动已经开始令军团感到不安了，$N。我的斥候刚刚通知我说，军团被迫重新开始利用信使来传递信件，完成通讯。这下我们就有了将他们彻底铲除出这片大陆的机会！$B$B接下来我要你做的事，要求你拥有远远超出一般的士兵的机敏和战力。$B$B军团的信使目前往返于最北方的阿苟纳之池与铸魔营地：暴虐之间。你必须在铸魔营地：暴虐外截住并干掉他，并带着他身上的军团公文回来见我。',Objectives_loc4='地狱火半岛上远征军岗哨的前线指挥官金斯顿要求你找到并杀死阿瑞克斯玛里达许，夺回军团公文。',OfferRewardText_loc4='<金斯顿读着公文。>$B$B我被赋予的权力并不足以应付这么重大的军情。你必须立刻带着这份公文到达纳斯.托尔贝恩那里!',RequestItemsText_loc4='我对你的能力有信心，$N。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10148,'任务:充当信差','我仅仅是一名前线的战地指挥官，$c。对于这样重要的情报，我们该采取什么样的行动……，决定权限只能属于我们的领袖军队指挥官达纳斯·托尔贝恩阁下。你必须马上把这些信件带到荣耀堡去呈现给他。士兵，去后面搭乘狮鹫吧，愿你一路上不会受到任何阻碍！','将军团公文带给地狱火半岛上荣耀堡内的军队指挥官达纳斯·托尔贝恩。','<达纳斯抓着他的胡须。>$B$B他们这下子栽在我们手上了!这将是由阿拉萨尔斯亲手写的最后一封公文。','你有军团行动的消息吗?') ON DUPLICATE KEY UPDATE Title_loc4='任务:充当信差',Details_loc4='我仅仅是一名前线的战地指挥官，$c。对于这样重要的情报，我们该采取什么样的行动……，决定权限只能属于我们的领袖军队指挥官达纳斯·托尔贝恩阁下。你必须马上把这些信件带到荣耀堡去呈现给他。士兵，去后面搭乘狮鹫吧，愿你一路上不会受到任何阻碍！',Objectives_loc4='将军团公文带给地狱火半岛上荣耀堡内的军队指挥官达纳斯·托尔贝恩。',OfferRewardText_loc4='<达纳斯抓着他的胡须。>$B$B他们这下子栽在我们手上了!这将是由阿拉萨尔斯亲手写的最后一封公文。',RequestItemsText_loc4='你有军团行动的消息吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10149,'任务:终结所有，战胜所有','假如你没有截获这些信件，你知道会发生什么事情吗，$N？<达纳斯点了点头。>$B$B是的，全地狱火半岛的燃烧军团部队都会来敲我们荣耀堡的大门。若是真有那样一场突袭，恐怕没有人可以活下来。$B$B要想不让这些命令抵达军团前线，那只有一个办法。你必须立刻前往西北方的阿苟纳之池，并杀死这只阿拉萨尔斯。$B$B去吧，若是能够成功，我会大力嘉奖你的。','地狱火半岛上荣耀堡的军队指挥官达纳斯·托尔贝恩要你去杀掉残忍的阿拉萨尔斯.','做得好，士兵。的确，做得好。这最少为我们挣得了另外一个月的时间，或许可给我们足够的时间去弄清楚地狱火堡垒里正在发生什么事。$B$B现在有关于表扬的事……','这任务可不简单，$N。') ON DUPLICATE KEY UPDATE Title_loc4='任务:终结所有，战胜所有',Details_loc4='假如你没有截获这些信件，你知道会发生什么事情吗，$N？<达纳斯点了点头。>$B$B是的，全地狱火半岛的燃烧军团部队都会来敲我们荣耀堡的大门。若是真有那样一场突袭，恐怕没有人可以活下来。$B$B要想不让这些命令抵达军团前线，那只有一个办法。你必须立刻前往西北方的阿苟纳之池，并杀死这只阿拉萨尔斯。$B$B去吧，若是能够成功，我会大力嘉奖你的。',Objectives_loc4='地狱火半岛上荣耀堡的军队指挥官达纳斯·托尔贝恩要你去杀掉残忍的阿拉萨尔斯.',OfferRewardText_loc4='做得好，士兵。的确，做得好。这最少为我们挣得了另外一个月的时间，或许可给我们足够的时间去弄清楚地狱火堡垒里正在发生什么事。$B$B现在有关于表扬的事……',RequestItemsText_loc4='这任务可不简单，$N。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10150,'堡垒的外围','每天，地狱火堡垒都会打开它的大门，无数的邪兽人会在此时涌出那个巨大的堡垒，如洪流一般分布到沿着要塞的南侧城墙周围所设立的各个营地去。$B$B我已经派了一名最优秀的斥候玛克哈去侦察这些邪兽人的活动状况、装备情况和数量分布等等情报。但是，她至今还没有向我发回任何报告或是其它什么信息。$B$B斥候玛克哈应该主要是在北部城墙最北侧营地一带，也就是靠近岩石堆的地方进行侦察。找到她，$N。若是没有她带回来的消息，我们就只能坐以待毙。','前往北部城墙最北端的营地寻找斥候玛克哈的下落。','在一连串其它事件中，命令提到一名兽人囚犯。如果斥候马克哈的确就是在记录里提及的俘虏，那她可能还活着。','俯倒，在你还没被抓到前快去检查这些计划书。') ON DUPLICATE KEY UPDATE Title_loc4='堡垒的外围',Details_loc4='每天，地狱火堡垒都会打开它的大门，无数的邪兽人会在此时涌出那个巨大的堡垒，如洪流一般分布到沿着要塞的南侧城墙周围所设立的各个营地去。$B$B我已经派了一名最优秀的斥候玛克哈去侦察这些邪兽人的活动状况、装备情况和数量分布等等情报。但是，她至今还没有向我发回任何报告或是其它什么信息。$B$B斥候玛克哈应该主要是在北部城墙最北侧营地一带，也就是靠近岩石堆的地方进行侦察。找到她，$N。若是没有她带回来的消息，我们就只能坐以待毙。',Objectives_loc4='前往北部城墙最北端的营地寻找斥候玛克哈的下落。',OfferRewardText_loc4='在一连串其它事件中，命令提到一名兽人囚犯。如果斥候马克哈的确就是在记录里提及的俘虏，那她可能还活着。',RequestItemsText_loc4='俯倒，在你还没被抓到前快去检查这些计划书。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10151,'指挥官奈克罗格的命令','这些命令是由指挥官奈克罗格下达的，他命令营地中的邪兽人巡逻兵将这个兽人囚犯带到南边去进行审讯。$B$B暗影猎手塔金曾说过，北部城墙附近到处都有邪兽人的营地，因此他们将斥候玛克哈带到北部城墙附近的任何一个营地之中都是有可能的。$B$B此外，从信中提到的审讯来看，捕捉到她的邪兽人一定认为暂时留着她的性命会有什么好处。因此，你最好趁这他们还没有改变主意之前，赶紧找到斥候玛克哈的下落。','沿着北部城墙的西侧往南搜索，在下一个营地处寻找斥候玛克哈的下落。','马克哈的盾，剑和其它贵重物品似乎被随便扔到一旁。囚犯好像在不久后被拖到了远处。','这盾跟剑看起来好像是部落斥候的旧有标准装备。') ON DUPLICATE KEY UPDATE Title_loc4='指挥官奈克罗格的命令',Details_loc4='这些命令是由指挥官奈克罗格下达的，他命令营地中的邪兽人巡逻兵将这个兽人囚犯带到南边去进行审讯。$B$B暗影猎手塔金曾说过，北部城墙附近到处都有邪兽人的营地，因此他们将斥候玛克哈带到北部城墙附近的任何一个营地之中都是有可能的。$B$B此外，从信中提到的审讯来看，捕捉到她的邪兽人一定认为暂时留着她的性命会有什么好处。因此，你最好趁这他们还没有改变主意之前，赶紧找到斥候玛克哈的下落。',Objectives_loc4='沿着北部城墙的西侧往南搜索，在下一个营地处寻找斥候玛克哈的下落。',OfferRewardText_loc4='马克哈的盾，剑和其它贵重物品似乎被随便扔到一旁。囚犯好像在不久后被拖到了远处。',RequestItemsText_loc4='这盾跟剑看起来好像是部落斥候的旧有标准装备。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10152,'西侧的威胁','除了其它指示之外，命令书中还提到要让邪兽人们准备好武器和装备，随时准备发动下一次进攻。$B$B依照这份计划，指挥官奈克罗格的军队将从西边进攻萨尔玛，与东边的军队形成一个钳形攻击战略。$B$B而当萨尔玛的守备部队把注意力都集中在东侧的城墙时，来自西边的袭击将是极具杀伤力的。只有让西边的军队无法发起袭击，萨尔玛才有希望逃脱危险。','杀死10名碎手卫兵、10名碎手狂战士和5名碎手侍僧，然后向塞斯高附近断背岗哨的石头守卫安比兰报到。','你是对的，$N。如果他们成功的与在萨斯葛尔的军队一起进行他们的攻击，萨尔玛就会被占领了。$B$B幸好你有先见之明，在一切太迟之前阻止了战王奈克罗格的部队$B$B','你看起来很不安。你发现了什么吗?') ON DUPLICATE KEY UPDATE Title_loc4='西侧的威胁',Details_loc4='除了其它指示之外，命令书中还提到要让邪兽人们准备好武器和装备，随时准备发动下一次进攻。$B$B依照这份计划，指挥官奈克罗格的军队将从西边进攻萨尔玛，与东边的军队形成一个钳形攻击战略。$B$B而当萨尔玛的守备部队把注意力都集中在东侧的城墙时，来自西边的袭击将是极具杀伤力的。只有让西边的军队无法发起袭击，萨尔玛才有希望逃脱危险。',Objectives_loc4='杀死10名碎手卫兵、10名碎手狂战士和5名碎手侍僧，然后向塞斯高附近断背岗哨的石头守卫安比兰报到。',OfferRewardText_loc4='你是对的，$N。如果他们成功的与在萨斯葛尔的军队一起进行他们的攻击，萨尔玛就会被占领了。$B$B幸好你有先见之明，在一切太迟之前阻止了战王奈克罗格的部队$B$B',RequestItemsText_loc4='你看起来很不安。你发现了什么吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10153,'拯救斥候玛克哈','玛克哈散落着的装备和物品略略向南方扩展了几十码，穿过了荣耀之路。而从地面上浅而凌乱的车轮印迹看得出，押解玛克哈的那些邪兽人都没来得及带走什么东西，走得十分匆忙。这是为什么呢？$B$B难道是有人在那边等着审讯她？难道就是指挥官奈克罗格，你在信中了解到的那个应该驻扎在最北边的邪兽人首领？$B$B总之，这面盾牌，以及这些车轮印迹给你带来了更多的疑问，但无论如何，你已经大致知道斥候玛克哈在什么地方了，说不定你还可以在那里找到指挥官奈克罗格。','往南穿越荣耀之路，前往南部城墙寻找指挥官奈克罗格囚禁斥候玛克哈的地方。','你必须让我离开这里，但并不容易。战王奈克罗格的手下个个凶猛且训练有素。','是影子猎人泰巾派你来找我的吗?') ON DUPLICATE KEY UPDATE Title_loc4='拯救斥候玛克哈',Details_loc4='玛克哈散落着的装备和物品略略向南方扩展了几十码，穿过了荣耀之路。而从地面上浅而凌乱的车轮印迹看得出，押解玛克哈的那些邪兽人都没来得及带走什么东西，走得十分匆忙。这是为什么呢？$B$B难道是有人在那边等着审讯她？难道就是指挥官奈克罗格，你在信中了解到的那个应该驻扎在最北边的邪兽人首领？$B$B总之，这面盾牌，以及这些车轮印迹给你带来了更多的疑问，但无论如何，你已经大致知道斥候玛克哈在什么地方了，说不定你还可以在那里找到指挥官奈克罗格。',Objectives_loc4='往南穿越荣耀之路，前往南部城墙寻找指挥官奈克罗格囚禁斥候玛克哈的地方。',OfferRewardText_loc4='你必须让我离开这里，但并不容易。战王奈克罗格的手下个个凶猛且训练有素。',RequestItemsText_loc4='是影子猎人泰巾派你来找我的吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10154,'逃脱计划','就像我说的那样，要想从这里逃出去不是件容易的事情。指挥官奈克罗格虽然看上去像是个只有一身蛮力的家伙，但实际上他一点也不笨。$B$B事实上，牢房的钥匙一直都在他身上，从没有离开过他的视线之外。而且，他根本不会轻易从塔顶上下来，除非是要审讯我或者另外一个人类俘虏。$B$B总之，想让他从塔顶上下来得花费点工夫，不过，我已经有个办法了。找个在南部城墙边巡逻的士兵，把他身上的炸药给我带回来。','杀死一名碎手掷弹兵，将他携带的劣质炸弹交给高加兹前哨的斥候玛克哈。','我看见过那些掷弹兵在战斗中使用这些东西。这种炸药好像大多数时候都可以确实引爆，并且造成相当的爆炸力!让我们测试它们。','你拿到爆裂物了吗?') ON DUPLICATE KEY UPDATE Title_loc4='逃脱计划',Details_loc4='就像我说的那样，要想从这里逃出去不是件容易的事情。指挥官奈克罗格虽然看上去像是个只有一身蛮力的家伙，但实际上他一点也不笨。$B$B事实上，牢房的钥匙一直都在他身上，从没有离开过他的视线之外。而且，他根本不会轻易从塔顶上下来，除非是要审讯我或者另外一个人类俘虏。$B$B总之，想让他从塔顶上下来得花费点工夫，不过，我已经有个办法了。找个在南部城墙边巡逻的士兵，把他身上的炸药给我带回来。',Objectives_loc4='杀死一名碎手掷弹兵，将他携带的劣质炸弹交给高加兹前哨的斥候玛克哈。',OfferRewardText_loc4='我看见过那些掷弹兵在战斗中使用这些东西。这种炸药好像大多数时候都可以确实引爆，并且造成相当的爆炸力!让我们测试它们。',RequestItemsText_loc4='你拿到爆裂物了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText3_loc4) VALUES (10155,'挑衅指挥官','计划是成功还是失败，可就全靠这些炸弹了……$B$B尽管我非常讨厌使用邪兽人制造的东西，但现在这可能是我活着逃出去的唯一机会。带上这个，将它扔向塔上悬挂着的旗帜。$B$B听到爆炸声之后，指挥官奈克罗格一定会从塔顶上走下来查看，要把捣乱的人给揪出来。你就要趁这个机会杀掉他，拿到钥匙后马上回来帮我把牢房的门打开。祝你好运，$N。','引爆劣质炸弹制造混乱，诱使指挥官奈克罗格离开哨塔。从他手中夺得奈克罗格的钥匙，打开囚禁斥候玛克哈的牢笼。救出斥候玛克哈之后向塞斯高附近断背岗哨的石头守卫安比兰复命。','我本来开始怀疑我们再也看不到斥候马克哈的消息，不过你已经证明我错了。$B$B没有多少时间可以庆祝了，把他们的计划告诉我。你成功的切断他们西边的军力，但是仍然有相当大的敌军集结在萨斯葛尔。','<石卫士安比蓝看起来很紧张。>$B$B影子猎人泰巾要我等你。你有找到任何斥候马克哈的蛛丝马迹吗?','营救斥候马克哈') ON DUPLICATE KEY UPDATE Title_loc4='挑衅指挥官',Details_loc4='计划是成功还是失败，可就全靠这些炸弹了……$B$B尽管我非常讨厌使用邪兽人制造的东西，但现在这可能是我活着逃出去的唯一机会。带上这个，将它扔向塔上悬挂着的旗帜。$B$B听到爆炸声之后，指挥官奈克罗格一定会从塔顶上走下来查看，要把捣乱的人给揪出来。你就要趁这个机会杀掉他，拿到钥匙后马上回来帮我把牢房的门打开。祝你好运，$N。',Objectives_loc4='引爆劣质炸弹制造混乱，诱使指挥官奈克罗格离开哨塔。从他手中夺得奈克罗格的钥匙，打开囚禁斥候玛克哈的牢笼。救出斥候玛克哈之后向塞斯高附近断背岗哨的石头守卫安比兰复命。',OfferRewardText_loc4='我本来开始怀疑我们再也看不到斥候马克哈的消息，不过你已经证明我错了。$B$B没有多少时间可以庆祝了，把他们的计划告诉我。你成功的切断他们西边的军力，但是仍然有相当大的敌军集结在萨斯葛尔。',RequestItemsText_loc4='<石卫士安比蓝看起来很紧张。>$B$B影子猎人泰巾要我等你。你有找到任何斥候马克哈的蛛丝马迹吗?',ObjectiveText3_loc4='营救斥候马克哈';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10156,'谁的命令？','现在，$N，至少有一件事已经明确了，那就是：我们不能让状况继续恶化下去。邪兽人数量增长的速度与我们消灭他们的速度几乎一样快，现在几乎已经将我们包围了。如果只是这样躲在工事后面，整天算着日子，等待邪兽人或是燃烧军团过来把我们完全杀光的话，我们是无法赢得这场战争的。$B$B你最近表现得非常出色，已经使我们避免了多次邪兽人凶残的进犯，但是，这还不够，你现在必须想办法攻进荣耀之路，并找出在幕后策划了这几次袭击的那个幕后黑手。','杀死20个碎手步兵和10个碎手术士，并夺得教官祖罗克的命令，然后向断背岗哨的石头守卫安比兰复命。','做得好，$N。这些公文终于可揭露出这些攻击之后的策划者身分。','我们离来源愈来愈近了，$N。你发现什么了吗?') ON DUPLICATE KEY UPDATE Title_loc4='谁的命令？',Details_loc4='现在，$N，至少有一件事已经明确了，那就是：我们不能让状况继续恶化下去。邪兽人数量增长的速度与我们消灭他们的速度几乎一样快，现在几乎已经将我们包围了。如果只是这样躲在工事后面，整天算着日子，等待邪兽人或是燃烧军团过来把我们完全杀光的话，我们是无法赢得这场战争的。$B$B你最近表现得非常出色，已经使我们避免了多次邪兽人凶残的进犯，但是，这还不够，你现在必须想办法攻进荣耀之路，并找出在幕后策划了这几次袭击的那个幕后黑手。',Objectives_loc4='杀死20个碎手步兵和10个碎手术士，并夺得教官祖罗克的命令，然后向断背岗哨的石头守卫安比兰复命。',OfferRewardText_loc4='做得好，$N。这些公文终于可揭露出这些攻击之后的策划者身分。',RequestItemsText_loc4='我们离来源愈来愈近了，$N。你发现什么了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10157,'刺杀指挥官','根据我目前所掌握的情报，教官祖罗克应该是为地狱火半岛上所有邪兽人首领指挥官戈拉克斯效力的，是他的心腹，他的左右臂膀。$B$B这个戈拉克斯明显不是个典型的邪兽人蛮夷，尽管他是我们的敌人，我仍不得不佩服他，是他让我们在如此长的时间内都被迫陷入被动的境地。$B$B祖罗克的命令书中显示出戈拉克斯的指挥部位于荣耀之路末端，靠近要塞城墙与北部城墙相接的地方，你要立刻去刺杀他。不过，面对这样一个强大的邪兽人，说不准会发生什么事情，$N，你最好能带些同伴一起去。','杀死指挥官戈拉克斯，然后向萨尔玛的暗影猎手塔金复命。','萨尔玛的防卫者已经享受到他们努力暂缓邪兽人攻击的喘息时间，虽然燃烧军团还是继续着他们的战争。击败军队指挥官葛洛克斯，你已经帮了萨尔玛一个大忙。$B$B你实在是你们战友的典范。','斥候马克哈在从葛卡兹哨站回来时带回了有关你的发现的消息。你在这对抗邪兽人的事迹不会被忽略的。') ON DUPLICATE KEY UPDATE Title_loc4='刺杀指挥官',Details_loc4='根据我目前所掌握的情报，教官祖罗克应该是为地狱火半岛上所有邪兽人首领指挥官戈拉克斯效力的，是他的心腹，他的左右臂膀。$B$B这个戈拉克斯明显不是个典型的邪兽人蛮夷，尽管他是我们的敌人，我仍不得不佩服他，是他让我们在如此长的时间内都被迫陷入被动的境地。$B$B祖罗克的命令书中显示出戈拉克斯的指挥部位于荣耀之路末端，靠近要塞城墙与北部城墙相接的地方，你要立刻去刺杀他。不过，面对这样一个强大的邪兽人，说不准会发生什么事情，$N，你最好能带些同伴一起去。',Objectives_loc4='杀死指挥官戈拉克斯，然后向萨尔玛的暗影猎手塔金复命。',OfferRewardText_loc4='萨尔玛的防卫者已经享受到他们努力暂缓邪兽人攻击的喘息时间，虽然燃烧军团还是继续着他们的战争。击败军队指挥官葛洛克斯，你已经帮了萨尔玛一个大忙。$B$B你实在是你们战友的典范。',RequestItemsText_loc4='斥候马克哈在从葛卡兹哨站回来时带回了有关你的发现的消息。你在这对抗邪兽人的事迹不会被忽略的。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10158,'血环补给品','东南边的兽人城镇废墟塞斯高现在成了那些地狱火堡垒中源源不断涌出的邪兽人的基地。$B$B因此，暗影猎手塔金把我派到这里来，监视这处据点，以及里面那些奇特的居民。$B$B总之，某种神秘的东西令那些邪兽人发生了变化，变得更加强大了。我们必须想办法阻止他们继续壮大自己的力量。现在你立刻前往塞斯高，破坏掉那里所有的补给品。','摧毁6堆血环补给箱，然后向断背岗哨的石头守卫安比兰复命。','做的好，$N。持续控制他们将会是一个挑战，但这是唯一的方法可以阻止自萨斯葛尔发动的一连串攻击。','避免更多攻击的唯一方法就是让邪兽人永远都在防御状态。你将他们的补给品都消毁了吗?') ON DUPLICATE KEY UPDATE Title_loc4='血环补给品',Details_loc4='东南边的兽人城镇废墟塞斯高现在成了那些地狱火堡垒中源源不断涌出的邪兽人的基地。$B$B因此，暗影猎手塔金把我派到这里来，监视这处据点，以及里面那些奇特的居民。$B$B总之，某种神秘的东西令那些邪兽人发生了变化，变得更加强大了。我们必须想办法阻止他们继续壮大自己的力量。现在你立刻前往塞斯高，破坏掉那里所有的补给品。',Objectives_loc4='摧毁6堆血环补给箱，然后向断背岗哨的石头守卫安比兰复命。',OfferRewardText_loc4='做的好，$N。持续控制他们将会是一个挑战，但这是唯一的方法可以阻止自萨斯葛尔发动的一连串攻击。',RequestItemsText_loc4='避免更多攻击的唯一方法就是让邪兽人永远都在防御状态。你将他们的补给品都消毁了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10159,'扫清棘牙岭！','我们目前正为扫清那些棘牙岭的掠食者而战。毕竟，如果我们这里与赞加沼泽庇护所之间的联系被完全切断，事态就太过糟糕了。$B$B其实，我们并也不想将这些生物全部赶出家园，但它们经常袭击这里的旅行者，而且最近变得越来越具备攻击性，因此，我们已经没有其它选择了。$B$B如果你愿意帮忙的话，就太好了。','杀死8只棘牙掠食者和8只棘牙喷毒者，然后返回地狱火半岛的塞纳里奥哨站，向玛霍拉姆·硬蹄复命。','随着劫毁者被清除了，那些往返于赞加沼泽上塞纳里奥避难所的旅人应该会比较轻松了。$B$B塞纳里奥远征队感谢你。','你去清理棘牙丘陵的这件事进展得如何?') ON DUPLICATE KEY UPDATE Title_loc4='扫清棘牙岭！',Details_loc4='我们目前正为扫清那些棘牙岭的掠食者而战。毕竟，如果我们这里与赞加沼泽庇护所之间的联系被完全切断，事态就太过糟糕了。$B$B其实，我们并也不想将这些生物全部赶出家园，但它们经常袭击这里的旅行者，而且最近变得越来越具备攻击性，因此，我们已经没有其它选择了。$B$B如果你愿意帮忙的话，就太好了。',Objectives_loc4='杀死8只棘牙掠食者和8只棘牙喷毒者，然后返回地狱火半岛的塞纳里奥哨站，向玛霍拉姆·硬蹄复命。',OfferRewardText_loc4='随着劫毁者被清除了，那些往返于赞加沼泽上塞纳里奥避难所的旅人应该会比较轻松了。$B$B塞纳里奥远征队感谢你。',RequestItemsText_loc4='你去清理棘牙丘陵的这件事进展得如何?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10160,'知己知彼','有传闻说，最近战场出现了一批新的兽人，而且他们的数量还在不断增加。相对于我们一直以来面对的那些兽人，这群新兽人体型更加巨大，性格也更加残忍与狡猾。如果这个传闻是真的，那们我们原本就已势单力薄的军队恐怕根本无法与之抗衡。$B$B我已经委托深得我信任的阿曼蒂中尉前去调查这个传闻。如果你愿意在这危机关头帮助我们的话，就请直接去找她吧。她的分队目前驻扎在荣耀堡西边那处古老的哨塔里。$B$B$N，离开荣耀堡后一定要格外小心，你将要面对的是一个完全陌生而又充满危险的新世界。','与荣耀堡西部哨塔内的阿曼蒂中尉谈一谈。','<阿玛迪中尉点头。>$B$B非常好，我们需要所有我们能取得的帮助。在南方堡垒附近持续增加的邪兽人使我忧心。我派了一个斥候去调查，但是他还没有回来。','很开心可以在这看到新面孔。你是军队指挥者派来的吗?') ON DUPLICATE KEY UPDATE Title_loc4='知己知彼',Details_loc4='有传闻说，最近战场出现了一批新的兽人，而且他们的数量还在不断增加。相对于我们一直以来面对的那些兽人，这群新兽人体型更加巨大，性格也更加残忍与狡猾。如果这个传闻是真的，那们我们原本就已势单力薄的军队恐怕根本无法与之抗衡。$B$B我已经委托深得我信任的阿曼蒂中尉前去调查这个传闻。如果你愿意在这危机关头帮助我们的话，就请直接去找她吧。她的分队目前驻扎在荣耀堡西边那处古老的哨塔里。$B$B$N，离开荣耀堡后一定要格外小心，你将要面对的是一个完全陌生而又充满危险的新世界。',Objectives_loc4='与荣耀堡西部哨塔内的阿曼蒂中尉谈一谈。',OfferRewardText_loc4='<阿玛迪中尉点头。>$B$B非常好，我们需要所有我们能取得的帮助。在南方堡垒附近持续增加的邪兽人使我忧心。我派了一个斥候去调查，但是他还没有回来。',RequestItemsText_loc4='很开心可以在这看到新面孔。你是军队指挥者派来的吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10161,'以防万一……','身为一名飞艇的艇长，在遇到紧急情况时，特别是当你的副驾驶只愿意服从来自胃部的命令时，你必须要保持头脑的冷静。$B$B比如现在，我就很冷静。我这里有一个好消息和一个坏消息，好消息是我们不必等待好几天才有替换零件可用；坏消息呢，就是我们的“备用零件”从这里一直散落到了东边的白骨之谷。$B$B啊，还有没有其它的坏消息？ 好吧，简单来说，备用零件已经没有了。嗯，对，在我们迫降的时候，零件全都掉落出去了。你能帮我把它们收集回来吗？这样我们就能把这玩意给修好了。','将30块飞艇碎片交给飞艇坠毁点的“尖嗓子”斯克里·拉克希德。','这些零件有的歪七扭八的，但是应该足够这里使用了。随着一些充满创意的工程，我有自信能够让它起作用!','你找到足够的零件了吗?如果没有，我可能得使用那个雷噶西一直在附近挥舞的平底锅。接着，我必须将飞艇重新命名为＂飞行平底锅″。') ON DUPLICATE KEY UPDATE Title_loc4='以防万一……',Details_loc4='身为一名飞艇的艇长，在遇到紧急情况时，特别是当你的副驾驶只愿意服从来自胃部的命令时，你必须要保持头脑的冷静。$B$B比如现在，我就很冷静。我这里有一个好消息和一个坏消息，好消息是我们不必等待好几天才有替换零件可用；坏消息呢，就是我们的“备用零件”从这里一直散落到了东边的白骨之谷。$B$B啊，还有没有其它的坏消息？ 好吧，简单来说，备用零件已经没有了。嗯，对，在我们迫降的时候，零件全都掉落出去了。你能帮我把它们收集回来吗？这样我们就能把这玩意给修好了。',Objectives_loc4='将30块飞艇碎片交给飞艇坠毁点的“尖嗓子”斯克里·拉克希德。',OfferRewardText_loc4='这些零件有的歪七扭八的，但是应该足够这里使用了。随着一些充满创意的工程，我有自信能够让它起作用!',RequestItemsText_loc4='你找到足够的零件了吗?如果没有，我可能得使用那个雷噶西一直在附近挥舞的平底锅。接着，我必须将飞艇重新命名为＂飞行平底锅″。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText3_loc4) VALUES (10162,'任务：地狱岩床','既然你现在已经可以飞行了，或许你会对另一个轰炸任务感兴趣？$B$B我们已经孤立了燃烧军团的主要生产区域，就在铸魔营地的正北方。而你要做的事情，就是乘坐双足飞龙去那里，炸掉那些该死的东西！$B$B这是给你的炸弹——当你准备好了的时候就去跟空军指挥官布拉克谈一谈。','地狱火半岛机甲残骸的前线指挥官托尔克要求你杀死20个甘尔葛苦工和5个莫尔葛监工，并摧毁5门邪能火炮。','你做得好像你一辈子都在飞行一样，$N。表现很杰出!双足翼龙毁灭者的身上甚至连一道抓痕都没有!','让他们知道不只有领空是安全的!','摧毁邪能火炮') ON DUPLICATE KEY UPDATE Title_loc4='任务：地狱岩床',Details_loc4='既然你现在已经可以飞行了，或许你会对另一个轰炸任务感兴趣？$B$B我们已经孤立了燃烧军团的主要生产区域，就在铸魔营地的正北方。而你要做的事情，就是乘坐双足飞龙去那里，炸掉那些该死的东西！$B$B这是给你的炸弹——当你准备好了的时候就去跟空军指挥官布拉克谈一谈。',Objectives_loc4='地狱火半岛机甲残骸的前线指挥官托尔克要求你杀死20个甘尔葛苦工和5个莫尔葛监工，并摧毁5门邪能火炮。',OfferRewardText_loc4='你做得好像你一辈子都在飞行一样，$N。表现很杰出!双足翼龙毁灭者的身上甚至连一道抓痕都没有!',RequestItemsText_loc4='让他们知道不只有领空是安全的!',ObjectiveText3_loc4='摧毁邪能火炮';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText3_loc4) VALUES (10163,'任务：地狱岩床','既然现在你也能够很熟练地飞行了，也许你还想再来一次轰炸任务？$B$B我们已经孤立了燃烧军团的主要生产区域，就在铸魔营地的正北方。我要你马上骑着狮鹫去摧毁这些该死的东西！$B$B拿上你的炸弹，准备完毕之后就去找狮鹫骑士维比洛吧。','地狱火半岛破碎岗哨的空军指挥官格莱芬加尔要求你杀死20个甘尔葛苦工和5个莫尔葛监工，并摧毁5门邪能火炮。','你做得好像你一辈子都在飞行一样，$N。表现很杰出!狮鹫兽毁灭者的身上甚至连一道抓痕都没有!','让他们知道不只有领空是安全的!','摧毁邪能火炮') ON DUPLICATE KEY UPDATE Title_loc4='任务：地狱岩床',Details_loc4='既然现在你也能够很熟练地飞行了，也许你还想再来一次轰炸任务？$B$B我们已经孤立了燃烧军团的主要生产区域，就在铸魔营地的正北方。我要你马上骑着狮鹫去摧毁这些该死的东西！$B$B拿上你的炸弹，准备完毕之后就去找狮鹫骑士维比洛吧。',Objectives_loc4='地狱火半岛破碎岗哨的空军指挥官格莱芬加尔要求你杀死20个甘尔葛苦工和5个莫尔葛监工，并摧毁5门邪能火炮。',OfferRewardText_loc4='你做得好像你一辈子都在飞行一样，$N。表现很杰出!狮鹫兽毁灭者的身上甚至连一道抓痕都没有!',RequestItemsText_loc4='让他们知道不只有领空是安全的!',ObjectiveText3_loc4='摧毁邪能火炮';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10164,'一切都会变好的','$N，看来你有着丰富的冒险经历，甚至进入过奥金尼地穴探险。$B$B我是个幸运的幽灵。我既没有沦为利维休斯的仆从，也没有成为大大主教玛拉达尔那罪恶的通灵术实验中的牺牲品。尽管你杀死了利维休斯，玛拉达尔却还活着，继续折磨着地穴中痛苦的灵魂。$B$B我希望你做的事很简单。进入奥金尼地穴杀死大大主教玛拉达尔，让那些被禁锢的灵魂得以安息。','奥金顿奥金尼地穴外的奥德里姆斯宗父要你进入奥金尼地穴，消灭大大主教玛拉达尔。','你做到了，$N!灵魂被释放了!$B$B虽然我没有一个物质上的表示，但我仍然能以来自精灵世界的物品奖赏你。小心使用，像这样的物品经常是具爆炸性且能更使它们的用户受到重大伤害。','拯救那些灵魂，$N。') ON DUPLICATE KEY UPDATE Title_loc4='一切都会变好的',Details_loc4='$N，看来你有着丰富的冒险经历，甚至进入过奥金尼地穴探险。$B$B我是个幸运的幽灵。我既没有沦为利维休斯的仆从，也没有成为大大主教玛拉达尔那罪恶的通灵术实验中的牺牲品。尽管你杀死了利维休斯，玛拉达尔却还活着，继续折磨着地穴中痛苦的灵魂。$B$B我希望你做的事很简单。进入奥金尼地穴杀死大大主教玛拉达尔，让那些被禁锢的灵魂得以安息。',Objectives_loc4='奥金顿奥金尼地穴外的奥德里姆斯宗父要你进入奥金尼地穴，消灭大大主教玛拉达尔。',OfferRewardText_loc4='你做到了，$N!灵魂被释放了!$B$B虽然我没有一个物质上的表示，但我仍然能以来自精灵世界的物品奖赏你。小心使用，像这样的物品经常是具爆炸性且能更使它们的用户受到重大伤害。',RequestItemsText_loc4='拯救那些灵魂，$N。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10165,'扫除竞争者','沙法尔真是个精明的家伙，我一定要治治他……星界社团只能眼睁睁地看着他将墓穴里值钱的东西劫掠一空。$r，瞧瞧我手下的这帮蠢材，他们根本无力突破沙法尔的防线，不如我们来做笔交易吧。$B$B进入法力陵墓，杀死节点亲王沙法尔。带回沙法尔的护腕带，做为你杀死他的凭证。我不会亏待你的。','法力陵墓外的节点亲王哈拉迈德要你杀死节点亲王沙法尔，并将沙法尔的护腕带交给他。','另一个竞争者消失了……你为了一个噬尸兽做了一件好事，$r。如果你来虚空风暴，来拜访我。我就住在风暴之尖。','我不喜欢『分享』。') ON DUPLICATE KEY UPDATE Title_loc4='扫除竞争者',Details_loc4='沙法尔真是个精明的家伙，我一定要治治他……星界社团只能眼睁睁地看着他将墓穴里值钱的东西劫掠一空。$r，瞧瞧我手下的这帮蠢材，他们根本无力突破沙法尔的防线，不如我们来做笔交易吧。$B$B进入法力陵墓，杀死节点亲王沙法尔。带回沙法尔的护腕带，做为你杀死他的凭证。我不会亏待你的。',Objectives_loc4='法力陵墓外的节点亲王哈拉迈德要你杀死节点亲王沙法尔，并将沙法尔的护腕带交给他。',OfferRewardText_loc4='另一个竞争者消失了……你为了一个噬尸兽做了一件好事，$r。如果你来虚空风暴，来拜访我。我就住在风暴之尖。',RequestItemsText_loc4='我不喜欢『分享』。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10166,'怀特巴克的记忆','这件坠饰让我想起了那段非比寻常的岁月，真是一段美好的时光……$B$B可惜现在我已经不需要任何回忆了。$B$B让这件坠饰和回忆都埋入焦痕谷的符石吧。我就是在那儿遇见那位树人长者的。让所有关于这位故人的回忆都一起埋葬了吧。','拉莉亚娜·河风要你将怀特巴克的坠饰放在焦痕谷的符石上。','我已经不再属于这个世界了，而且必须承认失败。这片土地已经永远改变了，没有什么会是永远不变的。$B$B把这个墬饰留在这里给我吧，$N。也许有一天，在精灵们消失很久以后，一颗新生之树会在这个特别的地方生长 -','你回来了，$N。你做得还不够吗?') ON DUPLICATE KEY UPDATE Title_loc4='怀特巴克的记忆',Details_loc4='这件坠饰让我想起了那段非比寻常的岁月，真是一段美好的时光……$B$B可惜现在我已经不需要任何回忆了。$B$B让这件坠饰和回忆都埋入焦痕谷的符石吧。我就是在那儿遇见那位树人长者的。让所有关于这位故人的回忆都一起埋葬了吧。',Objectives_loc4='拉莉亚娜·河风要你将怀特巴克的坠饰放在焦痕谷的符石上。',OfferRewardText_loc4='我已经不再属于这个世界了，而且必须承认失败。这片土地已经永远改变了，没有什么会是永远不变的。$B$B把这个墬饰留在这里给我吧，$N。也许有一天，在精灵们消失很久以后，一颗新生之树会在这个特别的地方生长 -',RequestItemsText_loc4='你回来了，$N。你做得还不够吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10167,'奥金顿……','奥金尼地穴深处有一座坟墓。破碎的外域随处都可以看到墓穴，惟有这座坟墓与众不同。奥金顿的陵墓群就起源于这座墓穴。$B$B进入奥金顿的奥金尼地穴，找到这处坟墓。杀死墓穴的守卫，解救出被关押在墓穴中的灵魂。那个灵魂就是一切的关键……','前往泰罗卡森林白骨荒野的奥金尼地穴，杀死大大主教玛拉达尔，解救德欧里的灵魂。','记忆是生动的，$N。我的能量完全被爆炸吸收。当预言者费伦和他的德莱尼同胞抬起我的遗体并且将它们带来这里时，我只是一个暗淡少量的虚无能量。在经过许多仪式之后，我那变小的身体被埋葬在这个石棺内。我花了差不多一千年一直在重生。循环过程几乎完成了……','<迪欧瑞的鬼魂哼了几下。>$B$B你好啊，$N。') ON DUPLICATE KEY UPDATE Title_loc4='奥金顿……',Details_loc4='奥金尼地穴深处有一座坟墓。破碎的外域随处都可以看到墓穴，惟有这座坟墓与众不同。奥金顿的陵墓群就起源于这座墓穴。$B$B进入奥金顿的奥金尼地穴，找到这处坟墓。杀死墓穴的守卫，解救出被关押在墓穴中的灵魂。那个灵魂就是一切的关键……',Objectives_loc4='前往泰罗卡森林白骨荒野的奥金尼地穴，杀死大大主教玛拉达尔，解救德欧里的灵魂。',OfferRewardText_loc4='记忆是生动的，$N。我的能量完全被爆炸吸收。当预言者费伦和他的德莱尼同胞抬起我的遗体并且将它们带来这里时，我只是一个暗淡少量的虚无能量。在经过许多仪式之后，我那变小的身体被埋葬在这个石棺内。我花了差不多一千年一直在重生。循环过程几乎完成了……',RequestItemsText_loc4='<迪欧瑞的鬼魂哼了几下。>$B$B你好啊，$N。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10168,'灵魂之眼','数百年来，无数奥金顿的灵魂被卷入了我体内黯淡的精华之中，我的能量一直不断衰竭，奥金尼地穴也因此频发灾难。$B$B很遗憾，没有什么能阻止这个循环。这便是纳鲁生命的轮回——没有虚空，圣光也不可能存在。$B$B惟一的挽救措施就是在纳格兰的兽人灵魂堕落为虚空生物之前消灭他们。这座墓穴中的灵魂之镜可以搭救他们……','在奥金尼地穴中找到一面灵魂之镜，用它召唤纳格兰上古兽人先祖的黑暗之魂。消灭15个黑暗的灵魂，让兽人先祖得以安然长眠。$B$B完成任务后，向先祖之地的卡舒尔宗母复命。','你已经完成了一次又长远又危险的旅行，冒着生命危险去确保玛格汉的安全和我们祖先的宁静。对此我不知道要怎么表达我的感谢。','<族母卡修尔看起来很生气。>$B$B这些纳鲁远比世界上所有形态的生命还要聪明。') ON DUPLICATE KEY UPDATE Title_loc4='灵魂之眼',Details_loc4='数百年来，无数奥金顿的灵魂被卷入了我体内黯淡的精华之中，我的能量一直不断衰竭，奥金尼地穴也因此频发灾难。$B$B很遗憾，没有什么能阻止这个循环。这便是纳鲁生命的轮回——没有虚空，圣光也不可能存在。$B$B惟一的挽救措施就是在纳格兰的兽人灵魂堕落为虚空生物之前消灭他们。这座墓穴中的灵魂之镜可以搭救他们……',Objectives_loc4='在奥金尼地穴中找到一面灵魂之镜，用它召唤纳格兰上古兽人先祖的黑暗之魂。消灭15个黑暗的灵魂，让兽人先祖得以安然长眠。$B$B完成任务后，向先祖之地的卡舒尔宗母复命。',OfferRewardText_loc4='你已经完成了一次又长远又危险的旅行，冒着生命危险去确保玛格汉的安全和我们祖先的宁静。对此我不知道要怎么表达我的感谢。',RequestItemsText_loc4='<族母卡修尔看起来很生气。>$B$B这些纳鲁远比世界上所有形态的生命还要聪明。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10169,'镇静剂','奥尔多如今看来是得到沙塔尔的恩宠了。怎么说好呢，这真是意料之外，情理之中。$B$B看吧，他们竟然在离阿达尔那么近的地方炫耀着他们的队列操演。除了拍纳鲁的马屁，他们还能干点别的正经事吗？$B$B先驱者哈隆奈姆的火枪手中队未免也太认真了点，居然因为担心午饭时间过长耽搁了操练，把自己的锅都给带来了。我们可不能放过这个机会，得给他们点颜色看看，$N。$B$B我要你把这个瓶子里的东西倒进他们的饭菜里。这样一来，结果可就……有趣了。','沙塔斯城内的魔导师法尔里斯要求你将一瓶镇静剂带去圣光广场，倒入射手队的烹饪锅内。','奥多尔神射手似乎被他们的训练分布注意力，让你有充裕的时间将药水放进炖菜里。','这些药草跟香料的香味充满着锅炉周围的空气中。') ON DUPLICATE KEY UPDATE Title_loc4='镇静剂',Details_loc4='奥尔多如今看来是得到沙塔尔的恩宠了。怎么说好呢，这真是意料之外，情理之中。$B$B看吧，他们竟然在离阿达尔那么近的地方炫耀着他们的队列操演。除了拍纳鲁的马屁，他们还能干点别的正经事吗？$B$B先驱者哈隆奈姆的火枪手中队未免也太认真了点，居然因为担心午饭时间过长耽搁了操练，把自己的锅都给带来了。我们可不能放过这个机会，得给他们点颜色看看，$N。$B$B我要你把这个瓶子里的东西倒进他们的饭菜里。这样一来，结果可就……有趣了。',Objectives_loc4='沙塔斯城内的魔导师法尔里斯要求你将一瓶镇静剂带去圣光广场，倒入射手队的烹饪锅内。',OfferRewardText_loc4='奥多尔神射手似乎被他们的训练分布注意力，让你有充裕的时间将药水放进炖菜里。',RequestItemsText_loc4='这些药草跟香料的香味充满着锅炉周围的空气中。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10170,'返回盖亚安祖母身边','$N，返回加拉达尔，向盖亚安祖母汇报这个好消息吧。玛格汉氏族必定会因此欢欣鼓舞。地狱咆哮之子说不定也能摆脱悲伤，重新振作起来。','返回加拉达尔，与盖亚安祖母谈一谈。','我要你亲自告诉加尔鲁什这个消息。','我看到你的梦境，$N。灵魂看顾着你……以他们无形的碰触指示你……') ON DUPLICATE KEY UPDATE Title_loc4='返回盖亚安祖母身边',Details_loc4='$N，返回加拉达尔，向盖亚安祖母汇报这个好消息吧。玛格汉氏族必定会因此欢欣鼓舞。地狱咆哮之子说不定也能摆脱悲伤，重新振作起来。',Objectives_loc4='返回加拉达尔，与盖亚安祖母谈一谈。',OfferRewardText_loc4='我要你亲自告诉加尔鲁什这个消息。',RequestItemsText_loc4='我看到你的梦境，$N。灵魂看顾着你……以他们无形的碰触指示你……';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10171,'消沉的酋长','$N，你给予了玛格汉氏族太多的帮助，你的英勇事迹传遍了整个氏族，连加尔鲁什都已经知道了。去找他吧，告诉他你所取得的成就。告诉他，你为他和他的子民所做的一切。你的话必定可以激励加尔鲁什。','加拉达尔的盖亚安祖母要你去跟加尔鲁什谈一谈。','每个人都觉得骄傲。骄傲我们的族人能活着看见另一个冬天。但那之后呢?还有什么?$B$B也许你应该来领导这个氏族，$N。也许接着当主母过世，我就可以死去。允许最后让我拭去家族姓氏的羞耻。我渴望如此的平静。','话语……无意义的话语……') ON DUPLICATE KEY UPDATE Title_loc4='消沉的酋长',Details_loc4='$N，你给予了玛格汉氏族太多的帮助，你的英勇事迹传遍了整个氏族，连加尔鲁什都已经知道了。去找他吧，告诉他你所取得的成就。告诉他，你为他和他的子民所做的一切。你的话必定可以激励加尔鲁什。',Objectives_loc4='加拉达尔的盖亚安祖母要你去跟加尔鲁什谈一谈。',OfferRewardText_loc4='每个人都觉得骄傲。骄傲我们的族人能活着看见另一个冬天。但那之后呢?还有什么?$B$B也许你应该来领导这个氏族，$N。也许接着当主母过世，我就可以死去。允许最后让我拭去家族姓氏的羞耻。我渴望如此的平静。',RequestItemsText_loc4='话语……无意义的话语……';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,EndText_loc4) VALUES (10172,'毫无希望','$N，你是一位可敬的$r。你给予了玛格汉氏族太多的帮助，没有谁能否定你为我的子民所做的一切。唉，玛格汉氏族的历史已经划上了句号。事实证明，我并不适合做氏族的领导者。我的体内涌动着被诅咒的血液。我不能……不能像我的父亲那样，被堕落之血操控身心。$B$B$N，请将我的话转告给祖母。我没脸见她……我不敢看她的眼睛。','将加尔鲁什所说的话转告给盖亚安祖母。','<眼泪从主母吉雅的脸上流了下来。>$B$B去找你的大酋长。告诉他我在这里等他……','<主母吉雅躺了下来。>','与盖亚安祖母谈话') ON DUPLICATE KEY UPDATE Title_loc4='毫无希望',Details_loc4='$N，你是一位可敬的$r。你给予了玛格汉氏族太多的帮助，没有谁能否定你为我的子民所做的一切。唉，玛格汉氏族的历史已经划上了句号。事实证明，我并不适合做氏族的领导者。我的体内涌动着被诅咒的血液。我不能……不能像我的父亲那样，被堕落之血操控身心。$B$B$N，请将我的话转告给祖母。我没脸见她……我不敢看她的眼睛。',Objectives_loc4='将加尔鲁什所说的话转告给盖亚安祖母。',OfferRewardText_loc4='<眼泪从主母吉雅的脸上流了下来。>$B$B去找你的大酋长。告诉他我在这里等他……',RequestItemsText_loc4='<主母吉雅躺了下来。>',EndText_loc4='与盖亚安祖母谈话';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10173,'大法师的法杖','请允许我作个自我介绍，$C。$B$B我名叫拉文德维尔，是大法师瓦格斯的学徒。$B$B我的导师目前……暂且说是状况不适吧。我来到这里是有要事的。$B$B城东南方的阿尔科隆遗迹目前已被燃烧军团所占据，成了他们进行邪恶活动的温床。他们在遗迹里活动的目标既不是我，也不是我的导师，而是由他们的领袖埃克拉斯所持有的大法师的法杖。$B$B这份召唤粉尘可以帮你诱使那个恶魔从藏身地现身，将它撒在遗迹中心的火盆里吧。','从审讯者埃克拉斯手中夺得大法师瓦格斯的法杖，将它交给52区的拉文德维尔。要使埃克拉斯从藏身处现身，你需要向遗迹中心的火盆喷撒召唤粉尘。','啊，你设法取回了权杖。让人印象深刻，$N。或许你是我一直寻找的那个人。$B$B喔，是的，你的报酬……$B$B<罗樊德威将几个硬币放到你的手掌上。>$B$B毫无疑问的你期望得更多，但是那也要随着时机而来。现在，将机会当成是真正的报酬。','直到大法师瓦戈斯之杖归还我才会休息。你可以从恶魔的手中将它抢回来吗?') ON DUPLICATE KEY UPDATE Title_loc4='大法师的法杖',Details_loc4='请允许我作个自我介绍，$C。$B$B我名叫拉文德维尔，是大法师瓦格斯的学徒。$B$B我的导师目前……暂且说是状况不适吧。我来到这里是有要事的。$B$B城东南方的阿尔科隆遗迹目前已被燃烧军团所占据，成了他们进行邪恶活动的温床。他们在遗迹里活动的目标既不是我，也不是我的导师，而是由他们的领袖埃克拉斯所持有的大法师的法杖。$B$B这份召唤粉尘可以帮你诱使那个恶魔从藏身地现身，将它撒在遗迹中心的火盆里吧。',Objectives_loc4='从审讯者埃克拉斯手中夺得大法师瓦格斯的法杖，将它交给52区的拉文德维尔。要使埃克拉斯从藏身处现身，你需要向遗迹中心的火盆喷撒召唤粉尘。',OfferRewardText_loc4='啊，你设法取回了权杖。让人印象深刻，$N。或许你是我一直寻找的那个人。$B$B喔，是的，你的报酬……$B$B<罗樊德威将几个硬币放到你的手掌上。>$B$B毫无疑问的你期望得更多，但是那也要随着时机而来。现在，将机会当成是真正的报酬。',RequestItemsText_loc4='直到大法师瓦戈斯之杖归还我才会休息。你可以从恶魔的手中将它抢回来吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10174,'紫罗兰之塔的诅咒','现在，你可以依靠大法师的法杖与他取得联络了。$B$B他居住在紫罗兰之塔中，就在东南方一座浮空的“岛屿”上。这座被诅咒的塔楼既是他的庇护所，也是他的监狱。肯瑞托法师无法进出紫罗兰之塔，这导致我不能与导师见面。$B$B这根法杖的魔法可以渗透塔楼的防御层，不过需要由肯瑞托议会之外的人来激活它。$B$B利用大法师的法杖生成他的影像，告诉他目前的状况，告诉他，我没有辜负他的期望。','利用大法师瓦格斯的法杖与他取得联系。$B$B如果你弄丢了大法师瓦格斯的法杖，可以向52区的拉文德维尔再要一根。','<当你传达罗樊德威的讯息时，大法师瓦戈斯的影像同时检查着你。>$B$B罗樊德威凡事都能符合他师傅的期望。当我给他权杖并且要他逃离时，我原本希望一旦凯尔萨斯的部队从塔里撤出，他可以使用它来寻求协助并解救我。从那以后，我已经学到了许多有关诅咒的种类。$B$B这是可以被破除的，$N，但是会需要你的协助。','你是谁?') ON DUPLICATE KEY UPDATE Title_loc4='紫罗兰之塔的诅咒',Details_loc4='现在，你可以依靠大法师的法杖与他取得联络了。$B$B他居住在紫罗兰之塔中，就在东南方一座浮空的“岛屿”上。这座被诅咒的塔楼既是他的庇护所，也是他的监狱。肯瑞托法师无法进出紫罗兰之塔，这导致我不能与导师见面。$B$B这根法杖的魔法可以渗透塔楼的防御层，不过需要由肯瑞托议会之外的人来激活它。$B$B利用大法师的法杖生成他的影像，告诉他目前的状况，告诉他，我没有辜负他的期望。',Objectives_loc4='利用大法师瓦格斯的法杖与他取得联系。$B$B如果你弄丢了大法师瓦格斯的法杖，可以向52区的拉文德维尔再要一根。',OfferRewardText_loc4='<当你传达罗樊德威的讯息时，大法师瓦戈斯的影像同时检查着你。>$B$B罗樊德威凡事都能符合他师傅的期望。当我给他权杖并且要他逃离时，我原本希望一旦凯尔萨斯的部队从塔里撤出，他可以使用它来寻求协助并解救我。从那以后，我已经学到了许多有关诅咒的种类。$B$B这是可以被破除的，$N，但是会需要你的协助。',RequestItemsText_loc4='你是谁?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10175,'萨尔，杜隆坦之子','$N，返回艾泽拉斯世界。告诉我的孙子萨尔，他的兄弟还活着——就在外域这块破碎的世界中。$B$B让他来给加尔鲁什讲讲，地狱咆哮是个多么伟大的英雄。$B$B必须让加尔鲁什知道关于他父亲的一切……','前往奥格瑞玛，将盖亚安祖母的口信告诉萨尔。','<萨尔的声音呈现风暴雷云的空洞本质。>$B$B我……我还有一位祖母吗?她还活着?','<萨尔从他的宝座站起来迎接你。>$B$B他们说你从外外域带来紧急的消息，$N。') ON DUPLICATE KEY UPDATE Title_loc4='萨尔，杜隆坦之子',Details_loc4='$N，返回艾泽拉斯世界。告诉我的孙子萨尔，他的兄弟还活着——就在外域这块破碎的世界中。$B$B让他来给加尔鲁什讲讲，地狱咆哮是个多么伟大的英雄。$B$B必须让加尔鲁什知道关于他父亲的一切……',Objectives_loc4='前往奥格瑞玛，将盖亚安祖母的口信告诉萨尔。',OfferRewardText_loc4='<萨尔的声音呈现风暴雷云的空洞本质。>$B$B我……我还有一位祖母吗?她还活着?',RequestItemsText_loc4='<萨尔从他的宝座站起来迎接你。>$B$B他们说你从外外域带来紧急的消息，$N。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10176,'守护者阿尔凯洛斯','你已经集齐了破除凯尔萨斯的诅咒所需的物品，要做的事情仅剩一件了。凯尔萨斯封印紫罗兰之塔时，将一个名叫阿尔凯洛斯的奥术傀儡留在了塔楼顶层。$B$B你必须击败阿尔凯洛斯，让我恢复塔内的魔法系统。$B$B当你进入紫罗兰之塔的那一刻起，凯尔萨斯的诅咒就会在你身上生效。$B$B击败阿尔凯洛斯之后，你要登上塔楼，协助我准备仪式。','进入肯瑞瓦村中心的紫罗兰之塔，击败阿尔凯洛斯，然后与大法师瓦格斯谈一谈。','你做的很好，$N。摧毁这个结界将有助于我可以更容易的解除这个塔的诅咒。','终于，我们见面了。') ON DUPLICATE KEY UPDATE Title_loc4='守护者阿尔凯洛斯',Details_loc4='你已经集齐了破除凯尔萨斯的诅咒所需的物品，要做的事情仅剩一件了。凯尔萨斯封印紫罗兰之塔时，将一个名叫阿尔凯洛斯的奥术傀儡留在了塔楼顶层。$B$B你必须击败阿尔凯洛斯，让我恢复塔内的魔法系统。$B$B当你进入紫罗兰之塔的那一刻起，凯尔萨斯的诅咒就会在你身上生效。$B$B击败阿尔凯洛斯之后，你要登上塔楼，协助我准备仪式。',Objectives_loc4='进入肯瑞瓦村中心的紫罗兰之塔，击败阿尔凯洛斯，然后与大法师瓦格斯谈一谈。',OfferRewardText_loc4='你做的很好，$N。摧毁这个结界将有助于我可以更容易的解除这个塔的诅咒。',RequestItemsText_loc4='终于，我们见面了。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10177,'奥金顿的麻烦','我在奥金顿安插了许多间谍，他们不断地给我发来令人烦恼的报告。自从数年前的大爆炸事件后，那里的麻烦事就层出不穷。$B$B最近，奥金顿的局势再次恶化，暗影议会正在筹划发动战争。尽管这些报告还缺乏细节，但是我们可以了解到，他们在奥金顿内秘密进行着准备工作。$B$B你必须立刻前往暗影迷宫的入口，战地指挥官玛弗恩会将你派到最需要的地方去。','前往泰罗卡森林的奥金顿，向暗影迷宫入口处的战地指挥官玛弗恩报到。','该是你抵达的时候了。麦莉莎说她送出帮忙需求已经好几天了。但是我们在这里战斗的时间比那更久!') ON DUPLICATE KEY UPDATE Title_loc4='奥金顿的麻烦',Details_loc4='我在奥金顿安插了许多间谍，他们不断地给我发来令人烦恼的报告。自从数年前的大爆炸事件后，那里的麻烦事就层出不穷。$B$B最近，奥金顿的局势再次恶化，暗影议会正在筹划发动战争。尽管这些报告还缺乏细节，但是我们可以了解到，他们在奥金顿内秘密进行着准备工作。$B$B你必须立刻前往暗影迷宫的入口，战地指挥官玛弗恩会将你派到最需要的地方去。',Objectives_loc4='前往泰罗卡森林的奥金顿，向暗影迷宫入口处的战地指挥官玛弗恩报到。',OfferRewardText_loc4='该是你抵达的时候了。麦莉莎说她送出帮忙需求已经好几天了。但是我们在这里战斗的时间比那更久!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10178,'寻找间谍托古恩','托古恩真是个蠢货！我们在这儿苦苦支撑，抵御敌人的攻击；他却返回奥金顿，试图收集更多的信息，还想营救其它的间谍！$B$B我都不知道我该爱他还是该宰了他！$B$B暗影议会利用魔法发现了我们的踪迹，我们不得不匆促撤离奥金顿，可惜大多数间谍没能顺利逃生。$B$B如果你敢进入暗影迷宫的话，能帮忙寻找托古恩的下落吗？我担心他会遭遇不测。','进入奥金顿的暗影迷宫，寻找间谍托古恩的下落。','什么?葛瑞克萨在我之后派你来这里吗?$B$B我不知道是否应该感到感动还是要叫她傻瓜!$B$B你认为你能帮助我逃出这只笼子吗?它有点难度的。') ON DUPLICATE KEY UPDATE Title_loc4='寻找间谍托古恩',Details_loc4='托古恩真是个蠢货！我们在这儿苦苦支撑，抵御敌人的攻击；他却返回奥金顿，试图收集更多的信息，还想营救其它的间谍！$B$B我都不知道我该爱他还是该宰了他！$B$B暗影议会利用魔法发现了我们的踪迹，我们不得不匆促撤离奥金顿，可惜大多数间谍没能顺利逃生。$B$B如果你敢进入暗影迷宫的话，能帮忙寻找托古恩的下落吗？我担心他会遭遇不测。',Objectives_loc4='进入奥金顿的暗影迷宫，寻找间谍托古恩的下落。',OfferRewardText_loc4='什么?葛瑞克萨在我之后派你来这里吗?$B$B我不知道是否应该感到感动还是要叫她傻瓜!$B$B你认为你能帮助我逃出这只笼子吗?它有点难度的。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10179,'肯瑞瓦村的管理器','当我们明确得知远征军已经被困外域，无法返回艾泽拉斯世界的时候，肯瑞托先遣队进驻了法兰伦平原，并修筑了一座名为肯瑞瓦的村落。我将村子交给管理器戴沃斯负责，但是当凯尔萨斯和他的军队将我封印在紫罗兰之塔中后，我便彻底失去了与他的联络。$B$B$N，去肯瑞瓦村寻找他的下落，尽你所能地帮助他。我敢肯定，那次攻击后，他肯定非常忙碌。','与虚空风暴肯瑞瓦村的管理器戴沃斯谈一谈。','<你告诉管理人关于你与大法师瓦戈斯的谈话。管理人点头>$B$B他的忧虑是正确的。在对村庄的攻击过程中，凯尔萨斯使用一种具有毁灭性的魔法破坏镇的西北部分，大多数高级魔法师所聚集的地方。$B$B现在，纯法力的生物从村庄的四周如潮水般的涌近，而在战斗中死掉之魔法师的灵魂却徘徊在他们住所的街道上。','我们早就希望遇见一个能够与大法师联系的人。大法师瓦戈斯过得如何?') ON DUPLICATE KEY UPDATE Title_loc4='肯瑞瓦村的管理器',Details_loc4='当我们明确得知远征军已经被困外域，无法返回艾泽拉斯世界的时候，肯瑞托先遣队进驻了法兰伦平原，并修筑了一座名为肯瑞瓦的村落。我将村子交给管理器戴沃斯负责，但是当凯尔萨斯和他的军队将我封印在紫罗兰之塔中后，我便彻底失去了与他的联络。$B$B$N，去肯瑞瓦村寻找他的下落，尽你所能地帮助他。我敢肯定，那次攻击后，他肯定非常忙碌。',Objectives_loc4='与虚空风暴肯瑞瓦村的管理器戴沃斯谈一谈。',OfferRewardText_loc4='<你告诉管理人关于你与大法师瓦戈斯的谈话。管理人点头>$B$B他的忧虑是正确的。在对村庄的攻击过程中，凯尔萨斯使用一种具有毁灭性的魔法破坏镇的西北部分，大多数高级魔法师所聚集的地方。$B$B现在，纯法力的生物从村庄的四周如潮水般的涌近，而在战斗中死掉之魔法师的灵魂却徘徊在他们住所的街道上。',RequestItemsText_loc4='我们早就希望遇见一个能够与大法师联系的人。大法师瓦戈斯过得如何?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10180,'无法袖手旁观','我试着劝说伊斯法尔留在这里，留在安全的沙塔斯城，可他根本听不进去，竟然决定再次孤身犯险，进入奥金顿。$B$B之前他侥幸从塞泰克大厅捡回一条命，如果这次再被俘虏，恐怕就没那么幸运了。$B$B他想营救妹妹的决心令我敬佩，但是凭他一己之力，绝无成功的希望。$B$B$N，找到伊斯法尔，和他谈谈。如果你不能劝他回来，或许你可以帮他救出拉卡？','与奥金顿塞泰克大厅入口附近的伊斯法尔谈一谈。','我本该猜到他会派你来跟踪我。他试图想要说服我回到塞泰克大厅，但是我无法和让拉卡死在那里的自己共存。','你怎么会知道在这里可以找到我?') ON DUPLICATE KEY UPDATE Title_loc4='无法袖手旁观',Details_loc4='我试着劝说伊斯法尔留在这里，留在安全的沙塔斯城，可他根本听不进去，竟然决定再次孤身犯险，进入奥金顿。$B$B之前他侥幸从塞泰克大厅捡回一条命，如果这次再被俘虏，恐怕就没那么幸运了。$B$B他想营救妹妹的决心令我敬佩，但是凭他一己之力，绝无成功的希望。$B$B$N，找到伊斯法尔，和他谈谈。如果你不能劝他回来，或许你可以帮他救出拉卡？',Objectives_loc4='与奥金顿塞泰克大厅入口附近的伊斯法尔谈一谈。',OfferRewardText_loc4='我本该猜到他会派你来跟踪我。他试图想要说服我回到塞泰克大厅，但是我无法和让拉卡死在那里的自己共存。',RequestItemsText_loc4='你怎么会知道在这里可以找到我?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText2_loc4) VALUES (10182,'战斗法师达斯利克','这柄剑材质上等，锻造工艺精湛，整体质量经过平衡，非常适合战斗法师使用。剑柄上镶嵌着肯瑞托议会的徽章，还刻着“达斯利克”的名字。$B$B在手中翻转这件武器时，你注意到金属中似乎辐射出某种异样的感觉，似乎这柄剑在两个维度中迅速地切换着。难道它竟是战斗法师达斯利克的灵魂在这个世界唯一的羁绊？$B$B或许将这柄剑放回原来的位置，就能破除这羁绊，令达斯利克的灵魂得以安息。','在巫师街内找到战斗法师达斯利克的家，将剑放回他的武器架上。然后与肯瑞瓦村的管理器戴沃斯谈一谈。','你做的很好，$N。我不再感应到达斯立克灵魂的任何骚动。我愿意付出更多以得到再一次与他对话的机会，但他最终安息了那就够了。','你找到什么了，$N?','让达斯利克的灵魂安息') ON DUPLICATE KEY UPDATE Title_loc4='战斗法师达斯利克',Details_loc4='这柄剑材质上等，锻造工艺精湛，整体质量经过平衡，非常适合战斗法师使用。剑柄上镶嵌着肯瑞托议会的徽章，还刻着“达斯利克”的名字。$B$B在手中翻转这件武器时，你注意到金属中似乎辐射出某种异样的感觉，似乎这柄剑在两个维度中迅速地切换着。难道它竟是战斗法师达斯利克的灵魂在这个世界唯一的羁绊？$B$B或许将这柄剑放回原来的位置，就能破除这羁绊，令达斯利克的灵魂得以安息。',Objectives_loc4='在巫师街内找到战斗法师达斯利克的家，将剑放回他的武器架上。然后与肯瑞瓦村的管理器戴沃斯谈一谈。',OfferRewardText_loc4='你做的很好，$N。我不再感应到达斯立克灵魂的任何骚动。我愿意付出更多以得到再一次与他对话的机会，但他最终安息了那就够了。',RequestItemsText_loc4='你找到什么了，$N?',ObjectiveText2_loc4='让达斯利克的灵魂安息';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10183,'前往52区','我在这里潜心研究伟大的虚空——以太流以及虚空中的一切。这里真是最理想的研究点，没有刺眼的灯光，也没有镇上的喧闹。这座桥挺不错的吧？要是我能把这副破望远镜修好就更棒了。$B$B嘿，朋友，如果你想找事做的话，就去52区吧！沿着路往前走，在分岔口往右转。$B$B不如顺便把我最新的研究成果带去交给火箭主管弗斯拉格？我敢肯定他有一堆事要丢给你做，他就在X
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10184,'狂暴的幽灵','村中的大多数幽灵生前都是肯瑞托的法师。他们丧失了往昔的记忆，带着沉重的怨念游荡在废墟中。$B$B但是，最开始的时候并不是这样的。那场袭击后，灵魂们只是显得不太安分而已，远没有像现在这样充满敌意。时间一久，他们却变得越来越暴戾。我已经不敢靠近村子的南部了，他们恐怕连我都不会放过。请你净化法师们愤怒的灵魂，让他们平静下来吧。','肯瑞瓦村的管理器戴沃斯要求你去肯瑞瓦村广场消灭20个被杀死的幽魂。','<管理器戴沃斯温和的摇摇他的头。>$B$B这不是他们应得的，但却是我们能做的。','它让我痛到了解能为我们的同胞做的太少了。') ON DUPLICATE KEY UPDATE Title_loc4='狂暴的幽灵',Details_loc4='村中的大多数幽灵生前都是肯瑞托的法师。他们丧失了往昔的记忆，带着沉重的怨念游荡在废墟中。$B$B但是，最开始的时候并不是这样的。那场袭击后，灵魂们只是显得不太安分而已，远没有像现在这样充满敌意。时间一久，他们却变得越来越暴戾。我已经不敢靠近村子的南部了，他们恐怕连我都不会放过。请你净化法师们愤怒的灵魂，让他们平静下来吧。',Objectives_loc4='肯瑞瓦村的管理器戴沃斯要求你去肯瑞瓦村广场消灭20个被杀死的幽魂。',OfferRewardText_loc4='<管理器戴沃斯温和的摇摇他的头。>$B$B这不是他们应得的，但却是我们能做的。',RequestItemsText_loc4='它让我痛到了解能为我们的同胞做的太少了。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10185,'悲惨的命运','血精灵将肯瑞瓦村夷为平地后，便在西北方建起了一座高大的建筑物。没有大法师的知识，我们也无从得知那座建筑物的用途。$B$B不过，有点事倒是明摆着：血精灵的活动导致饥饿的法力生物如潮水般涌入村落。它们似乎对巫师街特别感兴趣，不断亵渎着法师们的遗物。我们必须制止这群法力生物。','杀死10个法师杀手和10个法力搜寻者，然后向肯瑞瓦村的管理器戴沃斯复命。','<管理器看起来很沮丧。>$B$B我几乎可以预见从地平线涌出的下一波。除掉他们暂且是可行，但仍需要长久的评估。','你有设法解决一些村庄废墟里的法力生物吗?') ON DUPLICATE KEY UPDATE Title_loc4='悲惨的命运',Details_loc4='血精灵将肯瑞瓦村夷为平地后，便在西北方建起了一座高大的建筑物。没有大法师的知识，我们也无从得知那座建筑物的用途。$B$B不过，有点事倒是明摆着：血精灵的活动导致饥饿的法力生物如潮水般涌入村落。它们似乎对巫师街特别感兴趣，不断亵渎着法师们的遗物。我们必须制止这群法力生物。',Objectives_loc4='杀死10个法师杀手和10个法力搜寻者，然后向肯瑞瓦村的管理器戴沃斯复命。',OfferRewardText_loc4='<管理器看起来很沮丧。>$B$B我几乎可以预见从地平线涌出的下一波。除掉他们暂且是可行，但仍需要长久的评估。',RequestItemsText_loc4='你有设法解决一些村庄废墟里的法力生物吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10186,'你被雇了！','就让我成为第一个欢迎你到来的人吧，三等见习技师$N！$B$B我们正忙于一项伟大的工程——虚空火箭X-52！$B$B不过，首先我们得准备好零件和燃料，这就是你要做的事。$B$B我需要水晶——注意，是大量的水晶，我要利用这些水晶构造火箭的以太锂引擎矩阵。德莱尼人那里到处都是水晶！$B$B你可以在北边的恩卡特废墟搞到水晶！当心那些德莱尼幽灵。','将10块以太锂矩阵水晶交给虚空风暴52区的火箭主管弗斯拉格。','哇!看起来很劣质呢。也许我们可以将它们使用在第三引擎歧管?$B$B尽管如此，做的好，资浅技师第三级!你很快就可以变成资浅技师第二级了。','X-52虚空火箭看起来像是准备好可以发射了吗?我是为了我驾驶座的舒适而漫行虚空的吗?开发陌生的新世界?寻找新科技及商机?勇敢的去那些没有哥布尔去过的地方?$B$B不是的!$B$B因此，我希望你能有我给你之后的那些水晶。') ON DUPLICATE KEY UPDATE Title_loc4='你被雇了！',Details_loc4='就让我成为第一个欢迎你到来的人吧，三等见习技师$N！$B$B我们正忙于一项伟大的工程——虚空火箭X-52！$B$B不过，首先我们得准备好零件和燃料，这就是你要做的事。$B$B我需要水晶——注意，是大量的水晶，我要利用这些水晶构造火箭的以太锂引擎矩阵。德莱尼人那里到处都是水晶！$B$B你可以在北边的恩卡特废墟搞到水晶！当心那些德莱尼幽灵。',Objectives_loc4='将10块以太锂矩阵水晶交给虚空风暴52区的火箭主管弗斯拉格。',OfferRewardText_loc4='哇!看起来很劣质呢。也许我们可以将它们使用在第三引擎歧管?$B$B尽管如此，做的好，资浅技师第三级!你很快就可以变成资浅技师第二级了。',RequestItemsText_loc4='X-52虚空火箭看起来像是准备好可以发射了吗?我是为了我驾驶座的舒适而漫行虚空的吗?开发陌生的新世界?寻找新科技及商机?勇敢的去那些没有哥布尔去过的地方?$B$B不是的!$B$B因此，我希望你能有我给你之后的那些水晶。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10187,'给大法师的消息','尽管局势举步维艰，但你的到来还是令我们振奋不已，这意味着大法师并没有忘记村子的困境。$B$B<管理器抬头望了望远处的高塔。>$B$B这听起来很荒谬，对吧？有的时候，一面石墙就能将我们隔绝。魔法壁障实在是太容易被忽视了。$B$B如果你愿意的话，请进入塔内告知大法师瓦格斯，我们正在努力恢复肯瑞瓦村的原貌，很快就能制定出计划，将这些法力生物逐出村落。','与虚空风暴紫罗兰之塔塔顶的大法师瓦格斯谈一谈。','<你描述在下面那个废墟的经过以及传达管理器的讯息。>$B$B那真是个好消息。由于你的持续帮忙及一点小运气，我希望不久之后能够加入他们。我们最后一定能够向凯尔萨斯复仇的。','你跟管理器戴沃斯谈过了吗?') ON DUPLICATE KEY UPDATE Title_loc4='给大法师的消息',Details_loc4='尽管局势举步维艰，但你的到来还是令我们振奋不已，这意味着大法师并没有忘记村子的困境。$B$B<管理器抬头望了望远处的高塔。>$B$B这听起来很荒谬，对吧？有的时候，一面石墙就能将我们隔绝。魔法壁障实在是太容易被忽视了。$B$B如果你愿意的话，请进入塔内告知大法师瓦格斯，我们正在努力恢复肯瑞瓦村的原貌，很快就能制定出计划，将这些法力生物逐出村落。',Objectives_loc4='与虚空风暴紫罗兰之塔塔顶的大法师瓦格斯谈一谈。',OfferRewardText_loc4='<你描述在下面那个废墟的经过以及传达管理器的讯息。>$B$B那真是个好消息。由于你的持续帮忙及一点小运气，我希望不久之后能够加入他们。我们最后一定能够向凯尔萨斯复仇的。',RequestItemsText_loc4='你跟管理器戴沃斯谈过了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10188,'克拉苏斯的魔符','多年前，在我们离开艾泽拉斯世界之前，肯瑞托议会曾授予远征军一件威力强大的神器——克拉苏斯的魔符。在我们与兽人的战争中，它的存在就是我们胜利的保障；事实上，这枚魔符还能破除禁锢我的妖术。$B$B但是，凯尔萨斯夺走了我全部的财产，并将魔符交给留驻此地的缚法者玛亚纳保管。玛亚纳若是意识到这件神器的力量，肯定不会心甘情愿地拱手相让。','前往紫罗兰之塔西北方的法力熔炉：库鲁恩，从缚法者玛亚纳手中夺得克拉苏斯的魔符。','阿，它就像我记得的那样尊贵。你感觉不到从它身上发出的力量吗?$B$B当然，还有很多事要做，但关于符印的交还，你拥有我最深刻的感谢。','如果我要解开这座塔的诅咒，我就必须有那个符印。') ON DUPLICATE KEY UPDATE Title_loc4='克拉苏斯的魔符',Details_loc4='多年前，在我们离开艾泽拉斯世界之前，肯瑞托议会曾授予远征军一件威力强大的神器——克拉苏斯的魔符。在我们与兽人的战争中，它的存在就是我们胜利的保障；事实上，这枚魔符还能破除禁锢我的妖术。$B$B但是，凯尔萨斯夺走了我全部的财产，并将魔符交给留驻此地的缚法者玛亚纳保管。玛亚纳若是意识到这件神器的力量，肯定不会心甘情愿地拱手相让。',Objectives_loc4='前往紫罗兰之塔西北方的法力熔炉：库鲁恩，从缚法者玛亚纳手中夺得克拉苏斯的魔符。',OfferRewardText_loc4='阿，它就像我记得的那样尊贵。你感觉不到从它身上发出的力量吗?$B$B当然，还有很多事要做，但关于符印的交还，你拥有我最深刻的感谢。',RequestItemsText_loc4='如果我要解开这座塔的诅咒，我就必须有那个符印。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10189,'法力熔炉：布纳尔','在来52区的路上，你大概已经发现了一座法力熔炉。那座巨大的紫色建筑物正源源不断地汲取着能量，想起来了吗？$B$B我们奉沙塔尔之命来这儿调查敌情。如果能搞到人员名册就好了。那上面记载着法力熔炉驻军的身份以及他们的计划，都是非常宝贵的信息。$B$B阿拉森上尉率领着一支弩炮队驻扎在法力熔炉：布纳尔外，他手中必定有一本名册。替我们取回布纳尔人员名册。','52区的间谍大师萨罗迪恩要你从法力熔炉：布纳尔外的阿拉森上尉手中夺得布纳尔人员名册。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。','好极了!有了这份名单我们在瞄准法力熔炉那些凯尔的部下时就可以做出适合的决定。$B$B真糟糕，我开始爱上随意杀掉他的仆从这件事。','你拿到我要你去拿的东西了吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='法力熔炉：布纳尔',Details_loc4='在来52区的路上，你大概已经发现了一座法力熔炉。那座巨大的紫色建筑物正源源不断地汲取着能量，想起来了吗？$B$B我们奉沙塔尔之命来这儿调查敌情。如果能搞到人员名册就好了。那上面记载着法力熔炉驻军的身份以及他们的计划，都是非常宝贵的信息。$B$B阿拉森上尉率领着一支弩炮队驻扎在法力熔炉：布纳尔外，他手中必定有一本名册。替我们取回布纳尔人员名册。',Objectives_loc4='52区的间谍大师萨罗迪恩要你从法力熔炉：布纳尔外的阿拉森上尉手中夺得布纳尔人员名册。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。',OfferRewardText_loc4='好极了!有了这份名单我们在瞄准法力熔炉那些凯尔的部下时就可以做出适合的决定。$B$B真糟糕，我开始爱上随意杀掉他的仆从这件事。',RequestItemsText_loc4='你拿到我要你去拿的东西了吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4) VALUES (10190,'电池充电','我肩负着从废墟中收集机械零件的重要任务，眼下却遭遇了电能不足的麻烦事。$B$B相位猎手——就是那些长得像法力浮龙的生物——体内充满了能量！它们漂浮在虚空中，在这座岛的边缘地带就能找到相位猎手。$B$B将电池装在充能器上，对着虚弱的相位猎手使用充能器，吸满电能后关闭它就行了。','对相位猎手使用电池充能器，直到电池充能等级到达10。然后将它交给虚空风暴恩卡特废墟的机器人专家艾蕾。','嘿，小心你用那个指到的东西!你已经把它的功能设定成“杀”!!!看起来你已经把电池充满电，其它的也是。这样我的机器人就可以继续运作，你帮了我一个大忙。','你已经将电池充满电了吗?','电池充能等级') ON DUPLICATE KEY UPDATE Title_loc4='电池充电',Details_loc4='我肩负着从废墟中收集机械零件的重要任务，眼下却遭遇了电能不足的麻烦事。$B$B相位猎手——就是那些长得像法力浮龙的生物——体内充满了能量！它们漂浮在虚空中，在这座岛的边缘地带就能找到相位猎手。$B$B将电池装在充能器上，对着虚弱的相位猎手使用充能器，吸满电能后关闭它就行了。',Objectives_loc4='对相位猎手使用电池充能器，直到电池充能等级到达10。然后将它交给虚空风暴恩卡特废墟的机器人专家艾蕾。',OfferRewardText_loc4='嘿，小心你用那个指到的东西!你已经把它的功能设定成“杀”!!!看起来你已经把电池充满电，其它的也是。这样我的机器人就可以继续运作，你帮了我一个大忙。',RequestItemsText_loc4='你已经将电池充满电了吗?',ObjectiveText1_loc4='电池充能等级';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,EndText_loc4) VALUES (10191,'麦克斯米林V型活了！','你好，$r。充能完毕，我的各项机能已全面恢复。$B$B这片废墟中散落着许多脆弱的德莱尼机械装置，我需要将它们回收。我腕部的伸缩装置配有精细的机械臂，以及最新型的可燃及助燃气体吸收泵，可以妥当地处理那些脆弱的装置。$B$B但是，盘踞在废墟中的幽灵很可能会攻击我，因此我需要你和你的朋友陪我一起进去，保护我的安全。','护送麦克斯米林V型穿越恩卡特废墟并返回安全地带，然后与虚空风暴恩卡特废墟外的机器人专家艾蕾谈一谈。','你做到了!你做到了!我要亲你!$B$B喔，该死……马克斯A型机器人五号又要没电了。阿还好，它还够维持到完成这个工作，那才是最重要!$B$B火箭主管夫斯拉吉会很乐意将这些德莱尼机械吊挂在X-52虚空火箭里的!那表示是对我的升等!我好开心阿，我一定要给你奖励!$B$B来，从这些里面挑一个吧。','这么快就回来了?$B$B马克斯A型机器人五号还好吗?!','护送麦克斯米林V型穿越恩卡特废墟') ON DUPLICATE KEY UPDATE Title_loc4='麦克斯米林V型活了！',Details_loc4='你好，$r。充能完毕，我的各项机能已全面恢复。$B$B这片废墟中散落着许多脆弱的德莱尼机械装置，我需要将它们回收。我腕部的伸缩装置配有精细的机械臂，以及最新型的可燃及助燃气体吸收泵，可以妥当地处理那些脆弱的装置。$B$B但是，盘踞在废墟中的幽灵很可能会攻击我，因此我需要你和你的朋友陪我一起进去，保护我的安全。',Objectives_loc4='护送麦克斯米林V型穿越恩卡特废墟并返回安全地带，然后与虚空风暴恩卡特废墟外的机器人专家艾蕾谈一谈。',OfferRewardText_loc4='你做到了!你做到了!我要亲你!$B$B喔，该死……马克斯A型机器人五号又要没电了。阿还好，它还够维持到完成这个工作，那才是最重要!$B$B火箭主管夫斯拉吉会很乐意将这些德莱尼机械吊挂在X-52虚空火箭里的!那表示是对我的升等!我好开心阿，我一定要给你奖励!$B$B来，从这些里面挑一个吧。',RequestItemsText_loc4='这么快就回来了?$B$B马克斯A型机器人五号还好吗?!',EndText_loc4='护送麦克斯米林V型穿越恩卡特废墟';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10192,'克拉苏斯的魔法纲要','肯瑞托议会将另一件克拉苏斯的物品也授予了远征军，就是那本名叫《克拉苏斯的魔法纲要》的法术书。书中记载了克拉苏斯掌握的全部法术，这本魔法纲要曾在战争中为我们赢得了巨大的优势。$B$B不过，在凯尔萨斯和他的军队攻陷肯瑞瓦村之前，一个试图修习通灵术的学徒偷走了《克拉苏斯的魔法纲要》。他和他的党羽为了掩人耳目，将纲要分成了数份，各自保存在他们位于镇子南部的家中。','前往肯瑞瓦村的城镇广场，收集克拉苏斯的魔法纲要 - 第一章，克拉苏斯的魔法纲要 - 第二章和克拉苏斯的魔法纲要 - 第三章。','<大法师瓦戈斯的影像看来像在检查这本手册。>$B$B表皮有点受损，但想想它遭遇过的事，能够保存着真是个奇迹。护送它，$N。没了这本书，我们打破塔的防御的机率就变小了。','你把书带来了吗?') ON DUPLICATE KEY UPDATE Title_loc4='克拉苏斯的魔法纲要',Details_loc4='肯瑞托议会将另一件克拉苏斯的物品也授予了远征军，就是那本名叫《克拉苏斯的魔法纲要》的法术书。书中记载了克拉苏斯掌握的全部法术，这本魔法纲要曾在战争中为我们赢得了巨大的优势。$B$B不过，在凯尔萨斯和他的军队攻陷肯瑞瓦村之前，一个试图修习通灵术的学徒偷走了《克拉苏斯的魔法纲要》。他和他的党羽为了掩人耳目，将纲要分成了数份，各自保存在他们位于镇子南部的家中。',Objectives_loc4='前往肯瑞瓦村的城镇广场，收集克拉苏斯的魔法纲要 - 第一章，克拉苏斯的魔法纲要 - 第二章和克拉苏斯的魔法纲要 - 第三章。',OfferRewardText_loc4='<大法师瓦戈斯的影像看来像在检查这本手册。>$B$B表皮有点受损，但想想它遭遇过的事，能够保存着真是个奇迹。护送它，$N。没了这本书，我们打破塔的防御的机率就变小了。',RequestItemsText_loc4='你把书带来了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10193,'有价值的目标','根据名册记载的信息来看，空间主宰和迁跃技师操纵着法力熔炉。他们负责从法力熔炉中提取一种名叫“迁跃能量”的物质，然后通过地下管道系统输送到别的地方。$B$B除空间主宰和迁跃技师外，凯尔还在法力熔炉派驻了若干名地质学家。剩下的驻军就是普通的士兵和魔导师了，应该很容易对付。$B$B进入法力熔炉：布纳尔，杀掉凯尔麾下的走狗；这必定会大大削弱他的势力。','52区的间谍大师萨罗迪恩要你进入法力熔炉：布纳尔，杀死2名日怒空间主宰、6名日怒迁跃技师和8名日怒地质学家。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。','你是个可靠的 $g家伙:小姑娘;，$N。如果还有比我杀掉凯尔萨斯的走狗更让我高兴的事，那就是找其它人来替我下手。$B$B这方法可以让我少沾点血腥。','进行的怎样，$N?有任何消息吗?你最近为我做了什么?') ON DUPLICATE KEY UPDATE Title_loc4='有价值的目标',Details_loc4='根据名册记载的信息来看，空间主宰和迁跃技师操纵着法力熔炉。他们负责从法力熔炉中提取一种名叫“迁跃能量”的物质，然后通过地下管道系统输送到别的地方。$B$B除空间主宰和迁跃技师外，凯尔还在法力熔炉派驻了若干名地质学家。剩下的驻军就是普通的士兵和魔导师了，应该很容易对付。$B$B进入法力熔炉：布纳尔，杀掉凯尔麾下的走狗；这必定会大大削弱他的势力。',Objectives_loc4='52区的间谍大师萨罗迪恩要你进入法力熔炉：布纳尔，杀死2名日怒空间主宰、6名日怒迁跃技师和8名日怒地质学家。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。',OfferRewardText_loc4='你是个可靠的 $g家伙:小姑娘;，$N。如果还有比我杀掉凯尔萨斯的走狗更让我高兴的事，那就是找其它人来替我下手。$B$B这方法可以让我少沾点血腥。',RequestItemsText_loc4='进行的怎样，$N?有任何消息吗?你最近为我做了什么?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10194,'隐秘飞行','你外出执行任务时，我们又发现了一座法力熔炉。它位于此地以东，被称为法力熔炉：库鲁恩。$B$B我手下最出色的两名密探已经在这座法力熔炉外设立了秘密的着陆点。请你协助他们潜入敌军内部，窃取一切有用的信息。$B$B到52区外面去找维罗妮娅，她会备好一头双足飞龙，载你前往法力熔炉：库鲁恩。着陆后跟卡勒迪斯·晨光谈谈，他会为你安排任务的。','与52区外的维罗妮娅谈一谈，她会安排你飞往法力熔炉：库鲁恩。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。','帮你付的机票钱可不便宜。希望你有足够的能耐完成工作。') ON DUPLICATE KEY UPDATE Title_loc4='隐秘飞行',Details_loc4='你外出执行任务时，我们又发现了一座法力熔炉。它位于此地以东，被称为法力熔炉：库鲁恩。$B$B我手下最出色的两名密探已经在这座法力熔炉外设立了秘密的着陆点。请你协助他们潜入敌军内部，窃取一切有用的信息。$B$B到52区外面去找维罗妮娅，她会备好一头双足飞龙，载你前往法力熔炉：库鲁恩。着陆后跟卡勒迪斯·晨光谈谈，他会为你安排任务的。',Objectives_loc4='与52区外的维罗妮娅谈一谈，她会安排你飞往法力熔炉：库鲁恩。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。',OfferRewardText_loc4='帮你付的机票钱可不便宜。希望你有足够的能耐完成工作。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10195,'流行时尚','自从我用你带回来的羽毛为波尔泰姆制作了一顶帽子之后，包括山德在内的其它所有雇佣兵都嚷嚷着说也想要一顶。于是我只好告诉他们说马上就为他们制作帽子，不过，我需要有人为我稳定地供应鸦人羽毛。$B$B如果你能将在森林冒险中收集到的羽毛都给我，我会非常感激你的。','给奥蕾莉亚要塞的洛瑟蕾丝带回30片鸦人的羽毛。','这些真是太棒了!要是你最近看到一大群男人带着这个羽毛帽走来走去可别被吓到了喔!','自从你带了第一批羽毛让我完成伯特泰欧的帽子，其它所有的佣兵吵着他们也要，包括萨德尔。我告诉他们我已经在进行了，但我需要替这个计划找到一个提供阿拉卡羽毛的稳定货源。$B$B我会很乐意接受你在森林探险中收集的任何阿拉卡羽毛。') ON DUPLICATE KEY UPDATE Title_loc4='流行时尚',Details_loc4='自从我用你带回来的羽毛为波尔泰姆制作了一顶帽子之后，包括山德在内的其它所有雇佣兵都嚷嚷着说也想要一顶。于是我只好告诉他们说马上就为他们制作帽子，不过，我需要有人为我稳定地供应鸦人羽毛。$B$B如果你能将在森林冒险中收集到的羽毛都给我，我会非常感激你的。',Objectives_loc4='给奥蕾莉亚要塞的洛瑟蕾丝带回30片鸦人的羽毛。',OfferRewardText_loc4='这些真是太棒了!要是你最近看到一大群男人带着这个羽毛帽走来走去可别被吓到了喔!',RequestItemsText_loc4='自从你带了第一批羽毛让我完成伯特泰欧的帽子，其它所有的佣兵吵着他们也要，包括萨德尔。我告诉他们我已经在进行了，但我需要替这个计划找到一个提供阿拉卡羽毛的稳定货源。$B$B我会很乐意接受你在森林探险中收集的任何阿拉卡羽毛。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10196,'更多鸦人羽毛','尽管我成功地将鸦人的灵魂吸引到了我的身边，但它们太容易受到惊吓了，一接触就逃跑了。或许我伪装得更好点，它们就会被迷惑得更深，可以长时间靠近我。$B$B你再去搞羽毛吧，我需要更多你先前给我搞来的那些羽毛。如果你能再给我带回来一些，我会很感激你的。','将30片鸦人的羽毛交给裂石堡的玛鲁卡兹。','谢谢你，$N。我会好好使用它们的。','我很成功的引来了阿拉卡的灵魂到我身边，但他们仍然很害羞。也许如果我改变我的打扮，他们会更愿意在催眠状态下接近我。$B$B虽然，为了这样，我需要更多像你带来给我的这种羽毛。如果你有更多这种羽毛的话，我会很乐意从你手中接过来的。') ON DUPLICATE KEY UPDATE Title_loc4='更多鸦人羽毛',Details_loc4='尽管我成功地将鸦人的灵魂吸引到了我的身边，但它们太容易受到惊吓了，一接触就逃跑了。或许我伪装得更好点，它们就会被迷惑得更深，可以长时间靠近我。$B$B你再去搞羽毛吧，我需要更多你先前给我搞来的那些羽毛。如果你能再给我带回来一些，我会很感激你的。',Objectives_loc4='将30片鸦人的羽毛交给裂石堡的玛鲁卡兹。',OfferRewardText_loc4='谢谢你，$N。我会好好使用它们的。',RequestItemsText_loc4='我很成功的引来了阿拉卡的灵魂到我身边，但他们仍然很害羞。也许如果我改变我的打扮，他们会更愿意在催眠状态下接近我。$B$B虽然，为了这样，我需要更多像你带来给我的这种羽毛。如果你有更多这种羽毛的话，我会很乐意从你手中接过来的。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10197,'以假乱真','潜入凯尔军中可不是件容易的事。我可以运用幻象术将你伪装成凯尔的追随者，不过我没法模仿这帮家伙制服上的小细节，那样的话，伪装就很可能被识破。$B$B将一件日怒长袍、一副日怒手套和一枚日怒卫士勋章带回来给我，这样就能让我的幻象术效果更加逼真。','收集一件日怒奥术师长袍、一副日怒研究员手套和一枚日怒卫士勋章，然后返回虚空风暴的法力熔炉：库鲁恩，将它们交给卡勒迪斯·晨光。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。','太好了!当我完成你的伪装，你就可以混入日怒军队而不被发现了。','你有拿到我要的那些东西吗?') ON DUPLICATE KEY UPDATE Title_loc4='以假乱真',Details_loc4='潜入凯尔军中可不是件容易的事。我可以运用幻象术将你伪装成凯尔的追随者，不过我没法模仿这帮家伙制服上的小细节，那样的话，伪装就很可能被识破。$B$B将一件日怒长袍、一副日怒手套和一枚日怒卫士勋章带回来给我，这样就能让我的幻象术效果更加逼真。',Objectives_loc4='收集一件日怒奥术师长袍、一副日怒研究员手套和一枚日怒卫士勋章，然后返回虚空风暴的法力熔炉：库鲁恩，将它们交给卡勒迪斯·晨光。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。',OfferRewardText_loc4='太好了!当我完成你的伪装，你就可以混入日怒军队而不被发现了。',RequestItemsText_loc4='你有拿到我要的那些东西吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,EndText_loc4) VALUES (10198,'收集情报','我利用你取回的东西做了件日怒制服，并对它施放了幻象术。$B$B几分钟前，指挥官纳萨托·晨铸来到法力熔炉：库鲁恩，准备与奥术师阿尔杜尼斯会面。纳萨托随身带着一帮护卫，他们必定是准备商谈要事。潜入日怒军营，看看能不能探得这次会面的详情。$B$B啊，差点忘了。你最好离奥术傀儡远些，它们在法力熔炉中巡逻，可以看穿伪装上的幻象术。','利用日怒伪装包进入法力熔炉：库鲁恩，偷听指挥官纳萨托·晨铸和奥术师阿尔杜尼斯的谈话。完成任务后向法力熔炉：库鲁恩的卡勒迪斯·晨光复命。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。','法力熔炉杜罗有困难?我相信间谍大师萨洛迪恩会很想听到这个消息。我们先专注在这里的工作吧。','窃听的如何阿，$N?你最好快一点。我已经开始坐立不安了。','收集情报') ON DUPLICATE KEY UPDATE Title_loc4='收集情报',Details_loc4='我利用你取回的东西做了件日怒制服，并对它施放了幻象术。$B$B几分钟前，指挥官纳萨托·晨铸来到法力熔炉：库鲁恩，准备与奥术师阿尔杜尼斯会面。纳萨托随身带着一帮护卫，他们必定是准备商谈要事。潜入日怒军营，看看能不能探得这次会面的详情。$B$B啊，差点忘了。你最好离奥术傀儡远些，它们在法力熔炉中巡逻，可以看穿伪装上的幻象术。',Objectives_loc4='利用日怒伪装包进入法力熔炉：库鲁恩，偷听指挥官纳萨托·晨铸和奥术师阿尔杜尼斯的谈话。完成任务后向法力熔炉：库鲁恩的卡勒迪斯·晨光复命。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。',OfferRewardText_loc4='法力熔炉杜罗有困难?我相信间谍大师萨洛迪恩会很想听到这个消息。我们先专注在这里的工作吧。',RequestItemsText_loc4='窃听的如何阿，$N?你最好快一点。我已经开始坐立不安了。',EndText_loc4='收集情报';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10199,'一点添加剂','眼下只缺最后一种原料了，它可以让这瓶混合物发挥额外的效力。$B$B瞧见那些在岩肤劫掠者旁边游荡的虚空鳐了吗？它们的钉刺就再好不过了。替我收集一些虚空鳐的钉刺，我就能分解出其中的毒液！$B$B只要在混合物中加入这种毒液，效果肯定好得很！','将5根虚空鳐的钉刺交给虚空风暴52区的布兹。','哇噢!好极了，现在我们正在讨论呢!$B$B就让我拿着这些小美人们将不好的东西挤出来。这实在该做成一桶火箭燃料酒将大家狠狠的击飞!$B$B来，就让我将页岩油及这个刺毒混在一起，看看会发生什么事……','如果我能从这些虚空鳍刺萃取出足够的毒液，我想我们会拥有有史以来最具爆炸性的燃料!') ON DUPLICATE KEY UPDATE Title_loc4='一点添加剂',Details_loc4='眼下只缺最后一种原料了，它可以让这瓶混合物发挥额外的效力。$B$B瞧见那些在岩肤劫掠者旁边游荡的虚空鳐了吗？它们的钉刺就再好不过了。替我收集一些虚空鳐的钉刺，我就能分解出其中的毒液！$B$B只要在混合物中加入这种毒液，效果肯定好得很！',Objectives_loc4='将5根虚空鳐的钉刺交给虚空风暴52区的布兹。',OfferRewardText_loc4='哇噢!好极了，现在我们正在讨论呢!$B$B就让我拿着这些小美人们将不好的东西挤出来。这实在该做成一桶火箭燃料酒将大家狠狠的击飞!$B$B来，就让我将页岩油及这个刺毒混在一起，看看会发生什么事……',RequestItemsText_loc4='如果我能从这些虚空鳍刺萃取出足够的毒液，我想我们会拥有有史以来最具爆炸性的燃料!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10200,'返回萨罗迪恩身边','最好立即把这消息告诉萨罗迪恩，我会留下来毁掉我们曾在这儿活动的证据。$B$B如果凯尔发现我们的踪迹就完蛋了。我们窃听秘密的行动还是不要让敌人发觉比较好。','返回虚空风暴的52区，向间谍大师萨罗迪恩复命。','你一直都令我惊讶，$N。那真是你在揭露法力熔炉寇鲁这项秘密行动中莫大的功绩。') ON DUPLICATE KEY UPDATE Title_loc4='返回萨罗迪恩身边',Details_loc4='最好立即把这消息告诉萨罗迪恩，我会留下来毁掉我们曾在这儿活动的证据。$B$B如果凯尔发现我们的踪迹就完蛋了。我们窃听秘密的行动还是不要让敌人发觉比较好。',Objectives_loc4='返回虚空风暴的52区，向间谍大师萨罗迪恩复命。',OfferRewardText_loc4='你一直都令我惊讶，$N。那真是你在揭露法力熔炉寇鲁这项秘密行动中莫大的功绩。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4) VALUES (10201,'真相大白','这些油总算准备好了，现在我们马上准备开始进行第一次试验。这种油质量很重，看起来是一种非常好的的武器油。$B$B不过，要真正验证这一点，还是得靠专家。看到那边通缉公告旁边站着的葛雷克了吗？噢，好吧，他虽然不是一个耍笔杆子的普通“专家”，但所有的兽人都知道他耍枪的本事！$B$B将这个油的样本带去给他，让他用他的枪去试试。等他试验完之后，告诉我他觉得这个油怎么样。','找到葛雷克，让他用枪试试油的品质。试验完成之后，向拉克妮亚报告结果。','<你告诉瑞蔻莉雅测试的结果然后她仰头，大笑。>','那么，你有测试的结果了吗?','让葛雷克测试奥雷巴油') ON DUPLICATE KEY UPDATE Title_loc4='真相大白',Details_loc4='这些油总算准备好了，现在我们马上准备开始进行第一次试验。这种油质量很重，看起来是一种非常好的的武器油。$B$B不过，要真正验证这一点，还是得靠专家。看到那边通缉公告旁边站着的葛雷克了吗？噢，好吧，他虽然不是一个耍笔杆子的普通“专家”，但所有的兽人都知道他耍枪的本事！$B$B将这个油的样本带去给他，让他用他的枪去试试。等他试验完之后，告诉我他觉得这个油怎么样。',Objectives_loc4='找到葛雷克，让他用枪试试油的品质。试验完成之后，向拉克妮亚报告结果。',OfferRewardText_loc4='<你告诉瑞蔻莉雅测试的结果然后她仰头，大笑。>',RequestItemsText_loc4='那么，你有测试的结果了吗?',ObjectiveText1_loc4='让葛雷克测试奥雷巴油';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10202,'叛徒','有位日怒魔导师最近频频与我们联系，称自己想要背叛凯尔投靠占星者，并说他掌握着对我们有利的重要信息。我们调查过此人的底细，确定他不是凯尔派来的卧底，便接纳了他的诚意。$B$B他暂时还呆在法力熔炉：艾拉，因此我们之间的交流变得极其困难。跟他谈谈，看看他都知道些什么内幕消息。就算他提供的信息只有他吹嘘的一半重要，我们也可以利用他办事。','前往法力熔炉：艾拉，与魔导师塞雷杜恩谈一谈。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。','该是你上场的时候了。我开始怀疑占星者是不是真的感兴趣。') ON DUPLICATE KEY UPDATE Title_loc4='叛徒',Details_loc4='有位日怒魔导师最近频频与我们联系，称自己想要背叛凯尔投靠占星者，并说他掌握着对我们有利的重要信息。我们调查过此人的底细，确定他不是凯尔派来的卧底，便接纳了他的诚意。$B$B他暂时还呆在法力熔炉：艾拉，因此我们之间的交流变得极其困难。跟他谈谈，看看他都知道些什么内幕消息。就算他提供的信息只有他吹嘘的一半重要，我们也可以利用他办事。',Objectives_loc4='前往法力熔炉：艾拉，与魔导师塞雷杜恩谈一谈。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。',OfferRewardText_loc4='该是你上场的时候了。我开始怀疑占星者是不是真的感兴趣。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4,ObjectiveText2_loc4,ObjectiveText3_loc4,ObjectiveText4_loc4) VALUES (10203,'价值连城的设备','看见横贯52区的裂隙了吗？是我们干的！嘿嘿！<傻笑声>$B$B我们把所有的资源都用来建造虚空火箭X-52了，结果眼下出现了设备短缺的窘境。$B$B在燃烧军团进驻东南方的阿尔科隆废墟之前，我们一直在那里进行采集作业，我要你前往废墟，利用超级拆解器带回散落在废墟中的设备，把它们交给裂隙东端的首席工兵布拉斯特菲兹。$B$B三等见习技师$N，这可是你晋升的好机会，千万别放过！','利用超级拆解器将高转速挖掘器、机械气压挖掘爪、多光谱地形扫描仪和一大车炸药带回52区。然后向虚空风暴52区裂隙东端的首席工兵布拉斯特菲兹报到。','你一定就是那个从废墟中把所有损坏的设备都传回我们这里的人!为你喝采!$B$B我已经重新将这些设备配置到我们其它的地点。现在我们就能够藉由一项重要的命令来加速我们在这整个岛的裂缝作用!虚空火箭要马上完成!$B$B呃呃，那是之后的事。等等，你说你传了4个回来给我们吗?我只收到3个……','这地方是不是很棒阿?而且每天都生产出崭新且奇特的东西!$B$B真是幸运，我们差点在探钻下来时毁了这座城镇。','回收高转速挖掘器','回收机械气压挖掘爪','回收多光谱地形扫描仪','回收一大车炸药') ON DUPLICATE KEY UPDATE Title_loc4='价值连城的设备',Details_loc4='看见横贯52区的裂隙了吗？是我们干的！嘿嘿！<傻笑声>$B$B我们把所有的资源都用来建造虚空火箭X-52了，结果眼下出现了设备短缺的窘境。$B$B在燃烧军团进驻东南方的阿尔科隆废墟之前，我们一直在那里进行采集作业，我要你前往废墟，利用超级拆解器带回散落在废墟中的设备，把它们交给裂隙东端的首席工兵布拉斯特菲兹。$B$B三等见习技师$N，这可是你晋升的好机会，千万别放过！',Objectives_loc4='利用超级拆解器将高转速挖掘器、机械气压挖掘爪、多光谱地形扫描仪和一大车炸药带回52区。然后向虚空风暴52区裂隙东端的首席工兵布拉斯特菲兹报到。',OfferRewardText_loc4='你一定就是那个从废墟中把所有损坏的设备都传回我们这里的人!为你喝采!$B$B我已经重新将这些设备配置到我们其它的地点。现在我们就能够藉由一项重要的命令来加速我们在这整个岛的裂缝作用!虚空火箭要马上完成!$B$B呃呃，那是之后的事。等等，你说你传了4个回来给我们吗?我只收到3个……',RequestItemsText_loc4='这地方是不是很棒阿?而且每天都生产出崭新且奇特的东西!$B$B真是幸运，我们差点在探钻下来时毁了这座城镇。',ObjectiveText1_loc4='回收高转速挖掘器',ObjectiveText2_loc4='回收机械气压挖掘爪',ObjectiveText3_loc4='回收多光谱地形扫描仪',ObjectiveText4_loc4='回收一大车炸药';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,EndText_loc4) VALUES (10204,'血宝石','凯尔的魔导师已将法力熔炉使用得炉火纯青，瞬间就能汲取到大量能量。$B$B他们利用小块的血宝石碎片，从巨大的血宝石水晶中源源不断地抽取能量。$B$B前往法力熔炉：布纳尔，从日怒魔导师手中夺得一块碎片，然后用这块碎片汲取大块水晶的能量。$B$B完成任务后回到我这儿来，让我研究能量光环的效果。别担心，它所引发的任何副作用都只是暂时的。','魔导师拉恩娜要你进入法力熔炉：布纳尔，从日怒魔导师手中夺得血宝石碎片。在较大的血宝石水晶附近使用这块碎片，然后返回52区向她复命。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。','嗯嗯……就如同我想得一样。$B$B暴露在这种等级的原始能量下大幅扩大了我们与生俱来的魔法沉溺。$B$B我不意外凯尔因为这样而侥幸成功;基本上他所有的部下都是喝这个的。','你调查过日怒博学者使用的那些血宝石了吗，$N?','吸取血宝石的能量') ON DUPLICATE KEY UPDATE Title_loc4='血宝石',Details_loc4='凯尔的魔导师已将法力熔炉使用得炉火纯青，瞬间就能汲取到大量能量。$B$B他们利用小块的血宝石碎片，从巨大的血宝石水晶中源源不断地抽取能量。$B$B前往法力熔炉：布纳尔，从日怒魔导师手中夺得一块碎片，然后用这块碎片汲取大块水晶的能量。$B$B完成任务后回到我这儿来，让我研究能量光环的效果。别担心，它所引发的任何副作用都只是暂时的。',Objectives_loc4='魔导师拉恩娜要你进入法力熔炉：布纳尔，从日怒魔导师手中夺得血宝石碎片。在较大的血宝石水晶附近使用这块碎片，然后返回52区向她复命。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。',OfferRewardText_loc4='嗯嗯……就如同我想得一样。$B$B暴露在这种等级的原始能量下大幅扩大了我们与生俱来的魔法沉溺。$B$B我不意外凯尔因为这样而侥幸成功;基本上他所有的部下都是喝这个的。',RequestItemsText_loc4='你调查过日怒博学者使用的那些血宝石了吗，$N?',EndText_loc4='吸取血宝石的能量';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10205,'星界强盗奈萨德','必须干掉星界强盗奈萨德！我真想不通他是怎么从我的必杀技下逃生的，但是我绝不容忍他继续干坏事。$B$B灭了奈萨德，他在机甲废场的西南角建
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10206,'偷来偷去','那些奸猾的虚灵和我们一样，都是彻头彻尾的机会主义者。他们渴望得到利益，我就给他们利益。但是没有人，我是说没有人，可以染指爆缸航天局的财产！$B$B南边那块机甲废场是我们的，我们没说给他们，他们不能抢！$B$B要制造出伟大的虚空火箭X-52，我们需要一切能够得到的新技术。我们必须以同样的手段回敬那帮偷东西的虚灵，这样才显得公平。$B$B不如你现在就去机甲废场，看看能不能从他们鼻子底下搞些他们的科技成果来。','收集10件虚灵科技的产品碎片，将它们交给虚空风暴52区的维勒老爹。','嘿嘿，以太族的混蛋!$B$B感谢你为我们带来了这三个部份，$C。我发誓我会将这些小宝贝们好好的勾在火箭内。我怀疑他们在做些什么?应该会找得很快乐吧!$B$B嗯嗯，我看看是否我可以挖出点钱来打发你。','这么快就带着他们的技术回来罗?你最好不要只是在这扯我的后腿，$C。$B$B这里的X-52计划成功与否，就全靠你赶快将那些东西带来给我们了!') ON DUPLICATE KEY UPDATE Title_loc4='偷来偷去',Details_loc4='那些奸猾的虚灵和我们一样，都是彻头彻尾的机会主义者。他们渴望得到利益，我就给他们利益。但是没有人，我是说没有人，可以染指爆缸航天局的财产！$B$B南边那块机甲废场是我们的，我们没说给他们，他们不能抢！$B$B要制造出伟大的虚空火箭X-52，我们需要一切能够得到的新技术。我们必须以同样的手段回敬那帮偷东西的虚灵，这样才显得公平。$B$B不如你现在就去机甲废场，看看能不能从他们鼻子底下搞些他们的科技成果来。',Objectives_loc4='收集10件虚灵科技的产品碎片，将它们交给虚空风暴52区的维勒老爹。',OfferRewardText_loc4='嘿嘿，以太族的混蛋!$B$B感谢你为我们带来了这三个部份，$C。我发誓我会将这些小宝贝们好好的勾在火箭内。我怀疑他们在做些什么?应该会找得很快乐吧!$B$B嗯嗯，我看看是否我可以挖出点钱来打发你。',RequestItemsText_loc4='这么快就带着他们的技术回来罗?你最好不要只是在这扯我的后腿，$C。$B$B这里的X-52计划成功与否，就全靠你赶快将那些东西带来给我们了!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10207,'前线基地:劫夺者荒野 重新启用','你在战争中的英勇表现已经被高层注意到了，$C.他们想要派你去前线与残拳的军队会合。他们激进，全心奉献于歼灭全数的燃烧军团，因此你应该可以处的很好……
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4,ObjectiveText2_loc4) VALUES (10208,'阻断援军','正东边是军团前线。就可以到达军团前线。那里部署着许多通向外域各地的传送门，使这里的燃烧军团能够随时得到增援。$n，我们决定摧毁所有的传送门！$B$B带上这捆雷管，它是由52区的技师设计的，可以利用恶魔自身的力量产生强大的爆炸！首先你要杀死希鲁斯传送门和科卢尔传送门旁边的那些军团士兵，收集他们身上的恶魔符文石，然后在传送门内使用雷管去引爆这些符文石，你必须亲眼看着传送门都被炸掉！任务完成后回来向我报告。','消灭希鲁斯传送门和科卢尔传送门附近的敌人，收集它们身上的恶魔符文石。$B$B然后在希鲁斯传送门和科卢尔传送门内使用托尔克的雷管。$B$B完成任务后，将剩馀的炸药还给地狱火半岛机甲残骸处的托尔克。','做得好!我从这里几乎还能感觉到爆炸的震动!$B$B现在，我们还有一个爆炸任务要给你……','军团会对你带给他们的惊喜措手不及，对吧 $N?','破坏希鲁斯传送门','破坏科卢尔传送门') ON DUPLICATE KEY UPDATE Title_loc4='阻断援军',Details_loc4='正东边是军团前线。就可以到达军团前线。那里部署着许多通向外域各地的传送门，使这里的燃烧军团能够随时得到增援。$n，我们决定摧毁所有的传送门！$B$B带上这捆雷管，它是由52区的技师设计的，可以利用恶魔自身的力量产生强大的爆炸！首先你要杀死希鲁斯传送门和科卢尔传送门旁边的那些军团士兵，收集他们身上的恶魔符文石，然后在传送门内使用雷管去引爆这些符文石，你必须亲眼看着传送门都被炸掉！任务完成后回来向我报告。',Objectives_loc4='消灭希鲁斯传送门和科卢尔传送门附近的敌人，收集它们身上的恶魔符文石。$B$B然后在希鲁斯传送门和科卢尔传送门内使用托尔克的雷管。$B$B完成任务后，将剩馀的炸药还给地狱火半岛机甲残骸处的托尔克。',OfferRewardText_loc4='做得好!我从这里几乎还能感觉到爆炸的震动!$B$B现在，我们还有一个爆炸任务要给你……',RequestItemsText_loc4='军团会对你带给他们的惊喜措手不及，对吧 $N?',ObjectiveText1_loc4='破坏希鲁斯传送门',ObjectiveText2_loc4='破坏科卢尔传送门';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10209,'召唤者坎西恩的战利品','接下来你必须帮我救出我的魔宠格拉修斯，它被血精灵召唤师坎西恩捉去了。在凯尔萨斯派来毁灭肯瑞瓦村的军队中，坎西恩是地位最高的魔导师之一。他将格拉修斯当作战利品，得意地在其它人面前炫耀。$B$B当然，我敢肯定这个蠢货一定尝试过强迫格拉修斯为他效力。从占卜结果来看，坎西恩就在“法力熔炉：杜隆”，你应该知道这个地方吧。','前往位于日怒堡北部岛屿的法力熔炉：杜隆，从召唤者坎西恩手中夺回格拉修斯之石。','<你不确定这是苦恼呢，还是这位大法师真的是在笑。>$B$B随着我的最后一个财产归还，我有了所有用来破解凯尔萨斯魔法所需要的物品。我现在就要开始执行法术了。','你有安全的取得葛拉希厄斯之石吗?') ON DUPLICATE KEY UPDATE Title_loc4='召唤者坎西恩的战利品',Details_loc4='接下来你必须帮我救出我的魔宠格拉修斯，它被血精灵召唤师坎西恩捉去了。在凯尔萨斯派来毁灭肯瑞瓦村的军队中，坎西恩是地位最高的魔导师之一。他将格拉修斯当作战利品，得意地在其它人面前炫耀。$B$B当然，我敢肯定这个蠢货一定尝试过强迫格拉修斯为他效力。从占卜结果来看，坎西恩就在“法力熔炉：杜隆”，你应该知道这个地方吧。',Objectives_loc4='前往位于日怒堡北部岛屿的法力熔炉：杜隆，从召唤者坎西恩手中夺回格拉修斯之石。',OfferRewardText_loc4='<你不确定这是苦恼呢，还是这位大法师真的是在笑。>$B$B随着我的最后一个财产归还，我有了所有用来破解凯尔萨斯魔法所需要的物品。我现在就要开始执行法术了。',RequestItemsText_loc4='你有安全的取得葛拉希厄斯之石吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10210,'阿达尔','欢迎来到沙塔斯城，$c。这里或许是整个外域里唯一能让你感觉到安全的地方。$B$B一群自称为沙塔尔的纳鲁赶走了这附近的所有恶魔。$B$B如果你从来没有见过纳鲁，那么或许你该去看看圣光广场内的阿达尔。这位沙塔尔的领袖的外貌比我见过的任何生物都要使人敬畏。他们的出现，真是令这里与这片荒凉大地上的任何其它地方都变得截然不同了。','与沙塔尔的领袖阿达尔谈一谈，他就在圣光广场的中央。','<在你与阿达尔谈话时，充斥你的感官的圣光和你接近阿达尔时一样强烈。合谐的钟声不停的包围在你的脑海内。>$B$B<你在这觉得很安全。>') ON DUPLICATE KEY UPDATE Title_loc4='阿达尔',Details_loc4='欢迎来到沙塔斯城，$c。这里或许是整个外域里唯一能让你感觉到安全的地方。$B$B一群自称为沙塔尔的纳鲁赶走了这附近的所有恶魔。$B$B如果你从来没有见过纳鲁，那么或许你该去看看圣光广场内的阿达尔。这位沙塔尔的领袖的外貌比我见过的任何生物都要使人敬畏。他们的出现，真是令这里与这片荒凉大地上的任何其它地方都变得截然不同了。',Objectives_loc4='与沙塔尔的领袖阿达尔谈一谈，他就在圣光广场的中央。',OfferRewardText_loc4='<在你与阿达尔谈话时，充斥你的感官的圣光和你接近阿达尔时一样强烈。合谐的钟声不停的包围在你的脑海内。>$B$B<你在这觉得很安全。>';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,EndText_loc4) VALUES (10211,'圣光之城','别拿那么多的问题去打扰阿达尔，$c。他是你所能面对的最强大的存在。$B$B你看起来有点陌生。我猜你应该很想了解一些有关这座城市的事吧？$B$B我本想亲自带你去参观这里，可我不巧需要和阿达尔讨论一些战略决策。那么我召唤一位仆从代替我去如何？希望你不会觉得这样很失礼。好，那就这样吧！','跟随卡德加的仆从游览城市并聆听这里的历史故事。完成任务后回去向卡德加复命。','我希望你有学到一两件有关沙塔斯的事，$N。也许需要点时间才有办法了解所有的事情。','人的故事是短暂的，$N。而城市的故事才能长远流传。','圣光之城') ON DUPLICATE KEY UPDATE Title_loc4='圣光之城',Details_loc4='别拿那么多的问题去打扰阿达尔，$c。他是你所能面对的最强大的存在。$B$B你看起来有点陌生。我猜你应该很想了解一些有关这座城市的事吧？$B$B我本想亲自带你去参观这里，可我不巧需要和阿达尔讨论一些战略决策。那么我召唤一位仆从代替我去如何？希望你不会觉得这样很失礼。好，那就这样吧！',Objectives_loc4='跟随卡德加的仆从游览城市并聆听这里的历史故事。完成任务后回去向卡德加复命。',OfferRewardText_loc4='我希望你有学到一两件有关沙塔斯的事，$N。也许需要点时间才有办法了解所有的事情。',RequestItemsText_loc4='人的故事是短暂的，$N。而城市的故事才能长远流传。',EndText_loc4='圣光之城';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10212,'玛格汉的英雄','离开之前，我必须交代好奥格瑞玛的事务。告诉祖母，她的孙子很快就去看望她了。','向纳格兰加拉达尔的盖亚安祖母复命。','你真是玛格汉的英雄，$N。要不是你，我们一定已经被巨魔及破碎者侵犯了。$B$B我们是贫穷的人但是我们真的有一些有力的神器。请，我坚持你得从我们得宝库中挑选奖励。','他来了吗?') ON DUPLICATE KEY UPDATE Title_loc4='玛格汉的英雄',Details_loc4='离开之前，我必须交代好奥格瑞玛的事务。告诉祖母，她的孙子很快就去看望她了。',Objectives_loc4='向纳格兰加拉达尔的盖亚安祖母复命。',OfferRewardText_loc4='你真是玛格汉的英雄，$N。要不是你，我们一定已经被巨魔及破碎者侵犯了。$B$B我们是贫穷的人但是我们真的有一些有力的神器。请，我坚持你得从我们得宝库中挑选奖励。',RequestItemsText_loc4='他来了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10213,'调查坠毁点','当我在荒野中受伤休息的时候，我目睹了一起地精飞艇坠毁的事故。它坠落在了西北边的远征军物资库那边。$B$B飞艇着了火，一些地精浑身冒火，尖叫着像火球般从空中跌落下来。当然，我的伤痛非常严重，而且我流了很多血，以上这些可能只是我的幻觉。$B$B如果你能找到幸存者的话，我们可以在断背岗哨为他们提供庇护所。','寻找飞艇坠毁事故的幸存者。','我们是被燃烧军团击中墬毁的，虽然我们有挥舞休战的旗帜。谁知道燃烧军团会这么残暴?$B$B我们不能跟你去断脊氏族岗哨。我们需要修理我们的飞艇并重新上路。','祝你在搜寻幸存者时拥有好运气。我怀疑是不是有人在这场空难中存活下来。') ON DUPLICATE KEY UPDATE Title_loc4='调查坠毁点',Details_loc4='当我在荒野中受伤休息的时候，我目睹了一起地精飞艇坠毁的事故。它坠落在了西北边的远征军物资库那边。$B$B飞艇着了火，一些地精浑身冒火，尖叫着像火球般从空中跌落下来。当然，我的伤痛非常严重，而且我流了很多血，以上这些可能只是我的幻觉。$B$B如果你能找到幸存者的话，我们可以在断背岗哨为他们提供庇护所。',Objectives_loc4='寻找飞艇坠毁事故的幸存者。',OfferRewardText_loc4='我们是被燃烧军团击中墬毁的，虽然我们有挥舞休战的旗帜。谁知道燃烧军团会这么残暴?$B$B我们不能跟你去断脊氏族岗哨。我们需要修理我们的飞艇并重新上路。',RequestItemsText_loc4='祝你在搜寻幸存者时拥有好运气。我怀疑是不是有人在这场空难中存活下来。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10214,'乱糟糟的矿洞','矿井被一群甘尔葛混蛋给侵占了，而那些苦工们却决定好好小憩一下！我不知道在矿井发生骚动的时候他们怎么还睡得着，不过这不是我最担心的事情。$B$B如果我们不能尽快除掉那些甘尔葛，萨尔玛的矿石和其它矿物供给都会被切断。我已经向前线指挥官卡伦克寻求帮助了，但是他说现在城镇不断遭到袭击，他没有多馀的人手可以派来支持我。你愿意帮帮我吗？','杀死15个甘尔葛工兵，然后向工头拉泽克拉兹复命。','终于!现在，我不认为你会愿意去棒打几个苦工的头，或者这得需要额外花费?','唔，你在矿坑那里有任何进展吗?') ON DUPLICATE KEY UPDATE Title_loc4='乱糟糟的矿洞',Details_loc4='矿井被一群甘尔葛混蛋给侵占了，而那些苦工们却决定好好小憩一下！我不知道在矿井发生骚动的时候他们怎么还睡得着，不过这不是我最担心的事情。$B$B如果我们不能尽快除掉那些甘尔葛，萨尔玛的矿石和其它矿物供给都会被切断。我已经向前线指挥官卡伦克寻求帮助了，但是他说现在城镇不断遭到袭击，他没有多馀的人手可以派来支持我。你愿意帮帮我吗？',Objectives_loc4='杀死15个甘尔葛工兵，然后向工头拉泽克拉兹复命。',OfferRewardText_loc4='终于!现在，我不认为你会愿意去棒打几个苦工的头，或者这得需要额外花费?',RequestItemsText_loc4='唔，你在矿坑那里有任何进展吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10216,'安全第一','沙法尔手下的虚灵将我们完全隔绝在了法力陵墓外。不过我已经想好了对付他的法子。虽然我们无法从正门进入，但是陵墓内应该设有好几台传送器。$B$B我要你去替我的手下清理陵墓的通路，然后激活传送器，将我们传送到法力陵墓中。$B$B通路清理完毕后，直接激活沙法尔的房间之前那个房间中的传送器就可以了。放心吧，我不会让你白跑这一趟的……','工匠莫法鲁斯要你杀死10个虚灵盗墓者、5个虚灵巫师、5个节点盗贼和5个虚灵缚法者。$B$B全部搞定之后，激活沙法尔房间的前一个房间中的虚灵传送器。','<你闭上了眼睛按了一个钮。>','这个装备有上百个按钮，没有一个你看的懂得。') ON DUPLICATE KEY UPDATE Title_loc4='安全第一',Details_loc4='沙法尔手下的虚灵将我们完全隔绝在了法力陵墓外。不过我已经想好了对付他的法子。虽然我们无法从正门进入，但是陵墓内应该设有好几台传送器。$B$B我要你去替我的手下清理陵墓的通路，然后激活传送器，将我们传送到法力陵墓中。$B$B通路清理完毕后，直接激活沙法尔的房间之前那个房间中的传送器就可以了。放心吧，我不会让你白跑这一趟的……',Objectives_loc4='工匠莫法鲁斯要你杀死10个虚灵盗墓者、5个虚灵巫师、5个节点盗贼和5个虚灵缚法者。$B$B全部搞定之后，激活沙法尔房间的前一个房间中的虚灵传送器。',OfferRewardText_loc4='<你闭上了眼睛按了一个钮。>',RequestItemsText_loc4='这个装备有上百个按钮，没有一个你看的懂得。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,EndText_loc4) VALUES (10218,'别人的烂摊子','你以为是谁！？莫法鲁斯那个饭桶已经被“降职”了，现在由我来处理他留下的烂摊子。我只有一件事需要你帮忙，在我从沙法尔的灵体收集器中收集灵体能量时保护我。如果我顺利完成使命的话，哈拉迈德会亲自奖励你的！$B$B怎么样？护送我穿越法力陵墓并收集这些令人目瞪口呆的宝藏，听起来如何？你看，你已经完成大部分的工作了！我们身后已经没有活的东西了，不是吗？','护送低温工程师沙赫恩穿过法力陵墓，在他从沙法尔的灵体收集器中收集灵体能量时保护他。$B$B完成任务后向节点亲王哈拉迈德复命，他就在星界财团设立在法力陵墓外的营地中。','看看工匠莫法利厄司的点子的成果，我决定让他复职了。做的好啊小噬尸兽。的确是做的好!$B$B记住，要是你想找工作或是到虚空风暴的时候，到风暴之尖来找我。','哈罗，小噬尸兽。','护送低温工程师沙赫恩') ON DUPLICATE KEY UPDATE Title_loc4='别人的烂摊子',Details_loc4='你以为是谁！？莫法鲁斯那个饭桶已经被“降职”了，现在由我来处理他留下的烂摊子。我只有一件事需要你帮忙，在我从沙法尔的灵体收集器中收集灵体能量时保护我。如果我顺利完成使命的话，哈拉迈德会亲自奖励你的！$B$B怎么样？护送我穿越法力陵墓并收集这些令人目瞪口呆的宝藏，听起来如何？你看，你已经完成大部分的工作了！我们身后已经没有活的东西了，不是吗？',Objectives_loc4='护送低温工程师沙赫恩穿过法力陵墓，在他从沙法尔的灵体收集器中收集灵体能量时保护他。$B$B完成任务后向节点亲王哈拉迈德复命，他就在星界财团设立在法力陵墓外的营地中。',OfferRewardText_loc4='看看工匠莫法利厄司的点子的成果，我决定让他复职了。做的好啊小噬尸兽。的确是做的好!$B$B记住，要是你想找工作或是到虚空风暴的时候，到风暴之尖来找我。',RequestItemsText_loc4='哈罗，小噬尸兽。',EndText_loc4='护送低温工程师沙赫恩';
INSERT INTO locales_quest(entry,Title_loc4) VALUES (10219,'遛狗') ON DUPLICATE KEY UPDATE Title_loc4='遛狗';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10220,'聆听之魂','我到这里来是为了和那些阴魂进行交流的。这些阴魂过去曾是一群值得骄傲的联盟士兵，但很久之前，他们全部都战死了。从此以后，他们被诅咒的灵魂就盘踞在西边的遗迹中。$B$B若是他们能够加入我们，我们就可以得到一批强力的援军了。想想吧，这样一群拥有不死之身的战士能够帮助我们御敌，那该有多好。可是，这些阴魂都因仇恨而变得疯狂与扭曲，恐怕不会与我好好交流。$B$B或许，我们应该使用武力逼迫他们与我们结盟。','莫迪巴要求你前往断背岗哨以西的远征军物资库，击败12个步兵的阴魂、8个骑士的阴魂和6个巫师的阴魂。','这些不屈者已经知道部落的力量了。无庸置疑的他们很快就会接受听取我的结盟提议的。','你让那些不屈的灵魂见识到反抗被遗忘者的下场了吗?') ON DUPLICATE KEY UPDATE Title_loc4='聆听之魂',Details_loc4='我到这里来是为了和那些阴魂进行交流的。这些阴魂过去曾是一群值得骄傲的联盟士兵，但很久之前，他们全部都战死了。从此以后，他们被诅咒的灵魂就盘踞在西边的遗迹中。$B$B若是他们能够加入我们，我们就可以得到一批强力的援军了。想想吧，这样一群拥有不死之身的战士能够帮助我们御敌，那该有多好。可是，这些阴魂都因仇恨而变得疯狂与扭曲，恐怕不会与我好好交流。$B$B或许，我们应该使用武力逼迫他们与我们结盟。',Objectives_loc4='莫迪巴要求你前往断背岗哨以西的远征军物资库，击败12个步兵的阴魂、8个骑士的阴魂和6个巫师的阴魂。',OfferRewardText_loc4='这些不屈者已经知道部落的力量了。无庸置疑的他们很快就会接受听取我的结盟提议的。',RequestItemsText_loc4='你让那些不屈的灵魂见识到反抗被遗忘者的下场了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10221,'砰砰博士！','$N，斯巴奇·尤伯萨斯特这家伙以前一直在我的保护之下。我们来到52区后，他老是不肯带上虚空头盔，终于在某一天摇身一变，成了臭名昭着的砰砰博士！$B$B他偷走了许多重要的挖掘设备，躲藏在东北方的某处营地！他和他的那些砰砰机器人已经对52区构成了巨大的威胁。$B$B我要你立即前往城镇外砰砰博士的营地，结果他的性命！利用这些砰砰厄运炸弹炸飞他。$B$B小心点，不要离他或者那些砰砰机器人太近！','杀死砰砰博士，然后将胜利的消息汇报给虚空风暴52区的首席工兵布拉斯特菲兹。','我会怀念史巴克的。<鼻酸>但是现在知道布姆博士无法再威胁我们的这件事使我们都可以睡的更好!$B$B就让这件事给你上一课。千万不要没戴虚空盔帽就下来这里!$B$B现在，我要怎么回报你呢?','你将我们从布姆博士的蹂躏中解救出来了吗?我发誓现在将不会有任何爆炸性的武器了，虽然那非常的有趣!$B$B我们真的应该要常常那样做。') ON DUPLICATE KEY UPDATE Title_loc4='砰砰博士！',Details_loc4='$N，斯巴奇·尤伯萨斯特这家伙以前一直在我的保护之下。我们来到52区后，他老是不肯带上虚空头盔，终于在某一天摇身一变，成了臭名昭着的砰砰博士！$B$B他偷走了许多重要的挖掘设备，躲藏在东北方的某处营地！他和他的那些砰砰机器人已经对52区构成了巨大的威胁。$B$B我要你立即前往城镇外砰砰博士的营地，结果他的性命！利用这些砰砰厄运炸弹炸飞他。$B$B小心点，不要离他或者那些砰砰机器人太近！',Objectives_loc4='杀死砰砰博士，然后将胜利的消息汇报给虚空风暴52区的首席工兵布拉斯特菲兹。',OfferRewardText_loc4='我会怀念史巴克的。<鼻酸>但是现在知道布姆博士无法再威胁我们的这件事使我们都可以睡的更好!$B$B就让这件事给你上一课。千万不要没戴虚空盔帽就下来这里!$B$B现在，我要怎么回报你呢?',RequestItemsText_loc4='你将我们从布姆博士的蹂躏中解救出来了吗?我发誓现在将不会有任何爆炸性的武器了，虽然那非常的有趣!$B$B我们真的应该要常常那样做。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10222,'日怒堡','凯尔萨斯王子的军队摧毁了肯瑞瓦村，将大法师囚禁在紫罗兰之塔，然后便退驻到了东北方的日怒堡。我们眼睁睁地看着他们庆祝着“伟大的胜利”却毫无复仇之力。$B$B绝不能容忍他们这样行恶！为我们的复仇事业而战吧，$N。前往日怒堡，让那些双手沾满鲜血的罪人得到正义的裁决。','肯瑞瓦村的管理器戴沃斯要你杀死10名日怒射手。','你今日所做的事永远无法挽回村子的沦陷，但也许这有助于安抚他们的灵魂。虽然，说实话，再多的血腥都无法平息我对凯尔萨斯的怒火。','完成了吗，$N!你已经为了肯瑞瓦村庄的沦陷复仇了吗?') ON DUPLICATE KEY UPDATE Title_loc4='日怒堡',Details_loc4='凯尔萨斯王子的军队摧毁了肯瑞瓦村，将大法师囚禁在紫罗兰之塔，然后便退驻到了东北方的日怒堡。我们眼睁睁地看着他们庆祝着“伟大的胜利”却毫无复仇之力。$B$B绝不能容忍他们这样行恶！为我们的复仇事业而战吧，$N。前往日怒堡，让那些双手沾满鲜血的罪人得到正义的裁决。',Objectives_loc4='肯瑞瓦村的管理器戴沃斯要你杀死10名日怒射手。',OfferRewardText_loc4='你今日所做的事永远无法挽回村子的沦陷，但也许这有助于安抚他们的灵魂。虽然，说实话，再多的血腥都无法平息我对凯尔萨斯的怒火。',RequestItemsText_loc4='完成了吗，$N!你已经为了肯瑞瓦村庄的沦陷复仇了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10223,'达尔利斯之死','我永远都不会忘记袭击肯瑞瓦村的血精灵首领。他穿着一身血红色的铠甲，佩戴着我从未见过的徽章。$B$B跟其它血精灵军官不同，这位残忍的首领竟然冲锋在最前线。那场战争中，许多肯瑞托法师都死在他的箭下。他在日怒堡驻留了一段时间，然后就被凯尔萨斯派去法力熔炉：杜隆，镇压那里的骚乱。$N，找到他的下落，让他的弓弦永久沉寂吧。','肯瑞瓦村的管理器戴沃斯要你杀死达尔利斯·晨击。','<你并不确定，但是看起来管理器戴沃斯已经濒临要落泪了。>$B$B终于，结束了。如果我可以选择离开这个世界，我会的，但事实上我却不知道该如何放手。为了那些在村庄牺牲的人们，这是个困难但明确的决定。我想这就是我们为了在这个地方维持强大势力所要付出的代价吧。','你完成任务了吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='达尔利斯之死',Details_loc4='我永远都不会忘记袭击肯瑞瓦村的血精灵首领。他穿着一身血红色的铠甲，佩戴着我从未见过的徽章。$B$B跟其它血精灵军官不同，这位残忍的首领竟然冲锋在最前线。那场战争中，许多肯瑞托法师都死在他的箭下。他在日怒堡驻留了一段时间，然后就被凯尔萨斯派去法力熔炉：杜隆，镇压那里的骚乱。$N，找到他的下落，让他的弓弦永久沉寂吧。',Objectives_loc4='肯瑞瓦村的管理器戴沃斯要你杀死达尔利斯·晨击。',OfferRewardText_loc4='<你并不确定，但是看起来管理器戴沃斯已经濒临要落泪了。>$B$B终于，结束了。如果我可以选择离开这个世界，我会的，但事实上我却不知道该如何放手。为了那些在村庄牺牲的人们，这是个困难但明确的决定。我想这就是我们为了在这个地方维持强大势力所要付出的代价吧。',RequestItemsText_loc4='你完成任务了吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10224,'引擎的能源','身为X-52的技术主管，我必须确保这艘虚空火箭的主引擎具备最优化的性能。$B$B可惜我到现在都还没有把这些主引擎造出来。$B$B$C，眼下的情况非常窘迫！除了引擎核心外，所有的零件都齐了。$B$B不过，我想我们可以利用法力怨魂的精华来发动引擎。$B$B它们遍布在岛屿北部那些闪闪发光的沟渠附近。当然，52区里可没这种生物。','将7块法力怨魂精华交给虚空风暴52区的主工程师特雷普。','哇喔，好多精华喔!$B$B好了，让我们看看将它及伊斯利母体水晶混合后会发生什么事。','你拿到所有精华了吗?') ON DUPLICATE KEY UPDATE Title_loc4='引擎的能源',Details_loc4='身为X-52的技术主管，我必须确保这艘虚空火箭的主引擎具备最优化的性能。$B$B可惜我到现在都还没有把这些主引擎造出来。$B$B$C，眼下的情况非常窘迫！除了引擎核心外，所有的零件都齐了。$B$B不过，我想我们可以利用法力怨魂的精华来发动引擎。$B$B它们遍布在岛屿北部那些闪闪发光的沟渠附近。当然，52区里可没这种生物。',Objectives_loc4='将7块法力怨魂精华交给虚空风暴52区的主工程师特雷普。',OfferRewardText_loc4='哇喔，好多精华喔!$B$B好了，让我们看看将它及伊斯利母体水晶混合后会发生什么事。',RequestItemsText_loc4='你拿到所有精华了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10225,'向主工程师汇报','$N！我要你将这些以太锂水晶交给主工程师特雷普，他是我们的，嗯，领头的工程师。$B$B他应该知道如何处理这些水晶。如果他不知道，你就在那里盯着他，直到他想出法子来！','将以太锂矩阵水晶交给虚空风暴52区的主工程师特雷普。','喔，伊斯利母体水晶。耶，这些听起来很重要耶!$B$B就放在这边，我会尽快找出它们的用途。','嗯，嗨。我现在有点忙。你有什么东西要给我吗?') ON DUPLICATE KEY UPDATE Title_loc4='向主工程师汇报',Details_loc4='$N！我要你将这些以太锂水晶交给主工程师特雷普，他是我们的，嗯，领头的工程师。$B$B他应该知道如何处理这些水晶。如果他不知道，你就在那里盯着他，直到他想出法子来！',Objectives_loc4='将以太锂矩阵水晶交给虚空风暴52区的主工程师特雷普。',OfferRewardText_loc4='喔，伊斯利母体水晶。耶，这些听起来很重要耶!$B$B就放在这边，我会尽快找出它们的用途。',RequestItemsText_loc4='嗯，嗨。我现在有点忙。你有什么东西要给我吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10226,'元素能量萃取器','该死，这玩意根本就不行！$B$B噢噢，我想到个新主意！我曾让塞希罗制作过一台元素能量萃取器，不知道这东西收集来的能量管不管用，但至少我们可以试试。$B$B南边的碎裂废土分布着许多碎裂的滚石和迁跃畸变体，它们体内的能量可以发动引擎！$B$B击败元素生物后，利用这台萃取器将它们的能量转化为便于收集的固体。然后把那些固体带回来给我就行啦。','萃取5份元素能量，将它们交给虚空风暴52区的主工程师特雷普。','这才像话嘛!太好了，现在我想我们可以开工了。$B$B就让我将这些东西倒到这个什么什么里面，我相信将会喷出一个全功能的引擎核心。$B$B喔，嘿，我猜我应该要感谢你保住了我的小命!嘿嘿。','你从那些元素生物身上得到力量了没?喔，我不是想催你或什么的。只不过我的生活及工作都靠你了。') ON DUPLICATE KEY UPDATE Title_loc4='元素能量萃取器',Details_loc4='该死，这玩意根本就不行！$B$B噢噢，我想到个新主意！我曾让塞希罗制作过一台元素能量萃取器，不知道这东西收集来的能量管不管用，但至少我们可以试试。$B$B南边的碎裂废土分布着许多碎裂的滚石和迁跃畸变体，它们体内的能量可以发动引擎！$B$B击败元素生物后，利用这台萃取器将它们的能量转化为便于收集的固体。然后把那些固体带回来给我就行啦。',Objectives_loc4='萃取5份元素能量，将它们交给虚空风暴52区的主工程师特雷普。',OfferRewardText_loc4='这才像话嘛!太好了，现在我想我们可以开工了。$B$B就让我将这些东西倒到这个什么什么里面，我相信将会喷出一个全功能的引擎核心。$B$B喔，嘿，我猜我应该要感谢你保住了我的小命!嘿嘿。',RequestItemsText_loc4='你从那些元素生物身上得到力量了没?喔，我不是想催你或什么的。只不过我的生活及工作都靠你了。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10227,'我看到了死德莱尼人','我看见许多死去的德莱尼人。他们就在我们周围。$B$B唉，没人相信小孩子的话，连我妈妈都认为我在说谎。$B$B<哈雷指着拉姆杜尔。>$B$B只有他相信我……他也能看见死人。他为此恼怒不已，真是孩子气呀！$B$B我觉得这件事真好笑。我说我看见了幽灵，大家只是笑着拍我的头，试图安慰我。拉姆杜尔也能看见幽灵，可是他们都认为他疯了。我真希望我永远都不会长大！$B$B在你进去之前，最好先和拉姆杜尔聊聊。他以前还是个死亡祭司呢。','与奥金尼地穴外的疯狂的拉姆杜尔谈一谈，他就站在地穴入口附近的骨堆上。','那小孩子是对的。我曾经是个“死亡祭司”。$B$B<蓝姆多在抽搐。>$B$B真是令人讨厌的名称。$B$B这条走廊后面就是奥金尼地穴。你会在里面找到我的修道院的幸存者。当然，他们现在都疯了。彻底的疯了!我想我是唯一的例外，是他们之中最后一个还有理智的人。当然，我因为我的信仰而被逐出教会。$B$B你说，我的信仰是什么呢?','<蓝姆多惊讶的看着你。>$B$B嗯嗯，有事吗???') ON DUPLICATE KEY UPDATE Title_loc4='我看到了死德莱尼人',Details_loc4='我看见许多死去的德莱尼人。他们就在我们周围。$B$B唉，没人相信小孩子的话，连我妈妈都认为我在说谎。$B$B<哈雷指着拉姆杜尔。>$B$B只有他相信我……他也能看见死人。他为此恼怒不已，真是孩子气呀！$B$B我觉得这件事真好笑。我说我看见了幽灵，大家只是笑着拍我的头，试图安慰我。拉姆杜尔也能看见幽灵，可是他们都认为他疯了。我真希望我永远都不会长大！$B$B在你进去之前，最好先和拉姆杜尔聊聊。他以前还是个死亡祭司呢。',Objectives_loc4='与奥金尼地穴外的疯狂的拉姆杜尔谈一谈，他就站在地穴入口附近的骨堆上。',OfferRewardText_loc4='那小孩子是对的。我曾经是个“死亡祭司”。$B$B<蓝姆多在抽搐。>$B$B真是令人讨厌的名称。$B$B这条走廊后面就是奥金尼地穴。你会在里面找到我的修道院的幸存者。当然，他们现在都疯了。彻底的疯了!我想我是唯一的例外，是他们之中最后一个还有理智的人。当然，我因为我的信仰而被逐出教会。$B$B你说，我的信仰是什么呢?',RequestItemsText_loc4='<蓝姆多惊讶的看着你。>$B$B嗯嗯，有事吗???';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10228,'伊瑟基尔','过去500年来，我们一直守护着德莱尼的亡魂。我希望他们能享受这份安宁，不要被任何人打扰。玛拉达尔却有他自己的计划。他躲入纪念地穴中，展开……通灵术实验。$B$B你最好先别想着进入地穴……至少得帮我一把，好让这些被诅咒的灵魂得到安息，别再烦我了。$r，我知道他们将财宝藏在哪里。怎么样，你现在对此感兴趣了吧？$B$B把亡者之书带回来给我，它应该在沙塔斯城的伊瑟基尔手中。','与沙塔斯城的伊瑟基尔谈一谈。','亡者之书?从来没听过……不过这是有关什么的啊?是谁要你来的?','圣光与你同在，我的朋友。') ON DUPLICATE KEY UPDATE Title_loc4='伊瑟基尔',Details_loc4='过去500年来，我们一直守护着德莱尼的亡魂。我希望他们能享受这份安宁，不要被任何人打扰。玛拉达尔却有他自己的计划。他躲入纪念地穴中，展开……通灵术实验。$B$B你最好先别想着进入地穴……至少得帮我一把，好让这些被诅咒的灵魂得到安息，别再烦我了。$r，我知道他们将财宝藏在哪里。怎么样，你现在对此感兴趣了吧？$B$B把亡者之书带回来给我，它应该在沙塔斯城的伊瑟基尔手中。',Objectives_loc4='与沙塔斯城的伊瑟基尔谈一谈。',OfferRewardText_loc4='亡者之书?从来没听过……不过这是有关什么的啊?是谁要你来的?',RequestItemsText_loc4='圣光与你同在，我的朋友。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10229,'解读书卷','这本书卷上似乎用某种隐秘的联盟密码语言记录着一些历史事件。那个目前逗留在断背岗哨的历史学家奥尔森研究阴魂已经很久了，或许他能够破解这种联盟密码，并翻译整本书的内容。','将神秘的典籍交给断背岗哨的史学家奥尔森。','我一辈子都在研究先祖历史。但我从未见过像这样的一本书。里面记载整个军械库的历史，包括毁灭之后发生的事。$B$B不屈者延续了他们的历史，即使是在他们于战斗中沦陷后。藉由这本书我们将可了解不屈者并说服他们加入。','这是什么?一本传达不屈者意念的书?真是奇怪。我研究看看。也许我有办法知道不屈者的历史。') ON DUPLICATE KEY UPDATE Title_loc4='解读书卷',Details_loc4='这本书卷上似乎用某种隐秘的联盟密码语言记录着一些历史事件。那个目前逗留在断背岗哨的历史学家奥尔森研究阴魂已经很久了，或许他能够破解这种联盟密码，并翻译整本书的内容。',Objectives_loc4='将神秘的典籍交给断背岗哨的史学家奥尔森。',OfferRewardText_loc4='我一辈子都在研究先祖历史。但我从未见过像这样的一本书。里面记载整个军械库的历史，包括毁灭之后发生的事。$B$B不屈者延续了他们的历史，即使是在他们于战斗中沦陷后。藉由这本书我们将可了解不屈者并说服他们加入。',RequestItemsText_loc4='这是什么?一本传达不屈者意念的书?真是奇怪。我研究看看。也许我有办法知道不屈者的历史。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10230,'战斗的号角','或许我们之前接触阴魂的方式是完全错误的？$B$B这本书中的内容告诉我，远征军物资库很久以前就被兽人和死亡骑士毁灭了。这些阴魂是被禁锢在这里的一批复仇之灵，与邪兽人各氏族进行着永恒的战争。$B$B现在，他们所想的事情除了复仇之外再无它物。我们必须让阴魂们击败他们最憎恨的敌人。请你再去一趟远征军物资库，找到塔沃斯少校。他身上带着一只可以召唤所有阴魂的战斗号角。把它带回来给我。','从塔沃斯少校那里拿到顽强战斗号角，把它交给断背岗哨的史学家奥尔森。','你做得很好 $N。这个先祖号角使我们能够招集不屈者。$B$B不过，得要他们愿意才行。','我们得尽快帮助不屈者。要是我们能够说服他们加入我们，部落将获得一个有利的盟友。') ON DUPLICATE KEY UPDATE Title_loc4='战斗的号角',Details_loc4='或许我们之前接触阴魂的方式是完全错误的？$B$B这本书中的内容告诉我，远征军物资库很久以前就被兽人和死亡骑士毁灭了。这些阴魂是被禁锢在这里的一批复仇之灵，与邪兽人各氏族进行着永恒的战争。$B$B现在，他们所想的事情除了复仇之外再无它物。我们必须让阴魂们击败他们最憎恨的敌人。请你再去一趟远征军物资库，找到塔沃斯少校。他身上带着一只可以召唤所有阴魂的战斗号角。把它带回来给我。',Objectives_loc4='从塔沃斯少校那里拿到顽强战斗号角，把它交给断背岗哨的史学家奥尔森。',OfferRewardText_loc4='你做得很好 $N。这个先祖号角使我们能够招集不屈者。$B$B不过，得要他们愿意才行。',RequestItemsText_loc4='我们得尽快帮助不屈者。要是我们能够说服他们加入我们，部落将获得一个有利的盟友。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,EndText_loc4) VALUES (10231,'什么书？我没见过什么书','拉姆杜尔？呃，让我想想……拉姆杜尔……哦，是那个死亡祭司。他要亡者之书做什么？唔，无所谓。很抱歉，我没说实话，但那本书真的不在我这儿。准确地说，我不再拥有它了。它被偷走了，或许是某个卑贱的难民干的。$B$B奥金顿已是了无生气的死地，亡者之书对我们来说没有任何用处了。如果你找到它，就留着好了。$B$B上周我还看见那帮无赖鬼鬼祟祟地在附近出没。就从他们身上开始调查吧。现在他们可能在贫民窟玩骰子。','伊瑟基尔说亡者之书已经被偷走了。你最好去问问那些无赖，看他们是否知道些什么。','好，好!不要伤害我们。我们是有这本书不过我们卖掉了……','你要啥?','教训“脏鬼”拉瑞，获取信息') ON DUPLICATE KEY UPDATE Title_loc4='什么书？我没见过什么书',Details_loc4='拉姆杜尔？呃，让我想想……拉姆杜尔……哦，是那个死亡祭司。他要亡者之书做什么？唔，无所谓。很抱歉，我没说实话，但那本书真的不在我这儿。准确地说，我不再拥有它了。它被偷走了，或许是某个卑贱的难民干的。$B$B奥金顿已是了无生气的死地，亡者之书对我们来说没有任何用处了。如果你找到它，就留着好了。$B$B上周我还看见那帮无赖鬼鬼祟祟地在附近出没。就从他们身上开始调查吧。现在他们可能在贫民窟玩骰子。',Objectives_loc4='伊瑟基尔说亡者之书已经被偷走了。你最好去问问那些无赖，看他们是否知道些什么。',OfferRewardText_loc4='好，好!不要伤害我们。我们是有这本书不过我们卖掉了……',RequestItemsText_loc4='你要啥?',EndText_loc4='教训“脏鬼”拉瑞，获取信息';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10232,'废料场中的燃烧军团','沿着道路往东走，桥对面的废料场原本是我们的地盘，可现在被燃烧军团侵占了。$B$B这会给我们造成很大的麻烦！先是阿尔科隆废墟，接下来是废料场，局势越来越糟糕了，不知道52区的火箭计划是否会受到影响。$B$B$N，我要你前往废料场消灭那些恶魔！我本想亲自动手的，但我是个讨厌打斗和杀戮的博爱者。$B$B没错，这是一项艰难的任务，我知道！','杀死5名莫尔葛铁匠和15名甘尔葛工程师，然后向虚空风暴52区的维勒老爹复命。','好吧，有好消息也有坏消息，是吧? 我们给了他们一击，但随着燃烧军团遍布整个虚空风暴上 - 并且更接近我们了 -','我当然希望你忙着与燃烧军团战斗。$B$B没有什么是比背信更让我厌恶的，还有<咳嗽>地精，而恶魔必定就是这两种其中一种!') ON DUPLICATE KEY UPDATE Title_loc4='废料场中的燃烧军团',Details_loc4='沿着道路往东走，桥对面的废料场原本是我们的地盘，可现在被燃烧军团侵占了。$B$B这会给我们造成很大的麻烦！先是阿尔科隆废墟，接下来是废料场，局势越来越糟糕了，不知道52区的火箭计划是否会受到影响。$B$B$N，我要你前往废料场消灭那些恶魔！我本想亲自动手的，但我是个讨厌打斗和杀戮的博爱者。$B$B没错，这是一项艰难的任务，我知道！',Objectives_loc4='杀死5名莫尔葛铁匠和15名甘尔葛工程师，然后向虚空风暴52区的维勒老爹复命。',OfferRewardText_loc4='好吧，有好消息也有坏消息，是吧? 我们给了他们一击，但随着燃烧军团遍布整个虚空风暴上 - 并且更接近我们了 -',RequestItemsText_loc4='我当然希望你忙着与燃烧军团战斗。$B$B没有什么是比背信更让我厌恶的，还有<咳嗽>地精，而恶魔必定就是这两种其中一种!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4,ObjectiveText2_loc4) VALUES (10233,'烧毁日怒堡','哪怕我们杀光日怒堡的驻军，也不能阻止血精灵重新夺回城堡。凯尔萨斯的追随者狂热而顽强，如果我们留下任何有用的器物，他们肯定会利用这些东西向我们发动反击。$B$B不行，必须毁掉日怒堡的一切。焚毁那里的帐篷和弩车！$B$B<鬼魂攥紧了拳头。>$B$B$N，你可以从日怒护火者手中夺得火炬来完成这项任务。','使用燃烧的火把烧毁4台日怒弩车和4顶日怒帐篷，然后向肯瑞瓦村的巫师上尉莫尔兰复命。','<莫尔兰巫士中尉严肃的点头。>$B$B肯瑞托很难从建筑物本身的利益来欣赏它，但我们并不会因为对抗敌人而觉得良心不安，就算死的也一样。','烟从日怒要塞的堡垒中升起。那是你的杰作吗?','烧毁日怒弩车','烧毁日怒帐篷') ON DUPLICATE KEY UPDATE Title_loc4='烧毁日怒堡',Details_loc4='哪怕我们杀光日怒堡的驻军，也不能阻止血精灵重新夺回城堡。凯尔萨斯的追随者狂热而顽强，如果我们留下任何有用的器物，他们肯定会利用这些东西向我们发动反击。$B$B不行，必须毁掉日怒堡的一切。焚毁那里的帐篷和弩车！$B$B<鬼魂攥紧了拳头。>$B$B$N，你可以从日怒护火者手中夺得火炬来完成这项任务。',Objectives_loc4='使用燃烧的火把烧毁4台日怒弩车和4顶日怒帐篷，然后向肯瑞瓦村的巫师上尉莫尔兰复命。',OfferRewardText_loc4='<莫尔兰巫士中尉严肃的点头。>$B$B肯瑞托很难从建筑物本身的利益来欣赏它，但我们并不会因为对抗敌人而觉得良心不安，就算死的也一样。',RequestItemsText_loc4='烟从日怒要塞的堡垒中升起。那是你的杰作吗?',ObjectiveText1_loc4='烧毁日怒弩车',ObjectiveText2_loc4='烧毁日怒帐篷';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10234,'恶魔的垃圾……','你看上去像是位有能力的年轻人！我想知道你是否能帮我个忙？$B$B在东边的废料场，对，就是燃烧军团的驻地，那里堆满了大型魔能机甲零件之外，还散落着许多小尺寸的零件。而且，恶魔们似乎不怎么在意那些小零件。$B$B我要你前往废料场，将那些小尺寸的魔能机甲零件带回来给我！','收集10个魔能机甲零件，然后返回虚空风暴的中央生态圆顶，将它们交给中央圆顶哨站的维勒老妈。','我认为这些都得现在就去做了。只要我们能够将他们吓跑。$B$B嘿，这让我想到了个办法!','你取得那些零件了吗?随着燃烧军团每次一个一个进驻我们在这里的领地，我们所剩的时间不多了。') ON DUPLICATE KEY UPDATE Title_loc4='恶魔的垃圾……',Details_loc4='你看上去像是位有能力的年轻人！我想知道你是否能帮我个忙？$B$B在东边的废料场，对，就是燃烧军团的驻地，那里堆满了大型魔能机甲零件之外，还散落着许多小尺寸的零件。而且，恶魔们似乎不怎么在意那些小零件。$B$B我要你前往废料场，将那些小尺寸的魔能机甲零件带回来给我！',Objectives_loc4='收集10个魔能机甲零件，然后返回虚空风暴的中央生态圆顶，将它们交给中央圆顶哨站的维勒老妈。',OfferRewardText_loc4='我认为这些都得现在就去做了。只要我们能够将他们吓跑。$B$B嘿，这让我想到了个办法!',RequestItemsText_loc4='你取得那些零件了吗?随着燃烧军团每次一个一个进驻我们在这里的领地，我们所剩的时间不多了。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10235,'厄运之爪','你知道怎样才能让他们垂头丧气吗？那就是干掉他们的头目！$B$B我听说这招特别有效。若是他们目睹一位彪悍的$c，比如你，一刀砍翻他们的头目……哇，我敢打赌他们会立即卷起尾巴仓惶逃走！$B$B返回废料场，干掉他们的首领厄运之爪。我听说他躲藏在废料场东边的管道下面。$B$B哦，记得把他的爪子给我带来！我们或许用得上。','取得厄运之爪的手，然后返回虚空风暴的中央生态圆顶，将它们交给中央圆顶哨站的维勒老妈。','他，嗯……他说什么?他们将要侵犯52区?!$B$B喔，这太糟了……糟透了!','解决末日裂爪了没?') ON DUPLICATE KEY UPDATE Title_loc4='厄运之爪',Details_loc4='你知道怎样才能让他们垂头丧气吗？那就是干掉他们的头目！$B$B我听说这招特别有效。若是他们目睹一位彪悍的$c，比如你，一刀砍翻他们的头目……哇，我敢打赌他们会立即卷起尾巴仓惶逃走！$B$B返回废料场，干掉他们的首领厄运之爪。我听说他躲藏在废料场东边的管道下面。$B$B哦，记得把他的爪子给我带来！我们或许用得上。',Objectives_loc4='取得厄运之爪的手，然后返回虚空风暴的中央生态圆顶，将它们交给中央圆顶哨站的维勒老妈。',OfferRewardText_loc4='他，嗯……他说什么?他们将要侵犯52区?!$B$B喔，这太糟了……糟透了!',RequestItemsText_loc4='解决末日裂爪了没?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10236,'外域这烂地方！','我真不敢相信我竟然会离开藏宝海湾来到外域。我的兄弟斯克里·拉克希德许诺说我能在这里赚一大笔钱，但这家伙倒是乘坐飞艇离开了，把我留在这个破矿井里混吃等死。$B$B这鬼地方整天被地狱野猪、恶魔还有邪兽人攻击，叫我怎么活？我的伐木机昨天也坏了，修理机器的备用零件还被邪兽人偷走了。他们把零件搬到了西南边的裂谷中，没准就丢在那边呢。','找到6个伐木机备用零件，然后返回萨尔玛西北方的矿洞，将它们交给工头拉泽克拉兹。','喔耶，你找到零件了!也许现在我可以修好我的伐木机了。假如我可以赚到足够的钱我就可以回去藏宝海湾了。$B$B我真希望我的堂弟，史哥利德.幸运心，还有他的飞艇一起坠机。我不敢相信他骗我来外域。','你帮我的伐木机找到修理的零件了吗?我希望赶快修好他我才能继续去矿坑工作。不论如何我都必须要赚钱过日子，只有这样我才能赚足够的钱买一张回去藏宝海湾的单程票。') ON DUPLICATE KEY UPDATE Title_loc4='外域这烂地方！',Details_loc4='我真不敢相信我竟然会离开藏宝海湾来到外域。我的兄弟斯克里·拉克希德许诺说我能在这里赚一大笔钱，但这家伙倒是乘坐飞艇离开了，把我留在这个破矿井里混吃等死。$B$B这鬼地方整天被地狱野猪、恶魔还有邪兽人攻击，叫我怎么活？我的伐木机昨天也坏了，修理机器的备用零件还被邪兽人偷走了。他们把零件搬到了西南边的裂谷中，没准就丢在那边呢。',Objectives_loc4='找到6个伐木机备用零件，然后返回萨尔玛西北方的矿洞，将它们交给工头拉泽克拉兹。',OfferRewardText_loc4='喔耶，你找到零件了!也许现在我可以修好我的伐木机了。假如我可以赚到足够的钱我就可以回去藏宝海湾了。$B$B我真希望我的堂弟，史哥利德.幸运心，还有他的飞艇一起坠机。我不敢相信他骗我来外域。',RequestItemsText_loc4='你帮我的伐木机找到修理的零件了吗?我希望赶快修好他我才能继续去矿坑工作。不论如何我都必须要赚钱过日子，只有这样我才能赚足够的钱买一张回去藏宝海湾的单程票。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10237,'通知52区！','$N，你必须立即把这个消息传递给52区！快！$B$B告诉火箭主管，燃烧军团已经盯上我们了！','将坏消息告诉虚空风暴52区的火箭主管弗斯拉格。','嘿，你在开玩笑，对吧?燃烧军团就因为那样而怪罪于我们吗?$B$B但是你才是元凶吧!$B$B天啊，我的头痛到像这个火箭那么大了。好啦，好啦，看来我们需要改变计划了。$B$B如果燃烧军团认为他们会来这里，毁掉我们的城镇以及破坏我漫游扭曲虚空的梦想，那他们就太天真了。$B$B我刚好知道有一个哥布尔可以帮助我们。','有事吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='通知52区！',Details_loc4='$N，你必须立即把这个消息传递给52区！快！$B$B告诉火箭主管，燃烧军团已经盯上我们了！',Objectives_loc4='将坏消息告诉虚空风暴52区的火箭主管弗斯拉格。',OfferRewardText_loc4='嘿，你在开玩笑，对吧?燃烧军团就因为那样而怪罪于我们吗?$B$B但是你才是元凶吧!$B$B天啊，我的头痛到像这个火箭那么大了。好啦，好啦，看来我们需要改变计划了。$B$B如果燃烧军团认为他们会来这里，毁掉我们的城镇以及破坏我漫游扭曲虚空的梦想，那他们就太天真了。$B$B我刚好知道有一个哥布尔可以帮助我们。',RequestItemsText_loc4='有事吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4,ObjectiveText2_loc4,ObjectiveText3_loc4) VALUES (10238,'如何为地精效力','为什么邪兽人要偷走我的伐木机零件？我讨厌他们。这帮家伙老是溜进营地偷东西。几天前，他们竟然偷走了三名苦工！现在，矿洞的其它苦工都跑光了，他们可不想被邪兽人吃掉。$B$B没苦工叫我怎么开矿啊？要是你能把那些苦工救回来，没准其它人就肯回来工作了。邪兽人的营地就在西南边的城墙下。','从邪兽人的营地中救出曼尼、莫恩和雅克，然后返回萨尔玛西北方的矿洞，向工头拉泽克拉兹复命。','感谢你拯救了我的苦工们。也许现在我就可以叫他们拿着零件去修我的伐木机，赚到足够的钱然后离开外域。我等不及想回去藏宝海湾了。','你救回我的苦工了没?拜托快一点，我怕他们很快就会被吃掉而且他们应该不好吃。假如邪兽人吃了倒胃口的话他们可是会迁怒到我呢。','营救曼尼','营救莫恩','营救雅克') ON DUPLICATE KEY UPDATE Title_loc4='如何为地精效力',Details_loc4='为什么邪兽人要偷走我的伐木机零件？我讨厌他们。这帮家伙老是溜进营地偷东西。几天前，他们竟然偷走了三名苦工！现在，矿洞的其它苦工都跑光了，他们可不想被邪兽人吃掉。$B$B没苦工叫我怎么开矿啊？要是你能把那些苦工救回来，没准其它人就肯回来工作了。邪兽人的营地就在西南边的城墙下。',Objectives_loc4='从邪兽人的营地中救出曼尼、莫恩和雅克，然后返回萨尔玛西北方的矿洞，向工头拉泽克拉兹复命。',OfferRewardText_loc4='感谢你拯救了我的苦工们。也许现在我就可以叫他们拿着零件去修我的伐木机，赚到足够的钱然后离开外域。我等不及想回去藏宝海湾了。',RequestItemsText_loc4='你救回我的苦工了没?拜托快一点，我怕他们很快就会被吃掉而且他们应该不好吃。假如邪兽人吃了倒胃口的话他们可是会迁怒到我呢。',ObjectiveText1_loc4='营救曼尼',ObjectiveText2_loc4='营救莫恩',ObjectiveText3_loc4='营救雅克';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10239,'强大的能量源','我们并非是唯一与法力生物抗争的势力。血精灵也深受它们的困扰，不过我并不清楚原因。$B$B无论血精灵在法力熔炉遭遇了怎样的麻烦，他们却没有收手的意思。我发现，他们用各种方法杀死法力生物，其中最有效的就是利用高度集中的能量形成魔法防御屏障。$B$B前往法力熔炉：库鲁恩夺取一些能量源，然后带回来给我。如果有机会的话，别忘记给血精灵制造一点麻烦。','肯瑞瓦村的巫师上尉莫尔兰要你前往法力熔炉：库鲁恩，取回10块能量隔离器。','<莫兰小心翼翼的处理其中一个容器。>$B$B我不相信我之前曾看过任何跟这一样的东西。一定有很多的能量悬浮在这里，但是是以原始的状态。我们得小心处理，不过我想我们能找到方法来改写这些能量进而协助抵挡那些法力生物。','你有办法取得到任何他们的能量来源吗?') ON DUPLICATE KEY UPDATE Title_loc4='强大的能量源',Details_loc4='我们并非是唯一与法力生物抗争的势力。血精灵也深受它们的困扰，不过我并不清楚原因。$B$B无论血精灵在法力熔炉遭遇了怎样的麻烦，他们却没有收手的意思。我发现，他们用各种方法杀死法力生物，其中最有效的就是利用高度集中的能量形成魔法防御屏障。$B$B前往法力熔炉：库鲁恩夺取一些能量源，然后带回来给我。如果有机会的话，别忘记给血精灵制造一点麻烦。',Objectives_loc4='肯瑞瓦村的巫师上尉莫尔兰要你前往法力熔炉：库鲁恩，取回10块能量隔离器。',OfferRewardText_loc4='<莫兰小心翼翼的处理其中一个容器。>$B$B我不相信我之前曾看过任何跟这一样的东西。一定有很多的能量悬浮在这里，但是是以原始的状态。我们得小心处理，不过我想我们能找到方法来改写这些能量进而协助抵挡那些法力生物。',RequestItemsText_loc4='你有办法取得到任何他们的能量来源吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4,ObjectiveText2_loc4,ObjectiveText3_loc4) VALUES (10240,'构筑能量壁障','现在，我们计划利用这些从血精灵手中夺来的能量源在村子周围创建起一道能量壁障。我不敢保证这绝对有效，但总得试试看。$B$B否则法力生物就会源源不断地涌进村落，继续吞噬肯瑞托法师的灵魂。$B$B利用这个装置激活村子周围的小符文。如果力场分布得没有错，每激活一块符文，你就能感受到周围的变化。','对东部符文、东北部符文和西部符文使用符文激活装置。你可以在肯瑞瓦村城镇广场和巫师街周边找到这些符文。完成任务后向巫师上尉莫尔兰复命。','做得好。抓紧你的手，$N。我要启动防护罩了。','你启动了所有的符文了吗?我很急切的想知道是否我们无法改善这里的血精灵秩序。任何凯尔萨斯的手下可以做到的事，真正的肯瑞托可以做的更好。','激活东部符文','激活东北部符文','激活西部符文') ON DUPLICATE KEY UPDATE Title_loc4='构筑能量壁障',Details_loc4='现在，我们计划利用这些从血精灵手中夺来的能量源在村子周围创建起一道能量壁障。我不敢保证这绝对有效，但总得试试看。$B$B否则法力生物就会源源不断地涌进村落，继续吞噬肯瑞托法师的灵魂。$B$B利用这个装置激活村子周围的小符文。如果力场分布得没有错，每激活一块符文，你就能感受到周围的变化。',Objectives_loc4='对东部符文、东北部符文和西部符文使用符文激活装置。你可以在肯瑞瓦村城镇广场和巫师街周边找到这些符文。完成任务后向巫师上尉莫尔兰复命。',OfferRewardText_loc4='做得好。抓紧你的手，$N。我要启动防护罩了。',RequestItemsText_loc4='你启动了所有的符文了吗?我很急切的想知道是否我们无法改善这里的血精灵秩序。任何凯尔萨斯的手下可以做到的事，真正的肯瑞托可以做的更好。',ObjectiveText1_loc4='激活东部符文',ObjectiveText2_loc4='激活东北部符文',ObjectiveText3_loc4='激活西部符文';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10241,'削弱法力熔炉：布纳尔','沙塔尔派我们来调查凯尔萨斯的军队运转法力熔炉的情况。不幸的是，占星者威胁说，如果我们不派兵支持，他们就拒绝履行信息收集义务。$B$B如果因为政治原因导致任务失败，我们可承担不起这样的后果。因此，我们同意削弱法力熔炉的防御力量，让占星者安全完成他们的工作。$B$B向奥尔多证明你的忠诚吧，去消灭驻守法力熔炉：布纳尔的日怒魔导师和日怒血卫士。','杀死8名日怒魔导师和8名日怒血卫士，然后向52区的大主教欧雷里斯复命。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。','做得好，$N。先知者已经揭露了宝贵的资讯以感谢你的扰乱行动。也许这次他们会真的跟我们分享了。','你完成任务了吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='削弱法力熔炉：布纳尔',Details_loc4='沙塔尔派我们来调查凯尔萨斯的军队运转法力熔炉的情况。不幸的是，占星者威胁说，如果我们不派兵支持，他们就拒绝履行信息收集义务。$B$B如果因为政治原因导致任务失败，我们可承担不起这样的后果。因此，我们同意削弱法力熔炉的防御力量，让占星者安全完成他们的工作。$B$B向奥尔多证明你的忠诚吧，去消灭驻守法力熔炉：布纳尔的日怒魔导师和日怒血卫士。',Objectives_loc4='杀死8名日怒魔导师和8名日怒血卫士，然后向52区的大主教欧雷里斯复命。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。',OfferRewardText_loc4='做得好，$N。先知者已经揭露了宝贵的资讯以感谢你的扰乱行动。也许这次他们会真的跟我们分享了。',RequestItemsText_loc4='你完成任务了吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10242,'断背岗哨','$N，真是可惜，现有的设备无法进行我想要做的血液检测。不过，我可以找断背岗哨的药剂师阿尔布雷克帮忙，他有合适的器械。$B$B我有一份血环兽人的血样，是萨尔玛的间谍执行任务时收集到的。将这份血样交给阿尔布雷克研究研究。$B$B要去断背岗哨的话，跟空军指挥官布拉克谈谈就可以了。他就在南边那群双足飞龙旁边。','机甲残骸的药剂师塞兰娜要你与空军指挥官布拉克谈一谈，搭乘双足飞龙前往断背岗哨，并将血环血样交给断背岗哨的药剂师阿尔布雷克。','一个血液测试，是吗?我很荣幸。我向来喜欢与血为伍……','欢迎来到断脊氏族岗哨。我能帮你什么忙吗?') ON DUPLICATE KEY UPDATE Title_loc4='断背岗哨',Details_loc4='$N，真是可惜，现有的设备无法进行我想要做的血液检测。不过，我可以找断背岗哨的药剂师阿尔布雷克帮忙，他有合适的器械。$B$B我有一份血环兽人的血样，是萨尔玛的间谍执行任务时收集到的。将这份血样交给阿尔布雷克研究研究。$B$B要去断背岗哨的话，跟空军指挥官布拉克谈谈就可以了。他就在南边那群双足飞龙旁边。',Objectives_loc4='机甲残骸的药剂师塞兰娜要你与空军指挥官布拉克谈一谈，搭乘双足飞龙前往断背岗哨，并将血环血样交给断背岗哨的药剂师阿尔布雷克。',OfferRewardText_loc4='一个血液测试，是吗?我很荣幸。我向来喜欢与血为伍……',RequestItemsText_loc4='欢迎来到断脊氏族岗哨。我能帮你什么忙吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10243,'纳鲁科技','占星者得到了一份法力熔炉：布纳尔的人员名册，他们花了一整天时间挑选暗杀目标。$B$B然而，占星者却没有留意到写在名册边上的一串潦草的符号。这些符号似乎是进出像埃索达或是风暴要塞这样的纳鲁建筑物的密码。$B$B进入法力熔炉寻找控制台，将控制台上的读数拓在这个卷轴上。我们必须确认这些符号的来源。','进入法力熔炉：布纳尔，找到布纳尔控制台。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。','你打开了卷轴准备好要将这些怪异的符号复制下来。','这个在你面前出现的符号看起来怪异且难懂。') ON DUPLICATE KEY UPDATE Title_loc4='纳鲁科技',Details_loc4='占星者得到了一份法力熔炉：布纳尔的人员名册，他们花了一整天时间挑选暗杀目标。$B$B然而，占星者却没有留意到写在名册边上的一串潦草的符号。这些符号似乎是进出像埃索达或是风暴要塞这样的纳鲁建筑物的密码。$B$B进入法力熔炉寻找控制台，将控制台上的读数拓在这个卷轴上。我们必须确认这些符号的来源。',Objectives_loc4='进入法力熔炉：布纳尔，找到布纳尔控制台。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。',OfferRewardText_loc4='你打开了卷轴准备好要将这些怪异的符号复制下来。',RequestItemsText_loc4='这个在你面前出现的符号看起来怪异且难懂。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10244,'恶魔抢夺者制造手册R.T.F.R.C.M.','撕开这本厚重书卷上的封印之后，你发现你基本上无法理解上面所书文字的内容。它们似乎是用某种恶魔语所撰写的。$B$B不过，你却能看明白上面的图片，并理解了这些图片所表达的涵义。$B$B很明显，这是一本恶魔劫夺者的建造手册，而且，你知道，威勒妈妈一定非常想看看这本手册！','将恶魔劫夺者制造手册带到虚空风暴的秘境领地里的领地岗哨给威勒妈妈。','恶魔劫夺者制造手册?!你看过它了吗?喔，别在意……没人看过这个手册!$B$B喔喔，虽然我希望我有时间可以仔细研究它。但我们需要将这本书送回52区!','你带来的那本邪恶外表的书是什么?') ON DUPLICATE KEY UPDATE Title_loc4='恶魔抢夺者制造手册R.T.F.R.C.M.',Details_loc4='撕开这本厚重书卷上的封印之后，你发现你基本上无法理解上面所书文字的内容。它们似乎是用某种恶魔语所撰写的。$B$B不过，你却能看明白上面的图片，并理解了这些图片所表达的涵义。$B$B很明显，这是一本恶魔劫夺者的建造手册，而且，你知道，威勒妈妈一定非常想看看这本手册！',Objectives_loc4='将恶魔劫夺者制造手册带到虚空风暴的秘境领地里的领地岗哨给威勒妈妈。',OfferRewardText_loc4='恶魔劫夺者制造手册?!你看过它了吗?喔，别在意……没人看过这个手册!$B$B喔喔，虽然我希望我有时间可以仔细研究它。但我们需要将这本书送回52区!',RequestItemsText_loc4='你带来的那本邪恶外表的书是什么?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10245,'布纳尔控制台拓文','无数图形在你眼前快速掠过，你尝试着拓下它们的形状。卷轴上的拓文虽欠精确，但它们足以证明奥尔多的猜想是否正确了。','将布纳尔控制台拓文交给虚空风暴52区的学者卡尔亚。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。','你做得很好，$N。给我几分钟去看一下你的誊本。$B$B你拥有全体牧师的感谢，$C。','让我们看看你带了什么要给我们，$N。') ON DUPLICATE KEY UPDATE Title_loc4='布纳尔控制台拓文',Details_loc4='无数图形在你眼前快速掠过，你尝试着拓下它们的形状。卷轴上的拓文虽欠精确，但它们足以证明奥尔多的猜想是否正确了。',Objectives_loc4='将布纳尔控制台拓文交给虚空风暴52区的学者卡尔亚。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。',OfferRewardText_loc4='你做得很好，$N。给我几分钟去看一下你的誊本。$B$B你拥有全体牧师的感谢，$C。',RequestItemsText_loc4='让我们看看你带了什么要给我们，$N。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10246,'攻击法力熔炉：库鲁恩','你在法力熔炉：布纳尔获得了令人侧目的成就。我敢肯定学者卡尔亚一定希望你在法力熔炉：库鲁恩也有同样优秀的表现。$B$B最近我们得到消息，一大群地位显赫的日怒奥术师和研究者被派驻到了法力熔炉：库鲁恩，我要你以他们为作战目标。如果你能成功的话，这将是对敌人的一次沉重打击。','前往法力熔炉：库鲁恩，杀死8名日怒奥术师和5名日怒研究员，完成任务后向大主教欧雷里斯复命。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。','做得好，$N。有你的全力奉献我们必定能打败我们的敌人。','完成你的任务了吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='攻击法力熔炉：库鲁恩',Details_loc4='你在法力熔炉：布纳尔获得了令人侧目的成就。我敢肯定学者卡尔亚一定希望你在法力熔炉：库鲁恩也有同样优秀的表现。$B$B最近我们得到消息，一大群地位显赫的日怒奥术师和研究者被派驻到了法力熔炉：库鲁恩，我要你以他们为作战目标。如果你能成功的话，这将是对敌人的一次沉重打击。',Objectives_loc4='前往法力熔炉：库鲁恩，杀死8名日怒奥术师和5名日怒研究员，完成任务后向大主教欧雷里斯复命。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。',OfferRewardText_loc4='做得好，$N。有你的全力奉献我们必定能打败我们的敌人。',RequestItemsText_loc4='完成你的任务了吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10247,'工程学博士沃米萨','城外东边就是实验场。我们的首席实验家沃米萨博士就在那里捣鼓魔能机甲，虚灵科技，当然，还有地精科技。$B$B$N，鉴于你在担任三等见习技师期间的优良表现，我们决定派你过去！$B$B去吧，我相信他能想出拯救52区的办法。$B$B不过，你很可能会成为沃米萨博士的实验品。如果我是你的话，我会带上朋友一同前往实验场，以防万一。','与虚空风暴实验场的工程学博士沃米萨谈一谈。','嗯，嗯，看来我们的运气不错，年轻的$g先生:女士;。$B$B我最近才刚完成建造我的最新发明，废料劫夺者X6000!$B$B而你刚好有这个荣幸可以帮我测试它能否负起保卫52区的责任!','喔，嗯?什么?有什么我能帮助你的吗……我都还不知道你的名字呢!') ON DUPLICATE KEY UPDATE Title_loc4='工程学博士沃米萨',Details_loc4='城外东边就是实验场。我们的首席实验家沃米萨博士就在那里捣鼓魔能机甲，虚灵科技，当然，还有地精科技。$B$B$N，鉴于你在担任三等见习技师期间的优良表现，我们决定派你过去！$B$B去吧，我相信他能想出拯救52区的办法。$B$B不过，你很可能会成为沃米萨博士的实验品。如果我是你的话，我会带上朋友一同前往实验场，以防万一。',Objectives_loc4='与虚空风暴实验场的工程学博士沃米萨谈一谈。',OfferRewardText_loc4='嗯，嗯，看来我们的运气不错，年轻的$g先生:女士;。$B$B我最近才刚完成建造我的最新发明，废料劫夺者X6000!$B$B而你刚好有这个荣幸可以帮我测试它能否负起保卫52区的责任!',RequestItemsText_loc4='喔，嗯?什么?有什么我能帮助你的吗……我都还不知道你的名字呢!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4) VALUES (10248,'你，机器人','工程学博士沃米萨愿意为您效劳！来，拿着这个控制器。我要你启动它，遥控我新造的这台再造机甲X6000型四下转转。$B$B别跑远了！控制器是连接在控制台上的。要是你跑得太远，遥控设备就会停止运转。$B$B记得把所有的功能都测试一下……我会根据实验结果来校准它的随动系统。','启动再造机甲X6000型控制器并测试其性能，灵活应对测试过程中的突发状况。然后向虚空风暴实验场的工程学博士沃米萨汇报实验结果。','嗯，我的$g男孩:女孩;那还真是刺激呀!由于制造它的资金有限，我觉得废料劫夺者X6000的表现非常的棒，尽管那个驾驶是个菜鸟。$B$B嘿嘿，不，别生气，我只是开玩笑而已。毕竟，你刚刚已经把52区还有X-52虚空火箭从毁灭的边缘救回来了!','你觉得如何?是否需要大翻修呢?','完成再造机甲X6000型的测试') ON DUPLICATE KEY UPDATE Title_loc4='你，机器人',Details_loc4='工程学博士沃米萨愿意为您效劳！来，拿着这个控制器。我要你启动它，遥控我新造的这台再造机甲X6000型四下转转。$B$B别跑远了！控制器是连接在控制台上的。要是你跑得太远，遥控设备就会停止运转。$B$B记得把所有的功能都测试一下……我会根据实验结果来校准它的随动系统。',Objectives_loc4='启动再造机甲X6000型控制器并测试其性能，灵活应对测试过程中的突发状况。然后向虚空风暴实验场的工程学博士沃米萨汇报实验结果。',OfferRewardText_loc4='嗯，我的$g男孩:女孩;那还真是刺激呀!由于制造它的资金有限，我觉得废料劫夺者X6000的表现非常的棒，尽管那个驾驶是个菜鸟。$B$B嘿嘿，不，别生气，我只是开玩笑而已。毕竟，你刚刚已经把52区还有X-52虚空火箭从毁灭的边缘救回来了!',RequestItemsText_loc4='你觉得如何?是否需要大翻修呢?',ObjectiveText1_loc4='完成再造机甲X6000型的测试';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10249,'去找火箭主管！','我敢肯定火箭主管有话要对你说！$B$B如果我是你的话，我就会立即返回52区与他谈一谈！','立刻向虚空风暴52区的火箭主管弗斯拉格报到！','$N!或者，我应该说新手技师第一级') ON DUPLICATE KEY UPDATE Title_loc4='去找火箭主管！',Details_loc4='我敢肯定火箭主管有话要对你说！$B$B如果我是你的话，我就会立即返回52区与他谈一谈！',Objectives_loc4='立刻向虚空风暴52区的火箭主管弗斯拉格报到！',OfferRewardText_loc4='$N!或者，我应该说新手技师第一级';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10250,'血之复仇','这里的正东方有一处已被摧毁的联盟攻城塔，现在那里只有一片废墟。很久以前，许多联盟的战士牺牲在那处攻城塔中，而且他们的军旗也被一个邪兽人军官夺取了。$B$B到联盟的军旗下面去吹响这只战斗号角。它会引起乌尔特拉克的注意，也会召来那些在战斗中倒下的士兵。','在联盟战旗附近吹响顽强战斗号角。然后杀死乌尔特拉克，并向断背岗哨的史学家奥尔森复命。','很高兴听到不屈者加入了你的战斗。我以为他们只会听从他们自己的战斗号角，但是我并不确定。也许是因为我们给予他们最渴望的复仇机会。$B$B你已经杀死乌崔克而我们必须向远征队军械库的指挥官霍卡尔斯回报你的胜利消息。他会了解你对他们的付出。','你在攻塔时吹了这个号角了吗?我们必须快点进行这件事。谁知道萨尔玛何时会需要不屈者。') ON DUPLICATE KEY UPDATE Title_loc4='血之复仇',Details_loc4='这里的正东方有一处已被摧毁的联盟攻城塔，现在那里只有一片废墟。很久以前，许多联盟的战士牺牲在那处攻城塔中，而且他们的军旗也被一个邪兽人军官夺取了。$B$B到联盟的军旗下面去吹响这只战斗号角。它会引起乌尔特拉克的注意，也会召来那些在战斗中倒下的士兵。',Objectives_loc4='在联盟战旗附近吹响顽强战斗号角。然后杀死乌尔特拉克，并向断背岗哨的史学家奥尔森复命。',OfferRewardText_loc4='很高兴听到不屈者加入了你的战斗。我以为他们只会听从他们自己的战斗号角，但是我并不确定。也许是因为我们给予他们最渴望的复仇机会。$B$B你已经杀死乌崔克而我们必须向远征队军械库的指挥官霍卡尔斯回报你的胜利消息。他会了解你对他们的付出。',RequestItemsText_loc4='你在攻塔时吹了这个号角了吗?我们必须快点进行这件事。谁知道萨尔玛何时会需要不屈者。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10251,'主人的伟大设计？','昨天夜里，两个德莱尼人拜访了我们。他们不知道从哪里得知了我们拥有那本书的消息，非常慷慨地出了笔大价钱来收购它，说是“帮我们卸下这个大包袱”。$B$B我们没有细问他们要这本书来干嘛，倒是年轻一点的那个一直说什么“主人的伟大设计”，也不知道是什么意思。$B$B只要有钱赚，我才不会多嘴呢。他们给了我们一大笔钱，我们就把书给他们了。$B$B这俩人住在纳格兰废弃的军械库，据说在塔拉北边。','前往纳格兰废弃的军械库寻找博学者尼特林的下落。','征兆一直都在，但是我竟然没看见。$B$B军团的势力每天都变得更强大。即使在这些部分……$B$B要是我知道就好了……要是我知道我的孩子正与恶魔融为一体……他们提供他力量接着让他小试身手。就这样那个孩子沦为恶魔一伍……$B$B书本消失了。被勒威萨斯带走了……他的计划只有我和他的黑暗主人知道。$B$B陌生人，我不知道你这一生当中是否曾经做过对的事，但我知道:必须阻止这孩子。','你……你在找亡者之书吗?它不见了。我弄丢了……') ON DUPLICATE KEY UPDATE Title_loc4='主人的伟大设计？',Details_loc4='昨天夜里，两个德莱尼人拜访了我们。他们不知道从哪里得知了我们拥有那本书的消息，非常慷慨地出了笔大价钱来收购它，说是“帮我们卸下这个大包袱”。$B$B我们没有细问他们要这本书来干嘛，倒是年轻一点的那个一直说什么“主人的伟大设计”，也不知道是什么意思。$B$B只要有钱赚，我才不会多嘴呢。他们给了我们一大笔钱，我们就把书给他们了。$B$B这俩人住在纳格兰废弃的军械库，据说在塔拉北边。',Objectives_loc4='前往纳格兰废弃的军械库寻找博学者尼特林的下落。',OfferRewardText_loc4='征兆一直都在，但是我竟然没看见。$B$B军团的势力每天都变得更强大。即使在这些部分……$B$B要是我知道就好了……要是我知道我的孩子正与恶魔融为一体……他们提供他力量接着让他小试身手。就这样那个孩子沦为恶魔一伍……$B$B书本消失了。被勒威萨斯带走了……他的计划只有我和他的黑暗主人知道。$B$B陌生人，我不知道你这一生当中是否曾经做过对的事，但我知道:必须阻止这孩子。',RequestItemsText_loc4='你……你在找亡者之书吗?它不见了。我弄丢了……';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10252,'亡者的视界','利维休斯已经开始实施他的计划了。他站在奥金顿遗址顶部，诵读着亡者之书。他叫着亡者的名字，将他们召唤出来，然后利用恶魔的仪祭扭曲这些灵魂的意志，使其成为他的仆从。如果不阻止利维休斯的话，他一定会控制奥金顿的所有亡者！$B$B但是……你必须做好充分的准备。你是无法与你看不见的敌人作战的。$B$B<尼特林递给你一张羊皮纸。>$B$B替我找来这些材料，我就为你配制一瓶通灵药剂。它能打开你的心智，让你看到灵魂的世界。','收集1颗山丘戈隆的眼球、1个完美的大型风鹏之喙和1份老迈裂蹄牛的脂肪，然后返回纳格兰废弃的军械库，把它们交给尼特林。','陌生人……我对你并不诚实。一旦你喝了这个药剂，你将永远看得到死者的世界。你喝的配方是给奥齐顿所有死亡祭司的入门祭仪。许多人在它的效用持续发作后发疯了。看见死者是……可怕的。$B$B<奈崔恩将那药剂放到你的嘴唇。>$B$B你想要继续吗?','勒威萨斯的军队每分每秒都在茁壮。你一定要加紧脚步。') ON DUPLICATE KEY UPDATE Title_loc4='亡者的视界',Details_loc4='利维休斯已经开始实施他的计划了。他站在奥金顿遗址顶部，诵读着亡者之书。他叫着亡者的名字，将他们召唤出来，然后利用恶魔的仪祭扭曲这些灵魂的意志，使其成为他的仆从。如果不阻止利维休斯的话，他一定会控制奥金顿的所有亡者！$B$B但是……你必须做好充分的准备。你是无法与你看不见的敌人作战的。$B$B<尼特林递给你一张羊皮纸。>$B$B替我找来这些材料，我就为你配制一瓶通灵药剂。它能打开你的心智，让你看到灵魂的世界。',Objectives_loc4='收集1颗山丘戈隆的眼球、1个完美的大型风鹏之喙和1份老迈裂蹄牛的脂肪，然后返回纳格兰废弃的军械库，把它们交给尼特林。',OfferRewardText_loc4='陌生人……我对你并不诚实。一旦你喝了这个药剂，你将永远看得到死者的世界。你喝的配方是给奥齐顿所有死亡祭司的入门祭仪。许多人在它的效用持续发作后发疯了。看见死者是……可怕的。$B$B<奈崔恩将那药剂放到你的嘴唇。>$B$B你想要继续吗?',RequestItemsText_loc4='勒威萨斯的军队每分每秒都在茁壮。你一定要加紧脚步。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10253,'唤魂者利维休斯','$N，去吧。利维休斯就在奥金顿遗迹的顶部。从白骨荒野南侧进入奥金顿，他被灵魂的风暴围绕着……$B$B杀死利维休斯，夺走亡者之书。一旦你得到那本被诅咒的书，就立即销毁它！一定要销毁它，绝不能让它落入其它野心家手中。','杀死利维休斯，夺得亡者之书。$B$B将亡者之书交给疯狂的拉姆杜尔，他就站在奥金顿的奥金尼地穴入口外。$B$B你们之间有协议的，还记得吗？','如果老德莱尼告诉你把书摧毁，为什么你没做?$B$B<蓝姆多怒视着你。>$B$B呸，有什么差别。你也许是贪婪的不过至少你诚实。$B$B而我在另一方面……我说谎以得到这本书。我不知道这些可怜的失落灵魂将他们的财宝藏在哪里，也不会告诉你我有没有 - 虽然 -','你是谁，你想要干嘛?喔……是你喔。') ON DUPLICATE KEY UPDATE Title_loc4='唤魂者利维休斯',Details_loc4='$N，去吧。利维休斯就在奥金顿遗迹的顶部。从白骨荒野南侧进入奥金顿，他被灵魂的风暴围绕着……$B$B杀死利维休斯，夺走亡者之书。一旦你得到那本被诅咒的书，就立即销毁它！一定要销毁它，绝不能让它落入其它野心家手中。',Objectives_loc4='杀死利维休斯，夺得亡者之书。$B$B将亡者之书交给疯狂的拉姆杜尔，他就站在奥金顿的奥金尼地穴入口外。$B$B你们之间有协议的，还记得吗？',OfferRewardText_loc4='如果老德莱尼告诉你把书摧毁，为什么你没做?$B$B<蓝姆多怒视着你。>$B$B呸，有什么差别。你也许是贪婪的不过至少你诚实。$B$B而我在另一方面……我说谎以得到这本书。我不知道这些可怜的失落灵魂将他们的财宝藏在哪里，也不会告诉你我有没有 - 虽然 -',RequestItemsText_loc4='你是谁，你想要干嘛?喔……是你喔。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10254,'指挥官达纳斯','<伊斯多尔元帅狠狠地对着地面啐了一口。>$B$B好吧，是该拿报酬的时候了，立刻去向城堡内的远征军指挥官达纳斯·托尔贝恩报到。他和他的顾问见到你毫无疑问会非常高兴的。$B$B<伊斯多尔元帅笑着向你敬了个礼。>$B$B为了联盟而战！','伊斯多尔元帅要求你向荣耀堡的远征军指挥官达纳斯·托尔贝恩报到。','很高兴见到你，我的$g兄弟:姐妹;。我很开心你来了。我是达纳斯-洛萨之子的领导者，这个要塞的军队指挥官。') ON DUPLICATE KEY UPDATE Title_loc4='指挥官达纳斯',Details_loc4='<伊斯多尔元帅狠狠地对着地面啐了一口。>$B$B好吧，是该拿报酬的时候了，立刻去向城堡内的远征军指挥官达纳斯·托尔贝恩报到。他和他的顾问见到你毫无疑问会非常高兴的。$B$B<伊斯多尔元帅笑着向你敬了个礼。>$B$B为了联盟而战！',Objectives_loc4='伊斯多尔元帅要求你向荣耀堡的远征军指挥官达纳斯·托尔贝恩报到。',OfferRewardText_loc4='很高兴见到你，我的$g兄弟:姐妹;。我很开心你来了。我是达纳斯-洛萨之子的领导者，这个要塞的军队指挥官。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4) VALUES (10255,'测试解毒剂','我想，我们可以利用本地生物血液中的某些成分来制作解毒药剂。你觉得我疯了吗？别那么看着我好不好！$B$B你要知道，这是自然界中的普遍规律，通常能治愈毒症的成分都是来源于毒素本身，我就是遵循着这个规律在尝试。$B$B将这些野猪身上的恶魔力量祛除之后，或许它们就不会再这样具有攻击性了。我们也可以借机仔细地观察一下净化的过程和状况，看看怎样才能更好地帮助其它物种。','对笨拙的地狱野猪使用塞纳里奥解毒剂，并观察解毒剂的效果。然后返回地狱火半岛的塞纳里奥哨站，向塞安·红鬃汇报实验的结果。','<当你描述了实验的结果，塞伊亚.红发瞪大了眼睛。>$B$B这，这怎么可能呢?我确定我正确的调配了解毒剂!$B$B它明明就可以解开蜘蛛还有蛇的毒液，那么为什么这次会失败呢?也许是外域的差异性造成的吧，$N。我最好把这项讯息传递给其它的同伴们知道。','你知道实验的结果了吗?','测试解毒剂') ON DUPLICATE KEY UPDATE Title_loc4='测试解毒剂',Details_loc4='我想，我们可以利用本地生物血液中的某些成分来制作解毒药剂。你觉得我疯了吗？别那么看着我好不好！$B$B你要知道，这是自然界中的普遍规律，通常能治愈毒症的成分都是来源于毒素本身，我就是遵循着这个规律在尝试。$B$B将这些野猪身上的恶魔力量祛除之后，或许它们就不会再这样具有攻击性了。我们也可以借机仔细地观察一下净化的过程和状况，看看怎样才能更好地帮助其它物种。',Objectives_loc4='对笨拙的地狱野猪使用塞纳里奥解毒剂，并观察解毒剂的效果。然后返回地狱火半岛的塞纳里奥哨站，向塞安·红鬃汇报实验的结果。',OfferRewardText_loc4='<当你描述了实验的结果，塞伊亚.红发瞪大了眼睛。>$B$B这，这怎么可能呢?我确定我正确的调配了解毒剂!$B$B它明明就可以解开蜘蛛还有蛇的毒液，那么为什么这次会失败呢?也许是外域的差异性造成的吧，$N。我最好把这项讯息传递给其它的同伴们知道。',RequestItemsText_loc4='你知道实验的结果了吗?',ObjectiveText1_loc4='测试解毒剂';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4) VALUES (10256,'钥匙的主人','回想起来，我真该预料到凯尔萨斯拥有如此强大的魔法能力。他是一位很有天份的法师，然而凯尔袭击肯瑞瓦村的那天，他所使用的法术完全超出了我的想象。$B$B凯尔萨斯施加在紫罗兰之塔的结界令我无法探察周围的敌情，不过好在它还不能阻止你来替我完成这项工作。$B$B但是你首先得搞到一块透镜。法力熔炉：杜隆以西的平原生活着一位名叫阿匹克斯的巨人，他身上有质地非常不错的水晶，我们可以利用这种水晶制成探知透镜。','找到阿匹克斯并夺得阿匹克斯的聚焦水晶，然后返回紫罗兰之塔，在大法师瓦格斯的宝珠旁使用阿匹克斯的聚焦水晶，查明破除塔内诅咒的钥匙在谁手中。','<你描述了你占卜的结果。>$B$B你是说，指挥官萨瑞尼斯?嗯……$B$B她是凯尔萨斯的顾问之一，但一定不是位法师。我从那次肯瑞瓦村庄的攻击中记起她。我认为你的想法是对的，$N。她不用亲自维持咒语，但是她可以拥有它的钥匙。','你的水晶球告诉你什么?','查明钥匙在谁手中') ON DUPLICATE KEY UPDATE Title_loc4='钥匙的主人',Details_loc4='回想起来，我真该预料到凯尔萨斯拥有如此强大的魔法能力。他是一位很有天份的法师，然而凯尔袭击肯瑞瓦村的那天，他所使用的法术完全超出了我的想象。$B$B凯尔萨斯施加在紫罗兰之塔的结界令我无法探察周围的敌情，不过好在它还不能阻止你来替我完成这项工作。$B$B但是你首先得搞到一块透镜。法力熔炉：杜隆以西的平原生活着一位名叫阿匹克斯的巨人，他身上有质地非常不错的水晶，我们可以利用这种水晶制成探知透镜。',Objectives_loc4='找到阿匹克斯并夺得阿匹克斯的聚焦水晶，然后返回紫罗兰之塔，在大法师瓦格斯的宝珠旁使用阿匹克斯的聚焦水晶，查明破除塔内诅咒的钥匙在谁手中。',OfferRewardText_loc4='<你描述了你占卜的结果。>$B$B你是说，指挥官萨瑞尼斯?嗯……$B$B她是凯尔萨斯的顾问之一，但一定不是位法师。我从那次肯瑞瓦村庄的攻击中记起她。我认为你的想法是对的，$N。她不用亲自维持咒语，但是她可以拥有它的钥匙。',RequestItemsText_loc4='你的水晶球告诉你什么?',ObjectiveText1_loc4='查明钥匙在谁手中';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10257,'夺回钥石','凯尔萨斯将钥石交给指挥官萨拉妮丝这样的人保管，我一点都不觉得惊讶。凯尔萨斯王子在许多方面都非常优秀，他绝对不是傻子。$B$B为了永久破除这个诅咒，你必须杀入风暴要塞夺回钥石。$B$B一旦钥石被摧毁，我就能重获久违的自由。','进入风暴要塞的生态船，从指挥官萨拉妮丝手中夺得钥石，将它交给紫罗兰之塔的大法师瓦格斯。','<当你把石头交给他时，大法师的眼睛发亮。>$B$B真是惊人!根据我所看到的少许关于法拉隆德的命运，我不确定我想要出去了，但是这会比我困在这里度过馀生来得好多了。','你拿到拱心石了吗?') ON DUPLICATE KEY UPDATE Title_loc4='夺回钥石',Details_loc4='凯尔萨斯将钥石交给指挥官萨拉妮丝这样的人保管，我一点都不觉得惊讶。凯尔萨斯王子在许多方面都非常优秀，他绝对不是傻子。$B$B为了永久破除这个诅咒，你必须杀入风暴要塞夺回钥石。$B$B一旦钥石被摧毁，我就能重获久违的自由。',Objectives_loc4='进入风暴要塞的生态船，从指挥官萨拉妮丝手中夺得钥石，将它交给紫罗兰之塔的大法师瓦格斯。',OfferRewardText_loc4='<当你把石头交给他时，大法师的眼睛发亮。>$B$B真是惊人!根据我所看到的少许关于法拉隆德的命运，我不确定我想要出去了，但是这会比我困在这里度过馀生来得好多了。',RequestItemsText_loc4='你拿到拱心石了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10258,'逝者的荣耀','物资库的指挥官霍加斯在东边的那座塔中徘徊。你一定要把干掉乌尔特拉克的消息告诉他，也许这样他就会对你友好些，当然，也许……他可能会干脆吞噬你的灵魂。我们是永远无法了解一个幽灵的感情的。$B$B阴魂仍然对我们保持着敌对态度，他们很有可能会杀了你。千万小心，$N。','向远征军物资库的指挥官霍加斯报到。','我们在很久以前的战争中输给了邪兽人。你杀了乌崔克帮我们赢回了一点自尊。$B$B从我们的武器之中选一把带着吧。当你跟我们最痛恨的敌人战斗的时候，使用这个武器，那么从我们的诅咒之中脱离的战友将会赶来协助你。$B$B在你离开之前，曾经在围攻哨塔战死的同伴们想要表扬你消灭了我们的敌人。','你是谁还有你想要从这个被诅咒的地方得到什么?这里不欢迎活人。') ON DUPLICATE KEY UPDATE Title_loc4='逝者的荣耀',Details_loc4='物资库的指挥官霍加斯在东边的那座塔中徘徊。你一定要把干掉乌尔特拉克的消息告诉他，也许这样他就会对你友好些，当然，也许……他可能会干脆吞噬你的灵魂。我们是永远无法了解一个幽灵的感情的。$B$B阴魂仍然对我们保持着敌对态度，他们很有可能会杀了你。千万小心，$N。',Objectives_loc4='向远征军物资库的指挥官霍加斯报到。',OfferRewardText_loc4='我们在很久以前的战争中输给了邪兽人。你杀了乌崔克帮我们赢回了一点自尊。$B$B从我们的武器之中选一把带着吧。当你跟我们最痛恨的敌人战斗的时候，使用这个武器，那么从我们的诅咒之中脱离的战友将会赶来协助你。$B$B在你离开之前，曾经在围攻哨塔战死的同伴们想要表扬你消灭了我们的敌人。',RequestItemsText_loc4='你是谁还有你想要从这个被诅咒的地方得到什么?这里不欢迎活人。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10259,'勇往直前','黑暗之门战事迭起！银色黎明正在拼死奋战，一旦他们战败，恶魔的火焰就将烧遍整个世界。$B$B帮帮我们吧，$N。前往黑暗之门，伸出援手，与我们的兄弟姐妹并肩作战。阻止这可怕的黑暗之潮！银色黎明需要你，艾泽拉斯需要你！','杀死6个入侵的恶魔卫士，然后向银色使者普罗维尔复命。','谢谢你，$N。在战斗的混乱中，英雄燃烧光明对抗黑暗。你的圣光确实闪耀着!','再次进入裂缝里吧，我的朋友!') ON DUPLICATE KEY UPDATE Title_loc4='勇往直前',Details_loc4='黑暗之门战事迭起！银色黎明正在拼死奋战，一旦他们战败，恶魔的火焰就将烧遍整个世界。$B$B帮帮我们吧，$N。前往黑暗之门，伸出援手，与我们的兄弟姐妹并肩作战。阻止这可怕的黑暗之潮！银色黎明需要你，艾泽拉斯需要你！',Objectives_loc4='杀死6个入侵的恶魔卫士，然后向银色使者普罗维尔复命。',OfferRewardText_loc4='谢谢你，$N。在战斗的混乱中，英雄燃烧光明对抗黑暗。你的圣光确实闪耀着!',RequestItemsText_loc4='再次进入裂缝里吧，我的朋友!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10260,'虚空学家卡伯尼寇斯','你一定是穿过了那座由刀锋山连接虚空风暴的桥才来到这里的。你也一定看见Netherologist Coppernickels和他那些疯狂的研究装备了吧？$B$B奇怪……我还在等着他的报告呢，已经迟到太久太久了。他一定是把这事给忘记了。你知道那些“科学家”的，忙起来什么都忘了。$B$B立刻回到桥边帮我逮住他，马上要来他的报告，无论他说什么借口都不行。$B$B谢谢你了！','前往刀锋山与虚空风暴相连接的桥边寻找Netherologist Coppernickels，并与他交谈。','火箭主管夫斯拉吉?你提到报告吗?$B$B啊，没错，当然罗!他真是没有耐心，对吧?','什么?嗯嗯?那是什么?') ON DUPLICATE KEY UPDATE Title_loc4='虚空学家卡伯尼寇斯',Details_loc4='你一定是穿过了那座由刀锋山连接虚空风暴的桥才来到这里的。你也一定看见Netherologist Coppernickels和他那些疯狂的研究装备了吧？$B$B奇怪……我还在等着他的报告呢，已经迟到太久太久了。他一定是把这事给忘记了。你知道那些“科学家”的，忙起来什么都忘了。$B$B立刻回到桥边帮我逮住他，马上要来他的报告，无论他说什么借口都不行。$B$B谢谢你了！',Objectives_loc4='前往刀锋山与虚空风暴相连接的桥边寻找Netherologist Coppernickels，并与他交谈。',OfferRewardText_loc4='火箭主管夫斯拉吉?你提到报告吗?$B$B啊，没错，当然罗!他真是没有耐心，对吧?',RequestItemsText_loc4='什么?嗯嗯?那是什么?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10261,'悬赏：歼灭者机械臂','悬赏：我需要一根歼灭者机械臂来替换长管光谱分析仪中损坏的零件。$B$B你和你的朋友可以去西边的法力熔炉：布纳尔，看看那里的血精灵是否有这类备用零件。法力熔炉中似乎有奥术歼灭者活动。$B$B请将一根品质完好的歼灭者机械臂交给52区的维勒老爹。','将一根歼灭者机械臂交给虚空风暴52区的维勒老爹。','喔呵!你知道要得到这些东西有多难吗?这跟我在这里收到的普通零件可不一样。$B$B告诉你吧，我要你从我的旧货盒中拿取一样东西做为报酬。我相信那里有你可以用得东西。如果不是的话，就卖掉吧。$B$B好了，让我从你手中接过这样东西并在这个坏掉的伺服电动机爆炸前放进我的长颈光谱分析器中。','我希望你是来关切我张贴的悬赏布告!') ON DUPLICATE KEY UPDATE Title_loc4='悬赏：歼灭者机械臂',Details_loc4='悬赏：我需要一根歼灭者机械臂来替换长管光谱分析仪中损坏的零件。$B$B你和你的朋友可以去西边的法力熔炉：布纳尔，看看那里的血精灵是否有这类备用零件。法力熔炉中似乎有奥术歼灭者活动。$B$B请将一根品质完好的歼灭者机械臂交给52区的维勒老爹。',Objectives_loc4='将一根歼灭者机械臂交给虚空风暴52区的维勒老爹。',OfferRewardText_loc4='喔呵!你知道要得到这些东西有多难吗?这跟我在这里收到的普通零件可不一样。$B$B告诉你吧，我要你从我的旧货盒中拿取一样东西做为报酬。我相信那里有你可以用得东西。如果不是的话，就卖掉吧。$B$B好了，让我从你手中接过这样东西并在这个坏掉的伺服电动机爆炸前放进我的长颈光谱分析器中。',RequestItemsText_loc4='我希望你是来关切我张贴的悬赏布告!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10262,'叛徒的徽记','我还有件事要你帮忙。$B$B一个名叫萨克希斯的虚灵组织已经脱离了星界财团，经营起自己的生意来。他们居然和日怒血精灵有贸易往来，我无法容忍这种行径！$B$B我偷偷潜入了南边的机甲废场，那里就是萨克希斯虚灵的营地。在干掉了他们的领袖之后，我不得不逃回52区。$B$B$C，返回机甲废场，把他们的徽记带回来给我。当然，你不必赶尽杀绝，给他们点颜色瞧瞧就可以了，这帮家伙全是懦夫。','收集10枚萨克希斯徽记，将它们交给虚空风暴52区的虚空猎手卡尔伊。','这些徽记是一个好开始。$B$B不幸的是，当你在聚集之地时，我在萨希斯的其它密探其中之一捎话给我，星移劫掠者尼萨德还活着!','完成了吗?你有除去外域的萨希斯渣滓，并将他们的徽记带来给我了吗?') ON DUPLICATE KEY UPDATE Title_loc4='叛徒的徽记',Details_loc4='我还有件事要你帮忙。$B$B一个名叫萨克希斯的虚灵组织已经脱离了星界财团，经营起自己的生意来。他们居然和日怒血精灵有贸易往来，我无法容忍这种行径！$B$B我偷偷潜入了南边的机甲废场，那里就是萨克希斯虚灵的营地。在干掉了他们的领袖之后，我不得不逃回52区。$B$B$C，返回机甲废场，把他们的徽记带回来给我。当然，你不必赶尽杀绝，给他们点颜色瞧瞧就可以了，这帮家伙全是懦夫。',Objectives_loc4='收集10枚萨克希斯徽记，将它们交给虚空风暴52区的虚空猎手卡尔伊。',OfferRewardText_loc4='这些徽记是一个好开始。$B$B不幸的是，当你在聚集之地时，我在萨希斯的其它密探其中之一捎话给我，星移劫掠者尼萨德还活着!',RequestItemsText_loc4='完成了吗?你有除去外域的萨希斯渣滓，并将他们的徽记带来给我了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10263,'协助星界财团','沙塔斯城的纳鲁一直在寻找着某种能够改变星界财团审事态度的方式。$B$B走运的是，最近这些虚灵和虚空风暴的血精灵们在生意场日益敌对起来，于是我们就有了机会。$B$B星界财团在镇上有一名代表，名叫虚空猎手卡尔伊，他最近惹上了一群变节的虚灵。作为奥尔多的代表，我希望你能去向他提供帮助，让他成为我们的朋友。','到虚空风暴去，与52区的虚空猎手卡尔伊谈一谈。','你好，$r。$B$B你该不是碰巧有空可以进行一个有点重要的修复任务吧?') ON DUPLICATE KEY UPDATE Title_loc4='协助星界财团',Details_loc4='沙塔斯城的纳鲁一直在寻找着某种能够改变星界财团审事态度的方式。$B$B走运的是，最近这些虚灵和虚空风暴的血精灵们在生意场日益敌对起来，于是我们就有了机会。$B$B星界财团在镇上有一名代表，名叫虚空猎手卡尔伊，他最近惹上了一群变节的虚灵。作为奥尔多的代表，我希望你能去向他提供帮助，让他成为我们的朋友。',Objectives_loc4='到虚空风暴去，与52区的虚空猎手卡尔伊谈一谈。',OfferRewardText_loc4='你好，$r。$B$B你该不是碰巧有空可以进行一个有点重要的修复任务吧?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10264,'协助星界财团','沙塔斯城的纳鲁一直在寻找着某种能够改变星界财团审事态度的方式。$B$B走运的是，最近这些虚灵和虚空风暴的血精灵们在生意场日益敌对起来，于是我们就有了机会。$B$B星界财团在镇上有一名代表，名叫虚空猎手卡尔伊，他最近惹上了一群变节的虚灵。作为占星者的代表，我希望你能去向他提供帮助，让他成为我们的朋友。','到虚空风暴去，与52区的虚空猎手卡尔伊谈一谈。','你好，$r。$B$B你该不是碰巧有空可以进行一个有点重要的修复任务吧?') ON DUPLICATE KEY UPDATE Title_loc4='协助星界财团',Details_loc4='沙塔斯城的纳鲁一直在寻找着某种能够改变星界财团审事态度的方式。$B$B走运的是，最近这些虚灵和虚空风暴的血精灵们在生意场日益敌对起来，于是我们就有了机会。$B$B星界财团在镇上有一名代表，名叫虚空猎手卡尔伊，他最近惹上了一群变节的虚灵。作为占星者的代表，我希望你能去向他提供帮助，让他成为我们的朋友。',Objectives_loc4='到虚空风暴去，与52区的虚空猎手卡尔伊谈一谈。',OfferRewardText_loc4='你好，$r。$B$B你该不是碰巧有空可以进行一个有点重要的修复任务吧?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10265,'星界财团的水晶','我们的领袖——节点亲王哈拉迈德派我前往东南方的阿尔科隆废墟，取回一件水晶神器。$B$B那里是一处古老的德莱尼文明废墟，我和此地的地精遇到了同样的麻烦：燃烧军团已经进驻阿尔科隆废墟并启动了挖掘工事。$B$B如果你愿意帮助我的话，就进入废墟将那件水晶神器从恐惧魔王匹塔塞隆手中抢回来吧。','将一件阿尔科隆水晶神器交给虚空风暴52区的虚空猎手卡尔伊。','让我看一下那东西。$B$B嗯，看来似乎没有什么特别的。我怀疑这就是那个东西吗，虽然你所描述燃烧军团在废墟活动的方式，听起来好像他们正在寻找某些特别的东西。$B$B让我们期望这不会是节点亲王那么想拥有的水晶。','我有印象王子正在寻找一颗特别的水晶，但是我不确定它是什么。$B$B你已经从惊惧领主那拿到一个了吗?') ON DUPLICATE KEY UPDATE Title_loc4='星界财团的水晶',Details_loc4='我们的领袖——节点亲王哈拉迈德派我前往东南方的阿尔科隆废墟，取回一件水晶神器。$B$B那里是一处古老的德莱尼文明废墟，我和此地的地精遇到了同样的麻烦：燃烧军团已经进驻阿尔科隆废墟并启动了挖掘工事。$B$B如果你愿意帮助我的话，就进入废墟将那件水晶神器从恐惧魔王匹塔塞隆手中抢回来吧。',Objectives_loc4='将一件阿尔科隆水晶神器交给虚空风暴52区的虚空猎手卡尔伊。',OfferRewardText_loc4='让我看一下那东西。$B$B嗯，看来似乎没有什么特别的。我怀疑这就是那个东西吗，虽然你所描述燃烧军团在废墟活动的方式，听起来好像他们正在寻找某些特别的东西。$B$B让我们期望这不会是节点亲王那么想拥有的水晶。',RequestItemsText_loc4='我有印象王子正在寻找一颗特别的水晶，但是我不确定它是什么。$B$B你已经从惊惧领主那拿到一个了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10266,'寻求帮助','在你前往阿尔科隆废墟执行任务时，我收到了本地区另一位虚灵特使的支持请求。似乎血精灵拒绝支付货款，星界财团在夺回财产的事情上遇到了一些“麻烦”。$B$B出了52区后沿着东边的道路走，过了桥便是一座浮岛，岛上的中央生态圆顶内设有一座哨站。你可以在哨站中找到我的同事加鲁斯。','前往虚空风暴中央生态圆顶的中央圆顶哨站，找到加鲁斯并为他效力。','没错，是真的。血精灵在另一批已经送达的货物买卖上食言了。$B$B因为虚空巡者凯泽对你的保证，我希望你能在这件事情上协助我。') ON DUPLICATE KEY UPDATE Title_loc4='寻求帮助',Details_loc4='在你前往阿尔科隆废墟执行任务时，我收到了本地区另一位虚灵特使的支持请求。似乎血精灵拒绝支付货款，星界财团在夺回财产的事情上遇到了一些“麻烦”。$B$B出了52区后沿着东边的道路走，过了桥便是一座浮岛，岛上的中央生态圆顶内设有一座哨站。你可以在哨站中找到我的同事加鲁斯。',Objectives_loc4='前往虚空风暴中央生态圆顶的中央圆顶哨站，找到加鲁斯并为他效力。',OfferRewardText_loc4='没错，是真的。血精灵在另一批已经送达的货物买卖上食言了。$B$B因为虚空巡者凯泽对你的保证，我希望你能在这件事情上协助我。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10267,'贸易终结','我们与血精灵之间的贸易关系看来就此终结了。几周前，我们按订货单为法力熔炉：杜隆送去了一批探测设备，但是血精灵拒绝付款。$B$B$N，我要你去东边的法力熔炉：杜隆跑一趟。他们似乎正为肆虐的法力生物烦恼不已，你可以趁机混入法力熔炉。$B$B我根本不关心他们的境遇，我只想取回星界财团的财产。','收集10箱测量装置，然后返回虚空风暴中央生态圆顶的中央圆顶哨站，将它们交给加鲁斯。','嗯，我个人对于解决了这桩小生意感到很开心。我不记得何时联合团与那样粗野且无法信任的生物交易过。$B$B不过，你好像很值得信任，$N。或许你不介意帮我更多的忙?','你拿到那些血精灵拖欠的调查设备了吗?') ON DUPLICATE KEY UPDATE Title_loc4='贸易终结',Details_loc4='我们与血精灵之间的贸易关系看来就此终结了。几周前，我们按订货单为法力熔炉：杜隆送去了一批探测设备，但是血精灵拒绝付款。$B$B$N，我要你去东边的法力熔炉：杜隆跑一趟。他们似乎正为肆虐的法力生物烦恼不已，你可以趁机混入法力熔炉。$B$B我根本不关心他们的境遇，我只想取回星界财团的财产。',Objectives_loc4='收集10箱测量装置，然后返回虚空风暴中央生态圆顶的中央圆顶哨站，将它们交给加鲁斯。',OfferRewardText_loc4='嗯，我个人对于解决了这桩小生意感到很开心。我不记得何时联合团与那样粗野且无法信任的生物交易过。$B$B不过，你好像很值得信任，$N。或许你不介意帮我更多的忙?',RequestItemsText_loc4='你拿到那些血精灵拖欠的调查设备了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10268,'与节点亲王会面','节点亲王哈拉迈德刚刚派来特使向我转达了他的意愿，亲王殿下希望我们立刻将这件无价之宝归还到他本人手中。如果你能帮我跑这一趟的话，我会由衷地感激你。$B$B能够得到节点亲王的召见将是无上的荣耀，我相信他会非常乐意聆听你在虚空风暴的冒险故事。$B$B前往北边的风暴尖塔吧，亲王将在塔顶的大厅中接见你。哦，你可能会注意到，他通常以全息影像的方式现身。','前往虚空风暴的风暴尖塔，将测量装置交给节点亲王哈拉迈德的影像。','欢迎来到风暴之尖，$C。请享用联合团的殷勤招待。$B$B你可以将那个设备放在任何地方。我猜你可能很快地就要背起它了。','靠近。') ON DUPLICATE KEY UPDATE Title_loc4='与节点亲王会面',Details_loc4='节点亲王哈拉迈德刚刚派来特使向我转达了他的意愿，亲王殿下希望我们立刻将这件无价之宝归还到他本人手中。如果你能帮我跑这一趟的话，我会由衷地感激你。$B$B能够得到节点亲王的召见将是无上的荣耀，我相信他会非常乐意聆听你在虚空风暴的冒险故事。$B$B前往北边的风暴尖塔吧，亲王将在塔顶的大厅中接见你。哦，你可能会注意到，他通常以全息影像的方式现身。',Objectives_loc4='前往虚空风暴的风暴尖塔，将测量装置交给节点亲王哈拉迈德的影像。',OfferRewardText_loc4='欢迎来到风暴之尖，$C。请享用联合团的殷勤招待。$B$B你可以将那个设备放在任何地方。我猜你可能很快地就要背起它了。',RequestItemsText_loc4='靠近。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,EndText_loc4) VALUES (10269,'一号三角点','还有一个原因让我们必须取回那些测量装置。德莱尼人的传说中曾提到一颗神奇的水晶，它对我来说非常重要。$B$B据说这颗水晶中蕴藏着能与神祗媲美的力量！但现在，它很可能落入了燃烧军团的手中。$B$B$N，利用测量仪找到第一个三角点。我想它应该在法力熔炉：乌提斯以东的某个地方。$B$B找到之后，与法力熔炉：乌提斯所在的浮岛上的商人哈斯辛谈一谈，他是我派驻在那里的代理人。','利用三角测量仪找到一号三角点。找到之后，立刻前往虚空风暴法力熔炉：乌提斯的维序派哨站，向商人哈斯辛汇报三角点的位置。','<商人海辛降低他的声音变成耳语一般。>$B$B啊，我知道你的任务。这对节点亲王哈拉迈德来说非常重要!$B$B既然我们知道第一个三角测量点的位置，你必须迅速动身去找到第二个!','你好啊，旅人。你到海辛这来是想要买我的商品吗?','找到一号三角测量点') ON DUPLICATE KEY UPDATE Title_loc4='一号三角点',Details_loc4='还有一个原因让我们必须取回那些测量装置。德莱尼人的传说中曾提到一颗神奇的水晶，它对我来说非常重要。$B$B据说这颗水晶中蕴藏着能与神祗媲美的力量！但现在，它很可能落入了燃烧军团的手中。$B$B$N，利用测量仪找到第一个三角点。我想它应该在法力熔炉：乌提斯以东的某个地方。$B$B找到之后，与法力熔炉：乌提斯所在的浮岛上的商人哈斯辛谈一谈，他是我派驻在那里的代理人。',Objectives_loc4='利用三角测量仪找到一号三角点。找到之后，立刻前往虚空风暴法力熔炉：乌提斯的维序派哨站，向商人哈斯辛汇报三角点的位置。',OfferRewardText_loc4='<商人海辛降低他的声音变成耳语一般。>$B$B啊，我知道你的任务。这对节点亲王哈拉迈德来说非常重要!$B$B既然我们知道第一个三角测量点的位置，你必须迅速动身去找到第二个!',RequestItemsText_loc4='你好啊，旅人。你到海辛这来是想要买我的商品吗?',EndText_loc4='找到一号三角测量点';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10270,'不太谦虚的提议','从你脸上的神色我看得出，你是个擅长为自己谋取利益的$r。$B$B我是位小有名气的特种货物贸易商，最近我正打算展开一段新的冒险。$B$B眼下，我需要一名可靠的下线帮我从苍穹之脊搞些货物来，不知你意下如何？$B$B首先，你需要给传送器补充能量。在法力熔炉：乌提斯南侧的瑟安竖井处有一套备用的能量包，你可以利用它来充能。维序派正在那一带活动，你可以根据他们留下的踪迹行动。','取回传送器能量包，将它带至法力熔炉：乌提斯东边苍穹之脊上的虚灵传送器。激活传送器，然后将传送器能量包交给星界商人玛里德的影像，让他进行安装。','这个电池应该要为了我们的目标保留。一旦钱进帐后，我们就能将它改良得更好。$B$B有这样的东西就够了。每个讨论的片段都会造成利益的损失。','你准备好现在谈生意了吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='不太谦虚的提议',Details_loc4='从你脸上的神色我看得出，你是个擅长为自己谋取利益的$r。$B$B我是位小有名气的特种货物贸易商，最近我正打算展开一段新的冒险。$B$B眼下，我需要一名可靠的下线帮我从苍穹之脊搞些货物来，不知你意下如何？$B$B首先，你需要给传送器补充能量。在法力熔炉：乌提斯南侧的瑟安竖井处有一套备用的能量包，你可以利用它来充能。维序派正在那一带活动，你可以根据他们留下的踪迹行动。',Objectives_loc4='取回传送器能量包，将它带至法力熔炉：乌提斯东边苍穹之脊上的虚灵传送器。激活传送器，然后将传送器能量包交给星界商人玛里德的影像，让他进行安装。',OfferRewardText_loc4='这个电池应该要为了我们的目标保留。一旦钱进帐后，我们就能将它改良得更好。$B$B有这样的东西就够了。每个讨论的片段都会造成利益的损失。',RequestItemsText_loc4='你准备好现在谈生意了吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10271,'重要生意','你肯定已经看见了，这一带生活着许多处于不同生长阶段的虚空龙。无论是幼龙还是成年虚空龙，体内都蕴涵着某种精华。凯……呃，我的一名客户迫切地想要得到它。$B$B大多数人都不敢冒着生命危险来收集龙类精华，因此我们只能自己动手啦。你可以从虚空龙身上收集到这种精华，但关键问题在于我们是否能联手创建起一条稳定的供应渠道。这样，你搞到第一批之后就立即带回来给我。','收集8份虚空龙类精华，然后返回虚灵传送器区域。你可以从虚空幼龙或虚空之龙身上收集到虚空龙类精华。','想想看，卑鄙的以太族要把这些精华像糖果一样卖给血精灵……','我相信你会有很多问题，所有的问题都会在适当的时间得到回答。') ON DUPLICATE KEY UPDATE Title_loc4='重要生意',Details_loc4='你肯定已经看见了，这一带生活着许多处于不同生长阶段的虚空龙。无论是幼龙还是成年虚空龙，体内都蕴涵着某种精华。凯……呃，我的一名客户迫切地想要得到它。$B$B大多数人都不敢冒着生命危险来收集龙类精华，因此我们只能自己动手啦。你可以从虚空龙身上收集到这种精华，但关键问题在于我们是否能联手创建起一条稳定的供应渠道。这样，你搞到第一批之后就立即带回来给我。',Objectives_loc4='收集8份虚空龙类精华，然后返回虚灵传送器区域。你可以从虚空幼龙或虚空之龙身上收集到虚空龙类精华。',OfferRewardText_loc4='想想看，卑鄙的以太族要把这些精华像糖果一样卖给血精灵……',RequestItemsText_loc4='我相信你会有很多问题，所有的问题都会在适当的时间得到回答。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10272,'成功的开始','谣传此地近来有奇异的龙族血脉出现，我们正是来调查此事真实性的，据说它们可能是死亡之翼的后代。不过，这些龙显然不是普通的黑龙。$B$B如果有机会检查它们的卵，或许我们就能了解到更多秘密。这些虚空龙非常仇视蓝龙，因此我根本无法接近它们的卵，你能帮帮我吗？','收集15枚虚空龙卵，然后向苍穹之脊的泰莉和乔拉德复命。','这些蛋会得到良好的运用，$N。谢谢你同意帮助我们。$B$B不过，在我们继续之前，还有其它事情需要我们先处理。','你可以去收集蛋吗?') ON DUPLICATE KEY UPDATE Title_loc4='成功的开始',Details_loc4='谣传此地近来有奇异的龙族血脉出现，我们正是来调查此事真实性的，据说它们可能是死亡之翼的后代。不过，这些龙显然不是普通的黑龙。$B$B如果有机会检查它们的卵，或许我们就能了解到更多秘密。这些虚空龙非常仇视蓝龙，因此我根本无法接近它们的卵，你能帮帮我吗？',Objectives_loc4='收集15枚虚空龙卵，然后向苍穹之脊的泰莉和乔拉德复命。',OfferRewardText_loc4='这些蛋会得到良好的运用，$N。谢谢你同意帮助我们。$B$B不过，在我们继续之前，还有其它事情需要我们先处理。',RequestItemsText_loc4='你可以去收集蛋吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10273,'棘手的目标','你之前的雇主——星界商人玛里德一定听到了风声，知道你正在帮助我们。通过投影，我发现他手下的虚空猎手已经进入了这片地区，想要搜寻我们的下落。$B$B到目前为止，我们总能成功地躲避猎手的攻击；但是为了避免事情闹到不可收拾的地步，你必须先发制人，替我们铲除玛里德。$B$B如果你了解玛里德的话，就会明白这家伙肯定会不惜代价地确保货物供应线的安全。回去找他吧，告诉他你要和他做笔交易。将玛里德引离商栈，然后杀死他。','与星界商人玛里德谈一谈，诱使他离开商栈。杀死玛里德后向苍穹之脊的泰莉和乔拉德复命。','既然那令人讨厌的以太族已经被解决掉了，我们可以努力专注去了解这些虚空龙了。我有一个机会可以去检查这些蛋，而且我得到了一些发现。','这个玛利德是个笨蛋，或者我该说，曾经是个笨蛋。') ON DUPLICATE KEY UPDATE Title_loc4='棘手的目标',Details_loc4='你之前的雇主——星界商人玛里德一定听到了风声，知道你正在帮助我们。通过投影，我发现他手下的虚空猎手已经进入了这片地区，想要搜寻我们的下落。$B$B到目前为止，我们总能成功地躲避猎手的攻击；但是为了避免事情闹到不可收拾的地步，你必须先发制人，替我们铲除玛里德。$B$B如果你了解玛里德的话，就会明白这家伙肯定会不惜代价地确保货物供应线的安全。回去找他吧，告诉他你要和他做笔交易。将玛里德引离商栈，然后杀死他。',Objectives_loc4='与星界商人玛里德谈一谈，诱使他离开商栈。杀死玛里德后向苍穹之脊的泰莉和乔拉德复命。',OfferRewardText_loc4='既然那令人讨厌的以太族已经被解决掉了，我们可以努力专注去了解这些虚空龙了。我有一个机会可以去检查这些蛋，而且我得到了一些发现。',RequestItemsText_loc4='这个玛利德是个笨蛋，或者我该说，曾经是个笨蛋。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4) VALUES (10274,'占领苍穹之脊','虚空龙的性情与它们的黑龙同宗一样凶暴而狂躁，但也有一些截然不同的地方。虚空龙的孵化期和成长期十分短暂，身上涌动着奇特的能量。这种能量流是在德拉诺世界毁灭的时候产生的，从而导致了虚空龙这一族群的诞生。$B$B我还需要了解更多的细节，我相信这种能量可以为蓝龙所用。如果我能取代这些虚空龙的领袖维拉库，充分展示我的统御力，我们就能令其它虚空龙屈服。','前往苍穹之脊的南端，使用蓝龙的挑战激怒维拉库。击败他后向苍穹之脊的泰莉和乔拉德复命。','做得好，$N。的确做得很好。虚空龙族最初不愿接受一条蓝龙混在他们之中，但是随着时间和我坚定的展示权威，他们会到这里这。分布的，单独的，没有一位可靠的领导人，我们必须警戒避免它们落入邪恶力量的统治，永远保持他们的控制权。','你去挑战并且打败维拉库了吗?','消灭维拉库') ON DUPLICATE KEY UPDATE Title_loc4='占领苍穹之脊',Details_loc4='虚空龙的性情与它们的黑龙同宗一样凶暴而狂躁，但也有一些截然不同的地方。虚空龙的孵化期和成长期十分短暂，身上涌动着奇特的能量。这种能量流是在德拉诺世界毁灭的时候产生的，从而导致了虚空龙这一族群的诞生。$B$B我还需要了解更多的细节，我相信这种能量可以为蓝龙所用。如果我能取代这些虚空龙的领袖维拉库，充分展示我的统御力，我们就能令其它虚空龙屈服。',Objectives_loc4='前往苍穹之脊的南端，使用蓝龙的挑战激怒维拉库。击败他后向苍穹之脊的泰莉和乔拉德复命。',OfferRewardText_loc4='做得好，$N。的确做得很好。虚空龙族最初不愿接受一条蓝龙混在他们之中，但是随着时间和我坚定的展示权威，他们会到这里这。分布的，单独的，没有一位可靠的领导人，我们必须警戒避免它们落入邪恶力量的统治，永远保持他们的控制权。',RequestItemsText_loc4='你去挑战并且打败维拉库了吗?',ObjectiveText1_loc4='消灭维拉库';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,EndText_loc4) VALUES (10275,'二号三角点','根据你提供的一号三角点的信息，我对这台三角测量仪进行了重新校正。你可以采用同样的方法寻找二号三角点。$B$B我唯一能告诉你的就是它可能在极远的西方。$B$B一旦你发现了二号三角点，立即与节点亲王的另一名代理人——星界商人图鲁曼取得联系，他乔装成武器商，藏身于法力熔炉：艾拉所在的浮岛上，过了桥就能看见他的商栈。','利用三角测量仪找到二号三角点。找到之后，立刻前往虚空风暴法力熔炉：艾拉对面的图鲁曼的营地，向星界商人图鲁曼汇报三角点的位置。','的确非常好。节点亲王会很高兴!$B$B我们现在知道第2个点了，它将告诉我们第3个点在哪里，以及水晶的大概位置!','你要买还是要卖?','找到二号三角测量点') ON DUPLICATE KEY UPDATE Title_loc4='二号三角点',Details_loc4='根据你提供的一号三角点的信息，我对这台三角测量仪进行了重新校正。你可以采用同样的方法寻找二号三角点。$B$B我唯一能告诉你的就是它可能在极远的西方。$B$B一旦你发现了二号三角点，立即与节点亲王的另一名代理人——星界商人图鲁曼取得联系，他乔装成武器商，藏身于法力熔炉：艾拉所在的浮岛上，过了桥就能看见他的商栈。',Objectives_loc4='利用三角测量仪找到二号三角点。找到之后，立刻前往虚空风暴法力熔炉：艾拉对面的图鲁曼的营地，向星界商人图鲁曼汇报三角点的位置。',OfferRewardText_loc4='的确非常好。节点亲王会很高兴!$B$B我们现在知道第2个点了，它将告诉我们第3个点在哪里，以及水晶的大概位置!',RequestItemsText_loc4='你要买还是要卖?',EndText_loc4='找到二号三角测量点';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10276,'三角测量','利用一号和二号三角点的资料，我敢确定那颗水晶就在东北方法兰伦废墟的上方。$B$B不幸的是，数据显示它一直在移动，这就是说燃烧军团很可能已经得到了这颗水晶！$B$B为了以防万一，我建议你召集几个朋友一同前往法兰伦废墟。$B$B从恶魔手中夺回水晶，将它交给节点亲王哈拉迈德吧。','夺得阿塔玛水晶，然后返回虚空风暴的风暴之塔，将它交给节点亲王哈拉迈德的影像。','出乎我最疯狂的想象之外，我从没想到你能取回水晶!$B$B还真的将它交给我!你知道它有多么强大吗?$B$B你的无私是鼓舞人心和无可非议的，$N!你给了我许多值得思考的事。','又见面啦，我的朋友。水晶找的如何阿?') ON DUPLICATE KEY UPDATE Title_loc4='三角测量',Details_loc4='利用一号和二号三角点的资料，我敢确定那颗水晶就在东北方法兰伦废墟的上方。$B$B不幸的是，数据显示它一直在移动，这就是说燃烧军团很可能已经得到了这颗水晶！$B$B为了以防万一，我建议你召集几个朋友一同前往法兰伦废墟。$B$B从恶魔手中夺回水晶，将它交给节点亲王哈拉迈德吧。',Objectives_loc4='夺得阿塔玛水晶，然后返回虚空风暴的风暴之塔，将它交给节点亲王哈拉迈德的影像。',OfferRewardText_loc4='出乎我最疯狂的想象之外，我从没想到你能取回水晶!$B$B还真的将它交给我!你知道它有多么强大吗?$B$B你的无私是鼓舞人心和无可非议的，$N!你给了我许多值得思考的事。',RequestItemsText_loc4='又见面啦，我的朋友。水晶找的如何阿?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,EndText_loc4) VALUES (10277,'时光之穴','$N，你好。请跟随时光监护者。她会帮助你理解这一切……','时光之穴的安多尔姆要你跟随时光监护者游览时光之穴。','希望你现在对于在等着你的东西有更多的了解。','直到你至少初步了解到发生的事情前都不要回来。','游览时光之穴') ON DUPLICATE KEY UPDATE Title_loc4='时光之穴',Details_loc4='$N，你好。请跟随时光监护者。她会帮助你理解这一切……',Objectives_loc4='时光之穴的安多尔姆要你跟随时光监护者游览时光之穴。',OfferRewardText_loc4='希望你现在对于在等着你的东西有更多的了解。',RequestItemsText_loc4='直到你至少初步了解到发生的事情前都不要回来。',EndText_loc4='游览时光之穴';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10278,'迁跃裂隙','从很久以前开始，我就在外域的土地上流浪，在这里探
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10279,'主宰之巢','啊，$N，我们一直盼着你呢。让我的兄弟载你去见青铜龙的首领吧。他在时光之穴的底部等着你……','与时光之穴的安多尔姆谈一谈。','我们必须帮你准备好进行即将发生的战斗……','你好……') ON DUPLICATE KEY UPDATE Title_loc4='主宰之巢',Details_loc4='啊，$N，我们一直盼着你呢。让我的兄弟载你去见青铜龙的首领吧。他在时光之穴的底部等着你……',Objectives_loc4='与时光之穴的安多尔姆谈一谈。',OfferRewardText_loc4='我们必须帮你准备好进行即将发生的战斗……',RequestItemsText_loc4='你好……';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10280,'送往沙塔斯的特殊货物','我是位信守诺言的虚灵，$N。你的行为令我深受感动。$B$B给，将这块阿塔玛水晶转交给纳鲁吧。是你从恶魔手中夺回了这颗水晶，因此由你将它献给纳鲁是再合适不过的了。$B$B你可以使用我的私人传送装置直接抵达沙塔斯城。只要踩上去，你就会被传送过去。$B$B将阿塔玛水晶交给圣光广场中的纳鲁阿达尔，愿自由之风伴你前行。','将阿塔玛水晶交给沙塔斯城圣光广场的阿达尔。','你取回了鬼魂之歌!这个阿塔莫水晶就是预言者费伦前往埃索达进行他不幸的任务前留给族人保管的东西。$B$B奇怪的是他并没有预见它会落入燃烧军团的手中，就算只是暂时而已。$B$B或者，也许他预见了?也许他预见了这全部的事，所以将它留在那里好让你可以取回水晶并且来到这里把它交付给我?$B$B我觉得那就是事情的实情。你是你族人的伟大英雄，$N!','<纳鲁说话的美妙口音充满了你的内心。>$B$B我感觉到你带着某种拥有巨大力量的东西，$r。你带给我的是什么呢?') ON DUPLICATE KEY UPDATE Title_loc4='送往沙塔斯的特殊货物',Details_loc4='我是位信守诺言的虚灵，$N。你的行为令我深受感动。$B$B给，将这块阿塔玛水晶转交给纳鲁吧。是你从恶魔手中夺回了这颗水晶，因此由你将它献给纳鲁是再合适不过的了。$B$B你可以使用我的私人传送装置直接抵达沙塔斯城。只要踩上去，你就会被传送过去。$B$B将阿塔玛水晶交给圣光广场中的纳鲁阿达尔，愿自由之风伴你前行。',Objectives_loc4='将阿塔玛水晶交给沙塔斯城圣光广场的阿达尔。',OfferRewardText_loc4='你取回了鬼魂之歌!这个阿塔莫水晶就是预言者费伦前往埃索达进行他不幸的任务前留给族人保管的东西。$B$B奇怪的是他并没有预见它会落入燃烧军团的手中，就算只是暂时而已。$B$B或者，也许他预见了?也许他预见了这全部的事，所以将它留在那里好让你可以取回水晶并且来到这里把它交付给我?$B$B我觉得那就是事情的实情。你是你族人的伟大英雄，$N!',RequestItemsText_loc4='<纳鲁说话的美妙口音充满了你的内心。>$B$B我感觉到你带着某种拥有巨大力量的东西，$r。你带给我的是什么呢?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10281,'正式介绍','你好，$N。别害怕。这只是我目前形态的投影而已，也是我和我的伙伴秘密监视周围动向的方式，既安全又有效。$B$B之前企图跟你套近乎的虚灵，就是那个叫玛里德的家伙，他不过是个披着合法商人外衣的大骗子，你还不如与我合作得好，我是为了揭开异种龙类的谜团才来到这片山脊的。来苍穹之脊的最北端找我吧，我们可以详细谈谈。','找到苍穹之脊北端的泰莉，与她谈一谈。','我叫泰利苟莎，玛里苟斯的一伙，但是大部分的人叫我＂泰利″。我的同伴是圣骑士乔洛德.麦斯。$B$B这些奇怪龙类的消息已经传开了，我怕会有太多人会急着为了获利而利用他们，却不了解他们正在处理的正确种类为何。藉由你的帮助，我们希望在其它人发现他们的存在前深入了解这些生物。','我很开心你决定接受我的邀请。') ON DUPLICATE KEY UPDATE Title_loc4='正式介绍',Details_loc4='你好，$N。别害怕。这只是我目前形态的投影而已，也是我和我的伙伴秘密监视周围动向的方式，既安全又有效。$B$B之前企图跟你套近乎的虚灵，就是那个叫玛里德的家伙，他不过是个披着合法商人外衣的大骗子，你还不如与我合作得好，我是为了揭开异种龙类的谜团才来到这片山脊的。来苍穹之脊的最北端找我吧，我们可以详细谈谈。',Objectives_loc4='找到苍穹之脊北端的泰莉，与她谈一谈。',OfferRewardText_loc4='我叫泰利苟莎，玛里苟斯的一伙，但是大部分的人叫我＂泰利″。我的同伴是圣骑士乔洛德.麦斯。$B$B这些奇怪龙类的消息已经传开了，我怕会有太多人会急着为了获利而利用他们，却不了解他们正在处理的正确种类为何。藉由你的帮助，我们希望在其它人发现他们的存在前深入了解这些生物。',RequestItemsText_loc4='我很开心你决定接受我的邀请。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10282,'往日的希尔斯布莱德','西边是通往旧希尔斯布莱德丘陵的时光通道，准确的说是7年前的希尔斯布莱德丘陵。$B$B永恒之龙的爪牙们企图将部落的酋长萨尔永远囚禁在敦霍尔德城堡。$B$B你应该明白，要是萨尔无法逃离敦霍尔德城堡，这世界就将不复存在。$B$B组织一队冒险者，穿越时光通道进入旧希尔斯布莱德丘陵。$B$B跟伊洛希恩谈谈。','时光之穴的安多尔姆要求你进入旧希尔斯布莱德丘陵，与伊洛希恩谈一谈。','我们最担心的事很快就会成真。在这次短暂骚动背后主导的力量是一群被称为无尽重生的新种飞龙。我们不知道他们从何而来或是为何破坏时间之道。$B$B在这个时光区域中，他们拐走了塔蕾莎，塔米思.佛斯顿的女儿，埃德拉斯.布拉克摩尔的秘书，敦霍尔德的统治者以及艾泽拉斯所有俘虏集中营的监督者。','不用紧张，凡人。你的外表已经被改变了，因此你不会干扰到时间线。') ON DUPLICATE KEY UPDATE Title_loc4='往日的希尔斯布莱德',Details_loc4='西边是通往旧希尔斯布莱德丘陵的时光通道，准确的说是7年前的希尔斯布莱德丘陵。$B$B永恒之龙的爪牙们企图将部落的酋长萨尔永远囚禁在敦霍尔德城堡。$B$B你应该明白，要是萨尔无法逃离敦霍尔德城堡，这世界就将不复存在。$B$B组织一队冒险者，穿越时光通道进入旧希尔斯布莱德丘陵。$B$B跟伊洛希恩谈谈。',Objectives_loc4='时光之穴的安多尔姆要求你进入旧希尔斯布莱德丘陵，与伊洛希恩谈一谈。',OfferRewardText_loc4='我们最担心的事很快就会成真。在这次短暂骚动背后主导的力量是一群被称为无尽重生的新种飞龙。我们不知道他们从何而来或是为何破坏时间之道。$B$B在这个时光区域中，他们拐走了塔蕾莎，塔米思.佛斯顿的女儿，埃德拉斯.布拉克摩尔的秘书，敦霍尔德的统治者以及艾泽拉斯所有俘虏集中营的监督者。',RequestItemsText_loc4='不用紧张，凡人。你的外表已经被改变了，因此你不会干扰到时间线。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4) VALUES (10283,'塔蕾莎的计谋','塔蕾莎是挽救萨尔性命的关键人物，她还教会了萨尔如何思考，为他日后成长为部落酋长奠定了坚实的基础。$B$B正是塔蕾莎在敦霍尔德城堡采取的声东击西战术，帮助萨尔成功脱逃。$B$B永恒之龙却将塔蕾莎囚禁在塔伦米尔。倘若我们袖手旁观的话，就不会发生这场混乱，萨尔也无从逃脱。你必须利用我交给你的燃烧弹，焚毁敦霍尔德城堡的收容所。引爆燃烧弹后，跟被关押在敦霍尔德城堡地牢中的年轻的萨尔谈谈。','进入敦霍尔德城堡，将伊洛希恩交给你的燃烧弹包分别放入5间收容所内的木桶，并启动定时装置。$B$B引爆燃烧弹后，与被关押在敦霍尔德城堡地牢中的萨尔谈一谈。','你是塔蕾莎的朋友吗?所以这是她的新计划吗?非常好……','你是谁?','点燃收容所') ON DUPLICATE KEY UPDATE Title_loc4='塔蕾莎的计谋',Details_loc4='塔蕾莎是挽救萨尔性命的关键人物，她还教会了萨尔如何思考，为他日后成长为部落酋长奠定了坚实的基础。$B$B正是塔蕾莎在敦霍尔德城堡采取的声东击西战术，帮助萨尔成功脱逃。$B$B永恒之龙却将塔蕾莎囚禁在塔伦米尔。倘若我们袖手旁观的话，就不会发生这场混乱，萨尔也无从逃脱。你必须利用我交给你的燃烧弹，焚毁敦霍尔德城堡的收容所。引爆燃烧弹后，跟被关押在敦霍尔德城堡地牢中的年轻的萨尔谈谈。',Objectives_loc4='进入敦霍尔德城堡，将伊洛希恩交给你的燃烧弹包分别放入5间收容所内的木桶，并启动定时装置。$B$B引爆燃烧弹后，与被关押在敦霍尔德城堡地牢中的萨尔谈一谈。',OfferRewardText_loc4='你是塔蕾莎的朋友吗?所以这是她的新计划吗?非常好……',RequestItemsText_loc4='你是谁?',ObjectiveText1_loc4='点燃收容所';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4) VALUES (10284,'逃离敦霍尔德','在你看来，我现在不过是个小孩，但是在我心中藏着远大的梦想。陌生人，我已经为我的族人规划了未来。终有一天，他们会团结一致，推翻人类的压迫。他们会挣脱束缚，新生的兽人部落将再次崛起。$B$B陌生人，我向你保证，只要你伸出援手，帮助我们从这儿逃生，一旦我有能力报答你，我必定会找到你……必定。$B$B<萨尔点了点头。>$B$B等你准备就绪，我们就出发吧。','准备就绪后告知萨尔。保护萨尔逃离敦霍尔德城堡，并与他一起搭救塔蕾莎。$B$B任务完成后与旧希尔斯布莱德丘陵的伊洛希恩谈一谈。','你完成了一件伟大的事，$N。哎呀，这个年轻大酋长对这些事件的回忆一定和当时分毫不差……安杜姆就在主人的藏身处等着你。','<伊洛森点了点头。>','完成萨尔的命运') ON DUPLICATE KEY UPDATE Title_loc4='逃离敦霍尔德',Details_loc4='在你看来，我现在不过是个小孩，但是在我心中藏着远大的梦想。陌生人，我已经为我的族人规划了未来。终有一天，他们会团结一致，推翻人类的压迫。他们会挣脱束缚，新生的兽人部落将再次崛起。$B$B陌生人，我向你保证，只要你伸出援手，帮助我们从这儿逃生，一旦我有能力报答你，我必定会找到你……必定。$B$B<萨尔点了点头。>$B$B等你准备就绪，我们就出发吧。',Objectives_loc4='准备就绪后告知萨尔。保护萨尔逃离敦霍尔德城堡，并与他一起搭救塔蕾莎。$B$B任务完成后与旧希尔斯布莱德丘陵的伊洛希恩谈一谈。',OfferRewardText_loc4='你完成了一件伟大的事，$N。哎呀，这个年轻大酋长对这些事件的回忆一定和当时分毫不差……安杜姆就在主人的藏身处等着你。',RequestItemsText_loc4='<伊洛森点了点头。>',ObjectiveText1_loc4='完成萨尔的命运';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10285,'返回安多尔姆身边','历史的进程得以维护，永恒之龙企图在旧希尔斯布莱德丘陵引发混乱的阴谋已经被粉碎。$B$B立即向安多尔姆复命吧，他在主宰之巢等着你。','返回塔纳利斯沙漠的时光之穴，向幼时的安多尔姆复命。','请接受青铜龙的这份礼物。这些物品将会在你踏上时间之旅的时候协助你。','这么快就回来啦?') ON DUPLICATE KEY UPDATE Title_loc4='返回安多尔姆身边',Details_loc4='历史的进程得以维护，永恒之龙企图在旧希尔斯布莱德丘陵引发混乱的阴谋已经被粉碎。$B$B立即向安多尔姆复命吧，他在主宰之巢等着你。',Objectives_loc4='返回塔纳利斯沙漠的时光之穴，向幼时的安多尔姆复命。',OfferRewardText_loc4='请接受青铜龙的这份礼物。这些物品将会在你踏上时间之旅的时候协助你。',RequestItemsText_loc4='这么快就回来啦?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10286,'埃雷利恩的秘密','埃雷利恩在日记中写下的并不是什么学术研究笔记，而是关于他与一名年轻的血精灵女子的风流韵事！我怎么会蠢到这个地步？$B$B可惜日记中没有提到这个荡妇的名字。阿利迪斯是埃雷利恩的同事，也是他最好的朋友和知己。去审问他，查明我的丈夫到底和谁有暧昧关系。$B$B我看到阿利迪斯离开猎鹰岗哨往赞加沼泽去了。沿着北边的道路走，它一直通向西边的赞加沼泽。','魔导师卡尔琳达要你审问魔导师阿利迪斯，他已经离开猎鹰岗哨，往赞加沼泽的方向去了。','我会告诉你想知道的讯息，$C。放下你的武器，我不想惹更多麻烦了。','你取得我想要的资讯没，$N?') ON DUPLICATE KEY UPDATE Title_loc4='埃雷利恩的秘密',Details_loc4='埃雷利恩在日记中写下的并不是什么学术研究笔记，而是关于他与一名年轻的血精灵女子的风流韵事！我怎么会蠢到这个地步？$B$B可惜日记中没有提到这个荡妇的名字。阿利迪斯是埃雷利恩的同事，也是他最好的朋友和知己。去审问他，查明我的丈夫到底和谁有暧昧关系。$B$B我看到阿利迪斯离开猎鹰岗哨往赞加沼泽去了。沿着北边的道路走，它一直通向西边的赞加沼泽。',Objectives_loc4='魔导师卡尔琳达要你审问魔导师阿利迪斯，他已经离开猎鹰岗哨，往赞加沼泽的方向去了。',OfferRewardText_loc4='我会告诉你想知道的讯息，$C。放下你的武器，我不想惹更多麻烦了。',RequestItemsText_loc4='你取得我想要的资讯没，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10287,'“恋人”曝光','我是埃雷利恩的朋友，但我不会为了他丢掉自己的性命。他的“恋人”是薇拉·火语。$B$B去告诉他的妻子吧。不知道这个彪悍的女人会做出什么事来？','向地狱火半岛猎鹰岗哨的魔导师卡尔琳达复命。','薇艾拉.阳语吗?那个被宠坏的污秽女人。$B$B我将让她知道我不是个轻易让人愚弄的人!') ON DUPLICATE KEY UPDATE Title_loc4='“恋人”曝光',Details_loc4='我是埃雷利恩的朋友，但我不会为了他丢掉自己的性命。他的“恋人”是薇拉·火语。$B$B去告诉他的妻子吧。不知道这个彪悍的女人会做出什么事来？',Objectives_loc4='向地狱火半岛猎鹰岗哨的魔导师卡尔琳达复命。',OfferRewardText_loc4='薇艾拉.阳语吗?那个被宠坏的污秽女人。$B$B我将让她知道我不是个轻易让人愚弄的人!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10288,'抵达外域','我要你去和阿米什·蛮锤谈谈，他就站在我们南边30步远的地方。他可以安排你搭乘狮鹫直飞荣耀堡。到达荣耀堡之后，你会先和伊斯多尔元帅碰面。我这里还准备了一份书面报告，描述了这里的情况。你要把这份报告带给他，并向他报到。$B$B这就是我给你的命令，立刻去执行！你的力量将一定可以帮助我们对付那些恶魔，别在这里浪费时间了。荣耀堡更加需要你的帮助。','地狱火半岛上黑暗之门的指挥官杜隆要求你将杜隆的报告交给阿米什·蛮锤。','回报荣耀堡吗?没问题 -- 我的狮鹫兽将安全迅速地带你到那里!','我看过你在那跟杜朗交谈。你一定是在进行一项重要的任务吧!') ON DUPLICATE KEY UPDATE Title_loc4='抵达外域',Details_loc4='我要你去和阿米什·蛮锤谈谈，他就站在我们南边30步远的地方。他可以安排你搭乘狮鹫直飞荣耀堡。到达荣耀堡之后，你会先和伊斯多尔元帅碰面。我这里还准备了一份书面报告，描述了这里的情况。你要把这份报告带给他，并向他报到。$B$B这就是我给你的命令，立刻去执行！你的力量将一定可以帮助我们对付那些恶魔，别在这里浪费时间了。荣耀堡更加需要你的帮助。',Objectives_loc4='地狱火半岛上黑暗之门的指挥官杜隆要求你将杜隆的报告交给阿米什·蛮锤。',OfferRewardText_loc4='回报荣耀堡吗?没问题 -- 我的狮鹫兽将安全迅速地带你到那里!',RequestItemsText_loc4='我看过你在那跟杜朗交谈。你一定是在进行一项重要的任务吧!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10289,'萨尔玛之旅','我随时都可以召唤双足飞龙将你送去萨尔玛，只要你准备好就可以了。到了那边之后，记得马上将沃雷恩的报告交给克拉库克将军。$B$BLok''tar ogar，$n，祝你好运。','乘坐维拉加·乱羽的双足飞龙前往萨尔玛，并将沃雷恩的报告交给克拉库克将军。','我将集结我所能调动的军队，并且派他们去援助在黑暗之门的欧莱恩部队。不久之后燃烧军团将忘不了部落的战吼声!至于你$N，你今天已经为萨尔玛做了一项伟大的事。我期待你在这里能给我们很大的协助……假如你有让自己生存下去的智慧的话。','来自欧莱恩的报告吗?快一点拿过来!$B$B<克洛克尔克将军皱着眉头迅速地审视了潦草的文件。>$B$B可恶，这是我们所担心的。欧莱恩和他的战士们随时可能被包围!') ON DUPLICATE KEY UPDATE Title_loc4='萨尔玛之旅',Details_loc4='我随时都可以召唤双足飞龙将你送去萨尔玛，只要你准备好就可以了。到了那边之后，记得马上将沃雷恩的报告交给克拉库克将军。$B$BLok''tar ogar，$n，祝你好运。',Objectives_loc4='乘坐维拉加·乱羽的双足飞龙前往萨尔玛，并将沃雷恩的报告交给克拉库克将军。',OfferRewardText_loc4='我将集结我所能调动的军队，并且派他们去援助在黑暗之门的欧莱恩部队。不久之后燃烧军团将忘不了部落的战吼声!至于你$N，你今天已经为萨尔玛做了一项伟大的事。我期待你在这里能给我们很大的协助……假如你有让自己生存下去的智慧的话。',RequestItemsText_loc4='来自欧莱恩的报告吗?快一点拿过来!$B$B<克洛克尔克将军皱着眉头迅速地审视了潦草的文件。>$B$B可恶，这是我们所担心的。欧莱恩和他的战士们随时可能被包围!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10290,'寻找法兰石','此地东北方就是虚空石。虚空石的景致跟这里的青翠绿地截然不同，暴露在地表外的水晶石几乎结成了阵。我们将水晶中包含的矿物质命名为法兰石，以此纪念这片土地以前的主人。$B$B我们开采到的少量法兰石成了市面上的抢手货。不过，高纯度的法兰石并非来自沉积水晶岩，而是取自虚空石附近的石巨人身上。如果你能帮我收集天然法兰石的话，我就与你分享销售收入。','收集4块天然法兰石，将它们交给风暴尖塔的伊格努比。','啊，是的。这种等级确实是我所期待的。假如我们能从巨人身上取得稳定的进货来源，我们也许能完全的放弃开采水晶矿。','我了解收集法拉莱特的风险，但是做生意也是如此。不愿意冒险的商人最好关门大吉，为自己减少麻烦。') ON DUPLICATE KEY UPDATE Title_loc4='寻找法兰石',Details_loc4='此地东北方就是虚空石。虚空石的景致跟这里的青翠绿地截然不同，暴露在地表外的水晶石几乎结成了阵。我们将水晶中包含的矿物质命名为法兰石，以此纪念这片土地以前的主人。$B$B我们开采到的少量法兰石成了市面上的抢手货。不过，高纯度的法兰石并非来自沉积水晶岩，而是取自虚空石附近的石巨人身上。如果你能帮我收集天然法兰石的话，我就与你分享销售收入。',Objectives_loc4='收集4块天然法兰石，将它们交给风暴尖塔的伊格努比。',OfferRewardText_loc4='啊，是的。这种等级确实是我所期待的。假如我们能从巨人身上取得稳定的进货来源，我们也许能完全的放弃开采水晶矿。',RequestItemsText_loc4='我了解收集法拉莱特的风险，但是做生意也是如此。不愿意冒险的商人最好关门大吉，为自己减少麻烦。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10291,'向纳兹格雷尔报到','尽管我军将士的勇猛无可匹敌，但我们在这片废土上仍然举步维艰。立刻向兵营内的纳兹格雷尔大人报到，他正需要一批忠诚的死士，譬如你。如果无法保住在这里的阵地，我们将一无是处，毫无价值。现在，快去吧！','萨尔玛的克拉库克将军要求你向纳兹格雷尔报到。','我们已经在这个该死的荒原失去了许多勇敢的战士。我不想再派更多的新兵去送死。$B$B<纳兹格雷尔透过他残破不堪的狼型面罩严厉的怒视着你>$B$B反正，假如克洛克尔克将军派你来见我，那就表示你有可取之处。那么你的意思呢，$N?你会荣誉地为你的大酋长服务吗?') ON DUPLICATE KEY UPDATE Title_loc4='向纳兹格雷尔报到',Details_loc4='尽管我军将士的勇猛无可匹敌，但我们在这片废土上仍然举步维艰。立刻向兵营内的纳兹格雷尔大人报到，他正需要一批忠诚的死士，譬如你。如果无法保住在这里的阵地，我们将一无是处，毫无价值。现在，快去吧！',Objectives_loc4='萨尔玛的克拉库克将军要求你向纳兹格雷尔报到。',OfferRewardText_loc4='我们已经在这个该死的荒原失去了许多勇敢的战士。我不想再派更多的新兵去送死。$B$B<纳兹格雷尔透过他残破不堪的狼型面罩严厉的怒视着你>$B$B反正，假如克洛克尔克将军派你来见我，那就表示你有可取之处。那么你的意思呢，$N?你会荣誉地为你的大酋长服务吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10292,'更多能量！','小规模地采集珍贵物资带有一种原始而低等的作坊经济的感觉，这种方式在如今的市场经济时代已经了失去竞争力。$B$B我们迫切需要找出大量开采和生产法兰石的方法！这样的话，流入市场的法兰石量将完全掌握在我们手中。$B$B我有个法子，不过这需要一个强大而集中的能量源。唯一可能找到这种强大的能量源的地方就是燃烧军团的营地。前往此地以北的军营，偷几尊火炮回来。','伊格努比要你将8尊军团火炮带回风暴尖塔。','<祖班.艾贞努比露出了像以太族一样龇牙咧嘴的笑容。>$B$B我保证只会把这个难以置信的火力用在善良的用途。这个善良的用途就是我赚取的利润。','你有拿到那些我需要的火炮吗?') ON DUPLICATE KEY UPDATE Title_loc4='更多能量！',Details_loc4='小规模地采集珍贵物资带有一种原始而低等的作坊经济的感觉，这种方式在如今的市场经济时代已经了失去竞争力。$B$B我们迫切需要找出大量开采和生产法兰石的方法！这样的话，流入市场的法兰石量将完全掌握在我们手中。$B$B我有个法子，不过这需要一个强大而集中的能量源。唯一可能找到这种强大的能量源的地方就是燃烧军团的营地。前往此地以北的军营，偷几尊火炮回来。',Objectives_loc4='伊格努比要你将8尊军团火炮带回风暴尖塔。',OfferRewardText_loc4='<祖班.艾贞努比露出了像以太族一样龇牙咧嘴的笑容。>$B$B我保证只会把这个难以置信的火力用在善良的用途。这个善良的用途就是我赚取的利润。',RequestItemsText_loc4='你有拿到那些我需要的火炮吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10293,'完美的水晶','有了优良的基准产品，接下来我们需要寻找品质更高的水晶。当然，目前为止我们开采到的法兰石已经相当不错了，但是我知道哪里有更好的水晶。$B$B我们要从法兰伦石巨人族长克拉格斯卡身上直接采集一份样品！他与别的石巨人一起生活在虚空石。他的后背生长着巨大的法兰石水晶簇，那正是我们需要的东西。打倒这个巨人，然后将他身上的法兰石核心带回来。','风暴尖塔的伊格努比要你取回一个法兰石核心。','做得好!我等不及要测试这东西了。','你仍然活着，表示你已取得核心，或者你已经改变主意。是哪一个呢?') ON DUPLICATE KEY UPDATE Title_loc4='完美的水晶',Details_loc4='有了优良的基准产品，接下来我们需要寻找品质更高的水晶。当然，目前为止我们开采到的法兰石已经相当不错了，但是我知道哪里有更好的水晶。$B$B我们要从法兰伦石巨人族长克拉格斯卡身上直接采集一份样品！他与别的石巨人一起生活在虚空石。他的后背生长着巨大的法兰石水晶簇，那正是我们需要的东西。打倒这个巨人，然后将他身上的法兰石核心带回来。',Objectives_loc4='风暴尖塔的伊格努比要你取回一个法兰石核心。',OfferRewardText_loc4='做得好!我等不及要测试这东西了。',RequestItemsText_loc4='你仍然活着，表示你已取得核心，或者你已经改变主意。是哪一个呢?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10294,'虚空山脉','我们得略微改进一下我这台迁跃裂隙生成器。这样，你带着它到虚空山脉去，就在这里的正东方。你去的路上要小心避开塞斯高。在塞斯高那边东侧的山里应该有条隐秘的小路，直接沿着这条小路过去，就可以找到虚空山脉了，那是一片位于深渊边缘的可怕的地方。$B$B到了那边以后，你要先杀死几只虚空行者，然后把它们的灵魂碎片带回来。有了它们的力量，我就可以大大强化迁跃裂隙生成器的功率，打开一扇永远不会关闭的传送门了。','前往虚空山脉杀死当地的生物。收集40块虚空山脉灵魂碎片，把它们交给断背岗哨的疯狂的欧加斯。','非常好，扭曲裂隙生成器几乎完成了。我们只需要最后一种原料。不久我们将能打开一道扭曲裂隙通往深渊的最深处。$B$B谁知道什么奇怪的生物会穿过裂隙而来?想想看$N，探索未知地学得的知识所带来的益处是不可限量的。','你已经完成了吗?你拿到我们需要的裂片了吗?') ON DUPLICATE KEY UPDATE Title_loc4='虚空山脉',Details_loc4='我们得略微改进一下我这台迁跃裂隙生成器。这样，你带着它到虚空山脉去，就在这里的正东方。你去的路上要小心避开塞斯高。在塞斯高那边东侧的山里应该有条隐秘的小路，直接沿着这条小路过去，就可以找到虚空山脉了，那是一片位于深渊边缘的可怕的地方。$B$B到了那边以后，你要先杀死几只虚空行者，然后把它们的灵魂碎片带回来。有了它们的力量，我就可以大大强化迁跃裂隙生成器的功率，打开一扇永远不会关闭的传送门了。',Objectives_loc4='前往虚空山脉杀死当地的生物。收集40块虚空山脉灵魂碎片，把它们交给断背岗哨的疯狂的欧加斯。',OfferRewardText_loc4='非常好，扭曲裂隙生成器几乎完成了。我们只需要最后一种原料。不久我们将能打开一道扭曲裂隙通往深渊的最深处。$B$B谁知道什么奇怪的生物会穿过裂隙而来?想想看$N，探索未知地学得的知识所带来的益处是不可限量的。',RequestItemsText_loc4='你已经完成了吗?你拿到我们需要的裂片了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10295,'来自深渊','我的迁跃裂隙生成器完成了。现在你可以直接用它召唤出一个真正的虚空行者贵族，只有它的灵魂碎片才能告诉我们，那无底深渊之中到底有些什么样的存在。$B$B立刻前往虚空山脉，在那里的深渊边缘寻找一簇一簇的水晶石，对，它们的学名叫虚空石。然后，你在那些虚空石旁边使用我的迁跃裂隙生成器，虚空男爵加拉希斯会跨越巨大的空间裂隙出现在你的面前。$B$B杀死这只生物，把它的灵魂碎片给我带回来。','杀死虚空男爵加拉希斯，并得到他的灵魂碎片，把它交给断背岗哨的疯狂的欧加斯。','你挽救了我一生的工作$N。$B$B他们说我疯了、他们嘲笑我、他们认为我为虚无山脉和扭曲原野而着魔发狂。现在有这块灵魂裂片我就能解开虚无行者的秘密了。我将拥有深渊的力量。','你解决虚无男爵.加伦希斯了没?') ON DUPLICATE KEY UPDATE Title_loc4='来自深渊',Details_loc4='我的迁跃裂隙生成器完成了。现在你可以直接用它召唤出一个真正的虚空行者贵族，只有它的灵魂碎片才能告诉我们，那无底深渊之中到底有些什么样的存在。$B$B立刻前往虚空山脉，在那里的深渊边缘寻找一簇一簇的水晶石，对，它们的学名叫虚空石。然后，你在那些虚空石旁边使用我的迁跃裂隙生成器，虚空男爵加拉希斯会跨越巨大的空间裂隙出现在你的面前。$B$B杀死这只生物，把它的灵魂碎片给我带回来。',Objectives_loc4='杀死虚空男爵加拉希斯，并得到他的灵魂碎片，把它交给断背岗哨的疯狂的欧加斯。',OfferRewardText_loc4='你挽救了我一生的工作$N。$B$B他们说我疯了、他们嘲笑我、他们认为我为虚无山脉和扭曲原野而着魔发狂。现在有这块灵魂裂片我就能解开虚无行者的秘密了。我将拥有深渊的力量。',RequestItemsText_loc4='你解决虚无男爵.加伦希斯了没?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10296,'黑色沼泽','永恒之龙撕下伪装，露出了阴险狡猾的真面目。他们计划杀死守护者麦迪文，阻止黑暗之门的开启。从表面上看，这对联盟来说是件好事；但是事实上，这将导致一场大灾难，直接导致艾泽拉斯世界的毁灭。$B$B你必须穿越时光通道，进入黑色沼泽。向西走，然后往南，一直走到达存放着沼泽标本的房间，途中你会遇到未来的我。与黑色沼泽的萨艾特谈谈吧。','深入时光之穴，前往正在发生黑暗之门开启这一历史事件的黑色沼泽，与萨艾特谈一谈。','的确，如果兽人从未到达艾泽拉斯，今日的联盟也不会存在。迟早内战将爆发，更进一步减弱人类王国。$B$B最终燃烧军团将侵入艾泽拉斯，在没有任何防卫者的情况下毁灭它。','在你更深入之前……') ON DUPLICATE KEY UPDATE Title_loc4='黑色沼泽',Details_loc4='永恒之龙撕下伪装，露出了阴险狡猾的真面目。他们计划杀死守护者麦迪文，阻止黑暗之门的开启。从表面上看，这对联盟来说是件好事；但是事实上，这将导致一场大灾难，直接导致艾泽拉斯世界的毁灭。$B$B你必须穿越时光通道，进入黑色沼泽。向西走，然后往南，一直走到达存放着沼泽标本的房间，途中你会遇到未来的我。与黑色沼泽的萨艾特谈谈吧。',Objectives_loc4='深入时光之穴，前往正在发生黑暗之门开启这一历史事件的黑色沼泽，与萨艾特谈一谈。',OfferRewardText_loc4='的确，如果兽人从未到达艾泽拉斯，今日的联盟也不会存在。迟早内战将爆发，更进一步减弱人类王国。$B$B最终燃烧军团将侵入艾泽拉斯，在没有任何防卫者的情况下毁灭它。',RequestItemsText_loc4='在你更深入之前……';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,EndText_loc4) VALUES (10297,'开启黑暗之门','在这条时光通道的尽头，守护者麦迪文正在黑色沼泽中心兴奋地忙碌着，想要打开黑暗之门，让兽人大军尽数入侵艾泽拉斯世界。$B$B永恒之龙派出裂隙领主滋扰生事，企图阻止黑暗之门的开启。$B$B这些裂隙领主潜伏在黑色沼泽的各处伺机而动，他们的目标是破坏麦迪文的法力护盾，最终杀死麦迪文。$B$B消灭裂隙领主和他们的首领！保护麦迪文，直到黑暗之门成功开启。这个时空道标可以帮上你的忙。','时光之穴黑色沼泽的萨艾特要求你保护麦迪文，直到他成功开启黑暗之门。$B$B任务完成后向萨艾特复命。','做得好，$N。安杜姆这个孩子，希望再一次与你谈话。','你在每一个时光之袋只可以使用一个时间信号灯。','开启黑暗之门') ON DUPLICATE KEY UPDATE Title_loc4='开启黑暗之门',Details_loc4='在这条时光通道的尽头，守护者麦迪文正在黑色沼泽中心兴奋地忙碌着，想要打开黑暗之门，让兽人大军尽数入侵艾泽拉斯世界。$B$B永恒之龙派出裂隙领主滋扰生事，企图阻止黑暗之门的开启。$B$B这些裂隙领主潜伏在黑色沼泽的各处伺机而动，他们的目标是破坏麦迪文的法力护盾，最终杀死麦迪文。$B$B消灭裂隙领主和他们的首领！保护麦迪文，直到黑暗之门成功开启。这个时空道标可以帮上你的忙。',Objectives_loc4='时光之穴黑色沼泽的萨艾特要求你保护麦迪文，直到他成功开启黑暗之门。$B$B任务完成后向萨艾特复命。',OfferRewardText_loc4='做得好，$N。安杜姆这个孩子，希望再一次与你谈话。',RequestItemsText_loc4='你在每一个时光之袋只可以使用一个时间信号灯。',EndText_loc4='开启黑暗之门';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10298,'龙族的英雄','$N，去向幼时的安多尔姆复命吧。他在这个时间分支外等你，就在主宰之巢。$B$B我听见了龙翼拍打的声音。流沙之鳞对你的能力相当感兴趣，或许他们也想跟你谈谈。','返回塔纳利斯沙漠的时光之穴，向幼时的安多尔姆复命。','你又一次的拯救了这个世界的现在还有未来，$N。为了你的成就，请接受这些物品当作奖赏。','欢迎归来，$N。') ON DUPLICATE KEY UPDATE Title_loc4='龙族的英雄',Details_loc4='$N，去向幼时的安多尔姆复命吧。他在这个时间分支外等你，就在主宰之巢。$B$B我听见了龙翼拍打的声音。流沙之鳞对你的能力相当感兴趣，或许他们也想跟你谈谈。',Objectives_loc4='返回塔纳利斯沙漠的时光之穴，向幼时的安多尔姆复命。',OfferRewardText_loc4='你又一次的拯救了这个世界的现在还有未来，$N。为了你的成就，请接受这些物品当作奖赏。',RequestItemsText_loc4='欢迎归来，$N。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText2_loc4) VALUES (10299,'关闭法力熔炉：布纳尔','若是强行摧毁法力熔炉，由此引发的大爆炸很可能会波及整个外域，我们可不能冒这样大的风险。$B$B从你取回的拓文来看，控制台配备了紧急关闭装置，纳鲁科技通常会在建筑物中使用这种安全的控制机制。$B$B要关闭控制台，你就必须夺得控制水晶。根据我们掌握的情报来看，这颗水晶就在工头瑟瑞狄斯手中。','返回法力熔炉：布纳尔，从工头瑟瑞狄斯手中夺得布纳尔控制水晶。使用水晶关闭法力熔炉：布纳尔控制台，然后向学者卡尔亚复命。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。','圣光眷顾着你，$N。我们全都祈求你的成功。','你已经完成你的任务了吗，$N?','关闭法力熔炉：布纳尔') ON DUPLICATE KEY UPDATE Title_loc4='关闭法力熔炉：布纳尔',Details_loc4='若是强行摧毁法力熔炉，由此引发的大爆炸很可能会波及整个外域，我们可不能冒这样大的风险。$B$B从你取回的拓文来看，控制台配备了紧急关闭装置，纳鲁科技通常会在建筑物中使用这种安全的控制机制。$B$B要关闭控制台，你就必须夺得控制水晶。根据我们掌握的情报来看，这颗水晶就在工头瑟瑞狄斯手中。',Objectives_loc4='返回法力熔炉：布纳尔，从工头瑟瑞狄斯手中夺得布纳尔控制水晶。使用水晶关闭法力熔炉：布纳尔控制台，然后向学者卡尔亚复命。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。',OfferRewardText_loc4='圣光眷顾着你，$N。我们全都祈求你的成功。',RequestItemsText_loc4='你已经完成你的任务了吗，$N?',ObjectiveText2_loc4='关闭法力熔炉：布纳尔';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10300,'修复法杖','<拉文德维尔仔细检查着法杖，突然注意到杖头部分缺失了。>$B$B这太野蛮了！埃克拉斯肯定将水晶杖头拆了下来挪作它用，完全破坏了杖头与法杖其它部分的魔力平衡。$B$B杖头一旦损坏，势必会大大削弱法杖的力量。若是能找到合适的德莱尼水晶，我应该可以修复它。我听地精们说，北边恩卡特废墟的鬼魂身上有这种水晶。','从恩卡特废墟的鬼魂身上收集4块无瑕的水晶碎片，将它们交给52区的拉文德维尔。','<罗樊德威仔细地检验水晶，然后从中挑选一个。>$B$B这水晶应该可以。我将重新雕塑法杖以装上新的法杖首盔。$B$B当大法师瓦戈斯看见法杖时，他将感到失望，但是如果这么做可以释放主人，我能承担主人的失望。','你已经设法找到适合当作大法师法杖头部配件的水晶了吗?') ON DUPLICATE KEY UPDATE Title_loc4='修复法杖',Details_loc4='<拉文德维尔仔细检查着法杖，突然注意到杖头部分缺失了。>$B$B这太野蛮了！埃克拉斯肯定将水晶杖头拆了下来挪作它用，完全破坏了杖头与法杖其它部分的魔力平衡。$B$B杖头一旦损坏，势必会大大削弱法杖的力量。若是能找到合适的德莱尼水晶，我应该可以修复它。我听地精们说，北边恩卡特废墟的鬼魂身上有这种水晶。',Objectives_loc4='从恩卡特废墟的鬼魂身上收集4块无瑕的水晶碎片，将它们交给52区的拉文德维尔。',OfferRewardText_loc4='<罗樊德威仔细地检验水晶，然后从中挑选一个。>$B$B这水晶应该可以。我将重新雕塑法杖以装上新的法杖首盔。$B$B当大法师瓦戈斯看见法杖时，他将感到失望，但是如果这么做可以释放主人，我能承担主人的失望。',RequestItemsText_loc4='你已经设法找到适合当作大法师法杖头部配件的水晶了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10301,'魔法纲要的防护','你夺回了克拉苏斯的魔法纲要，这令我非常欣慰。但是如果没有紫色单片眼镜的话，这本书就是一摞废纸。睿智的克拉苏斯非常清楚，许多人都会觊觎书中记载的强大法术；于是他为魔法纲要设置了完美的防护机制。$B$B只有知识渊博的法师才能利用紫色单片眼镜揭开书中的秘密。$B$B在凯尔萨斯进攻这里时，他手下一位名叫掠法者玛拉瑟雷的军官将眼镜抢走，带去了日怒堡东北方的一处法师塔中。她只是把它当成了一件有点价值的小玩意收藏着。','从日怒堡的掠法者玛拉瑟雷手中夺得紫色单片眼镜。','太好了，$N。现在，我们已经获得大多数我们需要用来破除凯尔萨斯之魔法的东西了。$B$B如果血精灵丧失他们本地的指挥官而感到苦恼的话，当然更好。','你拿到紫罗兰之目了吗?') ON DUPLICATE KEY UPDATE Title_loc4='魔法纲要的防护',Details_loc4='你夺回了克拉苏斯的魔法纲要，这令我非常欣慰。但是如果没有紫色单片眼镜的话，这本书就是一摞废纸。睿智的克拉苏斯非常清楚，许多人都会觊觎书中记载的强大法术；于是他为魔法纲要设置了完美的防护机制。$B$B只有知识渊博的法师才能利用紫色单片眼镜揭开书中的秘密。$B$B在凯尔萨斯进攻这里时，他手下一位名叫掠法者玛拉瑟雷的军官将眼镜抢走，带去了日怒堡东北方的一处法师塔中。她只是把它当成了一件有点价值的小玩意收藏着。',Objectives_loc4='从日怒堡的掠法者玛拉瑟雷手中夺得紫色单片眼镜。',OfferRewardText_loc4='太好了，$N。现在，我们已经获得大多数我们需要用来破除凯尔萨斯之魔法的东西了。$B$B如果血精灵丧失他们本地的指挥官而感到苦恼的话，当然更好。',RequestItemsText_loc4='你拿到紫罗兰之目了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10302,'暴躁的变异体','埃索达的放射能量核心肆意破坏着这一带的环境。最显着的负面效应当属能量核心周围如雨后春笋般冒
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10303,'血精灵','你必须解除……血精灵的……威胁。查明……他们的……目的！$B$B他们就在我身后的……山脊中。','杀死10个血精灵斥候，然后向埃门谷暗影山的图兰复命。','这些血精灵想杀死我们全部。我们该怎样让他们转移到别的方向?','他们的人数太多了……我们必须削弱他们，否则那些幸存者将没有机会对抗他们。') ON DUPLICATE KEY UPDATE Title_loc4='血精灵',Details_loc4='你必须解除……血精灵的……威胁。查明……他们的……目的！$B$B他们就在我身后的……山脊中。',Objectives_loc4='杀死10个血精灵斥候，然后向埃门谷暗影山的图兰复命。',OfferRewardText_loc4='这些血精灵想杀死我们全部。我们该怎样让他们转移到别的方向?',RequestItemsText_loc4='他们的人数太多了……我们必须削弱他们，否则那些幸存者将没有机会对抗他们。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10304,'守备官奥达尔','在你的帮助下，我们迅速解决了这个难题，速度快到令人咋舌。$B$B我目前没有别的事情要交给你做了。剩下的就交给我和学徒们吧。$B$B去跟飞船另一侧的守备官奥达尔谈谈吧。','与埃门谷坠毁点的守备官奥达尔谈一谈。','$N，是吗?自从你来到这里，我已经听到关于你的英勇事迹以及你在近来所完成的工作。$B$B我们很明确需要你的帮助让事情恢复正常。我相信在那里的萨那，也需要你的帮助。') ON DUPLICATE KEY UPDATE Title_loc4='守备官奥达尔',Details_loc4='在你的帮助下，我们迅速解决了这个难题，速度快到令人咋舌。$B$B我目前没有别的事情要交给你做了。剩下的就交给我和学徒们吧。$B$B去跟飞船另一侧的守备官奥达尔谈谈吧。',Objectives_loc4='与埃门谷坠毁点的守备官奥达尔谈一谈。',OfferRewardText_loc4='$N，是吗?自从你来到这里，我已经听到关于你的英勇事迹以及你在近来所完成的工作。$B$B我们很明确需要你的帮助让事情恢复正常。我相信在那里的萨那，也需要你的帮助。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4) VALUES (10305,'防御法师贝尔玛拉','虽说是肯瑞托法师之物，这本破旧的书卷却并不是什么法术书。书页里都是手抄体的故事，字体娟秀，还配有精美的彩色插画。$B$B书卷看上去比它的主人还要古老，很可能是家族的传家宝吧。贝尔玛拉的灵魂至今仍在肯瑞瓦村的废墟中徘徊，这本书卷似乎是她在世间最后的羁绊。将它放回贝尔玛拉家中的书架上，或许就可以平息她的怒火。','在巫师街内找到防御法师贝尔玛拉的住所，将书放回书架上。然后与肯瑞瓦村的管理器戴沃斯谈一谈。','啊，是的。我已经听说弃绝者贝马拉有一本旧的故事书，但是我不知道她将它带到了外域。你已经找到这本书并且将它带回她的住处，我相信她的灵魂将得到更多的宁静。','你发现了什么，$N?','让鲁米拉斯的灵魂安息') ON DUPLICATE KEY UPDATE Title_loc4='防御法师贝尔玛拉',Details_loc4='虽说是肯瑞托法师之物，这本破旧的书卷却并不是什么法术书。书页里都是手抄体的故事，字体娟秀，还配有精美的彩色插画。$B$B书卷看上去比它的主人还要古老，很可能是家族的传家宝吧。贝尔玛拉的灵魂至今仍在肯瑞瓦村的废墟中徘徊，这本书卷似乎是她在世间最后的羁绊。将它放回贝尔玛拉家中的书架上，或许就可以平息她的怒火。',Objectives_loc4='在巫师街内找到防御法师贝尔玛拉的住所，将书放回书架上。然后与肯瑞瓦村的管理器戴沃斯谈一谈。',OfferRewardText_loc4='啊，是的。我已经听说弃绝者贝马拉有一本旧的故事书，但是我不知道她将它带到了外域。你已经找到这本书并且将它带回她的住处，我相信她的灵魂将得到更多的宁静。',RequestItemsText_loc4='你发现了什么，$N?',ObjectiveText1_loc4='让鲁米拉斯的灵魂安息';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4) VALUES (10306,'咒术师鲁米拉斯','这件披风无疑出自高等精灵匠人之手，即便是以肯瑞托法师的标准来看，它也称得上材质华美、价格不菲的精品。你看不懂绣在披风上的符号与文字，但显然衣料中附着了魔法属性。$B$B或许它仍然将主人的灵魂羁绊在这个物质位面中。如果是这样的话，就将这件披风放回咒术师鲁米拉斯家中的衣柜里，或许就能破除羁绊，让他的灵魂得到安息。','在巫师街内找到咒术师鲁米拉斯的住所，将披风放回衣柜里。然后与肯瑞瓦村的管理器戴沃斯谈一谈。','我们总是常常说卢瑞斯不论穿什么衣服都会搭配那件披风。对他来说，红色在搭配上与白色、黑色、紫色、蓝色、黄色、橘色和绿色同样好。他绝不会连续两天穿相同的长袍，但他总是穿着那件披风……','你发现了什么，$N?','让鲁米拉斯的灵魂安息') ON DUPLICATE KEY UPDATE Title_loc4='咒术师鲁米拉斯',Details_loc4='这件披风无疑出自高等精灵匠人之手，即便是以肯瑞托法师的标准来看，它也称得上材质华美、价格不菲的精品。你看不懂绣在披风上的符号与文字，但显然衣料中附着了魔法属性。$B$B或许它仍然将主人的灵魂羁绊在这个物质位面中。如果是这样的话，就将这件披风放回咒术师鲁米拉斯家中的衣柜里，或许就能破除羁绊，让他的灵魂得到安息。',Objectives_loc4='在巫师街内找到咒术师鲁米拉斯的住所，将披风放回衣柜里。然后与肯瑞瓦村的管理器戴沃斯谈一谈。',OfferRewardText_loc4='我们总是常常说卢瑞斯不论穿什么衣服都会搭配那件披风。对他来说，红色在搭配上与白色、黑色、紫色、蓝色、黄色、橘色和绿色同样好。他绝不会连续两天穿相同的长袍，但他总是穿着那件披风……',RequestItemsText_loc4='你发现了什么，$N?',ObjectiveText1_loc4='让鲁米拉斯的灵魂安息';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4) VALUES (10307,'考利恩·霜纹','看着这顶帽子，你禁不住怀疑有哪位肯瑞托法师会拥有这样的头部装备。从帽子的磨损程度看得出，它的侏儒主人无论走到哪里都戴着它。$B$B你试着戴上帽子，发现除了一点点想要跳舞的冲动外，这顶帽子没有任何魔法属性。$B$B这件珍贵的物品很可能将主人的灵魂羁绊在了村庄中。将它放回考利恩家中的小提箱里，或许就能让法师的灵魂得到自由了吧。','在巫师街内找到考利恩·霜纹的住所，将帽子放回小提箱中。然后与肯瑞瓦村的管理器戴沃斯谈一谈。','<管理器听到了考林的名字以后露出了微笑。>$B$B关于那顶帽子你说对了。他总是穿着它而且不会让它离开他的视线。$B$B他曾经有一个法师同事，我不方便透露名字，“借走了”那顶帽子然后恶作剧的把它藏起来。不用说你也知道后来考林的寒冰箭让他改变了主意。$B$B我会非常想念小考林的。他对女精灵很有一套。','你发现了什么，$N?','让考利恩的灵魂安息') ON DUPLICATE KEY UPDATE Title_loc4='考利恩·霜纹',Details_loc4='看着这顶帽子，你禁不住怀疑有哪位肯瑞托法师会拥有这样的头部装备。从帽子的磨损程度看得出，它的侏儒主人无论走到哪里都戴着它。$B$B你试着戴上帽子，发现除了一点点想要跳舞的冲动外，这顶帽子没有任何魔法属性。$B$B这件珍贵的物品很可能将主人的灵魂羁绊在了村庄中。将它放回考利恩家中的小提箱里，或许就能让法师的灵魂得到自由了吧。',Objectives_loc4='在巫师街内找到考利恩·霜纹的住所，将帽子放回小提箱中。然后与肯瑞瓦村的管理器戴沃斯谈一谈。',OfferRewardText_loc4='<管理器听到了考林的名字以后露出了微笑。>$B$B关于那顶帽子你说对了。他总是穿着它而且不会让它离开他的视线。$B$B他曾经有一个法师同事，我不方便透露名字，“借走了”那顶帽子然后恶作剧的把它藏起来。不用说你也知道后来考林的寒冰箭让他改变了主意。$B$B我会非常想念小考林的。他对女精灵很有一套。',RequestItemsText_loc4='你发现了什么，$N?',ObjectiveText1_loc4='让考利恩的灵魂安息';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10308,'更多叛徒的徽记','他们全都是叛徒!$B$B做得好，$C!如果你有再到那里去，我一直都想增加他们徽记的收藏。','联合团对于彻底消灭所有在南方聚集之地的萨希斯反叛者感到强烈的兴趣。$B$B$C，如果你想让我们更加喜欢你，就回去那里带回更多他们的联合徽记。') ON DUPLICATE KEY UPDATE Title_loc4='更多叛徒的徽记',OfferRewardText_loc4='他们全都是叛徒!$B$B做得好，$C!如果你有再到那里去，我一直都想增加他们徽记的收藏。',RequestItemsText_loc4='联合团对于彻底消灭所有在南方聚集之地的萨希斯反叛者感到强烈的兴趣。$B$B$C，如果你想让我们更加喜欢你，就回去那里带回更多他们的联合徽记。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10309,'魔能机甲的心跳','你看见南边那些破损的魔能机甲了吗？你不觉得它很美吗？$B$B我想它要的心！$B$B什么？是的，它当然有心……为什么没有？$B$B<米西·米恩卡普的语气中透出一丝恼怒。>$B$B橇开魔能机甲的装甲，把我想要的东西给带回来，我会付给你一大笔钱当报酬的。$B$B哦，如果我是你的话，我会带一两个朋友同去，因为那里有许多萨克希斯虚灵！$B$B带上这个邪能起搏器，在你卸下魔能机甲之心前，记得先使用这个小玩意。','将魔能机甲之心交给虚空风暴机甲废场的米西·米恩卡普。','哇，看看那个……一颗跳动的恶魔劫夺者之心!呃，它其实没＂跳动″，但是你知道我的意思。$B$B我等不及要充分利用这件东西了。或者，考虑出售它。我知道一些呆瓜……呃，感兴趣的客户。$B$B来，你已经挣得了你的薪水!','我的视力一定是随虚空辐射线而去了。你取得恶魔劫夺者之心了吗?') ON DUPLICATE KEY UPDATE Title_loc4='魔能机甲的心跳',Details_loc4='你看见南边那些破损的魔能机甲了吗？你不觉得它很美吗？$B$B我想它要的心！$B$B什么？是的，它当然有心……为什么没有？$B$B<米西·米恩卡普的语气中透出一丝恼怒。>$B$B橇开魔能机甲的装甲，把我想要的东西给带回来，我会付给你一大笔钱当报酬的。$B$B哦，如果我是你的话，我会带一两个朋友同去，因为那里有许多萨克希斯虚灵！$B$B带上这个邪能起搏器，在你卸下魔能机甲之心前，记得先使用这个小玩意。',Objectives_loc4='将魔能机甲之心交给虚空风暴机甲废场的米西·米恩卡普。',OfferRewardText_loc4='哇，看看那个……一颗跳动的恶魔劫夺者之心!呃，它其实没＂跳动″，但是你知道我的意思。$B$B我等不及要充分利用这件东西了。或者，考虑出售它。我知道一些呆瓜……呃，感兴趣的客户。$B$B来，你已经挣得了你的薪水!',RequestItemsText_loc4='我的视力一定是随虚空辐射线而去了。你取得恶魔劫夺者之心了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,EndText_loc4) VALUES (10310,'破坏迁跃门！','燃烧军团已经占领了附近的魔能机甲废料场，我们必须竭尽全力阻止这群该死的恶魔继续向前推进，入侵到这里。$B$B他们在南边有一处名为登陆场：破坏的营地，营地中设有迁跃门。$B$B我要你护送我进入营地，并在我破坏迁跃门时确保我的安全。$B$B完成任务后，就返回北边中央生态圆顶的中央圆顶哨站，将这一好消息告诉加鲁斯。$B$B不过，我们恐怕还需要另外一两位朋友来帮忙。','护送德里亚到达登陆场：破坏的迁跃门，并在他尝试破坏迁跃门的过程中保护他的安全。然后返回虚空风暴的中央生态圆顶，向中央圆顶哨站的加鲁斯复命。','那真是最好的消息，我的朋友!$B$B你和迪耶亚已经为我们做了一项伟大的事。随着那星移门的损坏，附近的恶魔将不会再有任何增援部队了。$B$B请允许我以联合团的名义给予你适当的奖励。','我可以帮你什么吗?','破坏燃烧军团迁跃门') ON DUPLICATE KEY UPDATE Title_loc4='破坏迁跃门！',Details_loc4='燃烧军团已经占领了附近的魔能机甲废料场，我们必须竭尽全力阻止这群该死的恶魔继续向前推进，入侵到这里。$B$B他们在南边有一处名为登陆场：破坏的营地，营地中设有迁跃门。$B$B我要你护送我进入营地，并在我破坏迁跃门时确保我的安全。$B$B完成任务后，就返回北边中央生态圆顶的中央圆顶哨站，将这一好消息告诉加鲁斯。$B$B不过，我们恐怕还需要另外一两位朋友来帮忙。',Objectives_loc4='护送德里亚到达登陆场：破坏的迁跃门，并在他尝试破坏迁跃门的过程中保护他的安全。然后返回虚空风暴的中央生态圆顶，向中央圆顶哨站的加鲁斯复命。',OfferRewardText_loc4='那真是最好的消息，我的朋友!$B$B你和迪耶亚已经为我们做了一项伟大的事。随着那星移门的损坏，附近的恶魔将不会再有任何增援部队了。$B$B请允许我以联合团的名义给予你适当的奖励。',RequestItemsText_loc4='我可以帮你什么吗?',EndText_loc4='破坏燃烧军团迁跃门';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10311,'德里亚需要你的帮助','$C，你肯帮忙真是再好不过了。$B$B这附近的燃烧军团魔能机甲的行动变得越来越大胆，我们的安全已经开始受到威胁了。那些恶魔还经常从南面的登陆场：破坏得到增援。$B$B我的同胞德里亚已经赶去那里侦察情况了，他想看看自己能否摧毁燃烧军团的迁跃门。$B$B去登陆场找他吧，尽你所能地帮助他。','与虚空风暴登陆场：破坏的德里亚谈一谈。','我希望加鲁派你来是为了帮助我完成我的任务。') ON DUPLICATE KEY UPDATE Title_loc4='德里亚需要你的帮助',Details_loc4='$C，你肯帮忙真是再好不过了。$B$B这附近的燃烧军团魔能机甲的行动变得越来越大胆，我们的安全已经开始受到威胁了。那些恶魔还经常从南面的登陆场：破坏得到增援。$B$B我的同胞德里亚已经赶去那里侦察情况了，他想看看自己能否摧毁燃烧军团的迁跃门。$B$B去登陆场找他吧，尽你所能地帮助他。',Objectives_loc4='与虚空风暴登陆场：破坏的德里亚谈一谈。',OfferRewardText_loc4='我希望加鲁派你来是为了帮助我完成我的任务。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10312,'肯瑞瓦名册','看来我们的期望落空了，上一次的行动并没有彻底消除他们的攻击性。你看，那些曾被你制服的邪恶幽灵再度出现镇子的街道上。$B$B我们必须揭开其中的隐秘。躁动难安的灵魂……难道肯瑞瓦的毁灭才刚刚拉开序幕吗？$B$B肯瑞瓦的城镇大厅就在村子的东南角，那里保存着一本村民资料的名册。我听说战斗法师达斯利克负责保管它，说不定他的灵魂还守护着这本名册。','从肯瑞瓦村的城镇大厅中取回肯瑞瓦名册，将它交给管理器戴沃斯。','<监护者戴沃斯接过你手中的记录簿，匆匆翻阅那些书页。>$B$B嗯……$B$B看起来我猜的没错，这件事有规律可寻。$B$B最具侵略性和最危险的鬼魂与居住在村庄里的最强大和最高等级的肯瑞托相符。比较起来市镇居民和小贩好像被忽略了。这意味着什么?','你找得到记录簿吗?') ON DUPLICATE KEY UPDATE Title_loc4='肯瑞瓦名册',Details_loc4='看来我们的期望落空了，上一次的行动并没有彻底消除他们的攻击性。你看，那些曾被你制服的邪恶幽灵再度出现镇子的街道上。$B$B我们必须揭开其中的隐秘。躁动难安的灵魂……难道肯瑞瓦的毁灭才刚刚拉开序幕吗？$B$B肯瑞瓦的城镇大厅就在村子的东南角，那里保存着一本村民资料的名册。我听说战斗法师达斯利克负责保管它，说不定他的灵魂还守护着这本名册。',Objectives_loc4='从肯瑞瓦村的城镇大厅中取回肯瑞瓦名册，将它交给管理器戴沃斯。',OfferRewardText_loc4='<监护者戴沃斯接过你手中的记录簿，匆匆翻阅那些书页。>$B$B嗯……$B$B看起来我猜的没错，这件事有规律可寻。$B$B最具侵略性和最危险的鬼魂与居住在村庄里的最强大和最高等级的肯瑞托相符。比较起来市镇居民和小贩好像被忽略了。这意味着什么?',RequestItemsText_loc4='你找得到记录簿吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4,ObjectiveText2_loc4,ObjectiveText3_loc4,ObjectiveText4_loc4) VALUES (10313,'测量迁跃能量','如果我们直觉没有错，这些法力熔炉应该都是利用风暴要塞的科技建造而成的。这样一来，整个外域恐怕就岌岌可危了。$B$B风暴要塞的能量补给机制绝对不适合在靠近陆地的地方使用。虽说能量管道是凯尔萨斯设计的，但是传输过程中产生的强大迁跃能量流也足以使整片陆地失去生机。$B$B必须采取行动！带上这颗宝珠前往法力熔炉布纳尔，它能监测到迁跃能量的强度。在法力熔炉管道的末端，也就是管道进入地下的那里使用它。','52区的大主教欧雷里斯要你将迁跃共鸣宝珠带往法力熔炉：布纳尔，并在法力熔炉四条管道的末端使用它。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。','这是重要的消息，$N。从管线流出的扭曲能量具高危险性。$B$B我们必须找到方法关闭法力熔炉，否则爆炸之后外域只会剩下几块碎片而已。','你执行过我要的测量了吗，$N?','测量北部管道','测量东部管道','测量南部管道','测量西部管道') ON DUPLICATE KEY UPDATE Title_loc4='测量迁跃能量',Details_loc4='如果我们直觉没有错，这些法力熔炉应该都是利用风暴要塞的科技建造而成的。这样一来，整个外域恐怕就岌岌可危了。$B$B风暴要塞的能量补给机制绝对不适合在靠近陆地的地方使用。虽说能量管道是凯尔萨斯设计的，但是传输过程中产生的强大迁跃能量流也足以使整片陆地失去生机。$B$B必须采取行动！带上这颗宝珠前往法力熔炉布纳尔，它能监测到迁跃能量的强度。在法力熔炉管道的末端，也就是管道进入地下的那里使用它。',Objectives_loc4='52区的大主教欧雷里斯要你将迁跃共鸣宝珠带往法力熔炉：布纳尔，并在法力熔炉四条管道的末端使用它。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。',OfferRewardText_loc4='这是重要的消息，$N。从管线流出的扭曲能量具高危险性。$B$B我们必须找到方法关闭法力熔炉，否则爆炸之后外域只会剩下几块碎片而已。',RequestItemsText_loc4='你执行过我要的测量了吗，$N?',ObjectiveText1_loc4='测量北部管道',ObjectiveText2_loc4='测量东部管道',ObjectiveText3_loc4='测量南部管道',ObjectiveText4_loc4='测量西部管道';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10314,'久远的痕迹','你从没见过如此奇特的魔法装置，它显然不是血精灵的制品。$B$B你发现，一旦有幽灵靠近建筑物，球体所发出的光芒就会变得强烈；而当幽灵走远后，光芒也会逐渐黯淡下来。毫无疑问，这台装置与幽灵的堕落有着密切的关系。$B$B但是它的设计原理仍然还是一个谜。如果你将观测结果告知管理器戴沃斯，再从幽灵身上收集一些碎片供他研究，或许他能揭开其中的秘密。','从肯瑞瓦村礼拜堂广场中扭曲的幽灵身上收集10份令人厌恶的残留物，将它们交给管理器戴沃斯。','<监护者戴沃斯检验残馀物。>$B$B你描述的装置听起来好像是一种死灵法术的媒介……我本该知道那个不学好的学徒会因此而堕落。我本以为他的训练会使他远离今日的堕落程度，但是我想他已经证明我是错的。','你发现了什么，$N?') ON DUPLICATE KEY UPDATE Title_loc4='久远的痕迹',Details_loc4='你从没见过如此奇特的魔法装置，它显然不是血精灵的制品。$B$B你发现，一旦有幽灵靠近建筑物，球体所发出的光芒就会变得强烈；而当幽灵走远后，光芒也会逐渐黯淡下来。毫无疑问，这台装置与幽灵的堕落有着密切的关系。$B$B但是它的设计原理仍然还是一个谜。如果你将观测结果告知管理器戴沃斯，再从幽灵身上收集一些碎片供他研究，或许他能揭开其中的秘密。',Objectives_loc4='从肯瑞瓦村礼拜堂广场中扭曲的幽灵身上收集10份令人厌恶的残留物，将它们交给管理器戴沃斯。',OfferRewardText_loc4='<监护者戴沃斯检验残馀物。>$B$B你描述的装置听起来好像是一种死灵法术的媒介……我本该知道那个不学好的学徒会因此而堕落。我本以为他的训练会使他远离今日的堕落程度，但是我想他已经证明我是错的。',RequestItemsText_loc4='你发现了什么，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10315,'消灭虚空法师','所有血精灵都是蠢货！和他们解除贸易关系真是件值得庆幸的好事。我走遍了宇宙中的每个角落，却从来没有见过这样自私自利的生物。$B$B他们利用法力熔炉不断地侵蚀着我们周围的土地，那么我们就在桥对面的法力熔炉：艾拉搞点破坏好了。$B$B据我所知，要想稳定法力熔炉的能量流，血精灵的虚空法师们必须利用血宝石不停地引导能量。前往法力熔炉：艾拉，干掉那些虚空法师！','消灭15名日怒虚空法师，然后返回虚空风暴内的图鲁曼的营地，向虚空猎手奥尔苏复命。','任何我们能推动他们停止在这些法力熔炉所做的事都是好事。$B$B他们当然不会跟你讲道理。而且我很清楚无论他们的领导人在想什么，他们都是疯狂的。$B$B如果不会冒犯你的话，我想要给你属于你们国度的钱币作为达成联合团目标之忠诚服务的报酬。','你计划要杀掉几个虚空术师?') ON DUPLICATE KEY UPDATE Title_loc4='消灭虚空法师',Details_loc4='所有血精灵都是蠢货！和他们解除贸易关系真是件值得庆幸的好事。我走遍了宇宙中的每个角落，却从来没有见过这样自私自利的生物。$B$B他们利用法力熔炉不断地侵蚀着我们周围的土地，那么我们就在桥对面的法力熔炉：艾拉搞点破坏好了。$B$B据我所知，要想稳定法力熔炉的能量流，血精灵的虚空法师们必须利用血宝石不停地引导能量。前往法力熔炉：艾拉，干掉那些虚空法师！',Objectives_loc4='消灭15名日怒虚空法师，然后返回虚空风暴内的图鲁曼的营地，向虚空猎手奥尔苏复命。',OfferRewardText_loc4='任何我们能推动他们停止在这些法力熔炉所做的事都是好事。$B$B他们当然不会跟你讲道理。而且我很清楚无论他们的领导人在想什么，他们都是疯狂的。$B$B如果不会冒犯你的话，我想要给你属于你们国度的钱币作为达成联合团目标之忠诚服务的报酬。',RequestItemsText_loc4='你计划要杀掉几个虚空术师?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10316,'寻找证据','那个让鬼魂发生变异的幕后黑手显然制订了详细的计划，他首先挑选了几位最强大的法师作为目标，但这是为什么呢？要想扭曲肯瑞托法师的灵魂，需要以强大的法术来构筑诅咒仪式。$B$B为什么要耗费这么大的精力来对付肯瑞托法师呢？嗯……我认为这是凯尔萨斯的又一个阴谋，他试图将肯瑞瓦村变得更加凄惨。如果这附近有血精灵作祟的话，他们很可能就躲藏在桥对面的房子里。','在肯瑞瓦村的礼拜堂广场寻找操纵鬼魂滋扰村庄的幕后黑手的线索。','一个发光的宝珠座落在一个方形台座顶上。乍看之下，它好像是魔法能源的储藏处，但是储存的是哪种能量，又是给谁使用的呢?','你检查这个怪异的魔法装置，找寻有关使用的方法及持有者的蛛丝马迹。') ON DUPLICATE KEY UPDATE Title_loc4='寻找证据',Details_loc4='那个让鬼魂发生变异的幕后黑手显然制订了详细的计划，他首先挑选了几位最强大的法师作为目标，但这是为什么呢？要想扭曲肯瑞托法师的灵魂，需要以强大的法术来构筑诅咒仪式。$B$B为什么要耗费这么大的精力来对付肯瑞托法师呢？嗯……我认为这是凯尔萨斯的又一个阴谋，他试图将肯瑞瓦村变得更加凄惨。如果这附近有血精灵作祟的话，他们很可能就躲藏在桥对面的房子里。',Objectives_loc4='在肯瑞瓦村的礼拜堂广场寻找操纵鬼魂滋扰村庄的幕后黑手的线索。',OfferRewardText_loc4='一个发光的宝珠座落在一个方形台座顶上。乍看之下，它好像是魔法能源的储藏处，但是储存的是哪种能量，又是给谁使用的呢?',RequestItemsText_loc4='你检查这个怪异的魔法装置，找寻有关使用的方法及持有者的蛛丝马迹。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10317,'对付工头','血精灵将法力熔炉：艾拉地下的矿井命名为特雷卢姆矿井。自从法力熔炉：乌提斯地下的矿井被毁后，特雷卢姆矿井便成为运转法力熔炉所需原料的唯一来源点。$B$B这样一来，我们就能轻而易举地彻底破坏血精灵的采矿工事，甚至还能将这座矿井据为己有！$B$B我要你前往法力熔炉：艾拉，干掉那里的工头萨杜恩·日落。特雷卢姆矿井就在浮岛后方偏左的位置。','前往虚空风暴法力熔炉：艾拉地下的特雷卢姆矿井，对付工头萨杜恩·日落。','<工头压低音调说着。>$B$B你来这里是要杀死我吗?嗯。我猜以太族尚未知道所有的事情，是吧?$B$B我不是你想杀的人，相信我。','<这个血精灵的眼睛睁的得好大!>$B$B你在这里干嘛?!') ON DUPLICATE KEY UPDATE Title_loc4='对付工头',Details_loc4='血精灵将法力熔炉：艾拉地下的矿井命名为特雷卢姆矿井。自从法力熔炉：乌提斯地下的矿井被毁后，特雷卢姆矿井便成为运转法力熔炉所需原料的唯一来源点。$B$B这样一来，我们就能轻而易举地彻底破坏血精灵的采矿工事，甚至还能将这座矿井据为己有！$B$B我要你前往法力熔炉：艾拉，干掉那里的工头萨杜恩·日落。特雷卢姆矿井就在浮岛后方偏左的位置。',Objectives_loc4='前往虚空风暴法力熔炉：艾拉地下的特雷卢姆矿井，对付工头萨杜恩·日落。',OfferRewardText_loc4='<工头压低音调说着。>$B$B你来这里是要杀死我吗?嗯。我猜以太族尚未知道所有的事情，是吧?$B$B我不是你想杀的人，相信我。',RequestItemsText_loc4='<这个血精灵的眼睛睁的得好大!>$B$B你在这里干嘛?!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10318,'督工格林加尔','我曾是法力熔炉的工头，不过我已经被降职了。不久前我忽然意识到，当初从奎尔萨拉斯一路朝圣来到外域，经历多少苦难，而这一切全都是个骗局。$B$B这是凯尔萨斯为了壮大他在虚空风暴的军队而布下的骗局。$B$B我试图说服同胞们离开燃烧军团，但他们性情顽固，不肯相信我。$B$B你能帮我个忙吗？去干掉督工格林加尔，然后回到你的虚灵朋友那里，告诉他我不再与他为敌了。','杀死督工格林加尔，然后返回虚空风暴内图鲁曼的营地，向星界商人图鲁曼复命。','一个末日守卫征服者?真是奇怪!燃烧军团在那边做什么呢?$B$B所以，一部分的血精灵正在逃离。我们应该记住这点，假如我们将来想靠武力征服那里的话。至少这些事情带来了一些好消息，不是吗?$B$B来吧，$N，收下这个东西还有我最深的感激吧。','你带了什么有关法力熔炉艾拉的消息吗?你解决了工头日落吗?') ON DUPLICATE KEY UPDATE Title_loc4='督工格林加尔',Details_loc4='我曾是法力熔炉的工头，不过我已经被降职了。不久前我忽然意识到，当初从奎尔萨拉斯一路朝圣来到外域，经历多少苦难，而这一切全都是个骗局。$B$B这是凯尔萨斯为了壮大他在虚空风暴的军队而布下的骗局。$B$B我试图说服同胞们离开燃烧军团，但他们性情顽固，不肯相信我。$B$B你能帮我个忙吗？去干掉督工格林加尔，然后回到你的虚灵朋友那里，告诉他我不再与他为敌了。',Objectives_loc4='杀死督工格林加尔，然后返回虚空风暴内图鲁曼的营地，向星界商人图鲁曼复命。',OfferRewardText_loc4='一个末日守卫征服者?真是奇怪!燃烧军团在那边做什么呢?$B$B所以，一部分的血精灵正在逃离。我们应该记住这点，假如我们将来想靠武力征服那里的话。至少这些事情带来了一些好消息，不是吗?$B$B来吧，$N，收下这个东西还有我最深的感激吧。',RequestItemsText_loc4='你带了什么有关法力熔炉艾拉的消息吗?你解决了工头日落吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10319,'纳比留斯的护符匣','我想事情已经水落石出了。你应该已经和学徒拉文瑞德尔见过面了吧，不过大法师还有一位名叫纳比留斯的学徒。$B$B他是个勤奋的学生，却因沉迷通灵术而无法自拔。当凯尔萨斯率领大军逼近肯瑞瓦村时，纳比留斯借机背叛了大法师，将紫罗兰之塔的防御机密告诉了凯尔萨斯。$B$B他似乎已经沦为巫妖。如果要阻止他继续做恶，就必须夺得他的护符匣。你要知道，这个狡猾的家伙绝对不会将它埋在他视线之外的地方。','在肯瑞瓦村的礼拜堂广场中找到纳比留斯的护符匣，将它交给管理器戴沃斯。','做得好，$N。这个骨匣将是我们获胜的关键。当你与纳伯瑞厄斯战斗时，我将粉碎骨匣，使他暴露在你的攻击中。','在我们能攻击他之前，你必须取得纳伯瑞厄斯的骨匣。否则，他会是刀枪不入的。') ON DUPLICATE KEY UPDATE Title_loc4='纳比留斯的护符匣',Details_loc4='我想事情已经水落石出了。你应该已经和学徒拉文瑞德尔见过面了吧，不过大法师还有一位名叫纳比留斯的学徒。$B$B他是个勤奋的学生，却因沉迷通灵术而无法自拔。当凯尔萨斯率领大军逼近肯瑞瓦村时，纳比留斯借机背叛了大法师，将紫罗兰之塔的防御机密告诉了凯尔萨斯。$B$B他似乎已经沦为巫妖。如果要阻止他继续做恶，就必须夺得他的护符匣。你要知道，这个狡猾的家伙绝对不会将它埋在他视线之外的地方。',Objectives_loc4='在肯瑞瓦村的礼拜堂广场中找到纳比留斯的护符匣，将它交给管理器戴沃斯。',OfferRewardText_loc4='做得好，$N。这个骨匣将是我们获胜的关键。当你与纳伯瑞厄斯战斗时，我将粉碎骨匣，使他暴露在你的攻击中。',RequestItemsText_loc4='在我们能攻击他之前，你必须取得纳伯瑞厄斯的骨匣。否则，他会是刀枪不入的。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10320,'毁灭纳比留斯！','大法师沃格斯早已意识到纳比留斯研习通灵术的危险。但我想，他恐怕未曾预料到自己的学徒会给肯瑞托带来这场毁灭性的灾难。$B$B你必须击败纳比留斯，$N。否则，他将继续奴役肯瑞托法师的灵魂，让他们永远得不到安宁，最终他将使肯瑞瓦的每一寸土地都落入毁灭的深渊。$B$B只要得到了他的护符匣，我们就可以派出两到三名刺客对付他，否则，谁有知道他会对赶去围剿他的军队用出什么样的法术呢？','肯瑞瓦村的管理器戴沃斯要你击败礼拜堂广场中的纳比留斯。','击败纳伯瑞厄斯是一项伟大的成就，$N。我一直在想假如当时纳伯瑞厄斯没有背叛大法师的话，我们可能有击溃凯尔萨斯大军的机会。','你消毁了那个卑鄙的纳伯瑞厄斯的尸体了吗?') ON DUPLICATE KEY UPDATE Title_loc4='毁灭纳比留斯！',Details_loc4='大法师沃格斯早已意识到纳比留斯研习通灵术的危险。但我想，他恐怕未曾预料到自己的学徒会给肯瑞托带来这场毁灭性的灾难。$B$B你必须击败纳比留斯，$N。否则，他将继续奴役肯瑞托法师的灵魂，让他们永远得不到安宁，最终他将使肯瑞瓦的每一寸土地都落入毁灭的深渊。$B$B只要得到了他的护符匣，我们就可以派出两到三名刺客对付他，否则，谁有知道他会对赶去围剿他的军队用出什么样的法术呢？',Objectives_loc4='肯瑞瓦村的管理器戴沃斯要你击败礼拜堂广场中的纳比留斯。',OfferRewardText_loc4='击败纳伯瑞厄斯是一项伟大的成就，$N。我一直在想假如当时纳伯瑞厄斯没有背叛大法师的话，我们可能有击溃凯尔萨斯大军的机会。',RequestItemsText_loc4='你消毁了那个卑鄙的纳伯瑞厄斯的尸体了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText2_loc4) VALUES (10321,'关闭法力熔炉：库鲁恩','你在布纳尔的成功为我们燃起了新的希望，$N。$B$B我们和占星者分享了最新的发现；作为回报，他们将剩下几座法力熔炉的情况告诉了我们。$B$B目前，仍有三座法力熔炉在运作中，而且都在日怒血精灵的掌控之下。$B$B前往东边的法力熔炉：库鲁恩，从工头希兰娜手中夺得库鲁恩控制水晶。对法力熔炉：库鲁恩的控制台使用水晶，启动紧急关闭装置。$B$B$N，我们都指望你了。','前往52区以东的法力熔炉：库鲁恩，从工头希兰娜手中夺得库鲁恩控制水晶。对法力熔炉：库鲁恩的控制台使用水晶关闭法力熔炉，然后向学者卡尔亚复命。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。','做得好。只剩两个法力熔炉保持运作。$B$B很快地凯尔萨斯的主要动力就会被切断了。','你完成你的任务了吗，$N?','关闭法力熔炉：库鲁恩') ON DUPLICATE KEY UPDATE Title_loc4='关闭法力熔炉：库鲁恩',Details_loc4='你在布纳尔的成功为我们燃起了新的希望，$N。$B$B我们和占星者分享了最新的发现；作为回报，他们将剩下几座法力熔炉的情况告诉了我们。$B$B目前，仍有三座法力熔炉在运作中，而且都在日怒血精灵的掌控之下。$B$B前往东边的法力熔炉：库鲁恩，从工头希兰娜手中夺得库鲁恩控制水晶。对法力熔炉：库鲁恩的控制台使用水晶，启动紧急关闭装置。$B$B$N，我们都指望你了。',Objectives_loc4='前往52区以东的法力熔炉：库鲁恩，从工头希兰娜手中夺得库鲁恩控制水晶。对法力熔炉：库鲁恩的控制台使用水晶关闭法力熔炉，然后向学者卡尔亚复命。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。',OfferRewardText_loc4='做得好。只剩两个法力熔炉保持运作。$B$B很快地凯尔萨斯的主要动力就会被切断了。',RequestItemsText_loc4='你完成你的任务了吗，$N?',ObjectiveText2_loc4='关闭法力熔炉：库鲁恩';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText2_loc4) VALUES (10322,'关闭法力熔炉：杜隆','我们收到消息说，仍在运行的两座熔炉中，日怒血精灵突然失去了对法力熔炉：杜隆的控制。$B$B大群狂乱的法力生物被高速增长的能量流所吸引，冲入了法力熔炉。$B$B如果杜隆发生爆炸的话，很可能引发波及整个外域的大规模连锁反应。你必须从工头安萨奈尔手中夺得控制水晶，并安全关闭法力熔炉：杜隆。','学者卡尔亚要你前往法力熔炉：杜隆，从工头安萨奈尔手中夺得杜隆控制水晶。对法力熔炉：杜隆的控制台使用水晶关闭法力熔炉。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。','纳鲁祝福你，$N。你付出的供献将不会被忽略或者未受奖赏。','你完成你的任务了吗，$N?','关闭法力熔炉：杜隆') ON DUPLICATE KEY UPDATE Title_loc4='关闭法力熔炉：杜隆',Details_loc4='我们收到消息说，仍在运行的两座熔炉中，日怒血精灵突然失去了对法力熔炉：杜隆的控制。$B$B大群狂乱的法力生物被高速增长的能量流所吸引，冲入了法力熔炉。$B$B如果杜隆发生爆炸的话，很可能引发波及整个外域的大规模连锁反应。你必须从工头安萨奈尔手中夺得控制水晶，并安全关闭法力熔炉：杜隆。',Objectives_loc4='学者卡尔亚要你前往法力熔炉：杜隆，从工头安萨奈尔手中夺得杜隆控制水晶。对法力熔炉：杜隆的控制台使用水晶关闭法力熔炉。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。',OfferRewardText_loc4='纳鲁祝福你，$N。你付出的供献将不会被忽略或者未受奖赏。',RequestItemsText_loc4='你完成你的任务了吗，$N?',ObjectiveText2_loc4='关闭法力熔炉：杜隆';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText2_loc4) VALUES (10323,'关闭法力熔炉：艾拉','现在仅剩一座法力熔炉来维持整个风暴要塞的能源供给了。如果我们能摧毁法力熔炉：艾拉，凯尔就不得不启用他之前储存的能量。$B$B关闭西北方的法力熔炉：艾拉，给予凯尔萨斯最沉重的一击。$B$B最后一块控制水晶由工头阿扎拉德保管。注意，这是凯尔最后一座仍在运行中的法力熔炉，恐怕你会遭到非常顽强的抵抗。你可能会需要可靠的朋友帮忙。','前往法力熔炉：艾拉，从工头阿扎拉德手中夺得艾拉控制水晶。对法力熔炉：艾拉的控制台使用水晶关闭法力熔炉。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。','燃烧军团?与凯尔萨斯.逐日者结盟?$B$B这真是个可怕的消息。这解释了我们在这及影月所见到的景象。$B$B我们必须马上将消息传回沙塔斯城。','你完成我要求的任务了吗，$N?','关闭法力熔炉：艾拉') ON DUPLICATE KEY UPDATE Title_loc4='关闭法力熔炉：艾拉',Details_loc4='现在仅剩一座法力熔炉来维持整个风暴要塞的能源供给了。如果我们能摧毁法力熔炉：艾拉，凯尔就不得不启用他之前储存的能量。$B$B关闭西北方的法力熔炉：艾拉，给予凯尔萨斯最沉重的一击。$B$B最后一块控制水晶由工头阿扎拉德保管。注意，这是凯尔最后一座仍在运行中的法力熔炉，恐怕你会遭到非常顽强的抵抗。你可能会需要可靠的朋友帮忙。',Objectives_loc4='前往法力熔炉：艾拉，从工头阿扎拉德手中夺得艾拉控制水晶。对法力熔炉：艾拉的控制台使用水晶关闭法力熔炉。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。',OfferRewardText_loc4='燃烧军团?与凯尔萨斯.逐日者结盟?$B$B这真是个可怕的消息。这解释了我们在这及影月所见到的景象。$B$B我们必须马上将消息传回沙塔斯城。',RequestItemsText_loc4='你完成我要求的任务了吗，$N?',ObjectiveText2_loc4='关闭法力熔炉：艾拉';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10324,'狩猎月痕鹿','干得好，$n！$b$b你利用月痕雄鹿好好地磨练了自己的狩猎技术，现在是时候让你面对更强大一些的猎物了，比如月痕巨鹿。你可千万不要被月痕巨鹿寻常的那种温顺与懒洋洋的样子给骗了。只要一被激怒，它们马上就会变为最可怕的野兽。$b$b在这里的正北方就可以找到这些月痕巨鹿，祝你狩猎愉快。','将6张月痕鹿皮交给碧蓝岗哨的艾克提恩。','太完美了!你彻底变成猎人了，$N。$B$B你要如
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10325,'基尔加丹印记','你应该已经知道了，$N，我们奥尔多是圣光的守护者，是纳鲁的仆从。$B$B而我们最直接的敌人就是燃烧军团——那群以扭曲和毁灭世界，腐化和侵蚀无辜种族为乐的恶魔。$B$B如果你想对奥尔多证明自己的价值，那么就给我带一些低级燃烧军团士兵和暗影议会成员的徽记回来吧。暗影议会在白骨荒野有一处据点，而燃烧军团的据点则大多分布在刀锋山脉和纳格兰。','将10枚基尔加丹印记交给沙塔斯城内的圣光护卫者阿德因。$B$B为奥尔多完成任务将会使你在占星者声望中的声望等级降低。','对抗燃烧军团的恶魔和崇拜他们的疯狂教徒不是件容易的事，$N。你已经展现了伟大的功勋和勇气。坚持下去，你在奥多尔中的名望将继续成长。','你手上有任何我们敌人的徽记吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='基尔加丹印记',Details_loc4='你应该已经知道了，$N，我们奥尔多是圣光的守护者，是纳鲁的仆从。$B$B而我们最直接的敌人就是燃烧军团——那群以扭曲和毁灭世界，腐化和侵蚀无辜种族为乐的恶魔。$B$B如果你想对奥尔多证明自己的价值，那么就给我带一些低级燃烧军团士兵和暗影议会成员的徽记回来吧。暗影议会在白骨荒野有一处据点，而燃烧军团的据点则大多分布在刀锋山脉和纳格兰。',Objectives_loc4='将10枚基尔加丹印记交给沙塔斯城内的圣光护卫者阿德因。$B$B为奥尔多完成任务将会使你在占星者声望中的声望等级降低。',OfferRewardText_loc4='对抗燃烧军团的恶魔和崇拜他们的疯狂教徒不是件容易的事，$N。你已经展现了伟大的功勋和勇气。坚持下去，你在奥多尔中的名望将继续成长。',RequestItemsText_loc4='你手上有任何我们敌人的徽记吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10326,'更多基尔加丹印记','继续证明你的价值，$N。跟圣光的敌人战斗吧，不管他们在哪里;你的行为将获得良好的报酬。$B$B<这个任务可重复执行直到声望阶级到达尊敬。>','你带回了更多敌人的印记了吗，$C?燃烧军团仍是一个威胁，不论天涯海角我们都将继续对抗他们。') ON DUPLICATE KEY UPDATE Title_loc4='更多基尔加丹印记',OfferRewardText_loc4='继续证明你的价值，$N。跟圣光的敌人战斗吧，不管他们在哪里;你的行为将获得良好的报酬。$B$B<这个任务可重复执行直到声望阶级到达尊敬。>',RequestItemsText_loc4='你带回了更多敌人的印记了吗，$C?燃烧军团仍是一个威胁，不论天涯海角我们都将继续对抗他们。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10327,'单枚基尔加丹印记','继续证明你的价值，$N。跟圣光的敌人战斗吧，不管他们在哪里;你的行为将获得良好的报酬。$B$B<这个任务可重复执行直到声望阶级到达尊敬。>','我将拿走你剩下的所有印记。别担心;你的行为将被正式的表扬。') ON DUPLICATE KEY UPDATE Title_loc4='单枚基尔加丹印记',OfferRewardText_loc4='继续证明你的价值，$N。跟圣光的敌人战斗吧，不管他们在哪里;你的行为将获得良好的报酬。$B$B<这个任务可重复执行直到声望阶级到达尊敬。>',RequestItemsText_loc4='我将拿走你剩下的所有印记。别担心;你的行为将被正式的表扬。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10328,'日怒简报','法力熔炉的事一直在困扰着我，$N。纳鲁的科技水平遥遥领先，即便是凯尔萨斯，也应该需要数年时间才能掌握。$B$B凯尔萨斯的军队纪律严明，他们会及时销毁所有书面通信证据，情报收集工作非常艰难。$B$B我们接到消息，法力熔炉：杜隆遭到了法力生物的入侵。血精灵很可能还来不及销毁那里的文件和简报。立刻将这些东西带回来给我。','前往法力熔炉：杜隆，从日怒军团士兵手中夺得日怒军事简报和日怒奥术简报。完成任务后向大主教欧雷里斯复命。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。','做得好，$N!让我们看看能从这些简报里发现些什么。','你去法力熔炉杜罗取得简报的进展如何?') ON DUPLICATE KEY UPDATE Title_loc4='日怒简报',Details_loc4='法力熔炉的事一直在困扰着我，$N。纳鲁的科技水平遥遥领先，即便是凯尔萨斯，也应该需要数年时间才能掌握。$B$B凯尔萨斯的军队纪律严明，他们会及时销毁所有书面通信证据，情报收集工作非常艰难。$B$B我们接到消息，法力熔炉：杜隆遭到了法力生物的入侵。血精灵很可能还来不及销毁那里的文件和简报。立刻将这些东西带回来给我。',Objectives_loc4='前往法力熔炉：杜隆，从日怒军团士兵手中夺得日怒军事简报和日怒奥术简报。完成任务后向大主教欧雷里斯复命。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。',OfferRewardText_loc4='做得好，$N!让我们看看能从这些简报里发现些什么。',RequestItemsText_loc4='你去法力熔炉杜罗取得简报的进展如何?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText2_loc4) VALUES (10329,'关闭法力熔炉：布纳尔','你外出执行任务时，我和奥尔多进行了一番友好的谈话。法力熔炉极像是风暴要塞中纳鲁科技的改良建筑物。当然，大多数纳鲁建筑物都会配备安全装置，倘若出现紧急情况，就可以启动安全装置彻底废掉这类建筑物。$B$B通常，他们会利用控制水晶来关闭建筑物的控制台。瞧！这本名册上写道，工头瑟瑞狄斯掌管着控制水晶。夺得水晶，看看能不能派上用场。','返回法力熔炉：布纳尔，从工头瑟瑞狄斯手中夺得布纳尔控制水晶。对法力熔炉：布纳尔的控制台使用水晶关闭法力熔炉，然后向间谍大师萨罗迪恩复命。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。','这么做当然会成功!我是一个间谍大师;我刺探到的军情永远是正确的。$B$B无论如何，我有一个全新的刺激任务等着你去完成。你想听吗?当然你想。','计划成功了吗?老实跟你说我预计有一半的机会你会一起被炸死。','关闭法力熔炉：布纳尔') ON DUPLICATE KEY UPDATE Title_loc4='关闭法力熔炉：布纳尔',Details_loc4='你外出执行任务时，我和奥尔多进行了一番友好的谈话。法力熔炉极像是风暴要塞中纳鲁科技的改良建筑物。当然，大多数纳鲁建筑物都会配备安全装置，倘若出现紧急情况，就可以启动安全装置彻底废掉这类建筑物。$B$B通常，他们会利用控制水晶来关闭建筑物的控制台。瞧！这本名册上写道，工头瑟瑞狄斯掌管着控制水晶。夺得水晶，看看能不能派上用场。',Objectives_loc4='返回法力熔炉：布纳尔，从工头瑟瑞狄斯手中夺得布纳尔控制水晶。对法力熔炉：布纳尔的控制台使用水晶关闭法力熔炉，然后向间谍大师萨罗迪恩复命。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。',OfferRewardText_loc4='这么做当然会成功!我是一个间谍大师;我刺探到的军情永远是正确的。$B$B无论如何，我有一个全新的刺激任务等着你去完成。你想听吗?当然你想。',RequestItemsText_loc4='计划成功了吗?老实跟你说我预计有一半的机会你会一起被炸死。',ObjectiveText2_loc4='关闭法力熔炉：布纳尔';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText2_loc4) VALUES (10330,'关闭法力熔炉：库鲁恩','萨罗迪恩告诉我说，你成功地关闭了法力熔炉：布纳尔。他希望能如法炮制地关闭法力熔炉：库鲁恩，因此下令寻找拥有控制水晶的人。我们已经查明工头希兰娜掌管着控制水晶。$B$B去关闭法力熔炉：库鲁恩吧。这次别偷偷摸摸的。直接夺得水晶，关掉法力熔炉，杀死企图阻止你的技师，然后撤退。$B$B快，凯尔的走狗很快就能查到我们的下落。','从工头希兰娜手中夺得库鲁恩控制水晶。对法力熔炉：库鲁恩的控制台使用水晶关闭法力熔炉，然后向卡勒迪斯·晨光复命。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。','我们听到了全场的骚动并正要离开。很高兴看见你没有受到多大的伤害。','你完成你的任务了吗，$N?','关闭法力熔炉：库鲁恩') ON DUPLICATE KEY UPDATE Title_loc4='关闭法力熔炉：库鲁恩',Details_loc4='萨罗迪恩告诉我说，你成功地关闭了法力熔炉：布纳尔。他希望能如法炮制地关闭法力熔炉：库鲁恩，因此下令寻找拥有控制水晶的人。我们已经查明工头希兰娜掌管着控制水晶。$B$B去关闭法力熔炉：库鲁恩吧。这次别偷偷摸摸的。直接夺得水晶，关掉法力熔炉，杀死企图阻止你的技师，然后撤退。$B$B快，凯尔的走狗很快就能查到我们的下落。',Objectives_loc4='从工头希兰娜手中夺得库鲁恩控制水晶。对法力熔炉：库鲁恩的控制台使用水晶关闭法力熔炉，然后向卡勒迪斯·晨光复命。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。',OfferRewardText_loc4='我们听到了全场的骚动并正要离开。很高兴看见你没有受到多大的伤害。',RequestItemsText_loc4='你完成你的任务了吗，$N?',ObjectiveText2_loc4='关闭法力熔炉：库鲁恩';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10331,'必备的工具','你有没有在附近看见一把重型铁匠锤？我原本要用它给阿莫尔林那老家伙的马匹钉上铁蹄的，可现在却找不到了。$B$B我翻遍了整座马厩，找了十来次，还是一无所获。会不会是哪个学徒捡到铁锤，把它带回我的铁匠铺了？你愿意到那边去帮我找找吗？我的铺子就在城镇广场塔楼的东南边。','从肯瑞瓦学徒手中夺回铁匠锤，将它交给肯瑞瓦村的学徒安德雷萨。','感谢老天爷!现在我可以继续工作了。我知道你会觉得我疯了，竟然不在一般锻造的适合地点制造可以帮我赢得熟练工地位的作品，但是我不能冒险让其它的学徒们抄袭我的作品。','你找我的锤子找的还顺利吗?') ON DUPLICATE KEY UPDATE Title_loc4='必备的工具',Details_loc4='你有没有在附近看见一把重型铁匠锤？我原本要用它给阿莫尔林那老家伙的马匹钉上铁蹄的，可现在却找不到了。$B$B我翻遍了整座马厩，找了十来次，还是一无所获。会不会是哪个学徒捡到铁锤，把它带回我的铁匠铺了？你愿意到那边去帮我找找吗？我的铺子就在城镇广场塔楼的东南边。',Objectives_loc4='从肯瑞瓦学徒手中夺回铁匠锤，将它交给肯瑞瓦村的学徒安德雷萨。',OfferRewardText_loc4='感谢老天爷!现在我可以继续工作了。我知道你会觉得我疯了，竟然不在一般锻造的适合地点制造可以帮我赢得熟练工地位的作品，但是我不能冒险让其它的学徒们抄袭我的作品。',RequestItemsText_loc4='你找我的锤子找的还顺利吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10332,'铁匠大师罗恩苏斯','终于，我的学徒课程全部结束了！我真是等不及要告诉罗恩苏斯大师了。$B$B<学徒认真地听你你描述取回铁锤的经历。>$B$B他们攻击了你？所有人？圣光啊，他们一定是疯了！$B$B那我们要怎么办，$N？难道必须要杀死罗恩苏斯大师，哦，说出这话已经让我十分悲痛了。这样下去……我或许就是肯瑞瓦村唯一的铁匠了，但我相信我的能力足以满足全镇的需要。','肯瑞瓦村的学徒安德雷萨要你消灭镇上铁匠大师罗恩苏斯的鬼魂。','我的一切智识技能都是朗瑟士大师教我的。我将透过我的技能服务肯瑞瓦的人们来纪念他。','<眼泪在这个徒弟开口时冒上了他的眼眶。>$B$B你已经……解决朗瑟士大师了吗?') ON DUPLICATE KEY UPDATE Title_loc4='铁匠大师罗恩苏斯',Details_loc4='终于，我的学徒课程全部结束了！我真是等不及要告诉罗恩苏斯大师了。$B$B<学徒认真地听你你描述取回铁锤的经历。>$B$B他们攻击了你？所有人？圣光啊，他们一定是疯了！$B$B那我们要怎么办，$N？难道必须要杀死罗恩苏斯大师，哦，说出这话已经让我十分悲痛了。这样下去……我或许就是肯瑞瓦村唯一的铁匠了，但我相信我的能力足以满足全镇的需要。',Objectives_loc4='肯瑞瓦村的学徒安德雷萨要你消灭镇上铁匠大师罗恩苏斯的鬼魂。',OfferRewardText_loc4='我的一切智识技能都是朗瑟士大师教我的。我将透过我的技能服务肯瑞瓦的人们来纪念他。',RequestItemsText_loc4='<眼泪在这个徒弟开口时冒上了他的眼眶。>$B$B你已经……解决朗瑟士大师了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10333,'帮助维勒老妈','嗯，$N，不知道你是否能再帮我一个忙。$B$B我有个合作伙伴正在野外进行实验，她非常需要帮助。你不如去看看她那里的情况？$B$B我想维勒老妈一定会感激你的，别在意她的刀子嘴。$B$B她正在东部为我们拓展利益，你可以在中央生态圆顶的中央圆顶哨站中找到她。','前往虚空风暴的中央生态圆顶，与中央圆顶哨站的维勒老妈谈一谈。','什么?!他叫我“合伙人”吗?我是他的妻子!$B$B他说我有一根刻薄的舌头!唔，当我回到52区时，我要给他又大又绿的耳朵一记耳光!$B$B但是我很高兴你在这里。他有一件事情说对了;我非常需要你的帮助!','哎在这里，$g帅哥:宝贝;!$B$B什么风把你吹到这来的阿?') ON DUPLICATE KEY UPDATE Title_loc4='帮助维勒老妈',Details_loc4='嗯，$N，不知道你是否能再帮我一个忙。$B$B我有个合作伙伴正在野外进行实验，她非常需要帮助。你不如去看看她那里的情况？$B$B我想维勒老妈一定会感激你的，别在意她的刀子嘴。$B$B她正在东部为我们拓展利益，你可以在中央生态圆顶的中央圆顶哨站中找到她。',Objectives_loc4='前往虚空风暴的中央生态圆顶，与中央圆顶哨站的维勒老妈谈一谈。',OfferRewardText_loc4='什么?!他叫我“合伙人”吗?我是他的妻子!$B$B他说我有一根刻薄的舌头!唔，当我回到52区时，我要给他又大又绿的耳朵一记耳光!$B$B但是我很高兴你在这里。他有一件事情说对了;我非常需要你的帮助!',RequestItemsText_loc4='哎在这里，$g帅哥:宝贝;!$B$B什么风把你吹到这来的阿?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10334,'贝希的铃铛','在哪里呢，我的贝希跑到哪里去了？那次袭击之后，我就一直在农田和礼拜堂广场附近寻找她，可怎么都看不见她的身影！$B$B贝希留下的唯一对象就是这个老铃铛了。过去她一听到铃铛响就会跑过来，但是我这把骨头恐怕已经摇不响它了。$B$B我把贝希的铃铛交给你，你能帮我到田地那边去摇摇铃铛，看看她会不会出现……或许贝希正四处寻找着这铃铛的声音呢。','在虚空风暴肯瑞瓦村礼拜堂小丘附近的农田中找到贝希。','<从你的背包取出颈铃来，你摇动铃铛一会儿并把它秀给似乎认得它的贝丝看。母牛允许将这个铃铛的绳子系在她的颈子上，并且期待的看着你。>','<这只牛站在本来的地方，怀疑地看着你。>') ON DUPLICATE KEY UPDATE Title_loc4='贝希的铃铛',Details_loc4='在哪里呢，我的贝希跑到哪里去了？那次袭击之后，我就一直在农田和礼拜堂广场附近寻找她，可怎么都看不见她的身影！$B$B贝希留下的唯一对象就是这个老铃铛了。过去她一听到铃铛响就会跑过来，但是我这把骨头恐怕已经摇不响它了。$B$B我把贝希的铃铛交给你，你能帮我到田地那边去摇摇铃铛，看看她会不会出现……或许贝希正四处寻找着这铃铛的声音呢。',Objectives_loc4='在虚空风暴肯瑞瓦村礼拜堂小丘附近的农田中找到贝希。',OfferRewardText_loc4='<从你的背包取出颈铃来，你摇动铃铛一会儿并把它秀给似乎认得它的贝丝看。母牛允许将这个铃铛的绳子系在她的颈子上，并且期待的看着你。>',RequestItemsText_loc4='<这只牛站在本来的地方，怀疑地看着你。>';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4,ObjectiveText2_loc4,ObjectiveText3_loc4) VALUES (10335,'调查废墟','我打算立刻前往法兰伦废墟进行挖掘工作！但问题是那里恶魔肆虐，根本无法进入！$B$B或许你能帮我做些挖掘之前的初期准备工作？$B$B我想在遗迹东北角的三处地点放下测量标记。测量点附近各有一面德莱尼旗帜，很好辨认。$B$B放好测量标记后回来找我。','放置好三枚测量标记，然后返回虚空风暴的风暴尖塔里，向塞菲里恩复命。','你不会扯我的后腿吧?那真是最好的消息啊!$B$B现在你已经完成了轻松的实地调查工作，我可以带着我的团队到废墟上面去寻宝了。$B$B感谢你，$C。','动作真快。你一定是一个非常有效率的人，已经将那3个标记全部放置妥当。','放置一号测量标记','放置二号测量标记','放置三号测量标记') ON DUPLICATE KEY UPDATE Title_loc4='调查废墟',Details_loc4='我打算立刻前往法兰伦废墟进行挖掘工作！但问题是那里恶魔肆虐，根本无法进入！$B$B或许你能帮我做些挖掘之前的初期准备工作？$B$B我想在遗迹东北角的三处地点放下测量标记。测量点附近各有一面德莱尼旗帜，很好辨认。$B$B放好测量标记后回来找我。',Objectives_loc4='放置好三枚测量标记，然后返回虚空风暴的风暴尖塔里，向塞菲里恩复命。',OfferRewardText_loc4='你不会扯我的后腿吧?那真是最好的消息啊!$B$B现在你已经完成了轻松的实地调查工作，我可以带着我的团队到废墟上面去寻宝了。$B$B感谢你，$C。',RequestItemsText_loc4='动作真快。你一定是一个非常有效率的人，已经将那3个标记全部放置妥当。',ObjectiveText1_loc4='放置一号测量标记',ObjectiveText2_loc4='放置二号测量标记',ObjectiveText3_loc4='放置三号测量标记';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10336,'库鲁萨斯的爪牙','几周前，燃烧军团占据了法兰伦废墟，彻底阻碍了我们调查遗迹并挖掘文物的计划。$B$B今天早些时候我收到情报，据称一个名叫库鲁萨斯的恐惧魔王杀光了军中的其它将士，然后便开始召唤恶魔来侍奉他。$B$B$C，我要你前往东北方的法兰伦废墟，将这些恶魔全部消灭。','杀死10只库鲁萨斯的猎犬和5只库鲁萨斯之眼。然后返回虚空风暴的风暴尖塔，向虚空猎手纳乌希思复命。','做的真好。$B$B在卡露萨斯的恶魔被杀后，塞菲尔恩将能安全的把他的挖掘队带进法拉隆废墟。$B$B收下这枚硬币代表我对你的感激。','你把所有法拉隆废墟的恶魔都杀掉了没?') ON DUPLICATE KEY UPDATE Title_loc4='库鲁萨斯的爪牙',Details_loc4='几周前，燃烧军团占据了法兰伦废墟，彻底阻碍了我们调查遗迹并挖掘文物的计划。$B$B今天早些时候我收到情报，据称一个名叫库鲁萨斯的恐惧魔王杀光了军中的其它将士，然后便开始召唤恶魔来侍奉他。$B$B$C，我要你前往东北方的法兰伦废墟，将这些恶魔全部消灭。',Objectives_loc4='杀死10只库鲁萨斯的猎犬和5只库鲁萨斯之眼。然后返回虚空风暴的风暴尖塔，向虚空猎手纳乌希思复命。',OfferRewardText_loc4='做的真好。$B$B在卡露萨斯的恶魔被杀后，塞菲尔恩将能安全的把他的挖掘队带进法拉隆废墟。$B$B收下这枚硬币代表我对你的感激。',RequestItemsText_loc4='你把所有法拉隆废墟的恶魔都杀掉了没?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,EndText_loc4) VALUES (10337,'奶牛回家','你意识到贝希仍然盯着你看，就指了指萨德尔所处的位置。你告诉这头奶牛，说你想护送她安全返家。说完之后你才明白，要让奶牛听懂你的话是不可能的。$B$B你只好耸了耸肩，准备好护送她回到萨德尔身边。','护送贝希安全返回她的主人萨德尔那里。','贝丝，是你吗?$B$B<农夫转身走向你。>$B$B谢谢你带回我的贝丝，$N。没有她我活不下去!','你有找到我的贝丝吗?','护送贝希回家。') ON DUPLICATE KEY UPDATE Title_loc4='奶牛回家',Details_loc4='你意识到贝希仍然盯着你看，就指了指萨德尔所处的位置。你告诉这头奶牛，说你想护送她安全返家。说完之后你才明白，要让奶牛听懂你的话是不可能的。$B$B你只好耸了耸肩，准备好护送她回到萨德尔身边。',Objectives_loc4='护送贝希安全返回她的主人萨德尔那里。',OfferRewardText_loc4='贝丝，是你吗?$B$B<农夫转身走向你。>$B$B谢谢你带回我的贝丝，$N。没有她我活不下去!',RequestItemsText_loc4='你有找到我的贝丝吗?',EndText_loc4='护送贝希回家。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText2_loc4) VALUES (10338,'关闭法力熔炉：杜隆','法力熔炉：杜隆遭到攻击，局势已经失控？这真叫我为难！如果杜隆被摧毁，风暴要塞也就在劫难逃了。唯一的缺憾是……风暴要塞被摧毁时引发的大爆炸势必会将这片被遗忘的土地夷为平地。$B$B凯尔萨斯死掉固然很好，可是白白搭上这许多无辜的生命……就不太好吧。没办法，只能由我们来收拾凯尔萨斯留下的烂摊子咯。你只能前往法力熔炉：杜隆，在这座法力熔炉爆炸前关闭它。控制水晶由工头安萨奈尔掌管。','返回法力熔炉：杜隆，从工头安萨奈尔手中夺得杜隆控制水晶。对法力熔炉：杜隆的控制台使用水晶关闭法力熔炉，然后向间谍大师萨罗迪恩复命。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。','你已经关掉了三个法力熔炉了，$N。凯尔萨斯现在一定昏倒了吧。','你完成关闭的任务了吗?你得在我改变对这整个计划的心意前快点完成。','关闭法力熔炉：杜隆') ON DUPLICATE KEY UPDATE Title_loc4='关闭法力熔炉：杜隆',Details_loc4='法力熔炉：杜隆遭到攻击，局势已经失控？这真叫我为难！如果杜隆被摧毁，风暴要塞也就在劫难逃了。唯一的缺憾是……风暴要塞被摧毁时引发的大爆炸势必会将这片被遗忘的土地夷为平地。$B$B凯尔萨斯死掉固然很好，可是白白搭上这许多无辜的生命……就不太好吧。没办法，只能由我们来收拾凯尔萨斯留下的烂摊子咯。你只能前往法力熔炉：杜隆，在这座法力熔炉爆炸前关闭它。控制水晶由工头安萨奈尔掌管。',Objectives_loc4='返回法力熔炉：杜隆，从工头安萨奈尔手中夺得杜隆控制水晶。对法力熔炉：杜隆的控制台使用水晶关闭法力熔炉，然后向间谍大师萨罗迪恩复命。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。',OfferRewardText_loc4='你已经关掉了三个法力熔炉了，$N。凯尔萨斯现在一定昏倒了吧。',RequestItemsText_loc4='你完成关闭的任务了吗?你得在我改变对这整个计划的心意前快点完成。',ObjectiveText2_loc4='关闭法力熔炉：杜隆';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10339,'复仇军','此地正南方就是复仇军前沿基地。最近，大批复仇军在那里筹备着什么行动……或许他们是想突袭乌提斯。$B$B万一他们的目标是我们就麻烦了，我们绝不能冒这个风险，$c。立刻突破他们的外围防御网，摧毁他们的训练设施。$B$B杀死索瓦克斯上尉和他手下的士兵后，找到复仇军发射器 - 塞塔。利用它与我取得联系，我会传达给你后续的命令。','指挥官阿米尔要你杀死5名复仇军刺客、5名复仇军突击队员、2名复仇军研究员和索瓦克斯上尉，然后启动复仇军发射器 - 塞塔。','我们必须收集他们已经储存在这个区域的任何资料。','做得好，凡人……') ON DUPLICATE KEY UPDATE Title_loc4='复仇军',Details_loc4='此地正南方就是复仇军前沿基地。最近，大批复仇军在那里筹备着什么行动……或许他们是想突袭乌提斯。$B$B万一他们的目标是我们就麻烦了，我们绝不能冒这个风险，$c。立刻突破他们的外围防御网，摧毁他们的训练设施。$B$B杀死索瓦克斯上尉和他手下的士兵后，找到复仇军发射器 - 塞塔。利用它与我取得联系，我会传达给你后续的命令。',Objectives_loc4='指挥官阿米尔要你杀死5名复仇军刺客、5名复仇军突击队员、2名复仇军研究员和索瓦克斯上尉，然后启动复仇军发射器 - 塞塔。',OfferRewardText_loc4='我们必须收集他们已经储存在这个区域的任何资料。',RequestItemsText_loc4='做得好，凡人……';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10340,'破碎岗哨','$n，你曾在前线完成过那么重要的任务，现在你又显示出在武装狮鹫驾驶方面的天赋与才能……我想，我有件非常适合你的任务要交给你。$B$B这项新的任务要求你前往蛮锤部族设置在黑暗之门附近一处浮空岛屿上的前线攻击基地——破碎岗哨。那边的状况有些不太好，人员都因长期作战而身心疲惫，但你是一个富有勇气与感染力的人，在那边一定不会有问题的。$B$B和空军指挥官达比利谈谈吧，他会送你去破碎岗哨。到了那里以后，立刻向狮鹫管理员鲁恩托格·蛮锤报到。','前线指挥官金斯顿要求你与空军指挥官达比利交谈，搭乘狮鹫前往破碎岗哨，并向鲁恩托格·蛮锤报告。','哈哈!来自大陆的一个新的$r!好的，不要担心 -- 到破碎岗哨的这段飞行旅程可能会让你晕吐，但是她不会绕太远的路!$B$B而且我只有曾经看过她翻转的乱七八糟一次……或是两次。') ON DUPLICATE KEY UPDATE Title_loc4='破碎岗哨',Details_loc4='$n，你曾在前线完成过那么重要的任务，现在你又显示出在武装狮鹫驾驶方面的天赋与才能……我想，我有件非常适合你的任务要交给你。$B$B这项新的任务要求你前往蛮锤部族设置在黑暗之门附近一处浮空岛屿上的前线攻击基地——破碎岗哨。那边的状况有些不太好，人员都因长期作战而身心疲惫，但你是一个富有勇气与感染力的人，在那边一定不会有问题的。$B$B和空军指挥官达比利谈谈吧，他会送你去破碎岗哨。到了那里以后，立刻向狮鹫管理员鲁恩托格·蛮锤报到。',Objectives_loc4='前线指挥官金斯顿要求你与空军指挥官达比利交谈，搭乘狮鹫前往破碎岗哨，并向鲁恩托格·蛮锤报告。',OfferRewardText_loc4='哈哈!来自大陆的一个新的$r!好的，不要担心 -- 到破碎岗哨的这段飞行旅程可能会让你晕吐，但是她不会绕太远的路!$B$B而且我只有曾经看过她翻转的乱七八糟一次……或是两次。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10341,'乘胜追击','$N，你打探回来的消息对我们大为有利。如此一来，你就能顺利地混入法力熔炉：杜隆，狠狠地打击凯尔军队的嚣张气焰。$B$B趁法力熔炉：杜隆陷入混乱之际杀掉那些掉队的日怒士兵。$B$B跟萨罗迪恩不同，我不喜欢无意义的屠杀；不过放弃此次战略优势就太可惜了。','杀死8名日怒咒术师、6名日怒弓箭手和4名日怒百夫长。完成任务后返回52区向魔导师拉恩娜复命。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。','你做得很好，$N。凯尔萨斯的军队会很难从你今天的打击中恢复。','你完成了你的任务了吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='乘胜追击',Details_loc4='$N，你打探回来的消息对我们大为有利。如此一来，你就能顺利地混入法力熔炉：杜隆，狠狠地打击凯尔军队的嚣张气焰。$B$B趁法力熔炉：杜隆陷入混乱之际杀掉那些掉队的日怒士兵。$B$B跟萨罗迪恩不同，我不喜欢无意义的屠杀；不过放弃此次战略优势就太可惜了。',Objectives_loc4='杀死8名日怒咒术师、6名日怒弓箭手和4名日怒百夫长。完成任务后返回52区向魔导师拉恩娜复命。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。',OfferRewardText_loc4='你做得很好，$N。凯尔萨斯的军队会很难从你今天的打击中恢复。',RequestItemsText_loc4='你完成了你的任务了吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10342,'收集岩肤油块','我在52区售卖饮料，赚了不少钱。可我还想要赚更多！$B$B火箭主管总是向我抱怨说他找不到能让X-52飞上天的燃料。$B$B我们可以帮他搞定这个小问题。$B$B首先，我必须要从此地的岩肤劫掠者的油块上分解出原油来！浓缩后的原油就可以用作混合燃料的燃基。$B$B去那些紫色的岩石附近寻找岩肤劫掠者吧，替我取回它们身上的油块。','收集5块岩肤油块，将它们交给虚空风暴52区的布兹。','好了!第一号原料完成了。$B$B现在，要是你加把劲，我们可以继续收集某种可提供页岩油一点需要额外刺激的东西来将虚空火箭推进扭曲虚空里……或者是发生爆炸，看看哪个会先发生。','你取得足够的页岩了吗?我需要大量去淬取出可用于X-52 虚空火箭燃料所需的油。') ON DUPLICATE KEY UPDATE Title_loc4='收集岩肤油块',Details_loc4='我在52区售卖饮料，赚了不少钱。可我还想要赚更多！$B$B火箭主管总是向我抱怨说他找不到能让X-52飞上天的燃料。$B$B我们可以帮他搞定这个小问题。$B$B首先，我必须要从此地的岩肤劫掠者的油块上分解出原油来！浓缩后的原油就可以用作混合燃料的燃基。$B$B去那些紫色的岩石附近寻找岩肤劫掠者吧，替我取回它们身上的油块。',Objectives_loc4='收集5块岩肤油块，将它们交给虚空风暴52区的布兹。',OfferRewardText_loc4='好了!第一号原料完成了。$B$B现在，要是你加把劲，我们可以继续收集某种可提供页岩油一点需要额外刺激的东西来将虚空火箭推进扭曲虚空里……或者是发生爆炸，看看哪个会先发生。',RequestItemsText_loc4='你取得足够的页岩了吗?我需要大量去淬取出可用于X-52 虚空火箭燃料所需的油。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10343,'无尽的入侵','凯尔萨斯首先朝肯瑞瓦村西北角的军官区发动了攻击，当时那里突然传来雷鸣般的噪音，接着便从空中落下一道闪电。军官区成为了肯瑞瓦村破坏最为严重的区域。血精灵撤军后，就发生了怪事。$B$B由纯法力构成的生命体突然如潮水般从四面八方涌入村中。到目前为止，我们还能勉强牵制住肆虐的法力生物。不过如果我们能了解到凯尔萨斯所用武器的更多信息，就有机会彻底切断它们的来路。','在肯瑞瓦村中法力生物肆虐的地区收集一块魔法炸弹碎片，将它交给巫师上尉莫尔兰。','一枚法力炸弹?$B$B<莫尔兰将手中的碎片翻来翻去。>$B$B几乎难以想象!即使在达拉然里最聪明的人也不可能想象出一种像这样的武器。一定是这场大骚动在虚空中撕破一道裂隙，让这些生物可以进入我们的土地。','你有找到凯尔萨斯用来攻击村子所剩下的武器吗?') ON DUPLICATE KEY UPDATE Title_loc4='无尽的入侵',Details_loc4='凯尔萨斯首先朝肯瑞瓦村西北角的军官区发动了攻击，当时那里突然传来雷鸣般的噪音，接着便从空中落下一道闪电。军官区成为了肯瑞瓦村破坏最为严重的区域。血精灵撤军后，就发生了怪事。$B$B由纯法力构成的生命体突然如潮水般从四面八方涌入村中。到目前为止，我们还能勉强牵制住肆虐的法力生物。不过如果我们能了解到凯尔萨斯所用武器的更多信息，就有机会彻底切断它们的来路。',Objectives_loc4='在肯瑞瓦村中法力生物肆虐的地区收集一块魔法炸弹碎片，将它交给巫师上尉莫尔兰。',OfferRewardText_loc4='一枚法力炸弹?$B$B<莫尔兰将手中的碎片翻来翻去。>$B$B几乎难以想象!即使在达拉然里最聪明的人也不可能想象出一种像这样的武器。一定是这场大骚动在虚空中撕破一道裂隙，让这些生物可以进入我们的土地。',RequestItemsText_loc4='你有找到凯尔萨斯用来攻击村子所剩下的武器吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10344,'空军指挥官格莱芬加尔','空军指挥官格莱芬加尔负责管理这处蛮锤矮人的据点。如果你是第一次来到破碎岗哨，那么就应该去向他报到。$B$B他就在那边的哨塔废墟里。','与破碎岗哨的空军指挥官格莱芬加尔谈一谈。','你与符文衣谈过了吗?他是一个好的矮人。将他的狮鹫保持在良好状态，随时准备好战斗。$B$B我是葛莱弗卡尔，破碎岗哨的指挥官。我知道这看起来不漂亮，但这块岩石是一个突击地狱火的重要据点。你会看到狮鹫不停地飞进飞出!$B$B忠告?这里有一些:保持你的设备满载，掏空你的胃，以及将你的视线盯在地平线……如果破碎岗哨开始摇晃，就抓住不会漂浮离开的东西!') ON DUPLICATE KEY UPDATE Title_loc4='空军指挥官格莱芬加尔',Details_loc4='空军指挥官格莱芬加尔负责管理这处蛮锤矮人的据点。如果你是第一次来到破碎岗哨，那么就应该去向他报到。$B$B他就在那边的哨塔废墟里。',Objectives_loc4='与破碎岗哨的空军指挥官格莱芬加尔谈一谈。',OfferRewardText_loc4='你与符文衣谈过了吗?他是一个好的矮人。将他的狮鹫保持在良好状态，随时准备好战斗。$B$B我是葛莱弗卡尔，破碎岗哨的指挥官。我知道这看起来不漂亮，但这块岩石是一个突击地狱火的重要据点。你会看到狮鹫不停地飞进飞出!$B$B忠告?这里有一些:保持你的设备满载，掏空你的胃，以及将你的视线盯在地平线……如果破碎岗哨开始摇晃，就抓住不会漂浮离开的东西!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4) VALUES (10345,'血肉会撒谎……','$r，瞧见这些尸体了吗？是阿克努斯干的。他吸干了尸体，只留下一具干枯的躯壳。但是，你千万别被表象欺骗了！尸体中蛰伏着蠢蠢欲动的血肉兽，随时准备伏击那些放松警惕的蠢材。$B$B我刚刚接到新的指令，必须留在这里等待增援。不如你拿上我的点火器，替我烧毁矿井中的干枯的尸体。无论如何，我们必须完成任务。','对12具干枯的尸体使用维序派点火器。完成任务后将维序派点火器还给瑟安竖井外的代理人阿拉克塞。','你救了我的伪装，$N。护国者将会知道你今日的作为，朋友。','亚希克斯找得如何?','焚烧干枯的尸体') ON DUPLICATE KEY UPDATE Title_loc4='血肉会撒谎……',Details_loc4='$r，瞧见这些尸体了吗？是阿克努斯干的。他吸干了尸体，只留下一具干枯的躯壳。但是，你千万别被表象欺骗了！尸体中蛰伏着蠢蠢欲动的血肉兽，随时准备伏击那些放松警惕的蠢材。$B$B我刚刚接到新的指令，必须留在这里等待增援。不如你拿上我的点火器，替我烧毁矿井中的干枯的尸体。无论如何，我们必须完成任务。',Objectives_loc4='对12具干枯的尸体使用维序派点火器。完成任务后将维序派点火器还给瑟安竖井外的代理人阿拉克塞。',OfferRewardText_loc4='你救了我的伪装，$N。护国者将会知道你今日的作为，朋友。',RequestItemsText_loc4='亚希克斯找得如何?',ObjectiveText1_loc4='焚烧干枯的尸体';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText3_loc4) VALUES (10346,'返回地狱岩床','$n，听说你早已证明自己是个合格的狮鹫骑士了。现在，我们正好需要你的力量，来协助地狱岩床附近的作战。你怎么说，$c？还想再来几次飞行吗？','地狱火半岛破碎岗哨的狮鹫骑士维比洛要求你杀死20个甘尔葛苦工和5个莫尔葛监工，并摧毁5门邪能火炮。','这次进展如何?你状况很不错喔……或许好到甚至可以进行下一个回合!','在这个深渊沙洲上仍然有许多的目标，$N。当你准备好进行下一回合时找只狮鹫兽吧。','摧毁邪能火炮') ON DUPLICATE KEY UPDATE Title_loc4='返回地狱岩床',Details_loc4='$n，听说你早已证明自己是个合格的狮鹫骑士了。现在，我们正好需要你的力量，来协助地狱岩床附近的作战。你怎么说，$c？还想再来几次飞行吗？',Objectives_loc4='地狱火半岛破碎岗哨的狮鹫骑士维比洛要求你杀死20个甘尔葛苦工和5个莫尔葛监工，并摧毁5门邪能火炮。',OfferRewardText_loc4='这次进展如何?你状况很不错喔……或许好到甚至可以进行下一个回合!',RequestItemsText_loc4='在这个深渊沙洲上仍然有许多的目标，$N。当你准备好进行下一回合时找只狮鹫兽吧。',ObjectiveText3_loc4='摧毁邪能火炮';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText3_loc4) VALUES (10347,'返回地狱岩床','$n，你已经准备再次去突袭地狱岩床了吗？我担心如果我们不继续向那里的燃烧军团施加压力，一旦他们增强了要塞的军力，大批的恶魔就会从北边袭击我们。$B$B你觉得呢，$c？你愿意乘坐驭风者，再次去轰炸地狱岩床的燃烧军团吗？','地狱火半岛机甲残骸的空军指挥官布拉克要求你杀死20个甘尔葛苦工和5个莫尔葛监工，并摧毁5门邪能火炮。','其它的双足飞龙飞行员对你赞扬极高，$N。你在深渊沙洲上的击杀得到了相当多的分数。保持好成绩!','军团一定不认为他们在这深渊沙洲的高顶上是安全的。我们一定要不断的攻击他们!','摧毁邪能火炮') ON DUPLICATE KEY UPDATE Title_loc4='返回地狱岩床',Details_loc4='$n，你已经准备再次去突袭地狱岩床了吗？我担心如果我们不继续向那里的燃烧军团施加压力，一旦他们增强了要塞的军力，大批的恶魔就会从北边袭击我们。$B$B你觉得呢，$c？你愿意乘坐驭风者，再次去轰炸地狱岩床的燃烧军团吗？',Objectives_loc4='地狱火半岛机甲残骸的空军指挥官布拉克要求你杀死20个甘尔葛苦工和5个莫尔葛监工，并摧毁5门邪能火炮。',OfferRewardText_loc4='其它的双足飞龙飞行员对你赞扬极高，$N。你在深渊沙洲上的击杀得到了相当多的分数。保持好成绩!',RequestItemsText_loc4='军团一定不认为他们在这深渊沙洲的高顶上是安全的。我们一定要不断的攻击他们!',ObjectiveText3_loc4='摧毁邪能火炮';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10348,'新的机遇','我听说一群来自艾泽拉斯世界的“德鲁伊”对生态圆顶技术非常感兴趣。$B$B塞纳里奥远征队的代表希望得到生长在圆顶内的植株，尤其是象牙铃笼草，这种植物
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10349,'缚地者','你应该把这块水晶碎片交给缚地者。她跟你一样……总是喜欢思考，并以揭开一个又一个的谜团为乐。$B$B其实在我看来，她倒是根本不用去想那么多事的。$B$B你把这块水晶碎片交给她吧，然后，为了弄清坠星山事件的真相，她肯定会丢一堆麻烦的事情给你去做的。','将火红水晶碎片交给地狱火半岛塞纳里奥哨站的缚地者加兰蒂娅·夜风。','噢，太好了!我一直等待把那件东西弄到手，但是塔拉希恩一直拖拖拉拉的。$B$B他应该是到那去帮我调查坠天山脉发生了什么事。相反的他只是不断的派你这种可怜的傻瓜 - 别生气 - 上去那里送死。$B$B假如你给我水晶，或许我能找到在它与戈罗西之间的关联。','那就是来自坠天山脉上大水晶裂片的一部分吗?') ON DUPLICATE KEY UPDATE Title_loc4='缚地者',Details_loc4='你应该把这块水晶碎片交给缚地者。她跟你一样……总是喜欢思考，并以揭开一个又一个的谜团为乐。$B$B其实在我看来，她倒是根本不用去想那么多事的。$B$B你把这块水晶碎片交给她吧，然后，为了弄清坠星山事件的真相，她肯定会丢一堆麻烦的事情给你去做的。',Objectives_loc4='将火红水晶碎片交给地狱火半岛塞纳里奥哨站的缚地者加兰蒂娅·夜风。',OfferRewardText_loc4='噢，太好了!我一直等待把那件东西弄到手，但是塔拉希恩一直拖拖拉拉的。$B$B他应该是到那去帮我调查坠天山脉发生了什么事。相反的他只是不断的派你这种可怜的傻瓜 - 别生气 - 上去那里送死。$B$B假如你给我水晶，或许我能找到在它与戈罗西之间的关联。',RequestItemsText_loc4='那就是来自坠天山脉上大水晶裂片的一部分吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10350,'贝霍玛特','在我这里学习的这段时间里，你掌握了许多艰难的技术，现在是时候把你托付更有智慧的老师了。$b$b贝霍玛特在我初出茅庐的时候曾经训练过我，他将是你新导师。我告诉过他说，你马上就会去找他，他也正期待着你的到达呢。$b$b他就在埃索达内贸易阶梯最高处的战士平台的中央。','与埃索达贸易阶梯的贝霍玛特谈一谈。','啊，你终于来了。我是毕和玛特，我将指导你战士的技能。罗达有跟我说过你对抗劫毁者的试验，令我印象深刻。我有个礼物要给你。$B$B我们从埃索达的残骸那里找到有用的东西不多，所以一定得交给最适合的人。请拿着适合你战斗风格的武器并用你学到的知识来使用它。$B$B而谈到作战风格，是你学习新的事物的时候了。') ON DUPLICATE KEY UPDATE Title_loc4='贝霍玛特',Details_loc4='在我这里学习的这段时间里，你掌握了许多艰难的技术，现在是时候把你托付更有智慧的老师了。$b$b贝霍玛特在我初出茅庐的时候曾经训练过我，他将是你新导师。我告诉过他说，你马上就会去找他，他也正期待着你的到达呢。$b$b他就在埃索达内贸易阶梯最高处的战士平台的中央。',Objectives_loc4='与埃索达贸易阶梯的贝霍玛特谈一谈。',OfferRewardText_loc4='啊，你终于来了。我是毕和玛特，我将指导你战士的技能。罗达有跟我说过你对抗劫毁者的试验，令我印象深刻。我有个礼物要给你。$B$B我们从埃索达的残骸那里找到有用的东西不多，所以一定得交给最适合的人。请拿着适合你战斗风格的武器并用你学到的知识来使用它。$B$B而谈到作战风格，是你学习新的事物的时候了。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4) VALUES (10351,'自然的治愈','一定是水晶散发出的邪恶力量将那些山丘巨人吸引到周围，而且还令它们发狂了。$B$B那块水晶实在太大了，我们根本没办法把它移走，毁掉它似乎也不太现实……不过，我想我知道一个办法，至少可以驱散它的力量。$B$B我已经在坠星山的水晶西北角布置了一个法阵。你将这粒种子带到法阵去，引导它蕴涵的魔法能量，通过细雨、骄阳和轻风这些自然的力量治愈那片土地。$B$B不过，$N，你一定要小心，我可以感觉到有一股外界的力量……邪恶的力量盘踞在那里！','在缚地者法阵中使用新生之种，治愈水晶周围的土地。然后返回地狱火半岛的塞纳里奥哨站，向缚地者加兰蒂娅·夜风汇报情况。','哥利亚森?计算者帕萨雷恩?$B$B凯尔萨斯!?$B$B凯尔萨斯王子也有参予这件事?$B$B<缚地者感到愤怒。>这么做他简直是疯了!从空中丢下巨大的水晶并且毁坏大地这种事情只有疯子才做的出来!$B$B我可以向你保证，假如他们的部队还想尝试任何进一步的行动那么塞纳里奥远征队将会反击回去直到类似的事件不再发生。$B$B我们欠你的人情实在太多了，$N。','有用吗?你学到了什么?你找出是谁或者什么东西在背后主导发生在坠天山脉的事件吗?','治愈坠星山') ON DUPLICATE KEY UPDATE Title_loc4='自然的治愈',Details_loc4='一定是水晶散发出的邪恶力量将那些山丘巨人吸引到周围，而且还令它们发狂了。$B$B那块水晶实在太大了，我们根本没办法把它移走，毁掉它似乎也不太现实……不过，我想我知道一个办法，至少可以驱散它的力量。$B$B我已经在坠星山的水晶西北角布置了一个法阵。你将这粒种子带到法阵去，引导它蕴涵的魔法能量，通过细雨、骄阳和轻风这些自然的力量治愈那片土地。$B$B不过，$N，你一定要小心，我可以感觉到有一股外界的力量……邪恶的力量盘踞在那里！',Objectives_loc4='在缚地者法阵中使用新生之种，治愈水晶周围的土地。然后返回地狱火半岛的塞纳里奥哨站，向缚地者加兰蒂娅·夜风汇报情况。',OfferRewardText_loc4='哥利亚森?计算者帕萨雷恩?$B$B凯尔萨斯!?$B$B凯尔萨斯王子也有参予这件事?$B$B<缚地者感到愤怒。>这么做他简直是疯了!从空中丢下巨大的水晶并且毁坏大地这种事情只有疯子才做的出来!$B$B我可以向你保证，假如他们的部队还想尝试任何进一步的行动那么塞纳里奥远征队将会反击回去直到类似的事件不再发生。$B$B我们欠你的人情实在太多了，$N。',RequestItemsText_loc4='有用吗?你学到了什么?你找出是谁或者什么东西在背后主导发生在坠天山脉的事件吗?',ObjectiveText1_loc4='治愈坠星山';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10352,'捐献毛料','太好了!我们感谢你慷慨的捐赠，$N!','我们现在接受毛料的捐赠。只要捐赠60块毛料，埃索达就会对你的慷慨行为表示感谢。我们只需要你捐赠60块毛料就够了，更多的毛料可以从其他志愿者的捐赠获得。$B$B如果你有60块毛料并且愿意进行捐献的话，那现在就可以给我了。') ON DUPLICATE KEY UPDATE Title_loc4='捐献毛料',OfferRewardText_loc4='太好了!我们感谢你慷慨的捐赠，$N!',RequestItemsText_loc4='我们现在接受毛料的捐赠。只要捐赠60块毛料，埃索达就会对你的慷慨行为表示感谢。我们只需要你捐赠60块毛料就够了，更多的毛料可以从其他志愿者的捐赠获得。$B$B如果你有60块毛料并且愿意进行捐献的话，那现在就可以给我了。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10353,'贪婪者阿克努斯','两天前，我和阿拉克塞奉命来到乌提斯。我们的任务是找到并消灭虚空领主阿克努斯。我们一路追踪着他来到这座矿井，发现他一直在这片区域吸取其它生物体内的能量。$B$B在与阿克努斯初次交战的过程中，我和阿拉克塞失散了。眼下我身负重伤，被困在这里动弹不得。但任务绝不能就这样失败！$B$B如果你能消灭阿克努斯的话，指挥官一定会对你表示感谢的。你愿意接受这项任务吗？我的镜像会协助你作战。','虚空风暴瑟安竖井的代理人亚希克斯要你杀死贪婪者阿克努斯，然后向虚空风暴维序派哨站的指挥官阿米尔复命。','亚希克斯呢?他还健在吗?$B$B我们只好希望如此了。我无法让增援部队回到他们那里……复仇军现在占领了整个地区。$B$B抱歉，我差点忘记你的报酬了。','报出名来，凡人?报上你的名来?') ON DUPLICATE KEY UPDATE Title_loc4='贪婪者阿克努斯',Details_loc4='两天前，我和阿拉克塞奉命来到乌提斯。我们的任务是找到并消灭虚空领主阿克努斯。我们一路追踪着他来到这座矿井，发现他一直在这片区域吸取其它生物体内的能量。$B$B在与阿克努斯初次交战的过程中，我和阿拉克塞失散了。眼下我身负重伤，被困在这里动弹不得。但任务绝不能就这样失败！$B$B如果你能消灭阿克努斯的话，指挥官一定会对你表示感谢的。你愿意接受这项任务吗？我的镜像会协助你作战。',Objectives_loc4='虚空风暴瑟安竖井的代理人亚希克斯要你杀死贪婪者阿克努斯，然后向虚空风暴维序派哨站的指挥官阿米尔复命。',OfferRewardText_loc4='亚希克斯呢?他还健在吗?$B$B我们只好希望如此了。我无法让增援部队回到他们那里……复仇军现在占领了整个地区。$B$B抱歉，我差点忘记你的报酬了。',RequestItemsText_loc4='报出名来，凡人?报上你的名来?';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10354,'捐献丝绸','太好了!我们感谢你慷慨的捐赠，$N!','和其他纺织材料一样，我们的丝绸库存也已经降到了历史最低点。如果有足够的补给，我们就可以达成预期的目标。$B$B如果你愿意将丝绸作为礼物送给我们的话，那你在这个社区中的地位无疑将大大提升!那么，要是你有60块丝绸并且愿意把它们捐出来，那现在就可以给我了。') ON DUPLICATE KEY UPDATE Title_loc4='捐献丝绸',OfferRewardText_loc4='太好了!我们感谢你慷慨的捐赠，$N!',RequestItemsText_loc4='和其他纺织材料一样，我们的丝绸库存也已经降到了历史最低点。如果有足够的补给，我们就可以达成预期的目标。$B$B如果你愿意将丝绸作为礼物送给我们的话，那你在这个社区中的地位无疑将大大提升!那么，要是你有60块丝绸并且愿意把它们捐出来，那现在就可以给我了。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10355,'枯萎的血肉','我们必须搞清楚灾害的波及范围究竟有多广。你带回的孢芽来自于某个泥沼巨人。沼泽领主是泥沼巨人的近亲，但是他们的体型较大，足以抵御困扰发生在泥沼巨人身上的衰竭现象。$B$B我们最好查明死亡泥潭的水位变化是否影响到了居住在那里的其它生物。$B$B返回死亡泥潭，替我取回一些多头蛇的样本和沼泽领主的样本。','将5份干燥的多头蛇样本和5份枯萎的沼泽领主样本交给泰雷多尔的鲁埃姆。','<洛安玛检验了那些样本，看起来很忧伤。>$B$B这正是我所担心的，$N。逐渐干枯的环境对那些从没想过要住在沼泽以外的生物造成很大的负担。我们只好继续观察该区域然后跟塞纳里奥远征队协商看看我们能做些什么。','你能够去收集这些样本吗?') ON DUPLICATE KEY UPDATE Title_loc4='枯萎的血肉',Details_loc4='我们必须搞清楚灾害的波及范围究竟有多广。你带回的孢芽来自于某个泥沼巨人。沼泽领主是泥沼巨人的近亲，但是他们的体型较大，足以抵御困扰发生在泥沼巨人身上的衰竭现象。$B$B我们最好查明死亡泥潭的水位变化是否影响到了居住在那里的其它生物。$B$B返回死亡泥潭，替我取回一些多头蛇的样本和沼泽领主的样本。',Objectives_loc4='将5份干燥的多头蛇样本和5份枯萎的沼泽领主样本交给泰雷多尔的鲁埃姆。',OfferRewardText_loc4='<洛安玛检验了那些样本，看起来很忧伤。>$B$B这正是我所担心的，$N。逐渐干枯的环境对那些从没想过要住在沼泽以外的生物造成很大的负担。我们只好继续观察该区域然后跟塞纳里奥远征队协商看看我们能做些什么。',RequestItemsText_loc4='你能够去收集这些样本吗?';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10356,'捐献魔纹布','太好了!我们感谢你慷慨的捐赠，$N!','我们的魔纹布储量很低，而你可以帮助我们补充库存!如果计算整个社区所能作出的贡献的话，我们只需要从你那里获得60块魔纹布就可以达到我们的目标了。你这样的慷慨贡献一定会被埃索达的德莱尼广为传颂，这一点我可以向你保证!$B$B如果你有60块魔纹布并且愿意捐赠的话，那现在就可以给我了。') ON DUPLICATE KEY UPDATE Title_loc4='捐献魔纹布',OfferRewardText_loc4='太好了!我们感谢你慷慨的捐赠，$N!',RequestItemsText_loc4='我们的魔纹布储量很低，而你可以帮助我们补充库存!如果计算整个社区所能作出的贡献的话，我们只需要从你那里获得60块魔纹布就可以达到我们的目标了。你这样的慷慨贡献一定会被埃索达的德莱尼广为传颂，这一点我可以向你保证!$B$B如果你有60块魔纹布并且愿意捐赠的话，那现在就可以给我了。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10357,'捐献符文布','太棒了―我向你保证，这些一定能派上用场。再次感谢你的帮助!如果没有你的话，我们肯定会一筹莫展的。$B$B鉴于你一贯的慷慨，我会欣然接受你随时捐赠更多的符文布。请及时与我联系，我个人可以确保你所做的好事一定会被广为传颂!','$N，你对于我们的布匹储量做出了巨大的贡献。我们正在尽力补充我们的物资，而我要告诉你的是，现在我们最需要的是符文布。我们的符文布储量实在是太匮乏了，希望你能一如既往地帮助我们。$B$B如果你愿意的话，请把你多馀的符文布捐献给我。我们现在接受一次60块符文布捐赠。') ON DUPLICATE KEY UPDATE Title_loc4='捐献符文布',OfferRewardText_loc4='太棒了―我向你保证，这些一定能派上用场。再次感谢你的帮助!如果没有你的话，我们肯定会一筹莫展的。$B$B鉴于你一贯的慷慨，我会欣然接受你随时捐赠更多的符文布。请及时与我联系，我个人可以确保你所做的好事一定会被广为传颂!',RequestItemsText_loc4='$N，你对于我们的布匹储量做出了巨大的贡献。我们正在尽力补充我们的物资，而我要告诉你的是，现在我们最需要的是符文布。我们的符文布储量实在是太匮乏了，希望你能一如既往地帮助我们。$B$B如果你愿意的话，请把你多馀的符文布捐献给我。我们现在接受一次60块符文布捐赠。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10358,'更多的符文布','$N―如果没有像你这样的英雄为埃索达亲力亲为的话，我们肯定会碰到很多麻烦。感谢你为我们付出的努力!','你好，$N!我们的符文布一直比较紧缺，如果你可以省出一些符文布来给我们的话，我们总是表示欢迎的。要是你可以再给我们20块符文布，那么我可以保证，你一定会因为对于埃索达的贡献而被大家认同。$B$B随时欢迎你捐献符文布。') ON DUPLICATE KEY UPDATE Title_loc4='更多的符文布',OfferRewardText_loc4='$N―如果没有像你这样的英雄为埃索达亲力亲为的话，我们肯定会碰到很多麻烦。感谢你为我们付出的努力!',RequestItemsText_loc4='你好，$N!我们的符文布一直比较紧缺，如果你可以省出一些符文布来给我们的话，我们总是表示欢迎的。要是你可以再给我们20块符文布，那么我可以保证，你一定会因为对于埃索达的贡献而被大家认同。$B$B随时欢迎你捐献符文布。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10359,'捐献毛料','太好了!我们感谢你慷慨的捐赠，$N!','我们现在接受毛料的捐赠。只要捐赠60块毛料，银月城就会对你的慷慨行为表示感谢。我们只需要你捐赠60块毛料就够了，更多的毛料可以从其它志愿者的捐赠获得。$B$B如果你有60块毛料并且愿意进行捐献的话，那现在就可以给我了。') ON DUPLICATE KEY UPDATE Title_loc4='捐献毛料',OfferRewardText_loc4='太好了!我们感谢你慷慨的捐赠，$N!',RequestItemsText_loc4='我们现在接受毛料的捐赠。只要捐赠60块毛料，银月城就会对你的慷慨行为表示感谢。我们只需要你捐赠60块毛料就够了，更多的毛料可以从其它志愿者的捐赠获得。$B$B如果你有60块毛料并且愿意进行捐献的话，那现在就可以给我了。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10360,'捐献丝绸','太好了!我们感谢你慷慨的捐赠，$N!','和其它纺织材料一样，我们的丝绸库存也已经降到了历史最低点。如果有足够的补给，我们就可以达成预期的目标。$B$B如果你愿意将丝绸作为礼物送给我们的话，那你在这个社区中的地位无疑将大大提升!那么，要是你有60块丝绸并且愿意把它们捐出来，那现在就可以给我了。') ON DUPLICATE KEY UPDATE Title_loc4='捐献丝绸',OfferRewardText_loc4='太好了!我们感谢你慷慨的捐赠，$N!',RequestItemsText_loc4='和其它纺织材料一样，我们的丝绸库存也已经降到了历史最低点。如果有足够的补给，我们就可以达成预期的目标。$B$B如果你愿意将丝绸作为礼物送给我们的话，那你在这个社区中的地位无疑将大大提升!那么，要是你有60块丝绸并且愿意把它们捐出来，那现在就可以给我了。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10361,'捐献魔纹布','太好了!我们感谢你慷慨的捐赠，$N!','我们的魔纹布储量很低，而你可以帮助我们补充库存!如果计算整个社区所能作出的贡献的话，我们只需要从你那里获得60块魔纹布就可以达到我们的目标了。你这样的慷慨贡献一定会被银月城的血精灵广为传颂，这一点我可以向你保证!$B$B如果你有60块魔纹布并且愿意捐赠的话，那现在就可以给我了。') ON DUPLICATE KEY UPDATE Title_loc4='捐献魔纹布',OfferRewardText_loc4='太好了!我们感谢你慷慨的捐赠，$N!',RequestItemsText_loc4='我们的魔纹布储量很低，而你可以帮助我们补充库存!如果计算整个社区所能作出的贡献的话，我们只需要从你那里获得60块魔纹布就可以达到我们的目标了。你这样的慷慨贡献一定会被银月城的血精灵广为传颂，这一点我可以向你保证!$B$B如果你有60块魔纹布并且愿意捐赠的话，那现在就可以给我了。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10362,'捐献符文布','太棒了―我向你保证，这些一定能派上用场。再次感谢你的帮助!如果没有你的话，我们肯定会一筹莫展的。$B$B鉴于你一贯的慷慨，我会欣然接受你随时捐赠更多的符文布。请及时与我联系，我个人可以确保你所做的好事一定会被广为传颂!','$N，你对于我们的布匹储量做出了巨大的贡献。我们正在尽力补充我们的物资，而我要告诉你的是，现在我们最需要的是符文布。我们的符文布储量实在是太匮乏了，希望你能一如既往地帮助我们。$B$B如果你愿意的话，请把你多馀的符文布捐献给我。我们现在接受一次60块符文布捐赠。') ON DUPLICATE KEY UPDATE Title_loc4='捐献符文布',OfferRewardText_loc4='太棒了―我向你保证，这些一定能派上用场。再次感谢你的帮助!如果没有你的话，我们肯定会一筹莫展的。$B$B鉴于你一贯的慷慨，我会欣然接受你随时捐赠更多的符文布。请及时与我联系，我个人可以确保你所做的好事一定会被广为传颂!',RequestItemsText_loc4='$N，你对于我们的布匹储量做出了巨大的贡献。我们正在尽力补充我们的物资，而我要告诉你的是，现在我们最需要的是符文布。我们的符文布储量实在是太匮乏了，希望你能一如既往地帮助我们。$B$B如果你愿意的话，请把你多馀的符文布捐献给我。我们现在接受一次60块符文布捐赠。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10363,'更多的符文布','$N―如果没有像你这样的英雄为银月城亲力亲为的话，我们肯定会碰到很多麻烦。感谢你为我们付出的努力!','你好，$N!我们的符文布一直比较紧缺，如果你可以省出一些符文布来给我们的话，我们总是表示欢迎的。要是你可以再给我们20块符文布，那么我可以保证，你一定会因为对于银月城的贡献而被大家认同。$B$B随时欢迎你捐献符文布。') ON DUPLICATE KEY UPDATE Title_loc4='更多的符文布',OfferRewardText_loc4='$N―如果没有像你这样的英雄为银月城亲力亲为的话，我们肯定会碰到很多麻烦。感谢你为我们付出的努力!',RequestItemsText_loc4='你好，$N!我们的符文布一直比较紧缺，如果你可以省出一些符文布来给我们的话，我们总是表示欢迎的。要是你可以再给我们20块符文布，那么我可以保证，你一定会因为对于银月城的贡献而被大家认同。$B$B随时欢迎你捐献符文布。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10364,'凯德莫斯','你在短时间内的进步相当可观，$n，远比我想象和希望得要快。差不多是时候让你继续接受凯德莫斯的指导和监护了。$b$b我已经给他带去了口信，他也正在埃索达等着你呢。你可以在圣光穹顶门口附近的学者圣殿找到他。','与埃索达圣光穹顶的凯德莫斯谈一谈。','欢迎到隐士圣所，$N。我已经听到非常多关于你的事，并且一直期待继续你的训练。$B$B当你准备好更进一步训练时，到我这里来，我将抽出时间指导你。') ON DUPLICATE KEY UPDATE Title_loc4='凯德莫斯',Details_loc4='你在短时间内的进步相当可观，$n，远比我想象和希望得要快。差不多是时候让你继续接受凯德莫斯的指导和监护了。$b$b我已经给他带去了口信，他也正在埃索达等着你呢。你可以在圣光穹顶门口附近的学者圣殿找到他。',Objectives_loc4='与埃索达圣光穹顶的凯德莫斯谈一谈。',OfferRewardText_loc4='欢迎到隐士圣所，$N。我已经听到非常多关于你的事，并且一直期待继续你的训练。$B$B当你准备好更进一步训练时，到我这里来，我将抽出时间指导你。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText2_loc4) VALUES (10365,'关闭法力熔炉：艾拉','你取得的成就完全出乎我们的意料。法力熔炉：艾拉是凯尔萨斯硕果仅存的一座法力熔炉。它位于此地西北方的浮岛上，不过你得绕一大圈才能到达那儿。关闭最后这座法力熔炉。$B$B控制水晶由工头阿扎拉德掌管。据我们所知，法力熔炉：艾拉是凯尔最后一处能量来源，必定驻派了重兵把守。换做是我的话，我会叫上一帮朋友共同前往。$B$B唔……阿扎拉德。辛多雷取这样的名字真是古怪。','前往法力熔炉：艾拉，从工头阿扎拉德手中夺得艾拉控制水晶。对法力熔炉：艾拉的控制台使用水晶关闭法力熔炉。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。','燃烧军团与凯尔合伙?嘿!听到这情报沃蓝索将会很高兴。$B$B你认为来自艾泽拉斯的数千位朝圣者想要与燃烧军团有关联吗?我认为不会喔!','你完成了我要求你的任务了吗，$N?','关闭法力熔炉：艾拉') ON DUPLICATE KEY UPDATE Title_loc4='关闭法力熔炉：艾拉',Details_loc4='你取得的成就完全出乎我们的意料。法力熔炉：艾拉是凯尔萨斯硕果仅存的一座法力熔炉。它位于此地西北方的浮岛上，不过你得绕一大圈才能到达那儿。关闭最后这座法力熔炉。$B$B控制水晶由工头阿扎拉德掌管。据我们所知，法力熔炉：艾拉是凯尔最后一处能量来源，必定驻派了重兵把守。换做是我的话，我会叫上一帮朋友共同前往。$B$B唔……阿扎拉德。辛多雷取这样的名字真是古怪。',Objectives_loc4='前往法力熔炉：艾拉，从工头阿扎拉德手中夺得艾拉控制水晶。对法力熔炉：艾拉的控制台使用水晶关闭法力熔炉。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。',OfferRewardText_loc4='燃烧军团与凯尔合伙?嘿!听到这情报沃蓝索将会很高兴。$B$B你认为来自艾泽拉斯的数千位朝圣者想要与燃烧军团有关联吗?我认为不会喔!',RequestItemsText_loc4='你完成了我要求你的任务了吗，$N?',ObjectiveText2_loc4='关闭法力熔炉：艾拉';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10366,'约尔','圣光与净化之路并非是一条容易前行的道路，$n。即使是我，在追随它的过程中也经历了数次动摇。$b$b现在你立刻到埃索达去寻找我过去的导师约尔。在我刚刚开始追寻圣光之时，就是她指引了我。我相信，她很快就会发现你也是一位十分优秀的学生。$b$b你在埃索达圣光穹顶的守备官圣殿就可以找到她，那是一处充满了圣光力量的房间。','与埃索达守备官圣殿的约尔谈一谈。','$N，我一直在等着你。$B$B朵拉斯已经传颂了对你的赞赏，我期待在圣光的道路上能够继续你的训练。当你准备更进一步了解你的能力和力量时，我将会引导你。') ON DUPLICATE KEY UPDATE Title_loc4='约尔',Details_loc4='圣光与净化之路并非是一条容易前行的道路，$n。即使是我，在追随它的过程中也经历了数次动摇。$b$b现在你立刻到埃索达去寻找我过去的导师约尔。在我刚刚开始追寻圣光之时，就是她指引了我。我相信，她很快就会发现你也是一位十分优秀的学生。$b$b你在埃索达圣光穹顶的守备官圣殿就可以找到她，那是一处充满了圣光力量的房间。',Objectives_loc4='与埃索达守备官圣殿的约尔谈一谈。',OfferRewardText_loc4='$N，我一直在等着你。$B$B朵拉斯已经传颂了对你的赞赏，我期待在圣光的道路上能够继续你的训练。当你准备更进一步了解你的能力和力量时，我将会引导你。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10367,'叛徒','在每个被奴役的破碎者部族中，必定有一位叛徒作祟。这个卑鄙的家伙为了得到力量不惜出卖自己的同胞。$B$B沙纳尔废墟中心的阶梯顶部有一间小屋。那便是背叛者的居所。$B$B他现在恰好不在，如果你有耐心的话，可以悄悄地潜进去。小屋中有个箱子，里面的钥匙可以打开囚禁残冠长者的镣铐。把钥匙带回来给我。$B$B千万小心，无情的阿尔泽斯就在小屋附近徘徊。','沙纳尔废墟的纳拉杜要你在附近的小屋中找到沙纳尔钥匙。','感谢你，$N。我的人民很快就会获得自由，感谢你。','你拿到钥匙了吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='叛徒',Details_loc4='在每个被奴役的破碎者部族中，必定有一位叛徒作祟。这个卑鄙的家伙为了得到力量不惜出卖自己的同胞。$B$B沙纳尔废墟中心的阶梯顶部有一间小屋。那便是背叛者的居所。$B$B他现在恰好不在，如果你有耐心的话，可以悄悄地潜进去。小屋中有个箱子，里面的钥匙可以打开囚禁残冠长者的镣铐。把钥匙带回来给我。$B$B千万小心，无情的阿尔泽斯就在小屋附近徘徊。',Objectives_loc4='沙纳尔废墟的纳拉杜要你在附近的小屋中找到沙纳尔钥匙。',OfferRewardText_loc4='感谢你，$N。我的人民很快就会获得自由，感谢你。',RequestItemsText_loc4='你拿到钥匙了吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4,ObjectiveText2_loc4,ObjectiveText3_loc4) VALUES (10368,'残冠长者','残冠长者被囚禁后，氏族的灵魂便陷入了绝望。带上这把钥匙，去搭救残冠长者。$B$B救出抚风者莫洛德、召火者阿库鲁和唤水者埃伊兰。一旦他们重获自由，灵魂就会返回残冠氏族。','搭救被囚禁在沙纳尔废墟的抚风者莫洛德、召火者阿库鲁和唤水者埃伊兰。完成任务后向纳拉杜复命。','我能感觉到，$N!精灵们要回归我们身边。','告诉我，$N。那些崔互德长者是否已经被释放了?','释放抚风者莫洛德','释放召火者阿库鲁','释放唤水者埃伊兰') ON DUPLICATE KEY UPDATE Title_loc4='残冠长者',Details_loc4='残冠长者被囚禁后，氏族的灵魂便陷入了绝望。带上这把钥匙，去搭救残冠长者。$B$B救出抚风者莫洛德、召火者阿库鲁和唤水者埃伊兰。一旦他们重获自由，灵魂就会返回残冠氏族。',Objectives_loc4='搭救被囚禁在沙纳尔废墟的抚风者莫洛德、召火者阿库鲁和唤水者埃伊兰。完成任务后向纳拉杜复命。',OfferRewardText_loc4='我能感觉到，$N!精灵们要回归我们身边。',RequestItemsText_loc4='告诉我，$N。那些崔互德长者是否已经被释放了?',ObjectiveText1_loc4='释放抚风者莫洛德',ObjectiveText2_loc4='释放召火者阿库鲁',ObjectiveText3_loc4='释放唤水者埃伊兰';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10369,'阿尔泽斯之死','没错，元素的灵魂已经回到了我们身边！虽然我们不如从前那样强大，但是使用得当的话，一点点魔法都会发挥巨大的功效。$B$B阿尔泽斯的主子赐予了他可怕的力量。带上这根法杖，它曾是残冠氏族力量的象征。利用它对付阿尔泽斯，法杖能让阿尔泽斯的力量暂时消失。趁机杀死他，我们才能获得真正的自由！','对无情的阿尔泽斯使用残冠长者法杖，趁阿尔泽斯失去力量时杀死他。完成任务后向沙纳尔废墟的纳拉杜复命。','没错，$N。我曾经是大地守卫者纳拉杜。$B$B就是我背叛了其它的崔互德长者换取力量的空泛诺言。如果你想的话，你现在就能轻视我。重要的是我的部族再一次得到自由，而精灵们也已经回到我们身边。$B$B我无法再被部族的其它人接纳，但是我现在能安稳地死去了。愿大地之灵能够在我的兄弟中找到一位新的服侍者。','完成了吗，$N?阿尔塞斯死了吗?') ON DUPLICATE KEY UPDATE Title_loc4='阿尔泽斯之死',Details_loc4='没错，元素的灵魂已经回到了我们身边！虽然我们不如从前那样强大，但是使用得当的话，一点点魔法都会发挥巨大的功效。$B$B阿尔泽斯的主子赐予了他可怕的力量。带上这根法杖，它曾是残冠氏族力量的象征。利用它对付阿尔泽斯，法杖能让阿尔泽斯的力量暂时消失。趁机杀死他，我们才能获得真正的自由！',Objectives_loc4='对无情的阿尔泽斯使用残冠长者法杖，趁阿尔泽斯失去力量时杀死他。完成任务后向沙纳尔废墟的纳拉杜复命。',OfferRewardText_loc4='没错，$N。我曾经是大地守卫者纳拉杜。$B$B就是我背叛了其它的崔互德长者换取力量的空泛诺言。如果你想的话，你现在就能轻视我。重要的是我的部族再一次得到自由，而精灵们也已经回到我们身边。$B$B我无法再被部族的其它人接纳，但是我现在能安稳地死去了。愿大地之灵能够在我的兄弟中找到一位新的服侍者。',RequestItemsText_loc4='完成了吗，$N?阿尔塞斯死了吗?';
INSERT INTO locales_quest(entry,Title_loc4) VALUES (10370,'纳兹格雷尔的命令') ON DUPLICATE KEY UPDATE Title_loc4='纳兹格雷尔的命令';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10371,'犹鲁斯·麦酒','一个名叫犹鲁斯·麦酒的矮人战士向联盟所有强大的战士发出了挑战。他在赤脊山的湖畔镇旅店等候着你们，并承诺会给所有通过试炼的战士提供丰厚的报酬。你的旅途会很遥远，但是你可以通过它来证明自己的实力，$n。','与赤脊山湖畔镇的犹鲁斯·麦酒谈一谈。','哈!你听说了我的挑战，对吗?$B$B请坐下来听我说。来一杯酒，慢慢享受……因为这也许是你这辈子最后一次喝酒了。$B') ON DUPLICATE KEY UPDATE Title_loc4='犹鲁斯·麦酒',Details_loc4='一个名叫犹鲁斯·麦酒的矮人战士向联盟所有强大的战士发出了挑战。他在赤脊山的湖畔镇旅店等候着你们，并承诺会给所有通过试炼的战士提供丰厚的报酬。你的旅途会很遥远，但是你可以通过它来证明自己的实力，$n。',Objectives_loc4='与赤脊山湖畔镇的犹鲁斯·麦酒谈一谈。',OfferRewardText_loc4='哈!你听说了我的挑战，对吗?$B$B请坐下来听我说。来一杯酒，慢慢享受……因为这也许是你这辈子最后一次喝酒了。$B';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10372,'谨慎的询问','我在塔奎林的一位同事艾拉兰向我发来了请求，需要我派人过去协助她完成一件十分紧急的工作。$B$B我并不知道她在想什么，但出于纪律原因，我是不会问的。如果你能证明自己具备足够的能力来完成这项工作的话，我希望你能到幽魂之地的塔奎林与艾拉兰谈谈。$B$B她的性格可能不怎么温和，甚至有点粗暴，但她绝对是一个值得信赖的人。','与塔奎林的艾拉兰谈一谈。','我刚开始怀疑是否赛蓝尼斯有收到那封信呢。$B$B<依兰儿轻轻的点了点头。>$B$B好的。让我们开始工作吧。','你是赛蓝尼斯的朋友吗?') ON DUPLICATE KEY UPDATE Title_loc4='谨慎的询问',Details_loc4='我在塔奎林的一位同事艾拉兰向我发来了请求，需要我派人过去协助她完成一件十分紧急的工作。$B$B我并不知道她在想什么，但出于纪律原因，我是不会问的。如果你能证明自己具备足够的能力来完成这项工作的话，我希望你能到幽魂之地的塔奎林与艾拉兰谈谈。$B$B她的性格可能不怎么温和，甚至有点粗暴，但她绝对是一个值得信赖的人。',Objectives_loc4='与塔奎林的艾拉兰谈一谈。',OfferRewardText_loc4='我刚开始怀疑是否赛蓝尼斯有收到那封信呢。$B$B<依兰儿轻轻的点了点头。>$B$B好的。让我们开始工作吧。',RequestItemsText_loc4='你是赛蓝尼斯的朋友吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10373,'战斗的号角：瘟疫之地！','大家都听着！大家都听着！所有的英雄都应该聆听这号召的声音！$B$B暴风城已经发出了备战的号召！所有勇士都应该拿起武器，一同面对来自东部王国北部地区亡灵天灾的威胁！城中传言四起，东部王国的废墟中滋生出了新的威胁！它们已经在幽暗城东面的瘟疫之地大量集结，联盟的安全岌岌可危！$B$B联盟的英雄们——去向指挥官阿什拉姆·瓦罗菲斯特报到吧，他的大本营就在奥特兰克山脉北边的冰风岗！','找到指挥官阿什拉姆·瓦罗菲斯特。他的大本营位于奥特兰克山脉以北的冰风岗。','欢迎你来到瘟疫之地，英雄。这里是艾泽拉斯最危险的地区之一，更糟糕的是，在我们北边和东北边的广袤土地上，到处都潜伏着天灾军团的势力。面对联盟的召唤，你毅然赶来履行自己的职责，这让我感到非常高兴!$B$B如果你已经准备要上阵杀敌了，那么，在瘟疫之地有足够多的敌人，你想杀多少就杀多少。') ON DUPLICATE KEY UPDATE Title_loc4='战斗的号角：瘟疫之地！',Details_loc4='大家都听着！大家都听着！所有的英雄都应该聆听这号召的声音！$B$B暴风城已经发出了备战的号召！所有勇士都应该拿起武器，一同面对来自东部王国北部地区亡灵天灾的威胁！城中传言四起，东部王国的废墟中滋生出了新的威胁！它们已经在幽暗城东面的瘟疫之地大量集结，联盟的安全岌岌可危！$B$B联盟的英雄们——去向指挥官阿什拉姆·瓦罗菲斯特报到吧，他的大本营就在奥特兰克山脉北边的冰风岗！',Objectives_loc4='找到指挥官阿什拉姆·瓦罗菲斯特。他的大本营位于奥特兰克山脉以北的冰风岗。',OfferRewardText_loc4='欢迎你来到瘟疫之地，英雄。这里是艾泽拉斯最危险的地区之一，更糟糕的是，在我们北边和东北边的广袤土地上，到处都潜伏着天灾军团的势力。面对联盟的召唤，你毅然赶来履行自己的职责，这让我感到非常高兴!$B$B如果你已经准备要上阵杀敌了，那么，在瘟疫之地有足够多的敌人，你想杀多少就杀多少。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10374,'战斗的号角：瘟疫之地！','部落的英雄们，请聆听这召唤的声音——部落召唤你们迅速行动起来！$B$B战斗的号角已经吹响，所有勇士都应拿起武器，准备与天灾军团殊死作战！城中传言四起，东部王国的废墟中滋生出了新的威胁！它们已经在幽暗城东面的瘟疫之地大量集结，部落的安全岌岌可危！$B$B部落的英雄们——去向高级执行官德灵顿报到吧，他的大本营就在提瑞斯法林地东部的亡灵壁垒！','找到高级执行官德灵顿。他将自己的大本营建在提瑞斯法林地和幽暗城以东的亡灵壁垒。','欢迎你来到瘟疫之地，英雄。这里是艾泽拉斯最危险的地区之一，更糟糕的是，在我们北边的广袤土地上，到处都潜伏着天灾军团的势力。面对部落的召唤，你毅然赶来履行自己的职责，这让我感到非常高兴!$B$B如果你已经准备要上阵杀敌了，那么，在瘟疫之地有足够多的敌人，你想杀多少就杀多少。') ON DUPLICATE KEY UPDATE Title_loc4='战斗的号角：瘟疫之地！',Details_loc4='部落的英雄们，请聆听这召唤的声音——部落召唤你们迅速行动起来！$B$B战斗的号角已经吹响，所有勇士都应拿起武器，准备与天灾军团殊死作战！城中传言四起，东部王国的废墟中滋生出了新的威胁！它们已经在幽暗城东面的瘟疫之地大量集结，部落的安全岌岌可危！$B$B部落的英雄们——去向高级执行官德灵顿报到吧，他的大本营就在提瑞斯法林地东部的亡灵壁垒！',Objectives_loc4='找到高级执行官德灵顿。他将自己的大本营建在提瑞斯法林地和幽暗城以东的亡灵壁垒。',OfferRewardText_loc4='欢迎你来到瘟疫之地，英雄。这里是艾泽拉斯最危险的地区之一，更糟糕的是，在我们北边的广袤土地上，到处都潜伏着天灾军团的势力。面对部落的召唤，你毅然赶来履行自己的职责，这让我感到非常高兴!$B$B如果你已经准备要上阵杀敌了，那么，在瘟疫之地有足够多的敌人，你想杀多少就杀多少。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4) VALUES (10375,'黑曜石作战念珠','想要证明你对我们的忠诚，就勇敢地跟我们的敌人作战吧。$B$B残忍野蛮的食人魔是塔拉最大的威胁。如果你想证明自己的实力，就把他们脖子上的作战念珠带回来给我。我会将你取得的成就告诉氏族其它成员的。') ON DUPLICATE KEY UPDATE Title_loc4='黑曜石作战念珠',Details_loc4='想要证明你对我们的忠诚，就勇敢地跟我们的敌人作战吧。$B$B残忍野蛮的食人魔是塔拉最大的威胁。如果你想证明自己的实力，就把他们脖子上的作战念珠带回来给我。我会将你取得的成就告诉氏族其它成员的。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10376,'希望符记','在你的训练进展成为一位牧师时，你就会影响到其它人。德莱尼牧师是一个希望的象征，帮助并且鼓舞那些有需要的人。$B$B因为如此，纳鲁给予了我们一项特别的礼物，将圣光灌注在我们周遭的那些人身上。使用这能力去协助盟友的力量吧。','注意听好，$N。我接着要说的话你不可以漏掉。') ON DUPLICATE KEY UPDATE Title_loc4='希望符记',OfferRewardText_loc4='在你的训练进展成为一位牧师时，你就会影响到其它人。德莱尼牧师是一个希望的象征，帮助并且鼓舞那些有需要的人。$B$B因为如此，纳鲁给予了我们一项特别的礼物，将圣光灌注在我们周遭的那些人身上。使用这能力去协助盟友的力量吧。',RequestItemsText_loc4='注意听好，$N。我接着要说的话你不可以漏掉。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4) VALUES (10377,'无所畏惧','德莱尼牧师群是毫无畏惧的，就像那些在战斗中支持我们的人一样。该是你知道为什么的时候了。') ON DUPLICATE KEY UPDATE Title_loc4='无所畏惧',OfferRewardText_loc4='德莱尼牧师群是毫无畏惧的，就像那些在战斗中支持我们的人一样。该是你知道为什么的时候了。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4) VALUES (10378,'吞噬魔法','我们全体牧师已经学会控制滥用魔法的欲望了。该是你学会如何操纵的时候了。') ON DUPLICATE KEY UPDATE Title_loc4='吞噬魔法',OfferRewardText_loc4='我们全体牧师已经学会控制滥用魔法的欲望了。该是你学会如何操纵的时候了。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4) VALUES (10379,'虚弱之触','啊，年轻的$g牧师:女牧师;，我很高兴你回来这里。我会帮你上一堂令你永生难忘的课。你准备好了吗?') ON DUPLICATE KEY UPDATE Title_loc4='虚弱之触',OfferRewardText_loc4='啊，年轻的$g牧师:女牧师;，我很高兴你回来这里。我会帮你上一堂令你永生难忘的课。你准备好了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10380,'黑暗的契约','$N，两个最危险的敌人已经结为同盟，而我们竟然一无所知！$B$B如果是占星者故意隐瞒这个消息的话，我并不会为此感到惊讶。但是，我们必须面对现实。燃烧军团已经和凯尔萨斯的日怒军团站到了同一阵线上。$B$B凯尔萨斯能够利用风暴要塞的科技，肯定和燃烧军团的恶魔有关。根据欧雷里斯的指示，我命令你立即消灭他们。','图鲁曼的营地中的凯兰恩要你杀死6名甘尔葛迁跃修理师、3名命运之女和3名莫尔葛空间主宰。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。','那时就完成了。我们来这里，奉我们大师们的命令来猎杀它们。完全不留馀地。$B$B有时会让你心存怀疑。','你完成任务了吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='黑暗的契约',Details_loc4='$N，两个最危险的敌人已经结为同盟，而我们竟然一无所知！$B$B如果是占星者故意隐瞒这个消息的话，我并不会为此感到惊讶。但是，我们必须面对现实。燃烧军团已经和凯尔萨斯的日怒军团站到了同一阵线上。$B$B凯尔萨斯能够利用风暴要塞的科技，肯定和燃烧军团的恶魔有关。根据欧雷里斯的指示，我命令你立即消灭他们。',Objectives_loc4='图鲁曼的营地中的凯兰恩要你杀死6名甘尔葛迁跃修理师、3名命运之女和3名莫尔葛空间主宰。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。',OfferRewardText_loc4='那时就完成了。我们来这里，奉我们大师们的命令来猎杀它们。完全不留馀地。$B$B有时会让你心存怀疑。',RequestItemsText_loc4='你完成任务了吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10381,'退出奥尔多','我的使命已经结束。我一如既往地完成了欧雷里斯交代的所有指令。$B$B到此为止吧。凯尔萨斯和燃烧军团既已结为同盟，我想一场大屠杀——也就是所谓的远征即将拉开序幕。$B$B他们先是将我们圣地让给了敌人，现在还想让我们为保卫他们流血牺牲。请你回去转告欧雷里斯，从今以后让纳鲁亲自上阵作战吧。','返回52区，向大主教欧雷里斯报到。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。','你带来的坏消息令我满心悲痛。两个我们的死敌合力而一个最亲爱的沙塔斯之子却失去了他的方向。') ON DUPLICATE KEY UPDATE Title_loc4='退出奥尔多',Details_loc4='我的使命已经结束。我一如既往地完成了欧雷里斯交代的所有指令。$B$B到此为止吧。凯尔萨斯和燃烧军团既已结为同盟，我想一场大屠杀——也就是所谓的远征即将拉开序幕。$B$B他们先是将我们圣地让给了敌人，现在还想让我们为保卫他们流血牺牲。请你回去转告欧雷里斯，从今以后让纳鲁亲自上阵作战吧。',Objectives_loc4='返回52区，向大主教欧雷里斯报到。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。',OfferRewardText_loc4='你带来的坏消息令我满心悲痛。两个我们的死敌合力而一个最亲爱的沙塔斯之子却失去了他的方向。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10382,'奔赴前线','嗯，$N，我希望你已经准备好进行我们下一步的计划了。燃烧军团从来没有停歇过，我们也绝对不会停下来！你立即乘坐狮鹫飞到荣耀岗哨去——那是靠近军团前线的一小块驻地。$B$B与巴洛克元帅谈一谈，他会安排工作给你的。哦，告诉那个脸色煞白的可怜虫，我向他问好。','乘坐狮鹫飞往荣耀岗哨，抵达之后与巴洛克元帅谈一谈。','你好，$C。我很高兴那个粗暴的老矮人终于适时的派来救援了!','没有必要站在这盯着我美丽的脸!退下!$B$B<莱弗卡尔狂笑>') ON DUPLICATE KEY UPDATE Title_loc4='奔赴前线',Details_loc4='嗯，$N，我希望你已经准备好进行我们下一步的计划了。燃烧军团从来没有停歇过，我们也绝对不会停下来！你立即乘坐狮鹫飞到荣耀岗哨去——那是靠近军团前线的一小块驻地。$B$B与巴洛克元帅谈一谈，他会安排工作给你的。哦，告诉那个脸色煞白的可怜虫，我向他问好。',Objectives_loc4='乘坐狮鹫飞往荣耀岗哨，抵达之后与巴洛克元帅谈一谈。',OfferRewardText_loc4='你好，$C。我很高兴那个粗暴的老矮人终于适时的派来救援了!',RequestItemsText_loc4='没有必要站在这盯着我美丽的脸!退下!$B$B<莱弗卡尔狂笑>';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10383,'线索在这!','哈啰。你应该查明那些兔子。','与强纳森·乐卡夫特谈论关于兔子的事。','开始了……') ON DUPLICATE KEY UPDATE Title_loc4='线索在这!',Details_loc4='哈啰。你应该查明那些兔子。',Objectives_loc4='与强纳森·乐卡夫特谈论关于兔子的事。',OfferRewardText_loc4='开始了……';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10384,'复仇军的数据','仔细查看你四周，这台传送器附近应该有一份复仇军数据单元。找到这份数据单元，取出里面的内容。$B$B然后立刻将它带回传送器面前！','复仇军前沿基地中的复仇军发射器 - 塞塔所投射出来的指挥官阿米尔的影像要你带回复仇军数据单元。','<你将数据机体交出让阿密尔可以阅览这个计划。>$B$B没事……该死!他们是很聪明没错但是绝没有阿密尔那么聪明!$B$B我将要求你去做的事情非常危险。要是你不想继续的话我可以理解，凡人。','你拿到数据机体了吗?') ON DUPLICATE KEY UPDATE Title_loc4='复仇军的数据',Details_loc4='仔细查看你四周，这台传送器附近应该有一份复仇军数据单元。找到这份数据单元，取出里面的内容。$B$B然后立刻将它带回传送器面前！',Objectives_loc4='复仇军前沿基地中的复仇军发射器 - 塞塔所投射出来的指挥官阿米尔的影像要你带回复仇军数据单元。',OfferRewardText_loc4='<你将数据机体交出让阿密尔可以阅览这个计划。>$B$B没事……该死!他们是很聪明没错但是绝没有阿密尔那么聪明!$B$B我将要求你去做的事情非常危险。要是你不想继续的话我可以理解，凡人。',RequestItemsText_loc4='你拿到数据机体了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10385,'脑部损伤几率：高','复仇军利用一种名叫传达者的东西在各个前线基地之间传递消息。$B$B想要发现并解读传达者携带的信息，只有一个办法。不幸的是，这样做很可能使你受到无可挽回的脑部损伤。$B$B如果你仍然有兴趣的话，就前往前线基地杀死复仇军虚灵，取出他们的精华。饮下虚灵精华后，你就能暂时看见复仇军传达者，精华的有效时间足以让你摧毁传达者并解读它携带的信息。','复仇军前沿基地中的复仇军发射器 - 塞塔所投射出来的指挥官阿米尔的影像要你带回15份复仇军中继数据。','护国者之所以存在的原因现在完全了解了。$B$B复仇军不是到这里猎补迪曼修斯!他们想在这里操控虚无!$B$B他们在这个法力熔炉里操作虚无能量以结合他们自己的能量成为一种叫做奈萨斯潜猎者的生物。$B$B他们毫无疑问地使用一台原始加速器去完成转化过程。','你拿到传达资料了吗?') ON DUPLICATE KEY UPDATE Title_loc4='脑部损伤几率：高',Details_loc4='复仇军利用一种名叫传达者的东西在各个前线基地之间传递消息。$B$B想要发现并解读传达者携带的信息，只有一个办法。不幸的是，这样做很可能使你受到无可挽回的脑部损伤。$B$B如果你仍然有兴趣的话，就前往前线基地杀死复仇军虚灵，取出他们的精华。饮下虚灵精华后，你就能暂时看见复仇军传达者，精华的有效时间足以让你摧毁传达者并解读它携带的信息。',Objectives_loc4='复仇军前沿基地中的复仇军发射器 - 塞塔所投射出来的指挥官阿米尔的影像要你带回15份复仇军中继数据。',OfferRewardText_loc4='护国者之所以存在的原因现在完全了解了。$B$B复仇军不是到这里猎补迪曼修斯!他们想在这里操控虚无!$B$B他们在这个法力熔炉里操作虚无能量以结合他们自己的能量成为一种叫做奈萨斯潜猎者的生物。$B$B他们毫无疑问地使用一台原始加速器去完成转化过程。',RequestItemsText_loc4='你拿到传达资料了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10386,'魔能机甲的摧毁者','大督军霍恩·重拳一直在寻找愿意采用自杀式攻击方法对付燃烧军团的人。你一定有勇气去接受其中一个任务。$B$B当你准备好流血牺牲的时候去跟他谈一谈。他正在那边庆祝干掉了一台魔能机甲。他和他的护卫队几个小时前摧毁了那台魔能机甲，要不是他的凶猛和战斗技巧，我们可能都死在这里了。','与大督军霍恩·重拳谈一谈。','前线指挥官吐阿奇派你来找我是对的，$N。我可以让那些有勇气拿起武器对抗燃烧军团的人发挥用处。','你该去跟霸主残拳谈谈。他就在废弃的恶魔劫夺者那边。') ON DUPLICATE KEY UPDATE Title_loc4='魔能机甲的摧毁者',Details_loc4='大督军霍恩·重拳一直在寻找愿意采用自杀式攻击方法对付燃烧军团的人。你一定有勇气去接受其中一个任务。$B$B当你准备好流血牺牲的时候去跟他谈一谈。他正在那边庆祝干掉了一台魔能机甲。他和他的护卫队几个小时前摧毁了那台魔能机甲，要不是他的凶猛和战斗技巧，我们可能都死在这里了。',Objectives_loc4='与大督军霍恩·重拳谈一谈。',OfferRewardText_loc4='前线指挥官吐阿奇派你来找我是对的，$N。我可以让那些有勇气拿起武器对抗燃烧军团的人发挥用处。',RequestItemsText_loc4='你该去跟霸主残拳谈谈。他就在废弃的恶魔劫夺者那边。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10387,'魔能机甲的摧毁者','大督军霍恩·重拳一直在寻找愿意采用自杀式攻击方法对付燃烧军团的人。你一定有勇气去接受其中一个任务。$B$B当你准备好流血牺牲的时候去跟他谈一谈。他正在那边庆祝干掉了一台魔能机甲。他和他的护卫队几个小时前摧毁了那台魔能机甲，要不是他的凶猛和战斗技巧，我们可能都死在这里了。','与大督军霍恩·重拳谈一谈。','前线指挥官吐阿奇派你来找我是对的，$N。我可以让那些有勇气拿起武器对抗燃烧军团的人发挥用处。','你该去跟霸主残拳谈谈。他就在废弃的恶魔劫夺者那边。') ON DUPLICATE KEY UPDATE Title_loc4='魔能机甲的摧毁者',Details_loc4='大督军霍恩·重拳一直在寻找愿意采用自杀式攻击方法对付燃烧军团的人。你一定有勇气去接受其中一个任务。$B$B当你准备好流血牺牲的时候去跟他谈一谈。他正在那边庆祝干掉了一台魔能机甲。他和他的护卫队几个小时前摧毁了那台魔能机甲，要不是他的凶猛和战斗技巧，我们可能都死在这里了。',Objectives_loc4='与大督军霍恩·重拳谈一谈。',OfferRewardText_loc4='前线指挥官吐阿奇派你来找我是对的，$N。我可以让那些有勇气拿起武器对抗燃烧军团的人发挥用处。',RequestItemsText_loc4='你该去跟霸主残拳谈谈。他就在废弃的恶魔劫夺者那边。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10388,'返回萨尔玛','希望你的旅途愉快，朋友。你刚离开的时候来了一个信使——看来纳兹格雷尔有新的任务给你了。你最好回萨尔玛去看看，我预感燃烧军团又有了新的动向。','返回萨尔玛与纳兹格雷尔谈一谈。','喔，$N，你来的正是时候。我们的斥候已经发现，燃烧军团驻军在我们后方山坡上的其实是他们的''炼冶场''。那边就是燃烧军团的恶魔们用来制造他们的炼狱火恶魔劫夺者的地方。如果我们动作够快的话就可以瓦解他们的生产了!','嗯，你在这等什么?') ON DUPLICATE KEY UPDATE Title_loc4='返回萨尔玛',Details_loc4='希望你的旅途愉快，朋友。你刚离开的时候来了一个信使——看来纳兹格雷尔有新的任务给你了。你最好回萨尔玛去看看，我预感燃烧军团又有了新的动向。',Objectives_loc4='返回萨尔玛与纳兹格雷尔谈一谈。',OfferRewardText_loc4='喔，$N，你来的正是时候。我们的斥候已经发现，燃烧军团驻军在我们后方山坡上的其实是他们的''炼冶场''。那边就是燃烧军团的恶魔们用来制造他们的炼狱火恶魔劫夺者的地方。如果我们动作够快的话就可以瓦解他们的生产了!',RequestItemsText_loc4='嗯，你在这等什么?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10389,'痛苦与黑暗','你好，$N。我破译出了燃烧军团的信件，发现了这些恶魔进攻地狱火半岛的战略计划。似乎有一大群可怕的恐惧魔聚集在了西边的阿苟纳之池附近。我们绝对不能允许这样一支庞大的军队来攻击我们。你必须赶到那里去，杀掉那些该死的恶魔，削弱他们的力量。','魔导师文森特·血鹰要你在阿苟纳之池杀掉10个恐惧魔。','太棒了，$N。我就知道你会凯旋归来!军团离失败越来越接近了!','嗯，$C - 你打败恐惧恶魔了吗?') ON DUPLICATE KEY UPDATE Title_loc4='痛苦与黑暗',Details_loc4='你好，$N。我破译出了燃烧军团的信件，发现了这些恶魔进攻地狱火半岛的战略计划。似乎有一大群可怕的恐惧魔聚集在了西边的阿苟纳之池附近。我们绝对不能允许这样一支庞大的军队来攻击我们。你必须赶到那里去，杀掉那些该死的恶魔，削弱他们的力量。',Objectives_loc4='魔导师文森特·血鹰要你在阿苟纳之池杀掉10个恐惧魔。',OfferRewardText_loc4='太棒了，$N。我就知道你会凯旋归来!军团离失败越来越接近了!',RequestItemsText_loc4='嗯，$C - 你打败恐惧恶魔了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10390,'铸魔营地：暴虐','$N，我们有理由相信最东边的铸魔营地还没有完全建造好。燃烧军团的甘尔葛仆从正在日夜赶工让营地运作起来，我们必须阻止他们。$B$B去东边的铸魔营地：暴虐，杀掉10个甘尔葛仆从。把他们的主人剃刀电锯的徽记给我带回来——燃烧军团的魔能机甲铸造计划必须停止！','萨尔玛的纳兹格雷尔命令你攻击铸魔营地：暴虐，杀死10个甘尔葛仆从，然后将剃刀电锯的徽记带回去交给纳兹格雷尔。','做得好，$C，那是我们需要担心的炼冶场中较规模的一个。这会让军团花一些时间来取回这些设备备份及照料。你刚为我们买到了我们缺乏的东西','快点，$C，我们得在这些恶魔建造完成前让黑色祭坛停工!') ON DUPLICATE KEY UPDATE Title_loc4='铸魔营地：暴虐',Details_loc4='$N，我们有理由相信最东边的铸魔营地还没有完全建造好。燃烧军团的甘尔葛仆从正在日夜赶工让营地运作起来，我们必须阻止他们。$B$B去东边的铸魔营地：暴虐，杀掉10个甘尔葛仆从。把他们的主人剃刀电锯的徽记给我带回来——燃烧军团的魔能机甲铸造计划必须停止！',Objectives_loc4='萨尔玛的纳兹格雷尔命令你攻击铸魔营地：暴虐，杀死10个甘尔葛仆从，然后将剃刀电锯的徽记带回去交给纳兹格雷尔。',OfferRewardText_loc4='做得好，$C，那是我们需要担心的炼冶场中较规模的一个。这会让军团花一些时间来取回这些设备备份及照料。你刚为我们买到了我们缺乏的东西',RequestItemsText_loc4='快点，$C，我们得在这些恶魔建造完成前让黑色祭坛停工!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10391,'军团的火炮','第二个铸魔营地：狂乱位于萨尔玛的东北边。恶魔们将一些邪能火炮部署在了山脉地区——他们将攻击目标直接瞄准了我们！你必须进入到营地中毁掉这些邪能火炮。$B$B$N，你必须引爆所有的邪能火炮，否则燃烧军团仍会利用这些该死的东西来对付我们！','摧毁铸魔营地：狂乱中的3座邪能火炮I型，然后返回萨尔玛向纳兹格雷尔复命。','我知道你很勇敢，$N，但这次你超越了你自己!我们听到那些可怜的火炮从这里爆炸!那应该可以让军团们学到别低估了杜隆塔尔之子!','军团随时都有可能对我们发射，$N!你得去毁掉那些该死的火炮!') ON DUPLICATE KEY UPDATE Title_loc4='军团的火炮',Details_loc4='第二个铸魔营地：狂乱位于萨尔玛的东北边。恶魔们将一些邪能火炮部署在了山脉地区——他们将攻击目标直接瞄准了我们！你必须进入到营地中毁掉这些邪能火炮。$B$B$N，你必须引爆所有的邪能火炮，否则燃烧军团仍会利用这些该死的东西来对付我们！',Objectives_loc4='摧毁铸魔营地：狂乱中的3座邪能火炮I型，然后返回萨尔玛向纳兹格雷尔复命。',OfferRewardText_loc4='我知道你很勇敢，$N，但这次你超越了你自己!我们听到那些可怜的火炮从这里爆炸!那应该可以让军团们学到别低估了杜隆塔尔之子!',RequestItemsText_loc4='军团随时都有可能对我们发射，$N!你得去毁掉那些该死的火炮!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText2_loc4) VALUES (10392,'深渊之门','我们为你感到荣耀，$N。不过现在我们必须在燃烧军团恢复实力之前再给他们一次重击！萨尔玛的北边就是登陆场：歼灭，里面有一座传送门负责传送燃烧军团的增援军。$B$B你必须设法使它过载，把它炸成灰烬。开启传送门的钥匙在登陆场指挥官阿利萨玛尔身上。杀掉他，找到钥匙，用钥匙打开传送门后炸毁它。愿酋长祝福你。','杀掉阿利萨玛尔，找到燃烧军团传送门钥匙，利用它毁掉怨恨符文，然后返回萨尔玛向纳兹格雷尔复命。','赞美先祖，你做到了，$N!军团遭到了重大的攻击 -','快点，$N。传送门每开一秒，就多一个邪恶的恶魔被带到这个世界里!','关闭燃烧军团传送门') ON DUPLICATE KEY UPDATE Title_loc4='深渊之门',Details_loc4='我们为你感到荣耀，$N。不过现在我们必须在燃烧军团恢复实力之前再给他们一次重击！萨尔玛的北边就是登陆场：歼灭，里面有一座传送门负责传送燃烧军团的增援军。$B$B你必须设法使它过载，把它炸成灰烬。开启传送门的钥匙在登陆场指挥官阿利萨玛尔身上。杀掉他，找到钥匙，用钥匙打开传送门后炸毁它。愿酋长祝福你。',Objectives_loc4='杀掉阿利萨玛尔，找到燃烧军团传送门钥匙，利用它毁掉怨恨符文，然后返回萨尔玛向纳兹格雷尔复命。',OfferRewardText_loc4='赞美先祖，你做到了，$N!军团遭到了重大的攻击 -',RequestItemsText_loc4='快点，$N。传送门每开一秒，就多一个邪恶的恶魔被带到这个世界里!',ObjectiveText2_loc4='关闭燃烧军团传送门';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10393,'邪恶的计划','信上的字是使用某种黑暗而潦草的笔迹书写的，难以辨认。你盯着看的时间越久，那些符号在你的眼前就变得越发扭曲，似乎要熊熊燃烧起来。在萨尔玛只有一个人能辨认出这样邪恶的笔迹——血精灵魔导师文森特·血鹰。','将燃烧军团信件交给交给萨尔玛的魔导师文森特·血鹰。','你把这份文件带给我是对的。这可能是一份要求制造更多恶魔劫夺者的命令-或者新的攻击计划!我需要一些时间才能解读这份命令。去吧。当我有更进一步的了解我会叫你来的。$B$B<在你转身离开的时候博学者血鹰对你点了点头。>$B$B你是一个行家，$N。我应该会很期待听到你的新事迹。','我没有太多时间可以浪费，$C。这就是让你要烦我的东西吗?') ON DUPLICATE KEY UPDATE Title_loc4='邪恶的计划',Details_loc4='信上的字是使用某种黑暗而潦草的笔迹书写的，难以辨认。你盯着看的时间越久，那些符号在你的眼前就变得越发扭曲，似乎要熊熊燃烧起来。在萨尔玛只有一个人能辨认出这样邪恶的笔迹——血精灵魔导师文森特·血鹰。',Objectives_loc4='将燃烧军团信件交给交给萨尔玛的魔导师文森特·血鹰。',OfferRewardText_loc4='你把这份文件带给我是对的。这可能是一份要求制造更多恶魔劫夺者的命令-或者新的攻击计划!我需要一些时间才能解读这份命令。去吧。当我有更进一步的了解我会叫你来的。$B$B<在你转身离开的时候博学者血鹰对你点了点头。>$B$B你是一个行家，$N。我应该会很期待听到你的新事迹。',RequestItemsText_loc4='我没有太多时间可以浪费，$C。这就是让你要烦我的东西吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10394,'铸魔营地：暴虐','听仔细了，$N。我们正在调查前方山脉中的燃烧军团营地。我们有理由相信这些所谓的“铸魔营地”是他们铸造那些该死的魔能机甲的地方。$B$B你可以看到最近的一处目标，也就是西边的铸魔营地：暴虐。情报表明这座营地仍在建造中。如果你能杀掉甘尔葛仆从和他们的主人剃刀电锯，我们就可以阻止燃烧军团铸造魔能机甲的计划！','杀掉铸魔营地：暴虐的剃刀电锯和10个甘尔葛仆从，然后返回荣耀岗哨向巴洛克元帅复命。','好吧，我必须说，我很感动，$N。我之前根本不认为你有勇气完成这个任务。做得好。真的做得很好。','不要告诉我你害怕了，$C。要是他们完成了炼治场的兴建，你就有比那些恶魔劫夺者更多需要担心的事!去吧!') ON DUPLICATE KEY UPDATE Title_loc4='铸魔营地：暴虐',Details_loc4='听仔细了，$N。我们正在调查前方山脉中的燃烧军团营地。我们有理由相信这些所谓的“铸魔营地”是他们铸造那些该死的魔能机甲的地方。$B$B你可以看到最近的一处目标，也就是西边的铸魔营地：暴虐。情报表明这座营地仍在建造中。如果你能杀掉甘尔葛仆从和他们的主人剃刀电锯，我们就可以阻止燃烧军团铸造魔能机甲的计划！',Objectives_loc4='杀掉铸魔营地：暴虐的剃刀电锯和10个甘尔葛仆从，然后返回荣耀岗哨向巴洛克元帅复命。',OfferRewardText_loc4='好吧，我必须说，我很感动，$N。我之前根本不认为你有勇气完成这个任务。做得好。真的做得很好。',RequestItemsText_loc4='不要告诉我你害怕了，$C。要是他们完成了炼治场的兴建，你就有比那些恶魔劫夺者更多需要担心的事!去吧!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10395,'邪恶的信件','信上的字是使用某种黑暗而潦草的笔迹书写的，难以辨认。你盯着看的时间越久，那些符号在你的眼前就变得越发扭曲，似乎要熊熊燃烧起来。荣耀堡只有一个人能辨认出这种古老的笔迹，那就是德莱尼秘法师克雷夫。$B$B将燃烧军团信件交给荣耀堡的位面占卜者克雷夫。','将燃烧军团信件交给荣耀堡的位面占卜者克雷夫。','你很幸运的拦截到了这封书信，$N。虽然这得花费我一点时间来解译，但我已经能够感受到从这份卷轴里发出的恨意及急迫。我担心军团对这个大陆的真正目的将会很快显露出来……$B$B给我一点时间辨认这个字迹。$B$B<星移占卜师克里开始阅读这份恶魔书信。>','这是什么，$C?我感觉你找到的东西说明了一场即将到来的灾难。') ON DUPLICATE KEY UPDATE Title_loc4='邪恶的信件',Details_loc4='信上的字是使用某种黑暗而潦草的笔迹书写的，难以辨认。你盯着看的时间越久，那些符号在你的眼前就变得越发扭曲，似乎要熊熊燃烧起来。荣耀堡只有一个人能辨认出这种古老的笔迹，那就是德莱尼秘法师克雷夫。$B$B将燃烧军团信件交给荣耀堡的位面占卜者克雷夫。',Objectives_loc4='将燃烧军团信件交给荣耀堡的位面占卜者克雷夫。',OfferRewardText_loc4='你很幸运的拦截到了这封书信，$N。虽然这得花费我一点时间来解译，但我已经能够感受到从这份卷轴里发出的恨意及急迫。我担心军团对这个大陆的真正目的将会很快显露出来……$B$B给我一点时间辨认这个字迹。$B$B<星移占卜师克里开始阅读这份恶魔书信。>',RequestItemsText_loc4='这是什么，$C?我感觉你找到的东西说明了一场即将到来的灾难。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10396,'我的敌人的敌人……','我们的第二个目标是铸魔营地：狂乱，它就在铸魔营地：暴虐的西边。但现在的问题是，恶魔们将许多邪能火炮直接瞄准了部落的前哨基地萨尔玛！尽管这听起来有些奇怪，但我们确实需要部落帮忙守住黑暗之门的战线。因此绝对不能让萨尔玛失守，你必须在燃烧军团击败我们的同伴之前毁掉这些火炮！','摧毁铸魔营地：狂乱中的3座邪能火炮I型，然后返回荣耀岗哨向巴洛克元帅复命。','我一定要为你鼓掌，$N，你是个天生的斗士!那些部落老粗可能永远都不知道他们曾经离死亡有多接近。使用真正的身份来代表你的敌人出面干预。就是这种信誉及奉献将联盟团结起来!$B$B<战场元帅布洛克俐落的向你致敬。>','军团随时都有可能开始炮轰部落，$N!你得摧毁那些该死的火炮!') ON DUPLICATE KEY UPDATE Title_loc4='我的敌人的敌人……',Details_loc4='我们的第二个目标是铸魔营地：狂乱，它就在铸魔营地：暴虐的西边。但现在的问题是，恶魔们将许多邪能火炮直接瞄准了部落的前哨基地萨尔玛！尽管这听起来有些奇怪，但我们确实需要部落帮忙守住黑暗之门的战线。因此绝对不能让萨尔玛失守，你必须在燃烧军团击败我们的同伴之前毁掉这些火炮！',Objectives_loc4='摧毁铸魔营地：狂乱中的3座邪能火炮I型，然后返回荣耀岗哨向巴洛克元帅复命。',OfferRewardText_loc4='我一定要为你鼓掌，$N，你是个天生的斗士!那些部落老粗可能永远都不知道他们曾经离死亡有多接近。使用真正的身份来代表你的敌人出面干预。就是这种信誉及奉献将联盟团结起来!$B$B<战场元帅布洛克俐落的向你致敬。>',RequestItemsText_loc4='军团随时都有可能开始炮轰部落，$N!你得摧毁那些该死的火炮!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText2_loc4) VALUES (10397,'登陆场：歼灭','嗯，我们锁定了燃烧军团的最后一座营地——登陆场：歼灭。它位于铸魔营地：狂乱的西北边，在里面有一座传送燃烧军团援军的传送门！$B$B你必须将那座传送门毁掉，阻止燃烧军团利用它输送更多的恶魔。传送门的钥匙在那里的头目阿利萨玛尔身上。将钥匙夺过来，炸毁那道门！','杀掉阿利萨玛尔，找到燃烧军团传送门钥匙，利用它毁掉怨恨符文。','做得好!这应该会大大削弱那些试着想要悄悄偷袭我们的恶魔数量。感谢不足以表达我对你提供帮助的谢意，$N。','你关闭传送门了没，$N?当你在这拖拖拉拉的同时，就有更多的恶魔进入了外域!','关闭燃烧军团传送门') ON DUPLICATE KEY UPDATE Title_loc4='登陆场：歼灭',Details_loc4='嗯，我们锁定了燃烧军团的最后一座营地——登陆场：歼灭。它位于铸魔营地：狂乱的西北边，在里面有一座传送燃烧军团援军的传送门！$B$B你必须将那座传送门毁掉，阻止燃烧军团利用它输送更多的恶魔。传送门的钥匙在那里的头目阿利萨玛尔身上。将钥匙夺过来，炸毁那道门！',Objectives_loc4='杀掉阿利萨玛尔，找到燃烧军团传送门钥匙，利用它毁掉怨恨符文。',OfferRewardText_loc4='做得好!这应该会大大削弱那些试着想要悄悄偷袭我们的恶魔数量。感谢不足以表达我对你提供帮助的谢意，$N。',RequestItemsText_loc4='你关闭传送门了没，$N?当你在这拖拖拉拉的同时，就有更多的恶魔进入了外域!',ObjectiveText2_loc4='关闭燃烧军团传送门';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10398,'返回荣耀堡','PH:出发到荣耀堡。','PH: 出发到荣耀堡。','PH:你回来了真好。我们必须杀死阿葛纳尔之池的首领。','PH:你应该到荣耀堡去。') ON DUPLICATE KEY UPDATE Title_loc4='返回荣耀堡',Details_loc4='PH:出发到荣耀堡。',Objectives_loc4='PH: 出发到荣耀堡。',OfferRewardText_loc4='PH:你回来了真好。我们必须杀死阿葛纳尔之池的首领。',RequestItemsText_loc4='PH:你应该到荣耀堡去。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10399,'黑暗之心','正如我担心的那样。你之前杀死的那个恶魔阿利萨玛尔听命于一个神秘的燃烧军团领主，残酷的阿拉修斯。这个恶棍似乎在阿苟纳之池附近聚集了一支可恶的恐惧魔部队。$B$B你必须赶在他们袭击我们之前去那里杀掉恐惧魔。不过你一定要小心，朋友——阿苟纳之池在一个充满剧毒的山谷中，你可以在西北边找到这个邪恶的地方，就在地狱火堡垒的那一边。$B$B圣光与你同在， $N。','在阿苟纳之池杀掉10个恐惧魔，然后向荣耀堡的位面占卜者克雷夫复命。','我预见了这场伟大的胜利，$N。今日，神圣的纳鲁偏爱你。','我感觉到你心中一股日渐增长的黑暗，$C。你正视过你的恐惧吗?或是它还在阿葛纳尔之池那等待着你呢?') ON DUPLICATE KEY UPDATE Title_loc4='黑暗之心',Details_loc4='正如我担心的那样。你之前杀死的那个恶魔阿利萨玛尔听命于一个神秘的燃烧军团领主，残酷的阿拉修斯。这个恶棍似乎在阿苟纳之池附近聚集了一支可恶的恐惧魔部队。$B$B你必须赶在他们袭击我们之前去那里杀掉恐惧魔。不过你一定要小心，朋友——阿苟纳之池在一个充满剧毒的山谷中，你可以在西北边找到这个邪恶的地方，就在地狱火堡垒的那一边。$B$B圣光与你同在， $N。',Objectives_loc4='在阿苟纳之池杀掉10个恐惧魔，然后向荣耀堡的位面占卜者克雷夫复命。',OfferRewardText_loc4='我预见了这场伟大的胜利，$N。今日，神圣的纳鲁偏爱你。',RequestItemsText_loc4='我感觉到你心中一股日渐增长的黑暗，$C。你正视过你的恐惧吗?或是它还在阿葛纳尔之池那等待着你呢?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10400,'霸王','$N，尊敬的位面占卜者说你冒着生命危险发现了新的敌人。如果克雷夫说得没错，那这个“残酷的阿拉修斯”就无疑是个非常强大而又邪恶的敌人了。$B$B你愿意帮助我们吗，$N？你愿意去对付这个燃烧军团的头目，让他受到圣光的制裁吗？如果你愿意的话，就去阿苟纳之池找到他吧。如果你不去杀掉他，他的邪恶力量也终究会找到你。','前往阿苟纳之池，除掉残酷的阿拉修斯，然后返回荣耀堡向远征军指挥官达纳斯·托尔贝恩复命。','赞美圣光，我就知道你可以的!阿拉萨尔斯和他的爪牙消失了!很快地，军团就会滚回家，我们将再度的安全了。接着，当正义被彰显，我们也就可以回家。$B$B谢谢你，$N - 联盟及洛萨之子今日以你为荣!','告诉我，$N，任务完成了吗?军团领主被制伏了吗?') ON DUPLICATE KEY UPDATE Title_loc4='霸王',Details_loc4='$N，尊敬的位面占卜者说你冒着生命危险发现了新的敌人。如果克雷夫说得没错，那这个“残酷的阿拉修斯”就无疑是个非常强大而又邪恶的敌人了。$B$B你愿意帮助我们吗，$N？你愿意去对付这个燃烧军团的头目，让他受到圣光的制裁吗？如果你愿意的话，就去阿苟纳之池找到他吧。如果你不去杀掉他，他的邪恶力量也终究会找到你。',Objectives_loc4='前往阿苟纳之池，除掉残酷的阿拉修斯，然后返回荣耀堡向远征军指挥官达纳斯·托尔贝恩复命。',OfferRewardText_loc4='赞美圣光，我就知道你可以的!阿拉萨尔斯和他的爪牙消失了!很快地，军团就会滚回家，我们将再度的安全了。接着，当正义被彰显，我们也就可以回家。$B$B谢谢你，$N - 联盟及洛萨之子今日以你为荣!',RequestItemsText_loc4='告诉我，$N，任务完成了吗?军团领主被制伏了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10401,'任务:终结所有，战胜所有','假如你没有截获这些信件，你知道会发生什么事情吗，$N？<纳兹格雷尔点了点头。>$B$B是的，全地狱火半岛的燃烧军团部队都会来敲我们萨尔玛的大门。若是真有那样一场突袭，没有人可以活下来。$B$B要想不让这些命令抵达军团前线，那只有一个办法。你必须立刻前往西北方的阿苟纳之池，并杀死这只阿拉萨尔斯。$B$B去吧，若是能够成功，我会推荐酋长大力嘉奖你的。','地狱火半岛上萨尔玛的纳兹格雷尔要求你杀掉残忍的阿拉萨尔斯。','做得好，士兵。的确，做得很好。这最少为我们挣得另一个月的时间，或许可给我们足够的时间去弄清楚地狱火堡垒里发生的事。$B$B现在有关奖赏的部份……','这任务可不简单啊，$N。') ON DUPLICATE KEY UPDATE Title_loc4='任务:终结所有，战胜所有',Details_loc4='假如你没有截获这些信件，你知道会发生什么事情吗，$N？<纳兹格雷尔点了点头。>$B$B是的，全地狱火半岛的燃烧军团部队都会来敲我们萨尔玛的大门。若是真有那样一场突袭，没有人可以活下来。$B$B要想不让这些命令抵达军团前线，那只有一个办法。你必须立刻前往西北方的阿苟纳之池，并杀死这只阿拉萨尔斯。$B$B去吧，若是能够成功，我会推荐酋长大力嘉奖你的。',Objectives_loc4='地狱火半岛上萨尔玛的纳兹格雷尔要求你杀掉残忍的阿拉萨尔斯。',OfferRewardText_loc4='做得好，士兵。的确，做得很好。这最少为我们挣得另一个月的时间，或许可给我们足够的时间去弄清楚地狱火堡垒里发生的事。$B$B现在有关奖赏的部份……',RequestItemsText_loc4='这任务可不简单啊，$N。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10403,'纳拉杜','或许残冠氏族还存有一线希望。被伊利达雷恶魔奴役之前，我是氏族的四名长者之一。我原本以为另外三位长者都已亡故，但后来才知道至少还有两人活着——他们跟我一样被囚禁起来，无力逃脱。$B$B至今我都没能找到纳拉杜的下落，我担心他可能遭遇不测。废墟顶部还有许多小屋，或许你可以去找找他。如果所有的残冠长者都活着，对我们的氏族而言将会是个天大的好消息。','前往沙纳尔废墟，寻找纳拉杜的下落。','你是来帮助我的部族的吗，$r?真不寻常。没有多少人会关心这块土地上的破碎者命运。') ON DUPLICATE KEY UPDATE Title_loc4='纳拉杜',Details_loc4='或许残冠氏族还存有一线希望。被伊利达雷恶魔奴役之前，我是氏族的四名长者之一。我原本以为另外三位长者都已亡故，但后来才知道至少还有两人活着——他们跟我一样被囚禁起来，无力逃脱。$B$B至今我都没能找到纳拉杜的下落，我担心他可能遭遇不测。废墟顶部还有许多小屋，或许你可以去找找他。如果所有的残冠长者都活着，对我们的氏族而言将会是个天大的好消息。',Objectives_loc4='前往沙纳尔废墟，寻找纳拉杜的下落。',OfferRewardText_loc4='你是来帮助我的部族的吗，$r?真不寻常。没有多少人会关心这块土地上的破碎者命运。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10404,'对抗军团','我们目前已经获悉，燃烧军团向凯尔萨斯提供了大量的技术援助，这已经使凯尔萨斯的威胁等级提高了数倍。$B$B然而，由于燃烧军团在这一地区部署的军队实在太多了，我们所能对敌人造成的最大打击，恐怕也只有直接正面进攻地域内正北方的两处铸魔营地了。立刻前往铸魔基地：炼狱和铸魔基地：湮灭，消灭那里所有的敌人。愿圣光指引着剑的方向，$N。','在52区的主教欧瑞利斯要你去熔炉基地:遗忘和熔炉基地:苦难，并杀掉12个甘纳格锻造黑手，6个莫阿格锻造王和6个愤怒使者。$B$B为奥多尔完成任务会使你的占星者声望降低。','你已经给予圣光的敌人迎头痛击，$N。我与奥多尔都感谢你。','你成功的抵抗军团了吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='对抗军团',Details_loc4='我们目前已经获悉，燃烧军团向凯尔萨斯提供了大量的技术援助，这已经使凯尔萨斯的威胁等级提高了数倍。$B$B然而，由于燃烧军团在这一地区部署的军队实在太多了，我们所能对敌人造成的最大打击，恐怕也只有直接正面进攻地域内正北方的两处铸魔营地了。立刻前往铸魔基地：炼狱和铸魔基地：湮灭，消灭那里所有的敌人。愿圣光指引着剑的方向，$N。',Objectives_loc4='在52区的主教欧瑞利斯要你去熔炉基地:遗忘和熔炉基地:苦难，并杀掉12个甘纳格锻造黑手，6个莫阿格锻造王和6个愤怒使者。$B$B为奥多尔完成任务会使你的占星者声望降低。',OfferRewardText_loc4='你已经给予圣光的敌人迎头痛击，$N。我与奥多尔都感谢你。',RequestItemsText_loc4='你成功的抵抗军团了吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10405,'破坏行动','我们必须摧毁将复仇军的虚灵变异为节点猎手的特殊机器。但是这种机器是虚灵科技的产物，直接破坏原质加速器根本不起作用。我们得破坏那些传输魔法能量的管道。$B$B眼下还缺一份材料，没有它，我无法制造能使管道能量超负荷的设备。为了校准这台设备，我要你从尚未变异的虚灵执政官或主宰身上拿来他的裹布。','复仇军前沿基地中的复仇军发射器 - 塞塔所投射出来的指挥官阿米尔的影像要你带回1条精制复仇军裹布。','太好了!现在校准装置。','你拿到裹带了吗?') ON DUPLICATE KEY UPDATE Title_loc4='破坏行动',Details_loc4='我们必须摧毁将复仇军的虚灵变异为节点猎手的特殊机器。但是这种机器是虚灵科技的产物，直接破坏原质加速器根本不起作用。我们得破坏那些传输魔法能量的管道。$B$B眼下还缺一份材料，没有它，我无法制造能使管道能量超负荷的设备。为了校准这台设备，我要你从尚未变异的虚灵执政官或主宰身上拿来他的裹布。',Objectives_loc4='复仇军前沿基地中的复仇军发射器 - 塞塔所投射出来的指挥官阿米尔的影像要你带回1条精制复仇军裹布。',OfferRewardText_loc4='太好了!现在校准装置。',RequestItemsText_loc4='你拿到裹带了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,EndText_loc4) VALUES (10406,'传达信息','我打算派一名爆破师去放置扰流器。希望你能在他安装扰流器时保护他。$B$B一定要确保他的安全！他
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10407,'索克雷萨之影','索克雷萨，这个声名狼藉的艾瑞达人统领着整个虚空风暴的燃烧军团部队。单是提起他的名字，就足以令大多数德莱尼人吓得发抖。索克雷萨驻扎在西北方的某座浮岛上，只有他最信任的军官才有资格与他会面。$B$B你必须夺得传送石才能进入那座浮岛，这可不是件容易的事。传送石的上半部在铸魔基地：湮灭的熔炉主管莫鲁格手中，而下半部则由铸魔基地：炼狱的希尔洛斯保管。','52区的学者卡尔亚要你从铸魔基地：湮灭的熔炉主管莫鲁格手中夺得索克雷萨之石的上半部，并从铸魔基地：炼狱的希尔洛斯手中夺得索克雷萨之石的下半部。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。','你对我们理想的奉献足以作为模范，$N。现在我们已经拥有了索奎萨尔的传送石，只剩下一件事情需要去做。','你拿到索奎萨尔的传送石了吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='索克雷萨之影',Details_loc4='索克雷萨，这个声名狼藉的艾瑞达人统领着整个虚空风暴的燃烧军团部队。单是提起他的名字，就足以令大多数德莱尼人吓得发抖。索克雷萨驻扎在西北方的某座浮岛上，只有他最信任的军官才有资格与他会面。$B$B你必须夺得传送石才能进入那座浮岛，这可不是件容易的事。传送石的上半部在铸魔基地：湮灭的熔炉主管莫鲁格手中，而下半部则由铸魔基地：炼狱的希尔洛斯保管。',Objectives_loc4='52区的学者卡尔亚要你从铸魔基地：湮灭的熔炉主管莫鲁格手中夺得索克雷萨之石的上半部，并从铸魔基地：炼狱的希尔洛斯手中夺得索克雷萨之石的下半部。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。',OfferRewardText_loc4='你对我们理想的奉献足以作为模范，$N。现在我们已经拥有了索奎萨尔的传送石，只剩下一件事情需要去做。',RequestItemsText_loc4='你拿到索奎萨尔的传送石了吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10408,'节点之王萨哈达尔','我这里还有一个扰流器，它能摧毁环绕着萨哈达尔的三根管道。一旦管道尽数被毁，萨哈达尔身上的保护力场就会消失。$N，那样的话，他会爆发出你前所未见的狂暴力量，你将与他展开激烈的战斗。$B$B如果你决意要铲除萨哈达尔，我就将这个扰流器交给你。','复仇军前沿基地的复仇军发射器 - 塞塔中投射出来的指挥官阿米尔的影像要你使用维序派扰流器关闭萨哈达尔防御力场，然后杀死节点之王萨哈达尔。','已经一千年了，或许更久，自从萨哈达尔开始他的圣战以消灭所有挡住他的事物。我几乎不能相信这是它的最后……你已经为我们所有人做了件伟大的事，$N，而为此你将被奖赏。','他……他真的死了吗?被杀了?') ON DUPLICATE KEY UPDATE Title_loc4='节点之王萨哈达尔',Details_loc4='我这里还有一个扰流器，它能摧毁环绕着萨哈达尔的三根管道。一旦管道尽数被毁，萨哈达尔身上的保护力场就会消失。$N，那样的话，他会爆发出你前所未见的狂暴力量，你将与他展开激烈的战斗。$B$B如果你决意要铲除萨哈达尔，我就将这个扰流器交给你。',Objectives_loc4='复仇军前沿基地的复仇军发射器 - 塞塔中投射出来的指挥官阿米尔的影像要你使用维序派扰流器关闭萨哈达尔防御力场，然后杀死节点之王萨哈达尔。',OfferRewardText_loc4='已经一千年了，或许更久，自从萨哈达尔开始他的圣战以消灭所有挡住他的事物。我几乎不能相信这是它的最后……你已经为我们所有人做了件伟大的事，$N，而为此你将被奖赏。',RequestItemsText_loc4='他……他真的死了吗?被杀了?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,EndText_loc4) VALUES (10409,'重创燃烧军团','在面对拥有强大力量的艾瑞达人时，以数量制胜恐怕是无稽之谈。他们的腐蚀力足以令凡人迅速堕落，只有意志最坚定的勇士才敢于面对这种挑战。$B$B召集你最亲密和最优秀的战友，带上这块传送石，前往位于铸魔基地：湮灭和铸魔基地：炼狱之间的登陆场：霸王。欧雷里斯和卡尔亚会在索克雷萨之座等你，我还会派阿德因一同去帮助你。$B$B圣光必胜，$N！让索克雷萨消亡吧！','高阶祭司伊沙娜要你前往虚空风暴西北角的军团传送控制器，利用它传送到索克雷萨之座，然后击败索克雷萨。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。','完成了，$N。索奎萨尔已经被消灭。$B$B我和其它人将自我们的伤口恢复，$N。但是，索奎萨尔魔法的愤怒远非年轻的凯岚所能承受的。即使是我最强大的祷言也无法唤起他。$B$B那是不堪忍受的遗憾，一个如此年轻的人在战斗中阵亡。不过，最后他的强大意志能使它从军团的腐败中恢复，则是我们感到欣慰的地方。','愿圣光与你同在，$C。','重创燃烧军团') ON DUPLICATE KEY UPDATE Title_loc4='重创燃烧军团',Details_loc4='在面对拥有强大力量的艾瑞达人时，以数量制胜恐怕是无稽之谈。他们的腐蚀力足以令凡人迅速堕落，只有意志最坚定的勇士才敢于面对这种挑战。$B$B召集你最亲密和最优秀的战友，带上这块传送石，前往位于铸魔基地：湮灭和铸魔基地：炼狱之间的登陆场：霸王。欧雷里斯和卡尔亚会在索克雷萨之座等你，我还会派阿德因一同去帮助你。$B$B圣光必胜，$N！让索克雷萨消亡吧！',Objectives_loc4='高阶祭司伊沙娜要你前往虚空风暴西北角的军团传送控制器，利用它传送到索克雷萨之座，然后击败索克雷萨。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。',OfferRewardText_loc4='完成了，$N。索奎萨尔已经被消灭。$B$B我和其它人将自我们的伤口恢复，$N。但是，索奎萨尔魔法的愤怒远非年轻的凯岚所能承受的。即使是我最强大的祷言也无法唤起他。$B$B那是不堪忍受的遗憾，一个如此年轻的人在战斗中阵亡。不过，最后他的强大意志能使它从军团的腐败中恢复，则是我们感到欣慰的地方。',RequestItemsText_loc4='愿圣光与你同在，$C。',EndText_loc4='重创燃烧军团';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10410,'伊沙娜的帮助','是时候面对索克雷萨了，$N。对我们来说，挑战艾瑞达人的领袖并不是一件容易的事。如果准备得不够妥当，那么任何微小的错误都会让我们付出生命的代价。$B$B带上索克雷萨的传送石，前往沙塔斯城的永恒圣光神殿，去找高阶祭司伊沙娜。她会告诉我们要如何应对目前的情况。','返回沙塔斯城奥尔多高地的永恒圣光神殿，将索克雷萨的传送石交给高阶祭师伊沙娜。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。','索奎萨尔……我记得那个名字。他曾经是一位着名的圣光战士，而骄傲是他唯一的瑕疵。','什么困扰着你呢，孩子?') ON DUPLICATE KEY UPDATE Title_loc4='伊沙娜的帮助',Details_loc4='是时候面对索克雷萨了，$N。对我们来说，挑战艾瑞达人的领袖并不是一件容易的事。如果准备得不够妥当，那么任何微小的错误都会让我们付出生命的代价。$B$B带上索克雷萨的传送石，前往沙塔斯城的永恒圣光神殿，去找高阶祭司伊沙娜。她会告诉我们要如何应对目前的情况。',Objectives_loc4='返回沙塔斯城奥尔多高地的永恒圣光神殿，将索克雷萨的传送石交给高阶祭师伊沙娜。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。',OfferRewardText_loc4='索奎萨尔……我记得那个名字。他曾经是一位着名的圣光战士，而骄傲是他唯一的瑕疵。',RequestItemsText_loc4='什么困扰着你呢，孩子?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10411,'电磁冲击！','你在法力熔炉的废墟四周可以发现大量从迪门修斯体内渗透出的流质。滴水的淤泥怪已经占据了乌提斯外围的池塘，池塘正下方就是复仇军的前线基地，基地中到处都是一种名叫空灵废弃者的流质生命体。$B$B要对付这些软泥怪，最好的办法就是用电磁冲击枪将它们轰成小水珠。利用这瓶药剂强化你的电流攻击能力吧，如此一来，那些软泥怪就会衰变成原始的形态。消灭那些水珠！','虚空风暴维序派哨站的研究员纳乌德要你摧毁30只空灵废弃者水珠和30只滴水的淤泥怪水珠。','我希望不会太迟。你有发现附近或是在虚无荒废者被吸入的地区有任何异常的大型泥浆怪的出现?','淤泥怪和荒废者都带有极毒。如果不予理会的话，他们将形成凝结的虚无恐兽!') ON DUPLICATE KEY UPDATE Title_loc4='电磁冲击！',Details_loc4='你在法力熔炉的废墟四周可以发现大量从迪门修斯体内渗透出的流质。滴水的淤泥怪已经占据了乌提斯外围的池塘，池塘正下方就是复仇军的前线基地，基地中到处都是一种名叫空灵废弃者的流质生命体。$B$B要对付这些软泥怪，最好的办法就是用电磁冲击枪将它们轰成小水珠。利用这瓶药剂强化你的电流攻击能力吧，如此一来，那些软泥怪就会衰变成原始的形态。消灭那些水珠！',Objectives_loc4='虚空风暴维序派哨站的研究员纳乌德要你摧毁30只空灵废弃者水珠和30只滴水的淤泥怪水珠。',OfferRewardText_loc4='我希望不会太迟。你有发现附近或是在虚无荒废者被吸入的地区有任何异常的大型泥浆怪的出现?',RequestItemsText_loc4='淤泥怪和荒废者都带有极毒。如果不予理会的话，他们将形成凝结的虚无恐兽!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10412,'火翼徽记','凯尔萨斯·逐日者已将我们视为一个巨大的威胁，这早就不再是什么秘密了。让我们勇敢地面对他们吧，并不是所有银月城的辛多雷都愿意追随凯尔萨斯的。$B$B此外，我们与凯尔萨斯·逐日者之间的冲突也早已不只停留在文字与纸面上，这也不是秘密了。现在，占星者与凯尔萨斯的军队只要一见面就会交战。而你唯一向我们证明自身价值的方式，就是让我们分享你的力量，$N。$B$B凯尔的低阶追随者身上都带有用于标识其阶级的火翼徽记。将它们带回来给我。','沙塔斯城的魔导师菲亚琳要求你给她带回10个火翼徽记。$B$B为占星者完成任务将会使你在奥尔多阵营中的声望等级降低。','做得好，$N。你或许可以证明是一个有用的盟友。','继续，$N。请说。') ON DUPLICATE KEY UPDATE Title_loc4='火翼徽记',Details_loc4='凯尔萨斯·逐日者已将我们视为一个巨大的威胁，这早就不再是什么秘密了。让我们勇敢地面对他们吧，并不是所有银月城的辛多雷都愿意追随凯尔萨斯的。$B$B此外，我们与凯尔萨斯·逐日者之间的冲突也早已不只停留在文字与纸面上，这也不是秘密了。现在，占星者与凯尔萨斯的军队只要一见面就会交战。而你唯一向我们证明自身价值的方式，就是让我们分享你的力量，$N。$B$B凯尔的低阶追随者身上都带有用于标识其阶级的火翼徽记。将它们带回来给我。',Objectives_loc4='沙塔斯城的魔导师菲亚琳要求你给她带回10个火翼徽记。$B$B为占星者完成任务将会使你在奥尔多阵营中的声望等级降低。',OfferRewardText_loc4='做得好，$N。你或许可以证明是一个有用的盟友。',RequestItemsText_loc4='继续，$N。请说。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10413,'虚空的软泥','你小心地将虚空软泥留下的泥浆装入瓶中。$B$B维序派哨站的研究员纳乌德一定会对此感兴趣的！快把这瓶虚空软泥带给他吧！','将一瓶虚空软泥交给虚空风暴维序派哨站的研究员纳乌德。','什么!?你跟一个虚无恐兽交手?而且还活着?!难以置信!$B$B这个样品比等重的黄金还有价值，像这样的发现应该要好好奖励。','哇，你看起来有点脏……你是掉进什么地方里面?') ON DUPLICATE KEY UPDATE Title_loc4='虚空的软泥',Details_loc4='你小心地将虚空软泥留下的泥浆装入瓶中。$B$B维序派哨站的研究员纳乌德一定会对此感兴趣的！快把这瓶虚空软泥带给他吧！',Objectives_loc4='将一瓶虚空软泥交给虚空风暴维序派哨站的研究员纳乌德。',OfferRewardText_loc4='什么!?你跟一个虚无恐兽交手?而且还活着?!难以置信!$B$B这个样品比等重的黄金还有价值，像这样的发现应该要好好奖励。',RequestItemsText_loc4='哇，你看起来有点脏……你是掉进什么地方里面?';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10414,'单枚火翼徽记','太好了……凯尔萨斯的部队人数持续缩减而我们的数目持续上升。$B$B<这个任务可以重复进行直到声望阶级达到尊敬。>','即使是最小的贡献也会被注意到，$N。我们的敌人很多，但是我们将战胜他们!') ON DUPLICATE KEY UPDATE Title_loc4='单枚火翼徽记',OfferRewardText_loc4='太好了……凯尔萨斯的部队人数持续缩减而我们的数目持续上升。$B$B<这个任务可以重复进行直到声望阶级达到尊敬。>',RequestItemsText_loc4='即使是最小的贡献也会被注意到，$N。我们的敌人很多，但是我们将战胜他们!';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10415,'更多火翼徽记','太好了!反抗我们的人都将被消灭!$B$B<这个任务可以重复进行直到声望阶级达到尊敬。>','你最近为我们做了什么，$N?对凯尔萨斯的战争是不会自己开始的，你知道吗?') ON DUPLICATE KEY UPDATE Title_loc4='更多火翼徽记',OfferRewardText_loc4='太好了!反抗我们的人都将被消灭!$B$B<这个任务可以重复进行直到声望阶级达到尊敬。>',RequestItemsText_loc4='你最近为我们做了什么，$N?对凯尔萨斯的战争是不会自己开始的，你知道吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10416,'能量的聚合','奥法宝典并不是一般的描写或记载奥术魔法相关内容的书籍，它们蕴涵着某种自身固有的能量。而我可以将这种能量吸收并转化，合成为一枚奥术符文。$B$B如果你在冒险的旅途中找到奥法宝典的话，可以把它带来给我，我愿意帮你将其转化成这种符文。只有最强大的施法者身上才会带着我所说的奥法宝典。而在外域，最强的施法者一般就是指凯尔手下的血精灵，但这也并不是绝对的。','沙塔斯城内的先知沃雷塔尔要求你取得一本奥法宝典。为占星者完成任务将会使你在奥尔多阵营中的声望等级降低。','像许诺的那样，$N。秘典所有的自然力量，被浓缩成一个符文。','你拿到秘法宝典了没，$N?') ON DUPLICATE KEY UPDATE Title_loc4='能量的聚合',Details_loc4='奥法宝典并不是一般的描写或记载奥术魔法相关内容的书籍，它们蕴涵着某种自身固有的能量。而我可以将这种能量吸收并转化，合成为一枚奥术符文。$B$B如果你在冒险的旅途中找到奥法宝典的话，可以把它带来给我，我愿意帮你将其转化成这种符文。只有最强大的施法者身上才会带着我所说的奥法宝典。而在外域，最强的施法者一般就是指凯尔手下的血精灵，但这也并不是绝对的。',Objectives_loc4='沙塔斯城内的先知沃雷塔尔要求你取得一本奥法宝典。为占星者完成任务将会使你在奥尔多阵营中的声望等级降低。',OfferRewardText_loc4='像许诺的那样，$N。秘典所有的自然力量，被浓缩成一个符文。',RequestItemsText_loc4='你拿到秘法宝典了没，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10417,'诊断报告','无论星界财团在何处搭建新营地，我们都会利用生态圆顶科技。你要知道，我们时常需要在环境恶劣的地方做生意，而生态圆顶的力场能为我们提供可控的、适合生物生存的大气环境。$B$B然而，虚空风暴中的那些暴戾的生命体和多变的气候已经开始毁坏用于维持生态圆顶的装置了，特别是那些我们部署在东边的力场发生器。我已经启动了诊断程序，希望能分析出修复损害的办法。你能帮我取回诊断报告吗？','取回诊断报告，将它们交给中央圆顶哨站的玛尔达德。','<玛戴德点头，然后检验诊断结果。>$B$B这真是令人烦恼。损害比我想象的更加严重。我能送一些工具到风暴之尖去开始修理，但是那没用，除非我们能先将损坏设备的东西给隔离。','你取得诊断结果了吗?') ON DUPLICATE KEY UPDATE Title_loc4='诊断报告',Details_loc4='无论星界财团在何处搭建新营地，我们都会利用生态圆顶科技。你要知道，我们时常需要在环境恶劣的地方做生意，而生态圆顶的力场能为我们提供可控的、适合生物生存的大气环境。$B$B然而，虚空风暴中的那些暴戾的生命体和多变的气候已经开始毁坏用于维持生态圆顶的装置了，特别是那些我们部署在东边的力场发生器。我已经启动了诊断程序，希望能分析出修复损害的办法。你能帮我取回诊断报告吗？',Objectives_loc4='取回诊断报告，将它们交给中央圆顶哨站的玛尔达德。',OfferRewardText_loc4='<玛戴德点头，然后检验诊断结果。>$B$B这真是令人烦恼。损害比我想象的更加严重。我能送一些工具到风暴之尖去开始修理，但是那没用，除非我们能先将损坏设备的东西给隔离。',RequestItemsText_loc4='你取得诊断结果了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10418,'解决破坏者','在这片区域收集装置损害的线索时，我在北边的小湖里发现了一些护罩发生器的残骸。我真不明白为什么鳄鱼会对这些设备感兴趣，但我们必须解决这个问题。$B$B星界财团对此的态度非常明确。如果要在装置和鳄鱼之间做出选择的话，那么让这些野兽去死吧。如果你能帮我解决它们，我是不会亏待你的。','中央圆顶哨站的玛尔达德要你杀死8条钩鳞鳄鱼。','这地区已经看起来更清楚了。秘境十分有用，但是主要缺点是他们在某些地方刺激繁茂的生长，加速当地生物种类的生长和发展。','你释放了那些动物的生命了吗?不要误解我，我真的是一个动物爱好者，不过不是当动物们把给予它们食物和庇护的人的手给咬掉的时候。') ON DUPLICATE KEY UPDATE Title_loc4='解决破坏者',Details_loc4='在这片区域收集装置损害的线索时，我在北边的小湖里发现了一些护罩发生器的残骸。我真不明白为什么鳄鱼会对这些设备感兴趣，但我们必须解决这个问题。$B$B星界财团对此的态度非常明确。如果要在装置和鳄鱼之间做出选择的话，那么让这些野兽去死吧。如果你能帮我解决它们，我是不会亏待你的。',Objectives_loc4='中央圆顶哨站的玛尔达德要你杀死8条钩鳞鳄鱼。',OfferRewardText_loc4='这地区已经看起来更清楚了。秘境十分有用，但是主要缺点是他们在某些地方刺激繁茂的生长，加速当地生物种类的生长和发展。',RequestItemsText_loc4='你释放了那些动物的生命了吗?不要误解我，我真的是一个动物爱好者，不过不是当动物们把给予它们食物和庇护的人的手给咬掉的时候。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10419,'奥法宝典','包含在这本秘典里的力量是惊人的。然而一个纯正心灵的人却可以轻易的将它压缩成一个符文。','你拿到更多的秘法宝典了吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='奥法宝典',OfferRewardText_loc4='包含在这本秘典里的力量是惊人的。然而一个纯正心灵的人却可以轻易的将它压缩成一个符文。',RequestItemsText_loc4='你拿到更多的秘法宝典了吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10420,'净化之光','这处神殿是外域最为神圣的地点之一。在这里，你可以感受到相当强大的圣光之力，即使是沾染了最邪恶的污迹的物品，也可以在这里得到净化。$B$B最近，你在与恶魔交战的时候，是否曾经获得一些邪能装备呢？把它们交给我，我可以利用圣光的力量将它们净化。','将一套邪能装备交给沙塔斯城的伊沙娜。$B$B为奥尔多完成任务将会使你在占星者阵营中的声望等级降低。','看着当令人厌恶的物质瓦解时。看着当金属转为灰尘时。$B$B圣光净化全部事物，只剩下最纯净的躯体。','你有拿到任何魔化武器没，$N?') ON DUPLICATE KEY UPDATE Title_loc4='净化之光',Details_loc4='这处神殿是外域最为神圣的地点之一。在这里，你可以感受到相当强大的圣光之力，即使是沾染了最邪恶的污迹的物品，也可以在这里得到净化。$B$B最近，你在与恶魔交战的时候，是否曾经获得一些邪能装备呢？把它们交给我，我可以利用圣光的力量将它们净化。',Objectives_loc4='将一套邪能装备交给沙塔斯城的伊沙娜。$B$B为奥尔多完成任务将会使你在占星者阵营中的声望等级降低。',OfferRewardText_loc4='看着当令人厌恶的物质瓦解时。看着当金属转为灰尘时。$B$B圣光净化全部事物，只剩下最纯净的躯体。',RequestItemsText_loc4='你有拿到任何魔化武器没，$N?';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10421,'邪能装备','将恶魔势力从这个世界除净。让圣光照耀大地。','你今天有拿到任何魔化武器吗?让圣光消灭他们，$N。别让哪些污秽的生物残存在这世界上。') ON DUPLICATE KEY UPDATE Title_loc4='邪能装备',OfferRewardText_loc4='将恶魔势力从这个世界除净。让圣光照耀大地。',RequestItemsText_loc4='你今天有拿到任何魔化武器吗?让圣光消灭他们，$N。别让哪些污秽的生物残存在这世界上。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4) VALUES (10422,'泰拉留斯上尉','十天前，泰拉留斯上尉带领一小队士兵去了南边的复仇军前沿基地，至今杳无音信。$B$B他们很可能遭到了伏击，说不定已经命丧敌手，但是我的仪器接收到了奇怪的信号。$B$B我认为是求援信号，但是这东西以前出过好几次差错，所以我们也不敢肯定。如果泰拉留斯还活着，他应该是被囚禁起来了。你必须设法营救他，或许牢笼的钥匙就在守卫身上。','虚空风暴维序派哨站的驯兽者维里迪斯要你找到并营救泰拉留斯上尉。','谢谢你，$N。泰拉里斯受到了严重的伤害，但是我想它应该可以称过去。$B$B他提及监狱的场所，很像你从中拯救他的那个。监狱充满来自整个宇宙的生物!$B$B当我们准备好可以突破它时，我们会进行联系。联合团已经表示对派遣一些团队并且着手进行一些技术来突破复仇军的封锁感到兴趣。','你找到泰拉里斯了吗?','营救泰拉留斯上尉') ON DUPLICATE KEY UPDATE Title_loc4='泰拉留斯上尉',Details_loc4='十天前，泰拉留斯上尉带领一小队士兵去了南边的复仇军前沿基地，至今杳无音信。$B$B他们很可能遭到了伏击，说不定已经命丧敌手，但是我的仪器接收到了奇怪的信号。$B$B我认为是求援信号，但是这东西以前出过好几次差错，所以我们也不敢肯定。如果泰拉留斯还活着，他应该是被囚禁起来了。你必须设法营救他，或许牢笼的钥匙就在守卫身上。',Objectives_loc4='虚空风暴维序派哨站的驯兽者维里迪斯要你找到并营救泰拉留斯上尉。',OfferRewardText_loc4='谢谢你，$N。泰拉里斯受到了严重的伤害，但是我想它应该可以称过去。$B$B他提及监狱的场所，很像你从中拯救他的那个。监狱充满来自整个宇宙的生物!$B$B当我们准备好可以突破它时，我们会进行联系。联合团已经表示对派遣一些团队并且着手进行一些技术来突破复仇军的封锁感到兴趣。',RequestItemsText_loc4='你找到泰拉里斯了吗?',ObjectiveText1_loc4='营救泰拉留斯上尉';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10423,'前往风暴尖塔','首席技师贾巴尔很想知道诊断程序的结果。他要我们留意圆顶发生器的运行状况，如果力场变得越来越不稳定的话，力场产生的效果也会变得更加难以控制。这对我们和任何其它生活在圆顶下的生物来说都是一场灭顶之灾。$B$B贾巴尔就在风暴尖塔，从生态圆顶出发一路向北，越过桥梁就能看见风暴尖塔底部的升降机了。把诊断结果告诉贾巴尔吧。','与虚空风暴中风暴尖塔的贾巴尔谈一谈。','<你介绍自己并且报告玛戴德对秘境领地的诊断结果。>$B$B玛戴德仅仅是一位技师，但是他拥有观察入微之热心的眼睛。如果他的报告是正确的，那么我们将需要尽快诊断我们其馀的秘境生成器。','我好像没见过你。有什么我可以帮你的吗?') ON DUPLICATE KEY UPDATE Title_loc4='前往风暴尖塔',Details_loc4='首席技师贾巴尔很想知道诊断程序的结果。他要我们留意圆顶发生器的运行状况，如果力场变得越来越不稳定的话，力场产生的效果也会变得更加难以控制。这对我们和任何其它生活在圆顶下的生物来说都是一场灭顶之灾。$B$B贾巴尔就在风暴尖塔，从生态圆顶出发一路向北，越过桥梁就能看见风暴尖塔底部的升降机了。把诊断结果告诉贾巴尔吧。',Objectives_loc4='与虚空风暴中风暴尖塔的贾巴尔谈一谈。',OfferRewardText_loc4='<你介绍自己并且报告玛戴德对秘境领地的诊断结果。>$B$B玛戴德仅仅是一位技师，但是他拥有观察入微之热心的眼睛。如果他的报告是正确的，那么我们将需要尽快诊断我们其馀的秘境生成器。',RequestItemsText_loc4='我好像没见过你。有什么我可以帮你的吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10424,'重要的诊断','如果玛尔达德的诊断结果正确无误——当然，我相信他不会犯错，那么生态圆顶要有大麻烦了。$B$B看来玛尔达德并没有查明造成这种状况的根本原因。以前也曾发生过生物损坏发生器的情况，但从来都没有这么严重过。$B$B为了安全起见，我打算派你去风暴尖塔的主圆顶发生器运行一次诊断程序，它就在最东端的苏瑟伦生态圆顶上。','在苏瑟伦生态圆顶发生器旁使用诊断设备，然后将诊断设备报告交给风暴尖塔的贾巴尔。','这些结果正好符合玛戴德，但是为什么?我能想起的唯一可能解释是一些秘境生成设备已经失效或者失踪。那将使秘境明显地衰弱，并且失去平衡，正如诊断表明的。','你取得那些诊断了吗?') ON DUPLICATE KEY UPDATE Title_loc4='重要的诊断',Details_loc4='如果玛尔达德的诊断结果正确无误——当然，我相信他不会犯错，那么生态圆顶要有大麻烦了。$B$B看来玛尔达德并没有查明造成这种状况的根本原因。以前也曾发生过生物损坏发生器的情况，但从来都没有这么严重过。$B$B为了安全起见，我打算派你去风暴尖塔的主圆顶发生器运行一次诊断程序，它就在最东端的苏瑟伦生态圆顶上。',Objectives_loc4='在苏瑟伦生态圆顶发生器旁使用诊断设备，然后将诊断设备报告交给风暴尖塔的贾巴尔。',OfferRewardText_loc4='这些结果正好符合玛戴德，但是为什么?我能想起的唯一可能解释是一些秘境生成设备已经失效或者失踪。那将使秘境明显地衰弱，并且失去平衡，正如诊断表明的。',RequestItemsText_loc4='你取得那些诊断了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,EndText_loc4) VALUES (10425,'逃离前沿基地','感谢卡雷什！他差点没把我给撕碎！$B$B你好，我是一名维序派士兵。十天前，我所属的分队奉命外出执行侦察任务。就在我们穿越这座浮岛时，一群复仇军士兵突然袭击了我们。至少我觉得是复仇军干的。他们的能量团颜色与复仇军虚灵相同，只是裹带的颜色有些暗淡。$B$B只有泰拉留斯活了下来，他似乎被单独关押起来了。$B$B我必须返回维序派哨站！你能护送我回去吗？','护送被俘虏的维序派前锋返回虚空风暴的维序派哨站。','<指挥官阿密尔露出高兴的表情。>$B$B做的好，新兵!这名士兵可能是攻下复仇军行动的主要关键。','嗯?','护送被俘虏的维序派前锋') ON DUPLICATE KEY UPDATE Title_loc4='逃离前沿基地',Details_loc4='感谢卡雷什！他差点没把我给撕碎！$B$B你好，我是一名维序派士兵。十天前，我所属的分队奉命外出执行侦察任务。就在我们穿越这座浮岛时，一群复仇军士兵突然袭击了我们。至少我觉得是复仇军干的。他们的能量团颜色与复仇军虚灵相同，只是裹带的颜色有些暗淡。$B$B只有泰拉留斯活了下来，他似乎被单独关押起来了。$B$B我必须返回维序派哨站！你能护送我回去吗？',Objectives_loc4='护送被俘虏的维序派前锋返回虚空风暴的维序派哨站。',OfferRewardText_loc4='<指挥官阿密尔露出高兴的表情。>$B$B做的好，新兵!这名士兵可能是攻下复仇军行动的主要关键。',RequestItemsText_loc4='嗯?',EndText_loc4='护送被俘虏的维序派前锋';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4) VALUES (10426,'生态圆顶中的花朵','看看周围，$c！很神奇吧？生命体难以置信地在复苏！虽然这是虚灵的生态圆顶的副产品，但你想想，如果远征队也能掌握这种科技，那将会发挥多大的效用。$B$B我准备和这些虚灵好好协商，看能不能获得这项技术。不过，我想要更直观地了解它对植株的影响力。$B$B这是我制造的调节器，它能将圆顶的能量集中照射在那些鞭笞者身上。你愿意帮我做这项实验，然后告诉我结果吗？','对法兰伦鞭笞者使用能量力场调节器并观察实验结果，进行10次实验后返回风暴尖塔，向欧瑞恩·月焰汇报情况。','喔我的天!集中秘境的能量似乎会持续加快它的成长并使它产生强大的侵略性。如果我们真的获得使用这项技术的能力，我们必须确定要正确地校验它。','你有试着去集中秘境的能量吗?','测试能量调节器') ON DUPLICATE KEY UPDATE Title_loc4='生态圆顶中的花朵',Details_loc4='看看周围，$c！很神奇吧？生命体难以置信地在复苏！虽然这是虚灵的生态圆顶的副产品，但你想想，如果远征队也能掌握这种科技，那将会发挥多大的效用。$B$B我准备和这些虚灵好好协商，看能不能获得这项技术。不过，我想要更直观地了解它对植株的影响力。$B$B这是我制造的调节器，它能将圆顶的能量集中照射在那些鞭笞者身上。你愿意帮我做这项实验，然后告诉我结果吗？',Objectives_loc4='对法兰伦鞭笞者使用能量力场调节器并观察实验结果，进行10次实验后返回风暴尖塔，向欧瑞恩·月焰汇报情况。',OfferRewardText_loc4='喔我的天!集中秘境的能量似乎会持续加快它的成长并使它产生强大的侵略性。如果我们真的获得使用这项技术的能力，我们必须确定要正确地校验它。',RequestItemsText_loc4='你有试着去集中秘境的能量吗?',ObjectiveText1_loc4='测试能量调节器';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText2_loc4) VALUES (10427,'生态圆顶中的生物','你在鞭笞者身上进行的实验取得了令人惊愕的结果，但我还想确认它对动物是否同样有效。$B$B从生态圆顶中的塔布羊身上收集一些信息吧，我想这比研究鞭笞者更为有效。$B$B你可以利用这个标记器，催眠并标记生命力衰弱的塔布羊，便于我追踪它们的生长状况。但是标记器对活蹦乱跳的塔布羊可不起作用，你得先令它们耗尽精力。','为风暴尖塔的欧瑞恩·月焰标记12只塔布羊。你可以使用塔布羊标记器来标记雄性塔布羊和雌性塔布羊。','做得好。我将密切注意那些你加上标示的，并且看看是否他们与秘境里其它生命成熟的一样迅速。$B$B只要控制得适当，我们能使用这技术去使外域和艾泽拉斯被毁坏的地区恢复生机。','你替足够的塔巴克贴上标示了吗?','标记塔布羊') ON DUPLICATE KEY UPDATE Title_loc4='生态圆顶中的生物',Details_loc4='你在鞭笞者身上进行的实验取得了令人惊愕的结果，但我还想确认它对动物是否同样有效。$B$B从生态圆顶中的塔布羊身上收集一些信息吧，我想这比研究鞭笞者更为有效。$B$B你可以利用这个标记器，催眠并标记生命力衰弱的塔布羊，便于我追踪它们的生长状况。但是标记器对活蹦乱跳的塔布羊可不起作用，你得先令它们耗尽精力。',Objectives_loc4='为风暴尖塔的欧瑞恩·月焰标记12只塔布羊。你可以使用塔布羊标记器来标记雄性塔布羊和雌性塔布羊。',OfferRewardText_loc4='做得好。我将密切注意那些你加上标示的，并且看看是否他们与秘境里其它生命成熟的一样迅速。$B$B只要控制得适当，我们能使用这技术去使外域和艾泽拉斯被毁坏的地区恢复生机。',RequestItemsText_loc4='你替足够的塔巴克贴上标示了吗?',ObjectiveText2_loc4='标记塔布羊';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10428,'失踪的渔夫','我们这位身负重伤的客人发了高烧，似乎还做了噩梦。她在说梦话的时候提到了一位名叫库雷的渔夫，这位渔夫似乎就在秘蓝岛西南海岸外的秘银岛上。$b$b这里事情很多，乱作一团，恐怕没有人能够去那边一探究竟了，但我仍然有一点担心。或许你能帮上忙，$N？','在秘银岛东南角正对秘蓝岛海岸边的码头上找到库雷。','我的家人……我做了什么……我怎么会这样做?$B$B为什么我必须被这样惩罚?') ON DUPLICATE KEY UPDATE Title_loc4='失踪的渔夫',Details_loc4='我们这位身负重伤的客人发了高烧，似乎还做了噩梦。她在说梦话的时候提到了一位名叫库雷的渔夫，这位渔夫似乎就在秘蓝岛西南海岸外的秘银岛上。$b$b这里事情很多，乱作一团，恐怕没有人能够去那边一探究竟了，但我仍然有一点担心。或许你能帮上忙，$N？',Objectives_loc4='在秘银岛东南角正对秘蓝岛海岸边的码头上找到库雷。',OfferRewardText_loc4='我的家人……我做了什么……我怎么会这样做?$B$B为什么我必须被这样惩罚?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10429,'失控的大自然','圆顶科技竟然如此强大！当然，$N，我们不能毫无节制地滥用这种力量。$B$B如果生物生长得过于旺盛，肥沃的土地将因此变得贫瘠。$B$B谣传东边池塘中就生活着这种巨型生物，据说有的虚灵商人无聊时就利用那些大型多头怪进行狩猎娱乐。我想要进一步了解这种过度生长的生物，你能取回它的心脏供我研究吗？','风暴尖塔的欧瑞恩·月焰要你取回一颗巨大的多头怪之心。','<阿鲁尼收下那颗心。>$B$B就算是那种尺寸的生物，这个心也太大了。它努力跟上生物的庞大身体。我怀疑它可能在达到正常寿命的一半之前就死了。$B$B即使这样做有很大的风险，我决定说服联合团分享他们的技术。现在有太多承诺要放弃。','你从那个巨大的海蛇身上取得样本了吗?') ON DUPLICATE KEY UPDATE Title_loc4='失控的大自然',Details_loc4='圆顶科技竟然如此强大！当然，$N，我们不能毫无节制地滥用这种力量。$B$B如果生物生长得过于旺盛，肥沃的土地将因此变得贫瘠。$B$B谣传东边池塘中就生活着这种巨型生物，据说有的虚灵商人无聊时就利用那些大型多头怪进行狩猎娱乐。我想要进一步了解这种过度生长的生物，你能取回它的心脏供我研究吗？',Objectives_loc4='风暴尖塔的欧瑞恩·月焰要你取回一颗巨大的多头怪之心。',OfferRewardText_loc4='<阿鲁尼收下那颗心。>$B$B就算是那种尺寸的生物，这个心也太大了。它努力跟上生物的庞大身体。我怀疑它可能在达到正常寿命的一半之前就死了。$B$B即使这样做有很大的风险，我决定说服联合团分享他们的技术。现在有太多承诺要放弃。',RequestItemsText_loc4='你从那个巨大的海蛇身上取得样本了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10430,'测试原型','我一直在研制便携式的发生器维修包，供星界财团在气候恶劣的地区使用。虽然目前的设计并非为虚空风暴定制的，但我想问题应该不大。$B$B我准备派一批最优秀的技师在虚空石西边方的边缘生态圆顶对它进行测试。将维修设备交给塔沙尔吧，他知道如何使用它。如果效果不错的话，我们就利用维修包来强化大型生态圆顶的护罩发生器。','将实验维修设备交给虚空风暴边缘生态圆顶的塔沙尔。','这个东西看起来有点奇特。加巴绝对不是为了虚空风暴而制造这个东西。$B$B别露出惊讶的表情，$N。跟我们在其它工作的环境比较起来虚空风暴的环境算是温和的了。然而一个失败的秘境总是会令人担心。','看来你已经取得原型了。是加巴派你来的吗?') ON DUPLICATE KEY UPDATE Title_loc4='测试原型',Details_loc4='我一直在研制便携式的发生器维修包，供星界财团在气候恶劣的地区使用。虽然目前的设计并非为虚空风暴定制的，但我想问题应该不大。$B$B我准备派一批最优秀的技师在虚空石西边方的边缘生态圆顶对它进行测试。将维修设备交给塔沙尔吧，他知道如何使用它。如果效果不错的话，我们就利用维修包来强化大型生态圆顶的护罩发生器。',Objectives_loc4='将实验维修设备交给虚空风暴边缘生态圆顶的塔沙尔。',OfferRewardText_loc4='这个东西看起来有点奇特。加巴绝对不是为了虚空风暴而制造这个东西。$B$B别露出惊讶的表情，$N。跟我们在其它工作的环境比较起来虚空风暴的环境算是温和的了。然而一个失败的秘境总是会令人担心。',RequestItemsText_loc4='看来你已经取得原型了。是加巴派你来的吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10431,'外界的帮助','日怒军团的简报足以证明凯尔萨斯在建设和运行法力熔炉的过程中接受了外界的帮助。究竟是谁在暗地里支持凯尔依然是个谜，但是我们可以在法力熔炉：艾拉找到答案。$B$B我已经派出人手侦察那一带的情况。前往北边的图鲁曼的营地，与凯兰恩谈一谈。看看他在法力熔炉：艾拉有什么发现。一定要揪出暗中协助日怒军团的家伙。','前往52区以北的图鲁曼的营地，与凯兰恩谈一谈。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。','你是欧瑞利斯派来的唯一帮助?他一定觉得你非常厉害。$B$B让我们结束这一切。') ON DUPLICATE KEY UPDATE Title_loc4='外界的帮助',Details_loc4='日怒军团的简报足以证明凯尔萨斯在建设和运行法力熔炉的过程中接受了外界的帮助。究竟是谁在暗地里支持凯尔依然是个谜，但是我们可以在法力熔炉：艾拉找到答案。$B$B我已经派出人手侦察那一带的情况。前往北边的图鲁曼的营地，与凯兰恩谈一谈。看看他在法力熔炉：艾拉有什么发现。一定要揪出暗中协助日怒军团的家伙。',Objectives_loc4='前往52区以北的图鲁曼的营地，与凯兰恩谈一谈。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。',OfferRewardText_loc4='你是欧瑞利斯派来的唯一帮助?他一定觉得你非常厉害。$B$B让我们结束这一切。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10432,'可怕的证据','你大概也注意到了，法力熔炉：艾拉遍布着燃烧军团的仆从。凯尔萨斯已经与燃烧军团结为盟友。他定然察觉到伊利丹堕入了疯狂的边缘，对魔法的渴求促使他投靠燃烧军团麾下。$B$B如果此事证据确凿，那么这支实力雄厚的联合军队可不容小觑。占星者已经得到确切消息，称法力熔炉的燃烧军团将士们都听从凯尔萨斯的指挥。$B$B将凯尔萨斯的命令交给萨罗迪恩吧。','从法力熔炉：艾拉的恶魔手中夺得8份凯尔萨斯的命令，将它们交给52区的间谍大师萨罗迪恩。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。','这是一件大事，$N。非常大!$B$B沃蓝索将会想要尽快听到这事。','喔?萨洛迪恩有说什么吗?') ON DUPLICATE KEY UPDATE Title_loc4='可怕的证据',Details_loc4='你大概也注意到了，法力熔炉：艾拉遍布着燃烧军团的仆从。凯尔萨斯已经与燃烧军团结为盟友。他定然察觉到伊利丹堕入了疯狂的边缘，对魔法的渴求促使他投靠燃烧军团麾下。$B$B如果此事证据确凿，那么这支实力雄厚的联合军队可不容小觑。占星者已经得到确切消息，称法力熔炉的燃烧军团将士们都听从凯尔萨斯的指挥。$B$B将凯尔萨斯的命令交给萨罗迪恩吧。',Objectives_loc4='从法力熔炉：艾拉的恶魔手中夺得8份凯尔萨斯的命令，将它们交给52区的间谍大师萨罗迪恩。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。',OfferRewardText_loc4='这是一件大事，$N。非常大!$B$B沃蓝索将会想要尽快听到这事。',RequestItemsText_loc4='喔?萨洛迪恩有说什么吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10433,'保持伪装','虚灵都是聪明而机警的家伙，因此我不得不伪装成普通的毛皮商人。事实上我是52区的商业间谍，奉命来到这里评估他们搭建生态圆顶的科技。$B$B我需要你的帮助，$c。你看，必要的时候，我们就会利用非地精的间谍。$B$B我要你伪装成猎手，给我弄些锋牙山猫的毛皮回来，中央生态圆顶内到处都是这种山猫。','为中央圆顶哨站的舒利·波尔带回10张锋牙山猫的毛皮。','<休利对你带回来的毛皮露出赞叹的表情。>$B$B这些毛皮品质太好了，真的太棒了!我愿意付给你最高的价钱!多少钱才可以让你继续维持这种服务呢?','<休利提高了声量以吸引那里的以太族注意。>$B$B有任何毛皮要卖的吗?') ON DUPLICATE KEY UPDATE Title_loc4='保持伪装',Details_loc4='虚灵都是聪明而机警的家伙，因此我不得不伪装成普通的毛皮商人。事实上我是52区的商业间谍，奉命来到这里评估他们搭建生态圆顶的科技。$B$B我需要你的帮助，$c。你看，必要的时候，我们就会利用非地精的间谍。$B$B我要你伪装成猎手，给我弄些锋牙山猫的毛皮回来，中央生态圆顶内到处都是这种山猫。',Objectives_loc4='为中央圆顶哨站的舒利·波尔带回10张锋牙山猫的毛皮。',OfferRewardText_loc4='<休利对你带回来的毛皮露出赞叹的表情。>$B$B这些毛皮品质太好了，真的太棒了!我愿意付给你最高的价钱!多少钱才可以让你继续维持这种服务呢?',RequestItemsText_loc4='<休利提高了声量以吸引那里的以太族注意。>$B$B有任何毛皮要卖的吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10434,'两个同伴','干得不错。$B$B<舒利对你眨了眨眼睛。>$B$B我想这样他们就会相信我是普通的皮毛商人了。现在我要派你去联络我在风暴尖塔的同伴，虚灵应该不会对你起疑心的。$B$B去风暴尖塔寻找粗暴的贾森和针眼奥蒂吧。他们会告诉你所有你需要知道的事情。就说是舒利派你去的。','与虚空风暴中风暴尖塔的针眼奥蒂谈一谈。','<你自我介绍，并且告诉欧杜是休利派你来的。>$B$B啊，是呀，我们一直希望有人能帮上忙，呃 -- 帮忙搬动一些，嗯，商品。','很高兴见到你，$C。') ON DUPLICATE KEY UPDATE Title_loc4='两个同伴',Details_loc4='干得不错。$B$B<舒利对你眨了眨眼睛。>$B$B我想这样他们就会相信我是普通的皮毛商人了。现在我要派你去联络我在风暴尖塔的同伴，虚灵应该不会对你起疑心的。$B$B去风暴尖塔寻找粗暴的贾森和针眼奥蒂吧。他们会告诉你所有你需要知道的事情。就说是舒利派你去的。',Objectives_loc4='与虚空风暴中风暴尖塔的针眼奥蒂谈一谈。',OfferRewardText_loc4='<你自我介绍，并且告诉欧杜是休利派你来的。>$B$B啊，是呀，我们一直希望有人能帮上忙，呃 -- 帮忙搬动一些，嗯，商品。',RequestItemsText_loc4='很高兴见到你，$C。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10435,'找回货物','<奥蒂环顾四周，压低了嗓门。>$B$B我想舒利向你提过我们来这里的真正目的吧。当贾森和我在生态圆顶中“狩猎”时，我们会趁机收集掩码生成器的碎片，并将它们藏在猎物的毛皮中。$B$B通常我们都在边缘生态圆顶中猎杀迅猛龙，那地方位于风暴尖塔东北方，离虚空石很近。你能去那里帮我们收集掩码生成器的碎片吗？','风暴尖塔的针眼奥蒂要你取回10块掩码生成器碎片。','做的好!计划里最难的部分已经完成了。现在，所有我们需要的是如何将这些带回到52区的方法，并同时吸引塞纳里奥探险队的兴趣。这里应该足够我们自己的需要，加上一点额外的利润。','你收集到所有东西了吗?') ON DUPLICATE KEY UPDATE Title_loc4='找回货物',Details_loc4='<奥蒂环顾四周，压低了嗓门。>$B$B我想舒利向你提过我们来这里的真正目的吧。当贾森和我在生态圆顶中“狩猎”时，我们会趁机收集掩码生成器的碎片，并将它们藏在猎物的毛皮中。$B$B通常我们都在边缘生态圆顶中猎杀迅猛龙，那地方位于风暴尖塔东北方，离虚空石很近。你能去那里帮我们收集掩码生成器的碎片吗？',Objectives_loc4='风暴尖塔的针眼奥蒂要你取回10块掩码生成器碎片。',OfferRewardText_loc4='做的好!计划里最难的部分已经完成了。现在，所有我们需要的是如何将这些带回到52区的方法，并同时吸引塞纳里奥探险队的兴趣。这里应该足够我们自己的需要，加上一点额外的利润。',RequestItemsText_loc4='你收集到所有东西了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10436,'全部清理！','我们必须首先确保这片区域没有其它干扰因素才能进行实验。我是指那些过度生长的蜥蜴类的生物。$B$B<塔沙尔指了指远处的镰牙迅猛龙。>$B$B如果它们在发生器充能时突然冲上去咬一口，天知道会发生什么事。在我担任技师的这些年里，见过不少诡异的事情，例如目睹某些可爱的小动物成长为异型怪兽。','边缘生态圆顶的塔沙尔要你杀死12只镰牙迅猛龙。','做得好。看起来一切都就绪了。我们准备要开始了。','你把测试区域清除了吗?') ON DUPLICATE KEY UPDATE Title_loc4='全部清理！',Details_loc4='我们必须首先确保这片区域没有其它干扰因素才能进行实验。我是指那些过度生长的蜥蜴类的生物。$B$B<塔沙尔指了指远处的镰牙迅猛龙。>$B$B如果它们在发生器充能时突然冲上去咬一口，天知道会发生什么事。在我担任技师的这些年里，见过不少诡异的事情，例如目睹某些可爱的小动物成长为异型怪兽。',Objectives_loc4='边缘生态圆顶的塔沙尔要你杀死12只镰牙迅猛龙。',OfferRewardText_loc4='做得好。看起来一切都就绪了。我们准备要开始了。',RequestItemsText_loc4='你把测试区域清除了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10437,'毁灭的材料','虚空领主迪门修斯利用法力熔炉：乌提斯顶部的虚空裂隙进入了我们的世界。这处裂隙使得迪门修斯能在物质世界和扭曲虚空间自由穿行，免疫一切物理伤害。如果我们能切断空灵管道的能量流，迪门修斯将被困在这个位面，再也无法进行相位变换。那样的话，我们就能轻而易举地消灭它了。$B$B要完成这个计划，我们需要你从迪门修斯创造的虚空生物身上收集一些来自虚空领主本体的碎片。','虚空风暴维序派哨站的达比雷教授要你取回8块迪门修斯的碎片。','太好了。有了这些碎片，我们就能校准一颗炸弹摧毁奥崔斯上面的虚无导线。随着虚无导线的摧毁，迪曼修斯将无法与虚无连结并变得毫无防御!','你收集到足够的碎片了吗?') ON DUPLICATE KEY UPDATE Title_loc4='毁灭的材料',Details_loc4='虚空领主迪门修斯利用法力熔炉：乌提斯顶部的虚空裂隙进入了我们的世界。这处裂隙使得迪门修斯能在物质世界和扭曲虚空间自由穿行，免疫一切物理伤害。如果我们能切断空灵管道的能量流，迪门修斯将被困在这个位面，再也无法进行相位变换。那样的话，我们就能轻而易举地消灭它了。$B$B要完成这个计划，我们需要你从迪门修斯创造的虚空生物身上收集一些来自虚空领主本体的碎片。',Objectives_loc4='虚空风暴维序派哨站的达比雷教授要你取回8块迪门修斯的碎片。',OfferRewardText_loc4='太好了。有了这些碎片，我们就能校准一颗炸弹摧毁奥崔斯上面的虚无导线。随着虚无导线的摧毁，迪曼修斯将无法与虚无连结并变得毫无防御!',RequestItemsText_loc4='你收集到足够的碎片了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4) VALUES (10438,'虚空幼龙之翼','给，$N。带上这些相位扰流器出发吧！维序派的虚空幼龙会将你送到乌提斯上空，然后你要对准空灵管道投掷相位扰流器。$B$B为了彻底摧毁空灵管道，你必须尽可能多地抛下扰流器！$B$B等你准备就绪，就与虚空幼龙谈一谈，它会载你前往目的地的。$B$B如果你没能瞄准目标，浪费了太多扰流器的话，可以回来向我再要一些。','虚空风暴维序派哨站的达比雷教授要你前往法力熔炉：乌提斯，在顶部的空灵管道附近使用相位扰流器。为了彻底摧毁空灵管道，你必须尽可能多地抛下相位扰流器。只要投掷的距离够近，相位扰流器就会自动依附在空灵管道上。$B$B完成任务后向达比雷教授复命。','出击的时候到了!随着裂洞消失，迪曼修斯的身体及魔力上变得不堪一击!','你击中目标了吗?','摧毁空灵管道') ON DUPLICATE KEY UPDATE Title_loc4='虚空幼龙之翼',Details_loc4='给，$N。带上这些相位扰流器出发吧！维序派的虚空幼龙会将你送到乌提斯上空，然后你要对准空灵管道投掷相位扰流器。$B$B为了彻底摧毁空灵管道，你必须尽可能多地抛下扰流器！$B$B等你准备就绪，就与虚空幼龙谈一谈，它会载你前往目的地的。$B$B如果你没能瞄准目标，浪费了太多扰流器的话，可以回来向我再要一些。',Objectives_loc4='虚空风暴维序派哨站的达比雷教授要你前往法力熔炉：乌提斯，在顶部的空灵管道附近使用相位扰流器。为了彻底摧毁空灵管道，你必须尽可能多地抛下相位扰流器。只要投掷的距离够近，相位扰流器就会自动依附在空灵管道上。$B$B完成任务后向达比雷教授复命。',OfferRewardText_loc4='出击的时候到了!随着裂洞消失，迪曼修斯的身体及魔力上变得不堪一击!',RequestItemsText_loc4='你击中目标了吗?',ObjectiveText1_loc4='摧毁空灵管道';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText2_loc4) VALUES (10439,'诸界吞噬者迪门修斯','你勇敢的行动为阿米尔赢得了有利的时机！他已经调派了萨义德上尉和复仇者部队准备出击。$B$B与迪门修斯决战的时刻就要来临了。$B$B你准备妥当后就联络萨义德。如果他目前没有执行其它战斗任务的话，应该在此地正东方等待你的调遣。$B$B告诉他你已经准备好迎战迪门修斯，他的部队会配合你展开行动！$B$B祝你好运，肉乎乎的朋友！我们奉命追杀迪门修斯已经有千年之久了，胜利就在眼前！','虚空风暴维序派哨站的达比雷教授要你与萨义德上尉谈一谈，然后跟随他的军队前往法力熔炉：乌提斯，杀死诸界吞噬者迪门修斯！','一千年来，我们知道的就是战斗。我们已经保护我的人民以免遭受虚无生物及以太族同类的攻击。$B$B现在，我们憎恨的敌人之一已经死亡了 - 终于。$B$B我致上十亿名以太族的感谢，凡人。','虚无领主怎么样了?','与萨义德上尉交谈') ON DUPLICATE KEY UPDATE Title_loc4='诸界吞噬者迪门修斯',Details_loc4='你勇敢的行动为阿米尔赢得了有利的时机！他已经调派了萨义德上尉和复仇者部队准备出击。$B$B与迪门修斯决战的时刻就要来临了。$B$B你准备妥当后就联络萨义德。如果他目前没有执行其它战斗任务的话，应该在此地正东方等待你的调遣。$B$B告诉他你已经准备好迎战迪门修斯，他的部队会配合你展开行动！$B$B祝你好运，肉乎乎的朋友！我们奉命追杀迪门修斯已经有千年之久了，胜利就在眼前！',Objectives_loc4='虚空风暴维序派哨站的达比雷教授要你与萨义德上尉谈一谈，然后跟随他的军队前往法力熔炉：乌提斯，杀死诸界吞噬者迪门修斯！',OfferRewardText_loc4='一千年来，我们知道的就是战斗。我们已经保护我的人民以免遭受虚无生物及以太族同类的攻击。$B$B现在，我们憎恨的敌人之一已经死亡了 - 终于。$B$B我致上十亿名以太族的感谢，凡人。',RequestItemsText_loc4='虚无领主怎么样了?',ObjectiveText2_loc4='与萨义德上尉交谈';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10440,'成功了！','实验非常成功！我们可以利用这台装置进行生态圆顶的修复作业了。$B$B返回风暴尖塔汇报实验结果吧，告诉贾巴尔我已查明引发掩码生成器运行故障的基本原因。$N，数座生态圆顶护罩发生器的重要功能单元都不翼而飞。这不是意外事件，也绝对不是技术故障。换句话说，我们遭窃了。','返回虚空风暴中的风暴尖塔，与贾巴尔谈一谈。','我会让我的技师马上去修复这些机器。$B$B不过，塔斯尔对于损坏的怀疑让我忧心。我不认为有任何人那么大胆敢来偷我们的机器。至少没有人知道我们有这种技术。或许是闭锁风暴之尖的时候了。$B') ON DUPLICATE KEY UPDATE Title_loc4='成功了！',Details_loc4='实验非常成功！我们可以利用这台装置进行生态圆顶的修复作业了。$B$B返回风暴尖塔汇报实验结果吧，告诉贾巴尔我已查明引发掩码生成器运行故障的基本原因。$N，数座生态圆顶护罩发生器的重要功能单元都不翼而飞。这不是意外事件，也绝对不是技术故障。换句话说，我们遭窃了。',Objectives_loc4='返回虚空风暴中的风暴尖塔，与贾巴尔谈一谈。',OfferRewardText_loc4='我会让我的技师马上去修复这些机器。$B$B不过，塔斯尔对于损坏的怀疑让我忧心。我不认为有任何人那么大胆敢来偷我们的机器。至少没有人知道我们有这种技术。或许是闭锁风暴之尖的时候了。$B';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10441,'推销货物','<奥蒂再次压低了嗓门。>$B$B我打算将手头上的货偷偷送回52区。这些零件可以组装出不止一台的掩码生成器，为我们带来难以估量的商业利益。$B$B我看见塞纳里奥远征队的代表在与虚灵协商，希望能获得生态圆顶科技的资料。你不妨告诉她，她想要的货我们也有，而且价码非常合理。这样她就不用和那些狡诈的虚灵继续交涉了。','与虚空风暴中风暴尖塔底部的欧瑞恩·月焰谈一谈。','<阿鲁尼仔细地聆听你的讯息。>$B$B那么看我是否确实了解你的意思。这些哥布尔是怎么设法“取得”这个秘境生成器的我连问都不用问。$B$B正常来说，塞纳里奥远征队是不与这类型的企业有关联，不过我会传达这个“提议”给我的上级。','我能帮你什么呢，$N?') ON DUPLICATE KEY UPDATE Title_loc4='推销货物',Details_loc4='<奥蒂再次压低了嗓门。>$B$B我打算将手头上的货偷偷送回52区。这些零件可以组装出不止一台的掩码生成器，为我们带来难以估量的商业利益。$B$B我看见塞纳里奥远征队的代表在与虚灵协商，希望能获得生态圆顶科技的资料。你不妨告诉她，她想要的货我们也有，而且价码非常合理。这样她就不用和那些狡诈的虚灵继续交涉了。',Objectives_loc4='与虚空风暴中风暴尖塔底部的欧瑞恩·月焰谈一谈。',OfferRewardText_loc4='<阿鲁尼仔细地聆听你的讯息。>$B$B那么看我是否确实了解你的意思。这些哥布尔是怎么设法“取得”这个秘境生成器的我连问都不用问。$B$B正常来说，塞纳里奥远征队是不与这类型的企业有关联，不过我会传达这个“提议”给我的上级。',RequestItemsText_loc4='我能帮你什么呢，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10442,'帮助塞纳里奥哨站','$C，有一个叫塞安·红鬃的牛头人需要我们的帮助。她现在跟塞纳里奥远征队在一起，驻扎在通往赞加沼泽的道路南边的一处规模岗哨里。$B$B你看到棘牙岭以后，就基本上已经到达那处岗哨了。$B$B你愿意到那里去看看她需要什么帮助吗？我不想为了这一点点小事打扰到游侠队长维恩雷大人。','驯鹰者德蕾娜·河风要你前往地狱火半岛的塞纳里奥哨站，帮助塞安·红鬃。','喔，天啊，你一定就是我几个星期前从猎鹰哨站请求协助的帮手吧。$B$B好吧，你现在来了，有很多事要做。我要你从这件开始做。') ON DUPLICATE KEY UPDATE Title_loc4='帮助塞纳里奥哨站',Details_loc4='$C，有一个叫塞安·红鬃的牛头人需要我们的帮助。她现在跟塞纳里奥远征队在一起，驻扎在通往赞加沼泽的道路南边的一处规模岗哨里。$B$B你看到棘牙岭以后，就基本上已经到达那处岗哨了。$B$B你愿意到那里去看看她需要什么帮助吗？我不想为了这一点点小事打扰到游侠队长维恩雷大人。',Objectives_loc4='驯鹰者德蕾娜·河风要你前往地狱火半岛的塞纳里奥哨站，帮助塞安·红鬃。',OfferRewardText_loc4='喔，天啊，你一定就是我几个星期前从猎鹰哨站请求协助的帮手吧。$B$B好吧，你现在来了，有很多事要做。我要你从这件开始做。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10443,'帮助塞纳里奥哨站','艾泽拉斯的塞纳里奥议会也派了一支远征队到外域来。据我了解，他们应该是来调查这里的环境，并同时试图挽救这里所遭受的生态危机。$B$B他们目前驻扎在西面，在通向赞加沼泽的道路南侧创建了一处小规模的岗哨。$B$B走到棘牙岭附近，你就可以看到他们的岗哨了。$B$B你愿意去那里看看能否帮上什么忙吗？与塞安·红鬃谈一谈吧，就是她来向找我们寻求帮助的。','智者阿曼恩要你前往地狱火半岛的塞纳里奥哨站，帮助塞安·红鬃。','喔，天啊，你一定是我对特尔哈曼神庙提出要求而来的帮手。$B$B我很高兴你来了;我们有很多事情要做，而且我这里刚好有样东西可以帮助你开始着手。') ON DUPLICATE KEY UPDATE Title_loc4='帮助塞纳里奥哨站',Details_loc4='艾泽拉斯的塞纳里奥议会也派了一支远征队到外域来。据我了解，他们应该是来调查这里的环境，并同时试图挽救这里所遭受的生态危机。$B$B他们目前驻扎在西面，在通向赞加沼泽的道路南侧创建了一处小规模的岗哨。$B$B走到棘牙岭附近，你就可以看到他们的岗哨了。$B$B你愿意去那里看看能否帮上什么忙吗？与塞安·红鬃谈一谈吧，就是她来向找我们寻求帮助的。',Objectives_loc4='智者阿曼恩要你前往地狱火半岛的塞纳里奥哨站，帮助塞安·红鬃。',OfferRewardText_loc4='喔，天啊，你一定是我对特尔哈曼神庙提出要求而来的帮手。$B$B我很高兴你来了;我们有很多事情要做，而且我这里刚好有样东西可以帮助你开始着手。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10444,'奥蕾莉亚岗哨','必须立即采取行动！$B$B我要你跟火翼岗哨前线附近的米利迪安中尉谈谈。他应该知道我们下一步该怎么做。$B$B去吧，向奥蕾莉亚岗哨外的米利迪安中尉报到并汇报眼下的局势。岗哨位于此地东北方，就在火翼岗哨以南那条河流的南岸。$B$B$N，祝你成功。','杰奈·星语要你前往泰罗卡森林的奥蕾莉亚岗哨，向米利迪安中尉报到。','炸弹零件。所以我的怀疑是正确的。那不是我希望的事。$B$B好吧，接着你跟我还有一些讨厌的事情要处理。') ON DUPLICATE KEY UPDATE Title_loc4='奥蕾莉亚岗哨',Details_loc4='必须立即采取行动！$B$B我要你跟火翼岗哨前线附近的米利迪安中尉谈谈。他应该知道我们下一步该怎么做。$B$B去吧，向奥蕾莉亚岗哨外的米利迪安中尉报到并汇报眼下的局势。岗哨位于此地东北方，就在火翼岗哨以南那条河流的南岸。$B$B$N，祝你成功。',Objectives_loc4='杰奈·星语要你前往泰罗卡森林的奥蕾莉亚岗哨，向米利迪安中尉报到。',OfferRewardText_loc4='炸弹零件。所以我的怀疑是正确的。那不是我希望的事。$B$B好吧，接着你跟我还有一些讨厌的事情要处理。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10445,'永恒水瓶','伊利丹从永恒之井中取出了七瓶水。他将其中三瓶倒入海加尔山颠的湖泊中，由此形成了第二口永恒之井。岁月流逝，剩下的四瓶水已不知去向。$B$B黑暗之门开启后，我们得知伊利丹将两瓶水交给了他的副官凯尔萨斯和瓦丝琪。取回残馀的永恒之水，我们可以利用它打开通往近代或是远古时期的海加尔山的时光通道。我们必须维持海加尔圣战的事件不被改变。','时光之穴的索莉多米要你从盘牙水库的瓦丝琪那里取回瓦丝琪的水瓶残馀，并从风暴要塞的凯尔萨斯·逐日者那里取回凯尔萨斯的水瓶残馀。','即使是这么少量的永恒之井水也包含了不可思议的能量。
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText2_loc4) VALUES (10446,'终极密码','他们正在火翼岗哨的庭院中制作第二枚魔法炸弹。这枚魔法炸弹的终极密码在火翼岗哨的监工沙尔斯·沃多恩手中。$B$B$N，你必须返回那儿，夺取终极密码。他就在那座最高的塔中。$B$B使用终极密码引爆中央庭院的魔法炸弹，只有这样才能确保奥蕾莉亚要塞的安全。','米利迪安中尉要你使用终极密码引爆魔法炸弹，然后向泰罗卡森林奥蕾莉亚要塞的杰奈·星语复命。','你做到了!你拯救了我们!你救了整个艾兰里堡垒!!$B$B随着他们部队的消灭，领导者的死亡以及法力炸弹的摧毁，我们现在能够更自在的呼吸了。$B$B$N，我从来都没有这么忘我过……','莫瑞狄恩中尉一直都在通报我们有关火翼岗哨的状况。一切都还好吗?','引爆魔法炸弹') ON DUPLICATE KEY UPDATE Title_loc4='终极密码',Details_loc4='他们正在火翼岗哨的庭院中制作第二枚魔法炸弹。这枚魔法炸弹的终极密码在火翼岗哨的监工沙尔斯·沃多恩手中。$B$B$N，你必须返回那儿，夺取终极密码。他就在那座最高的塔中。$B$B使用终极密码引爆中央庭院的魔法炸弹，只有这样才能确保奥蕾莉亚要塞的安全。',Objectives_loc4='米利迪安中尉要你使用终极密码引爆魔法炸弹，然后向泰罗卡森林奥蕾莉亚要塞的杰奈·星语复命。',OfferRewardText_loc4='你做到了!你拯救了我们!你救了整个艾兰里堡垒!!$B$B随着他们部队的消灭，领导者的死亡以及法力炸弹的摧毁，我们现在能够更自在的呼吸了。$B$B$N，我从来都没有这么忘我过……',RequestItemsText_loc4='莫瑞狄恩中尉一直都在通报我们有关火翼岗哨的状况。一切都还好吗?',ObjectiveText2_loc4='引爆魔法炸弹';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText2_loc4) VALUES (10447,'终极密码','他们正在火翼岗哨的庭院中制作第二枚魔法炸弹。这枚魔法炸弹的终极密码在火翼岗哨的监工沙尔斯·沃多恩手中。$B$B$N，你必须返回那儿，夺取终极密码。他就在那座最高的塔中。$B$B使用终极密码引爆中央庭院的魔法炸弹，只有这样才能确保裂石堡的安全。','卡乌尼中士要你使用终极密码引爆魔法炸弹，然后向泰罗卡森林裂石堡的图基复命。','你做到了!你拯救了我们!你救了整个碎石堡!!$B$B随着他们部队的消灭，领导者的死亡以及法力炸弹的摧毁，我们现在能够更自在的呼吸了。$B$B$N，我从来都没有如此忘我过……如此的英勇!请接受这个代表我们所有人的东西。','丘尼士官一直都在通报我们有关火翼岗哨的状况。一切都还好吗?','引爆魔法炸弹') ON DUPLICATE KEY UPDATE Title_loc4='终极密码',Details_loc4='他们正在火翼岗哨的庭院中制作第二枚魔法炸弹。这枚魔法炸弹的终极密码在火翼岗哨的监工沙尔斯·沃多恩手中。$B$B$N，你必须返回那儿，夺取终极密码。他就在那座最高的塔中。$B$B使用终极密码引爆中央庭院的魔法炸弹，只有这样才能确保裂石堡的安全。',Objectives_loc4='卡乌尼中士要你使用终极密码引爆魔法炸弹，然后向泰罗卡森林裂石堡的图基复命。',OfferRewardText_loc4='你做到了!你拯救了我们!你救了整个碎石堡!!$B$B随着他们部队的消灭，领导者的死亡以及法力炸弹的摧毁，我们现在能够更自在的呼吸了。$B$B$N，我从来都没有如此忘我过……如此的英勇!请接受这个代表我们所有人的东西。',RequestItemsText_loc4='丘尼士官一直都在通报我们有关火翼岗哨的状况。一切都还好吗?',ObjectiveText2_loc4='引爆魔法炸弹';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10448,'向裂石营地报到','必须立即采取行动！$B$B我要你跟火翼岗哨附近的卡乌尼中士谈谈。她应该知道我们下一步该怎么做。$B$B向裂石营地的卡乌尼中士报到并汇报眼下的局势。出了要塞往北走，在图雷姆往东转，营地就在火翼岗哨以南那条河流的南岸。$B$B$N，祝你成功。','图基要你前往泰罗卡森林的裂石营地，向卡乌尼中士报到。','炸弹零件。所以我的怀疑是正确的。那不是我希望的事。$B$B好吧，接着你跟我还有一些讨厌的事情要处理。') ON DUPLICATE KEY UPDATE Title_loc4='向裂石营地报到',Details_loc4='必须立即采取行动！$B$B我要你跟火翼岗哨附近的卡乌尼中士谈谈。她应该知道我们下一步该怎么做。$B$B向裂石营地的卡乌尼中士报到并汇报眼下的局势。出了要塞往北走，在图雷姆往东转，营地就在火翼岗哨以南那条河流的南岸。$B$B$N，祝你成功。',Objectives_loc4='图基要你前往泰罗卡森林的裂石营地，向卡乌尼中士报到。',OfferRewardText_loc4='炸弹零件。所以我的怀疑是正确的。那不是我希望的事。$B$B好吧，接着你跟我还有一些讨厌的事情要处理。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10449,'药剂师塞兰娜','药剂师塞兰娜一直在研究地狱火半岛一带的野生动物，她也需要一份你之前采集到的血样。运气好的话，她或许能检测出令噬骨邪兽人的皮肤变红的原因！$B$B塞兰娜在萨尔玛东南方的机甲残骸。沿着道路往东走，你很快就会看见一块发着绿光的大块金属残体，那就是你的目的地。她在那群双足飞龙后面设立了一处营地。','萨尔玛的乌托克·断斧要你前往机甲残骸，将噬骨血样交给药剂师塞兰娜。','啊，太好了。噬骨者氏族的血。我对这些兽人很好奇……他们仍是过去堕落的恶魔，但他们的力量却比我所听过的更强大了……$B$B嗯，让我们开始吧?','为部落效劳是我的荣幸。我能帮你什么忙?') ON DUPLICATE KEY UPDATE Title_loc4='药剂师塞兰娜',Details_loc4='药剂师塞兰娜一直在研究地狱火半岛一带的野生动物，她也需要一份你之前采集到的血样。运气好的话，她或许能检测出令噬骨邪兽人的皮肤变红的原因！$B$B塞兰娜在萨尔玛东南方的机甲残骸。沿着道路往东走，你很快就会看见一块发着绿光的大块金属残体，那就是你的目的地。她在那群双足飞龙后面设立了一处营地。',Objectives_loc4='萨尔玛的乌托克·断斧要你前往机甲残骸，将噬骨血样交给药剂师塞兰娜。',OfferRewardText_loc4='啊，太好了。噬骨者氏族的血。我对这些兽人很好奇……他们仍是过去堕落的恶魔，但他们的力量却比我所听过的更强大了……$B$B嗯，让我们开始吧?',RequestItemsText_loc4='为部落效劳是我的荣幸。我能帮你什么忙?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10450,'噬骨之血','噬骨邪兽人！他们都该死！一看到他们的红色皮肤和堕落的模样，我浑身就热血沸腾！$B$B$N，我有项任务要给你。去干掉那些噬骨邪兽人，然后收集一些他们污秽的血液。有一位药剂师需要这些血液来做检测，结果出来以后，我们或许就能了解到这些兽人是如何被恶魔腐化身心的。事实上，我们也是刚刚摆脱这种腐化。$B$B噬骨邪兽人分布在南边荣耀之路两侧的碉堡废墟附近，任务完成后回来向我复命。','将12瓶噬骨之血交给萨尔玛的乌托克·断斧。','哈!所以你真的挑战了噬骨者，我们堕落的亲戚。做的好，$N。我唯一的悔恨就是他们不能放下他们的生命溅洒他们的鲜血，来平息我的暴行!','你挑战了噬骨者吗，$N。我希望他们的鲜血洒满大地!') ON DUPLICATE KEY UPDATE Title_loc4='噬骨之血',Details_loc4='噬骨邪兽人！他们都该死！一看到他们的红色皮肤和堕落的模样，我浑身就热血沸腾！$B$B$N，我有项任务要给你。去干掉那些噬骨邪兽人，然后收集一些他们污秽的血液。有一位药剂师需要这些血液来做检测，结果出来以后，我们或许就能了解到这些兽人是如何被恶魔腐化身心的。事实上，我们也是刚刚摆脱这种腐化。$B$B噬骨邪兽人分布在南边荣耀之路两侧的碉堡废墟附近，任务完成后回来向我复命。',Objectives_loc4='将12瓶噬骨之血交给萨尔玛的乌托克·断斧。',OfferRewardText_loc4='哈!所以你真的挑战了噬骨者，我们堕落的亲戚。做的好，$N。我唯一的悔恨就是他们不能放下他们的生命溅洒他们的鲜血，来平息我的暴行!',RequestItemsText_loc4='你挑战了噬骨者吗，$N。我希望他们的鲜血洒满大地!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,EndText_loc4) VALUES (10451,'逃离库斯卡水池','感谢大地之母！几天前我跟大地之环的伙伴分开，决心揭开水元素之魂躁动的秘密。我一路探寻，发现库斯卡的纳迦正在污染影月谷的水源。$B$B不幸的是，我不小心暴露了行踪，被关了起来。不知道这帮家伙会用什么样的法子来折磨我。$B$B我们必须离开这里！护送我逃离库斯卡水池，然后到诅咒祭坛去找托洛克。','护送大地治愈者维尔达逃离库斯卡水池，然后前往古尔丹之手以西的诅咒祭坛，向大地治愈者托洛克复命。','赞美大地之母。我确定威尔达将会找到回家的路。请收下这个以表我们的谢意。','你找到威尔达姐妹了吗?','护送大地治愈者维尔达到达安全地点') ON DUPLICATE KEY UPDATE Title_loc4='逃离库斯卡水池',Details_loc4='感谢大地之母！几天前我跟大地之环的伙伴分开，决心揭开水元素之魂躁动的秘密。我一路探寻，发现库斯卡的纳迦正在污染影月谷的水源。$B$B不幸的是，我不小心暴露了行踪，被关了起来。不知道这帮家伙会用什么样的法子来折磨我。$B$B我们必须离开这里！护送我逃离库斯卡水池，然后到诅咒祭坛去找托洛克。',Objectives_loc4='护送大地治愈者维尔达逃离库斯卡水池，然后前往古尔丹之手以西的诅咒祭坛，向大地治愈者托洛克复命。',OfferRewardText_loc4='赞美大地之母。我确定威尔达将会找到回家的路。请收下这个以表我们的谢意。',RequestItemsText_loc4='你找到威尔达姐妹了吗?',EndText_loc4='护送大地治愈者维尔达到达安全地点';
INSERT INTO locales_quest(entry,Title_loc4) VALUES (10454,'FLAG - OFF THE RAILS') ON DUPLICATE KEY UPDATE Title_loc4='FLAG - OFF THE RAILS';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10455,'危险的荒野','我们目前正在全力进行着活木林生态环境的培育，但这里的山猫数量有些超出了控制范围。$B$B虽然林地山猫的数量曾经处于比较稳定的状态，但是现在它们已经威胁到了希尔瓦纳的生存空间，并可能导致许多令人不愉快的事情。$B$B我现在甚至怀疑拉什鸦巢的那群鸦人正是此事的幕后黑手，但现在，最迫切的问题还是来自于这些山猫本身。$B$B若是你能帮助我们解决这个问题，那可就真是太好了。','杀死12只林地山猫。','速度很快。你确定有解决到足够的量吗?$B$B很好，有其他的事情需要你帮忙，如果你愿意的话。$B','我没有说明真相？ 不论是对过路者还是希尔瓦纳本身，林地山猫都已经成为一个威胁。$B$BTheir deaths are regrettable, but the whole point of our creation of the Living Grove is so that Sylvanaar can be surrounded by a defensive region of natural beauty and tranquility.') ON DUPLICATE KEY UPDATE Title_loc4='危险的荒野',Details_loc4='我们目前正在全力进行着活木林生态环境的培育，但这里的山猫数量有些超出了控制范围。$B$B虽然林地山猫的数量曾经处于比较稳定的状态，但是现在它们已经威胁到了希尔瓦纳的生存空间，并可能导致许多令人不愉快的事情。$B$B我现在甚至怀疑拉什鸦巢的那群鸦人正是此事的幕后黑手，但现在，最迫切的问题还是来自于这些山猫本身。$B$B若是你能帮助我们解决这个问题，那可就真是太好了。',Objectives_loc4='杀死12只林地山猫。',OfferRewardText_loc4='速度很快。你确定有解决到足够的量吗?$B$B很好，有其他的事情需要你帮忙，如果你愿意的话。$B',RequestItemsText_loc4='我没有说明真相？ 不论是对过路者还是希尔瓦纳本身，林地山猫都已经成为一个威胁。$B$BTheir deaths are regrettable, but the whole point of our creation of the Living Grove is so that Sylvanaar can be surrounded by a defensive region of natural beauty and tranquility.';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10456,'徘徊的恶狼','那些肮脏污秽的部落在东边创建了一处定居点。他们还带了一大群恐狼来，估计要用来看家或是当作座骑。$B$B这些野兽经常冲过桥来劫掠和骚扰我们的营地。它们甚至捕食了我们的许多精灵龙，这已经严重影响了活木林内所有植物的授粉，影响到了它们的生长和繁殖。$B$B你立刻从这里东侧出镇，越过血槌峡谷上的桥，到东边的锯齿山去猎杀那里的狼群，记得将它们的尾巴砍下来作为证据！','收集4条雷神恶狼的尾巴。','很好。我会看看是不是可以将这些尾巴做成什么有用的东西。$B$B无庸置疑的这些部落会找方法补足他们的狼群数量，不过现在我们可以透口气了。$B$B$N，如果你愿意的话我有其它的事要要求你保护希尔瓦纳及生命之林。','我无法充分的强调杀掉那些雷霆王恐狼的必要性。他们的存在危及到生命之林的稳定以及我们在这的工作。') ON DUPLICATE KEY UPDATE Title_loc4='徘徊的恶狼',Details_loc4='那些肮脏污秽的部落在东边创建了一处定居点。他们还带了一大群恐狼来，估计要用来看家或是当作座骑。$B$B这些野兽经常冲过桥来劫掠和骚扰我们的营地。它们甚至捕食了我们的许多精灵龙，这已经严重影响了活木林内所有植物的授粉，影响到了它们的生长和繁殖。$B$B你立刻从这里东侧出镇，越过血槌峡谷上的桥，到东边的锯齿山去猎杀那里的狼群，记得将它们的尾巴砍下来作为证据！',Objectives_loc4='收集4条雷神恶狼的尾巴。',OfferRewardText_loc4='很好。我会看看是不是可以将这些尾巴做成什么有用的东西。$B$B无庸置疑的这些部落会找方法补足他们的狼群数量，不过现在我们可以透口气了。$B$B$N，如果你愿意的话我有其它的事要要求你保护希尔瓦纳及生命之林。',RequestItemsText_loc4='我无法充分的强调杀掉那些雷霆王恐狼的必要性。他们的存在危及到生命之林的稳定以及我们在这的工作。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4) VALUES (10457,'自我保护','尽管你已经为防卫活木林做出了许多卓越的贡献，但我还是觉得这处新的家园需要更多的保护。$B$B拜托你，带上这棵已被我灌注入自然之力的小树苗。只要在那些被我埋下了种子的地方使用它，它就会令种子迅速成长，破土而出，成为强大的树人卫士。$B$B这些树人卫士对于林地的防御体系来说相当重要，既然你选择了希尔瓦纳作为长期的住所，想必你也会很重视这套防御体系。','在5处活木林树苗上使用莉娜的树枝，召唤生物保卫活木林。','现在你已经加强了树林里的防御，我觉得安全多了。$B$B你已经赢得我们对你的赞赏与感恩之心$B$B当然，这刚好提醒我还有其他的事需要去关切!$B','How fares the bolstering of the Living Grove''s defenses?$B$BWith the intentions of the arakkoa at Veil Lessh unknown, and the Horde just on the other side of the ravine, I fear that if we do not move quickly we will find ourselves in a poor situation to protect our new home and our work in the grove.','召唤活木林防御者') ON DUPLICATE KEY UPDATE Title_loc4='自我保护',Details_loc4='尽管你已经为防卫活木林做出了许多卓越的贡献，但我还是觉得这处新的家园需要更多的保护。$B$B拜托你，带上这棵已被我灌注入自然之力的小树苗。只要在那些被我埋下了种子的地方使用它，它就会令种子迅速成长，破土而出，成为强大的树人卫士。$B$B这些树人卫士对于林地的防御体系来说相当重要，既然你选择了希尔瓦纳作为长期的住所，想必你也会很重视这套防御体系。',Objectives_loc4='在5处活木林树苗上使用莉娜的树枝，召唤生物保卫活木林。',OfferRewardText_loc4='现在你已经加强了树林里的防御，我觉得安全多了。$B$B你已经赢得我们对你的赞赏与感恩之心$B$B当然，这刚好提醒我还有其他的事需要去关切!$B',RequestItemsText_loc4='How fares the bolstering of the Living Grove''s defenses?$B$BWith the intentions of the arakkoa at Veil Lessh unknown, and the Horde just on the other side of the ravine, I fear that if we do not move quickly we will find ourselves in a poor situation to protect our new home and our work in the grove.',ObjectiveText1_loc4='召唤活木林防御者';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4,ObjectiveText2_loc4) VALUES (10458,'愤怒的火灵和地灵','我们必须设法挽救现在的局面。跟这片区域的元素沟通，看看有什么补救措施！$B$B$r，我将灵魂图腾交给你。如果你在图腾附近杀死暴怒的元素之灵，灵魂图腾将吸收它们的灵魂。使用图腾吸收元素生物的灵魂，然后向我复命。$B$B首先对付火之灵和土之灵吧，将装满土之魂和火之魂的灵魂图腾交给我。','使用灵魂图腾俘获8个土之魂和8个火之魂，然后向影月谷诅咒祭坛的大地治愈者托洛克复命。','当这个区域的所有元素之灵被放置到这个图腾里时，我们会与他们交流并找出是否能为影月谷做得事。','我担心这个大陆可能失去希望了。','捕获土之魂','捕获火之魂') ON DUPLICATE KEY UPDATE Title_loc4='愤怒的火灵和地灵',Details_loc4='我们必须设法挽救现在的局面。跟这片区域的元素沟通，看看有什么补救措施！$B$B$r，我将灵魂图腾交给你。如果你在图腾附近杀死暴怒的元素之灵，灵魂图腾将吸收它们的灵魂。使用图腾吸收元素生物的灵魂，然后向我复命。$B$B首先对付火之灵和土之灵吧，将装满土之魂和火之魂的灵魂图腾交给我。',Objectives_loc4='使用灵魂图腾俘获8个土之魂和8个火之魂，然后向影月谷诅咒祭坛的大地治愈者托洛克复命。',OfferRewardText_loc4='当这个区域的所有元素之灵被放置到这个图腾里时，我们会与他们交流并找出是否能为影月谷做得事。',RequestItemsText_loc4='我担心这个大陆可能失去希望了。',ObjectiveText1_loc4='捕获土之魂',ObjectiveText2_loc4='捕获火之魂';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10459,'塞纳里奥远征队的崇敬','$N，你取得的成就，我们有目共睹。你所做的完全超出我们的预想。$B$B我有一项特殊的请求，但是在那之前，我必须考验你对塞纳里奥远征队的忠心。','塞纳里奥庇护所的伊谢尔·风歌要求你在塞纳里奥远征队中达到崇敬声望。','你已经向塞纳里奥远征队证明你自己了，$N。你在这场与我们敌人的战争中不只是个受到信任的朋友，还是个珍贵的盟友。','你完成我要求你的任务了吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='塞纳里奥远征队的崇敬',Details_loc4='$N，你取得的成就，我们有目共睹。你所做的完全超出我们的预想。$B$B我有一项特殊的请求，但是在那之前，我必须考验你对塞纳里奥远征队的忠心。',Objectives_loc4='塞纳里奥庇护所的伊谢尔·风歌要求你在塞纳里奥远征队中达到崇敬声望。',OfferRewardText_loc4='你已经向塞纳里奥远征队证明你自己了，$N。你在这场与我们敌人的战争中不只是个受到信任的朋友，还是个珍贵的盟友。',RequestItemsText_loc4='你完成我要求你的任务了吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4) VALUES (10460,'防御者的契约','你确定这是你想要进行的道路吗，$N?这不是个你该随意取决的决定。$B$B这个戒指灌注了永恒之井中的一小滴。当你向流沙之鳞证明自己时它也会变得更加强大。') ON DUPLICATE KEY UPDATE Title_loc4='防御者的契约',OfferRewardText_loc4='你确定这是你想要进行的道路吗，$N?这不是个你该随意取决的决定。$B$B这个戒指灌注了永恒之井中的一小滴。当你向流沙之鳞证明自己时它也会变得更加强大。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4) VALUES (10461,'治愈者的契约','你确定这是你所想要踏上的道路吗，$N?这可不该是个轻率的决定。$B$B这个戒指灌注了一小滴永恒之井井水。当你向流沙之鳞证明自己时，它也会随之变得更为强大。') ON DUPLICATE KEY UPDATE Title_loc4='治愈者的契约',OfferRewardText_loc4='你确定这是你所想要踏上的道路吗，$N?这可不该是个轻率的决定。$B$B这个戒指灌注了一小滴永恒之井井水。当你向流沙之鳞证明自己时，它也会随之变得更为强大。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4) VALUES (10462,'勇士的契约','你确定这是你所想要踏上的道路吗，$N?这可不该是个轻率的决定。$B$B这个戒指灌注了一小滴永恒之井井水。当你向流沙之鳞证明自己时，它也会随之变得更为强大。') ON DUPLICATE KEY UPDATE Title_loc4='勇士的契约',OfferRewardText_loc4='你确定这是你所想要踏上的道路吗，$N?这可不该是个轻率的决定。$B$B这个戒指灌注了一小滴永恒之井井水。当你向流沙之鳞证明自己时，它也会随之变得更为强大。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4) VALUES (10463,'先知的契约','你确定这是你所想要踏上的道路吗，$N?这可不该是个轻率的决定。$B$B这个戒指灌注了一小滴永恒之井井水。当你向流沙之鳞证明自己时，它也会随之变得更为强大。') ON DUPLICATE KEY UPDATE Title_loc4='先知的契约',OfferRewardText_loc4='你确定这是你所想要踏上的道路吗，$N?这可不该是个轻率的决定。$B$B这个戒指灌注了一小滴永恒之井井水。当你向流沙之鳞证明自己时，它也会随之变得更为强大。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10464,'先知的誓约','$c，你既然做出了承诺，就要实现自己的诺言。$B$B为流沙之鳞效力，你就会获得应得的奖励。如果你失败的话，历史的进程将被破坏！','当你在流沙之鳞中的声望达到尊敬后，将永恒之戒交给时空之穴的索莉多米。','你已经证明了你的价值，$r。至少，提升到某个阶段了。$B$B诺兹多姆的最佳伙伴这个荣耀可是没那么高速缓冲得的。','你一直对我们很有贡献，$N。') ON DUPLICATE KEY UPDATE Title_loc4='先知的誓约',Details_loc4='$c，你既然做出了承诺，就要实现自己的诺言。$B$B为流沙之鳞效力，你就会获得应得的奖励。如果你失败的话，历史的进程将被破坏！',Objectives_loc4='当你在流沙之鳞中的声望达到尊敬后，将永恒之戒交给时空之穴的索莉多米。',OfferRewardText_loc4='你已经证明了你的价值，$r。至少，提升到某个阶段了。$B$B诺兹多姆的最佳伙伴这个荣耀可是没那么高速缓冲得的。',RequestItemsText_loc4='你一直对我们很有贡献，$N。';
