INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10476,'强悍的敌人','想要证明你对我们的忠诚，就勇敢地与我们的敌人作战吧。$B$B残忍野蛮的食人魔是塔拉最大的威胁。因此，如果你想证明自己的实力，就把他们脖子上的作战念珠带回来给我。我会将你的功绩告诉氏族其它成员的。','塔拉的监护者莫布吉尔要你从纳格兰的食人魔身上收集10串黑曜石作战念珠。','你开始证实你身为一位盟友及战士的价值了。继续保持下去吧。','那么，$N?你是只要跟我谈一谈还是有什么东西要给我看一看?') ON DUPLICATE KEY UPDATE Title_loc4='强悍的敌人',Details_loc4='想要证明你对我们的忠诚，就勇敢地与我们的敌人作战吧。$B$B残忍野蛮的食人魔是塔拉最大的威胁。因此，如果你想证明自己的实力，就把他们脖子上的作战念珠带回来给我。我会将你的功绩告诉氏族其它成员的。',Objectives_loc4='塔拉的监护者莫布吉尔要你从纳格兰的食人魔身上收集10串黑曜石作战念珠。',OfferRewardText_loc4='你开始证实你身为一位盟友及战士的价值了。继续保持下去吧。',RequestItemsText_loc4='那么，$N?你是只要跟我谈一谈还是有什么东西要给我看一看?';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10477,'更多作战念珠','你继续对我们证明你的价值吧，$N。愿你的力量永不遗弃你。','你还有其它的黑曜石战争串珠吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='更多作战念珠',OfferRewardText_loc4='你继续对我们证明你的价值吧，$N。愿你的力量永不遗弃你。',RequestItemsText_loc4='你还有其它的黑曜石战争串珠吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10478,'更多作战念珠！','你继续证明你的力量及荣耀吧，$N。','你有更多的战争串珠吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='更多作战念珠！',OfferRewardText_loc4='你继续证明你的力量及荣耀吧，$N。',RequestItemsText_loc4='你有更多的战争串珠吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10479,'证明你的力量','平静的生活谁不向往？可是我们不得不面对许多敌对势力的挑战。残忍野蛮的食人魔是加拉达尔最大的威胁。$B$B如果你想证明自己的实力，就把他们脖子上的作战念珠带回来给我。我会将你取得的成就告诉氏族其它成员的。','加拉达尔的监护者布罗克要你从纳格兰的食人魔身上收集10串黑曜石作战念珠。','你的确是个强大的盟友，$N。前去对抗这些外域的巨魔可不是每个人都可以做得事。','你有东西要给我看吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='证明你的力量',Details_loc4='平静的生活谁不向往？可是我们不得不面对许多敌对势力的挑战。残忍野蛮的食人魔是加拉达尔最大的威胁。$B$B如果你想证明自己的实力，就把他们脖子上的作战念珠带回来给我。我会将你取得的成就告诉氏族其它成员的。',Objectives_loc4='加拉达尔的监护者布罗克要你从纳格兰的食人魔身上收集10串黑曜石作战念珠。',OfferRewardText_loc4='你的确是个强大的盟友，$N。前去对抗这些外域的巨魔可不是每个人都可以做得事。',RequestItemsText_loc4='你有东西要给我看吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4) VALUES (10480,'愤怒的水灵','这个地区的纳迦控制着影月谷唯一干净的水源。$B$B此地正北方便是纳迦的老巢库斯卡。那里周围分布着许多小水洼，水面剧烈地翻腾着，仿佛在对大地发出阵阵痛苦的哀嚎。暴怒的水灵就在水洼附近游荡。$B$B前往库斯卡，使用灵魂图腾俘获水之魂。那些水灵大多聚集在库斯卡水池。','使用灵魂图腾俘获5个水之魂，然后向影月谷诅咒祭坛的大地治愈者托洛克复命。','只剩下空气了，$N。','你在找到纳迦的地方就差不多可以找到那些受折磨的水之灵。','捕获水之魂') ON DUPLICATE KEY UPDATE Title_loc4='愤怒的水灵',Details_loc4='这个地区的纳迦控制着影月谷唯一干净的水源。$B$B此地正北方便是纳迦的老巢库斯卡。那里周围分布着许多小水洼，水面剧烈地翻腾着，仿佛在对大地发出阵阵痛苦的哀嚎。暴怒的水灵就在水洼附近游荡。$B$B前往库斯卡，使用灵魂图腾俘获水之魂。那些水灵大多聚集在库斯卡水池。',Objectives_loc4='使用灵魂图腾俘获5个水之魂，然后向影月谷诅咒祭坛的大地治愈者托洛克复命。',OfferRewardText_loc4='只剩下空气了，$N。',RequestItemsText_loc4='你在找到纳迦的地方就差不多可以找到那些受折磨的水之灵。',ObjectiveText1_loc4='捕获水之魂';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4) VALUES (10481,'愤怒的气灵','英雄，往东南方前进吧。当你看见大片破土而出的巨型蓝色水晶时，就说明你的目的地灵翼平原到了。暴怒的空气之灵在平原四周的悬崖和山岭附近游荡。$B$B杀死这些被折磨的元素生物，使用灵魂图腾俘获气之魂。完成任务后回来向我复命。','使用灵魂图腾俘获10个气之魂，然后向影月谷诅咒祭坛的大地治愈者托洛克复命。','让我为你克服如此艰巨的任务而奖励你，英雄。$B$B现在，我们必须进行我们的工作!请站后面一点，这样我才可以将图腾放在这并释放这些灵魂。','很快的，我会将可与灵魂对话。','捕获气之魂') ON DUPLICATE KEY UPDATE Title_loc4='愤怒的气灵',Details_loc4='英雄，往东南方前进吧。当你看见大片破土而出的巨型蓝色水晶时，就说明你的目的地灵翼平原到了。暴怒的空气之灵在平原四周的悬崖和山岭附近游荡。$B$B杀死这些被折磨的元素生物，使用灵魂图腾俘获气之魂。完成任务后回来向我复命。',Objectives_loc4='使用灵魂图腾俘获10个气之魂，然后向影月谷诅咒祭坛的大地治愈者托洛克复命。',OfferRewardText_loc4='让我为你克服如此艰巨的任务而奖励你，英雄。$B$B现在，我们必须进行我们的工作!请站后面一点，这样我才可以将图腾放在这并释放这些灵魂。',RequestItemsText_loc4='很快的，我会将可与灵魂对话。',ObjectiveText1_loc4='捕获气之魂';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10482,'邪兽人清理者','噬骨清理者躲藏在荒废的城垛上，窥视着荣耀之路的动向。我们相信，这帮邪兽人正在替地狱火堡垒中的主子收集战争机器的组件——必须阻止他们！$B$B$N，荣耀堡北边聚集了大批噬骨兽人。去杀死他们！但是不可掉以轻心，虽然噬骨兽人是邪兽人氏族中不起眼的一支，但是他们的力量跟那些绿皮兽人不相上下……','杀死20个噬骨兽人，然后向荣耀堡的阿曼蒂复命。','做得好。我相信地狱火堡垒会感觉到他们的损失。虽然那个黑暗堡垒逼近我们，看起来好像不能克服，但只有你们果敢行事我们才能战胜邪兽人!','噬骨者大量出现，$N。杀了他们否则邪兽人会侵扰我们!') ON DUPLICATE KEY UPDATE Title_loc4='邪兽人清理者',Details_loc4='噬骨清理者躲藏在荒废的城垛上，窥视着荣耀之路的动向。我们相信，这帮邪兽人正在替地狱火堡垒中的主子收集战争机器的组件——必须阻止他们！$B$B$N，荣耀堡北边聚集了大批噬骨兽人。去杀死他们！但是不可掉以轻心，虽然噬骨兽人是邪兽人氏族中不起眼的一支，但是他们的力量跟那些绿皮兽人不相上下……',Objectives_loc4='杀死20个噬骨兽人，然后向荣耀堡的阿曼蒂复命。',OfferRewardText_loc4='做得好。我相信地狱火堡垒会感觉到他们的损失。虽然那个黑暗堡垒逼近我们，看起来好像不能克服，但只有你们果敢行事我们才能战胜邪兽人!',RequestItemsText_loc4='噬骨者大量出现，$N。杀了他们否则邪兽人会侵扰我们!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10483,'邪恶的咒语','$N，在与血环邪兽人交战时，我们发现他们身上佩戴着某种不祥的饰物。那些邪兽人从荣耀堡士兵的尸体上取下徽章，制作成被诅咒的护符。我们担心血环兽人利用黑暗魔法将我们的徽章变成了咒符，还用来对付我们！$B$B前往荣耀堡以东的塞斯高，从血环兽人手中夺得一枚被诅咒的护符，然后将它交给塞斯高东北方远征军岗哨的埃隆雷下士。','荣耀堡的阿曼蒂中尉要你前往远征军岗哨，将1枚被诅咒的护符交给埃隆雷下士。','啊，你从血之谷兽人那里取回一个徽记了?很好 - 他们使用我们自己的象征来对抗我们，嘲笑我们阵亡在红皮肤野兽手下的同伴真是滔天大罪!','从荣耀堡回报，$N?很好 - 我们对抗恶魔和邪兽人的战役已越来越缺少健全的人手了!') ON DUPLICATE KEY UPDATE Title_loc4='邪恶的咒语',Details_loc4='$N，在与血环邪兽人交战时，我们发现他们身上佩戴着某种不祥的饰物。那些邪兽人从荣耀堡士兵的尸体上取下徽章，制作成被诅咒的护符。我们担心血环兽人利用黑暗魔法将我们的徽章变成了咒符，还用来对付我们！$B$B前往荣耀堡以东的塞斯高，从血环兽人手中夺得一枚被诅咒的护符，然后将它交给塞斯高东北方远征军岗哨的埃隆雷下士。',Objectives_loc4='荣耀堡的阿曼蒂中尉要你前往远征军岗哨，将1枚被诅咒的护符交给埃隆雷下士。',OfferRewardText_loc4='啊，你从血之谷兽人那里取回一个徽记了?很好 - 他们使用我们自己的象征来对抗我们，嘲笑我们阵亡在红皮肤野兽手下的同伴真是滔天大罪!',RequestItemsText_loc4='从荣耀堡回报，$N?很好 - 我们对抗恶魔和邪兽人的战役已越来越缺少健全的人手了!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10484,'被诅咒的护符','$N，我们绝对不能让血环兽人继续利用被诅咒的护符！你必须替我们夺回护符，让那些牺牲的荣耀堡士兵们得到应有的尊重。$B$B前往血环兽人被诅咒的据点塞斯高，执行这项艰巨的任务……集齐护符后返回荣耀堡向我复命。','将12枚被诅咒的护符交给远征军岗哨的埃隆雷下士。','谢谢你，$N。看到这些护符我的心真痛 -','你弄到护符了吗，$N?知道那些被诅咒的兽人拥有我们士兵的徽记真令我心痛……') ON DUPLICATE KEY UPDATE Title_loc4='被诅咒的护符',Details_loc4='$N，我们绝对不能让血环兽人继续利用被诅咒的护符！你必须替我们夺回护符，让那些牺牲的荣耀堡士兵们得到应有的尊重。$B$B前往血环兽人被诅咒的据点塞斯高，执行这项艰巨的任务……集齐护符后返回荣耀堡向我复命。',Objectives_loc4='将12枚被诅咒的护符交给远征军岗哨的埃隆雷下士。',OfferRewardText_loc4='谢谢你，$N。看到这些护符我的心真痛 -',RequestItemsText_loc4='你弄到护符了吗，$N?知道那些被诅咒的兽人拥有我们士兵的徽记真令我心痛……';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10485,'血环督军','你能够幸运地从塞斯高安然返回，足以证明你具备优秀的作战能力！现在，我有一项艰巨的任务要交给你，希望这次好运气还能伴随你……$B$B督军摩尔肯坐镇于塞斯高的兵营，指挥着他的邪兽人军团与我们作战。他的战术灵活而残忍，我必须承认，他重挫了我军的士气。因此，$N，我命令你除掉摩尔肯。将他的护甲带回来，我要将它放在这儿示众，鼓舞军中的将士。','把督军摩尔肯的破碎护甲交给远征军岗哨的埃隆雷下士。','你办到了!莫克被杀了!现在，我们对抗那些邪兽人野兽有望了!$B$B谢谢你，$N。你对这里的战事支持难以估计。','莫克的破碎胸甲在哪?你再次勇闯萨斯葛尔了吗?') ON DUPLICATE KEY UPDATE Title_loc4='血环督军',Details_loc4='你能够幸运地从塞斯高安然返回，足以证明你具备优秀的作战能力！现在，我有一项艰巨的任务要交给你，希望这次好运气还能伴随你……$B$B督军摩尔肯坐镇于塞斯高的兵营，指挥着他的邪兽人军团与我们作战。他的战术灵活而残忍，我必须承认，他重挫了我军的士气。因此，$N，我命令你除掉摩尔肯。将他的护甲带回来，我要将它放在这儿示众，鼓舞军中的将士。',Objectives_loc4='把督军摩尔肯的破碎护甲交给远征军岗哨的埃隆雷下士。',OfferRewardText_loc4='你办到了!莫克被杀了!现在，我们对抗那些邪兽人野兽有望了!$B$B谢谢你，$N。你对这里的战事支持难以估计。',RequestItemsText_loc4='莫克的破碎胸甲在哪?你再次勇闯萨斯葛尔了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10486,'荒野的危险','在饮下玛诺洛斯之血转变成邪兽人之前，雷神氏族曾是高贵的兽人氏族。$B$B在雷神氏族舍弃这座要塞后，食人魔便在此创建了据点，不过最近我们刚从食人魔手中收复了雷神要塞。$B$B我们决定守护这座要塞，希望你能伸出援手。$B$B要塞以南和以西的锯齿山中聚集着大量刃翼放血者，它们的繁殖速度极快，已经对要塞的安全构成了严重威胁。$B$B杀死刃翼放血者，然后回来向我复命。','杀死12个刃翼放血者。','比我本来想得还要快。你确定你有解决足够的数量吗?$B$B很好，还有一件事我要你帮忙的。一件更重要的事。$B','Our survival here depends upon our ability to concentrate our efforts against those that truly matter, not the mere bladewing bloodletters.$B$BYou are here again, so this must mean that you have dealt with the matter at hand?') ON DUPLICATE KEY UPDATE Title_loc4='荒野的危险',Details_loc4='在饮下玛诺洛斯之血转变成邪兽人之前，雷神氏族曾是高贵的兽人氏族。$B$B在雷神氏族舍弃这座要塞后，食人魔便在此创建了据点，不过最近我们刚从食人魔手中收复了雷神要塞。$B$B我们决定守护这座要塞，希望你能伸出援手。$B$B要塞以南和以西的锯齿山中聚集着大量刃翼放血者，它们的繁殖速度极快，已经对要塞的安全构成了严重威胁。$B$B杀死刃翼放血者，然后回来向我复命。',Objectives_loc4='杀死12个刃翼放血者。',OfferRewardText_loc4='比我本来想得还要快。你确定你有解决足够的数量吗?$B$B很好，还有一件事我要你帮忙的。一件更重要的事。$B',RequestItemsText_loc4='Our survival here depends upon our ability to concentrate our efforts against those that truly matter, not the mere bladewing bloodletters.$B$BYou are here again, so this must mean that you have dealt with the matter at hand?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10487,'仙龙之尘','暗夜精灵利用精灵一族的魔法，在雷神要塞西边安营扎寨，并迅速发展成一片林地。我们必须削弱他们的防御力量，防止联盟进一步扩大势力范围。$B$B我有一项绝妙的作战计划。我要你沿着西南方的石桥跨越血槌峡谷，前往活木林。$B$B杀掉活木林中的仙龙，削弱暗夜精灵的防御力量。记得将仙龙翅膀上的魔法尘带回来给我。','收集4份仙龙之尘。','不只有你去削弱他们的防御，我们也将使用这个粉尘来坚固我们本身对抗联盟的防守。','看来联盟似乎决定一路跟着我们不管到哪。让我们教教他们这样子没办法吓倒我们。$B$B你有带来我要的东西来吗?') ON DUPLICATE KEY UPDATE Title_loc4='仙龙之尘',Details_loc4='暗夜精灵利用精灵一族的魔法，在雷神要塞西边安营扎寨，并迅速发展成一片林地。我们必须削弱他们的防御力量，防止联盟进一步扩大势力范围。$B$B我有一项绝妙的作战计划。我要你沿着西南方的石桥跨越血槌峡谷，前往活木林。$B$B杀掉活木林中的仙龙，削弱暗夜精灵的防御力量。记得将仙龙翅膀上的魔法尘带回来给我。',Objectives_loc4='收集4份仙龙之尘。',OfferRewardText_loc4='不只有你去削弱他们的防御，我们也将使用这个粉尘来坚固我们本身对抗联盟的防守。',RequestItemsText_loc4='看来联盟似乎决定一路跟着我们不管到哪。让我们教教他们这样子没办法吓倒我们。$B$B你有带来我要的东西来吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4) VALUES (10488,'自卫','我利用你取回的魔法尘配制了一种药膏，可用于强化我们的防御力量。$B$B雷神恶狼是雷神氏族驯养的坐骑，它们还承担着重要的警戒工作，是氏族忠诚的伙伴；但是那帮卑鄙的联盟居然在锯齿山大肆捕杀雷神恶狼。$B$B$N，让雷神恶狼服下这种药膏，联盟猎手们下次再来捕杀雷神恶狼时就有苦头吃了。$B$B雷神恶狼可能不喜欢这种药膏的怪味儿，当心它们攻击你。','对5匹雷神恶狼使用高德雷克的药膏。','现在你已经强化了这些狼匹，和锯齿山脊当地的防御，也许我们能够重新将注意力放在更要命的事情上，像是巨魔啦?
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10489,'追杀战争古树','悬赏！$B$B深根古树，他是一棵战争古树，同时也是希尔瓦纳南部的活木林防御者的首领。$B$B沿着西边的石桥跨越血槌峡谷，寻找他的踪迹。$B$B将深根古树的树干交给雷神要塞旅店中的托查克·双爪。','取得深根古树的树干。','斯卓霖普.深根的大箱!你是靠自己击倒他的吗?$B$B我赌你一定是。你知道的，我们正在寻找一个年轻力壮的$C，就像你这样的人来帮助这里，特别是一直以来我们与巨魔之间存在的问题。确信你大有可能继续跟我合作。$B$B唉呀这个大箱很明显的就是证明，表示你来这里是要领取奖励而不是听我讲话的。来吧，选一个东西吧。','你拿的那个是什么?你真是个勇敢的家伙!') ON DUPLICATE KEY UPDATE Title_loc4='追杀战争古树',Details_loc4='悬赏！$B$B深根古树，他是一棵战争古树，同时也是希尔瓦纳南部的活木林防御者的首领。$B$B沿着西边的石桥跨越血槌峡谷，寻找他的踪迹。$B$B将深根古树的树干交给雷神要塞旅店中的托查克·双爪。',Objectives_loc4='取得深根古树的树干。',OfferRewardText_loc4='斯卓霖普.深根的大箱!你是靠自己击倒他的吗?$B$B我赌你一定是。你知道的，我们正在寻找一个年轻力壮的$C，就像你这样的人来帮助这里，特别是一直以来我们与巨魔之间存在的问题。确信你大有可能继续跟我合作。$B$B唉呀这个大箱很明显的就是证明，表示你来这里是要领取奖励而不是听我讲话的。来吧，选一个东西吧。',RequestItemsText_loc4='你拿的那个是什么?你真是个勇敢的家伙!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10490,'水之召唤','自你上一次接受考验之后已经过去一段时间了。预言者努波顿想让你去见他。$B$B你的智慧在过去的这段时间里是否有长足的提高？因为你被召唤的原因，是要去了解水元素的秘密。$B$B我相信你一定还记得怎样去卡利姆多大陆的黑海岸地区，乘坐奥伯丁的航船回埃索达吧？你也一定记得先知在埃索达水晶大厅的什么位置，对吧？','与埃索达水晶大厅的预言者努波顿谈一谈。','我们又再次相见了。我一直从远处看着你的发展，萨满，我很高兴。$B$B你与水元素融为一体的时刻已经到了，学习它的秘密并把你自己交给水，如此你便能依次学习掌握它。') ON DUPLICATE KEY UPDATE Title_loc4='水之召唤',Details_loc4='自你上一次接受考验之后已经过去一段时间了。预言者努波顿想让你去见他。$B$B你的智慧在过去的这段时间里是否有长足的提高？因为你被召唤的原因，是要去了解水元素的秘密。$B$B我相信你一定还记得怎样去卡利姆多大陆的黑海岸地区，乘坐奥伯丁的航船回埃索达吧？你也一定记得先知在埃索达水晶大厅的什么位置，对吧？',Objectives_loc4='与埃索达水晶大厅的预言者努波顿谈一谈。',OfferRewardText_loc4='我们又再次相见了。我一直从远处看着你的发展，萨满，我很高兴。$B$B你与水元素融为一体的时刻已经到了，学习它的秘密并把你自己交给水，如此你便能依次学习掌握它。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10491,'空气的召唤','$N， 预言者努波顿再次希望你去见他。是时候让你去了解最后一种元素——空气的奥秘了！$B$B我希望你知道，我对你目前为止所有的表现都非常满意。相信接下去你会做得更好。$B$B在卡利姆多黑海岸的奥伯丁乘船，穿过迷雾之海，到秘蓝岛的埃索达城中去，预言者就在水晶大厅里。','与埃索达水晶大厅中的预言者努波顿谈一谈。','我们终于来到这一步，四大元素中的最后一个:风。你认为你自己聪明得足以继续吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='空气的召唤',Details_loc4='$N， 预言者努波顿再次希望你去见他。是时候让你去了解最后一种元素——空气的奥秘了！$B$B我希望你知道，我对你目前为止所有的表现都非常满意。相信接下去你会做得更好。$B$B在卡利姆多黑海岸的奥伯丁乘船，穿过迷雾之海，到秘蓝岛的埃索达城中去，预言者就在水晶大厅里。',Objectives_loc4='与埃索达水晶大厅中的预言者努波顿谈一谈。',OfferRewardText_loc4='我们终于来到这一步，四大元素中的最后一个:风。你认为你自己聪明得足以继续吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10492,'热心的建议','你好，$c。我这里有一些你可能会很感兴趣的东西。$B$B它跟你们这个职业的人平常穿着的那些护甲有点类似，但质量上远远好于你们现在所拥有的。要是你能帮我一个小忙的话，我愿意拿它来从你手里换一件普通的套装组件。$B$B栖息在冬泉谷的霜刃豹和熊身上的血液有着某种我目前很需要的特性。给我带来一批样本，再把普通套装的手腕部分拿来，当然了，你还得支付一些金币。你会发现这其实是笔很划算的交易。','将15份冬泉谷血样、20枚金币以及一副元素护腕交给铁炉堡的德莉亚娜。','太棒了!那就来交易吧。要能和这件护甲搭配，还真不是件容易的事。可是我怕我马上就用不到这件了。$B$B若你还想帮我忙，我就再给你其它装备。','你把我要的东西带来了吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='热心的建议',Details_loc4='你好，$c。我这里有一些你可能会很感兴趣的东西。$B$B它跟你们这个职业的人平常穿着的那些护甲有点类似，但质量上远远好于你们现在所拥有的。要是你能帮我一个小忙的话，我愿意拿它来从你手里换一件普通的套装组件。$B$B栖息在冬泉谷的霜刃豹和熊身上的血液有着某种我目前很需要的特性。给我带来一批样本，再把普通套装的手腕部分拿来，当然了，你还得支付一些金币。你会发现这其实是笔很划算的交易。',Objectives_loc4='将15份冬泉谷血样、20枚金币以及一副元素护腕交给铁炉堡的德莉亚娜。',OfferRewardText_loc4='太棒了!那就来交易吧。要能和这件护甲搭配，还真不是件容易的事。可是我怕我马上就用不到这件了。$B$B若你还想帮我忙，我就再给你其它装备。',RequestItemsText_loc4='你把我要的东西带来了吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10493,'热心的建议','嗨，$C！从你的言行举止就能看出你是个历经沧桑、见多识广的家伙。但是我打赌你没有见过这么一件护甲。$B$B要是你能帮我一个小忙的话，我愿意拿它来从你手里换一件普通套装的手腕部分。$B$B我需要大量生活在希利苏斯地区的蝎子和蜘蛛的毒液。把毒液样本带给我，再支付一些金币，我就跟你交换。','将15份希利苏斯毒液样品、20枚金币以及一副光铸护腕交给奥格瑞玛的莫克瓦尔。','啊，是的。莫克斯一定会对这个感到非常满意。$B$B那护腕以前是大型护甲装备的一部份。如果你能再帮我忙的话，我这里还有更多可以跟你护腕搭配的装备。','你把我要的东西都带来了吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='热心的建议',Details_loc4='嗨，$C！从你的言行举止就能看出你是个历经沧桑、见多识广的家伙。但是我打赌你没有见过这么一件护甲。$B$B要是你能帮我一个小忙的话，我愿意拿它来从你手里换一件普通套装的手腕部分。$B$B我需要大量生活在希利苏斯地区的蝎子和蜘蛛的毒液。把毒液样本带给我，再支付一些金币，我就跟你交换。',Objectives_loc4='将15份希利苏斯毒液样品、20枚金币以及一副光铸护腕交给奥格瑞玛的莫克瓦尔。',OfferRewardText_loc4='啊，是的。莫克斯一定会对这个感到非常满意。$B$B那护腕以前是大型护甲装备的一部份。如果你能再帮我忙的话，我这里还有更多可以跟你护腕搭配的装备。',RequestItemsText_loc4='你把我要的东西都带来了吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10494,'小小的补偿','你做到了你所承诺的事，把穆克斯制造的装备给我带了回来，那么我也按承诺给予你一件不错的奖励。把你原先使用的腰带和手套拿来吧，我会帮你升级它们。我敢保证，新的装备会比原来的好得多。','将一条元素腰带和一副元素护手交给铁炉堡的德莉亚娜。','你已达成交易，我也会保留我的。$B$B记住，我会保留最好的部份，就等你完成任务了。','你准备好要交易了吗?') ON DUPLICATE KEY UPDATE Title_loc4='小小的补偿',Details_loc4='你做到了你所承诺的事，把穆克斯制造的装备给我带了回来，那么我也按承诺给予你一件不错的奖励。把你原先使用的腰带和手套拿来吧，我会帮你升级它们。我敢保证，新的装备会比原来的好得多。',Objectives_loc4='将一条元素腰带和一副元素护手交给铁炉堡的德莉亚娜。',OfferRewardText_loc4='你已达成交易，我也会保留我的。$B$B记住，我会保留最好的部份，就等你完成任务了。',RequestItemsText_loc4='你准备好要交易了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10495,'小小的补偿','你已经证明了自己是个非常守信誉的$r，$N。我坚信你能够帮我走出目前的困境，当然我也会根据你的表现给予你一些奖励。$B$B现在我可以帮你更换腰带和手套，如果事情进展顺利，我会继续帮你升级其它的部件。','将一条光铸腰带和一副光铸护手交给奥格瑞玛的莫克瓦尔。','我们的协议仍在。记住，这还只是个前菜而已。帮我从受诅咒的命运解除开来，我会奖励你超强大的物品。','你准备好要交换了吗?') ON DUPLICATE KEY UPDATE Title_loc4='小小的补偿',Details_loc4='你已经证明了自己是个非常守信誉的$r，$N。我坚信你能够帮我走出目前的困境，当然我也会根据你的表现给予你一些奖励。$B$B现在我可以帮你更换腰带和手套，如果事情进展顺利，我会继续帮你升级其它的部件。',Objectives_loc4='将一条光铸腰带和一副光铸护手交给奥格瑞玛的莫克瓦尔。',OfferRewardText_loc4='我们的协议仍在。记住，这还只是个前菜而已。帮我从受诅咒的命运解除开来，我会奖励你超强大的物品。',RequestItemsText_loc4='你准备好要交换了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10496,'告别安泰恩','瓦塔拉克的灵魂就封印在这枚护符里。因为贪婪，我们愚蠢地将它分成了好几部分，丝毫不了解这会为我们带来怎样残酷的诅咒。$B$B唯一解除瓦塔拉克的法术的办法，就是将这枚勋章重新组合在一起。回到德莉亚娜那里去，告诉她说，伯德雷已经是她找齐剩馀部分的最后希望了。顺便跟她提一下你应得的报酬。$B$B我只希望能从此安息。祝你好运……你会非常需要运气的！','带上一双元素长靴、一条元素护腿和一副元素护肩，回去向铁炉堡的德莉亚娜复命。','我真不敢相信我们的日子就因为这个愚蠢的勋章而绑死了!你确定安希恩有提到布德利吗?$B$B嗯，你完成了你的工作，让我们来看看你的奖励吧。','你回来了，$N。你一定要告诉我你发现的所有事情。但是首先让我们先来看看你的奖励。') ON DUPLICATE KEY UPDATE Title_loc4='告别安泰恩',Details_loc4='瓦塔拉克的灵魂就封印在这枚护符里。因为贪婪，我们愚蠢地将它分成了好几部分，丝毫不了解这会为我们带来怎样残酷的诅咒。$B$B唯一解除瓦塔拉克的法术的办法，就是将这枚勋章重新组合在一起。回到德莉亚娜那里去，告诉她说，伯德雷已经是她找齐剩馀部分的最后希望了。顺便跟她提一下你应得的报酬。$B$B我只希望能从此安息。祝你好运……你会非常需要运气的！',Objectives_loc4='带上一双元素长靴、一条元素护腿和一副元素护肩，回去向铁炉堡的德莉亚娜复命。',OfferRewardText_loc4='我真不敢相信我们的日子就因为这个愚蠢的勋章而绑死了!你确定安希恩有提到布德利吗?$B$B嗯，你完成了你的工作，让我们来看看你的奖励吧。',RequestItemsText_loc4='你回来了，$N。你一定要告诉我你发现的所有事情。但是首先让我们先来看看你的奖励。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10497,'告别安泰恩','瓦塔拉克的灵魂就封印在这枚护符里。因为贪婪，我们愚蠢地将它分成了好几部分，丝毫不了解这会为我们带来怎样残酷的诅咒。$B$B唯一解除瓦塔拉克的法术的办法，就是将这枚勋章重新组合在一起。回到莫克瓦尔那里去，告诉他说，伯德雷已经是他找齐剩馀部分的最后希望了。顺便跟他提一下你应得的报酬。$B$B我只希望能从此安息。祝你好运……你会非常需要运气的！','带上一双光铸战靴、一条光铸腿铠和一副光铸肩铠，回去向奥格瑞玛的莫克瓦尔复命。','就因为这个勋章，这个诅咒才会降临到我们身上。瓦萨拉克领主显然知道如何掌握仇恨。$B$B我们会尽力找到剩下的碎块 - 希望是在我面临最终的死期之前。不过在那之前，让我们先来看看你的奖励。','你回来了，我从你的眼睛里看出来你有很多话想跟我讲，$N。让我们先处理好你的奖励。') ON DUPLICATE KEY UPDATE Title_loc4='告别安泰恩',Details_loc4='瓦塔拉克的灵魂就封印在这枚护符里。因为贪婪，我们愚蠢地将它分成了好几部分，丝毫不了解这会为我们带来怎样残酷的诅咒。$B$B唯一解除瓦塔拉克的法术的办法，就是将这枚勋章重新组合在一起。回到莫克瓦尔那里去，告诉他说，伯德雷已经是他找齐剩馀部分的最后希望了。顺便跟他提一下你应得的报酬。$B$B我只希望能从此安息。祝你好运……你会非常需要运气的！',Objectives_loc4='带上一双光铸战靴、一条光铸腿铠和一副光铸肩铠，回去向奥格瑞玛的莫克瓦尔复命。',OfferRewardText_loc4='就因为这个勋章，这个诅咒才会降临到我们身上。瓦萨拉克领主显然知道如何掌握仇恨。$B$B我们会尽力找到剩下的碎块 - 希望是在我面临最终的死期之前。不过在那之前，让我们先来看看你的奖励。',RequestItemsText_loc4='你回来了，我从你的眼睛里看出来你有很多话想跟我讲，$N。让我们先处理好你的奖励。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10498,'最后的奖赏','这真是个令人惊异的故事，$N！我实在是太感谢你了，其它一些与此有关的人也会对你表示真心诚意的感激。或许今天晚上我就能睡个安稳觉了。$B$B这儿还有些你绝对会很喜欢的东西，送你算作奖励吧。','将你的元素罩帽与元素外衣交给德莉亚娜。','我会想念你的，$N。我欠你很大一份人情;我想我永远也无法报答你。$B$B希望你喜欢你的新头饰和胸甲，也希望它能保护你很长一段时间。','依照我们的约定，你准备好交出你的元素装备来换取全新的五雷兜帽和外衣了吗?') ON DUPLICATE KEY UPDATE Title_loc4='最后的奖赏',Details_loc4='这真是个令人惊异的故事，$N！我实在是太感谢你了，其它一些与此有关的人也会对你表示真心诚意的感激。或许今天晚上我就能睡个安稳觉了。$B$B这儿还有些你绝对会很喜欢的东西，送你算作奖励吧。',Objectives_loc4='将你的元素罩帽与元素外衣交给德莉亚娜。',OfferRewardText_loc4='我会想念你的，$N。我欠你很大一份人情;我想我永远也无法报答你。$B$B希望你喜欢你的新头饰和胸甲，也希望它能保护你很长一段时间。',RequestItemsText_loc4='依照我们的约定，你准备好交出你的元素装备来换取全新的五雷兜帽和外衣了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10499,'最后的奖赏','确实是个令人惊异的故事，$N！我实在是太感谢你了，其它一些与此有关的人也会对你表示真心诚意的感激，这一点我向你保证。你的努力使我们终于认识到了自己过去所犯的错误。$B$B这儿还有些你绝对会很喜欢的东西，送你算作奖励吧。','将你的光铸头盔与光铸胸甲交给莫克瓦尔。','我真的会很想你，$N。我欠你一份人情，这是我永远也无法回报的。$B$B好好使用你的新头饰和胸甲。愿它能保护你很长一段时间，为你带来更多的荣耀!','你准备好用你的光铸装备和我交换全新的魂铸头盔和胸甲了吗?') ON DUPLICATE KEY UPDATE Title_loc4='最后的奖赏',Details_loc4='确实是个令人惊异的故事，$N！我实在是太感谢你了，其它一些与此有关的人也会对你表示真心诚意的感激，这一点我向你保证。你的努力使我们终于认识到了自己过去所犯的错误。$B$B这儿还有些你绝对会很喜欢的东西，送你算作奖励吧。',Objectives_loc4='将你的光铸头盔与光铸胸甲交给莫克瓦尔。',OfferRewardText_loc4='我真的会很想你，$N。我欠你一份人情，这是我永远也无法回报的。$B$B好好使用你的新头饰和胸甲。愿它能保护你很长一段时间，为你带来更多的荣耀!',RequestItemsText_loc4='你准备好用你的光铸装备和我交换全新的魂铸头盔和胸甲了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10500,'部落需要你的帮助！','你好，我很高兴你愿意听我说话。部落需要一切可以获得的帮助来准备发动安其拉战争，这意味着，我们需要你！现在，官方的资源收集者正在收集必需的资源储备，但是如果没有你的帮助的话，我们是无法达成目标的，$N！$B$B你应该和负责此事的督军格尔库克谈一谈。你觉得怎么样？你是否愿意帮助部落做好战争的准备？','和奥格瑞玛精神谷的督军格尔库克谈一谈。','(兽人语)你好，$C!很高兴看到这么多像你$N一样的部落成员，伸出援手为安其拉之战打好基础。这样的努力一定会让我们胜过异种和他们藏在安其拉里面的邪恶主人。$B$B既然你在这里，记得去和不同的收集者谈谈并提供你的协助，收集你能取得的材料。','你和督军格尔库克交谈了吗 ，$C?') ON DUPLICATE KEY UPDATE Title_loc4='部落需要你的帮助！',Details_loc4='你好，我很高兴你愿意听我说话。部落需要一切可以获得的帮助来准备发动安其拉战争，这意味着，我们需要你！现在，官方的资源收集者正在收集必需的资源储备，但是如果没有你的帮助的话，我们是无法达成目标的，$N！$B$B你应该和负责此事的督军格尔库克谈一谈。你觉得怎么样？你是否愿意帮助部落做好战争的准备？',Objectives_loc4='和奥格瑞玛精神谷的督军格尔库克谈一谈。',OfferRewardText_loc4='(兽人语)你好，$C!很高兴看到这么多像你$N一样的部落成员，伸出援手为安其拉之战打好基础。这样的努力一定会让我们胜过异种和他们藏在安其拉里面的邪恶主人。$B$B既然你在这里，记得去和不同的收集者谈谈并提供你的协助，收集你能取得的材料。',RequestItemsText_loc4='你和督军格尔库克交谈了吗 ，$C?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10501,'联盟需要你的帮助！','你好，我很高兴你愿意听我说话。联盟需要一切可以获得的帮助来准备发动安其拉战争，这意味着，我们需要你！现在，官方的资源收集者正在收集必需的资源储备，但是如果没有你的帮助的话，我们是无法达成目标的，$N！$B$B你应该和负责此事的大元帅斯诺·落雪谈一谈。你觉得怎么样？你是否愿意帮助联盟做好战争的准备？','和铁炉堡军事区的大元帅斯诺·落雪谈一谈。','嗨','你和战场元帅斯诺.落雪交谈了吗，$C?') ON DUPLICATE KEY UPDATE Title_loc4='联盟需要你的帮助！',Details_loc4='你好，我很高兴你愿意听我说话。联盟需要一切可以获得的帮助来准备发动安其拉战争，这意味着，我们需要你！现在，官方的资源收集者正在收集必需的资源储备，但是如果没有你的帮助的话，我们是无法达成目标的，$N！$B$B你应该和负责此事的大元帅斯诺·落雪谈一谈。你觉得怎么样？你是否愿意帮助联盟做好战争的准备？',Objectives_loc4='和铁炉堡军事区的大元帅斯诺·落雪谈一谈。',OfferRewardText_loc4='嗨',RequestItemsText_loc4='你和战场元帅斯诺.落雪交谈了吗，$C?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4) VALUES (10502,'血槌食人魔','比起部落的雷神要塞，另一群势力对希尔瓦纳具备着更致命的威胁。$B$B我说的正是栖息在群山之中的食人魔原住民。血槌氏族居住在峡谷内的东方和南方，他们的确不是唯一一群威胁着我们的食人魔，但他们却是最近的。$B$B你要立刻向南，穿越活木林，然后沿路向东走入谷地，进入他们的哨站。之后，就请在血槌哨站消灭尽量多的食人魔吧。','消灭血槌哨站的任意30个血槌食人魔。','对于守护希尔瓦纳及林地踏出了成功的第一步。$B$B因为巨魔的人数不再这么众多，血槌就会好好思考有关攻击我们的事。$B$B现在，但愿他们是唯一我们需要担心的巨魔氏族。$B','我们的斥候回报这些刀塔食人魔已经在更接近山路的地方创建了一个营地，就是从他们的堡垒到我们这里的那条路。$B$B很不幸的我们无法苟同就这样屈服于这些巨魔垃圾底下，但如果他们想要开战，他们会发现部落不只适应力好而已。','杀死血槌食人魔') ON DUPLICATE KEY UPDATE Title_loc4='血槌食人魔',Details_loc4='比起部落的雷神要塞，另一群势力对希尔瓦纳具备着更致命的威胁。$B$B我说的正是栖息在群山之中的食人魔原住民。血槌氏族居住在峡谷内的东方和南方，他们的确不是唯一一群威胁着我们的食人魔，但他们却是最近的。$B$B你要立刻向南，穿越活木林，然后沿路向东走入谷地，进入他们的哨站。之后，就请在血槌哨站消灭尽量多的食人魔吧。',Objectives_loc4='消灭血槌哨站的任意30个血槌食人魔。',OfferRewardText_loc4='对于守护希尔瓦纳及林地踏出了成功的第一步。$B$B因为巨魔的人数不再这么众多，血槌就会好好思考有关攻击我们的事。$B$B现在，但愿他们是唯一我们需要担心的巨魔氏族。$B',RequestItemsText_loc4='我们的斥候回报这些刀塔食人魔已经在更接近山路的地方创建了一个营地，就是从他们的堡垒到我们这里的那条路。$B$B很不幸的我们无法苟同就这样屈服于这些巨魔垃圾底下，但如果他们想要开战，他们会发现部落不只适应力好而已。',ObjectiveText1_loc4='杀死血槌食人魔';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4) VALUES (10503,'刀塔的威胁','雷神要塞所面临的形势比联盟的希尔瓦纳更加严峻。$B$B我指的是那些刀塔氏族的食人魔，目前驻扎在正西边的沟壑之中。的确，他们不是唯一一支食人魔氏族，但他们离我们最近，威胁也最大，我们必须击败他们，才能得到生存的空间。$B$B你立刻向北走，穿过锯齿山，然后沿着路一直前进，进入他们的要塞。到那里以后，你要尽全部力量消灭刀塔要塞和刀塔平原那边的刀塔食人魔和刀塔迅猛龙。','消灭刀塔要塞和刀塔平原的30个刀塔食人魔和10只刀塔迅猛龙。','对于守护希尔瓦纳及林地踏出了成功的第一步。$B$B随着他们的人数减少，刀塔会好好思考有关再度攻击雷神要塞的事。$B$B现在，但愿他们是我们唯一需要担心的食人魔氏族。','我们的斥候回报这些刀塔食人魔已经在更接近山路的地方创建了一个营地，就是从他们的堡垒到我们这里的那条路。$B$B很不幸的我们无法苟同就这样屈服于这些巨魔垃圾底下，但如果他们想要开战，他们会发现部落不只适应力好而已。','杀死刀塔食人魔') ON DUPLICATE KEY UPDATE Title_loc4='刀塔的威胁',Details_loc4='雷神要塞所面临的形势比联盟的希尔瓦纳更加严峻。$B$B我指的是那些刀塔氏族的食人魔，目前驻扎在正西边的沟壑之中。的确，他们不是唯一一支食人魔氏族，但他们离我们最近，威胁也最大，我们必须击败他们，才能得到生存的空间。$B$B你立刻向北走，穿过锯齿山，然后沿着路一直前进，进入他们的要塞。到那里以后，你要尽全部力量消灭刀塔要塞和刀塔平原那边的刀塔食人魔和刀塔迅猛龙。',Objectives_loc4='消灭刀塔要塞和刀塔平原的30个刀塔食人魔和10只刀塔迅猛龙。',OfferRewardText_loc4='对于守护希尔瓦纳及林地踏出了成功的第一步。$B$B随着他们的人数减少，刀塔会好好思考有关再度攻击雷神要塞的事。$B$B现在，但愿他们是我们唯一需要担心的食人魔氏族。',RequestItemsText_loc4='我们的斥候回报这些刀塔食人魔已经在更接近山路的地方创建了一个营地，就是从他们的堡垒到我们这里的那条路。$B$B很不幸的我们无法苟同就这样屈服于这些巨魔垃圾底下，但如果他们想要开战，他们会发现部落不只适应力好而已。',ObjectiveText1_loc4='杀死刀塔食人魔';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4) VALUES (10504,'刀塔食人魔','在血槌氏族北方，坐落着另一个更具威胁的食人魔氏族的大本营——刀塔氏族的刀塔要塞。$B$B刀塔食人魔是刀锋山脉中最强大的食人魔氏族，甚至已经得到了屠龙者格鲁尔和他七个儿子的宠爱。$B$B现在我们已经解决掉了血槌氏族，是时候关注一下他们的竞争对手了。$B$B你从血槌要塞出发的话，只需直接向北穿越谷地，就可以直接抵达刀塔要塞和刀塔平原。请在那边消灭尽量多的刀塔食人魔吧。','消灭刀塔要塞和刀塔平原的任意30个刀塔食人魔。','你对抗血槌及刀塔食人魔氏族的行动对保护希尔瓦纳的未来有很大的帮助。因为我们不打算扩宽超越这个大陆的辖区，起初我们什么都没发现的地方，不过我们也不会折磨那些可能会摧毁我们的。$B$B因为你为我们立了大功，我会奖励你以表示联盟的感谢之意。','血槌或是刀塔，都不重要。所有的食人魔氏族互相征战，争取拥有弑龙者格鲁尔支持的统治权。$B$B每一个都是我们的敌人，不管最后花落谁家。','杀死刀塔食人魔') ON DUPLICATE KEY UPDATE Title_loc4='刀塔食人魔',Details_loc4='在血槌氏族北方，坐落着另一个更具威胁的食人魔氏族的大本营——刀塔氏族的刀塔要塞。$B$B刀塔食人魔是刀锋山脉中最强大的食人魔氏族，甚至已经得到了屠龙者格鲁尔和他七个儿子的宠爱。$B$B现在我们已经解决掉了血槌氏族，是时候关注一下他们的竞争对手了。$B$B你从血槌要塞出发的话，只需直接向北穿越谷地，就可以直接抵达刀塔要塞和刀塔平原。请在那边消灭尽量多的刀塔食人魔吧。',Objectives_loc4='消灭刀塔要塞和刀塔平原的任意30个刀塔食人魔。',OfferRewardText_loc4='你对抗血槌及刀塔食人魔氏族的行动对保护希尔瓦纳的未来有很大的帮助。因为我们不打算扩宽超越这个大陆的辖区，起初我们什么都没发现的地方，不过我们也不会折磨那些可能会摧毁我们的。$B$B因为你为我们立了大功，我会奖励你以表示联盟的感谢之意。',RequestItemsText_loc4='血槌或是刀塔，都不重要。所有的食人魔氏族互相征战，争取拥有弑龙者格鲁尔支持的统治权。$B$B每一个都是我们的敌人，不管最后花落谁家。',ObjectiveText1_loc4='杀死刀塔食人魔';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4) VALUES (10505,'血槌食人魔','除了刀塔氏族以外，还有另一支食人魔力量威胁着我们的安全，那就是血槌食人魔，他们甚至在刀塔哨站的南方创建起了血槌哨站。$B$B虽然血槌食人魔并非是山脉中最强大的氏族，但是他们也崇拜屠龙者格鲁尔，同样具有相当强大的实力。$B$B既然我们已经解决掉了刀塔氏族，那么现在是时候来对付他们的竞争对手了。$B$B从刀塔要塞往南走，穿过峡谷就能到达血槌哨站，到那里去吧，在哨站周围消灭尽可能多的血槌食人魔。','消灭血槌哨站内的任意30个血槌食人魔。','你对抗刀塔及血槌巨魔氏族的行动对保护雷神要塞的未来有很大的帮助。我们不会接受那些会阻碍我们在这的使命的事情。$B$B因为你在消灭这些食人魔这件事上立了大功，我打算以奖励你来表示部落的感谢之意。$B','血槌或是刀塔，都不重要。所有的食人魔氏族互相征战，争取拥有弑龙者格鲁尔支持的统治权。$B$B每一个都是我们的敌人，不管最后花落谁家。','杀死血槌食人魔') ON DUPLICATE KEY UPDATE Title_loc4='血槌食人魔',Details_loc4='除了刀塔氏族以外，还有另一支食人魔力量威胁着我们的安全，那就是血槌食人魔，他们甚至在刀塔哨站的南方创建起了血槌哨站。$B$B虽然血槌食人魔并非是山脉中最强大的氏族，但是他们也崇拜屠龙者格鲁尔，同样具有相当强大的实力。$B$B既然我们已经解决掉了刀塔氏族，那么现在是时候来对付他们的竞争对手了。$B$B从刀塔要塞往南走，穿过峡谷就能到达血槌哨站，到那里去吧，在哨站周围消灭尽可能多的血槌食人魔。',Objectives_loc4='消灭血槌哨站内的任意30个血槌食人魔。',OfferRewardText_loc4='你对抗刀塔及血槌巨魔氏族的行动对保护雷神要塞的未来有很大的帮助。我们不会接受那些会阻碍我们在这的使命的事情。$B$B因为你在消灭这些食人魔这件事上立了大功，我打算以奖励你来表示部落的感谢之意。$B',RequestItemsText_loc4='血槌或是刀塔，都不重要。所有的食人魔氏族互相征战，争取拥有弑龙者格鲁尔支持的统治权。$B$B每一个都是我们的敌人，不管最后花落谁家。',ObjectiveText1_loc4='杀死血槌食人魔';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4) VALUES (10506,'严峻的形势','部落的狼群数量锐减之后，他们已经开始积极地寻找替换品。不过，这附近没有任何可用的野兽资源，他们的目标或许在谷底。$B$B谷地底下的血槌食人魔养着大量的恶狼作为看门宠物。但是，我对上次把你派去屠杀雷神狼群的做法也感到十分厌恶，我们为什么就不能换一个方法呢？$B$B最近我从精灵龙的翅膀上掉落下的粉尘中提炼出了一种很有意思的魔粉。把这些粉末撒在血槌恐狼的身上，这样部落就不会想要它们了。','对血槌哨站和血槌峡谷内的5只血槌巨狼使用莉娜的缩小粉尘。完成之后回到刀锋山的希尔瓦纳向她复命。','我很高兴听到任务已经完成了。那些必须牺牲的自然生物愈少愈好。$B$B因为你为我们作得所有事情，我得说我开始愈来愈喜欢你们的团队了。$B$B保重，$N。','有任何收获吗?我知道混在血槌巨魔中进行这项工作很危险，不过要是我们能够避免再杀害任何动物，我会觉得比较开心。','削弱血槌巨狼') ON DUPLICATE KEY UPDATE Title_loc4='严峻的形势',Details_loc4='部落的狼群数量锐减之后，他们已经开始积极地寻找替换品。不过，这附近没有任何可用的野兽资源，他们的目标或许在谷底。$B$B谷地底下的血槌食人魔养着大量的恶狼作为看门宠物。但是，我对上次把你派去屠杀雷神狼群的做法也感到十分厌恶，我们为什么就不能换一个方法呢？$B$B最近我从精灵龙的翅膀上掉落下的粉尘中提炼出了一种很有意思的魔粉。把这些粉末撒在血槌恐狼的身上，这样部落就不会想要它们了。',Objectives_loc4='对血槌哨站和血槌峡谷内的5只血槌巨狼使用莉娜的缩小粉尘。完成之后回到刀锋山的希尔瓦纳向她复命。',OfferRewardText_loc4='我很高兴听到任务已经完成了。那些必须牺牲的自然生物愈少愈好。$B$B因为你为我们作得所有事情，我得说我开始愈来愈喜欢你们的团队了。$B$B保重，$N。',RequestItemsText_loc4='有任何收获吗?我知道混在血槌巨魔中进行这项工作很危险，不过要是我们能够避免再杀害任何动物，我会觉得比较开心。',ObjectiveText1_loc4='削弱血槌巨狼';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10507,'转折点','$N，我们一直在等待这样的机会。凯尔萨斯与燃烧军团私下勾结的阴谋已经败露，现在你要拿起武器，击败凯尔的新主子——索克雷萨。$B$B我的健康状态不允许我亲自上阵，无法与你并肩作战真是遗憾。我将这颗宝珠交给你，它能聚集我全部的能量，帮助你击败索克雷萨。','前往位于铸魔基地：湮灭以北的登陆场：霸王，使用索克雷萨的传送石将你的小队传送到索克雷萨之座。利用沃雷塔尔的宝珠击败索克雷萨。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。','你是个拥有强大力量的人，$N。先知者很幸运能有你这个盟友。$B$B随着凯尔萨斯新东家的消息散布出去，更多的人都会跟我们看法一样了。我们可以宣称在对抗凯尔萨斯的新霸主上如此决定性的胜利使情势变得有利于我们。','完成了吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='转折点',Details_loc4='$N，我们一直在等待这样的机会。凯尔萨斯与燃烧军团私下勾结的阴谋已经败露，现在你要拿起武器，击败凯尔的新主子——索克雷萨。$B$B我的健康状态不允许我亲自上阵，无法与你并肩作战真是遗憾。我将这颗宝珠交给你，它能聚集我全部的能量，帮助你击败索克雷萨。',Objectives_loc4='前往位于铸魔基地：湮灭以北的登陆场：霸王，使用索克雷萨的传送石将你的小队传送到索克雷萨之座。利用沃雷塔尔的宝珠击败索克雷萨。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。',OfferRewardText_loc4='你是个拥有强大力量的人，$N。先知者很幸运能有你这个盟友。$B$B随着凯尔萨斯新东家的消息散布出去，更多的人都会跟我们看法一样了。我们可以宣称在对抗凯尔萨斯的新霸主上如此决定性的胜利使情势变得有利于我们。',RequestItemsText_loc4='完成了吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10508,'给沃雷塔尔的礼物','我可不想让你两手空空去见沃雷塔尔，低调不是我做事的风格。$B$B想要进入北边的索克雷萨之座，我们就必须使用索克雷萨的传送器，而只有他的传送石才能启动传送器。铸魔基地：湮灭的熔炉主管莫鲁格掌管着索克雷萨之石的上半部，索克雷萨之石的下半部则由铸魔基地：炼狱的希尔洛斯保管。$B$B夺得索克雷萨之石的上半部和下半部，沃雷塔尔必定会惊讶得说不出话来。','52区的间谍大师萨罗迪恩要你从铸魔基地：湮灭的熔炉主管莫鲁格手中夺得索克雷萨之石的上半部，并从铸魔基地：炼狱的希尔洛斯手中夺得索克雷萨之石的下半部。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。','你真是让我惊喜，$N!很高兴你是与我们同一阵线的。','你拿到索奎萨尔的传送石了吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='给沃雷塔尔的礼物',Details_loc4='我可不想让你两手空空去见沃雷塔尔，低调不是我做事的风格。$B$B想要进入北边的索克雷萨之座，我们就必须使用索克雷萨的传送器，而只有他的传送石才能启动传送器。铸魔基地：湮灭的熔炉主管莫鲁格掌管着索克雷萨之石的上半部，索克雷萨之石的下半部则由铸魔基地：炼狱的希尔洛斯保管。$B$B夺得索克雷萨之石的上半部和下半部，沃雷塔尔必定会惊讶得说不出话来。',Objectives_loc4='52区的间谍大师萨罗迪恩要你从铸魔基地：湮灭的熔炉主管莫鲁格手中夺得索克雷萨之石的上半部，并从铸魔基地：炼狱的希尔洛斯手中夺得索克雷萨之石的下半部。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。',OfferRewardText_loc4='你真是让我惊喜，$N!很高兴你是与我们同一阵线的。',RequestItemsText_loc4='你拿到索奎萨尔的传送石了吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10509,'无上的荣耀','现在我可以派你回沙塔斯城了。你已经掌握了凯尔萨斯与燃烧军团结盟的证据，并且夺得了通往索克雷萨之座的钥匙。$B$B不过你得看着点沃雷塔尔，别让他太激动——他年岁已高，恐怕经不起这么震撼的消息，你应该懂我的意思。去占星者之台的先知图书馆找他吧。','将索克雷萨的传送石交给沙塔斯城占星者之台的先知沃雷塔尔。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。','你不知道这对先知者来说有什么意义，$N。请准许我调整一下呼吸及了解一下状况。','我从虚空风暴那听到消息了，$N。很高兴见到你。') ON DUPLICATE KEY UPDATE Title_loc4='无上的荣耀',Details_loc4='现在我可以派你回沙塔斯城了。你已经掌握了凯尔萨斯与燃烧军团结盟的证据，并且夺得了通往索克雷萨之座的钥匙。$B$B不过你得看着点沃雷塔尔，别让他太激动——他年岁已高，恐怕经不起这么震撼的消息，你应该懂我的意思。去占星者之台的先知图书馆找他吧。',Objectives_loc4='将索克雷萨的传送石交给沙塔斯城占星者之台的先知沃雷塔尔。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。',OfferRewardText_loc4='你不知道这对先知者来说有什么意义，$N。请准许我调整一下呼吸及了解一下状况。',RequestItemsText_loc4='我从虚空风暴那听到消息了，$N。很高兴见到你。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10510,'进入德拉诺晶矿','啊啊，终于找到愿意帮助我们的人了！$B$B我和伯格瑞姆都是探险者协会的成员，到这里来就是为了考察这处伟大的山脉。我们听过许多有关这里的传说，真是迫不及待地要安顿下来开始研究了。$B$B听这里的暗夜精灵说，在谷地下面的正东向，有一处叫作德拉诺晶矿的地方出产一种很特殊的水晶。我对这种水晶非常有兴趣，所以想要搞到一些水晶的样本进行研究。','收集5块德拉诺矿洞水晶。','喔，看看这些东西，他们可是优良的样本。我等不及要用我的实验工具打开亲眼看看他们!$B$B感谢你!','很刺激吧?在这些希利苏斯灰泥及虫子之外，这个地方像个天堂。') ON DUPLICATE KEY UPDATE Title_loc4='进入德拉诺晶矿',Details_loc4='啊啊，终于找到愿意帮助我们的人了！$B$B我和伯格瑞姆都是探险者协会的成员，到这里来就是为了考察这处伟大的山脉。我们听过许多有关这里的传说，真是迫不及待地要安顿下来开始研究了。$B$B听这里的暗夜精灵说，在谷地下面的正东向，有一处叫作德拉诺晶矿的地方出产一种很特殊的水晶。我对这种水晶非常有兴趣，所以想要搞到一些水晶的样本进行研究。',Objectives_loc4='收集5块德拉诺矿洞水晶。',OfferRewardText_loc4='喔，看看这些东西，他们可是优良的样本。我等不及要用我的实验工具打开亲眼看看他们!$B$B感谢你!',RequestItemsText_loc4='很刺激吧?在这些希利苏斯灰泥及虫子之外，这个地方像个天堂。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10511,'奇怪的美酒','悠闲假日的最好伴侣那就是美酒名酿了，来这里度假怎么能没有酒。但糟糕的是，这些精灵真的完全不懂发酵与酿造的艺术。$B$B我听说谷地下面的血槌食人魔也是嗜酒如命，存有不少美酒。说起来，我还真想试上一试。$B$B嘿，帮我个忙怎么样？你马上向南穿越活木林，沿路下坡，进入东边的血槌哨站里，替我抢点酒来如何？我听说那里到处都是装得满满的大酒桶，由他们的酿酒师负责保管。','收集11桶血槌烈酒。','这是什么味道?喔不，不要告诉我那就是巨魔的酒?!$B$B我连喝都不想喝看看这东西。喔好吧，究竟是什么鬼东西啊?倒掉!','这里变得很无聊。没有东西喝得话我要怎么享受我的假期呢?') ON DUPLICATE KEY UPDATE Title_loc4='奇怪的美酒',Details_loc4='悠闲假日的最好伴侣那就是美酒名酿了，来这里度假怎么能没有酒。但糟糕的是，这些精灵真的完全不懂发酵与酿造的艺术。$B$B我听说谷地下面的血槌食人魔也是嗜酒如命，存有不少美酒。说起来，我还真想试上一试。$B$B嘿，帮我个忙怎么样？你马上向南穿越活木林，沿路下坡，进入东边的血槌哨站里，替我抢点酒来如何？我听说那里到处都是装得满满的大酒桶，由他们的酿酒师负责保管。',Objectives_loc4='收集11桶血槌烈酒。',OfferRewardText_loc4='这是什么味道?喔不，不要告诉我那就是巨魔的酒?!$B$B我连喝都不想喝看看这东西。喔好吧，究竟是什么鬼东西啊?倒掉!',RequestItemsText_loc4='这里变得很无聊。没有东西喝得话我要怎么享受我的假期呢?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4) VALUES (10512,'灌醉刀塔食人魔','打死我也不会再喝一口这难闻到家的泥浆了！不过，我突然有了一个好主意。$B$B<伯格瑞姆狡黠地眨了眨眼睛。>$B$B那么，计划如此：血槌食人魔没有这种泥浆水是活不成的，这一点我们都知道了。但我也很好奇，想知道他们的死对头刀塔食人魔对这玩意有什么看法。$B$B$N，我要求你立刻把这桶垃圾拿到刀塔食人魔那边去，丢给他们喝。从血槌哨站一路沿着谷地向北去就可以找到刀塔食人魔了。','用血槌酒桶将5个刀塔食人魔灌醉。','啊，哈哈哈!跟我想的一样。我猜巨魔什么都喝。$B$B笨蛋，全部都是!$B$B好吧，我得说虽然我没有得到我要的酒，不过你已经带给我的假期一个美好的开始。$B$B跟你说……我们这有各种我们不需要的东西。你要哪一个呢?','如何?这些刀塔食人魔跟那些血槌一样吗，或是像我一样被他们去掉小命?','灌醉刀塔食人魔') ON DUPLICATE KEY UPDATE Title_loc4='灌醉刀塔食人魔',Details_loc4='打死我也不会再喝一口这难闻到家的泥浆了！不过，我突然有了一个好主意。$B$B<伯格瑞姆狡黠地眨了眨眼睛。>$B$B那么，计划如此：血槌食人魔没有这种泥浆水是活不成的，这一点我们都知道了。但我也很好奇，想知道他们的死对头刀塔食人魔对这玩意有什么看法。$B$B$N，我要求你立刻把这桶垃圾拿到刀塔食人魔那边去，丢给他们喝。从血槌哨站一路沿着谷地向北去就可以找到刀塔食人魔了。',Objectives_loc4='用血槌酒桶将5个刀塔食人魔灌醉。',OfferRewardText_loc4='啊，哈哈哈!跟我想的一样。我猜巨魔什么都喝。$B$B笨蛋，全部都是!$B$B好吧，我得说虽然我没有得到我要的酒，不过你已经带给我的假期一个美好的开始。$B$B跟你说……我们这有各种我们不需要的东西。你要哪一个呢?',RequestItemsText_loc4='如何?这些刀塔食人魔跟那些血槌一样吗，或是像我一样被他们去掉小命?',ObjectiveText1_loc4='灌醉刀塔食人魔';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10513,'欧鲁诺克·裂心','$N，我不知道要如何才能掌握元素之灵提到的法术。老实说，我甚至不知道从何下手。$B$B<托洛克凝视着远方，陷入了沉思。>$B$B嗯……此行可能会毫无收获，不过这是我们惟一的希望。诅咒祭坛曾有一位兽人长者来访。我跟他攀谈过几句。据说他隐居在东北方的库斯卡水池附近的山上。去寻找这位名叫欧鲁诺克·裂心的兽人。$B$B我说过，此行可能无功而返。','前往库斯卡水池北边的破碎岩床寻找欧鲁诺克·裂心。','毁灭之语?从来没听过。听听我的建议吧:让死者安息。$B$B不过既然你都来了，我可以用一些其它的方法来帮助你#。你觉得呢?','哎?你得说大声点 $g小弟:小姐;。我的听力已经大不如前了。') ON DUPLICATE KEY UPDATE Title_loc4='欧鲁诺克·裂心',Details_loc4='$N，我不知道要如何才能掌握元素之灵提到的法术。老实说，我甚至不知道从何下手。$B$B<托洛克凝视着远方，陷入了沉思。>$B$B嗯……此行可能会毫无收获，不过这是我们惟一的希望。诅咒祭坛曾有一位兽人长者来访。我跟他攀谈过几句。据说他隐居在东北方的库斯卡水池附近的山上。去寻找这位名叫欧鲁诺克·裂心的兽人。$B$B我说过，此行可能无功而返。',Objectives_loc4='前往库斯卡水池北边的破碎岩床寻找欧鲁诺克·裂心。',OfferRewardText_loc4='毁灭之语?从来没听过。听听我的建议吧:让死者安息。$B$B不过既然你都来了，我可以用一些其它的方法来帮助你#。你觉得呢?',RequestItemsText_loc4='哎?你得说大声点 $g小弟:小姐;。我的听力已经大不如前了。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10514,'历经沧桑……','陌生人，我曾历经沧桑，但是昔日的辉煌已是过眼云烟。时过境迁，我现在不过是个普通的农夫罢了。$B$B我在农场训练地狱野猪，教它们从破碎平原的坚硬土壤中掘出影月块茎。但是，来自东北方的一批剥石者最近不断袭击猪圈，搞得我没办法收集块茎。$B$B你愿意去北边的农地帮我采集块茎吗？你可以站在影月块茎露出根须的地方吹响这只哨子，就会有地狱野猪跑来掘出块茎！','影月谷欧鲁诺克农场的欧鲁诺克·裂心要你在破碎平原收集10个影月块茎。$B$B任务完成后把欧鲁诺克的野猪哨一并归还给他。','你提到那边的那些镰夺怪多到超乎你的想象?看来是除掉这些垃圾的时候了。','去帮我把那些肉条带来!') ON DUPLICATE KEY UPDATE Title_loc4='历经沧桑……',Details_loc4='陌生人，我曾历经沧桑，但是昔日的辉煌已是过眼云烟。时过境迁，我现在不过是个普通的农夫罢了。$B$B我在农场训练地狱野猪，教它们从破碎平原的坚硬土壤中掘出影月块茎。但是，来自东北方的一批剥石者最近不断袭击猪圈，搞得我没办法收集块茎。$B$B你愿意去北边的农地帮我采集块茎吗？你可以站在影月块茎露出根须的地方吹响这只哨子，就会有地狱野猪跑来掘出块茎！',Objectives_loc4='影月谷欧鲁诺克农场的欧鲁诺克·裂心要你在破碎平原收集10个影月块茎。$B$B任务完成后把欧鲁诺克的野猪哨一并归还给他。',OfferRewardText_loc4='你提到那边的那些镰夺怪多到超乎你的想象?看来是除掉这些垃圾的时候了。',RequestItemsText_loc4='去帮我把那些肉条带来!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4) VALUES (10515,'严厉的教训','这帮剥石者胆敢冒犯欧鲁诺克，我们要给他们点厉害瞧瞧！$B$B我要你返回破碎平原，摧毁贪婪剥石者的卵。它们大多分布在剥石者的老巢中，因此请千万小心。','返回破碎平原，摧毁10枚贪婪剥石者的卵，然后向影月谷欧鲁诺克农场的欧鲁诺克·裂心复命。','那会让那些该死，下流的生物得到教训不再杀害我的野猪!做得好，$N!','赶尽杀绝!','摧毁贪婪剥石者的卵') ON DUPLICATE KEY UPDATE Title_loc4='严厉的教训',Details_loc4='这帮剥石者胆敢冒犯欧鲁诺克，我们要给他们点厉害瞧瞧！$B$B我要你返回破碎平原，摧毁贪婪剥石者的卵。它们大多分布在剥石者的老巢中，因此请千万小心。',Objectives_loc4='返回破碎平原，摧毁10枚贪婪剥石者的卵，然后向影月谷欧鲁诺克农场的欧鲁诺克·裂心复命。',OfferRewardText_loc4='那会让那些该死，下流的生物得到教训不再杀害我的野猪!做得好，$N!',RequestItemsText_loc4='赶尽杀绝!',ObjectiveText1_loc4='摧毁贪婪剥石者的卵';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10516,'守备官的困境','这听起来很奇怪，但我确实是故意要继续待在这只笼子里面的。我来这里的目的是收集刀塔食人魔的情报，目前的状况给了我一个非常好的机会。$B$B其实，只要我愿意，我随时都可以离开，但是我需要先拿回我的佩剑和盾牌。$B$B这群食人魔中的两个头目拿着它们：德罗加姆拿着剑，玛戈多格拿着盾牌。$B$B要是有必要谨慎些的话，你可以去南边的血槌哨站搞一些酒来，把他们周围的其它食人魔都灌醉，这样他们就不会有援手了，当然，还是得小心那些不喝酒的守卫！','夺回守备官乌里恩之剑和守备官乌里恩之盾。','现在我欠你一个人情，因为你帮助我守住我的面子。但是我们在这个工作尚未完成。','$C，你拿到我的剑跟盾了吗?$B$B虽然我随时都可以离开，但是失去我的武器两手空空的回到希尔瓦纳是一件很丢脸的事。') ON DUPLICATE KEY UPDATE Title_loc4='守备官的困境',Details_loc4='这听起来很奇怪，但我确实是故意要继续待在这只笼子里面的。我来这里的目的是收集刀塔食人魔的情报，目前的状况给了我一个非常好的机会。$B$B其实，只要我愿意，我随时都可以离开，但是我需要先拿回我的佩剑和盾牌。$B$B这群食人魔中的两个头目拿着它们：德罗加姆拿着剑，玛戈多格拿着盾牌。$B$B要是有必要谨慎些的话，你可以去南边的血槌哨站搞一些酒来，把他们周围的其它食人魔都灌醉，这样他们就不会有援手了，当然，还是得小心那些不喝酒的守卫！',Objectives_loc4='夺回守备官乌里恩之剑和守备官乌里恩之盾。',OfferRewardText_loc4='现在我欠你一个人情，因为你帮助我守住我的面子。但是我们在这个工作尚未完成。',RequestItemsText_loc4='$C，你拿到我的剑跟盾了吗?$B$B虽然我随时都可以离开，但是失去我的武器两手空空的回到希尔瓦纳是一件很丢脸的事。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10517,'高尔迪姆，你完蛋了……','刀塔要塞的领袖据说是高尔迪姆。相信我……应该就是这个名字没错了。$B$B不过，我可绝对不会轻视这个家伙。他将自己的氏族发展壮大了许多，不仅得到了屠龙者格鲁尔的宠爱，甚至成为了刀锋山脉的统治者。高尔迪姆身边总是带着大量的随从，甚至有几名发誓绝对不碰酒的可靠侍卫。$B$B为了希尔瓦纳的安全，我命令你立刻返回那边，刺杀高尔迪姆。','杀死刀塔要塞内的食人魔头目高尔迪姆。','很好。你非常聪明，$C，那是一定的。$B$B我怀疑接下来是否会有另外一件事情你能为了我及希尔瓦纳去完成呢?','那些噪音是什么?是因为你解决哥尔迪姆的关系吗?') ON DUPLICATE KEY UPDATE Title_loc4='高尔迪姆，你完蛋了……',Details_loc4='刀塔要塞的领袖据说是高尔迪姆。相信我……应该就是这个名字没错了。$B$B不过，我可绝对不会轻视这个家伙。他将自己的氏族发展壮大了许多，不仅得到了屠龙者格鲁尔的宠爱，甚至成为了刀锋山脉的统治者。高尔迪姆身边总是带着大量的随从，甚至有几名发誓绝对不碰酒的可靠侍卫。$B$B为了希尔瓦纳的安全，我命令你立刻返回那边，刺杀高尔迪姆。',Objectives_loc4='杀死刀塔要塞内的食人魔头目高尔迪姆。',OfferRewardText_loc4='很好。你非常聪明，$C，那是一定的。$B$B我怀疑接下来是否会有另外一件事情你能为了我及希尔瓦纳去完成呢?',RequestItemsText_loc4='那些噪音是什么?是因为你解决哥尔迪姆的关系吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10518,'插旗子','我要你从那些刀塔勇士的身上偷一面刀塔旗帜，带到南边的血槌哨站去。之后，你要把旗子插在那里的北槌哨塔的顶上。$B$B这样一来，你就会马上激怒那些血槌食人魔，遭到他们的无情攻击，同时也会进一步挑起他们对刀塔要塞的仇恨，使他们忽略掉希尔瓦纳。$B$B你插上旗子之后，必定会引出血槌氏族的古恩·格鲁诺什，杀死他并夺走他的头盔，然后你就可以返回希尔瓦纳了。$B$B$N，这可是个艰难的任务，最好还是带上一两位朋友同行吧。','在北槌哨塔顶上使用刀塔旗帜，引出古恩·格鲁诺什。然后将旗帜和古恩·格鲁诺什的头盔一起交给刀锋山希尔瓦纳的指挥官萨卡斯·天影。','葛恩.格罗姆巴诺斯的头盔及一面刀塔氏族旌旗?$B$B你跟复仇者想出这个计划真的十分的聪明。$B$B藉由将血槌氏族的注意力保留在剑刃要塞那，你减轻了因为他们想要进犯我们这里的压力。$B$B请收下来自希尔瓦纳这份微薄的礼物，$N。','是什么将你引领到我这?不是与血槌巨魔氏族之间更多的麻烦吧?') ON DUPLICATE KEY UPDATE Title_loc4='插旗子',Details_loc4='我要你从那些刀塔勇士的身上偷一面刀塔旗帜，带到南边的血槌哨站去。之后，你要把旗子插在那里的北槌哨塔的顶上。$B$B这样一来，你就会马上激怒那些血槌食人魔，遭到他们的无情攻击，同时也会进一步挑起他们对刀塔要塞的仇恨，使他们忽略掉希尔瓦纳。$B$B你插上旗子之后，必定会引出血槌氏族的古恩·格鲁诺什，杀死他并夺走他的头盔，然后你就可以返回希尔瓦纳了。$B$B$N，这可是个艰难的任务，最好还是带上一两位朋友同行吧。',Objectives_loc4='在北槌哨塔顶上使用刀塔旗帜，引出古恩·格鲁诺什。然后将旗帜和古恩·格鲁诺什的头盔一起交给刀锋山希尔瓦纳的指挥官萨卡斯·天影。',OfferRewardText_loc4='葛恩.格罗姆巴诺斯的头盔及一面刀塔氏族旌旗?$B$B你跟复仇者想出这个计划真的十分的聪明。$B$B藉由将血槌氏族的注意力保留在剑刃要塞那，你减轻了因为他们想要进犯我们这里的压力。$B$B请收下来自希尔瓦纳这份微薄的礼物，$N。',RequestItemsText_loc4='是什么将你引领到我这?不是与血槌巨魔氏族之间更多的麻烦吧?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,EndText_loc4) VALUES (10519,'诅咒密码 - 真相和历史','<欧鲁诺克变换了站姿，挺直了腰板，身形顿时高大起来。>$B$B$N，我从不做没把握的事。刚才算是对你的考验吧，请原谅我现在才显露真面目。我并不是一位普通的兽人老农。$B$B如果你是为诅咒密码而来，就先听听我的故事吧。等你做好准备，我们就开始吧。','影月谷欧鲁诺克农场的欧鲁诺克·裂心要你听听他的故事。跟欧鲁诺克谈谈，听这位年老的兽人讲述他的故事。','你了解必须做什么了吧?去找欧朗诺克之子。找到我的儿子们……','耐心的听吧，$N。','诅咒密码 - 真相和历史') ON DUPLICATE KEY UPDATE Title_loc4='诅咒密码 - 真相和历史',Details_loc4='<欧鲁诺克变换了站姿，挺直了腰板，身形顿时高大起来。>$B$B$N，我从不做没把握的事。刚才算是对你的考验吧，请原谅我现在才显露真面目。我并不是一位普通的兽人老农。$B$B如果你是为诅咒密码而来，就先听听我的故事吧。等你做好准备，我们就开始吧。',Objectives_loc4='影月谷欧鲁诺克农场的欧鲁诺克·裂心要你听听他的故事。跟欧鲁诺克谈谈，听这位年老的兽人讲述他的故事。',OfferRewardText_loc4='你了解必须做什么了吧?去找欧朗诺克之子。找到我的儿子们……',RequestItemsText_loc4='耐心的听吧，$N。',EndText_loc4='诅咒密码 - 真相和历史';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10520,'协助大德鲁伊','打扰一下，$c，如果可能的话，我想占用你一点时间。$B$B达纳苏斯的塞纳里奥议会希望能找到像你这样经验丰富的冒险家来帮助他们进行一项重要的研究项目。虽然我不知道详细的情况，但是我可以告诉你，正是伊范达尔·鹿盔亲自负责这项研究。$B$B要是你感兴趣的话，请直接去达纳苏斯的塞纳里奥区找他谈谈。','与达纳苏斯的大德鲁伊范达尔·鹿盔谈一谈。','好吧，$C……你被告知是我独自负责这项研究，所以显然你尽快赶来了。$B$B现在既然你已经到了这儿，那么当我告诉你详细情况时，你可要集中精神听仔细了，我可没耐心再说一次。') ON DUPLICATE KEY UPDATE Title_loc4='协助大德鲁伊',Details_loc4='打扰一下，$c，如果可能的话，我想占用你一点时间。$B$B达纳苏斯的塞纳里奥议会希望能找到像你这样经验丰富的冒险家来帮助他们进行一项重要的研究项目。虽然我不知道详细的情况，但是我可以告诉你，正是伊范达尔·鹿盔亲自负责这项研究。$B$B要是你感兴趣的话，请直接去达纳苏斯的塞纳里奥区找他谈谈。',Objectives_loc4='与达纳苏斯的大德鲁伊范达尔·鹿盔谈一谈。',OfferRewardText_loc4='好吧，$C……你被告知是我独自负责这项研究，所以显然你尽快赶来了。$B$B现在既然你已经到了这儿，那么当我告诉你详细情况时，你可要集中精神听仔细了，我可没耐心再说一次。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10521,'格洛姆托，欧鲁诺克之子','我的长子格洛姆托前往正西南方的库斯卡岗哨去打探诅咒密码的线索。$B$B他是家族中的战士，这小子脾气暴躁、嗜血成性……完全遗传了他母亲的脾气。去库斯卡岗哨附近搜寻他的下落。如果你发现了纳迦的尸体，那格洛姆托一定就在附近。$B$B找到他后，告诉他：“我们为了正义而挥洒热血。”这样，他就会明白你是欧鲁诺克的朋友，你也可以避免死于非命。','前往影月谷的库斯卡岗哨寻找格洛姆托，欧鲁诺克之子。','<葛洛姆特哼了一声。>$B$B你来得好。这只蛆虫刚好穿肠破肚。我们现在有了!','父亲派你来的?') ON DUPLICATE KEY UPDATE Title_loc4='格洛姆托，欧鲁诺克之子',Details_loc4='我的长子格洛姆托前往正西南方的库斯卡岗哨去打探诅咒密码的线索。$B$B他是家族中的战士，这小子脾气暴躁、嗜血成性……完全遗传了他母亲的脾气。去库斯卡岗哨附近搜寻他的下落。如果你发现了纳迦的尸体，那格洛姆托一定就在附近。$B$B找到他后，告诉他：“我们为了正义而挥洒热血。”这样，他就会明白你是欧鲁诺克的朋友，你也可以避免死于非命。',Objectives_loc4='前往影月谷的库斯卡岗哨寻找格洛姆托，欧鲁诺克之子。',OfferRewardText_loc4='<葛洛姆特哼了一声。>$B$B你来得好。这只蛆虫刚好穿肠破肚。我们现在有了!',RequestItemsText_loc4='父亲派你来的?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10522,'诅咒密码 - 格洛姆托的命令','这是我今天审问的第六个纳迦。这家伙身穿华丽的护甲，想必知道些内情。其它的都是些一无是处的废物。$B$B<格洛姆托指着地上横七竖八的纳迦尸体。>$B$B我揍了他一顿，他就什么都说了。$B$B诅咒密码的第一块碎片被锁在库斯卡岗哨或是库斯卡水池的某个箱子中，钥匙就在纳迦身上。杀死纳迦，夺得钥匙，取回碎片之后回到我这里来。','取回诅咒密码的第一块碎片，然后向影月谷库斯卡岗哨的欧鲁诺克之子格洛姆托复命。','这个必须马上送回去给父亲。','运气好吗?') ON DUPLICATE KEY UPDATE Title_loc4='诅咒密码 - 格洛姆托的命令',Details_loc4='这是我今天审问的第六个纳迦。这家伙身穿华丽的护甲，想必知道些内情。其它的都是些一无是处的废物。$B$B<格洛姆托指着地上横七竖八的纳迦尸体。>$B$B我揍了他一顿，他就什么都说了。$B$B诅咒密码的第一块碎片被锁在库斯卡岗哨或是库斯卡水池的某个箱子中，钥匙就在纳迦身上。杀死纳迦，夺得钥匙，取回碎片之后回到我这里来。',Objectives_loc4='取回诅咒密码的第一块碎片，然后向影月谷库斯卡岗哨的欧鲁诺克之子格洛姆托复命。',OfferRewardText_loc4='这个必须马上送回去给父亲。',RequestItemsText_loc4='运气好吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10523,'诅咒密码 - 第一块碎片','<格洛姆托将诅咒密码的第一块碎片卷起来，放入带锁的箱子中。>$B$B把这只箱子交给我的父亲。他在东北方的欧鲁诺克农场等你。$B$B请转告他，我玩够了就会回家，很快的……','将格洛姆托的箱子交给影月谷欧鲁诺克农场的欧鲁诺克·裂心。','当毁灭密码改正后，我们就该终止这个诅咒了!','你成功了?') ON DUPLICATE KEY UPDATE Title_loc4='诅咒密码 - 第一块碎片',Details_loc4='<格洛姆托将诅咒密码的第一块碎片卷起来，放入带锁的箱子中。>$B$B把这只箱子交给我的父亲。他在东北方的欧鲁诺克农场等你。$B$B请转告他，我玩够了就会回家，很快的……',Objectives_loc4='将格洛姆托的箱子交给影月谷欧鲁诺克农场的欧鲁诺克·裂心。',OfferRewardText_loc4='当毁灭密码改正后，我们就该终止这个诅咒了!',RequestItemsText_loc4='你成功了?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10524,'雷神氏族的神器','这些印有标记的器物都是由雷神氏族的兽人制造的。在变异成邪兽人以后，这些兽人一直居住在雷神要塞中。$B$B刀塔氏族的食人魔甚至也曾在要塞居住过一段时间，直到最近才被部落赶走。$B$B想必你已经听说了还有其它部分圣物遗失的消息，包括一面鼓、一支箭，还有一块石板，目前我们正在搜索它们的踪迹，希望你也来帮忙。$B$B去刀塔要塞寻找这几样东西吧，如果找到的话，请把它们交给洛克加·血握。','找回雷神氏族战鼓、雷神氏族箭矢和雷神氏族石板。','我不敢相信我看到了什么!如果这是某种骗局，我会把你碎尸万段的，$C!$B$B快，在被你笨手笨脚弄坏前，先让我鉴定一下这些宝贵的神器。','我认识你吗?') ON DUPLICATE KEY UPDATE Title_loc4='雷神氏族的神器',Details_loc4='这些印有标记的器物都是由雷神氏族的兽人制造的。在变异成邪兽人以后，这些兽人一直居住在雷神要塞中。$B$B刀塔氏族的食人魔甚至也曾在要塞居住过一段时间，直到最近才被部落赶走。$B$B想必你已经听说了还有其它部分圣物遗失的消息，包括一面鼓、一支箭，还有一块石板，目前我们正在搜索它们的踪迹，希望你也来帮忙。$B$B去刀塔要塞寻找这几样东西吧，如果找到的话，请把它们交给洛克加·血握。',Objectives_loc4='找回雷神氏族战鼓、雷神氏族箭矢和雷神氏族石板。',OfferRewardText_loc4='我不敢相信我看到了什么!如果这是某种骗局，我会把你碎尸万段的，$C!$B$B快，在被你笨手笨脚弄坏前，先让我鉴定一下这些宝贵的神器。',RequestItemsText_loc4='我认识你吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,EndText_loc4) VALUES (10525,'幻像的指引','你这愚蠢的$R，你几乎毁掉了这面鼓！$B$B我费劲了千心万苦才来到这里，直到现在什么也没找到。其它寻找圣物的人也都失败了，或者遇到更糟的事。唉，算了，至少你能成功地把东西带回来。$B$B是时候召唤出幻像，让它指引你找到我所寻找的最后一件圣物了。$B$B带上这片炽热灵魂碎块，它可以将你的身体变为火焰，并将你的灵魂领入一个幻像中。那时，你就能知道最后一件雷神圣物在哪里了。','利用炽热灵魂碎块将你的灵魂转变为指引你方向的幻像。找到最后一个雷神圣物的位置。','德莱尼矿坑的后面?一定是血槌氏族从刀塔食人魔那偷来的。$B$B呸!那对我来说太远了……太过深入血槌的领土。$B$B不过对你就不是。你知道怎么去。你要代替我去那里!','你看
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10526,'雷霆之刺','如果我让你看到的幻境里所显示的地点没错，那你就必须去峡谷那边一趟。总之，到血槌峡谷南部边缘去，你可以在那里找到德拉诺晶矿。$B$B然后，你要绕到矿井背后找回雷霆之刺。千万别去管其它的东西！我对矿井里的水晶和食人魔都没有兴趣。$B$B找到圣物后马上把它带回来给我！$B$B嘿，$N，一定要非常小心……我实在不愿去想象你将它折断后会有怎样的结果。','找回雷霆之刺。','我现在很感动!你知道有多少其它鬼魂想要取回所有这些神器吗?$B$B我何其幸运有你在这与我们共事，$N。虽然你动作有点慢。$B$B请让我为了你的贡献而酬谢你。挑一个吧，不过请做出明智的选择。当你完成后，我就会交出神器来平息雷神要塞的鬼魂。','我相信，你一定很疑惑这些神器的用义。$B$B当我们五个都拥有的时候，我们在雷神要塞的所有权就可藉由安抚那些死去的鬼魂而稳固。$B$B你现在开始领会为何这有这么重要了吗?你了解为何我会这么挑剔了吧?') ON DUPLICATE KEY UPDATE Title_loc4='雷霆之刺',Details_loc4='如果我让你看到的幻境里所显示的地点没错，那你就必须去峡谷那边一趟。总之，到血槌峡谷南部边缘去，你可以在那里找到德拉诺晶矿。$B$B然后，你要绕到矿井背后找回雷霆之刺。千万别去管其它的东西！我对矿井里的水晶和食人魔都没有兴趣。$B$B找到圣物后马上把它带回来给我！$B$B嘿，$N，一定要非常小心……我实在不愿去想象你将它折断后会有怎样的结果。',Objectives_loc4='找回雷霆之刺。',OfferRewardText_loc4='我现在很感动!你知道有多少其它鬼魂想要取回所有这些神器吗?$B$B我何其幸运有你在这与我们共事，$N。虽然你动作有点慢。$B$B请让我为了你的贡献而酬谢你。挑一个吧，不过请做出明智的选择。当你完成后，我就会交出神器来平息雷神要塞的鬼魂。',RequestItemsText_loc4='我相信，你一定很疑惑这些神器的用义。$B$B当我们五个都拥有的时候，我们在雷神要塞的所有权就可藉由安抚那些死去的鬼魂而稳固。$B$B你现在开始领会为何这有这么重要了吗?你了解为何我会这么挑剔了吧?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10527,'阿托尔，欧鲁诺克之子','我的幼子阿托尔前往伊利达雷岗哨打探诅咒密码的线索，伊利达雷岗哨在遥远的西南方，位于军团要塞和蛮锤要塞之间。$B$B虽然阿托尔箭术精湛、善于追踪，但此行危机重重，恐怕他也应付不过来。伊利达雷岗哨是伊利丹恶魔大军的试验场。那里到处都是叛离燃烧军团、投靠背叛者的恶魔！$B$B$N，前往伊利达雷岗哨寻找阿托尔吧。','前往影月谷的伊利达雷岗哨寻找阿托尔，欧鲁诺克之子。','阿尔托的身体毫无生气的躺着，悬浮在半空中。你不知道他已经死了多久了，但你为了欧朗诺克而感到心痛。$B$B也许你可以试着将他放下来并将他的尸体带回去给他父亲。') ON DUPLICATE KEY UPDATE Title_loc4='阿托尔，欧鲁诺克之子',Details_loc4='我的幼子阿托尔前往伊利达雷岗哨打探诅咒密码的线索，伊利达雷岗哨在遥远的西南方，位于军团要塞和蛮锤要塞之间。$B$B虽然阿托尔箭术精湛、善于追踪，但此行危机重重，恐怕他也应付不过来。伊利达雷岗哨是伊利丹恶魔大军的试验场。那里到处都是叛离燃烧军团、投靠背叛者的恶魔！$B$B$N，前往伊利达雷岗哨寻找阿托尔吧。',Objectives_loc4='前往影月谷的伊利达雷岗哨寻找阿托尔，欧鲁诺克之子。',OfferRewardText_loc4='阿尔托的身体毫无生气的躺着，悬浮在半空中。你不知道他已经死了多久了，但你为了欧朗诺克而感到心痛。$B$B也许你可以试着将他放下来并将他的尸体带回去给他父亲。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10528,'恶魔的水晶牢笼','漂浮在半空中的水晶环绕着地面上的神秘符文，水晶射出的能量光束形成禁锢法阵，将阿托尔的尸体困在法阵中央。你试着想要移动这具尸体，却发现怎么用力都无济于事。$B$B你注意到所有的水晶底座上都有一个空槽，或许它们都配有钥匙吧。附近似乎时不时还有魅魔在举行某种仪式。$B$B在伊利达雷岗哨寻找魅魔首领的下落，也许她携带着解除禁锢法阵的钥匙。','杀死伊利达雷岗哨的痛苦女王加布莉萨，夺得晶体钥匙，然后返回欧鲁诺克之子阿托尔的尸体旁。','你将结晶钥匙转动插入每一个恶魔结晶底部的缝孔中。','阿尔托无生气的飘浮在你面前。') ON DUPLICATE KEY UPDATE Title_loc4='恶魔的水晶牢笼',Details_loc4='漂浮在半空中的水晶环绕着地面上的神秘符文，水晶射出的能量光束形成禁锢法阵，将阿托尔的尸体困在法阵中央。你试着想要移动这具尸体，却发现怎么用力都无济于事。$B$B你注意到所有的水晶底座上都有一个空槽，或许它们都配有钥匙吧。附近似乎时不时还有魅魔在举行某种仪式。$B$B在伊利达雷岗哨寻找魅魔首领的下落，也许她携带着解除禁锢法阵的钥匙。',Objectives_loc4='杀死伊利达雷岗哨的痛苦女王加布莉萨，夺得晶体钥匙，然后返回欧鲁诺克之子阿托尔的尸体旁。',OfferRewardText_loc4='你将结晶钥匙转动插入每一个恶魔结晶底部的缝孔中。',RequestItemsText_loc4='阿尔托无生气的飘浮在你面前。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10529,'猎人之道','远行者居所的达恩·晨行者中尉召集所有年轻强壮的猎人去见她。如果你能去找她的话，将对你未来的职业生涯非常有好处，$N。在我们这一行中，她就是智慧的灯塔，照亮着许多猎人前进的道路。$b$b远行者居所就在银月城正南方向。','与永歌森林中远行者居所的达恩·晨行者中尉谈一谈。','$N，你来了真好。我们盟友的数量愈来愈少了，甚至那些与我们有共同目标的也无法完全信任。这就是我们这些游侠转而向大自然求助的原因。$B$B在森林中的这些盟友中我们可以找到一股没有欺骗的深刻连结。') ON DUPLICATE KEY UPDATE Title_loc4='猎人之道',Details_loc4='远行者居所的达恩·晨行者中尉召集所有年轻强壮的猎人去见她。如果你能去找她的话，将对你未来的职业生涯非常有好处，$N。在我们这一行中，她就是智慧的灯塔，照亮着许多猎人前进的道路。$b$b远行者居所就在银月城正南方向。',Objectives_loc4='与永歌森林中远行者居所的达恩·晨行者中尉谈一谈。',OfferRewardText_loc4='$N，你来了真好。我们盟友的数量愈来愈少了，甚至那些与我们有共同目标的也无法完全信任。这就是我们这些游侠转而向大自然求助的原因。$B$B在森林中的这些盟友中我们可以找到一股没有欺骗的深刻连结。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10530,'猎人之道','远行者居所的达恩·晨行者中尉召集所有年轻强壮的猎人去见她。如果你能去找她的话，将对你未来的职业生涯非常有好处，$N。在我们这一行中，她就是智慧的灯塔，照亮着许多猎人前进的道路。$b$b远行者居所就在银月城正南方向。','与永歌森林中远行者居所的达恩·晨行者中尉谈一谈。','$N,你来了真好。我们盟友的数量愈来愈少了，甚至那些与我们有共同目标的也无法完全信任。这就是我们这些游侠转而向大自然求助的原因。$BB在森林中的这些盟友中我们可以找到一股没有欺骗的深刻连结。') ON DUPLICATE KEY UPDATE Title_loc4='猎人之道',Details_loc4='远行者居所的达恩·晨行者中尉召集所有年轻强壮的猎人去见她。如果你能去找她的话，将对你未来的职业生涯非常有好处，$N。在我们这一行中，她就是智慧的灯塔，照亮着许多猎人前进的道路。$b$b远行者居所就在银月城正南方向。',Objectives_loc4='与永歌森林中远行者居所的达恩·晨行者中尉谈一谈。',OfferRewardText_loc4='$N,你来了真好。我们盟友的数量愈来愈少了，甚至那些与我们有共同目标的也无法完全信任。这就是我们这些游侠转而向大自然求助的原因。$BB在森林中的这些盟友中我们可以找到一股没有欺骗的深刻连结。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4,ObjectiveText2_loc4,ObjectiveText3_loc4,ObjectiveText4_loc4) VALUES (10531,'阿拉希盆地之战！','$N，在阿拉希盆地的战斗是为了资源和领土而进行的战斗。这个地区作战的关键是保证我们军队稀有物资和补给的顺畅运作。我命令你去攻击距离我们在阿拉希盆地中的基地最远的战略设施。$B$B当农场、矿洞、伐木场或铁匠铺被敌人占据时，攻击这些设施，找到敌人的旗帜，然后把它拔掉！$B$B当你完成了夺回这四个点的任务之后，就回到我这里来。','进攻矿洞、伐木场、铁匠铺和农场，然后向避难谷地的奥斯莱特元帅复命。','我收到了你在阿拉希盆地大显神威的报告，$N。做得好!如果有越来越多的像你这样勇敢的$C加入我们，我坚信我们总有一天能夺回我们的家园。','$N，你还没有完成对这4个战略要点的攻击。任务完成之后再回到我这里来。','突袭矿洞','突袭伐木场','突袭铁匠铺','突袭农场') ON DUPLICATE KEY UPDATE Title_loc4='阿拉希盆地之战！',Details_loc4='$N，在阿拉希盆地的战斗是为了资源和领土而进行的战斗。这个地区作战的关键是保证我们军队稀有物资和补给的顺畅运作。我命令你去攻击距离我们在阿拉希盆地中的基地最远的战略设施。$B$B当农场、矿洞、伐木场或铁匠铺被敌人占据时，攻击这些设施，找到敌人的旗帜，然后把它拔掉！$B$B当你完成了夺回这四个点的任务之后，就回到我这里来。',Objectives_loc4='进攻矿洞、伐木场、铁匠铺和农场，然后向避难谷地的奥斯莱特元帅复命。',OfferRewardText_loc4='我收到了你在阿拉希盆地大显神威的报告，$N。做得好!如果有越来越多的像你这样勇敢的$C加入我们，我坚信我们总有一天能夺回我们的家园。',RequestItemsText_loc4='$N，你还没有完成对这4个战略要点的攻击。任务完成之后再回到我这里来。',ObjectiveText1_loc4='突袭矿洞',ObjectiveText2_loc4='突袭伐木场',ObjectiveText3_loc4='突袭铁匠铺',ObjectiveText4_loc4='突袭农场';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10532,'切断阿拉索补给线','阿拉索联军正在不惜一切代价进攻阿拉希，并妄图夺回这个区域。联盟的各个种族正在全力进军这块遥远的土地，想要将他们的势力从避难谷地扩张到这里。我们必须阻止他们，而最好的方式就是夺取他们的资源。$B$B你可以帮助我们，$N。进入阿拉希盆地，那里遍地都是丰富的矿藏、肥沃的土地和技艺精湛的能工巧匠。占据并控制你找到的所有基地，赢得战斗，然后把你获得的资源给我拿回来。','进入阿拉希盆地，获得一箱阿拉希资源箱，然后将它交给落锤镇的亡灵哨兵莫提斯。','非常感谢，$N。我们会确保这些资源不落入联盟的手中。$B$B你的战斗能力值得表彰，$N，去面对阿拉索联军，赢得更辉煌的胜利吧。','你赢得阿拉希盆地的战斗了吗，$N?你拿到资源木箱了吗?') ON DUPLICATE KEY UPDATE Title_loc4='切断阿拉索补给线',Details_loc4='阿拉索联军正在不惜一切代价进攻阿拉希，并妄图夺回这个区域。联盟的各个种族正在全力进军这块遥远的土地，想要将他们的势力从避难谷地扩张到这里。我们必须阻止他们，而最好的方式就是夺取他们的资源。$B$B你可以帮助我们，$N。进入阿拉希盆地，那里遍地都是丰富的矿藏、肥沃的土地和技艺精湛的能工巧匠。占据并控制你找到的所有基地，赢得战斗，然后把你获得的资源给我拿回来。',Objectives_loc4='进入阿拉希盆地，获得一箱阿拉希资源箱，然后将它交给落锤镇的亡灵哨兵莫提斯。',OfferRewardText_loc4='非常感谢，$N。我们会确保这些资源不落入联盟的手中。$B$B你的战斗能力值得表彰，$N，去面对阿拉索联军，赢得更辉煌的胜利吧。',RequestItemsText_loc4='你赢得阿拉希盆地的战斗了吗，$N?你拿到资源木箱了吗?';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10533,'更多的资源','啊，你抢到了更多的资源木箱!没有资源补给的联盟肯定会一败涂地的!$B$B感谢你，$N。你的努力已经为我们所知，并且也为瓦里玛萨斯所知。','虽然在破坏阿拉索联军的补给线方面，污染者做得已经很不错了，但是联盟还在继续对阿拉希盆地进行攻击。我们必须向盆地增派部队，并夺回更多的资源。') ON DUPLICATE KEY UPDATE Title_loc4='更多的资源',OfferRewardText_loc4='啊，你抢到了更多的资源木箱!没有资源补给的联盟肯定会一败涂地的!$B$B感谢你，$N。你的努力已经为我们所知，并且也为瓦里玛萨斯所知。',RequestItemsText_loc4='虽然在破坏阿拉索联军的补给线方面，污染者做得已经很不错了，但是联盟还在继续对阿拉希盆地进行攻击。我们必须向盆地增派部队，并夺回更多的资源。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10534,'回家','$R$C……$B$B嗯，之前有位跟你同族的牧师前来拜访，$N。他说你该返回埃索达跟凯德莫斯会面。似乎这事儿挺紧急的，我们匆匆聊了几句他就离开了。','埃索达的凯德莫斯要你回去与他会面。','圣光引领你回到我这，$N，你的训练才刚要开始。','你好啊年轻的$g牧师:女牧师;。') ON DUPLICATE KEY UPDATE Title_loc4='回家',Details_loc4='$R$C……$B$B嗯，之前有位跟你同族的牧师前来拜访，$N。他说你该返回埃索达跟凯德莫斯会面。似乎这事儿挺紧急的，我们匆匆聊了几句他就离开了。',Objectives_loc4='埃索达的凯德莫斯要你回去与他会面。',OfferRewardText_loc4='圣光引领你回到我这，$N，你的训练才刚要开始。',RequestItemsText_loc4='你好啊年轻的$g牧师:女牧师;。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10535,'阿拉希盆地的资源！','我们必须依靠我们的士兵进行战斗，所有的士兵都会这么告诉你的。他们还会告诉你，他们正在使用破烂不堪的装备，饥肠辘辘地开向战场！$B$B这就是阿拉希盆地显得非常重要的原因。金属，武器，食物，木材——所有我们所需要的东西都可以从那里获得。$B$B那就是我需要你发挥作用的地方，$N。进入阿拉希盆地，比敌人占据更多的基地，以此来获得战斗的胜利，然后给我带回一箱资源来。','获得阿拉希盆地战斗的胜利，获取一只阿拉希资源箱，然后向避难谷地的玛克里尔中士复命。','你拿到资源了!干得好!我会把这些资源送到我们的军需官那里，然后让他迅速把它们配置给我们的军队。$B$B谢谢你，$N。事实上，不断地完成这样的任务将是获得最终胜利的关键要素。','你拿到资源木箱了吗，$N?如果没有足够的资源，阿拉索联军的士兵可没有办法好好干一仗……') ON DUPLICATE KEY UPDATE Title_loc4='阿拉希盆地的资源！',Details_loc4='我们必须依靠我们的士兵进行战斗，所有的士兵都会这么告诉你的。他们还会告诉你，他们正在使用破烂不堪的装备，饥肠辘辘地开向战场！$B$B这就是阿拉希盆地显得非常重要的原因。金属，武器，食物，木材——所有我们所需要的东西都可以从那里获得。$B$B那就是我需要你发挥作用的地方，$N。进入阿拉希盆地，比敌人占据更多的基地，以此来获得战斗的胜利，然后给我带回一箱资源来。',Objectives_loc4='获得阿拉希盆地战斗的胜利，获取一只阿拉希资源箱，然后向避难谷地的玛克里尔中士复命。',OfferRewardText_loc4='你拿到资源了!干得好!我会把这些资源送到我们的军需官那里，然后让他迅速把它们配置给我们的军队。$B$B谢谢你，$N。事实上，不断地完成这样的任务将是获得最终胜利的关键要素。',RequestItemsText_loc4='你拿到资源木箱了吗，$N?如果没有足够的资源，阿拉索联军的士兵可没有办法好好干一仗……';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10536,'更多的资源','啊，你抢到了更多的资源木箱!没有资源补给的联盟肯定会一败涂地的!$B$B感谢你，$N。你的努力已经为我们所知，并且也为瓦里玛萨斯所知。','虽然在破坏阿拉索联军的补给线方面，污染者做得已经很不错了，但是联盟还在继续对阿拉希盆地进行攻击。我们必须向盆地增派部队，并夺回更多的资源。') ON DUPLICATE KEY UPDATE Title_loc4='更多的资源',OfferRewardText_loc4='啊，你抢到了更多的资源木箱!没有资源补给的联盟肯定会一败涂地的!$B$B感谢你，$N。你的努力已经为我们所知，并且也为瓦里玛萨斯所知。',RequestItemsText_loc4='虽然在破坏阿拉索联军的补给线方面，污染者做得已经很不错了，但是联盟还在继续对阿拉希盆地进行攻击。我们必须向盆地增派部队，并夺回更多的资源。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10537,'洛恩戈鲁，裂心之弓','这就是命运，$N，我的灵魂从未停止过抗争。我必须取回诅咒密码的第一块碎片。只要你肯伸出援手，就可以帮我达成这个未遂的心愿。$B$B在此之前，请替我取回长弓洛恩戈鲁。那是裂心家族世代相传的宝物。$B$B直觉告诉我，肯定是某个恶魔掳走了它。杀死岗哨中的恶魔，直到你找到洛恩戈鲁。','影月谷伊利达雷岗哨的阿托尔的灵魂要你从驻守岗哨的恶魔手中夺得洛恩戈鲁，裂心之弓。','这在我的母语中代表着“英雄居所”的意思。就算现在听起来还是很真实 - 这个世代的英雄都已经死了……$B$B看来似乎永远都会有人接班。','无所畏惧，英雄。到了合适的时机，我就会协助你的……') ON DUPLICATE KEY UPDATE Title_loc4='洛恩戈鲁，裂心之弓',Details_loc4='这就是命运，$N，我的灵魂从未停止过抗争。我必须取回诅咒密码的第一块碎片。只要你肯伸出援手，就可以帮我达成这个未遂的心愿。$B$B在此之前，请替我取回长弓洛恩戈鲁。那是裂心家族世代相传的宝物。$B$B直觉告诉我，肯定是某个恶魔掳走了它。杀死岗哨中的恶魔，直到你找到洛恩戈鲁。',Objectives_loc4='影月谷伊利达雷岗哨的阿托尔的灵魂要你从驻守岗哨的恶魔手中夺得洛恩戈鲁，裂心之弓。',OfferRewardText_loc4='这在我的母语中代表着“英雄居所”的意思。就算现在听起来还是很真实 - 这个世代的英雄都已经死了……$B$B看来似乎永远都会有人接班。',RequestItemsText_loc4='无所畏惧，英雄。到了合适的时机，我就会协助你的……';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10538,'沸腾之血','上次的实验不能算完全失败，至少我保留了一些你带来的血样。血液一经煮沸，血环巫师在邪兽人血液中施加的诅咒就能得以消除。$B$B我需要更多的血样进行研究。从塞斯高的兽人身上收集血环血样，然后将它们投入被诅咒的大锅中煮沸，然后把沸腾之血带回来给我。','将血环血样投入被诅咒的大锅中煮沸，然后将12份沸腾之血交给断背岗哨的药剂师阿尔布雷克。','非常好。现在我能更容易地进行我的测试……$B$B谢谢你，$N。你很有天份。','你弄到沸腾的血了吗，$N?我急着想研究它不想中断……') ON DUPLICATE KEY UPDATE Title_loc4='沸腾之血',Details_loc4='上次的实验不能算完全失败，至少我保留了一些你带来的血样。血液一经煮沸，血环巫师在邪兽人血液中施加的诅咒就能得以消除。$B$B我需要更多的血样进行研究。从塞斯高的兽人身上收集血环血样，然后将它们投入被诅咒的大锅中煮沸，然后把沸腾之血带回来给我。',Objectives_loc4='将血环血样投入被诅咒的大锅中煮沸，然后将12份沸腾之血交给断背岗哨的药剂师阿尔布雷克。',OfferRewardText_loc4='非常好。现在我能更容易地进行我的测试……$B$B谢谢你，$N。你很有天份。',RequestItemsText_loc4='你弄到沸腾的血了吗，$N?我急着想研究它不想中断……';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10539,'回家','$R$C……$B$B嗯，之前有位跟你同族的牧师前来拜访，$N。他说你该返回埃索达跟凯德莫斯会面。似乎这事儿挺紧急的，我们匆匆聊了几句他就离开了。','埃索达的凯德莫斯要你回去与他会面。','圣光引领你回到我这，$N，你的训练才刚要开始。','你好啊年轻的$g牧师:女牧师;。') ON DUPLICATE KEY UPDATE Title_loc4='回家',Details_loc4='$R$C……$B$B嗯，之前有位跟你同族的牧师前来拜访，$N。他说你该返回埃索达跟凯德莫斯会面。似乎这事儿挺紧急的，我们匆匆聊了几句他就离开了。',Objectives_loc4='埃索达的凯德莫斯要你回去与他会面。',OfferRewardText_loc4='圣光引领你回到我这，$N，你的训练才刚要开始。',RequestItemsText_loc4='你好啊年轻的$g牧师:女牧师;。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10540,'诅咒密码 - 阿托尔的命令','一切准备就绪。英雄，这是从我的灵魂中抽离出的一块碎片。它会保护你的安全，帮助你对抗邪恶势力。$B$B伊利达雷岗哨以南的祭坛附近躲藏着一个名叫维内拉图斯的怪物。一旦维内拉图斯出现在灵魂碎片的追踪范围内，我的灵魂猎手就会召唤出他来。$B$B杀了维内拉图斯，取回诅咒密码的第二块碎片。','从维内拉图斯手中夺得诅咒密码的第二块碎片，然后向影月谷伊利达雷岗哨的阿托尔的灵魂复命。$B$B你无法从被灵魂猎手攻击或杀死的怪物身上获得物品和经验值。','<阿尔托逐渐变淡失去了形体。>$B$B看来我的时间快到了，英雄。','你一定要把密码抢回来!') ON DUPLICATE KEY UPDATE Title_loc4='诅咒密码 - 阿托尔的命令',Details_loc4='一切准备就绪。英雄，这是从我的灵魂中抽离出的一块碎片。它会保护你的安全，帮助你对抗邪恶势力。$B$B伊利达雷岗哨以南的祭坛附近躲藏着一个名叫维内拉图斯的怪物。一旦维内拉图斯出现在灵魂碎片的追踪范围内，我的灵魂猎手就会召唤出他来。$B$B杀了维内拉图斯，取回诅咒密码的第二块碎片。',Objectives_loc4='从维内拉图斯手中夺得诅咒密码的第二块碎片，然后向影月谷伊利达雷岗哨的阿托尔的灵魂复命。$B$B你无法从被灵魂猎手攻击或杀死的怪物身上获得物品和经验值。',OfferRewardText_loc4='<阿尔托逐渐变淡失去了形体。>$B$B看来我的时间快到了，英雄。',RequestItemsText_loc4='你一定要把密码抢回来!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10541,'诅咒密码 - 第二块碎片','英雄，谢谢你。没有你的帮助，我的灵魂将永远禁锢在这个被诅咒的地方。$B$B<阿托尔递给你一只带锁的箱子。>$B$B把箱子交给我的父亲，他住在库斯卡水池附近的农场，在遥远的东北方……箱子里面装着洛恩戈鲁和诅咒密码的第二块碎片。$B$B他听闻我的死讯后必定会非常悲伤。答应我，让他相信我是在宁静祥和中离开这个世界的。告诉他我看见了美丽的狩猎场，告诉他我在那儿等他……','将阿托尔的箱子交给影月谷欧鲁诺克农场的欧鲁诺克·裂心。','<欧朗诺克擦掉眼泪对你微笑。>$B$B谢谢你。我答应你，英雄，会以你为名写一首赞颂的歌曲。','<一滴眼泪从欧朗诺克的脸颊落下。>') ON DUPLICATE KEY UPDATE Title_loc4='诅咒密码 - 第二块碎片',Details_loc4='英雄，谢谢你。没有你的帮助，我的灵魂将永远禁锢在这个被诅咒的地方。$B$B<阿托尔递给你一只带锁的箱子。>$B$B把箱子交给我的父亲，他住在库斯卡水池附近的农场，在遥远的东北方……箱子里面装着洛恩戈鲁和诅咒密码的第二块碎片。$B$B他听闻我的死讯后必定会非常悲伤。答应我，让他相信我是在宁静祥和中离开这个世界的。告诉他我看见了美丽的狩猎场，告诉他我在那儿等他……',Objectives_loc4='将阿托尔的箱子交给影月谷欧鲁诺克农场的欧鲁诺克·裂心。',OfferRewardText_loc4='<欧朗诺克擦掉眼泪对你微笑。>$B$B谢谢你。我答应你，英雄，会以你为名写一首赞颂的歌曲。',RequestItemsText_loc4='<一滴眼泪从欧朗诺克的脸颊落下。>';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10542,'他们偷走了我的水烟袋和酒！','塔卡里以前是一个很好很好的巨魔。我来到这个地方教血槌食人魔如何酿酒。但在我教会他们以后，血槌食人魔却将我塔卡里埋在这里不管了，他们让我在慢慢地死去，烂掉！$B$B更可气的是，他们偷走了我的水烟袋！$B$B你愿意帮帮塔卡里吗？去把水烟袋给我找回来。塔卡里认为那些食人魔把水烟袋带到西南边的矿井那里去了。$B$B哦，你到了那里之后，顺便帮我收集一些酒回来！','找回塔卡里的水烟袋和10瓶血槌烈酒。','没错，那就是提洽里说的东西!虽然我不知道那些巨魔放入了什么东西;但我在水烟筒闻到的并不是提洽里的烟草。$B$B没关系，提洽里已经很高兴了。事实上，因为太高兴了所以我还有别的事情要你去做。','嗨，你拿到我的水烟筒还有那些酒了吗?') ON DUPLICATE KEY UPDATE Title_loc4='他们偷走了我的水烟袋和酒！',Details_loc4='塔卡里以前是一个很好很好的巨魔。我来到这个地方教血槌食人魔如何酿酒。但在我教会他们以后，血槌食人魔却将我塔卡里埋在这里不管了，他们让我在慢慢地死去，烂掉！$B$B更可气的是，他们偷走了我的水烟袋！$B$B你愿意帮帮塔卡里吗？去把水烟袋给我找回来。塔卡里认为那些食人魔把水烟袋带到西南边的矿井那里去了。$B$B哦，你到了那里之后，顺便帮我收集一些酒回来！',Objectives_loc4='找回塔卡里的水烟袋和10瓶血槌烈酒。',OfferRewardText_loc4='没错，那就是提洽里说的东西!虽然我不知道那些巨魔放入了什么东西;但我在水烟筒闻到的并不是提洽里的烟草。$B$B没关系，提洽里已经很高兴了。事实上，因为太高兴了所以我还有别的事情要你去做。',RequestItemsText_loc4='嗨，你拿到我的水烟筒还有那些酒了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10543,'葛雷诺克和库尔加，你们完了！','塔卡里一直在等待机会报仇！$B$B第一天，那群该死的食人魔把塔卡里埋在这里，让我等死，带头的好象是葛雷诺克。第二天，从南边来的库尔加又跑来劫掠塔卡里，还踢了我的头。$B$B他们全部都得死！$B$B你可以在血槌哨站的南槌哨塔顶上找到葛雷诺克，而库尔加在刀塔要塞北部边缘的一座建筑物顶上。库尔加周围有很多完全不喝酒的卫兵，但库尔加自己则嗜酒如命，所以你要利用这些酒将他从那些卫兵身边引诱过来。','杀掉葛雷诺克和库尔加。','提洽里很高兴柯尔卡赫还有葛瑞诺克.巴拓伯恩变成跟他一样的下场。$B$B但是提洽里对复仇的渴望还没有得到纾解。还有一件事你必须去做!','你以为提洽里喜欢现在这个样子吗?不!$B$B那么，你已经强制执行我的复仇了吗?葛瑞诺克还有柯尔卡赫已经死了吗?') ON DUPLICATE KEY UPDATE Title_loc4='葛雷诺克和库尔加，你们完了！',Details_loc4='塔卡里一直在等待机会报仇！$B$B第一天，那群该死的食人魔把塔卡里埋在这里，让我等死，带头的好象是葛雷诺克。第二天，从南边来的库尔加又跑来劫掠塔卡里，还踢了我的头。$B$B他们全部都得死！$B$B你可以在血槌哨站的南槌哨塔顶上找到葛雷诺克，而库尔加在刀塔要塞北部边缘的一座建筑物顶上。库尔加周围有很多完全不喝酒的卫兵，但库尔加自己则嗜酒如命，所以你要利用这些酒将他从那些卫兵身边引诱过来。',Objectives_loc4='杀掉葛雷诺克和库尔加。',OfferRewardText_loc4='提洽里很高兴柯尔卡赫还有葛瑞诺克.巴拓伯恩变成跟他一样的下场。$B$B但是提洽里对复仇的渴望还没有得到纾解。还有一件事你必须去做!',RequestItemsText_loc4='你以为提洽里喜欢现在这个样子吗?不!$B$B那么，你已经强制执行我的复仇了吗?葛瑞诺克还有柯尔卡赫已经死了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4,ObjectiveText2_loc4) VALUES (10544,'诅咒你们的氏族！','塔卡里想要报复所有的食人魔！$B$B塔卡里生前是一个非常有影响力的巫医。只要进入到他的坟墓，你就能找到一个充满着邪恶力量的雕像。$B$B在刀塔要塞和血槌哨站的建筑物和塔的入口处使用这个雕像，不过要小心，施法召唤时会出现出一个邪灵，你必须先击败它。当你击败这个邪灵后，它所在的那座建筑物就会被诅咒。$B$B一定要小心，如果你试图诅咒一座已经被诅咒过的建筑物，那么你就又要面对一个邪灵的挑战！','利用邪恶雕像诅咒刀塔要塞的5座建筑物或者哨塔，以及血槌哨站的2座建筑物或者哨塔。','哈哈哈，复仇的滋味真好!$B$B但是，提洽里看的出来你帮我复仇了以后已经想离开了。我了解……活人有他们自己的生活。$B$B这样吧，提洽里的坟墓里面还有很多的好东西。你可以挑一件你最喜欢的!','提洽里一点都不想讲话直到$N使用神像诅咒刀塔氏族还有血槌氏族的建筑物还有高塔!','诅咒刀塔要塞的建筑物','诅咒血槌哨站的建筑物') ON DUPLICATE KEY UPDATE Title_loc4='诅咒你们的氏族！',Details_loc4='塔卡里想要报复所有的食人魔！$B$B塔卡里生前是一个非常有影响力的巫医。只要进入到他的坟墓，你就能找到一个充满着邪恶力量的雕像。$B$B在刀塔要塞和血槌哨站的建筑物和塔的入口处使用这个雕像，不过要小心，施法召唤时会出现出一个邪灵，你必须先击败它。当你击败这个邪灵后，它所在的那座建筑物就会被诅咒。$B$B一定要小心，如果你试图诅咒一座已经被诅咒过的建筑物，那么你就又要面对一个邪灵的挑战！',Objectives_loc4='利用邪恶雕像诅咒刀塔要塞的5座建筑物或者哨塔，以及血槌哨站的2座建筑物或者哨塔。',OfferRewardText_loc4='哈哈哈，复仇的滋味真好!$B$B但是，提洽里看的出来你帮我复仇了以后已经想离开了。我了解……活人有他们自己的生活。$B$B这样吧，提洽里的坟墓里面还有很多的好东西。你可以挑一件你最喜欢的!',RequestItemsText_loc4='提洽里一点都不想讲话直到$N使用神像诅咒刀塔氏族还有血槌氏族的建筑物还有高塔!',ObjectiveText1_loc4='诅咒刀塔要塞的建筑物',ObjectiveText2_loc4='诅咒血槌哨站的建筑物';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4) VALUES (10545,'血槌醉汉','就像巫医塔卡里之前说过的那样，他帮助他的血槌食人魔朋友酿酒，却一直没有说过为什么要这样做。$B$B血槌氏族目前的状况特别窘迫。刀塔氏族一直在压迫他们，他们需要一件新的武器来反抗。$B$B这时候，塔卡里有了一个好主意，为什么不通过完美的酒来壮大自己而削弱敌人呢？唯一的问题就是，塔卡里不知道这招有没有效。$B$B所以，你不如把这些酒带去刀塔氏族那里试试看。','使用血槌酒桶灌醉5个刀塔食人魔。','那真是个好消息!那种酒将会在提洽里接着要你去做的事情里面派上用场。','告诉提洽里……那种酒对他们有效吗?那些刀塔食人魔喜欢喝吗?','灌醉刀塔食人魔') ON DUPLICATE KEY UPDATE Title_loc4='血槌醉汉',Details_loc4='就像巫医塔卡里之前说过的那样，他帮助他的血槌食人魔朋友酿酒，却一直没有说过为什么要这样做。$B$B血槌氏族目前的状况特别窘迫。刀塔氏族一直在压迫他们，他们需要一件新的武器来反抗。$B$B这时候，塔卡里有了一个好主意，为什么不通过完美的酒来壮大自己而削弱敌人呢？唯一的问题就是，塔卡里不知道这招有没有效。$B$B所以，你不如把这些酒带去刀塔氏族那里试试看。',Objectives_loc4='使用血槌酒桶灌醉5个刀塔食人魔。',OfferRewardText_loc4='那真是个好消息!那种酒将会在提洽里接着要你去做的事情里面派上用场。',RequestItemsText_loc4='告诉提洽里……那种酒对他们有效吗?那些刀塔食人魔喜欢喝吗?',ObjectiveText1_loc4='灌醉刀塔食人魔';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10546,'伯拉克，欧鲁诺克之子','在阿托尔外出狩猎、格洛姆托勤练武艺时，伯拉克却醉心于学习。最终他成为一名学者，并离家前往满目疮痍的德拉诺世界。数年后，返家的游子却已改头换面。$B$B敏锐的洞察力和灵活的应变性造就了一位沉默寡言的刺客。$B$B他自信满满地承担起最为艰巨任务：夺回诅咒密码的第三块碎片。$B$B前往南边的日蚀岗哨寻找伯拉克。他就在岗哨附近的石桥边。','前往影月谷的日蚀岗哨附近寻找伯拉克，欧鲁诺克之子。','<柏尔拉克沉默了一会。>$B$B我已经监视这些血精灵好几个礼拜，我想找出他们把毁灭密码第三部藏到哪里去了。$B$B目前为止，我无法得到任何线索。我只知道伊利丹每天都会从黑暗神庙派一位使者来这里。$B$B这个使者身边守卫森严。我已经跟踪他一个礼拜，想找出将使者跟他的守卫分开的方法。可惜，那些守卫从不离开他的身边。','是父亲派你来的吗?') ON DUPLICATE KEY UPDATE Title_loc4='伯拉克，欧鲁诺克之子',Details_loc4='在阿托尔外出狩猎、格洛姆托勤练武艺时，伯拉克却醉心于学习。最终他成为一名学者，并离家前往满目疮痍的德拉诺世界。数年后，返家的游子却已改头换面。$B$B敏锐的洞察力和灵活的应变性造就了一位沉默寡言的刺客。$B$B他自信满满地承担起最为艰巨任务：夺回诅咒密码的第三块碎片。$B$B前往南边的日蚀岗哨寻找伯拉克。他就在岗哨附近的石桥边。',Objectives_loc4='前往影月谷的日蚀岗哨附近寻找伯拉克，欧鲁诺克之子。',OfferRewardText_loc4='<柏尔拉克沉默了一会。>$B$B我已经监视这些血精灵好几个礼拜，我想找出他们把毁灭密码第三部藏到哪里去了。$B$B目前为止，我无法得到任何线索。我只知道伊利丹每天都会从黑暗神庙派一位使者来这里。$B$B这个使者身边守卫森严。我已经跟踪他一个礼拜，想找出将使者跟他的守卫分开的方法。可惜，那些守卫从不离开他的身边。',RequestItemsText_loc4='是父亲派你来的吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10547,'血蓟交易……','要不是我发现了一个重要线索，也许我早就放弃了跟踪……这家伙是个血蓟瘾君子。刚开始我还没有注意到，后来却发现种种迹象都指向这一点……$B$B如果我们能弄到血蓟，事情就好办了。$B$B我曾在沙塔斯城遇见一个名叫托比亚斯的破碎者。$B$B托比亚斯跟血精灵有贸易往来，他将血蓟卖给血精灵，以换取腐烂的鸦人之卵。$B$B此地正西方就是一片鸦人废墟。去那里寻找一枚腐烂的鸦人之卵，然后前往沙塔斯城的贫民窟找到托比亚斯。','位于日蚀岗哨北面石桥旁的欧鲁诺克之子伯拉克要你将一枚腐烂的鸦人之卵交给沙塔斯城中的暴食者托比亚斯。','你有腐烂的阿拉卡蛋?你怎么不早说!我想我们可以成交。$B$B<图比亚斯微笑，露出了满嘴污秽的蛀牙。>','<图比亚斯吓了一跳。>$B$B血蓟?我从来没听过……你是保安官吗?假如你是的话你要跟我说……我有我的权利!') ON DUPLICATE KEY UPDATE Title_loc4='血蓟交易……',Details_loc4='要不是我发现了一个重要线索，也许我早就放弃了跟踪……这家伙是个血蓟瘾君子。刚开始我还没有注意到，后来却发现种种迹象都指向这一点……$B$B如果我们能弄到血蓟，事情就好办了。$B$B我曾在沙塔斯城遇见一个名叫托比亚斯的破碎者。$B$B托比亚斯跟血精灵有贸易往来，他将血蓟卖给血精灵，以换取腐烂的鸦人之卵。$B$B此地正西方就是一片鸦人废墟。去那里寻找一枚腐烂的鸦人之卵，然后前往沙塔斯城的贫民窟找到托比亚斯。',Objectives_loc4='位于日蚀岗哨北面石桥旁的欧鲁诺克之子伯拉克要你将一枚腐烂的鸦人之卵交给沙塔斯城中的暴食者托比亚斯。',OfferRewardText_loc4='你有腐烂的阿拉卡蛋?你怎么不早说!我想我们可以成交。$B$B<图比亚斯微笑，露出了满嘴污秽的蛀牙。>',RequestItemsText_loc4='<图比亚斯吓了一跳。>$B$B血蓟?我从来没听过……你是保安官吗?假如你是的话你要跟我说……我有我的权利!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10548,'悲伤的事实','还记得我跟你提过的那个寻找指环的胖商人吗？这位商人派他那醉心于考古学的儿子外出搜寻古物，可惜此行不顺。我的意思是，他挂了，死在了巨魔手里。$B$B虽然这样说显得冷酷无情，不过这位父亲愿意出重金取回他儿子的徽记。这项任务派你去再适合不过了！$B$B前往东边的巨魔废墟塞布提拉和塞布努瓦，徽记应该就在某个营地的某个箱子里。','从塞布提拉或是塞布努瓦的某个箱子中取出考古学家的徽记，然后向塔奎林的艾拉兰复命。','喔，我的天啊。看了真令人心酸。我相信那个商人会比我还要感激你。$B$B至于酬劳，那个商人付钱订了我的一个特殊库存物品要送给你，选一个吧$g帅哥:美女;!','猎头行动进行的如何呢?') ON DUPLICATE KEY UPDATE Title_loc4='悲伤的事实',Details_loc4='还记得我跟你提过的那个寻找指环的胖商人吗？这位商人派他那醉心于考古学的儿子外出搜寻古物，可惜此行不顺。我的意思是，他挂了，死在了巨魔手里。$B$B虽然这样说显得冷酷无情，不过这位父亲愿意出重金取回他儿子的徽记。这项任务派你去再适合不过了！$B$B前往东边的巨魔废墟塞布提拉和塞布努瓦，徽记应该就在某个营地的某个箱子里。',Objectives_loc4='从塞布提拉或是塞布努瓦的某个箱子中取出考古学家的徽记，然后向塔奎林的艾拉兰复命。',OfferRewardText_loc4='喔，我的天啊。看了真令人心酸。我相信那个商人会比我还要感激你。$B$B至于酬劳，那个商人付钱订了我的一个特殊库存物品要送给你，选一个吧$g帅哥:美女;!',RequestItemsText_loc4='猎头行动进行的如何呢?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10550,'一捆血蓟','我可没说谎。这蛋真是美味中的极品。你从哪儿搞到的？$B$B唔，如果你想要更多的血蓟，只管来找我，咱们各取所需嘛。$B$B这是你要的一捆血蓟。回去找你的头儿吧。','将一捆血蓟交给位于影月谷日蚀岗哨附近石桥处的欧鲁诺克之子伯拉克。','现在可以设下陷阱了!','你取得血蓟了吗?') ON DUPLICATE KEY UPDATE Title_loc4='一捆血蓟',Details_loc4='我可没说谎。这蛋真是美味中的极品。你从哪儿搞到的？$B$B唔，如果你想要更多的血蓟，只管来找我，咱们各取所需嘛。$B$B这是你要的一捆血蓟。回去找你的头儿吧。',Objectives_loc4='将一捆血蓟交给位于影月谷日蚀岗哨附近石桥处的欧鲁诺克之子伯拉克。',OfferRewardText_loc4='现在可以设下陷阱了!',RequestItemsText_loc4='你取得血蓟了吗?';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4) VALUES (10551,'为奥尔多效力','你确定已经做好决定了吗，$N?奥多尔将会欢迎你加入同盟，但是占星者将不会原谅你的这个决定。') ON DUPLICATE KEY UPDATE Title_loc4='为奥尔多效力',OfferRewardText_loc4='你确定已经做好决定了吗，$N?奥多尔将会欢迎你加入同盟，但是占星者将不会原谅你的这个决定。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4) VALUES (10552,'为占星者效力','你确定已经做好决定了吗，$N?占星者将会欢迎你加入同盟，但是奥多尔将不会原谅你的这个决定。') ON DUPLICATE KEY UPDATE Title_loc4='为占星者效力',OfferRewardText_loc4='你确定已经做好决定了吗，$N?占星者将会欢迎你加入同盟，但是奥多尔将不会原谅你的这个决定。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10553,'先知沃雷塔尔','现在你已经做出了选择，$N，你需
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10554,'伊沙娜','现在你已经决定站在奥尔多的一边，你需要向奥尔多的领袖做个自我介绍。$B$B高阶女祭司伊沙娜就在永恒圣光神殿里，去找她吧。','到沙塔斯城的奥尔多高地去，与永恒圣光神殿中的伊沙娜谈一谈。$B$B为奥尔多完成任务将会使你在占星者阵营中的声望等级降低。','欢迎，$N。很高兴你决定加入我们一同进行任务。愿圣光与你同在。') ON DUPLICATE KEY UPDATE Title_loc4='伊沙娜',Details_loc4='现在你已经决定站在奥尔多的一边，你需要向奥尔多的领袖做个自我介绍。$B$B高阶女祭司伊沙娜就在永恒圣光神殿里，去找她吧。',Objectives_loc4='到沙塔斯城的奥尔多高地去，与永恒圣光神殿中的伊沙娜谈一谈。$B$B为奥尔多完成任务将会使你在占星者阵营中的声望等级降低。',OfferRewardText_loc4='欢迎，$N。很高兴你决定加入我们一同进行任务。愿圣光与你同在。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10555,'诡异的魔法','拉什鸦人的魔法非常诡异。他们从自己身上扯下一把羽毛做为魔法材料！$B$B这听起来就很下等。我来希尔瓦纳就是为了研究他们的法术，可惜我一直不敢太靠近拉什鸦巢。$B$B不如你替我跑一趟，设法让他们的法术效果作用在你身上，然后回来向我复命。你还要阅读拉什鸦人放置在拉什鸦巢顶部的一本法术书。$B$B除非你身上长着我看不见的羽毛，不然，我想你必须从鸦人身上收集到足够的羽毛才行。','收集18片拉什鸦人的羽毛。','翻阅拉斯汗阿拉卡留下的破损便签和细长的字条，你发现有一页出现了你曾在迷雾拉斯看过的魔力法阵图案。','你从这本古老的书上发现的粗糙图文中记载着，需要大量的拉斯汗羽毛才能施放书中的该项法术。') ON DUPLICATE KEY UPDATE Title_loc4='诡异的魔法',Details_loc4='拉什鸦人的魔法非常诡异。他们从自己身上扯下一把羽毛做为魔法材料！$B$B这听起来就很下等。我来希尔瓦纳就是为了研究他们的法术，可惜我一直不敢太靠近拉什鸦巢。$B$B不如你替我跑一趟，设法让他们的法术效果作用在你身上，然后回来向我复命。你还要阅读拉什鸦人放置在拉什鸦巢顶部的一本法术书。$B$B除非你身上长着我看不见的羽毛，不然，我想你必须从鸦人身上收集到足够的羽毛才行。',Objectives_loc4='收集18片拉什鸦人的羽毛。',OfferRewardText_loc4='翻阅拉斯汗阿拉卡留下的破损便签和细长的字条，你发现有一页出现了你曾在迷雾拉斯看过的魔力法阵图案。',RequestItemsText_loc4='你从这本古老的书上发现的粗糙图文中记载着，需要大量的拉斯汗羽毛才能施放书中的该项法术。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4) VALUES (10556,'潦草的字迹','书页上绘制的图案显示鸦人在拉什鸦巢的某个法阵中用羽毛施法。$B$B似乎鸦人是在利用这个诡异的法术召唤出卡利鸟的灵魂。','在拉什鸦巢法阵使用一把羽毛。','我不知道该说什么。这个法术非常的奇怪。这不是某种召唤法术或者附魔，而是某种共享或者连结术。$B$B我不了解这个法术的原理，$N。我还要再想想。$B$B但还是感谢你的协助!我想迟早我都会想通的。','真是太棒啦!我等不及要看这个法术的效果了。','让达兰妮尔分析卡利鸟光环') ON DUPLICATE KEY UPDATE Title_loc4='潦草的字迹',Details_loc4='书页上绘制的图案显示鸦人在拉什鸦巢的某个法阵中用羽毛施法。$B$B似乎鸦人是在利用这个诡异的法术召唤出卡利鸟的灵魂。',Objectives_loc4='在拉什鸦巢法阵使用一把羽毛。',OfferRewardText_loc4='我不知道该说什么。这个法术非常的奇怪。这不是某种召唤法术或者附魔，而是某种共享或者连结术。$B$B我不了解这个法术的原理，$N。我还要再想想。$B$B但还是感谢你的协助!我想迟早我都会想通的。',RequestItemsText_loc4='真是太棒啦!我等不及要看这个法术的效果了。',ObjectiveText1_loc4='让达兰妮尔分析卡利鸟光环';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,EndText_loc4) VALUES (10557,'试飞：风动电容器','我造了一个很棒很棒的装置，叫风动电容器，它完美无缺，肯定能正常工作！但……你就说你愿不愿意帮我测试一下吧？$B$B报酬可是绝对非常丰厚喔！$B$B去和我的孪生兄弟拉雷谈谈吧。祝你好运，$N。实验完成以后再回来找我。或者……要是万一你受伤或者挂了的话，你的亲戚将可以拿走你的报酬。','与拉雷·萨普纳波谈一谈，并使用风动电容器。','哦，你成功了!而你身上连一处瘀青还是骨折都没有!你看吧，我告诉你一切都会顺利成功的!$B$B这是给你的报酬，$N，虽然我当初多算了医疗开销而你用不上……所以算你赚到了!','别害怕!你的牺牲都是为了科学，而科学的成长是痛苦的!','测试塔利的装置') ON DUPLICATE KEY UPDATE Title_loc4='试飞：风动电容器',Details_loc4='我造了一个很棒很棒的装置，叫风动电容器，它完美无缺，肯定能正常工作！但……你就说你愿不愿意帮我测试一下吧？$B$B报酬可是绝对非常丰厚喔！$B$B去和我的孪生兄弟拉雷谈谈吧。祝你好运，$N。实验完成以后再回来找我。或者……要是万一你受伤或者挂了的话，你的亲戚将可以拿走你的报酬。',Objectives_loc4='与拉雷·萨普纳波谈一谈，并使用风动电容器。',OfferRewardText_loc4='哦，你成功了!而你身上连一处瘀青还是骨折都没有!你看吧，我告诉你一切都会顺利成功的!$B$B这是给你的报酬，$N，虽然我当初多算了医疗开销而你用不上……所以算你赚到了!',RequestItemsText_loc4='别害怕!你的牺牲都是为了科学，而科学的成长是痛苦的!',EndText_loc4='测试塔利的装置';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10558,'荣耀堡的崇敬','你向我们证明了你的能力，$N。像你这样的人总有一天会成为伟大的领袖。$B$B继续去攻击破碎大厅的敌人，为你自己在我们的士兵中赢得荣誉。如果你没有让我失望，那我就会交给你更重要的任务。','地狱火半岛荣耀堡的远征军指挥官达纳斯·托尔贝恩要求你进入地狱火堡垒的破碎大厅对抗邪兽人，直到你在荣耀堡的声望达到崇敬。','你已经达到我的期望了，$N。未来有美好的事物在等着你。','你要走的路还很长，但是走到最后你就会发现这是值得的。') ON DUPLICATE KEY UPDATE Title_loc4='荣耀堡的崇敬',Details_loc4='你向我们证明了你的能力，$N。像你这样的人总有一天会成为伟大的领袖。$B$B继续去攻击破碎大厅的敌人，为你自己在我们的士兵中赢得荣誉。如果你没有让我失望，那我就会交给你更重要的任务。',Objectives_loc4='地狱火半岛荣耀堡的远征军指挥官达纳斯·托尔贝恩要求你进入地狱火堡垒的破碎大厅对抗邪兽人，直到你在荣耀堡的声望达到崇敬。',OfferRewardText_loc4='你已经达到我的期望了，$N。未来有美好的事物在等着你。',RequestItemsText_loc4='你要走的路还很长，但是走到最后你就会发现这是值得的。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,RequestItemsText_loc4) VALUES (10559,'萨尔玛的崇敬','你向我们证明了你的能力，$c。但是你还要经受更多的考验。$B$B继续攻击地狱火堡垒破碎大厅的邪兽人，这片土地上所有追随萨尔的部落勇士都会知道你的名字。','地狱火半岛萨尔玛的纳兹格雷尔要求你进入地狱火堡垒的破碎大厅对抗邪兽人，直到你在萨尔玛的声望达到崇敬。','你不会令我们失望的，$N。我很确定。') ON DUPLICATE KEY UPDATE Title_loc4='萨尔玛的崇敬',Details_loc4='你向我们证明了你的能力，$c。但是你还要经受更多的考验。$B$B继续攻击地狱火堡垒破碎大厅的邪兽人，这片土地上所有追随萨尔的部落勇士都会知道你的名字。',Objectives_loc4='地狱火半岛萨尔玛的纳兹格雷尔要求你进入地狱火堡垒的破碎大厅对抗邪兽人，直到你在萨尔玛的声望达到崇敬。',RequestItemsText_loc4='你不会令我们失望的，$N。我很确定。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10560,'沙塔尔的崇敬','<阿达尔所发出的平和而宁静的音律略略转向低沉与忧郁。>$B$<你的眼前浮现了一座带有明显纳鲁风格的巨大建筑，你知道那是风暴要塞，它现在已经被凯尔萨斯的军队占领了。他们还把那里的强大力量用于某些极端邪恶的目的。阿达尔承诺，在你为夺回风暴要塞做出应有的贡献之后，将赋予你更重要的使命。>','沙塔斯城的阿达尔希望你通过击败风暴要塞内的凯尔萨斯的军队，在沙塔尔阵营中达到崇敬声望。','<阿达尔对你感到非常的满意。有了你的帮助风暴要塞有一天会从凯尔萨斯的魔爪中被夺回。>','<你的脑海里浮现了一道光，提醒你阿达尔给予你的任务。>') ON DUPLICATE KEY UPDATE Title_loc4='沙塔尔的崇敬',Details_loc4='<阿达尔所发出的平和而宁静的音律略略转向低沉与忧郁。>$B$<你的眼前浮现了一座带有明显纳鲁风格的巨大建筑，你知道那是风暴要塞，它现在已经被凯尔萨斯的军队占领了。他们还把那里的强大力量用于某些极端邪恶的目的。阿达尔承诺，在你为夺回风暴要塞做出应有的贡献之后，将赋予你更重要的使命。>',Objectives_loc4='沙塔斯城的阿达尔希望你通过击败风暴要塞内的凯尔萨斯的军队，在沙塔尔阵营中达到崇敬声望。',OfferRewardText_loc4='<阿达尔对你感到非常的满意。有了你的帮助风暴要塞有一天会从凯尔萨斯的魔爪中被夺回。>',RequestItemsText_loc4='<你的脑海里浮现了一道光，提醒你阿达尔给予你的任务。>';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10561,'时光守护者：崇敬','$r，你已经证明了自己的价值。但是，入侵者依然在设法破坏历史的进程。$B$B我们需要真正的勇士来维护历史，你或许能成为这样的英雄。$B$B继续打败企图改写历史的入侵者，你会获得整个青铜龙族的赞誉。','时光之穴的安多尔姆要求你继续保护时光之穴中的旧希尔斯布莱德丘陵和黑色沼泽事件，直到你在时光守护者阵营的声望达到崇敬。','你已经完成了一般凡人不能完成的事情。你现在已经是青铜龙军团信赖的朋友了。$B$B你所拥有的声望同时也为你带来更多的责任，$N。不论我们的敌人是从哪里来的，你必须继续守卫时光线，$B$B','青铜龙军团的声望不是那么容易就可以获得的。') ON DUPLICATE KEY UPDATE Title_loc4='时光守护者：崇敬',Details_loc4='$r，你已经证明了自己的价值。但是，入侵者依然在设法破坏历史的进程。$B$B我们需要真正的勇士来维护历史，你或许能成为这样的英雄。$B$B继续打败企图改写历史的入侵者，你会获得整个青铜龙族的赞誉。',Objectives_loc4='时光之穴的安多尔姆要求你继续保护时光之穴中的旧希尔斯布莱德丘陵和黑色沼泽事件，直到你在时光守护者阵营的声望达到崇敬。',OfferRewardText_loc4='你已经完成了一般凡人不能完成的事情。你现在已经是青铜龙军团信赖的朋友了。$B$B你所拥有的声望同时也为你带来更多的责任，$N。不论我们的敌人是从哪里来的，你必须继续守卫时光线，$B$B',RequestItemsText_loc4='青铜龙军团的声望不是那么容易就可以获得的。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10562,'兵临城下！','保持警惕，$r。燃烧军团的攻击从没有停止过。$B$B他们目前盘踞在西南方的军团要塞，每天召唤出的地狱火总能像潮水般朝我们这里涌来。我们消灭敌人的速度根本就跟不上他们补充兵力的速度。$B$B现在，士兵们个个都精疲力竭，我也不知道他们还能撑多久了。$N，请你向我们伸出援手吧，帮助我们对抗军团。冲上前线，阻止那些地狱火的攻势！','蛮锤要塞外的空军指挥官努埃恩要求你杀死10个地狱火攻击者。','感谢你减轻了我们的压力，$N。多了你的帮助，还有其它人的帮助，我们还撑的下去。不幸的是，勉强支撑是不够的。我们要主动出击。','你已经累了吗，$C?') ON DUPLICATE KEY UPDATE Title_loc4='兵临城下！',Details_loc4='保持警惕，$r。燃烧军团的攻击从没有停止过。$B$B他们目前盘踞在西南方的军团要塞，每天召唤出的地狱火总能像潮水般朝我们这里涌来。我们消灭敌人的速度根本就跟不上他们补充兵力的速度。$B$B现在，士兵们个个都精疲力竭，我也不知道他们还能撑多久了。$N，请你向我们伸出援手吧，帮助我们对抗军团。冲上前线，阻止那些地狱火的攻势！',Objectives_loc4='蛮锤要塞外的空军指挥官努埃恩要求你杀死10个地狱火攻击者。',OfferRewardText_loc4='感谢你减轻了我们的压力，$N。多了你的帮助，还有其它人的帮助，我们还撑的下去。不幸的是，勉强支撑是不够的。我们要主动出击。',RequestItemsText_loc4='你已经累了吗，$C?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText3_loc4) VALUES (10563,'前往军团要塞','军团要塞固若金汤，难以攻取。老实说，我军也没有足够的兵力发动袭击。$N，所有的希望都寄托在你身上。$B$B从我们目前掌握的零碎情报来看，燃烧军团正在要塞中囤积和准备他们的地狱火大军。穿上这套伪装潜入军团要塞，打探他们的秘密计划。$B$B或许你能从燃烧军团指挥官们的谈话中偷听到一些东西。祝你好运，$N。','前往军团要塞寻找军团通讯装置。在伪装状态下站在军团通讯装置附近，偷听燃烧军团的计划。完成任务后向蛮锤要塞的空军指挥官努埃恩复命。','<空军指挥官奴艾恩听了你的报告，你的每一句话都更加的提高了他的警戒心。>$B$B你是说他们拥有充分的炼狱火可以猛烈的炮轰我们?假如我们不能阻止他们进行下一步计划，蛮锤要塞就玩完了。','你发现了什么?','偷听燃烧军团的计划') ON DUPLICATE KEY UPDATE Title_loc4='前往军团要塞',Details_loc4='军团要塞固若金汤，难以攻取。老实说，我军也没有足够的兵力发动袭击。$N，所有的希望都寄托在你身上。$B$B从我们目前掌握的零碎情报来看，燃烧军团正在要塞中囤积和准备他们的地狱火大军。穿上这套伪装潜入军团要塞，打探他们的秘密计划。$B$B或许你能从燃烧军团指挥官们的谈话中偷听到一些东西。祝你好运，$N。',Objectives_loc4='前往军团要塞寻找军团通讯装置。在伪装状态下站在军团通讯装置附近，偷听燃烧军团的计划。完成任务后向蛮锤要塞的空军指挥官努埃恩复命。',OfferRewardText_loc4='<空军指挥官奴艾恩听了你的报告，你的每一句话都更加的提高了他的警戒心。>$B$B你是说他们拥有充分的炼狱火可以猛烈的炮轰我们?假如我们不能阻止他们进行下一步计划，蛮锤要塞就玩完了。',RequestItemsText_loc4='你发现了什么?',ObjectiveText3_loc4='偷听燃烧军团的计划';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText2_loc4) VALUES (10564,'炸毁地狱火！','我们装配出来的这玩意虽然其丑无比，但是它能消灭军团要塞的地狱火大军。瞧瞧魔能机甲能量核心对恶臭之池的影响，这东西蕴藏的爆炸威力可不容小觑。$B$B如果在军团要塞的绿色雕文中心引爆这个邪能炸弹，应该可以一举歼灭所有地狱火。','站在军团要塞的绿色雕文上使用魔能炸弹消灭地狱火，然后向蛮锤要塞的空军指挥官努埃恩复命。','做的好，$N!我希望我可以说燃烧军团在遭遇了这样的挫折之后会有放弃的念头，但是你我都知道这是不可能的事情。你在侦察任务中查探过的死亡熔炉将是我们的下一个目标。','你找到摧毁军团囤积炼狱火的方法了吗?','摧毁军团要塞的地狱火') ON DUPLICATE KEY UPDATE Title_loc4='炸毁地狱火！',Details_loc4='我们装配出来的这玩意虽然其丑无比，但是它能消灭军团要塞的地狱火大军。瞧瞧魔能机甲能量核心对恶臭之池的影响，这东西蕴藏的爆炸威力可不容小觑。$B$B如果在军团要塞的绿色雕文中心引爆这个邪能炸弹，应该可以一举歼灭所有地狱火。',Objectives_loc4='站在军团要塞的绿色雕文上使用魔能炸弹消灭地狱火，然后向蛮锤要塞的空军指挥官努埃恩复命。',OfferRewardText_loc4='做的好，$N!我希望我可以说燃烧军团在遭遇了这样的挫折之后会有放弃的念头，但是你我都知道这是不可能的事情。你在侦察任务中查探过的死亡熔炉将是我们的下一个目标。',RequestItemsText_loc4='你找到摧毁军团囤积炼狱火的方法了吗?',ObjectiveText2_loc4='摧毁军团要塞的地狱火';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10565,'维克鸦巢水晶','多年来维克鸦人一直是我们的眼中钉。他们信奉某种奇怪的宗教，行为也因此变得癫狂。据说他们身上携带的维克鸦巢水晶具有某种邪恶的用途。$B$B我对维克鸦人的宗教仪式了解得不多，只知道他们利用维克鸦巢法阵对维克鸦巢水晶充能。杀入维克鸦巢，直到你找到水晶，然后将充能的水晶带回来供我研究。','在维克鸦巢法阵使用维克鸦巢水晶，来制造充能的维克鸦巢水晶。','哦，看它发光的样子!我一定要马上试试它。','维克尼尔的阿拉卡多年来一直是和善的一族，但是现在某种东西正在煽动他们。') ON DUPLICATE KEY UPDATE Title_loc4='维克鸦巢水晶',Details_loc4='多年来维克鸦人一直是我们的眼中钉。他们信奉某种奇怪的宗教，行为也因此变得癫狂。据说他们身上携带的维克鸦巢水晶具有某种邪恶的用途。$B$B我对维克鸦人的宗教仪式了解得不多，只知道他们利用维克鸦巢法阵对维克鸦巢水晶充能。杀入维克鸦巢，直到你找到水晶，然后将充能的水晶带回来供我研究。',Objectives_loc4='在维克鸦巢法阵使用维克鸦巢水晶，来制造充能的维克鸦巢水晶。',OfferRewardText_loc4='哦，看它发光的样子!我一定要马上试试它。',RequestItemsText_loc4='维克尼尔的阿拉卡多年来一直是和善的一族，但是现在某种东西正在煽动他们。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4,ObjectiveText2_loc4,ObjectiveText3_loc4,ObjectiveText4_loc4) VALUES (10566,'测试魔杖','我制作了四根魔杖，它们能强化维克鸦巢水晶的能量。带上这四根魔杖前往托格玛洞穴，在鸦人的食人魔奴隶身上试验它们的效果。$B$B每根魔杖都需要一颗充能的维克鸦巢水晶才能发挥效用。$B$B当你找出效果最好的那根魔杖后，回来向我复命。','利用鸦人的食人魔奴隶试验德尔托克制作的四根魔杖。每根魔杖都需要一颗充能的维克鸦巢水晶才能发挥效用。','这个资料非常的有用，$N。我将会进一步改良它的设计并且看看我们能否扩大它的用途。','我热切的等待你的测试结果，$N。','测试第一根魔杖','测试第二根魔杖','测试第三根魔杖','测试第四根魔杖') ON DUPLICATE KEY UPDATE Title_loc4='测试魔杖',Details_loc4='我制作了四根魔杖，它们能强化维克鸦巢水晶的能量。带上这四根魔杖前往托格玛洞穴，在鸦人的食人魔奴隶身上试验它们的效果。$B$B每根魔杖都需要一颗充能的维克鸦巢水晶才能发挥效用。$B$B当你找出效果最好的那根魔杖后，回来向我复命。',Objectives_loc4='利用鸦人的食人魔奴隶试验德尔托克制作的四根魔杖。每根魔杖都需要一颗充能的维克鸦巢水晶才能发挥效用。',OfferRewardText_loc4='这个资料非常的有用，$N。我将会进一步改良它的设计并且看看我们能否扩大它的用途。',RequestItemsText_loc4='我热切的等待你的测试结果，$N。',ObjectiveText1_loc4='测试第一根魔杖',ObjectiveText2_loc4='测试第二根魔杖',ObjectiveText3_loc4='测试第三根魔杖',ObjectiveText4_loc4='测试第四根魔杖';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10567,'制造坠饰','卢安荒野的鸦人是乌鸦之神的狂热崇拜者，整个氏族都听从乌鸦预言者的号令。$B$B鸦人们相信预言者为他们传达乌鸦之神的教义，是氏族的守护者。$B$B乌鸦预言者在鸦人中享有绝对的控制力，因此我们需要预言者佩戴的魔法坠饰。$B$B杀死卢安鸦人，将卢安利爪放置在祭坛处以吸引乌鸦预言者的注意。','收集6只卢安利爪，在卢安预言法阵中使用它们召唤一名乌鸦预言者。杀死乌鸦预言者，将预言者的坠饰交给卢安荒野的坦莫。','你得到了!$B$B有了这个坠饰，我就可以使你与葛瑞许纳什的阿拉卡同调化，这样就可以让你了解他们的语言。$B$B以这种方式，我们就可以进一步的了解阿拉卡还有他们神只的天性。我需要你的帮助才能完成这件事。','一旦乌鸦神谕使察觉到你在攻击他的同胞，他会立刻开始反击。') ON DUPLICATE KEY UPDATE Title_loc4='制造坠饰',Details_loc4='卢安荒野的鸦人是乌鸦之神的狂热崇拜者，整个氏族都听从乌鸦预言者的号令。$B$B鸦人们相信预言者为他们传达乌鸦之神的教义，是氏族的守护者。$B$B乌鸦预言者在鸦人中享有绝对的控制力，因此我们需要预言者佩戴的魔法坠饰。$B$B杀死卢安鸦人，将卢安利爪放置在祭坛处以吸引乌鸦预言者的注意。',Objectives_loc4='收集6只卢安利爪，在卢安预言法阵中使用它们召唤一名乌鸦预言者。杀死乌鸦预言者，将预言者的坠饰交给卢安荒野的坦莫。',OfferRewardText_loc4='你得到了!$B$B有了这个坠饰，我就可以使你与葛瑞许纳什的阿拉卡同调化，这样就可以让你了解他们的语言。$B$B以这种方式，我们就可以进一步的了解阿拉卡还有他们神只的天性。我需要你的帮助才能完成这件事。',RequestItemsText_loc4='一旦乌鸦神谕使察觉到你在攻击他的同胞，他会立刻开始反击。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10568,'巴尔里石板','影月谷中心的火山正是那位可怕的术士古尔丹数十年前的杰作，也因此，它被命名为古尔丹之手。当初，在这里的西南方曾有一座名叫巴尔里的德莱尼村落。火山爆发当日，大多数的村民和许多神圣古器都那场灾难中尽数被火山岩浆淹没，埋入了地底。$B$B最近，一支名叫灰舌的破碎者氏族奉伊利丹之命，在巴尔里废墟展开了一系列挖掘工作。他们的目标毫无疑问就是找回那些神器。我们必须利用这个机会夺回巴尔里石板。据说，那上面记载着许多卡拉波神殿——也就是黑暗神殿的秘密。','沙塔尔祭坛的学者希拉要你收集12块巴尔里石板，它们散落在巴尔里废墟中，那里的灰舌工人身上也携带着这种石板。$B$B为奥尔多阵营完成任务将降低你在占星者阵营中的声望等级。','巴瑞碑文!没错，这也许会提供我们非常有用的资料。','你找到碑文了吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='巴尔里石板',Details_loc4='影月谷中心的火山正是那位可怕的术士古尔丹数十年前的杰作，也因此，它被命名为古尔丹之手。当初，在这里的西南方曾有一座名叫巴尔里的德莱尼村落。火山爆发当日，大多数的村民和许多神圣古器都那场灾难中尽数被火山岩浆淹没，埋入了地底。$B$B最近，一支名叫灰舌的破碎者氏族奉伊利丹之命，在巴尔里废墟展开了一系列挖掘工作。他们的目标毫无疑问就是找回那些神器。我们必须利用这个机会夺回巴尔里石板。据说，那上面记载着许多卡拉波神殿——也就是黑暗神殿的秘密。',Objectives_loc4='沙塔尔祭坛的学者希拉要你收集12块巴尔里石板，它们散落在巴尔里废墟中，那里的灰舌工人身上也携带着这种石板。$B$B为奥尔多阵营完成任务将降低你在占星者阵营中的声望等级。',OfferRewardText_loc4='巴瑞碑文!没错，这也许会提供我们非常有用的资料。',RequestItemsText_loc4='你找到碑文了吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10569,'斯克瑟隆废墟','从斥候带回的消息来看，附近那座废弃的鸦人营地的情形令人堪忧。$B$B鸦人魔法师们阴魂不散，他们拥有的强大力量超出了我们的想象。这些幽灵们似乎在有组织地预谋着什么，可惜我们对此所知有限。面对潜伏的危机，我们绝不能无动于衷！$B$B从这里向北走，到死亡熔炉西北方的斯克瑟隆废墟搜寻线索。','从斯克瑟隆废墟黑暗教团的鸦人身上夺得斯克瑟隆指挥官的日记 - 第1页、斯克瑟隆指挥官的日记 - 第2页，以及斯克瑟隆指挥官的日记 - 第3页，将它们交给狮鹫骑士基尔兰。','<凯兰快速的翻阅日记页面。>$B$B大部分的内容都难以辨识，但是我可以东拼西凑的看出内容是关于一个偏向邪恶的法术准备仪式、受害者还有堕落的场景。还有一个奇怪的注明关于一个''背弃者''。','你发现了什么?') ON DUPLICATE KEY UPDATE Title_loc4='斯克瑟隆废墟',Details_loc4='从斥候带回的消息来看，附近那座废弃的鸦人营地的情形令人堪忧。$B$B鸦人魔法师们阴魂不散，他们拥有的强大力量超出了我们的想象。这些幽灵们似乎在有组织地预谋着什么，可惜我们对此所知有限。面对潜伏的危机，我们绝不能无动于衷！$B$B从这里向北走，到死亡熔炉西北方的斯克瑟隆废墟搜寻线索。',Objectives_loc4='从斯克瑟隆废墟黑暗教团的鸦人身上夺得斯克瑟隆指挥官的日记 - 第1页、斯克瑟隆指挥官的日记 - 第2页，以及斯克瑟隆指挥官的日记 - 第3页，将它们交给狮鹫骑士基尔兰。',OfferRewardText_loc4='<凯兰快速的翻阅日记页面。>$B$B大部分的内容都难以辨识，但是我可以东拼西凑的看出内容是关于一个偏向邪恶的法术准备仪式、受害者还有堕落的场景。还有一个奇怪的注明关于一个''背弃者''。',RequestItemsText_loc4='你发现了什么?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10570,'血蓟瘾君子','<伯拉克接过血蓟，放到鼻子下嗅了嗅。>$B$B真刺鼻……$B$B把这包东西放在石桥的另一端。特使每天都会在日蚀岗哨四处巡视；当他发现血蓟时，一定会撇下护卫，迫不及待地跑来捡起包裹。你知道，血精灵最瞧不起那些对血蓟上瘾的家伙。如果他的族人发现了这一点……$B$B你只需埋伏在一旁，等待特使遣散他的护卫，然后给他致命一击！杀掉特使，取回他携带的信件。','将怒风的信件交给位于影月谷日蚀岗哨附近石桥处的欧鲁诺克之子伯拉克。','<柏尔拉克从你身上拿走了信件并且阅读它。>$B$B这些耍小聪明的精灵!这是伊利丹的指令，指示他们下一封密信藏在哪里。很显然的，他们一直更改藏信的地点。这封信件并没有告诉我们下一封密信藏在哪里……假如我们可以把这封公文送到他们的手上，我们就可以知道他们藏匿下一封密信的地点。$B$B可惜这封公文的封条已经被拆开了，要交还给他们已经不可能了。$B$B嗯，现在还不行……','动作快一点，$g男孩:女孩;。') ON DUPLICATE KEY UPDATE Title_loc4='血蓟瘾君子',Details_loc4='<伯拉克接过血蓟，放到鼻子下嗅了嗅。>$B$B真刺鼻……$B$B把这包东西放在石桥的另一端。特使每天都会在日蚀岗哨四处巡视；当他发现血蓟时，一定会撇下护卫，迫不及待地跑来捡起包裹。你知道，血精灵最瞧不起那些对血蓟上瘾的家伙。如果他的族人发现了这一点……$B$B你只需埋伏在一旁，等待特使遣散他的护卫，然后给他致命一击！杀掉特使，取回他携带的信件。',Objectives_loc4='将怒风的信件交给位于影月谷日蚀岗哨附近石桥处的欧鲁诺克之子伯拉克。',OfferRewardText_loc4='<柏尔拉克从你身上拿走了信件并且阅读它。>$B$B这些耍小聪明的精灵!这是伊利丹的指令，指示他们下一封密信藏在哪里。很显然的，他们一直更改藏信的地点。这封信件并没有告诉我们下一封密信藏在哪里……假如我们可以把这封公文送到他们的手上，我们就可以知道他们藏匿下一封密信的地点。$B$B可惜这封公文的封条已经被拆开了，要交还给他们已经不可能了。$B$B嗯，现在还不行……',RequestItemsText_loc4='动作快一点，$g男孩:女孩;。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10571,'长者奥洛努','根据巴尔里石板的记载，巴尔里废墟中埋藏着一件名为卡拉波勋章的神器。在过去，德莱尼人当中只有最高阶的祭司团成员才有资格得到这件神器，从而也获得了自由进出卡拉波神殿的权利。$B$B我们现在必须查明灰舌破碎者们是否已从废墟中挖掘出了这枚勋章。这件神器一定可以对我们抵抗伊利丹有所帮助。$B$B现在，驻守在巴尔里废墟的灰舌军官——长者奥洛努每天都会接到他的上司阿卡玛的书面指令。去把阿卡玛的命令带来给我。','沙塔尔祭坛的学者希拉要求你从巴尔里废墟的长者奥洛努手中夺得阿卡玛的命令。$B$B为奥尔多阵营完成任务将降低你在占星者阵营中的声望等级。','阿卡玛的亲笔书信。像他这样如此有智慧又被敬爱的人竟然会变成现在这个样子，真是想起来也叫我难过。','你带回来了什么新消息了吗，$N?我们快没有时间了。') ON DUPLICATE KEY UPDATE Title_loc4='长者奥洛努',Details_loc4='根据巴尔里石板的记载，巴尔里废墟中埋藏着一件名为卡拉波勋章的神器。在过去，德莱尼人当中只有最高阶的祭司团成员才有资格得到这件神器，从而也获得了自由进出卡拉波神殿的权利。$B$B我们现在必须查明灰舌破碎者们是否已从废墟中挖掘出了这枚勋章。这件神器一定可以对我们抵抗伊利丹有所帮助。$B$B现在，驻守在巴尔里废墟的灰舌军官——长者奥洛努每天都会接到他的上司阿卡玛的书面指令。去把阿卡玛的命令带来给我。',Objectives_loc4='沙塔尔祭坛的学者希拉要求你从巴尔里废墟的长者奥洛努手中夺得阿卡玛的命令。$B$B为奥尔多阵营完成任务将降低你在占星者阵营中的声望等级。',OfferRewardText_loc4='阿卡玛的亲笔书信。像他这样如此有智慧又被敬爱的人竟然会变成现在这个样子，真是想起来也叫我难过。',RequestItemsText_loc4='你带回来了什么新消息了吗，$N?我们快没有时间了。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10572,'制造炸弹','燃烧军团意欲在前往黑暗神殿的行军途中摧毁蛮锤要塞，我们绝不能让他们的奸计得逞。$B$B$N，要阻止这场战事只有一个办法，那就是使用威力强大的炸弹将军团要塞的地狱火大军统统炸毁。$B$B军团要塞附近有一片恶臭之池，那里的魔能机甲动力核心可用作炸药。那些魔能机甲附近另一处废墟中的魔能机甲护板可用作炸弹外壳。','将魔能机甲动力核心和魔能机甲护板交给蛮锤要塞的空军指挥官努埃恩。','<空军指挥官将能量核心插入铠甲并密封仪器焊缝，点点头。>$B$B这应该可以了。如果要我说，这足以制造一个相当大的爆炸。','<你将材料交给空军指挥官。>') ON DUPLICATE KEY UPDATE Title_loc4='制造炸弹',Details_loc4='燃烧军团意欲在前往黑暗神殿的行军途中摧毁蛮锤要塞，我们绝不能让他们的奸计得逞。$B$B$N，要阻止这场战事只有一个办法，那就是使用威力强大的炸弹将军团要塞的地狱火大军统统炸毁。$B$B军团要塞附近有一片恶臭之池，那里的魔能机甲动力核心可用作炸药。那些魔能机甲附近另一处废墟中的魔能机甲护板可用作炸弹外壳。',Objectives_loc4='将魔能机甲动力核心和魔能机甲护板交给蛮锤要塞的空军指挥官努埃恩。',OfferRewardText_loc4='<空军指挥官将能量核心插入铠甲并密封仪器焊缝，点点头。>$B$B这应该可以了。如果要我说，这足以制造一个相当大的爆炸。',RequestItemsText_loc4='<你将材料交给空军指挥官。>';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10573,'死亡熔炉','从你在军团要塞查探到的情况来看，暗影议会正在死亡熔炉帮助燃烧军团制造地狱火。我曾派出侦察小队去探察死亡熔炉的动向，可这帮废柴竟然一事无成。$B$B如果我们不采取行动的话，他们很快就可以重新纠集起新的地狱火大军，数量堪比你在军团要塞炸掉的兵团。$B$B立刻前往西北方的死亡熔炉哨塔，向奉命在那儿监视死亡熔炉的伊万·蛮翼报到。','前往死亡熔炉哨塔向伊万·蛮翼报到。','<这个矮人点了点头。>$B$B有人支持的感觉真好。我们对于暗影议会的行动掌握了初步的资讯，但是要等我们开始对他们展开行动我才能安心。','空军指挥官终于派出支持部队了吗?') ON DUPLICATE KEY UPDATE Title_loc4='死亡熔炉',Details_loc4='从你在军团要塞查探到的情况来看，暗影议会正在死亡熔炉帮助燃烧军团制造地狱火。我曾派出侦察小队去探察死亡熔炉的动向，可这帮废柴竟然一事无成。$B$B如果我们不采取行动的话，他们很快就可以重新纠集起新的地狱火大军，数量堪比你在军团要塞炸掉的兵团。$B$B立刻前往西北方的死亡熔炉哨塔，向奉命在那儿监视死亡熔炉的伊万·蛮翼报到。',Objectives_loc4='前往死亡熔炉哨塔向伊万·蛮翼报到。',OfferRewardText_loc4='<这个矮人点了点头。>$B$B有人支持的感觉真好。我们对于暗影议会的行动掌握了初步的资讯，但是要等我们开始对他们展开行动我才能安心。',RequestItemsText_loc4='空军指挥官终于派出支持部队了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10574,'灰舌腐蚀者','阿卡玛在指令中提到，被挖掘出来的4块勋章碎片分别由四位灰舌腐蚀者负责保管。这些灰舌腐蚀者本都是氏族中的萨满祭司，如今却转而与他们曾经崇拜与侍奉的元素为敌，唉……$B$B气之腐蚀者哈鲁姆目前在灵翼小径；地之腐蚀者埃肯尼和火之腐蚀者乌拉鲁，曾有人看见他们在古尔丹之手附近的魔能熔池旁出没；水之腐蚀者拉坎恩据说在库斯卡岗哨附近。$B$B杀死他们，取回全部的勋章碎片。','从哈鲁姆、埃肯尼、拉坎恩和乌拉鲁手中夺得他们的勋章碎片，并把这些碎片交给影月谷沙塔尔祭坛的学者希拉。$B$B为奥尔多阵营完成任务将降低你在占星者阵营中的声望等级。','没错!这就是四个勋章碎片。现在，来将它们结合在一起……','你已经取回四个勋章碎片了吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='灰舌腐蚀者',Details_loc4='阿卡玛在指令中提到，被挖掘出来的4块勋章碎片分别由四位灰舌腐蚀者负责保管。这些灰舌腐蚀者本都是氏族中的萨满祭司，如今却转而与他们曾经崇拜与侍奉的元素为敌，唉……$B$B气之腐蚀者哈鲁姆目前在灵翼小径；地之腐蚀者埃肯尼和火之腐蚀者乌拉鲁，曾有人看见他们在古尔丹之手附近的魔能熔池旁出没；水之腐蚀者拉坎恩据说在库斯卡岗哨附近。$B$B杀死他们，取回全部的勋章碎片。',Objectives_loc4='从哈鲁姆、埃肯尼、拉坎恩和乌拉鲁手中夺得他们的勋章碎片，并把这些碎片交给影月谷沙塔尔祭坛的学者希拉。$B$B为奥尔多阵营完成任务将降低你在占星者阵营中的声望等级。',OfferRewardText_loc4='没错!这就是四个勋章碎片。现在，来将它们结合在一起……',RequestItemsText_loc4='你已经取回四个勋章碎片了吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10575,'守望者的牢笼','你取回的碎片只能拼凑出半块卡拉波勋章。另一半必定在灰舌破碎者的首领阿卡玛手中。$B$B派你去执行这项任务令我心中隐隐有些不安，因为阿卡玛是个邪恶而狡诈的家伙。$B$B据说，他甚至还和氏族中那些最卑劣残忍的成员——灰舌死誓者一起在守望者牢笼中设立了刑讯室。$B$B现在，我要你立刻前往刑讯室寻找阿卡玛的下落。如果有必要的话，你可以将他的副官萨诺鲁抓来审问。','学者希拉要求你进入巴尔里废墟以南的守望者牢笼，从萨诺鲁口中审问出阿卡玛的下落。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。','我们正在等着你，$N。阿卡玛说你迟早会来的。') ON DUPLICATE KEY UPDATE Title_loc4='守望者的牢笼',Details_loc4='你取回的碎片只能拼凑出半块卡拉波勋章。另一半必定在灰舌破碎者的首领阿卡玛手中。$B$B派你去执行这项任务令我心中隐隐有些不安，因为阿卡玛是个邪恶而狡诈的家伙。$B$B据说，他甚至还和氏族中那些最卑劣残忍的成员——灰舌死誓者一起在守望者牢笼中设立了刑讯室。$B$B现在，我要你立刻前往刑讯室寻找阿卡玛的下落。如果有必要的话，你可以将他的副官萨诺鲁抓来审问。',Objectives_loc4='学者希拉要求你进入巴尔里废墟以南的守望者牢笼，从萨诺鲁口中审问出阿卡玛的下落。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。',OfferRewardText_loc4='我们正在等着你，$N。阿卡玛说你迟早会来的。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10576,'影月谷的乔装者','<伯拉克打量着你。>$B$B这事儿有些棘手，不过我应该能办到。$B$B$N，我打算把你伪装成一名伊利达雷血精灵。但首先你得给我找些血精灵的护甲来，护甲必须保持整洁，不能有任何血渍！这样才不会引起怀疑。$B$B替我收集一些护甲，剩下的事就交给我吧。$B$B伪装完毕后，你就要亲自把口信传达给他们的总指挥官了。','将6件日蚀护甲交给位于影月谷日蚀岗哨附近石桥处的欧鲁诺克之子伯拉克。','做的好，$N。我希望你是一个很好的$g男演员:女演员;。在我伟大的计划里下一步将需要一些戏剧成分!','这太复杂了，$r。你不会了解的。') ON DUPLICATE KEY UPDATE Title_loc4='影月谷的乔装者',Details_loc4='<伯拉克打量着你。>$B$B这事儿有些棘手，不过我应该能办到。$B$B$N，我打算把你伪装成一名伊利达雷血精灵。但首先你得给我找些血精灵的护甲来，护甲必须保持整洁，不能有任何血渍！这样才不会引起怀疑。$B$B替我收集一些护甲，剩下的事就交给我吧。$B$B伪装完毕后，你就要亲自把口信传达给他们的总指挥官了。',Objectives_loc4='将6件日蚀护甲交给位于影月谷日蚀岗哨附近石桥处的欧鲁诺克之子伯拉克。',OfferRewardText_loc4='做的好，$N。我希望你是一个很好的$g男演员:女演员;。在我伟大的计划里下一步将需要一些戏剧成分!',RequestItemsText_loc4='这太复杂了，$r。你不会了解的。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,EndText_loc4) VALUES (10577,'伊利丹的信使……','带上这件血精灵伪装前往日蚀岗哨。记得及时换上伪装。日蚀血精灵大多不可能识破你的真面目，一路畅行无阻，你便可以见到总指挥官卢斯克。$B$B找到卢斯克后，告诉他诅咒密码的下一个藏匿点。$N，这场戏你可得用心去演。摆足架势，把自己想象成传达伊利丹口信的长官。这样必定能唬到他！$B$B哦，记得避开日蚀龙鹰，它们可以识破你的伪装。','位于影月谷日蚀岗哨附近石桥处的欧鲁诺克之子伯拉克要求你将伊利丹的口信传达给日蚀岗哨的总指挥官卢斯克。','现在你只需要去拿到那个密件而已。很简单，对吧?','这真是个巧妙的伪装。除了步行以外的其它动作都会中断维持伪装的魔法力量。','传达伊利丹的口信') ON DUPLICATE KEY UPDATE Title_loc4='伊利丹的信使……',Details_loc4='带上这件血精灵伪装前往日蚀岗哨。记得及时换上伪装。日蚀血精灵大多不可能识破你的真面目，一路畅行无阻，你便可以见到总指挥官卢斯克。$B$B找到卢斯克后，告诉他诅咒密码的下一个藏匿点。$N，这场戏你可得用心去演。摆足架势，把自己想象成传达伊利丹口信的长官。这样必定能唬到他！$B$B哦，记得避开日蚀龙鹰，它们可以识破你的伪装。',Objectives_loc4='位于影月谷日蚀岗哨附近石桥处的欧鲁诺克之子伯拉克要求你将伊利丹的口信传达给日蚀岗哨的总指挥官卢斯克。',OfferRewardText_loc4='现在你只需要去拿到那个密件而已。很简单，对吧?',RequestItemsText_loc4='这真是个巧妙的伪装。除了步行以外的其它动作都会中断维持伪装的魔法力量。',EndText_loc4='传达伊利丹的口信';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10578,'诅咒密码 - 伯拉克的命令','不能让祖鲁希德拿到诅咒密码的碎片。你必须抢在亵渎者鲁尔将它转交给祖鲁希德之前劫回碎片。$B$B在这里的正东方，灵翼平原对面便是龙喉要塞，鲁尔就在龙喉要塞和群星圣殿之间的某处。一旦你发现他的踪迹，就迅速杀掉他！$N，从我们套出的情报来看，鲁尔是个不好对付的家伙。请千万小心。$B$B夺得诅咒密码的碎片后就回来向我复命。','从亵渎者鲁尔手中夺回诅咒密码的第二块碎片，然后向位于影月谷日蚀岗哨附近石桥处的欧鲁诺克之子伯拉克复命。$B$B该任务最好组队完成。','终于!密码碎片终于是我们的了!$B$B
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10579,'诅咒密码 - 第三块碎片','将箱子交给我的父亲。他住在库斯卡水池附近的欧鲁诺克农场，在遥远的北方。一旦集齐了碎片，我们就可以解读诅咒密码了。$B$B祝你好运，$N。请转告我的父亲，我会尽快启程返家。','将伯拉克的箱子交给影月谷欧鲁诺克农场的欧鲁诺克·裂心。','等到三块密码碎片重新结合，隐藏在里头的古老文字就会出现。$B$B毫无疑问的是找回这个碎片的困难度很高。你应该为你的英勇行为受到奖赏。','$N!') ON DUPLICATE KEY UPDATE Title_loc4='诅咒密码 - 第三块碎片',Details_loc4='将箱子交给我的父亲。他住在库斯卡水池附近的欧鲁诺克农场，在遥远的北方。一旦集齐了碎片，我们就可以解读诅咒密码了。$B$B祝你好运，$N。请转告我的父亲，我会尽快启程返家。',Objectives_loc4='将伯拉克的箱子交给影月谷欧鲁诺克农场的欧鲁诺克·裂心。',OfferRewardText_loc4='等到三块密码碎片重新结合，隐藏在里头的古老文字就会出现。$B$B毫无疑问的是找回这个碎片的困难度很高。你应该为你的英勇行为受到奖赏。',RequestItemsText_loc4='$N!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10580,'侏儒都去哪里了？','尽管这里一切都进展顺利，但我的心情还是不怎么好，因为我先前几天被迫把托什雷和他的那些侏儒朋友都赶出了这里。$B$B可我们也确实没有办法，他们的科技实验对林地环境的影响很不好，可能会把我们的努力成果搅得一团糟。$B$B不知你是否能替我去探望探望他们，看看他们现在过得怎样？听说他们向东走去了，过了桥。我猜他们可能转向了南边，向着远离雷神要塞的方向继续前进。$B$B看看锯齿山的南部有没有他们的踪迹吧。','指挥官萨卡斯·天影要求你到刀锋山地区去，在锯齿山的南侧搜索有关托什雷和其它侏儒的下落。','希尔瓦纳?指挥官天影?$B$B这个推断是错误的!$B$B滚远一点，不要逼我对你用吼的!') ON DUPLICATE KEY UPDATE Title_loc4='侏儒都去哪里了？',Details_loc4='尽管这里一切都进展顺利，但我的心情还是不怎么好，因为我先前几天被迫把托什雷和他的那些侏儒朋友都赶出了这里。$B$B可我们也确实没有办法，他们的科技实验对林地环境的影响很不好，可能会把我们的努力成果搅得一团糟。$B$B不知你是否能替我去探望探望他们，看看他们现在过得怎样？听说他们向东走去了，过了桥。我猜他们可能转向了南边，向着远离雷神要塞的方向继续前进。$B$B看看锯齿山的南部有没有他们的踪迹吧。',Objectives_loc4='指挥官萨卡斯·天影要求你到刀锋山地区去，在锯齿山的南侧搜索有关托什雷和其它侏儒的下落。',OfferRewardText_loc4='希尔瓦纳?指挥官天影?$B$B这个推断是错误的!$B$B滚远一点，不要逼我对你用吼的!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10581,'废话连篇','非常好，我在此郑重警告你，你在这片山岭地带找不到任何东西。$B$B别想跟着那些散在地上的碎零件到托什雷的基地去！你找不到托什雷，你找不到任何侏儒。','伴随着无数的废话，R-3D0告诉你，如果你继续跟着这些散落在地上的零件走下去，并越过前面这道斜坡走上剃刀山的话，就可以在一处叫作“托什雷的基地”的地方找到侏儒们。$B$B到达那里之后与托什雷谈一谈。','没问题，你这么想证明你自己吗?好，我正好有一件事情可以让你证明你自己。$B$B我想你会喜欢它。') ON DUPLICATE KEY UPDATE Title_loc4='废话连篇',Details_loc4='非常好，我在此郑重警告你，你在这片山岭地带找不到任何东西。$B$B别想跟着那些散在地上的碎零件到托什雷的基地去！你找不到托什雷，你找不到任何侏儒。',Objectives_loc4='伴随着无数的废话，R-3D0告诉你，如果你继续跟着这些散落在地上的零件走下去，并越过前面这道斜坡走上剃刀山的话，就可以在一处叫作“托什雷的基地”的地方找到侏儒们。$B$B到达那里之后与托什雷谈一谈。',OfferRewardText_loc4='没问题，你这么想证明你自己吗?好，我正好有一件事情可以让你证明你自己。$B$B我想你会喜欢它。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10582,'暗影议会的爪牙','<伊万一边听着你汇报军团要塞的情况，一边不停地点着头。>$B$B听你这么一说，我们探察到的线索逐渐清晰了许多。侦察兵们曾隐约发现他们在向军团要塞那边输送地狱火，但是未能探得更多细节。$B$B暗影议会则将死亡熔炉部署得跟雷霆啤酒桶一般密不透风。因此，你首先得扫平外围的障碍。去消灭驻守在死亡熔炉入口处的暗影议会卫兵吧！','杀死10个死亡熔炉守护者和5个死亡熔炉召唤者，然后向死亡熔炉哨塔的伊万·蛮翼复命。','我希望我也可以跟你一同前去!闲置已久的战锤使我非常手痒，谁叫我的任务是观察，不是杀戳呢。$B$B现在你已经在他们的防御网上打出了一个缺口，让我们去终止死亡熔炉的生产线吧。','你已经清出一条路通往死亡熔炉的通道了吗?') ON DUPLICATE KEY UPDATE Title_loc4='暗影议会的爪牙',Details_loc4='<伊万一边听着你汇报军团要塞的情况，一边不停地点着头。>$B$B听你这么一说，我们探察到的线索逐渐清晰了许多。侦察兵们曾隐约发现他们在向军团要塞那边输送地狱火，但是未能探得更多细节。$B$B暗影议会则将死亡熔炉部署得跟雷霆啤酒桶一般密不透风。因此，你首先得扫平外围的障碍。去消灭驻守在死亡熔炉入口处的暗影议会卫兵吧！',Objectives_loc4='杀死10个死亡熔炉守护者和5个死亡熔炉召唤者，然后向死亡熔炉哨塔的伊万·蛮翼复命。',OfferRewardText_loc4='我希望我也可以跟你一同前去!闲置已久的战锤使我非常手痒，谁叫我的任务是观察，不是杀戳呢。$B$B现在你已经在他们的防御网上打出了一个缺口，让我们去终止死亡熔炉的生产线吧。',RequestItemsText_loc4='你已经清出一条路通往死亡熔炉的通道了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10583,'弗兰尼斯的命运','空军指挥官努埃恩指派我和另外两名侦察兵来这儿密切注视死亡熔炉的动向，并收集情报。弗兰尼斯·迅翼自告奋勇潜入死亡熔炉，可是数日来都没有他的消息。$B$B我担心事情不妙了，$N。虽然弗兰尼斯是一位经验丰富的侦察兵，可是这次他孤身深入敌后，我们已经无法与他取得联系。请你立刻前往死亡熔炉寻找他的行踪，获取他收集到的情报或物品。','死亡熔炉哨塔的伊万·蛮翼要你前往死亡熔炉寻找弗兰尼斯·迅翼，并找回弗兰尼斯的背包。','<艾文摇了摇头的从你手中接收了背包。>$B$B我想弗蓝尼斯并不了解死亡熔炉的守备有多森严。现在我们了解了那边的真实状况，我并不怪他们。我只希望弗蓝尼斯在进去之前就先能了解那边的状况。$B$B我只希望这里有东西可以帮助我们永久的让死亡熔炉停工。','你在死亡熔炉有找到任何弗蓝尼斯的踪迹吗?') ON DUPLICATE KEY UPDATE Title_loc4='弗兰尼斯的命运',Details_loc4='空军指挥官努埃恩指派我和另外两名侦察兵来这儿密切注视死亡熔炉的动向，并收集情报。弗兰尼斯·迅翼自告奋勇潜入死亡熔炉，可是数日来都没有他的消息。$B$B我担心事情不妙了，$N。虽然弗兰尼斯是一位经验丰富的侦察兵，可是这次他孤身深入敌后，我们已经无法与他取得联系。请你立刻前往死亡熔炉寻找他的行踪，获取他收集到的情报或物品。',Objectives_loc4='死亡熔炉哨塔的伊万·蛮翼要你前往死亡熔炉寻找弗兰尼斯·迅翼，并找回弗兰尼斯的背包。',OfferRewardText_loc4='<艾文摇了摇头的从你手中接收了背包。>$B$B我想弗蓝尼斯并不了解死亡熔炉的守备有多森严。现在我们了解了那边的真实状况，我并不怪他们。我只希望弗蓝尼斯在进去之前就先能了解那边的状况。$B$B我只希望这里有东西可以帮助我们永久的让死亡熔炉停工。',RequestItemsText_loc4='你在死亡熔炉有找到任何弗蓝尼斯的踪迹吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4) VALUES (10584,'能量转换器','北边刀塔哨站里那些蠢笨的食人魔曾袭击过我们，抢走了我们的能量转换器！你得去把它们给我抢回来，有多少抢回来多少。$B$B不过，想都不用想，他们那又肥又笨的手掌肯定把转换器都搞坏了。那么这样吧，你需要直接释放它们里面的能量，然后对着释放出来的电浆使用这个电磁收集器，把它固化吸收。$B$B它可能会给你搞出点麻烦，所以收录进磁力球之后，你得把它“杀掉”。','使用电磁收集器收集5个电荷元素。','太棒了!反正你帮我们取回来的电源能量可以让我们的机械运作好一阵子了。$B$B当ZC号的电源耗尽的时候还真是一个没用的东西!$B$B我希望取回电流体的这件事不会太困难。我有别的事情想请你去做，而我有预感这将会有一点危险。','我们用电流体所进行的一系列研究还真是刺激呀!想想看……只要我们愿意就可以生产有智慧的电子生物并且只会听从我们的指令!$B$B还有什么地方会出差错呢?','收集电荷元素') ON DUPLICATE KEY UPDATE Title_loc4='能量转换器',Details_loc4='北边刀塔哨站里那些蠢笨的食人魔曾袭击过我们，抢走了我们的能量转换器！你得去把它们给我抢回来，有多少抢回来多少。$B$B不过，想都不用想，他们那又肥又笨的手掌肯定把转换器都搞坏了。那么这样吧，你需要直接释放它们里面的能量，然后对着释放出来的电浆使用这个电磁收集器，把它固化吸收。$B$B它可能会给你搞出点麻烦，所以收录进磁力球之后，你得把它“杀掉”。',Objectives_loc4='使用电磁收集器收集5个电荷元素。',OfferRewardText_loc4='太棒了!反正你帮我们取回来的电源能量可以让我们的机械运作好一阵子了。$B$B当ZC号的电源耗尽的时候还真是一个没用的东西!$B$B我希望取回电流体的这件事不会太困难。我有别的事情想请你去做，而我有预感这将会有一点危险。',RequestItemsText_loc4='我们用电流体所进行的一系列研究还真是刺激呀!想想看……只要我们愿意就可以生产有智慧的电子生物并且只会听从我们的指令!$B$B还有什么地方会出差错呢?',ObjectiveText1_loc4='收集电荷元素';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4) VALUES (10585,'召唤之厅','为了满足燃烧军团的地狱火兵力需求，暗影议会必定挑选了一处隐蔽之地，在那里召唤堕落的元素生物来构成地狱火的核心部分。$B$B召唤室通常在地下，附近会有被污染的水池或熔岩。前往死亡熔炉寻找召唤大厅，并设法破坏他们的召唤仪式。一些莫尔葛恶魔也参与了制造地狱火，他们身上携带的某种工具或许能打断召唤师的魔法。','从死亡熔炉铁匠或死亡熔炉杂役身上取得元素置换器，用它打断召唤大厅中的召唤仪式。完成任务后返回死亡熔炉哨塔向伊万·蛮翼复命。','做的好，$N。瓦解暗影议会的召唤仪式让我们在终止死亡熔炉运作这件事上更进一步了。','我们不能容许他们继续制造地狱火。你已经终止召唤仪式了吗?','终止地狱火召唤仪式') ON DUPLICATE KEY UPDATE Title_loc4='召唤之厅',Details_loc4='为了满足燃烧军团的地狱火兵力需求，暗影议会必定挑选了一处隐蔽之地，在那里召唤堕落的元素生物来构成地狱火的核心部分。$B$B召唤室通常在地下，附近会有被污染的水池或熔岩。前往死亡熔炉寻找召唤大厅，并设法破坏他们的召唤仪式。一些莫尔葛恶魔也参与了制造地狱火，他们身上携带的某种工具或许能打断召唤师的魔法。',Objectives_loc4='从死亡熔炉铁匠或死亡熔炉杂役身上取得元素置换器，用它打断召唤大厅中的召唤仪式。完成任务后返回死亡熔炉哨塔向伊万·蛮翼复命。',OfferRewardText_loc4='做的好，$N。瓦解暗影议会的召唤仪式让我们在终止死亡熔炉运作这件事上更进一步了。',RequestItemsText_loc4='我们不能容许他们继续制造地狱火。你已经终止召唤仪式了吗?',ObjectiveText1_loc4='终止地狱火召唤仪式';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10586,'击败战争使者！','我们这次成功地阻止了暗影议会在死亡熔炉的军事扩张行动，但是要想取得全面胜利，就必须击败燃烧军团派驻在死亡熔炉的头目。$B$B我在弗兰尼斯的背包中找到了一把钥匙。它必定能帮你找到军团要塞的战争使者拉索恩的行踪。$B$B找到并击败战争使者拉索恩，然后直接向空军指挥官努埃恩复命。他正在焦急地等你的好消息呢！','击败战争使者拉索恩，取回拉索恩的命令，然后返回蛮锤要塞向空军指挥官努埃恩复命。','<你向空军指挥官回报并且交给他夺回的文件。>$B$B击败战争使者瑞术恩可能表示我们与燃烧军团之间的战事已经划下句点了，但是这些文件中的描述显示出他们的计划远比我想象中还要大许多。恐怕我们还有很多事情要做。','你从死亡熔炉带回了什么消息呀?') ON DUPLICATE KEY UPDATE Title_loc4='击败战争使者！',Details_loc4='我们这次成功地阻止了暗影议会在死亡熔炉的军事扩张行动，但是要想取得全面胜利，就必须击败燃烧军团派驻在死亡熔炉的头目。$B$B我在弗兰尼斯的背包中找到了一把钥匙。它必定能帮你找到军团要塞的战争使者拉索恩的行踪。$B$B找到并击败战争使者拉索恩，然后直接向空军指挥官努埃恩复命。他正在焦急地等你的好消息呢！',Objectives_loc4='击败战争使者拉索恩，取回拉索恩的命令，然后返回蛮锤要塞向空军指挥官努埃恩复命。',OfferRewardText_loc4='<你向空军指挥官回报并且交给他夺回的文件。>$B$B击败战争使者瑞术恩可能表示我们与燃烧军团之间的战事已经划下句点了，但是这些文件中的描述显示出他们的计划远比我想象中还要大许多。恐怕我们还有很多事情要做。',RequestItemsText_loc4='你从死亡熔炉带回了什么消息呀?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10587,'卡拉波训练场','据斥候回报，一支由日怒血精灵新兵组成的大部队目前正朝卡拉波废墟前进。原本，如此大规模的军事行动势必会构成强烈的军事威胁，但是我们相信此事另有内情。$B$B他们的服饰和战斗风格很像伊利丹麾下的部队。我可不想自乱阵脚。前往卡拉波废墟取回他们的武器，这样我们就能搞清楚状况了。','沙塔尔祭坛的大主教欧纳拉要你前往沙塔尔祭坛东南方的卡拉波废墟，从恶魔猎手学员和恶魔猎手新兵身上夺取8柄日怒阔剑。$B$B为奥尔多完成任务将会降低你在占星者阵营中的声望等级。','让我们靠近一点看这些武器，$N。嗯……这还真是令人不安啊。','你已经完成我要求的工作了吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='卡拉波训练场',Details_loc4='据斥候回报，一支由日怒血精灵新兵组成的大部队目前正朝卡拉波废墟前进。原本，如此大规模的军事行动势必会构成强烈的军事威胁，但是我们相信此事另有内情。$B$B他们的服饰和战斗风格很像伊利丹麾下的部队。我可不想自乱阵脚。前往卡拉波废墟取回他们的武器，这样我们就能搞清楚状况了。',Objectives_loc4='沙塔尔祭坛的大主教欧纳拉要你前往沙塔尔祭坛东南方的卡拉波废墟，从恶魔猎手学员和恶魔猎手新兵身上夺取8柄日怒阔剑。$B$B为奥尔多完成任务将会降低你在占星者阵营中的声望等级。',OfferRewardText_loc4='让我们靠近一点看这些武器，$N。嗯……这还真是令人不安啊。',RequestItemsText_loc4='你已经完成我要求的工作了吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10588,'诅咒密码','不知道这条危害世间的咒语被使用过多少次。你也看到了，它强大的破坏力是毋庸置疑的。$B$B带上经过修复的诅咒密码，前往诅咒祭坛，在古尔丹面前吟唱咒语。$B$B念诵咒语时，那些镌刻在大地上的回忆将浮现在你眼前，而你要做的就是等待火焰之王森卢肯现身。$B$B$N，你必须击败他。这片土地已经无法承受新一轮的摧残了。','在诅咒祭坛念诵诅咒密码，召唤出火焰之王森卢肯。$B$B杀死火焰之王森卢肯，然后与诅咒祭坛的大地治愈者托洛克谈一谈。','<大地治愈者托尔洛克从你身上拿走了毁灭密码。>$B$B你已经完成了元素们的要求。关于你的付出，我们非常感谢。我将给你应得的报酬，但是问题仍然潜伏在台面下，蠢蠢欲动。这件事情引起了火焰之灵们的一阵骚动。它们已经做出了决定。毁灭密码被它们认为是另外一样东西。$B$B我也知道这件事情很神秘，可是火焰之灵们也只让我知道这么多而已。这件事还有这个符号……$B$B<大地治愈者托尔洛克转过身背对着你然后指向了天空。>$B$B这代表着什么意义呢?','完成了吗?') ON DUPLICATE KEY UPDATE Title_loc4='诅咒密码',Details_loc4='不知道这条危害世间的咒语被使用过多少次。你也看到了，它强大的破坏力是毋庸置疑的。$B$B带上经过修复的诅咒密码，前往诅咒祭坛，在古尔丹面前吟唱咒语。$B$B念诵咒语时，那些镌刻在大地上的回忆将浮现在你眼前，而你要做的就是等待火焰之王森卢肯现身。$B$B$N，你必须击败他。这片土地已经无法承受新一轮的摧残了。',Objectives_loc4='在诅咒祭坛念诵诅咒密码，召唤出火焰之王森卢肯。$B$B杀死火焰之王森卢肯，然后与诅咒祭坛的大地治愈者托洛克谈一谈。',OfferRewardText_loc4='<大地治愈者托尔洛克从你身上拿走了毁灭密码。>$B$B你已经完成了元素们的要求。关于你的付出，我们非常感谢。我将给你应得的报酬，但是问题仍然潜伏在台面下，蠢蠢欲动。这件事情引起了火焰之灵们的一阵骚动。它们已经做出了决定。毁灭密码被它们认为是另外一样东西。$B$B我也知道这件事情很神秘，可是火焰之灵们也只让我知道这么多而已。这件事还有这个符号……$B$B<大地治愈者托尔洛克转过身背对着你然后指向了天空。>$B$B这代表着什么意义呢?',RequestItemsText_loc4='完成了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10589,'控制权','从拉索恩的命令来看，地狱火大军转移到了登陆场：灾难，就在北面的山上！只有使用军团要塞内的传送装置才能达到那里。$B$B燃烧军团的某些爪牙必定随身携带着可以控制传送装置的设备。你必须搞到这种设备才能使用传送装置。杀光那些恶魔，一一搜尸，绝不能空手而归。','将军团传送控制器交给蛮锤要塞的空军指挥官努埃恩。据说军团要塞的莫尔葛武器匠身上携带着这东西。','让我看看这个东西怎么使用……','我们必须想办法摧毁剩下的炼狱火，$N。我们已经奋斗到了这个地步，但是一次失败就可能让我们失去所有。') ON DUPLICATE KEY UPDATE Title_loc4='控制权',Details_loc4='从拉索恩的命令来看，地狱火大军转移到了登陆场：灾难，就在北面的山上！只有使用军团要塞内的传送装置才能达到那里。$B$B燃烧军团的某些爪牙必定随身携带着可以控制传送装置的设备。你必须搞到这种设备才能使用传送装置。杀光那些恶魔，一一搜尸，绝不能空手而归。',Objectives_loc4='将军团传送控制器交给蛮锤要塞的空军指挥官努埃恩。据说军团要塞的莫尔葛武器匠身上携带着这东西。',OfferRewardText_loc4='让我看看这个东西怎么使用……',RequestItemsText_loc4='我们必须想办法摧毁剩下的炼狱火，$N。我们已经奋斗到了这个地步，但是一次失败就可能让我们失去所有。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10590,'仇恨的证明','阿尔萨斯和他的天灾军团背负着沉重的血债……你要牢记这段不该被遗忘的历史。$B$B燃起复仇的怒火是释放我们内心伤痛的惟一途径。不幸的是，恐惧和痛楚对这帮行尸走肉完全不起作用。只有将其彻底毁灭才能给你的心灵带来一点点慰藉。$B$B与银色黎明的军官加鲁什交谈，了解天灾石的来历以及获得天灾石的方法。在我们再次交谈之前，我需要你交给我一些天灾石，作为你的能力和仇恨的凭证。','亡灵壁垒的麦拉·黎明之刃要求你给他带去20枚爪牙的天灾石。','非常好，$N。或许你对复仇很有天份。','你尝到复仇的快感了吗?') ON DUPLICATE KEY UPDATE Title_loc4='仇恨的证明',Details_loc4='阿尔萨斯和他的天灾军团背负着沉重的血债……你要牢记这段不该被遗忘的历史。$B$B燃起复仇的怒火是释放我们内心伤痛的惟一途径。不幸的是，恐惧和痛楚对这帮行尸走肉完全不起作用。只有将其彻底毁灭才能给你的心灵带来一点点慰藉。$B$B与银色黎明的军官加鲁什交谈，了解天灾石的来历以及获得天灾石的方法。在我们再次交谈之前，我需要你交给我一些天灾石，作为你的能力和仇恨的凭证。',Objectives_loc4='亡灵壁垒的麦拉·黎明之刃要求你给他带去20枚爪牙的天灾石。',OfferRewardText_loc4='非常好，$N。或许你对复仇很有天份。',RequestItemsText_loc4='你尝到复仇的快感了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10592,'女妖之王的智慧','一旦脱离了主人的身体，天灾石的力量就会减弱。瞧，我轻轻一握就能粉碎它们。$B$B<麦拉将天灾石捏成了碎片。>$B$B前往幽暗城的皇家区，将这些天灾石碎片交给女妖之王希尔瓦娜斯·风行者。女王知道如何将这些碎片铸造成对抗亡灵天灾的利器。','前往幽暗城，将天灾石碎片交给希尔瓦娜斯女王。','这些石头带着一个我不想记起的污点，但我也无法忘记。你把这些带来给我是在考验我的耐心。$B$B不过，很清楚的，你和我寻求一样的复仇，我会帮助你并给你指示。','你有什么东西要给我吗，$r?') ON DUPLICATE KEY UPDATE Title_loc4='女妖之王的智慧',Details_loc4='一旦脱离了主人的身体，天灾石的力量就会减弱。瞧，我轻轻一握就能粉碎它们。$B$B<麦拉将天灾石捏成了碎片。>$B$B前往幽暗城的皇家区，将这些天灾石碎片交给女妖之王希尔瓦娜斯·风行者。女王知道如何将这些碎片铸造成对抗亡灵天灾的利器。',Objectives_loc4='前往幽暗城，将天灾石碎片交给希尔瓦娜斯女王。',OfferRewardText_loc4='这些石头带着一个我不想记起的污点，但我也无法忘记。你把这些带来给我是在考验我的耐心。$B$B不过，很清楚的，你和我寻求一样的复仇，我会帮助你并给你指示。',RequestItemsText_loc4='你有什么东西要给我吗，$r?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10593,'远古的邪恶','想要把这堆石头打造成武器来对抗天灾士兵，你就需要某种侵染着邪恶气息的物品来强化它们。$B$B悲伤沼泽的阿塔哈卡神庙深处潜伏着古老的邪灵。释放并击败这个邪灵，然后将他的残骸交给麦拉·黎明之刃。我的卫兵们会替你将天灾石碎片交给麦拉的。','揭开阿塔哈卡神庙的秘密，释放阿塔拉利恩并击败他，从他的尸体上取走腐烂藤蔓。完成任务之后向亡灵壁垒的麦拉·黎明之刃复命。','女妖之王将你引导的很好。这确切是我需要去结合碎片的东西。$B$B<当藤蔓穿过碎片交织时，米哈尔注视着并把他们捆在一起。>$B$B那里!天灾毒物，我将召唤它。当你使用它时，谨慎小心，因为它违反它的意愿为你效劳。','假使你活着，我只能推测你运气好得获得智慧，而不是希尔瓦娜斯所给予的死亡。') ON DUPLICATE KEY UPDATE Title_loc4='远古的邪恶',Details_loc4='想要把这堆石头打造成武器来对抗天灾士兵，你就需要某种侵染着邪恶气息的物品来强化它们。$B$B悲伤沼泽的阿塔哈卡神庙深处潜伏着古老的邪灵。释放并击败这个邪灵，然后将他的残骸交给麦拉·黎明之刃。我的卫兵们会替你将天灾石碎片交给麦拉的。',Objectives_loc4='揭开阿塔哈卡神庙的秘密，释放阿塔拉利恩并击败他，从他的尸体上取走腐烂藤蔓。完成任务之后向亡灵壁垒的麦拉·黎明之刃复命。',OfferRewardText_loc4='女妖之王将你引导的很好。这确切是我需要去结合碎片的东西。$B$B<当藤蔓穿过碎片交织时，米哈尔注视着并把他们捆在一起。>$B$B那里!天灾毒物，我将召唤它。当你使用它时，谨慎小心，因为它违反它的意愿为你效劳。',RequestItemsText_loc4='假使你活着，我只能推测你运气好得获得智慧，而不是希尔瓦娜斯所给予的死亡。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,EndText_loc4) VALUES (10594,'测量振荡频率','把这些扫描器带到晶歌山脉去。你只需把它们按照特定的样式和位置摆放在地上，就可以创造出一个多维度的力场群，这个力场群会解读和分析出那些水晶的频谱。然后呢，你要按这样的方式站在它们中间，让五个振动场都能复盖到你，这样我就可以得到我需要的信息了！$B$B你的扫描器甚至还会对落入场中的其它东西产生反应。$B$B哦，对了，运行的时候，可能还会产生一道空间裂隙！我不知道里面有什么东西会跑出来，但你最好有心理准备。','测量者尼克维克要你将振荡频率扫描器按照一定方式摆放在地上，当你站进中央时，你必须能够同时受到5个重叠扫描场的影响。','哇，这真是太棒了!我实在搞不清楚……就好像这些水晶是有生命似的。$B$B我在想这些水晶跟虚空龙之间有没有某种特殊的关连性?$B$B谢谢你,谢谢!你一定要收下我的一点感谢之意，一些我的零件和完成品珍藏。$B$B他们之中一定有一个适合你。','嗯，你已经完成了我要求的歌唱水晶的测量资料了吗?','测量歌唱水晶震荡频率') ON DUPLICATE KEY UPDATE Title_loc4='测量振荡频率',Details_loc4='把这些扫描器带到晶歌山脉去。你只需把它们按照特定的样式和位置摆放在地上，就可以创造出一个多维度的力场群，这个力场群会解读和分析出那些水晶的频谱。然后呢，你要按这样的方式站在它们中间，让五个振动场都能复盖到你，这样我就可以得到我需要的信息了！$B$B你的扫描器甚至还会对落入场中的其它东西产生反应。$B$B哦，对了，运行的时候，可能还会产生一道空间裂隙！我不知道里面有什么东西会跑出来，但你最好有心理准备。',Objectives_loc4='测量者尼克维克要你将振荡频率扫描器按照一定方式摆放在地上，当你站进中央时，你必须能够同时受到5个重叠扫描场的影响。',OfferRewardText_loc4='哇，这真是太棒了!我实在搞不清楚……就好像这些水晶是有生命似的。$B$B我在想这些水晶跟虚空龙之间有没有某种特殊的关连性?$B$B谢谢你,谢谢!你一定要收下我的一点感谢之意，一些我的零件和完成品珍藏。$B$B他们之中一定有一个适合你。',RequestItemsText_loc4='嗯，你已经完成了我要求的歌唱水晶的测量资料了吗?',EndText_loc4='测量歌唱水晶震荡频率';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10595,'兵临城下！','<古尔穆克望着天空。>$B$B哎……我们的士兵消灭敌人的速度根本就跟不上他们补充兵力的速度。$B$B燃烧军团目前盘踞在西南方的军团要塞，每天召唤出的地狱火总能像潮水般朝我们这里涌来。就算是库卡隆的精英将士也没法阻挡他们的攻势。$B$B每一位强壮的$c都应该承担起保卫影月村的重担。这可不是儿戏，$c，形势确实已经岌岌可危。为了部落的荣耀，加入前线大军的阵列吧！','影月村外的血卫士古尔穆要求你杀死10个地狱火攻击者。','你可以在这场大屠杀当中存活下来让我印象深刻。你可能就是我们要执行危险任务的最佳人选。','你已经累了吗，$C?') ON DUPLICATE KEY UPDATE Title_loc4='兵临城下！',Details_loc4='<古尔穆克望着天空。>$B$B哎……我们的士兵消灭敌人的速度根本就跟不上他们补充兵力的速度。$B$B燃烧军团目前盘踞在西南方的军团要塞，每天召唤出的地狱火总能像潮水般朝我们这里涌来。就算是库卡隆的精英将士也没法阻挡他们的攻势。$B$B每一位强壮的$c都应该承担起保卫影月村的重担。这可不是儿戏，$c，形势确实已经岌岌可危。为了部落的荣耀，加入前线大军的阵列吧！',Objectives_loc4='影月村外的血卫士古尔穆要求你杀死10个地狱火攻击者。',OfferRewardText_loc4='你可以在这场大屠杀当中存活下来让我印象深刻。你可能就是我们要执行危险任务的最佳人选。',RequestItemsText_loc4='你已经累了吗，$C?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText3_loc4) VALUES (10596,'前往军团要塞','你的目的地是军团要塞。你没有援军，所以就不要想发动正面攻击了。$B$B从我们目前掌握的零碎情报来看，燃烧军团正在要塞中囤积和准备他们的地狱火大军。穿上这套伪装潜入军团要塞，打探他们的秘密计划。$B$B或许你能从燃烧军团指挥官们的谈话中偷听到一些东西。','前往军团要塞寻找军团通讯装置。在伪装状态下站在军团通讯装置附近，偷听燃烧军团的计划。完成任务后向影月村的血卫士古尔穆克复命。','<血卫士高莫克听着你的报告，他的警戒心随着你的每一句话而提高。>$B$B你说他们将加速轰炸攻击的准备是什么意思?我们不能允许这样的事情发生。在影月村还没有被完全摧毁之前回去那边解决这个问题!','你发现了什么?','偷听燃烧军团的计划') ON DUPLICATE KEY UPDATE Title_loc4='前往军团要塞',Details_loc4='你的目的地是军团要塞。你没有援军，所以就不要想发动正面攻击了。$B$B从我们目前掌握的零碎情报来看，燃烧军团正在要塞中囤积和准备他们的地狱火大军。穿上这套伪装潜入军团要塞，打探他们的秘密计划。$B$B或许你能从燃烧军团指挥官们的谈话中偷听到一些东西。',Objectives_loc4='前往军团要塞寻找军团通讯装置。在伪装状态下站在军团通讯装置附近，偷听燃烧军团的计划。完成任务后向影月村的血卫士古尔穆克复命。',OfferRewardText_loc4='<血卫士高莫克听着你的报告，他的警戒心随着你的每一句话而提高。>$B$B你说他们将加速轰炸攻击的准备是什么意思?我们不能允许这样的事情发生。在影月村还没有被完全摧毁之前回去那边解决这个问题!',RequestItemsText_loc4='你发现了什么?',ObjectiveText3_loc4='偷听燃烧军团的计划';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10597,'制造炸弹','燃烧军团意欲在前往黑暗神殿的行军途中摧毁蛮锤要塞，我们绝不能让他们的奸计得逞。$B$B设法消灭地狱火大军。$N，这不是请求，而是命令。$B$B军团要塞附近有一片恶臭之池，那里的魔能机甲动力核心可用作炸药。那些魔能机甲附近另一处废墟中的魔能机甲护板可用作炸弹外壳。收集这些两样东西来，然后你就可以制造出一枚威力强大的魔能炸弹了。','将魔能机甲动力核心和魔能机甲护板交给影月村的血卫士古尔穆克。','<高莫克将能量核心插入外罩并将它密封。>$B$B这应该可以了。当爆炸发生的时候我可不想在堡垒里。','<你将材料交给高莫克。>') ON DUPLICATE KEY UPDATE Title_loc4='制造炸弹',Details_loc4='燃烧军团意欲在前往黑暗神殿的行军途中摧毁蛮锤要塞，我们绝不能让他们的奸计得逞。$B$B设法消灭地狱火大军。$N，这不是请求，而是命令。$B$B军团要塞附近有一片恶臭之池，那里的魔能机甲动力核心可用作炸药。那些魔能机甲附近另一处废墟中的魔能机甲护板可用作炸弹外壳。收集这些两样东西来，然后你就可以制造出一枚威力强大的魔能炸弹了。',Objectives_loc4='将魔能机甲动力核心和魔能机甲护板交给影月村的血卫士古尔穆克。',OfferRewardText_loc4='<高莫克将能量核心插入外罩并将它密封。>$B$B这应该可以了。当爆炸发生的时候我可不想在堡垒里。',RequestItemsText_loc4='<你将材料交给高莫克。>';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText2_loc4) VALUES (10598,'炸毁地狱火！','我们装配出来的这玩意虽然奇丑无比，但是它能消灭军团要塞的地狱火大军。瞧瞧魔能机甲能量核心对恶臭之池的影响，这东西蕴藏的爆炸威力可不容小觑。$B$B如果在军团要塞的绿色雕文中心引爆这个邪能炸弹，应该可以一举歼灭所有地狱火。','站在军团要塞的绿色雕文上使用魔能炸弹消灭地狱火，然后向影月村的血卫士古尔穆克复命。','<高莫克严肃的点了点头。>$B$B现在可不是庆祝的时候，$N。我们还没脱离险境。我有新的指令要交给你。','你找到摧毁军团囤积炼狱火的方法了吗?','摧毁军团要塞的地狱火') ON DUPLICATE KEY UPDATE Title_loc4='炸毁地狱火！',Details_loc4='我们装配出来的这玩意虽然奇丑无比，但是它能消灭军团要塞的地狱火大军。瞧瞧魔能机甲能量核心对恶臭之池的影响，这东西蕴藏的爆炸威力可不容小觑。$B$B如果在军团要塞的绿色雕文中心引爆这个邪能炸弹，应该可以一举歼灭所有地狱火。',Objectives_loc4='站在军团要塞的绿色雕文上使用魔能炸弹消灭地狱火，然后向影月村的血卫士古尔穆克复命。',OfferRewardText_loc4='<高莫克严肃的点了点头。>$B$B现在可不是庆祝的时候，$N。我们还没脱离险境。我有新的指令要交给你。',RequestItemsText_loc4='你找到摧毁军团囤积炼狱火的方法了吗?',ObjectiveText2_loc4='摧毁军团要塞的地狱火';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10599,'死亡熔炉','在你前往军团要塞执行消灭地狱火的任务时，我一直在研究你查探到的情报。要知道，我们没有理由只注意军团要塞，却忽视死亡熔炉那帮蠢蠢欲动的燃烧军团，他们的确在那儿制造地狱火大军。我已经派出侦察小队注意死亡熔炉的动向。$B$B如果我们不采取行动的话，他们很快将重新纠集起新的地狱火大军，数量堪比你在军团要塞炸掉的兵团。$B$B前往东南方的熔渣哨塔，向奉命在那儿监视死亡熔炉的斥候萨格兰报到。','前往熔渣哨塔向斥候萨格兰报到。','<兽人点了点头。>$B$B有人来支持真好。我们已经对暗影议会在那边的企图有了初步的了解，但是现在是让他们战锤落地的时候了。','血卫士高莫克终于派人来支持了吗?') ON DUPLICATE KEY UPDATE Title_loc4='死亡熔炉',Details_loc4='在你前往军团要塞执行消灭地狱火的任务时，我一直在研究你查探到的情报。要知道，我们没有理由只注意军团要塞，却忽视死亡熔炉那帮蠢蠢欲动的燃烧军团，他们的确在那儿制造地狱火大军。我已经派出侦察小队注意死亡熔炉的动向。$B$B如果我们不采取行动的话，他们很快将重新纠集起新的地狱火大军，数量堪比你在军团要塞炸掉的兵团。$B$B前往东南方的熔渣哨塔，向奉命在那儿监视死亡熔炉的斥候萨格兰报到。',Objectives_loc4='前往熔渣哨塔向斥候萨格兰报到。',OfferRewardText_loc4='<兽人点了点头。>$B$B有人来支持真好。我们已经对暗影议会在那边的企图有了初步的了解，但是现在是让他们战锤落地的时候了。',RequestItemsText_loc4='血卫士高莫克终于派人来支持了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10600,'暗影议会的爪牙','<萨格兰听你汇报军团要塞的情况，不停地点着头。>$B$B你探察到的情况跟我们掌握的线索恰好吻合。侦察兵们曾隐约发现他们在向军团要塞那里运送地狱火，但是未能探得更多细节。$B$B暗影议会将死亡熔炉部署得密不透风。看来你得首先扫平沿途的障碍，先去消灭驻守在死亡熔炉入口处的暗影议会卫兵吧！','杀死10个死亡熔炉守护者和5个死亡熔炉召唤者，然后向熔渣哨塔的斥候萨格兰复命。','我自己也曾经去过那边敲碎敌人的脑袋，但是我现在有命令在身不允许我跟敌人交战。$B$B<这个斥候一边用模仿的唯妙唯肖的血卫士高莫克的声音一边说着。>$B$B让我们去终止他们的生产线吧。','你已经清除通往死亡熔炉的道路了吗?') ON DUPLICATE KEY UPDATE Title_loc4='暗影议会的爪牙',Details_loc4='<萨格兰听你汇报军团要塞的情况，不停地点着头。>$B$B你探察到的情况跟我们掌握的线索恰好吻合。侦察兵们曾隐约发现他们在向军团要塞那里运送地狱火，但是未能探得更多细节。$B$B暗影议会将死亡熔炉部署得密不透风。看来你得首先扫平沿途的障碍，先去消灭驻守在死亡熔炉入口处的暗影议会卫兵吧！',Objectives_loc4='杀死10个死亡熔炉守护者和5个死亡熔炉召唤者，然后向熔渣哨塔的斥候萨格兰复命。',OfferRewardText_loc4='我自己也曾经去过那边敲碎敌人的脑袋，但是我现在有命令在身不允许我跟敌人交战。$B$B<这个斥候一边用模仿的唯妙唯肖的血卫士高莫克的声音一边说着。>$B$B让我们去终止他们的生产线吧。',RequestItemsText_loc4='你已经清除通往死亡熔炉的道路了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10601,'卡格罗什的命运','侦察小队原本有三名成员，偏偏卡格罗什这家伙逞强好胜，想当英雄。$B$B他孤身潜入死亡熔炉后，便与我们失去了联系。$B$B现在，这个蠢货很可能已经被杀掉了，暗影议会的成员可不是傻子，卡格罗什也算不得侦察兵中的佼佼者。你立刻前往死亡熔炉寻找他的行踪，带回他收集到的情报或物品。','熔渣哨塔的斥候萨格兰要你前往死亡熔炉寻找卡格罗什，并找回卡格罗什的背包。','<萨葛兰一边摇头一边接过了你找回的背包。>$B$B我跟你说过他是一个笨蛋。我希望背包里头有我们可用的东西，这样才不枉你花那么多的时间去寻找他。','你在死亡熔炉有找到凯格罗西的踪影吗?') ON DUPLICATE KEY UPDATE Title_loc4='卡格罗什的命运',Details_loc4='侦察小队原本有三名成员，偏偏卡格罗什这家伙逞强好胜，想当英雄。$B$B他孤身潜入死亡熔炉后，便与我们失去了联系。$B$B现在，这个蠢货很可能已经被杀掉了，暗影议会的成员可不是傻子，卡格罗什也算不得侦察兵中的佼佼者。你立刻前往死亡熔炉寻找他的行踪，带回他收集到的情报或物品。',Objectives_loc4='熔渣哨塔的斥候萨格兰要你前往死亡熔炉寻找卡格罗什，并找回卡格罗什的背包。',OfferRewardText_loc4='<萨葛兰一边摇头一边接过了你找回的背包。>$B$B我跟你说过他是一个笨蛋。我希望背包里头有我们可用的东西，这样才不枉你花那么多的时间去寻找他。',RequestItemsText_loc4='你在死亡熔炉有找到凯格罗西的踪影吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4) VALUES (10602,'召唤之厅','为了满足燃烧军团的地狱火兵力需求，暗影议会必定挑选了一处隐蔽之地，在那里召唤堕落的元素生物来构成地狱火的核心部分。$B$B召唤室通常在地下，附近会有被污染的水池或熔岩。前往死亡熔炉寻找召唤大厅，并设法破坏他们的召唤仪式。一些莫尔葛恶魔也参与了制造地狱火，他们身上携带的某种工具或许能打断召唤师的魔法。','从死亡熔炉铁匠或死亡熔炉杂役身上取得元素置换器，用它打断召唤大厅中的召唤仪式。完成任务后返回熔渣哨塔向斥候萨格兰复命。','太好了，我们又更进一步了。这让我们更加靠近终止死亡熔炉运作然后安全回到影月村的目标
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10603,'击败战争使者！','我们成功地阻止了暗影议会在死亡熔炉的军事扩张行动，现在是彻底肃清这帮家伙的时候了。$B$B我在卡格罗什的背包中找到一把钥匙。看来卡格罗什还是有所收获的。$B$B这把钥匙应该能帮你找到军团要塞的战争使者拉索恩的行踪。$B$B搜寻并击败战争使者拉索恩，然后直接向血卫士古尔穆克复命。可别让他等太久。','击败战争使者拉索恩，取回拉索恩的命令，然后返回影月村向血卫士古尔穆克复命。','<你向血卫士回报的同时交出了你夺回的指令。>$B$B做的好，$N，但是别以为这件事可以让你拿到任何勋章绶带。让暗夜精灵们随他们的意思来装饰自己的战服吧。真正的战士只会透过一大杯的麦芽酒来歌颂自己的英勇战绩。','你从死亡熔炉带回了什么消息呢?') ON DUPLICATE KEY UPDATE Title_loc4='击败战争使者！',Details_loc4='我们成功地阻止了暗影议会在死亡熔炉的军事扩张行动，现在是彻底肃清这帮家伙的时候了。$B$B我在卡格罗什的背包中找到一把钥匙。看来卡格罗什还是有所收获的。$B$B这把钥匙应该能帮你找到军团要塞的战争使者拉索恩的行踪。$B$B搜寻并击败战争使者拉索恩，然后直接向血卫士古尔穆克复命。可别让他等太久。',Objectives_loc4='击败战争使者拉索恩，取回拉索恩的命令，然后返回影月村向血卫士古尔穆克复命。',OfferRewardText_loc4='<你向血卫士回报的同时交出了你夺回的指令。>$B$B做的好，$N，但是别以为这件事可以让你拿到任何勋章绶带。让暗夜精灵们随他们的意思来装饰自己的战服吧。真正的战士只会透过一大杯的麦芽酒来歌颂自己的英勇战绩。',RequestItemsText_loc4='你从死亡熔炉带回了什么消息呢?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10604,'控制权','从拉索恩的命令来看，地狱火大军转移到了登陆场：灾难，就在我们村子后面的山上！只有使用军团要塞内的传送装置才能达到那里。$B$B燃烧军团的某些爪牙必定随身携带着可以控制传送装置的设备，你必须搞到这种设备才能使用传送装置。杀光那些恶魔，一一搜尸，绝不能空手而归。快去吧，情势危急，敌人离我们很近了。','将军团传送控制器交给影月村的血卫士古尔穆克。据说军团要塞的莫尔葛武器匠身上携带着这东西。','终于，我们有办法把燃烧军团赶出影月谷了!','我们无法容忍燃烧军团出现在我们之中!我们必须在他们重组突击攻击前想办法解决。') ON DUPLICATE KEY UPDATE Title_loc4='控制权',Details_loc4='从拉索恩的命令来看，地狱火大军转移到了登陆场：灾难，就在我们村子后面的山上！只有使用军团要塞内的传送装置才能达到那里。$B$B燃烧军团的某些爪牙必定随身携带着可以控制传送装置的设备，你必须搞到这种设备才能使用传送装置。杀光那些恶魔，一一搜尸，绝不能空手而归。快去吧，情势危急，敌人离我们很近了。',Objectives_loc4='将军团传送控制器交给影月村的血卫士古尔穆克。据说军团要塞的莫尔葛武器匠身上携带着这东西。',OfferRewardText_loc4='终于，我们有办法把燃烧军团赶出影月谷了!',RequestItemsText_loc4='我们无法容忍燃烧军团出现在我们之中!我们必须在他们重组突击攻击前想办法解决。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10605,'凯伦丁的召唤','你似乎对获取知识显得十分饥渴的样子，$n。看来你的学习正好到了一个提升层次的阶段。$b$b去幽暗城与凯伦丁·哈加尔谈谈吧，那把老骨头知道许多歪门邪道，或许你以后的冒险里会用得上。','与幽暗城的凯伦丁·哈加尔谈一谈。','啊，又来一个渴望力量的新成员。太好了!$B$B假如你对力量没有强烈的欲望你也不算是一个合格的术士，你说对吗$g男孩:女孩;?让我们开始吧。') ON DUPLICATE KEY UPDATE Title_loc4='凯伦丁的召唤',Details_loc4='你似乎对获取知识显得十分饥渴的样子，$n。看来你的学习正好到了一个提升层次的阶段。$b$b去幽暗城与凯伦丁·哈加尔谈谈吧，那把老骨头知道许多歪门邪道，或许你以后的冒险里会用得上。',Objectives_loc4='与幽暗城的凯伦丁·哈加尔谈一谈。',OfferRewardText_loc4='啊，又来一个渴望力量的新成员。太好了!$B$B假如你对力量没有强烈的欲望你也不算是一个合格的术士，你说对吗$g男孩:女孩;?让我们开始吧。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10606,'魔能机甲维修窍门大全','歼灭燃烧军团残馀势力的最好办法便是以彼之道还施彼身。我一直在开发某种可以操控魔能机甲斥候的仪器。$B$B当然，还有一堆设计上的问题没解决。我需要加特里克博士的手册。不过，这家伙总是把它锁在斜坡底部的箱子里，他应该不会轻易交出钥匙。你得用抢的，朋友。取回魔能机甲的手册，剩下的就由我来搞定！','杀死加特里克博士，用博士的钥匙打开博士的保险箱，从中取出魔能机甲维修窍门大全，把它交给登陆场：灾难的普雷西。','喔，这正是我们需要的。我从来没有谴责燃烧军团会出版任何类似文学的东西，但是现在它可是帮了我一个大忙。','你拿到那本手册了吗?') ON DUPLICATE KEY UPDATE Title_loc4='魔能机甲维修窍门大全',Details_loc4='歼灭燃烧军团残馀势力的最好办法便是以彼之道还施彼身。我一直在开发某种可以操控魔能机甲斥候的仪器。$B$B当然，还有一堆设计上的问题没解决。我需要加特里克博士的手册。不过，这家伙总是把它锁在斜坡底部的箱子里，他应该不会轻易交出钥匙。你得用抢的，朋友。取回魔能机甲的手册，剩下的就由我来搞定！',Objectives_loc4='杀死加特里克博士，用博士的钥匙打开博士的保险箱，从中取出魔能机甲维修窍门大全，把它交给登陆场：灾难的普雷西。',OfferRewardText_loc4='喔，这正是我们需要的。我从来没有谴责燃烧军团会出版任何类似文学的东西，但是现在它可是帮了我一个大忙。',RequestItemsText_loc4='你拿到那本手册了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4,ObjectiveText2_loc4,ObjectiveText3_loc4,ObjectiveText4_loc4) VALUES (10607,'乌鸦之神的低语','格里施纳的鸦人利用乌鸦预言者留下的图腾，聆听来自乌鸦之神的神喻。不幸的是，我们无法解读鸦人的语言。$B$B这枚预言者的坠饰或许能帮助我们。你必须借助鸦人的灵魂来破解他们的语言。当鸦人之魂附着在你身上后，你就能破解图腾的秘密了。$B$B$N，帮我们揭开乌鸦之神的秘密吧。','杀死格里施纳的鸦人，获得持续2分钟的理解鸦语效果。利用该法术破解四座神殿的预言，完成任务后向坦莫复命。','这真是令人不安啊。阿拉卡人长久以来一直是和平的民族。他们对乌鸦神的狂热信仰只能用不正常还有疯狂来形容。$B$B但是他们的力量已经成长到我们无法低估的境界。也许这个乌鸦神还有我们所不知道的事情。','这个乌鸦神是谁?他们以为他会做出什么事?他们以为他会怎么引导他们?','获知第一个预言','获知第二个预言','获知第三个预言','获知第四个预言') ON DUPLICATE KEY UPDATE Title_loc4='乌鸦之神的低语',Details_loc4='格里施纳的鸦人利用乌鸦预言者留下的图腾，聆听来自乌鸦之神的神喻。不幸的是，我们无法解读鸦人的语言。$B$B这枚预言者的坠饰或许能帮助我们。你必须借助鸦人的灵魂来破解他们的语言。当鸦人之魂附着在你身上后，你就能破解图腾的秘密了。$B$B$N，帮我们揭开乌鸦之神的秘密吧。',Objectives_loc4='杀死格里施纳的鸦人，获得持续2分钟的理解鸦语效果。利用该法术破解四座神殿的预言，完成任务后向坦莫复命。',OfferRewardText_loc4='这真是令人不安啊。阿拉卡人长久以来一直是和平的民族。他们对乌鸦神的狂热信仰只能用不正常还有疯狂来形容。$B$B但是他们的力量已经成长到我们无法低估的境界。也许这个乌鸦神还有我们所不知道的事情。',RequestItemsText_loc4='这个乌鸦神是谁?他们以为他会做出什么事?他们以为他会怎么引导他们?',ObjectiveText1_loc4='获知第一个预言',ObjectiveText2_loc4='获知第二个预言',ObjectiveText3_loc4='获知第三个预言',ObjectiveText4_loc4='获知第四个预言';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10608,'水晶剥石者的麻烦','那些该死的剥石者搞得我根本没办法到晶歌山脉下面去进行研究！它们一直在不停地挖掘那里的水晶，每一爪都是在毁灭我研究这些歌唱水晶的机会。$B$B你看起来像是个能帮我解决问题的人。到南边去，把那些该死的水晶剥石者都消灭干净吧。','杀死10只水晶剥石者。','杀的好呀;我说。这些可恶的东西!$B$B假如你已经确定你消灭了那些害虫，那么我有一个小小的研究计划要请你帮忙。我想你会喜欢的。','你已经杀死了美声山脊的水晶镰夺怪了吗?不然我们的研究就无法进行了。') ON DUPLICATE KEY UPDATE Title_loc4='水晶剥石者的麻烦',Details_loc4='那些该死的剥石者搞得我根本没办法到晶歌山脉下面去进行研究！它们一直在不停地挖掘那里的水晶，每一爪都是在毁灭我研究这些歌唱水晶的机会。$B$B你看起来像是个能帮我解决问题的人。到南边去，把那些该死的水晶剥石者都消灭干净吧。',Objectives_loc4='杀死10只水晶剥石者。',OfferRewardText_loc4='杀的好呀;我说。这些可恶的东西!$B$B假如你已经确定你消灭了那些害虫，那么我有一个小小的研究计划要请你帮忙。我想你会喜欢的。',RequestItemsText_loc4='你已经杀死了美声山脊的水晶镰夺怪了吗?不然我们的研究就无法进行了。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10609,'先有龙还是先有蛋？','我正在研究各种龙类精华的药用价值，它们很可能是治愈多种疾病的灵药！$B$B我想派人前往南边的晶歌山脉，取回一些龙类精华。$B$B你愿意帮忙吗？对着那些从虚空龙蛋中孵化出的虚空幼龙使用时间定相调节器就行，将你收集到的各种龙类精华带回来给我。$B$B不过，这个时间定相调节器只是个我改造出来的工具，其实我自己也不知道虚空幼龙能转化出什么样龙类精华。','收集3份始祖虚空幼龙的精华、3份健壮虚空幼龙的精华和3份成熟虚空幼龙的精华。','你不知道这个研究的重要性。谢谢你!$B$B能够深入的去研究这些精华是很有趣的。我特别好奇想知道把黑龙蛋突变成虚空龙蛋的虚空效应会不会对我的研究有任何额外帮助的潜力。$B$B我在想，事实上你应该是第一个享受到我所做出来的小混和物好处的人。拿好这些初级试验品，当你有需要的时候就使用它们吧。','东西到手了吗?你已经拿到了我衷心需要用来继续我的研究的三种龙之精华了吗?$B$B你知道那些虚空龙蛋曾经是黑龙蛋吗?这是事实!但是当德拉诺毁灭的时候，残存的虚空龙们跨越彼此种族而产下突变的蛋。') ON DUPLICATE KEY UPDATE Title_loc4='先有龙还是先有蛋？',Details_loc4='我正在研究各种龙类精华的药用价值，它们很可能是治愈多种疾病的灵药！$B$B我想派人前往南边的晶歌山脉，取回一些龙类精华。$B$B你愿意帮忙吗？对着那些从虚空龙蛋中孵化出的虚空幼龙使用时间定相调节器就行，将你收集到的各种龙类精华带回来给我。$B$B不过，这个时间定相调节器只是个我改造出来的工具，其实我自己也不知道虚空幼龙能转化出什么样龙类精华。',Objectives_loc4='收集3份始祖虚空幼龙的精华、3份健壮虚空幼龙的精华和3份成熟虚空幼龙的精华。',OfferRewardText_loc4='你不知道这个研究的重要性。谢谢你!$B$B能够深入的去研究这些精华是很有趣的。我特别好奇想知道把黑龙蛋突变成虚空龙蛋的虚空效应会不会对我的研究有任何额外帮助的潜力。$B$B我在想，事实上你应该是第一个享受到我所做出来的小混和物好处的人。拿好这些初级试验品，当你有需要的时候就使用它们吧。',RequestItemsText_loc4='东西到手了吗?你已经拿到了我衷心需要用来继续我的研究的三种龙之精华了吗?$B$B你知道那些虚空龙蛋曾经是黑龙蛋吗?这是事实!但是当德拉诺毁灭的时候，残存的虚空龙们跨越彼此种族而产下突变的蛋。';
INSERT INTO locales_quest(entry,Title_loc4) VALUES (10610,'基本的勘察') ON DUPLICATE KEY UPDATE Title_loc4='基本的勘察';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10611,'魔能机甲维修窍门大全','歼灭燃烧军团残馀势力的最好办法便是以彼之道还施彼身。我一直在开发某种可以操控魔能机甲斥候的仪器。$B$B当然，还有一堆设计上的问题没解决。我需要麦尔费苏斯博士的手册。不过，这家伙总是把它锁在斜坡底部的箱子里，他应该不会轻易交出钥匙。你得用抢的，朋友。取回魔能机甲的手册，剩下的就由我来搞定！','杀死麦尔费苏斯博士，用博士的钥匙打开博士的保险箱，从中取出魔能机甲维修窍门大全，把它交给登陆场：灾难的纳斯坎。','这有我要的资讯。只要再一下子，我们就能让你控制恶魔劫夺者。','你取得手册了吗?') ON DUPLICATE KEY UPDATE Title_loc4='魔能机甲维修窍门大全',Details_loc4='歼灭燃烧军团残馀势力的最好办法便是以彼之道还施彼身。我一直在开发某种可以操控魔能机甲斥候的仪器。$B$B当然，还有一堆设计上的问题没解决。我需要麦尔费苏斯博士的手册。不过，这家伙总是把它锁在斜坡底部的箱子里，他应该不会轻易交出钥匙。你得用抢的，朋友。取回魔能机甲的手册，剩下的就由我来搞定！',Objectives_loc4='杀死麦尔费苏斯博士，用博士的钥匙打开博士的保险箱，从中取出魔能机甲维修窍门大全，把它交给登陆场：灾难的纳斯坎。',OfferRewardText_loc4='这有我要的资讯。只要再一下子，我们就能让你控制恶魔劫夺者。',RequestItemsText_loc4='你取得手册了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4) VALUES (10612,'狂暴的魔能机甲','<普雷西迅速翻阅着手册。>$B$B嗯，手册上记载着我需要的所有信息，现在只剩最后一个问题了。要知道，魔能机甲并不具备遥控的功能。$B$B不过，我们倒是可以改装出一台控制器来，但是它的控制有效期很短；你得抓紧时间，不然谁也无法预料会发生什么事！那帮燃烧军团的走狗目睹被控制的魔能机甲引发骚乱，必定会大跌眼镜。保持警惕，尽可能地消灭那些地狱火！','使用魔能机甲控制台控制一台魔能机甲斥候，并在控制失效之前杀死60个死亡熔炉地狱火。完成任务后向登陆场：灾难的普雷西复命。','太棒了!你已经成功的办到所有蛮锤要塞的狮鹫骑士都做不到的事情!你已经断了燃烧军团发展的后路而且你拯救了我们从他们的炼狱火手中被歼灭的命运。你的英勇行为已经赢得我们最高的感激，$N。','你回来啦，我猜你的行动进行顺利。你有什么要向我报告呢?','摧毁死亡熔炉的地狱火') ON DUPLICATE KEY UPDATE Title_loc4='狂暴的魔能机甲',Details_loc4='<普雷西迅速翻阅着手册。>$B$B嗯，手册上记载着我需要的所有信息，现在只剩最后一个问题了。要知道，魔能机甲并不具备遥控的功能。$B$B不过，我们倒是可以改装出一台控制器来，但是它的控制有效期很短；你得抓紧时间，不然谁也无法预料会发生什么事！那帮燃烧军团的走狗目睹被控制的魔能机甲引发骚乱，必定会大跌眼镜。保持警惕，尽可能地消灭那些地狱火！',Objectives_loc4='使用魔能机甲控制台控制一台魔能机甲斥候，并在控制失效之前杀死60个死亡熔炉地狱火。完成任务后向登陆场：灾难的普雷西复命。',OfferRewardText_loc4='太棒了!你已经成功的办到所有蛮锤要塞的狮鹫骑士都做不到的事情!你已经断了燃烧军团发展的后路而且你拯救了我们从他们的炼狱火手中被歼灭的命运。你的英勇行为已经赢得我们最高的感激，$N。',RequestItemsText_loc4='你回来啦，我猜你的行动进行顺利。你有什么要向我报告呢?',ObjectiveText1_loc4='摧毁死亡熔炉的地狱火';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4) VALUES (10613,'狂暴的魔能机甲','<纳坎斯迅速翻阅着手册。>$B$B嗯，手册上记载了我需要的所有信息，现在只剩最后一个问题了。要知道，魔能机甲并不具备遥控的功能。$B$B不过，我们倒是可以改装出一台控制器来，但是它的控制有效期很短；你得抓紧时间，不然谁也无法预料会发生什么事！那帮燃烧军团的走狗目睹被控制的魔能机甲引发骚乱，必定会大跌眼镜。在确保自身安全的同时请以影月村赋予你的使命为重！','使用魔能机甲控制台控制一台魔能机甲斥候，并在控制失效之前杀死60个死亡熔炉地狱火。完成任务后向登陆场：灾难的纳坎斯复命。','我承认，$N。你完成的壮举让我很佩服。摧毁燃烧军团在影月的作战能力将会给我们机会扭转战局。','你回来啦，我猜你的行动进行顺利。你有什么要向我报告呢?','摧毁死亡熔炉的地狱火') ON DUPLICATE KEY UPDATE Title_loc4='狂暴的魔能机甲',Details_loc4='<纳坎斯迅速翻阅着手册。>$B$B嗯，手册上记载了我需要的所有信息，现在只剩最后一个问题了。要知道，魔能机甲并不具备遥控的功能。$B$B不过，我们倒是可以改装出一台控制器来，但是它的控制有效期很短；你得抓紧时间，不然谁也无法预料会发生什么事！那帮燃烧军团的走狗目睹被控制的魔能机甲引发骚乱，必定会大跌眼镜。在确保自身安全的同时请以影月村赋予你的使命为重！',Objectives_loc4='使用魔能机甲控制台控制一台魔能机甲斥候，并在控制失效之前杀死60个死亡熔炉地狱火。完成任务后向登陆场：灾难的纳坎斯复命。',OfferRewardText_loc4='我承认，$N。你完成的壮举让我很佩服。摧毁燃烧军团在影月的作战能力将会给我们机会扭转战局。',RequestItemsText_loc4='你回来啦，我猜你的行动进行顺利。你有什么要向我报告呢?',ObjectiveText1_loc4='摧毁死亡熔炉的地狱火';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10614,'风之细语','我遍访外域的每个角落，试图寻找莫克纳萨氏族的下落。希望是如此渺茫，在信念的支撑下我们终于查探到氏族的落脚点。$B$B眼看就要与族人相认，我却被内心的不安深深困扰着，这种焦虑常常令我从睡梦中惊醒。他们会接受我吗？$B$B我……我知道莫克纳萨氏族的首领名叫莱欧洛克斯。去找他吧，替我查探氏族的情况。','前往刀锋山的莫克纳萨村，寻找莱欧洛克斯。','你来到我们的村庄有甚么事?') ON DUPLICATE KEY UPDATE Title_loc4='风之细语',Details_loc4='我遍访外域的每个角落，试图寻找莫克纳萨氏族的下落。希望是如此渺茫，在信念的支撑下我们终于查探到氏族的落脚点。$B$B眼看就要与族人相认，我却被内心的不安深深困扰着，这种焦虑常常令我从睡梦中惊醒。他们会接受我吗？$B$B我……我知道莫克纳萨氏族的首领名叫莱欧洛克斯。去找他吧，替我查探氏族的情况。',Objectives_loc4='前往刀锋山的莫克纳萨村，寻找莱欧洛克斯。',OfferRewardText_loc4='你来到我们的村庄有甚么事?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10615,'卢安荒野','谢谢你帮我揭开了鸦人的秘密，我知道还有个家伙会对这些资料感兴趣。$B$B刀锋山的鸦人引起了塞纳里奥远征队的注意，我和这位故人正是通过远征队的成员认识的。$B$B他名叫坦莫，去卢安荒野的常青林找他吧。沿着西边的道路离开莫克纳萨村，到达剃刀山后往北转，然后在刀刃峡谷的岔路口往西走就是卢安荒野了。','前往刀锋山卢安荒野的常青林，与坦莫谈一谈。','啊，是，德托克。我们简要地谈了关于阿拉卡的事。我必须说，我们……对他们十分显着的变化感到兴趣。') ON DUPLICATE KEY UPDATE Title_loc4='卢安荒野',Details_loc4='谢谢你帮我揭开了鸦人的秘密，我知道还有个家伙会对这些资料感兴趣。$B$B刀锋山的鸦人引起了塞纳里奥远征队的注意，我和这位故人正是通过远征队的成员认识的。$B$B他名叫坦莫，去卢安荒野的常青林找他吧。沿着西边的道路离开莫克纳萨村，到达剃刀山后往北转，然后在刀刃峡谷的岔路口往西走就是卢安荒野了。',Objectives_loc4='前往刀锋山卢安荒野的常青林，与坦莫谈一谈。',OfferRewardText_loc4='啊，是，德托克。我们简要地谈了关于阿拉卡的事。我必须说，我们……对他们十分显着的变化感到兴趣。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10617,'丝翼蛾茧','丝翼巨蛾的茧丝用途广泛，是制作各种生活用品的主要原料。我们对茧丝的需求量居高不下。$b$b但是当幼虫开始蜕变时，就很难收集到蛾茧了。$b$b我们的士兵正忙着抵抗外敌入侵，如果你愿意抽空帮我们收集一些蛾茧就最好不过了。','从丝翼幼虫身上收集8个丝翼蛾茧。$b$b迅速杀死幼虫，否则它们就会蜕变成丝翼巨蛾，破坏蛾茧。','这些茧的品质真好。我看的出来你的手很适合采集它们。$B$B我们自己也有尝试养丝翼幼虫，但是可惜小只的幼虫并没有生产足够的茧供大家使用。','采集茧需要一双快速而稳健的手。我希望你能成功。') ON DUPLICATE KEY UPDATE Title_loc4='丝翼蛾茧',Details_loc4='丝翼巨蛾的茧丝用途广泛，是制作各种生活用品的主要原料。我们对茧丝的需求量居高不下。$b$b但是当幼虫开始蜕变时，就很难收集到蛾茧了。$b$b我们的士兵正忙着抵抗外敌入侵，如果你愿意抽空帮我们收集一些蛾茧就最好不过了。',Objectives_loc4='从丝翼幼虫身上收集8个丝翼蛾茧。$b$b迅速杀死幼虫，否则它们就会蜕变成丝翼巨蛾，破坏蛾茧。',OfferRewardText_loc4='这些茧的品质真好。我看的出来你的手很适合采集它们。$B$B我们自己也有尝试养丝翼幼虫，但是可惜小只的幼虫并没有生产足够的茧供大家使用。',RequestItemsText_loc4='采集茧需要一双快速而稳健的手。我希望你能成功。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10618,'最柔软的翅膀','对年轻的士兵而言，捕杀丝翼幼虫是一个艰巨的挑战。值得庆幸的是，就算无法从幼虫身上收集到蛾茧，我们仍然能够利用丝翼巨蛾的翅膀。$b$b事实上，蛾翼的用途比蛾茧更为广泛，我们对此的需求量也相当巨大。$b$b如果你恰好要外出，能不能帮我带些蛾翼回来？','收集12片虹光之翼。','谢谢你，$N。我们会比你想得更快使用这些东西。','这些翅膀十分精致，不过可加入我们的设计成为一个装饰的成份。') ON DUPLICATE KEY UPDATE Title_loc4='最柔软的翅膀',Details_loc4='对年轻的士兵而言，捕杀丝翼幼虫是一个艰巨的挑战。值得庆幸的是，就算无法从幼虫身上收集到蛾茧，我们仍然能够利用丝翼巨蛾的翅膀。$b$b事实上，蛾翼的用途比蛾茧更为广泛，我们对此的需求量也相当巨大。$b$b如果你恰好要外出，能不能帮我带些蛾翼回来？',Objectives_loc4='收集12片虹光之翼。',OfferRewardText_loc4='谢谢你，$N。我们会比你想得更快使用这些东西。',RequestItemsText_loc4='这些翅膀十分精致，不过可加入我们的设计成为一个装饰的成份。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10619,'灰舌氏族','灰舌氏族是所有破碎者中最可怕的存在，这个氏族的成员都经过阿卡玛的精挑细选，个个生性邪恶、嗜血成瘾。即使是与伊利丹麾下的其它纳迦部队、恶魔部队或是血精灵部队相比，他们的残忍与无情也毫不逊色。眼下，有大批灰舌破碎者盘踞在西南方的巴尔里废墟一带。我们要先下手为强，在这帮家伙有机会攻击我们之前削弱他们的势力。','守备官奥鲁门要你进入巴尔里废墟，杀死3名灰舌驯兽者、4名灰舌战士和6名灰舌萨满祭司。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。','纳鲁万岁，$N。你已经完成圣光的命令打败了伊利丹的追随者。','你已经完成我交给你的任务了吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='灰舌氏族',Details_loc4='灰舌氏族是所有破碎者中最可怕的存在，这个氏族的成员都经过阿卡玛的精挑细选，个个生性邪恶、嗜血成瘾。即使是与伊利丹麾下的其它纳迦部队、恶魔部队或是血精灵部队相比，他们的残忍与无情也毫不逊色。眼下，有大批灰舌破碎者盘踞在西南方的巴尔里废墟一带。我们要先下手为强，在这帮家伙有机会攻击我们之前削弱他们的势力。',Objectives_loc4='守备官奥鲁门要你进入巴尔里废墟，杀死3名灰舌驯兽者、4名灰舌战士和6名灰舌萨满祭司。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。',OfferRewardText_loc4='纳鲁万岁，$N。你已经完成圣光的命令打败了伊利丹的追随者。',RequestItemsText_loc4='你已经完成我交给你的任务了吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10620,'山脊上的危险','托什雷最初决定迁移到外域时，就雇佣了我们作帮手，我们从那时候起就搬到了这里。$B$B现在，我们终于在这里扎下一些根基了。这里几乎所有的狂热科学家们都在进行着各自的研究计划，而我们这些硬汉队的成员则要负责保护他们。$B$B现在我们需要你帮忙，请前往北边的剃刀山，或是东边的鳞翼岩床，清理那边的捕猎者吧。这些行踪诡秘的蜘蛛总是隐藏在露出地面的大块岩石附近，一旦有警惕心松懈的旅人经过，就会跳出来发动袭击。','杀死10只山脊捕猎者。','以一个菜鸟来说你做的还不错。结果我们有一批由书呆子组成的小队伍想要去北边“勘查”以太族还有他们的科技。这些书呆子要是知道了你帮他们清除了路上的危险一定很兴奋。$B$B来，这些拿去。我们拥有的数量并不多，但是希望它们可以在将来帮上你的忙。','你已经清光那些巡者了吗?我们已经有几个人往北边去却失踪了。$B$B假如是那些巡者造成的话，我要确保这种事情不会再发生。') ON DUPLICATE KEY UPDATE Title_loc4='山脊上的危险',Details_loc4='托什雷最初决定迁移到外域时，就雇佣了我们作帮手，我们从那时候起就搬到了这里。$B$B现在，我们终于在这里扎下一些根基了。这里几乎所有的狂热科学家们都在进行着各自的研究计划，而我们这些硬汉队的成员则要负责保护他们。$B$B现在我们需要你帮忙，请前往北边的剃刀山，或是东边的鳞翼岩床，清理那边的捕猎者吧。这些行踪诡秘的蜘蛛总是隐藏在露出地面的大块岩石附近，一旦有警惕心松懈的旅人经过，就会跳出来发动袭击。',Objectives_loc4='杀死10只山脊捕猎者。',OfferRewardText_loc4='以一个菜鸟来说你做的还不错。结果我们有一批由书呆子组成的小队伍想要去北边“勘查”以太族还有他们的科技。这些书呆子要是知道了你帮他们清除了路上的危险一定很兴奋。$B$B来，这些拿去。我们拥有的数量并不多，但是希望它们可以在将来帮上你的忙。',RequestItemsText_loc4='你已经清光那些巡者了吗?我们已经有几个人往北边去却失踪了。$B$B假如是那些巡者造成的话，我要确保这种事情不会再发生。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10621,'伊利达雷斩除碎片','这似乎是一块武器的残片，金属表面镌刻着的符文依然清晰可辨，并闪烁着诡异的光芒。$B$B这把武器的用途已经不得而知，但你很想解开这个疑团。军团要塞的莫尔葛武器匠似乎经常使用这种材质的金属铸造武器。或许蛮锤要塞的武器锻造师能替你揭开谜底？','将伊利达雷斩除碎片交给蛮锤要塞的奥丁·雷拳。','<欧尔汀从你手中接过了武器碎片。>$B$B我好久没看过这种东西了。当然，这是由一个稀有的矿石所制造的，但是它肯定不是一般普通的武器，$N。它的剑身被注入一股消灭恶魔的魔法能量。假如你是从燃烧军团那边取来的，那一定是他们在制造某种“秘密武器”，计划用来对付伊利丹。真是一大发现!','你手中的是什么东西?') ON DUPLICATE KEY UPDATE Title_loc4='伊利达雷斩除碎片',Details_loc4='这似乎是一块武器的残片，金属表面镌刻着的符文依然清晰可辨，并闪烁着诡异的光芒。$B$B这把武器的用途已经不得而知，但你很想解开这个疑团。军团要塞的莫尔葛武器匠似乎经常使用这种材质的金属铸造武器。或许蛮锤要塞的武器锻造师能替你揭开谜底？',Objectives_loc4='将伊利达雷斩除碎片交给蛮锤要塞的奥丁·雷拳。',OfferRewardText_loc4='<欧尔汀从你手中接过了武器碎片。>$B$B我好久没看过这种东西了。当然，这是由一个稀有的矿石所制造的，但是它肯定不是一般普通的武器，$N。它的剑身被注入一股消灭恶魔的魔法能量。假如你是从燃烧军团那边取来的，那一定是他们在制造某种“秘密武器”，计划用来对付伊利丹。真是一大发现!',RequestItemsText_loc4='你手中的是什么东西?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10622,'忠诚的证明','$N，你不知道，其实阿卡玛大人一直在暗中观察你的动向。$B$B事实上，你在巴尔里废墟杀死的那些灰舌氏族成员正是所有破碎者中生性最为邪恶的一群，阿卡玛精心挑选出这样一批凶残的成员，为的正是利用他们的表现迷惑伊利丹。而我们灰舌死誓者才是阿卡玛真正的心腹，只有我们才了解大人真正的意图。$B$B最重要的事情是，我们必须确定你不是伊利丹的同伙。伊利丹指派了一个名叫杉德拉斯的萨特负责监视整座守望者牢笼。杀死他，以此证明你的忠诚。','杀死影月谷内守望者牢笼的杉德拉斯，然后向萨诺鲁复命。','很好，$N。你已经表明了你的立场。你现在可以见阿卡玛。','你完成我要求你的事了吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='忠诚的证明',Details_loc4='$N，你不知道，其实阿卡玛大人一直在暗中观察你的动向。$B$B事实上，你在巴尔里废墟杀死的那些灰舌氏族成员正是所有破碎者中生性最为邪恶的一群，阿卡玛精心挑选出这样一批凶残的成员，为的正是利用他们的表现迷惑伊利丹。而我们灰舌死誓者才是阿卡玛真正的心腹，只有我们才了解大人真正的意图。$B$B最重要的事情是，我们必须确定你不是伊利丹的同伙。伊利丹指派了一个名叫杉德拉斯的萨特负责监视整座守望者牢笼。杀死他，以此证明你的忠诚。',Objectives_loc4='杀死影月谷内守望者牢笼的杉德拉斯，然后向萨诺鲁复命。',OfferRewardText_loc4='很好，$N。你已经表明了你的立场。你现在可以见阿卡玛。',RequestItemsText_loc4='你完成我要求你的事了吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10623,'伊利达雷斩除碎片','这似乎是一块武器的残片，金属表面镌刻着的符文依然清晰可辨，并闪烁着诡异的光芒。$B$B这把武器的用途已经不得而知，但你很想解开这个疑团。军团要塞的莫尔葛武器匠似乎经常使用这种材质的金属铸造武器。或许影月村的武器锻造师能替你揭开谜底？','将伊利达雷斩除碎片交给影月村的格罗克姆·死眼。','<格罗姆空从你手中接过了武器碎片。>$B$B我好久没看过这种东西了。这块碎片不光是从一个稀有的矿石所打造的，它也不是用在一般的武器上面，$N。上面的魔法图样赋予了武器消灭恶魔的力量。假如他们愿意让他们的部队配备消灭恶魔的武器，这表示燃烧军团有多痛恨伊利丹。我们可以利用这点从中获利。','你带来了什么东西呢?') ON DUPLICATE KEY UPDATE Title_loc4='伊利达雷斩除碎片',Details_loc4='这似乎是一块武器的残片，金属表面镌刻着的符文依然清晰可辨，并闪烁着诡异的光芒。$B$B这把武器的用途已经不得而知，但你很想解开这个疑团。军团要塞的莫尔葛武器匠似乎经常使用这种材质的金属铸造武器。或许影月村的武器锻造师能替你揭开谜底？',Objectives_loc4='将伊利达雷斩除碎片交给影月村的格罗克姆·死眼。',OfferRewardText_loc4='<格罗姆空从你手中接过了武器碎片。>$B$B我好久没看过这种东西了。这块碎片不光是从一个稀有的矿石所打造的，它也不是用在一般的武器上面，$N。上面的魔法图样赋予了武器消灭恶魔的力量。假如他们愿意让他们的部队配备消灭恶魔的武器，这表示燃烧军团有多痛恨伊利丹。我们可以利用这点从中获利。',RequestItemsText_loc4='你带来了什么东西呢?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10624,'阴森的历史','你感受到阵阵的寒意了吗？就像冰凉的手掌落在肩上？$r，这并不是你的错觉。这儿确实有鬼魂出没，不散的怨灵永世在这片土地上徘徊着。$B$B你确定想看看他们的模样吗？这很可能会影响你的一生——而且是不良的影响。$B$B那么好吧，我要你前往影月谷西部的熔岩池收集一些永燃灰烬。绿色熔岩池附近到处都是这种东西……','将15份永燃灰烬样本交给影月谷影月村的主药剂师希尔达迦。','你的世界即将改变，$N。$B$B<希尔达嘉开始用灰烬制造某样东西。>','你的意思是?很明显的-我要把这些灰烬制成某种东西。') ON DUPLICATE KEY UPDATE Title_loc4='阴森的历史',Details_loc4='你感受到阵阵的寒意了吗？就像冰凉的手掌落在肩上？$r，这并不是你的错觉。这儿确实有鬼魂出没，不散的怨灵永世在这片土地上徘徊着。$B$B你确定想看看他们的模样吗？这很可能会影响你的一生——而且是不良的影响。$B$B那么好吧，我要你前往影月谷西部的熔岩池收集一些永燃灰烬。绿色熔岩池附近到处都是这种东西……',Objectives_loc4='将15份永燃灰烬样本交给影月谷影月村的主药剂师希尔达迦。',OfferRewardText_loc4='你的世界即将改变，$N。$B$B<希尔达嘉开始用灰烬制造某样东西。>',RequestItemsText_loc4='你的意思是?很明显的-我要把这些灰烬制成某种东西。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10625,'幽灵眼镜','我把这东西称为“幽灵眼镜”。很棒的名字，不是吗？戴上这副护目镜，你就能看见影月谷中的鬼魂。$B$B在把幽灵眼镜交给你之前，你得答应我一件事：帮我们清除影月村的鬼魂。$B$B来吧，戴上护目镜，杀掉徘徊在村落中的鬼魂。希望这能起到杀一儆百的效果，迫使剩馀的鬼魂离开影月村。','影月谷影月村的主药剂师希尔达迦要你去杀死12个影月狂徒。','血魔?泰…… 泰朗.血魔?这……这怎么可能呢?$B$B血魔怎么可能会在这里呢?这是不可能的!$B$B传说中的泰朗.血魔当初可是造成连遗忘者都会因恐惧而发抖呢。总而言之，血魔曾经是古尔丹的一个术士-他自身就拥有非常强大的力量。当血魔被奥格林.末日锤给杀了之后，古尔丹把这个阵亡的术士灵魂拿去植入一个被杀死的暴风城已故骑士受损的躯体之中。部落的第一个死亡骑士于是就这么诞生了。','假如你遗失了你的护目镜，让我知道我会制造一副新的给你。') ON DUPLICATE KEY UPDATE Title_loc4='幽灵眼镜',Details_loc4='我把这东西称为“幽灵眼镜”。很棒的名字，不是吗？戴上这副护目镜，你就能看见影月谷中的鬼魂。$B$B在把幽灵眼镜交给你之前，你得答应我一件事：帮我们清除影月村的鬼魂。$B$B来吧，戴上护目镜，杀掉徘徊在村落中的鬼魂。希望这能起到杀一儆百的效果，迫使剩馀的鬼魂离开影月村。',Objectives_loc4='影月谷影月村的主药剂师希尔达迦要你去杀死12个影月狂徒。',OfferRewardText_loc4='血魔?泰…… 泰朗.血魔?这……这怎么可能呢?$B$B血魔怎么可能会在这里呢?这是不可能的!$B$B传说中的泰朗.血魔当初可是造成连遗忘者都会因恐惧而发抖呢。总而言之，血魔曾经是古尔丹的一个术士-他自身就拥有非常强大的力量。当血魔被奥格林.末日锤给杀了之后，古尔丹把这个阵亡的术士灵魂拿去植入一个被杀死的暴风城已故骑士受损的躯体之中。部落的第一个死亡骑士于是就这么诞生了。',RequestItemsText_loc4='假如你遗失了你的护目镜，让我知道我会制造一副新的给你。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10626,'夺取武器','如果你能提供更多的此类材料，我就能为你铸造一柄适合的武器。$B$B军团要塞的两位深渊领主玛卡扎顿和莫戈洛隆就随身带着这种特殊的抗魔武器。如果能取回这两柄武器重新熔铸，应该就有足够的材料了，或许还有许多剩下来的呢。$B$B<奥丁咧嘴一笑。>$B$B用燃烧军团的“秘密武器”来对付他们应该相当有趣，不是吗？','将玛卡扎顿之刃和莫戈洛隆之刃交给蛮锤要塞的奥丁·雷拳。','这些就够了。现在，让我们把它们打造成更有用的形态吧。','你找到那些原始样本了吗?') ON DUPLICATE KEY UPDATE Title_loc4='夺取武器',Details_loc4='如果你能提供更多的此类材料，我就能为你铸造一柄适合的武器。$B$B军团要塞的两位深渊领主玛卡扎顿和莫戈洛隆就随身带着这种特殊的抗魔武器。如果能取回这两柄武器重新熔铸，应该就有足够的材料了，或许还有许多剩下来的呢。$B$B<奥丁咧嘴一笑。>$B$B用燃烧军团的“秘密武器”来对付他们应该相当有趣，不是吗？',Objectives_loc4='将玛卡扎顿之刃和莫戈洛隆之刃交给蛮锤要塞的奥丁·雷拳。',OfferRewardText_loc4='这些就够了。现在，让我们把它们打造成更有用的形态吧。',RequestItemsText_loc4='你找到那些原始样本了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10627,'夺取武器','如果你能提供更多的此类材料，我就能为你铸造一柄适合的武器。$B$B军团要塞的两位深渊领主玛卡扎顿和莫戈洛隆就随身带着这种特殊的抗魔武器。如果能取回这两柄武器重新熔铸，应该就有足够的材料了，或许还会有许多剩下来呢。$B$B真是迫不及待地想让那些家伙尝尝抗魔武器的厉害了。','将玛卡扎顿之刃和莫戈洛隆之刃交给影月村的格罗克姆·死眼。','这些就够了。现在，让我们把它们打造成更有用的形态吧。','你找到那些原始样本了吗?') ON DUPLICATE KEY UPDATE Title_loc4='夺取武器',Details_loc4='如果你能提供更多的此类材料，我就能为你铸造一柄适合的武器。$B$B军团要塞的两位深渊领主玛卡扎顿和莫戈洛隆就随身带着这种特殊的抗魔武器。如果能取回这两柄武器重新熔铸，应该就有足够的材料了，或许还会有许多剩下来呢。$B$B真是迫不及待地想让那些家伙尝尝抗魔武器的厉害了。',Objectives_loc4='将玛卡扎顿之刃和莫戈洛隆之刃交给影月村的格罗克姆·死眼。',OfferRewardText_loc4='这些就够了。现在，让我们把它们打造成更有用的形态吧。',RequestItemsText_loc4='你找到那些原始样本了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10628,'阿卡玛','你并非伊利丹的同伙，这点我们已经清楚了。我现在就告诉你阿卡玛大人的藏身之处。$B$B你从这里沿着墙一直走，不久之后就会看到右手边有一潭死水，地下秘道就在那儿。$B$B$N，我必须
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10629,'肮脏的工作','伐木机总算是修好了，可我好像又把钥匙弄丢了。我养了一群地狱警卫犬来保护营地，不过这帮废物除了喜欢咬我之外什么事儿都办不成。它们还特别喜欢亮晶晶的东西。我猜伐木机钥匙大约是被其中一只警卫犬给吃了。如果你愿意带它出去散散步的话，我就付给你一大笔钱。散步的时候杀些地狱野猪来喂它，饱餐之后它肯定得按自然规律办事。然后，你就在它排出的“残渣”里找找看有没有钥匙吧。','使用地狱犬哨召唤一只恶魔警卫犬。带恶魔警卫犬外出散步，并猎杀疯狂的地狱野猪来喂养它。在恶魔警卫犬排出的“残渣”中寻找伐木机钥匙。然后返回萨尔玛西北方的矿洞，将伐木机钥匙交给工头拉泽克拉兹。','你身上的味道真臭。但是你找到我的钥匙了!非常的感谢你。现在我的伐木机可以开始帮我赚钱了。不用多久我就可以赚到足够的钱离开外域了。我不知道你为什么想待在这里，我痛恨这个地方。你难道不想回藏宝海湾吗?$B$B也许可以钓钓鱼?','你找到我的钥匙了吗?我确定我养的其中一只恶魔犬吃了它。可能是我派去给你的那一只。大概是吧。') ON DUPLICATE KEY UPDATE Title_loc4='肮脏的工作',Details_loc4='伐木机总算是修好了，可我好像又把钥匙弄丢了。我养了一群地狱警卫犬来保护营地，不过这帮废物除了喜欢咬我之外什么事儿都办不成。它们还特别喜欢亮晶晶的东西。我猜伐木机钥匙大约是被其中一只警卫犬给吃了。如果你愿意带它出去散散步的话，我就付给你一大笔钱。散步的时候杀些地狱野猪来喂它，饱餐之后它肯定得按自然规律办事。然后，你就在它排出的“残渣”里找找看有没有钥匙吧。',Objectives_loc4='使用地狱犬哨召唤一只恶魔警卫犬。带恶魔警卫犬外出散步，并猎杀疯狂的地狱野猪来喂养它。在恶魔警卫犬排出的“残渣”中寻找伐木机钥匙。然后返回萨尔玛西北方的矿洞，将伐木机钥匙交给工头拉泽克拉兹。',OfferRewardText_loc4='你身上的味道真臭。但是你找到我的钥匙了!非常的感谢你。现在我的伐木机可以开始帮我赚钱了。不用多久我就可以赚到足够的钱离开外域了。我不知道你为什么想待在这里，我痛恨这个地方。你难道不想回藏宝海湾吗?$B$B也许可以钓钓鱼?',RequestItemsText_loc4='你找到我的钥匙了吗?我确定我养的其中一只恶魔犬吃了它。可能是我派去给你的那一只。大概是吧。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10630,'萨尔玛的地下','我本来马上就可以开始干活了。可……现在问题是我的矿里怎么会有这么多的甘尔葛。我没法派苦工进去，而且，虽然机器人修好了，可我也不想在战斗中把它弄坏。矿洞的深处肯定有一个甘尔葛的头目在坐镇指挥。要是你去把它干掉，或许这帮甘尔葛就会被吓跑，然后我就可以开始挣钱买票回家了。','杀死乌加兹，然后返回萨尔玛西北方的矿洞，向工头拉泽克拉兹复命。','全部的甘纳格已经要离开了。我会再一个礼拜之内回到藏宝海湾。我等不及想再次钓鱼了。来到外域是一个错误的决定。假如你肯接受我的建议的话，就顺原路回去。花点时间待在荆棘谷，或者假如你有冒险的精神，也可以去安戈洛环形山。反正不要待在这里就对了。','他已经死了吗?我不敢看。') ON DUPLICATE KEY UPDATE Title_loc4='萨尔玛的地下',Details_loc4='我本来马上就可以开始干活了。可……现在问题是我的矿里怎么会有这么多的甘尔葛。我没法派苦工进去，而且，虽然机器人修好了，可我也不想在战斗中把它弄坏。矿洞的深处肯定有一个甘尔葛的头目在坐镇指挥。要是你去把它干掉，或许这帮甘尔葛就会被吓跑，然后我就可以开始挣钱买票回家了。',Objectives_loc4='杀死乌加兹，然后返回萨尔玛西北方的矿洞，向工头拉泽克拉兹复命。',OfferRewardText_loc4='全部的甘纳格已经要离开了。我会再一个礼拜之内回到藏宝海湾。我等不及想再次钓鱼了。来到外域是一个错误的决定。假如你肯接受我的建议的话，就顺原路回去。花点时间待在荆棘谷，或者假如你有冒险的精神，也可以去安戈洛环形山。反正不要待在这里就对了。',RequestItemsText_loc4='他已经死了吗?我不敢看。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10632,'锋利的牙齿','你能帮助托什雷和他的科学家朋友们，这可真是太好了。然而，我却没有那个奢侈的条件去纵容我的“个人兴趣爱好”。$B$B如果你真想改善这里的状况，就得按我说的去做。现在，我需要武器。$B$B我们的枪在远距离的时候效果很不错，但如果被那些虫子接近的话，就需要强力的近战武器了。$B$B栖息在北边剃刀山一带的刃喉鞭尾龙有着锋利的牙齿，非常适合做成武器的刃部。给我带一些回来。','收集5颗非常锐利的刃喉龙牙。','做的好，小朋友。只要有一个士兵因为你的努力而救回一命的话，你所受的苦都是值得的。$B$B我想你付出的汗水与泪水应该被奖励。既然我们不久之后就会有一批新的武器，你就先从我这拿走一把吧?','你的牙齿收集的如何呢?$B$B我确定你可以为我们顺利的取得它们。在你完成之前，我们会一直驻守在哨站这边。') ON DUPLICATE KEY UPDATE Title_loc4='锋利的牙齿',Details_loc4='你能帮助托什雷和他的科学家朋友们，这可真是太好了。然而，我却没有那个奢侈的条件去纵容我的“个人兴趣爱好”。$B$B如果你真想改善这里的状况，就得按我说的去做。现在，我需要武器。$B$B我们的枪在远距离的时候效果很不错，但如果被那些虫子接近的话，就需要强力的近战武器了。$B$B栖息在北边剃刀山一带的刃喉鞭尾龙有着锋利的牙齿，非常适合做成武器的刃部。给我带一些回来。',Objectives_loc4='收集5颗非常锐利的刃喉龙牙。',OfferRewardText_loc4='做的好，小朋友。只要有一个士兵因为你的努力而救回一命的话，你所受的苦都是值得的。$B$B我想你付出的汗水与泪水应该被奖励。既然我们不久之后就会有一批新的武器，你就先从我这拿走一把吧?',RequestItemsText_loc4='你的牙齿收集的如何呢?$B$B我确定你可以为我们顺利的取得它们。在你完成之前，我们会一直驻守在哨站这边。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10633,'塔隆·血魔的传说','世间流传着许多关于塔隆·血魔的故事，但是大多数都只是传说。人们并不知道塔隆·血魔返回德拉诺世界后发生的事。$B$B我们只能确定一件事，那就是他已经死了。$B$B我曾听这儿的斥候说，在遥远的东南方，跨越灵翼平原，穿过灵翼小径就能到达暗影祭坛，有位远古的兽人灵魂居住在那儿。戴上幽灵眼镜搜寻这位兽人。他应该知道更多关于塔隆·血魔的事。','影月谷影月村的主药剂师希尔达迦要你找到上古影月之魂。$B$B如果你弄丢了幽灵眼镜，主药剂师希尔达迦可以再帮你做一副。','血魔?你为什么这么问，我已经很多年没有听到这个名字了!$B$B在第二次大战之后，血魔回到了这里，旁边跟着他的死亡骑士们。无法适应他的新形态所带来极坏的天性又失去他最尊敬的领导者古尔丹的支持，血魔自杀了。$B$B假如他现在以灵魂的形态游走在这片大地的话，对我来说倒是个新消息。但是，也许有了你的协助我可以研究推敲相关的消息。','你看的见我?真神奇!') ON DUPLICATE KEY UPDATE Title_loc4='塔隆·血魔的传说',Details_loc4='世间流传着许多关于塔隆·血魔的故事，但是大多数都只是传说。人们并不知道塔隆·血魔返回德拉诺世界后发生的事。$B$B我们只能确定一件事，那就是他已经死了。$B$B我曾听这儿的斥候说，在遥远的东南方，跨越灵翼平原，穿过灵翼小径就能到达暗影祭坛，有位远古的兽人灵魂居住在那儿。戴上幽灵眼镜搜寻这位兽人。他应该知道更多关于塔隆·血魔的事。',Objectives_loc4='影月谷影月村的主药剂师希尔达迦要你找到上古影月之魂。$B$B如果你弄丢了幽灵眼镜，主药剂师希尔达迦可以再帮你做一副。',OfferRewardText_loc4='血魔?你为什么这么问，我已经很多年没有听到这个名字了!$B$B在第二次大战之后，血魔回到了这里，旁边跟着他的死亡骑士们。无法适应他的新形态所带来极坏的天性又失去他最尊敬的领导者古尔丹的支持，血魔自杀了。$B$B假如他现在以灵魂的形态游走在这片大地的话，对我来说倒是个新消息。但是，也许有了你的协助我可以研究推敲相关的消息。',RequestItemsText_loc4='你看的见我?真神奇!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10634,'占卜：血魔的护甲','血魔活着的时候就是个不折不扣的混蛋，死了之后依然恶性不改，祸害世间。$B$B东南方的灵翼浮岛本是影月谷大陆的一部分，如今已变成一座残破的浮岛。$B$B这个地方曾经是死亡之翼的后嗣厄库尔的家园，但现在这里只是他的埋骨之地。厄库尔还在浮岛上空盘旋着，被血魔击败的耻辱令他狂怒不已。$B$B想要取回血魔的护甲，就得打败厄库尔。','将血魔的护甲交给影月谷东南方暗影祭坛的上古影月之魂。','我必须拥有全部三样的物品才能占卜到血魔的去向。','飞到虚空之翼岩架取回物品。') ON DUPLICATE KEY UPDATE Title_loc4='占卜：血魔的护甲',Details_loc4='血魔活着的时候就是个不折不扣的混蛋，死了之后依然恶性不改，祸害世间。$B$B东南方的灵翼浮岛本是影月谷大陆的一部分，如今已变成一座残破的浮岛。$B$B这个地方曾经是死亡之翼的后嗣厄库尔的家园，但现在这里只是他的埋骨之地。厄库尔还在浮岛上空盘旋着，被血魔击败的耻辱令他狂怒不已。$B$B想要取回血魔的护甲，就得打败厄库尔。',Objectives_loc4='将血魔的护甲交给影月谷东南方暗影祭坛的上古影月之魂。',OfferRewardText_loc4='我必须拥有全部三样的物品才能占卜到血魔的去向。',RequestItemsText_loc4='飞到虚空之翼岩架取回物品。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10635,'占卜：血魔的披风','血魔这家伙可谓是罪行累累，其中最残忍一次的要数卡拉波的牧师大屠杀事件。$B$B当年，古尔丹率领大军击败了驻守在卡拉波神殿的德莱尼人，幸存的卡拉波祭司们沦为战俘，兽人们便将这些牧师统统关押在地狱火堡垒中。$B$B那时，血魔还未堕落成死亡骑士，这个冷血的畜生竟然杀光了那些毫无反抗能力的战俘。如今，卡拉波祭司们的怨灵依然在黑暗神殿前游荡着，他们心中复仇的怒火愈燃愈烈。$B$B血魔的披风就在那些卡拉波的牧师手中。','将血魔的披风交给影月谷东南方暗影祭坛的上古影月之魂。','当我拥有全部三样的物品才能占卜到血魔的去向。','你必须使用显灵镜才能看见影月谷的灵魂。') ON DUPLICATE KEY UPDATE Title_loc4='占卜：血魔的披风',Details_loc4='血魔这家伙可谓是罪行累累，其中最残忍一次的要数卡拉波的牧师大屠杀事件。$B$B当年，古尔丹率领大军击败了驻守在卡拉波神殿的德莱尼人，幸存的卡拉波祭司们沦为战俘，兽人们便将这些牧师统统关押在地狱火堡垒中。$B$B那时，血魔还未堕落成死亡骑士，这个冷血的畜生竟然杀光了那些毫无反抗能力的战俘。如今，卡拉波祭司们的怨灵依然在黑暗神殿前游荡着，他们心中复仇的怒火愈燃愈烈。$B$B血魔的披风就在那些卡拉波的牧师手中。',Objectives_loc4='将血魔的披风交给影月谷东南方暗影祭坛的上古影月之魂。',OfferRewardText_loc4='当我拥有全部三样的物品才能占卜到血魔的去向。',RequestItemsText_loc4='你必须使用显灵镜才能看见影月谷的灵魂。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10636,'占卜：血魔的权杖','他们一个接一个地跪下来，愿以自身性命为誓效忠血魔。血魔手起刀落，砍下了他们的首级。大屠杀之后，这个残忍的刽子手便自杀了。$B$B他可不是诚心悔罪！绝不是，这家伙是在追求永生！卡拉波幽灵骑士在死亡骑士的尸体上复苏。$B$B他们绕着古尔丹之手行进，等待着主人的归来。血魔的权杖就在他们手中。把它取回来……','将血魔的权杖交给影月谷东南方暗影祭坛的上古影月之魂。','只有三样东西都到齐我才能帮你解开你迫切想寻找的答案!','你必须使用显灵镜才能看见影月谷的灵魂。') ON DUPLICATE KEY UPDATE Title_loc4='占卜：血魔的权杖',Details_loc4='他们一个接一个地跪下来，愿以自身性命为誓效忠血魔。血魔手起刀落，砍下了他们的首级。大屠杀之后，这个残忍的刽子手便自杀了。$B$B他可不是诚心悔罪！绝不是，这家伙是在追求永生！卡拉波幽灵骑士在死亡骑士的尸体上复苏。$B$B他们绕着古尔丹之手行进，等待着主人的归来。血魔的权杖就在他们手中。把它取回来……',Objectives_loc4='将血魔的权杖交给影月谷东南方暗影祭坛的上古影月之魂。',OfferRewardText_loc4='只有三样东西都到齐我才能帮你解开你迫切想寻找的答案!',RequestItemsText_loc4='你必须使用显灵镜才能看见影月谷的灵魂。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4) VALUES (10637,'必要的混乱','这些武器足以证明我们的担忧不是没有道理。伊利丹确实在卡拉波废墟训练恶魔猎手，我们必须阻止他进一步扩大势力。$B$B$N，别被恶魔猎手这名字给迷惑了，总有一天这帮家伙会像对付恶魔那样来对付我们的。$B$B目前，还有一批日怒术士在卡拉波废墟召唤并奴役恶魔，用于新兵训练。他们曾召唤出一个名叫阿萨洛斯的深渊领主，不过阿萨洛斯过于强大，并不适合新兵的训练课程，术士们只得不断地放逐他。设法令阿萨洛斯摆脱放逐，这场混乱必定能为我们赢得了解敌情的时间。','大主教欧纳拉要你返回卡拉波废墟，设法令阿萨洛斯摆脱放逐状态。$B$B为奥尔多完成任务将会降低你在占星者阵营中的声望等级。','希望你制造的混乱可以帮我们争取到足够的时间，让我们对卡拉伯尔废墟训练场有充份的了解。','你已经完成我的要求了吗?','释放阿萨洛斯') ON DUPLICATE KEY UPDATE Title_loc4='必要的混乱',Details_loc4='这些武器足以证明我们的担忧不是没有道理。伊利丹确实在卡拉波废墟训练恶魔猎手，我们必须阻止他进一步扩大势力。$B$B$N，别被恶魔猎手这名字给迷惑了，总有一天这帮家伙会像对付恶魔那样来对付我们的。$B$B目前，还有一批日怒术士在卡拉波废墟召唤并奴役恶魔，用于新兵训练。他们曾召唤出一个名叫阿萨洛斯的深渊领主，不过阿萨洛斯过于强大，并不适合新兵的训练课程，术士们只得不断地放逐他。设法令阿萨洛斯摆脱放逐，这场混乱必定能为我们赢得了解敌情的时间。',Objectives_loc4='大主教欧纳拉要你返回卡拉波废墟，设法令阿萨洛斯摆脱放逐状态。$B$B为奥尔多完成任务将会降低你在占星者阵营中的声望等级。',OfferRewardText_loc4='希望你制造的混乱可以帮我们争取到足够的时间，让我们对卡拉伯尔废墟训练场有充份的了解。',RequestItemsText_loc4='你已经完成我的要求了吗?',ObjectiveText1_loc4='释放阿萨洛斯';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10638,'影月城的训练','在影月城找到你的训练师。','在影月城的<地区>寻找<姓名>。','啦啦啦……该是学新东西的时候了。') ON DUPLICATE KEY UPDATE Title_loc4='影月城的训练',Details_loc4='在影月城找到你的训练师。',Objectives_loc4='在影月城的<地区>寻找<姓名>。',OfferRewardText_loc4='啦啦啦……该是学新东西的时候了。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10639,'我就是塔隆·血魔……','你取回了塔隆·血魔的所有对象，离谜底仅剩一步之遥：寄主。$B$B<上古影月之魂邪恶地咧嘴一笑。>$B$B你显然不相信我之前告诉你的故事。暗影祭坛便是我的牢狱。没有你的帮助，我大概会永世被禁锢在这座祭坛中。现在，我要寄宿在你体内。杀死上古看守者卡修斯，让我摆脱束缚。如果你拒绝的话，那咱俩就永远留在这儿好了。$B$B塔隆·血魔就要重获自由了！','上古影月之魂利用了你！在你集齐所有的物品后，他便露出了真面目，原来这家伙就是塔隆·血魔。想要摆脱束缚，就必须按他的吩咐杀死上古看守者卡修斯。$B$B杀死卡修斯之后，向影月村的主药剂师希尔达迦复命。','你做了什么?愚蠢!$B$B你必须纠正你犯下的错。毕竟，这是你的责任。从这里挑一顶盔帽去吧。每一顶盔帽都灌注了你帮我取得的永燃灰烬。更重要的是，他们会赋予你看见影月谷鬼魂的能力，包含泰朗.血魔。$B$B当你找到泰朗.血魔的时候，杀死他。','你说什么?') ON DUPLICATE KEY UPDATE Title_loc4='我就是塔隆·血魔……',Details_loc4='你取回了塔隆·血魔的所有对象，离谜底仅剩一步之遥：寄主。$B$B<上古影月之魂邪恶地咧嘴一笑。>$B$B你显然不相信我之前告诉你的故事。暗影祭坛便是我的牢狱。没有你的帮助，我大概会永世被禁锢在这座祭坛中。现在，我要寄宿在你体内。杀死上古看守者卡修斯，让我摆脱束缚。如果你拒绝的话，那咱俩就永远留在这儿好了。$B$B塔隆·血魔就要重获自由了！',Objectives_loc4='上古影月之魂利用了你！在你集齐所有的物品后，他便露出了真面目，原来这家伙就是塔隆·血魔。想要摆脱束缚，就必须按他的吩咐杀死上古看守者卡修斯。$B$B杀死卡修斯之后，向影月村的主药剂师希尔达迦复命。',OfferRewardText_loc4='你做了什么?愚蠢!$B$B你必须纠正你犯下的错。毕竟，这是你的责任。从这里挑一顶盔帽去吧。每一顶盔帽都灌注了你帮我取得的永燃灰烬。更重要的是，他们会赋予你看见影月谷鬼魂的能力，包含泰朗.血魔。$B$B当你找到泰朗.血魔的时候，杀死他。',RequestItemsText_loc4='你说什么?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10640,'奥图里斯','如今，选择恶魔猎手之路的人本来就非常罕见，要找到不愿意追随伊利丹的恶魔猎手更是难上加难。$B$B不过，据说外域就有这样一位英雄人物。他的名字令纳格兰的燃烧军团闻风丧胆，整支奥尔多守备军的官团都无法与他的力量抗衡。他就是奥图里斯。$B$B前往纳格兰西部寻找奥图里斯。他或许会告诉我们关于恶魔猎手训练场的事。','前往纳格兰西部寻找受难者奥图里斯。$B$B为奥尔多完成任务将会降低你在占星者阵营中的声望等级。','你竟然大老远的跑来找我，陌生人。我很惊讶派你来的人竟然知道我是谁。') ON DUPLICATE KEY UPDATE Title_loc4='奥图里斯',Details_loc4='如今，选择恶魔猎手之路的人本来就非常罕见，要找到不愿意追随伊利丹的恶魔猎手更是难上加难。$B$B不过，据说外域就有这样一位英雄人物。他的名字令纳格兰的燃烧军团闻风丧胆，整支奥尔多守备军的官团都无法与他的力量抗衡。他就是奥图里斯。$B$B前往纳格兰西部寻找奥图里斯。他或许会告诉我们关于恶魔猎手训练场的事。',Objectives_loc4='前往纳格兰西部寻找受难者奥图里斯。$B$B为奥尔多完成任务将会降低你在占星者阵营中的声望等级。',OfferRewardText_loc4='你竟然大老远的跑来找我，陌生人。我很惊讶派你来的人竟然知道我是谁。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10641,'对抗军团','燃烧军团可以令凡人的灵魂堕落腐化，这已是不争的事实，所以我并不信任你。想要从我口中得知恶魔训练场的详情，就必须证明你并非是燃烧军团的间谍。$B$B我正在追踪一个名叫萨莎尔的女恶魔，可惜她是以虚体形态存在的，因此总能逃脱我的侦测。$B$B萨莎尔负责管理铸魔基地：炼狱的天罚祭司，这些天罚祭司是她的心腹和爪牙，只听从她的命令。杀掉她的天罚祭司，将那祭司体内的魔血泼在地上。这必定会激得萨莎尔暂时显露真身，趁此机会杀死她。','受难者奥图里斯要你前往虚空风暴的铸魔基地：炼狱，从天罚祭司身上取回一份新鲜的魔血。然后，将新鲜的魔血泼在地上，并杀死萨莎尔的化身。完成任务之后向奥图里斯复命。','你已经证明你并没有跟燃烧军团接触而腐化而我的敌人的敌人则是我的朋友。','你杀死那个恶魔了吗?') ON DUPLICATE KEY UPDATE Title_loc4='对抗军团',Details_loc4='燃烧军团可以令凡人的灵魂堕落腐化，这已是不争的事实，所以我并不信任你。想要从我口中得知恶魔训练场的详情，就必须证明你并非是燃烧军团的间谍。$B$B我正在追踪一个名叫萨莎尔的女恶魔，可惜她是以虚体形态存在的，因此总能逃脱我的侦测。$B$B萨莎尔负责管理铸魔基地：炼狱的天罚祭司，这些天罚祭司是她的心腹和爪牙，只听从她的命令。杀掉她的天罚祭司，将那祭司体内的魔血泼在地上。这必定会激得萨莎尔暂时显露真身，趁此机会杀死她。',Objectives_loc4='受难者奥图里斯要你前往虚空风暴的铸魔基地：炼狱，从天罚祭司身上取回一份新鲜的魔血。然后，将新鲜的魔血泼在地上，并杀死萨莎尔的化身。完成任务之后向奥图里斯复命。',OfferRewardText_loc4='你已经证明你并没有跟燃烧军团接触而腐化而我的敌人的敌人则是我的朋友。',RequestItemsText_loc4='你杀死那个恶魔了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10642,'要塞中的幽灵','这些笨蛋矮人根本不知道他们把蛮锤要塞建在了什么地方。这儿曾是影月谷兽人的埋骨地。是的，$r，就是兽人的鬼魂。$B$B近二十年来，他们一直静静地躺在蛮锤要塞地下，最近却不知何故躁动起来。$B$B离开蛮锤要塞，在影月谷中搜寻熔岩池或是熔岩流。那附近到处都是永燃灰烬，去收集一些这种灰烬，我或许能利用它制作一件有用的物品。','将15份永燃灰烬样本交给影月谷蛮锤要塞的仲裁者索鲁斯。','<索罗斯开始用灰烬样本制造某样东西。>$B$B做好了。你看，显灵镜!','嗯，有一个灵跟在你后面……我可以感觉到。') ON DUPLICATE KEY UPDATE Title_loc4='要塞中的幽灵',Details_loc4='这些笨蛋矮人根本不知道他们把蛮锤要塞建在了什么地方。这儿曾是影月谷兽人的埋骨地。是的，$r，就是兽人的鬼魂。$B$B近二十年来，他们一直静静地躺在蛮锤要塞地下，最近却不知何故躁动起来。$B$B离开蛮锤要塞，在影月谷中搜寻熔岩池或是熔岩流。那附近到处都是永燃灰烬，去收集一些这种灰烬，我或许能利用它制作一件有用的物品。',Objectives_loc4='将15份永燃灰烬样本交给影月谷蛮锤要塞的仲裁者索鲁斯。',OfferRewardText_loc4='<索罗斯开始用灰烬样本制造某样东西。>$B$B做好了。你看，显灵镜!',RequestItemsText_loc4='嗯，有一个灵跟在你后面……我可以感觉到。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10643,'影月先驱者','要知道，索鲁斯是很有幽默感的。$B$B不过，闲聊到此为止吧。戴上幽灵眼镜，你就能看见徘徊在蛮锤要塞的兽人鬼魂了。别怕，其实我们才算是真正的入侵者。唉，可惜我们不得不痛下杀手，他们本应在平静中永远沉睡的。$B$B杀死滋扰蛮锤要塞的影月先驱者，然后向我复命。','影月谷蛮锤要塞的仲裁者索鲁斯要你去杀死12个影月先驱者。','你说你听见那些鬼魂跟你低声耳语?而他们提到了泰朗.血魔?$B$B<索罗斯颤抖着。>$B$B是的……我知道泰朗.血魔。更确切的说，我只知道他的过去。长久以来人们都认为他已经死了。这些鬼魂们是怎么说他的呢?','假如你弄丢了你的护目镜，跟我说我就会帮你重造一副。') ON DUPLICATE KEY UPDATE Title_loc4='影月先驱者',Details_loc4='要知道，索鲁斯是很有幽默感的。$B$B不过，闲聊到此为止吧。戴上幽灵眼镜，你就能看见徘徊在蛮锤要塞的兽人鬼魂了。别怕，其实我们才算是真正的入侵者。唉，可惜我们不得不痛下杀手，他们本应在平静中永远沉睡的。$B$B杀死滋扰蛮锤要塞的影月先驱者，然后向我复命。',Objectives_loc4='影月谷蛮锤要塞的仲裁者索鲁斯要你去杀死12个影月先驱者。',OfferRewardText_loc4='你说你听见那些鬼魂跟你低声耳语?而他们提到了泰朗.血魔?$B$B<索罗斯颤抖着。>$B$B是的……我知道泰朗.血魔。更确切的说，我只知道他的过去。长久以来人们都认为他已经死了。这些鬼魂们是怎么说他的呢?',RequestItemsText_loc4='假如你弄丢了你的护目镜，跟我说我就会帮你重造一副。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10644,'塔隆·血魔的传说','世间流传着许多关于塔隆·血魔的故事，但是大多数都只是传说。人们并不知道塔隆·血魔返回德拉诺世界后发生的事。$B$B我们只能确定一件事，那就是他已经死了。$B$B我曾听这儿的斥候说，在遥远的东南方，跨越灵翼平原，穿过灵翼小径就能到达暗影祭坛，有位远古的兽人灵魂居住在那儿。戴上幽灵眼镜搜寻这位兽人。他应该知道更多关于塔隆·血魔的事。','影月谷蛮锤要塞的仲裁者索鲁斯要你找到上古影月之魂。$B$B如果你弄丢了幽灵眼镜，仲裁者索鲁斯可以再帮你做一副。','血魔?你为什么这么问，我已经很多年没有听到这个名字了!$B$B在第二次大战之后，血魔回到了这里，旁边跟着他的死亡骑士们。无法适应他的新形态所带来极坏的天性又失去他最尊敬的领导者古尔丹的支持，血魔自杀了。$B$B假如他现在以灵魂的形态游走在这片大地的话，对我来说倒是个新消息。但是，也许有了你的协助我可以研究推敲相关的消息。','你看的见我吗?真是太神奇了!') ON DUPLICATE KEY UPDATE Title_loc4='塔隆·血魔的传说',Details_loc4='世间流传着许多关于塔隆·血魔的故事，但是大多数都只是传说。人们并不知道塔隆·血魔返回德拉诺世界后发生的事。$B$B我们只能确定一件事，那就是他已经死了。$B$B我曾听这儿的斥候说，在遥远的东南方，跨越灵翼平原，穿过灵翼小径就能到达暗影祭坛，有位远古的兽人灵魂居住在那儿。戴上幽灵眼镜搜寻这位兽人。他应该知道更多关于塔隆·血魔的事。',Objectives_loc4='影月谷蛮锤要塞的仲裁者索鲁斯要你找到上古影月之魂。$B$B如果你弄丢了幽灵眼镜，仲裁者索鲁斯可以再帮你做一副。',OfferRewardText_loc4='血魔?你为什么这么问，我已经很多年没有听到这个名字了!$B$B在第二次大战之后，血魔回到了这里，旁边跟着他的死亡骑士们。无法适应他的新形态所带来极坏的天性又失去他最尊敬的领导者古尔丹的支持，血魔自杀了。$B$B假如他现在以灵魂的形态游走在这片大地的话，对我来说倒是个新消息。但是，也许有了你的协助我可以研究推敲相关的消息。',RequestItemsText_loc4='你看的见我吗?真是太神奇了!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10645,'我就是塔隆·血魔……','你取回了塔隆·血魔的所有对象，离谜底仅剩一步之遥：寄主。$B$B<上古影月之魂邪恶地咧嘴一笑。>$B$B你显然不相信我之前告诉你的故事。暗影祭坛便是我的牢狱。没有你的帮助，我大概会永世被禁锢在这座祭坛中。现在，我要寄宿在你体内。杀死上古看守者卡修斯，让我摆脱束缚。如果你拒绝的话，那咱俩就永远留在这儿好了。$B$B塔隆·血魔就要重获自由了！','上古影月之魂利用了你！在你集齐所有的物品后，他便露出了真面目，原来这家伙就是塔隆·血魔。想要摆脱束缚，就必须按他的吩咐杀死上古看守者卡修斯。$B$B杀死卡修斯之后，向蛮锤要塞的仲裁者索鲁斯复命。','你做了什么?愚蠢!$B$B你必须纠正你犯下的错。毕竟，这是你的责任。从这里挑一顶盔帽去吧。每一顶盔帽都灌注了你帮我取得的永燃灰烬。更重要的是，他们会赋予你看见影月谷鬼魂的能力，包含泰朗.血魔。$B$B当你找到泰朗.血魔的时候，杀死他。','你说什么?') ON DUPLICATE KEY UPDATE Title_loc4='我就是塔隆·血魔……',Details_loc4='你取回了塔隆·血魔的所有对象，离谜底仅剩一步之遥：寄主。$B$B<上古影月之魂邪恶地咧嘴一笑。>$B$B你显然不相信我之前告诉你的故事。暗影祭坛便是我的牢狱。没有你的帮助，我大概会永世被禁锢在这座祭坛中。现在，我要寄宿在你体内。杀死上古看守者卡修斯，让我摆脱束缚。如果你拒绝的话，那咱俩就永远留在这儿好了。$B$B塔隆·血魔就要重获自由了！',Objectives_loc4='上古影月之魂利用了你！在你集齐所有的物品后，他便露出了真面目，原来这家伙就是塔隆·血魔。想要摆脱束缚，就必须按他的吩咐杀死上古看守者卡修斯。$B$B杀死卡修斯之后，向蛮锤要塞的仲裁者索鲁斯复命。',OfferRewardText_loc4='你做了什么?愚蠢!$B$B你必须纠正你犯下的错。毕竟，这是你的责任。从这里挑一顶盔帽去吧。每一顶盔帽都灌注了你帮我取得的永燃灰烬。更重要的是，他们会赋予你看见影月谷鬼魂的能力，包含泰朗.血魔。$B$B当你找到泰朗.血魔的时候，杀死他。',RequestItemsText_loc4='你说什么?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,EndText_loc4) VALUES (10646,'伊利丹的学生','$N，你已向恶魔猎手证明了自己的忠诚。请原谅我的谨慎，但是如今这世道人心叵测，我这样小心也不为过。$B$B接下来，我会告诉你关于瓦雷迪斯的故事。','听奥图里斯讲述他的故事。','你已经听完了我的故事。现在只剩下一件事情可以做了。','瓦瑞迪斯是非常强大的，没错。然而，还是有一个方法可以打败他。','伊利丹的学生') ON DUPLICATE KEY UPDATE Title_loc4='伊利丹的学生',Details_loc4='$N，你已向恶魔猎手证明了自己的忠诚。请原谅我的谨慎，但是如今这世道人心叵测，我这样小心也不为过。$B$B接下来，我会告诉你关于瓦雷迪斯的故事。',Objectives_loc4='听奥图里斯讲述他的故事。',OfferRewardText_loc4='你已经听完了我的故事。现在只剩下一件事情可以做了。',RequestItemsText_loc4='瓦瑞迪斯是非常强大的，没错。然而，还是有一个方法可以打败他。',EndText_loc4='伊利丹的学生';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10647,'通缉：乌鲁洛斯，影月谷的祸患','死亡通缉令：$B$B乌鲁洛斯，影月谷的祸患。$B$B奉奥巴洛恩大王之命，必须击杀邪恶的野兽乌鲁洛斯，并从它的尸首上取下烈焰之鬃做为凭证。如果你成功完成使命，请将乌鲁洛斯的烈焰之鬃交给战争召唤者萨尔东·图斯莱。$B$B乌鲁洛斯曾在影月村以东，位于影月谷中心的古尔丹之手附近出没。','杀死乌鲁洛斯，将乌鲁洛斯的烈焰之鬃交给影月谷影月村的战争召唤者萨尔东·图斯莱。','得来不易，嗯。做的好!你要领你的奖赏了吗。别担心!','要来讨你的奖赏了吗，嗯?') ON DUPLICATE KEY UPDATE Title_loc4='通缉：乌鲁洛斯，影月谷的祸患',Details_loc4='死亡通缉令：$B$B乌鲁洛斯，影月谷的祸患。$B$B奉奥巴洛恩大王之命，必须击杀邪恶的野兽乌鲁洛斯，并从它的尸首上取下烈焰之鬃做为凭证。如果你成功完成使命，请将乌鲁洛斯的烈焰之鬃交给战争召唤者萨尔东·图斯莱。$B$B乌鲁洛斯曾在影月村以东，位于影月谷中心的古尔丹之手附近出没。',Objectives_loc4='杀死乌鲁洛斯，将乌鲁洛斯的烈焰之鬃交给影月谷影月村的战争召唤者萨尔东·图斯莱。',OfferRewardText_loc4='得来不易，嗯。做的好!你要领你的奖赏了吗。别担心!',RequestItemsText_loc4='要来讨你的奖赏了吗，嗯?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10648,'通缉：乌鲁洛斯，影月谷的祸患','死亡通缉令：$B$B乌鲁洛斯，影月谷的祸患。$B$B奉大领主尤雷加尔之命，必须击杀邪恶的野兽乌鲁洛斯，并从它的尸首上取下烈焰之鬃做为凭证。如果你成功完成使命，请将乌鲁洛斯的烈焰之鬃交给战争召唤者萨尔东·图斯莱。$B$B乌鲁洛斯曾在蛮锤要塞东北方，位于影月谷中心的古尔丹之手附近出没。','杀死乌鲁洛斯，将乌鲁洛斯的烈焰之鬃交给影月谷蛮锤要塞的战争召唤者比尔斯诺特。','来，这是你的报酬。不要一次把它花光光。','我希望你已经完成了我们的要求，$g小伙子:小姑娘;。不然就滚到一边去!') ON DUPLICATE KEY UPDATE Title_loc4='通缉：乌鲁洛斯，影月谷的祸患',Details_loc4='死亡通缉令：$B$B乌鲁洛斯，影月谷的祸患。$B$B奉大领主尤雷加尔之命，必须击杀邪恶的野兽乌鲁洛斯，并从它的尸首上取下烈焰之鬃做为凭证。如果你成功完成使命，请将乌鲁洛斯的烈焰之鬃交给战争召唤者萨尔东·图斯莱。$B$B乌鲁洛斯曾在蛮锤要塞东北方，位于影月谷中心的古尔丹之手附近出没。',Objectives_loc4='杀死乌鲁洛斯，将乌鲁洛斯的烈焰之鬃交给影月谷蛮锤要塞的战争召唤者比尔斯诺特。',OfferRewardText_loc4='来，这是你的报酬。不要一次把它花光光。',RequestItemsText_loc4='我希望你已经完成了我们的要求，$g小伙子:小姑娘;。不然就滚到一边去!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10649,'恶魔名册','我理解你想要消灭瓦雷迪斯及其追随者的心愿，但时机尚未成熟，现在的你恐怕难以与他抗衡。除非，你能找到那件赐予他力量的神器。$B$B据说，恶魔名册在奥金顿暗影迷宫的煽动者布莱卡特手中，它是你击败瓦雷迪斯的唯一希望。','进入奥金顿的暗影迷宫，从煽动者布莱卡特手中夺得恶魔名册。完成任务后返回纳格兰向奥图里斯复命。','我从好远的距离外就感觉到这本书的力量了。我想将它据为己有的想法……实在是非常的强烈。','你已经把书拿回来了吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='恶魔名册',Details_loc4='我理解你想要消灭瓦雷迪斯及其追随者的心愿，但时机尚未成熟，现在的你恐怕难以与他抗衡。除非，你能找到那件赐予他力量的神器。$B$B据说，恶魔名册在奥金顿暗影迷宫的煽动者布莱卡特手中，它是你击败瓦雷迪斯的唯一希望。',Objectives_loc4='进入奥金顿的暗影迷宫，从煽动者布莱卡特手中夺得恶魔名册。完成任务后返回纳格兰向奥图里斯复命。',OfferRewardText_loc4='我从好远的距离外就感觉到这本书的力量了。我想将它据为己有的想法……实在是非常的强烈。',RequestItemsText_loc4='你已经把书拿回来了吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10650,'返回沙塔尔祭坛','这本书……我可以用它使我的力量增强十倍……不！那样做只会令我的灵魂堕落腐化，这是必然的结局。$N，回到将你派来的人那里去吧。$B$B你们现在可以利用这本恶魔名册击败瓦雷迪斯。你们必须要在他变身为恶魔形态时焚毁恶魔名册，这是唯一能削弱他的力量的方法。','与影月谷沙塔尔祭坛的大主教欧纳拉谈一谈。$B$B为奥尔多完成任务将会降低你在占星者阵营中的声望等级。','你把这本恶心的书带来这个神圣的地方做什么?你最好有一个好的理由，$N?','你为我带来了什么呢?') ON DUPLICATE KEY UPDATE Title_loc4='返回沙塔尔祭坛',Details_loc4='这本书……我可以用它使我的力量增强十倍……不！那样做只会令我的灵魂堕落腐化，这是必然的结局。$N，回到将你派来的人那里去吧。$B$B你们现在可以利用这本恶魔名册击败瓦雷迪斯。你们必须要在他变身为恶魔形态时焚毁恶魔名册，这是唯一能削弱他的力量的方法。',Objectives_loc4='与影月谷沙塔尔祭坛的大主教欧纳拉谈一谈。$B$B为奥尔多完成任务将会降低你在占星者阵营中的声望等级。',OfferRewardText_loc4='你把这本恶心的书带来这个神圣的地方做什么?你最好有一个好的理由，$N?',RequestItemsText_loc4='你为我带来了什么呢?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10651,'阻止瓦雷迪斯','我们必须摧毁这个邪恶的神器，但在那之前，可以先利用它来削弱瓦雷迪斯的力量。$B$B要彻底毁掉卡拉波废墟的训练场，就必须杀掉瓦雷迪斯，以及他手下的恶魔猎手阿兰蒂恩、瑟拉斯和奈萨里尔。$B$B召集你的朋友，一起返回卡拉波废墟。根据奥图里斯的指示击败瓦雷迪斯。希望这办法能起作用。','大主教欧纳拉要你前往卡拉波废墟，杀死阿兰蒂恩、瑟拉斯、奈萨里尔和瓦雷迪斯。在瓦雷迪斯变身为恶魔形态时利用恶魔名册削弱他的力量。完成任务后将恶魔名册交给大主教欧纳拉。$B$B为奥尔多完成任务将会降低你在占星者阵营中的声望等级。','做的好，$N!击败瓦瑞迪斯将会对我们跟伊利丹的战争带来巨大的影响。$B$B不管是对奥多尔还是整个外域你已经证明了你的实力。','你已经完成我的要求了吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='阻止瓦雷迪斯',Details_loc4='我们必须摧毁这个邪恶的神器，但在那之前，可以先利用它来削弱瓦雷迪斯的力量。$B$B要彻底毁掉卡拉波废墟的训练场，就必须杀掉瓦雷迪斯，以及他手下的恶魔猎手阿兰蒂恩、瑟拉斯和奈萨里尔。$B$B召集你的朋友，一起返回卡拉波废墟。根据奥图里斯的指示击败瓦雷迪斯。希望这办法能起作用。',Objectives_loc4='大主教欧纳拉要你前往卡拉波废墟，杀死阿兰蒂恩、瑟拉斯、奈萨里尔和瓦雷迪斯。在瓦雷迪斯变身为恶魔形态时利用恶魔名册削弱他的力量。完成任务后将恶魔名册交给大主教欧纳拉。$B$B为奥尔多完成任务将会降低你在占星者阵营中的声望等级。',OfferRewardText_loc4='做的好，$N!击败瓦瑞迪斯将会对我们跟伊利丹的战争带来巨大的影响。$B$B不管是对奥多尔还是整个外域你已经证明了你的实力。',RequestItemsText_loc4='你已经完成我的要求了吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10652,'深入敌后','我已经安排好了，这头双足飞龙会载你飞往密探的藏身之处。准备就绪后立即出发吧。','当你准备启程前往法力熔炉：库鲁恩时，就告知维罗妮娅。抵达法力熔炉：库鲁恩后，跟卡勒迪斯·晨光谈一谈。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。','欢迎，$C。请帮我们的藏身之处保密。$B$B假如被凯尔萨斯的手下察觉我们的地点，我们恐怕无法支持多久。') ON DUPLICATE KEY UPDATE Title_loc4='深入敌后',Details_loc4='我已经安排好了，这头双足飞龙会载你飞往密探的藏身之处。准备就绪后立即出发吧。',Objectives_loc4='当你准备启程前往法力熔炉：库鲁恩时，就告知维罗妮娅。抵达法力熔炉：库鲁恩后，跟卡勒迪斯·晨光谈一谈。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。',OfferRewardText_loc4='欢迎，$C。请帮我们的藏身之处保密。$B$B假如被凯尔萨斯的手下察觉我们的地点，我们恐怕无法支持多久。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10653,'萨格拉斯印记','现在，我想你已经非常清楚为什么我们要和燃烧军团和他们的追随者对抗了。$B$B如果你想在奥尔多阵营中证明自己，那么就给我带来一些只有高阶燃烧军团成员和高阶暗影议会成员才能拥有的徽记。最高级别的燃烧军
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10654,'更多萨格拉斯印记','继续证明你的价值，$N。跟圣光的敌人战斗吧，不管他们在哪里;你的行为将获得良好的报酬。','你佩带了更多我们敌人的徽记了吗，$C?燃烧军团仍是一个威胁，我们将继续在任何我们找到他们的地方追捕他们。') ON DUPLICATE KEY UPDATE Title_loc4='更多萨格拉斯印记',OfferRewardText_loc4='继续证明你的价值，$N。跟圣光的敌人战斗吧，不管他们在哪里;你的行为将获得良好的报酬。',RequestItemsText_loc4='你佩带了更多我们敌人的徽记了吗，$C?燃烧军团仍是一个威胁，我们将继续在任何我们找到他们的地方追捕他们。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10655,'单枚萨格拉斯印记','继续证明你的价值，$N。跟圣光的敌人战斗吧，不管他们在哪里;你的行为将获得良好的报酬。','我愿意收下你身上任何多的印记。别担心;你的行为将受到适当的表扬。') ON DUPLICATE KEY UPDATE Title_loc4='单枚萨格拉斯印记',OfferRewardText_loc4='继续证明你的价值，$N。跟圣光的敌人战斗吧，不管他们在哪里;你的行为将获得良好的报酬。',RequestItemsText_loc4='我愿意收下你身上任何多的印记。别担心;你的行为将受到适当的表扬。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10656,'日怒徽记','正如你所知，占星者与凯尔萨斯的军队之间的冲突已经全面爆发。凯尔萨斯一直将我们视为他愚弄和统治所有血精灵的重大障碍与威胁，并时刻幻想着彻底消灭我们。$B$B如果你想要帮助我们与凯尔萨斯的军队作战，那么你有许多目标都可以攻击。凯尔手下最高阶的士兵都佩戴着日怒徽记以体现他们的阶级。你可以在虚空风暴和影月谷中找到并干掉他们。','沙塔斯城的魔导师菲亚琳要求你给她带回10枚日怒徽记。$B$B为占星者完成任务将会使你在奥尔多阵营中的声望等级降低。','凯尔萨斯的部队是一支训练精良的军队。你做的很好，$N。','继续说，$N。') ON DUPLICATE KEY UPDATE Title_loc4='日怒徽记',Details_loc4='正如你所知，占星者与凯尔萨斯的军队之间的冲突已经全面爆发。凯尔萨斯一直将我们视为他愚弄和统治所有血精灵的重大障碍与威胁，并时刻幻想着彻底消灭我们。$B$B如果你想要帮助我们与凯尔萨斯的军队作战，那么你有许多目标都可以攻击。凯尔手下最高阶的士兵都佩戴着日怒徽记以体现他们的阶级。你可以在虚空风暴和影月谷中找到并干掉他们。',Objectives_loc4='沙塔斯城的魔导师菲亚琳要求你给她带回10枚日怒徽记。$B$B为占星者完成任务将会使你在奥尔多阵营中的声望等级降低。',OfferRewardText_loc4='凯尔萨斯的部队是一支训练精良的军队。你做的很好，$N。',RequestItemsText_loc4='继续说，$N。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4) VALUES (10657,'电闪雷鸣','现在风动电容器使用起来的能源成本实在是太高了。但是，我突然想起来东边的鳞翼岩床附近的飞蛇可以喷吐出闪电，它的腺体应该可以为我们所用。$B$B我已经重新设定了这个电磁收集器的极性，令它可以吸收闪电。现在，你直接带着它去吸收那些飞蛇喷出的免费闪电吧。','使用极化电磁球从鳞翼飞蛇身上吸收25发闪电打击，再收集5份鳞翼闪电腺体。','太好了，成功了!老实跟你说我并不相信……根据我的计算你有百分之二十三点七二的机率在遭受第三下闪电打击的时候就会爆炸。$B$B<托斯利天真的笑着。>$B$B如此说来我们就可以知道球体是可以使用的，这样我们就可以达到ZC号的能量需求了。嗯，那也必须要有自愿出去被电的人才行。$B$B不管怎么说，你为了我们而当第一个试验品所以我们应该给予你奖赏!','使用再极化的磁力发电机球体的秘诀就是知道何时该关掉它不然你会被烤焦。$B$B当然，你需要在开关之间衡量你要对付多少只飞蛇。$B$B讲到这，你有没有帮球体充电了呢?','吸收闪电打击') ON DUPLICATE KEY UPDATE Title_loc4='电闪雷鸣',Details_loc4='现在风动电容器使用起来的能源成本实在是太高了。但是，我突然想起来东边的鳞翼岩床附近的飞蛇可以喷吐出闪电，它的腺体应该可以为我们所用。$B$B我已经重新设定了这个电磁收集器的极性，令它可以吸收闪电。现在，你直接带着它去吸收那些飞蛇喷出的免费闪电吧。',Objectives_loc4='使用极化电磁球从鳞翼飞蛇身上吸收25发闪电打击，再收集5份鳞翼闪电腺体。',OfferRewardText_loc4='太好了，成功了!老实跟你说我并不相信……根据我的计算你有百分之二十三点七二的机率在遭受第三下闪电打击的时候就会爆炸。$B$B<托斯利天真的笑着。>$B$B如此说来我们就可以知道球体是可以使用的，这样我们就可以达到ZC号的能量需求了。嗯，那也必须要有自愿出去被电的人才行。$B$B不管怎么说，你为了我们而当第一个试验品所以我们应该给予你奖赏!',RequestItemsText_loc4='使用再极化的磁力发电机球体的秘诀就是知道何时该关掉它不然你会被烤焦。$B$B当然，你需要在开关之间衡量你要对付多少只飞蛇。$B$B讲到这，你有没有帮球体充电了呢?',ObjectiveText1_loc4='吸收闪电打击';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10658,'更多日怒徽记','太棒了!这样就可以让凯尔萨斯知道不要低估我们的力量。','你最近为我们做了什么，$N?对凯尔萨斯的战争是不会自己开始的，你知道吗?') ON DUPLICATE KEY UPDATE Title_loc4='更多日怒徽记',OfferRewardText_loc4='太棒了!这样就可以让凯尔萨斯知道不要低估我们的力量。',RequestItemsText_loc4='你最近为我们做了什么，$N?对凯尔萨斯的战争是不会自己开始的，你知道吗?';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10659,'单枚日怒徽记','占星者胜利!凯尔的力量很快就会粉碎。','即使是最小的贡献也会被注意到，$N。我们的敌人很多，但是我们将战胜他们!') ON DUPLICATE KEY UPDATE Title_loc4='单枚日怒徽记',OfferRewardText_loc4='占星者胜利!凯尔的力量很快就会粉碎。',RequestItemsText_loc4='即使是最小的贡献也会被注意到，$N。我们的敌人很多，但是我们将战胜他们!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10660,'奇怪的生物……','我对生活在影月谷熔岩流附近的爬行动物很感兴趣，这些奇怪的生物竟然能承受液态的岩浆所产生的高温，真是闻所未闻！$B$B你可以在影月村外发现许多魔火双帆龙，它们聚集在岩浆喷涌之处。杀死这些魔火双帆龙，将它们身上的魔火脾脏带回来。这样，我就能开始研究它们如何抵御高温了。$B$B从村子东南方开始搜寻吧。','影月谷影月村的研究员提欧鲁斯要求你给他带回8个魔火脾脏。','<研究员提欧鲁斯拿走了脾脏并且开始检查。>$B$B这可能要花点时间。这些钱是你辛苦工作的报酬。','脾脏!给我脾脏!') ON DUPLICATE KEY UPDATE Title_loc4='奇怪的生物……',Details_loc4='我对生活在影月谷熔岩流附近的爬行动物很感兴趣，这些奇怪的生物竟然能承受液态的岩浆所产生的高温，真是闻所未闻！$B$B你可以在影月村外发现许多魔火双帆龙，它们聚集在岩浆喷涌之处。杀死这些魔火双帆龙，将它们身上的魔火脾脏带回来。这样，我就能开始研究它们如何抵御高温了。$B$B从村子东南方开始搜寻吧。',Objectives_loc4='影月谷影月村的研究员提欧鲁斯要求你给他带回8个魔火脾脏。',OfferRewardText_loc4='<研究员提欧鲁斯拿走了脾脏并且开始检查。>$B$B这可能要花点时间。这些钱是你辛苦工作的报酬。',RequestItemsText_loc4='脾脏!给我脾脏!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10661,'美味的脾脏！','你听说过食物会自己变熟并一直保持刚出锅的新鲜吗？嘿，你要敢于想象才行！$B$B不过，这可真不是什么白日梦！在蛮锤要塞外面，你可以找到许多魔火双帆龙，它们无视灼热的高温，聚集在熔岩池或是熔岩流附近。$B$B矮人们告诉我，魔火双帆龙的脾脏堪称美味中的极品，而且这东西在它们身上就已经煮熟了！给我搞些魔火脾脏来，这些金币就归你。$B$B从要塞正东方开始搜寻吧。','影月谷蛮锤要塞的诺姆斯要求你给他带回8个魔火脾脏。','<饥饿的葛诺玛斯一把抓走了那些脾脏。>$B$B这是我答应要给你的钱。假如我需要更多的脾脏的话我会告诉你的。$B$B真好吃……我想说他们真是“好吃透了”!','脾脏!给我脾脏!') ON DUPLICATE KEY UPDATE Title_loc4='美味的脾脏！',Details_loc4='你听说过食物会自己变熟并一直保持刚出锅的新鲜吗？嘿，你要敢于想象才行！$B$B不过，这可真不是什么白日梦！在蛮锤要塞外面，你可以找到许多魔火双帆龙，它们无视灼热的高温，聚集在熔岩池或是熔岩流附近。$B$B矮人们告诉我，魔火双帆龙的脾脏堪称美味中的极品，而且这东西在它们身上就已经煮熟了！给我搞些魔火脾脏来，这些金币就归你。$B$B从要塞正东方开始搜寻吧。',Objectives_loc4='影月谷蛮锤要塞的诺姆斯要求你给他带回8个魔火脾脏。',OfferRewardText_loc4='<饥饿的葛诺玛斯一把抓走了那些脾脏。>$B$B这是我答应要给你的钱。假如我需要更多的脾脏的话我会告诉你的。$B$B真好吃……我想说他们真是“好吃透了”!',RequestItemsText_loc4='脾脏!给我脾脏!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10662,'隐居的铁匠','<奥丁试图将这些金属块锻造成武器，但是失败了。他遗憾地摇了摇头。>$B$B这些铁锭并非不能用于锻造武器，只是我的能力有限罢了。$B$B我知道有位技艺精湛的铁匠名叫戴维·韦恩，他是跟随着洛萨之子来到德拉诺的。现在，这位着名的铁匠已经离开了远征军，隐居在泰罗卡森林地区的火翼岗哨东北方的某个半岛上。带上铁锭去找他吧，或许他能有办法为你锻造武器。','将一箱铁锭交给泰罗卡森林内韦恩的避难所的戴维·韦恩。','欧尔汀派你带着这些东西来找我?$B$B<这个铁匠检视了这些金属块。>$B$B他是对的。大部份内含的魔力已经完成，但是我仍然可以感觉到它未完成的部份。给我一些“奇特”的材料还有一些加工的时间，我可以用这个金属锭帮你打造出一把强而有力的抗恶魔剑。','你来这里做什么，$C?我没有太多的访客。') ON DUPLICATE KEY UPDATE Title_loc4='隐居的铁匠',Details_loc4='<奥丁试图将这些金属块锻造成武器，但是失败了。他遗憾地摇了摇头。>$B$B这些铁锭并非不能用于锻造武器，只是我的能力有限罢了。$B$B我知道有位技艺精湛的铁匠名叫戴维·韦恩，他是跟随着洛萨之子来到德拉诺的。现在，这位着名的铁匠已经离开了远征军，隐居在泰罗卡森林地区的火翼岗哨东北方的某个半岛上。带上铁锭去找他吧，或许他能有办法为你锻造武器。',Objectives_loc4='将一箱铁锭交给泰罗卡森林内韦恩的避难所的戴维·韦恩。',OfferRewardText_loc4='欧尔汀派你带着这些东西来找我?$B$B<这个铁匠检视了这些金属块。>$B$B他是对的。大部份内含的魔力已经完成，但是我仍然可以感觉到它未完成的部份。给我一些“奇特”的材料还有一些加工的时间，我可以用这个金属锭帮你打造出一把强而有力的抗恶魔剑。',RequestItemsText_loc4='你来这里做什么，$C?我没有太多的访客。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10663,'隐居的铁匠','<你面前的这位兽人摇了摇头，他明显是失败了。>$B$B这些铁锭并非不能用于锻造武器，只是我的能力有限而已。$B$B虽然这么说挺伤自尊的，可你唯一的希望是一位名叫戴维·韦恩的人类铁匠。他曾是联盟远征军的一员，不过那已经是猴年马月的事了。这位铁匠现在早已离开洛萨之子，隐居在泰罗卡森林地区的火翼岗哨东北方的某个半岛上。带上这些铁锭去找他吧，或许他能有办法为你锻造武器。','将一箱铁锭交给泰罗卡森林内韦恩的避难所的戴维·韦恩。','欧尔汀派你带着这些东西来找我?$B$B<这个铁匠检视了这些金属块。>$B$B他是对的。大部份内含的魔力已经完成，但是我仍然可以感觉到它未完成的部份。给我一些“奇特”的材料还有一些加工的时间，我可以用这个金属锭帮你打造出一把强而有力的抗恶魔剑。','你来这里做什么，$C?我没有太多的访客。') ON DUPLICATE KEY UPDATE Title_loc4='隐居的铁匠',Details_loc4='<你面前的这位兽人摇了摇头，他明显是失败了。>$B$B这些铁锭并非不能用于锻造武器，只是我的能力有限而已。$B$B虽然这么说挺伤自尊的，可你唯一的希望是一位名叫戴维·韦恩的人类铁匠。他曾是联盟远征军的一员，不过那已经是猴年马月的事了。这位铁匠现在早已离开洛萨之子，隐居在泰罗卡森林地区的火翼岗哨东北方的某个半岛上。带上这些铁锭去找他吧，或许他能有办法为你锻造武器。',Objectives_loc4='将一箱铁锭交给泰罗卡森林内韦恩的避难所的戴维·韦恩。',OfferRewardText_loc4='欧尔汀派你带着这些东西来找我?$B$B<这个铁匠检视了这些金属块。>$B$B他是对的。大部份内含的魔力已经完成，但是我仍然可以感觉到它未完成的部份。给我一些“奇特”的材料还有一些加工的时间，我可以用这个金属锭帮你打造出一把强而有力的抗恶魔剑。',RequestItemsText_loc4='你来这里做什么，$C?我没有太多的访客。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10664,'其它的材料','你带来的铁锭是铸造剑刃的主要原料，但是我还需要别的材料来制作武器的其它部分。$B$B让我看看，我还需要一个精金框架、一些重结缔皮和一个恶魔防护结界图腾。熟练的工匠能制作出前两样东西，第三样就需要前往沙塔斯城的贫民窟向施法材料商芬提购买了。他跟其它商人一起在那块区域做生意。','将一个精金框架、4张重结缔皮和一个恶魔防护结界图腾交给韦恩的避难所的戴维·韦恩。','<那位铁匠收下了材料，对你表示认同的点了点头。>$B$B这些就够了。剩下来我需要的材料可不容易弄到手。','你已经收集完材料了吗?') ON DUPLICATE KEY UPDATE Title_loc4='其它的材料',Details_loc4='你带来的铁锭是铸造剑刃的主要原料，但是我还需要别的材料来制作武器的其它部分。$B$B让我看看，我还需要一个精金框架、一些重结缔皮和一个恶魔防护结界图腾。熟练的工匠能制作出前两样东西，第三样就需要前往沙塔斯城的贫民窟向施法材料商芬提购买了。他跟其它商人一起在那块区域做生意。',Objectives_loc4='将一个精金框架、4张重结缔皮和一个恶魔防护结界图腾交给韦恩的避难所的戴维·韦恩。',OfferRewardText_loc4='<那位铁匠收下了材料，对你表示认同的点了点头。>$B$B这些就够了。剩下来我需要的材料可不容易弄到手。',RequestItemsText_loc4='你已经收集完材料了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10665,'能源舰的热源','要熔炼你带来的铁锭需要极高的温度，普通的熔炉无法提供这样的温度。$B$B我需要一种特殊的热源，外域中能制造出如此高温的东西屈指可数。$B$B风暴要塞的能源舰里就能生产这种蕴涵着不可思议的能量的魔法晶格。这些超载的魔法晶格就分布在机械领主卡帕西图斯周围，去取一块吧。','将超载的魔法晶格交给韦恩的避难所的戴维·韦恩。','它的性能比我想象的还要好!有了这么大的能量，我可以做出一打的剑了!','你可以从能源舰区走私一个法力容器给我吗?') ON DUPLICATE KEY UPDATE Title_loc4='能源舰的热源',Details_loc4='要熔炼你带来的铁锭需要极高的温度，普通的熔炉无法提供这样的温度。$B$B我需要一种特殊的热源，外域中能制造出如此高温的东西屈指可数。$B$B风暴要塞的能源舰里就能生产这种蕴涵着不可思议的能量的魔法晶格。这些超载的魔法晶格就分布在机械领主卡帕西图斯周围，去取一块吧。',Objectives_loc4='将超载的魔法晶格交给韦恩的避难所的戴维·韦恩。',OfferRewardText_loc4='它的性能比我想象的还要好!有了这么大的能量，我可以做出一打的剑了!',RequestItemsText_loc4='你可以从能源舰区走私一个法力容器给我吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10666,'魔语辞典','只有用恶魔语吟唱法术才能重新为剑刃附魔。$B$B虽然我做学徒的时候完全没有学过什么恶魔语，可眼下没别的路可走了。暗影议会的某个术士手中有一本魔语辞典，其中记载了附魔所需的大部分恶魔语词汇。$B$B沃匹尔大师是此书的主人，这个难以对付的家伙就躲在奥金顿暗影迷宫的大厅深处。去吧，无论如何也要把魔语辞典完好无损地给抢回来。','从沃匹尔大师手中夺得魔语辞典，将它交给韦恩的避难所的戴维·韦恩。','<大卫一边匆匆的翻阅着那本书，一边颤抖着。>$B$B这可不是一个可以开玩笑的东西，$N。在武器制造完成的时候，我会毁掉它。即使这些文字不公诸于世，世界上的恶魔力量也已经太多了。','你已经得到那本书了吗?') ON DUPLICATE KEY UPDATE Title_loc4='魔语辞典',Details_loc4='只有用恶魔语吟唱法术才能重新为剑刃附魔。$B$B虽然我做学徒的时候完全没有学过什么恶魔语，可眼下没别的路可走了。暗影议会的某个术士手中有一本魔语辞典，其中记载了附魔所需的大部分恶魔语词汇。$B$B沃匹尔大师是此书的主人，这个难以对付的家伙就躲在奥金顿暗影迷宫的大厅深处。去吧，无论如何也要把魔语辞典完好无损地给抢回来。',Objectives_loc4='从沃匹尔大师手中夺得魔语辞典，将它交给韦恩的避难所的戴维·韦恩。',OfferRewardText_loc4='<大卫一边匆匆的翻阅着那本书，一边颤抖着。>$B$B这可不是一个可以开玩笑的东西，$N。在武器制造完成的时候，我会毁掉它。即使这些文字不公诸于世，世界上的恶魔力量也已经太多了。',RequestItemsText_loc4='你已经得到那本书了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10667,'地下的土壤','你先前带来的精金框架未经强化是不能承受金属熔化后产生的热量的。我们可以往精金框架中填入某种稀有土壤，强化其冷却性能。$B$B这种名为水下洞穴沃土的土壤被纳迦视为珍品，极少数纳迦才有资格拥有它；而据我所知，在外域，只有盘踞在盘牙水库内蒸汽地窟的水术师瑟丝比娅使用这种土壤。','从水术师瑟丝比娅手中夺得水下洞穴的沃土，将它交给韦恩的避难所的戴维·韦恩。','这样应该就可以成功了。我本来希望可以多拿一点，但是老实说，我们在这里能获得任何东西都算是幸运了。','你已经得到幽界土壤了吗?') ON DUPLICATE KEY UPDATE Title_loc4='地下的土壤',Details_loc4='你先前带来的精金框架未经强化是不能承受金属熔化后产生的热量的。我们可以往精金框架中填入某种稀有土壤，强化其冷却性能。$B$B这种名为水下洞穴沃土的土壤被纳迦视为珍品，极少数纳迦才有资格拥有它；而据我所知，在外域，只有盘踞在盘牙水库内蒸汽地窟的水术师瑟丝比娅使用这种土壤。',Objectives_loc4='从水术师瑟丝比娅手中夺得水下洞穴的沃土，将它交给韦恩的避难所的戴维·韦恩。',OfferRewardText_loc4='这样应该就可以成功了。我本来希望可以多拿一点，但是老实说，我们在这里能获得任何东西都算是幸运了。',RequestItemsText_loc4='你已经得到幽界土壤了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10668,'对抗伊利丹','我对伊利丹仍然心存敬意。若不是他，我也不会走上恶魔猎手之路。$B$B可惜，他已经不再是过去的他了。对力量的渴求让他出卖了灵魂，而数次失败又令他扭曲了心智。他已经成为了我发誓要彻底铲除的那种存在。伊利丹和他的仆从——那些被称为伊利达雷的家伙，现在跟燃烧军团的恶魔爪牙已经没什么区别。$B$B虽然伊利丹在外域的统治权已经越来越弱，但是他的势力依然不容小觑。前往影月谷的伊利达雷岗哨，杀死伊利丹手下的军官洛瑟鲁斯，以此证明你的立场。','受难者奥图里斯要你前往影月谷的伊利达雷岗哨杀死洛瑟鲁斯。','所以你不是跟伊利丹一伙。你还差一步就可以得到我完全的信任。','伊利达瑞副官死了吗?') ON DUPLICATE KEY UPDATE Title_loc4='对抗伊利丹',Details_loc4='我对伊利丹仍然心存敬意。若不是他，我也不会走上恶魔猎手之路。$B$B可惜，他已经不再是过去的他了。对力量的渴求让他出卖了灵魂，而数次失败又令他扭曲了心智。他已经成为了我发誓要彻底铲除的那种存在。伊利丹和他的仆从——那些被称为伊利达雷的家伙，现在跟燃烧军团的恶魔爪牙已经没什么区别。$B$B虽然伊利丹在外域的统治权已经越来越弱，但是他的势力依然不容小觑。前往影月谷的伊利达雷岗哨，杀死伊利丹手下的军官洛瑟鲁斯，以此证明你的立场。',Objectives_loc4='受难者奥图里斯要你前往影月谷的伊利达雷岗哨杀死洛瑟鲁斯。',OfferRewardText_loc4='所以你不是跟伊利丹一伙。你还差一步就可以得到我完全的信任。',RequestItemsText_loc4='伊利达瑞副官死了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10669,'扫除馀孽','这世上也有少数恶魔依旧我行我素，不会起誓效忠他人。但是，真正的恶魔猎手绝不会因此生恻隐之心。$B$B恶魔克瑟勒斯曾被生活在赞加沼泽的原始沼泽生物奉为神灵，他一直拒绝加入燃烧军团。德拉诺世界险些被摧毁时，他躲到沼光湖底，陷入了沉睡。前往沼光湖附近的荒弃传送门，将这根银色魔枪插入地面。$B$B这样一来，克瑟勒斯必定会苏醒。杀掉他，以此证明你也不是恶魔一伙的。','受难者奥图里斯要你前往赞加沼泽，在沼光湖附近的荒弃传送门使用银色魔枪以唤醒克瑟勒斯。杀死这个恶魔之后，向奥图里斯复命。','做的好，$N。他还记得我把这长矛刺进他身体的那一天吗?那已经是好久以前的事了……','你回来啦。希乐斯已经被你杀死了吗?') ON DUPLICATE KEY UPDATE Title_loc4='扫除馀孽',Details_loc4='这世上也有少数恶魔依旧我行我素，不会起誓效忠他人。但是，真正的恶魔猎手绝不会因此生恻隐之心。$B$B恶魔克瑟勒斯曾被生活在赞加沼泽的原始沼泽生物奉为神灵，他一直拒绝加入燃烧军团。德拉诺世界险些被摧毁时，他躲到沼光湖底，陷入了沉睡。前往沼光湖附近的荒弃传送门，将这根银色魔枪插入地面。$B$B这样一来，克瑟勒斯必定会苏醒。杀掉他，以此证明你也不是恶魔一伙的。',Objectives_loc4='受难者奥图里斯要你前往赞加沼泽，在沼光湖附近的荒弃传送门使用银色魔枪以唤醒克瑟勒斯。杀死这个恶魔之后，向奥图里斯复命。',OfferRewardText_loc4='做的好，$N。他还记得我把这长矛刺进他身体的那一天吗?那已经是好久以前的事了……',RequestItemsText_loc4='你回来啦。希乐斯已经被你杀死了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10670,'大地之母的眼泪','剑刃的附魔还需要将一些强大的能源体熔化入其中，例如宝石。有一颗宝石可以为我们所用，要知道，这世上能容纳如此强大的魔法能量而不碎裂的宝石可不多见。$B$B这颗名为“大地之母的眼泪”的宝石是食人魔制造的，目前在战争使者沃姆罗格手中。这家伙盘踞在地狱火堡垒内的破碎大厅内，有很多强大的手下帮衬，不好对付。$N，取回大地之母的眼泪，一路小心。','从战争使者沃姆罗格手中夺得大地之母的眼泪，将它交给韦恩的避难所的戴维·韦恩。','<大卫.伟恩将这个宝石举高，透过阳光欣赏着它。>$B$B这个宝石真是毫无瑕疵呀，而且这正是我们所需要的。一个有瑕疵的宝石将会危害将来挥舞这把剑的人，造成剑中的附魔效果反扑其主人。','你能从欧姆拉格的手中抢回宝石吗?') ON DUPLICATE KEY UPDATE Title_loc4='大地之母的眼泪',Details_loc4='剑刃的附魔还需要将一些强大的能源体熔化入其中，例如宝石。有一颗宝石可以为我们所用，要知道，这世上能容纳如此强大的魔法能量而不碎裂的宝石可不多见。$B$B这颗名为“大地之母的眼泪”的宝石是食人魔制造的，目前在战争使者沃姆罗格手中。这家伙盘踞在地狱火堡垒内的破碎大厅内，有很多强大的手下帮衬，不好对付。$N，取回大地之母的眼泪，一路小心。',Objectives_loc4='从战争使者沃姆罗格手中夺得大地之母的眼泪，将它交给韦恩的避难所的戴维·韦恩。',OfferRewardText_loc4='<大卫.伟恩将这个宝石举高，透过阳光欣赏着它。>$B$B这个宝石真是毫无瑕疵呀，而且这正是我们所需要的。一个有瑕疵的宝石将会危害将来挥舞这把剑的人，造成剑中的附魔效果反扑其主人。',RequestItemsText_loc4='你能从欧姆拉格的手中抢回宝石吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10671,'不仅仅是一磅肉','$N，我这里还有点别的事情想拜托你。我们这有个大脑袋的侏儒想研究一下剃刀山北方拉扎安码头一带的魔化野兽。$B$B更具体地说，他们想要直接研究那些血肉兽的肌肉。$B$B<迪娜厌恶地皱了皱眉。>$B$B但是，首先，显然他们不想弄脏自己的双手；其次，他们只想要充入了以太能量的肉。但这似乎并不是所有的血肉兽身上都会有。$B$B我得说，我们算是人穷志就短，没选择了，只能干，你呢？','收集5份以太能量肉块。','这些就足够了。不过，它们还真臭对吗?$B$B我希望你所做的努力是值得的……我只是很高兴去收集的人是你而不是我!','你已经取得我要的一磅肉了吗?什么，你不觉得那样讲很好笑吗?') ON DUPLICATE KEY UPDATE Title_loc4='不仅仅是一磅肉',Details_loc4='$N，我这里还有点别的事情想拜托你。我们这有个大脑袋的侏儒想研究一下剃刀山北方拉扎安码头一带的魔化野兽。$B$B更具体地说，他们想要直接研究那些血肉兽的肌肉。$B$B<迪娜厌恶地皱了皱眉。>$B$B但是，首先，显然他们不想弄脏自己的双手；其次，他们只想要充入了以太能量的肉。但这似乎并不是所有的血肉兽身上都会有。$B$B我得说，我们算是人穷志就短，没选择了，只能干，你呢？',Objectives_loc4='收集5份以太能量肉块。',OfferRewardText_loc4='这些就足够了。不过，它们还真臭对吗?$B$B我希望你所做的努力是值得的……我只是很高兴去收集的人是你而不是我!',RequestItemsText_loc4='你已经取得我要的一磅肉了吗?什么，你不觉得那样讲很好笑吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4) VALUES (10672,'没理由啊……','我们必须深入研究这些生物。$B$B此地以东便是巴尔里废墟。在那里，巨大的熔岩流从地表喷涌而出，而你可以在熔岩附近找到魔蝎控制器。这些控制器是一个名叫诺姆斯的天才制造的，可以用于操纵机械蝎探测熔岩。$B$B可惜的是，这家伙早已迷失心窍，现在他只对以辛辣着称的侏儒食品感兴趣。$B$B<提欧鲁斯露出滑稽的表情。>$B$B我要你使用控制器标记熔岩流中的大型魔火双帆龙，以便展开下一步的研究工作。','影月谷影月村的研究员提欧鲁斯要求你前往巴尔里废墟附近的熔岩流，使用魔蝎控制器控制一只魔蝎，并用它标记8只大型魔火双帆龙。','听好，我们没有时间可以浪费了。我一直在注意那些上了标示的双帆龙然后发现它们全部都会向一只巨大的，不，应该说超巨大的双帆龙伟大的魔脊回报。','注意听好，我没有时间也不想解释这么做的意义何在。你只要标好这些双帆龙就够了。','标记大型魔火双帆龙') ON DUPLICATE KEY UPDATE Title_loc4='没理由啊……',Details_loc4='我们必须深入研究这些生物。$B$B此地以东便是巴尔里废墟。在那里，巨大的熔岩流从地表喷涌而出，而你可以在熔岩附近找到魔蝎控制器。这些控制器是一个名叫诺姆斯的天才制造的，可以用于操纵机械蝎探测熔岩。$B$B可惜的是，这家伙早已迷失心窍，现在他只对以辛辣着称的侏儒食品感兴趣。$B$B<提欧鲁斯露出滑稽的表情。>$B$B我要你使用控制器标记熔岩流中的大型魔火双帆龙，以便展开下一步的研究工作。',Objectives_loc4='影月谷影月村的研究员提欧鲁斯要求你前往巴尔里废墟附近的熔岩流，使用魔蝎控制器控制一只魔蝎，并用它标记8只大型魔火双帆龙。',OfferRewardText_loc4='听好，我们没有时间可以浪费了。我一直在注意那些上了标示的双帆龙然后发现它们全部都会向一只巨大的，不，应该说超巨大的双帆龙伟大的魔脊回报。',RequestItemsText_loc4='注意听好，我没有时间也不想解释这么做的意义何在。你只要标好这些双帆龙就够了。',ObjectiveText1_loc4='标记大型魔火双帆龙';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10673,'魔脊龙','诺姆斯知道那条巨型魔火双帆龙的存在，并且打算把它吃了！我可以通过魔蝎发现魔脊龙，他必定也早已知晓了。没时间多解释了。诺姆斯这个疯子，魔脊龙的皮是上好的防火服，可不能让他给吃了。$B$B返回巴尔里废墟附近的熔岩流，搜寻魔脊龙。一旦你找到这头巨兽，立即杀掉它，然后将魔脊龙之皮带回来给我。$B$B$N，别跟我争辩。我早就不屑于此了。','杀死魔脊龙，将魔脊龙之皮交给影月谷影月村的研究员提欧鲁斯。','终于!对抗熔岩高温的完全防护是我的了!当然你也会分到这项工艺技术的好处，$N。这是你应得的!','动作快一点!那个地精的胃口没有上限的!') ON DUPLICATE KEY UPDATE Title_loc4='魔脊龙',Details_loc4='诺姆斯知道那条巨型魔火双帆龙的存在，并且打算把它吃了！我可以通过魔蝎发现魔脊龙，他必定也早已知晓了。没时间多解释了。诺姆斯这个疯子，魔脊龙的皮是上好的防火服，可不能让他给吃了。$B$B返回巴尔里废墟附近的熔岩流，搜寻魔脊龙。一旦你找到这头巨兽，立即杀掉它，然后将魔脊龙之皮带回来给我。$B$B$N，别跟我争辩。我早就不屑于此了。',Objectives_loc4='杀死魔脊龙，将魔脊龙之皮交给影月谷影月村的研究员提欧鲁斯。',OfferRewardText_loc4='终于!对抗熔岩高温的完全防护是我的了!当然你也会分到这项工艺技术的好处，$N。这是你应得的!',RequestItemsText_loc4='动作快一点!那个地精的胃口没有上限的!';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4) VALUES (10674,'捕捉光球','拉扎安虚灵正在北边的拉扎安码头研究着某些非常有趣的科技。$B$B我想，要是你去拿这个陷阱把他们的那些飘在空中的粉红色小光球偷几个过来的话，他们应该是不会介意的吧？反正看起来好像也就是他们用来装饰房子的东西。$B$B这个陷阱具备特殊的功能设计，只要打开，就可以直接把那种光球给吸引过来。当然，那些光球也可能会向拉扎安虚灵报警，暴露你的位置。','用多光谱光能陷阱捕获15颗拉扎安光球。','喂!等一下!!$B$B情况看起来不太妙……','我想既然我们已经在谈话了，那表示你已经找到雷森平台的光球?能够看看它们的构造一定很有趣，让我看看那些以太族在做些什么。','捕捉拉扎安光球') ON DUPLICATE KEY UPDATE Title_loc4='捕捉光球',Details_loc4='拉扎安虚灵正在北边的拉扎安码头研究着某些非常有趣的科技。$B$B我想，要是你去拿这个陷阱把他们的那些飘在空中的粉红色小光球偷几个过来的话，他们应该是不会介意的吧？反正看起来好像也就是他们用来装饰房子的东西。$B$B这个陷阱具备特殊的功能设计，只要打开，就可以直接把那种光球给吸引过来。当然，那些光球也可能会向拉扎安虚灵报警，暴露你的位置。',Objectives_loc4='用多光谱光能陷阱捕获15颗拉扎安光球。',OfferRewardText_loc4='喂!等一下!!$B$B情况看起来不太妙……',RequestItemsText_loc4='我想既然我们已经在谈话了，那表示你已经找到雷森平台的光球?能够看看它们的构造一定很有趣，让我看看那些以太族在做些什么。',ObjectiveText1_loc4='捕捉拉扎安光球';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10675,'侏儒之怒！','<托什雷擦去了脸上的血。>$B$B这些光球竟然是由虚空能量和灵魂混合组成的，甚至其中还包含着侏儒的灵魂！$B$B他们竟敢……难道那些我们派去探索北方的人就是被他们杀死的吗？！$B$B$N，你必须阻止这一切。不过，恐怕唯一的阻止方式就只有杀死他们的头目——节点亲王拉扎安了。$B$B我想，你必须首先干掉大票的拉扎安虚灵，把他引出藏身之地。$B$B把他身上收集到所有灵魂都给我带回来。','取得灵魂之盒。','你能解决他真是太好了!谢谢你终止了他们玩弄魔法还有科技的可怕行径。$B$B谨代表世界各地的地精英雄们，我现在将赠与你我们最高的荣誉…一些能量转换器以及从以下的奖品中任选其一。$B$B我知道你会好好使用它们的!','你已经解决那个偷取灵魂的混蛋，雷森了吗?') ON DUPLICATE KEY UPDATE Title_loc4='侏儒之怒！',Details_loc4='<托什雷擦去了脸上的血。>$B$B这些光球竟然是由虚空能量和灵魂混合组成的，甚至其中还包含着侏儒的灵魂！$B$B他们竟敢……难道那些我们派去探索北方的人就是被他们杀死的吗？！$B$B$N，你必须阻止这一切。不过，恐怕唯一的阻止方式就只有杀死他们的头目——节点亲王拉扎安了。$B$B我想，你必须首先干掉大票的拉扎安虚灵，把他引出藏身之地。$B$B把他身上收集到所有灵魂都给我带回来。',Objectives_loc4='取得灵魂之盒。',OfferRewardText_loc4='你能解决他真是太好了!谢谢你终止了他们玩弄魔法还有科技的可怕行径。$B$B谨代表世界各地的地精英雄们，我现在将赠与你我们最高的荣誉…一些能量转换器以及从以下的奖品中任选其一。$B$B我知道你会好好使用它们的!',RequestItemsText_loc4='你已经解决那个偷取灵魂的混蛋，雷森了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10676,'伊利达雷的斩除者','<戴维开始搜集他手边的锻造工具。>$B$B你成功取回了铸造这柄抗魔之剑所需的材料。现在，你付出的艰辛都将得到回报。$B$B让我们开始铸剑吧。','等待戴维·韦恩为你铸剑。','<大卫擦去他额头上的汗水。>$B$B主要的工作已经完成了，但是要在其中注入魔法的力量，必须要等剑身冷却下来。','快完成了……') ON DUPLICATE KEY UPDATE Title_loc4='伊利达雷的斩除者',Details_loc4='<戴维开始搜集他手边的锻造工具。>$B$B你成功取回了铸造这柄抗魔之剑所需的材料。现在，你付出的艰辛都将得到回报。$B$B让我们开始铸剑吧。',Objectives_loc4='等待戴维·韦恩为你铸剑。',OfferRewardText_loc4='<大卫擦去他额头上的汗水。>$B$B主要的工作已经完成了，但是要在其中注入魔法的力量，必须要等剑身冷却下来。',RequestItemsText_loc4='快完成了……';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10677,'第二道菜……','我曾在古尔丹之手以东、巴尔里废墟周围的熔岩流附近见过大型魔火双帆龙。我要你从它们身上取回一个巨大的魔火胃囊。这东西不太好切下来，运气不好的话，你可能要多杀几只才能弄到合适的。加油！下一顿美餐就靠你了。','影月谷蛮锤要塞的诺姆斯要求你给他带回一个巨大的魔火胃囊。','你做的很好但是我刚刚收到了一个不可思议的消息!','今日特餐:胃囊大餐。') ON DUPLICATE KEY UPDATE Title_loc4='第二道菜……',Details_loc4='我曾在古尔丹之手以东、巴尔里废墟周围的熔岩流附近见过大型魔火双帆龙。我要你从它们身上取回一个巨大的魔火胃囊。这东西不太好切下来，运气不好的话，你可能要多杀几只才能弄到合适的。加油！下一顿美餐就靠你了。',Objectives_loc4='影月谷蛮锤要塞的诺姆斯要求你给他带回一个巨大的魔火胃囊。',OfferRewardText_loc4='你做的很好但是我刚刚收到了一个不可思议的消息!',RequestItemsText_loc4='今日特餐:胃囊大餐。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10678,'主菜！','长话短说，我曾与一位名叫提欧鲁斯的血精灵共事过一段时间。但自从我醉心美食之后，他便与我分道扬镳了。这家伙非常自以为是，现在居然还在继续用我发明的设备进行研究。他前几天指派某个蠢货利用我的魔蝎勘测了巴尔里废墟的熔岩流，结果发现了所有双帆龙的头目！$B$B我要你赶在他之前去杀掉那条名叫魔脊龙的双帆龙王，将魔脊龙之皮带回来给我。$B$B快去！','将魔脊龙之皮交给影月谷蛮锤要塞的诺姆斯。','我想要一个人独处一下，$N。感谢你的帮忙!','今日特餐:魔脊的毛皮大餐。') ON DUPLICATE KEY UPDATE Title_loc4='主菜！',Details_loc4='长话短说，我曾与一位名叫提欧鲁斯的血精灵共事过一段时间。但自从我醉心美食之后，他便与我分道扬镳了。这家伙非常自以为是，现在居然还在继续用我发明的设备进行研究。他前几天指派某个蠢货利用我的魔蝎勘测了巴尔里废墟的熔岩流，结果发现了所有双帆龙的头目！$B$B我要你赶在他之前去杀掉那条名叫魔脊龙的双帆龙王，将魔脊龙之皮带回来给我。$B$B快去！',Objectives_loc4='将魔脊龙之皮交给影月谷蛮锤要塞的诺姆斯。',OfferRewardText_loc4='我想要一个人独处一下，$N。感谢你的帮忙!',RequestItemsText_loc4='今日特餐:魔脊的毛皮大餐。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10679,'淬火','武器就快锻造成功了！$B$B你几乎能感受到钢刃中的魔法力量在慢慢凝聚，只差最后一步了。$B$B前往影月谷内古尔丹之手顶部的滚烫熔池，将铸成的伊利达雷斩除之刃放入熔岩池中淬火，然后再将淬火的伊利达雷斩除之刃带回来给我。','前往古尔丹之手顶部寻找滚烫熔池，将铸成的伊利达雷斩除之刃放入熔岩池中淬火。然后将淬火的伊利达雷斩除之刃交给韦恩的避难所的戴维·韦恩。','做的好!$B$B<这名铁匠很靠近的检查这把剑。>$B$B跟你一开始的粗糙军团武器比起来现在已经有了大幅度的增强了。这把剑不光是可以拿来砍伊利丹的恶魔们，还可以拿来对付燃烧军团的手下。','你将这把刀放进古尔丹火山的熔岩池里冷却过了吗?') ON DUPLICATE KEY UPDATE Title_loc4='淬火',Details_loc4='武器就快锻造成功了！$B$B你几乎能感受到钢刃中的魔法力量在慢慢凝聚，只差最后一步了。$B$B前往影月谷内古尔丹之手顶部的滚烫熔池，将铸成的伊利达雷斩除之刃放入熔岩池中淬火，然后再将淬火的伊利达雷斩除之刃带回来给我。',Objectives_loc4='前往古尔丹之手顶部寻找滚烫熔池，将铸成的伊利达雷斩除之刃放入熔岩池中淬火。然后将淬火的伊利达雷斩除之刃交给韦恩的避难所的戴维·韦恩。',OfferRewardText_loc4='做的好!$B$B<这名铁匠很靠近的检查这把剑。>$B$B跟你一开始的粗糙军团武器比起来现在已经有了大幅度的增强了。这把剑不光是可以拿来砍伊利丹的恶魔们，还可以拿来对付燃烧军团的手下。',RequestItemsText_loc4='你将这把刀放进古尔丹火山的熔岩池里冷却过了吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10680,'古尔丹之手','元素需要你的帮助，$r！影月谷曾遭受过一场难以言喻的灾难。元素之灵至今仍在痛苦中挣扎，现在，这些被激怒的元素之灵已经不愿再继续与大地之环沟通了。$B$B朋友，帮助影月谷恢复原貌吧。$B$B蛮锤要塞东北方便是诅咒祭坛，到那里去，与大地治愈者托洛克谈谈。','与影月谷诅咒祭坛的大地治愈者托洛克谈一谈。','你肯来帮忙真是太好了，$r。我们有很多事情要做。','啊，有人来帮忙了。') ON DUPLICATE KEY UPDATE Title_loc4='古尔丹之手',Details_loc4='元素需要你的帮助，$r！影月谷曾遭受过一场难以言喻的灾难。元素之灵至今仍在痛苦中挣扎，现在，这些被激怒的元素之灵已经不愿再继续与大地之环沟通了。$B$B朋友，帮助影月谷恢复原貌吧。$B$B蛮锤要塞东北方便是诅咒祭坛，到那里去，与大地治愈者托洛克谈谈。',Objectives_loc4='与影月谷诅咒祭坛的大地治愈者托洛克谈一谈。',OfferRewardText_loc4='你肯来帮忙真是太好了，$r。我们有很多事情要做。',RequestItemsText_loc4='啊，有人来帮忙了。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10681,'古尔丹之手','元素需要你的帮助，$r！影月谷曾遭受过一场难以言喻的灾难。元素之灵至今仍在痛苦中挣扎，现在，这些被激怒的元素之灵已经不愿再继续与大地之环沟通了。$B$B朋友，帮助影月谷恢复原貌吧。$B$B蛮锤要塞东北方便是诅咒祭坛，到那里去，与大地治愈者托洛克谈谈。','与影月谷诅咒祭坛的大地治愈者托洛克谈一谈。','你肯来帮忙真是太好了，$r。我们有很多事情要做。','啊，有人来帮忙了。') ON DUPLICATE KEY UPDATE Title_loc4='古尔丹之手',Details_loc4='元素需要你的帮助，$r！影月谷曾遭受过一场难以言喻的灾难。元素之灵至今仍在痛苦中挣扎，现在，这些被激怒的元素之灵已经不愿再继续与大地之环沟通了。$B$B朋友，帮助影月谷恢复原貌吧。$B$B蛮锤要塞东北方便是诅咒祭坛，到那里去，与大地治愈者托洛克谈谈。',Objectives_loc4='与影月谷诅咒祭坛的大地治愈者托洛克谈一谈。',OfferRewardText_loc4='你肯来帮忙真是太好了，$r。我们有很多事情要做。',RequestItemsText_loc4='啊，有人来帮忙了。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,EndText_loc4) VALUES (10682,'该谈判了……','当我们刚刚抵达卢安荒野时，拜龙教还仅仅在西边隧道另一侧的黑翼集会所周围活动。但现在，他们的势力范围越来越大，已经接近我们的周边了。$B$B我要求你立刻去找到拜龙教派往这里的监工，他应该就在卢安荒野里的几处营地之间来回巡逻。$B$B去与他谈判，转告他，只要他们不再胡乱屠杀野生动物，不再砍伐树木，我们之间就还有和平共处的空间与馀地。','去与工头努埃尔谈判。','什么?!他们马上就把你以及我们的提议否决?$B$B真是令人吃惊!我们带着善意去找他们，而他们把你赶走连试着听听协议都不肯?$B$B好吧，我们走着瞧!','一切都还好吗?','完成与工头努埃尔的谈判') ON DUPLICATE KEY UPDATE Title_loc4='该谈判了……',Details_loc4='当我们刚刚抵达卢安荒野时，拜龙教还仅仅在西边隧道另一侧的黑翼集会所周围活动。但现在，他们的势力范围越来越大，已经接近我们的周边了。$B$B我要求你立刻去找到拜龙教派往这里的监工，他应该就在卢安荒野里的几处营地之间来回巡逻。$B$B去与他谈判，转告他，只要他们不再胡乱屠杀野生动物，不再砍伐树木，我们之间就还有和平共处的空间与馀地。',Objectives_loc4='去与工头努埃尔谈判。',OfferRewardText_loc4='什么?!他们马上就把你以及我们的提议否决?$B$B真是令人吃惊!我们带着善意去找他们，而他们把你赶走连试着听听协议都不肯?$B$B好吧，我们走着瞧!',RequestItemsText_loc4='一切都还好吗?',EndText_loc4='完成与工头努埃尔的谈判';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10683,'巴尔里石板','最近，一支名叫灰舌的破碎者氏族奉伊利丹之命，在巴尔里废墟展开了一系列挖掘工作。他们的目标毫无疑问就是当初那些被古尔丹所引发的火山爆发埋入地下的神圣古器。我们必须利用这个机会夺回巴尔里石板。据说，那上面记载着许多卡拉波神殿——也就是黑暗神殿的秘密。','群星圣殿的奥术师塞里斯要你收集12块巴尔里石板。它们散落在巴尔里废墟中，那里的灰舌工人身上也携带着这种石板。$B$B为占星者阵营完成任务将降低你在奥尔多阵营中的声望等级。','巴瑞碑文!没错，这也许会提供我们非常有用的资料。','你找到那些碑文了没，$N?') ON DUPLICATE KEY UPDATE Title_loc4='巴尔里石板',Details_loc4='最近，一支名叫灰舌的破碎者氏族奉伊利丹之命，在巴尔里废墟展开了一系列挖掘工作。他们的目标毫无疑问就是当初那些被古尔丹所引发的火山爆发埋入地下的神圣古器。我们必须利用这个机会夺回巴尔里石板。据说，那上面记载着许多卡拉波神殿——也就是黑暗神殿的秘密。',Objectives_loc4='群星圣殿的奥术师塞里斯要你收集12块巴尔里石板。它们散落在巴尔里废墟中，那里的灰舌工人身上也携带着这种石板。$B$B为占星者阵营完成任务将降低你在奥尔多阵营中的声望等级。',OfferRewardText_loc4='巴瑞碑文!没错，这也许会提供我们非常有用的资料。',RequestItemsText_loc4='你找到那些碑文了没，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10684,'长者奥洛努','根据巴尔里石板的记载，巴尔里废墟中埋藏着一件名为卡拉波勋章的神器。在过去，德莱尼人当中只有最高阶的祭司团成员才有资格得到这件神器，从而也获得了自由进出卡拉波神殿的权利。$B$B我们现在必须查明灰舌破碎者们是否已从废墟中挖掘出了这枚勋章。这件神器一定可以对我们抵抗伊利丹有所帮助。$B$B现在，驻守在巴尔里废墟的灰舌军官——长者奥洛努每天都会接到他的上司阿卡玛的书面指令。去把阿卡玛的命令带来给我。','群星圣殿的奥术师塞里斯要求你从巴尔里废墟的长者奥洛努手中夺得阿卡玛的命令。$B$B为占星者阵营完成任务将降低你在奥尔多阵营中的声望等级。','阿卡玛的亲笔书信…… 看看我们能从中得到什么资讯吧。','有任何消息了没，$N?我们快没有时间了。') ON DUPLICATE KEY UPDATE Title_loc4='长者奥洛努',Details_loc4='根据巴尔里石板的记载，巴尔里废墟中埋藏着一件名为卡拉波勋章的神器。在过去，德莱尼人当中只有最高阶的祭司团成员才有资格得到这件神器，从而也获得了自由进出卡拉波神殿的权利。$B$B我们现在必须查明灰舌破碎者们是否已从废墟中挖掘出了这枚勋章。这件神器一定可以对我们抵抗伊利丹有所帮助。$B$B现在，驻守在巴尔里废墟的灰舌军官——长者奥洛努每天都会接到他的上司阿卡玛的书面指令。去把阿卡玛的命令带来给我。',Objectives_loc4='群星圣殿的奥术师塞里斯要求你从巴尔里废墟的长者奥洛努手中夺得阿卡玛的命令。$B$B为占星者阵营完成任务将降低你在奥尔多阵营中的声望等级。',OfferRewardText_loc4='阿卡玛的亲笔书信…… 看看我们能从中得到什么资讯吧。',RequestItemsText_loc4='有任何消息了没，$N?我们快没有时间了。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10685,'灰舌腐蚀者','阿卡玛在指令中提到，被挖掘出来的4块勋章碎片分别由四位灰舌腐蚀者负责保管。这些灰舌腐蚀者本都是氏族中的萨满祭司，如今却转而与他们曾经崇拜与侍奉的元素为敌，唉……$B$B气之腐蚀者哈鲁姆目前在灵翼小径；地之腐蚀者埃肯尼和火之腐蚀者乌拉鲁，曾有人看见他们在古尔丹之手附近的魔能熔池旁出没；水之腐蚀者拉坎恩据说在库斯卡岗哨附近。$B$B杀死他们，取回全部的勋章碎片。','从哈鲁姆、埃肯尼、拉坎恩和乌拉鲁手中夺得他们的勋章碎片，并把这些碎片交给影月谷群星圣殿的奥术师塞里斯。$B$B为占星者阵营完成任务将降低你在奥尔多阵营中的声望等级。','没错!这就是四个勋章碎片。现在，来将它们结合在一起……','你已经取回四个勋章碎片了吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='灰舌腐蚀者',Details_loc4='阿卡玛在指令中提到，被挖掘出来的4块勋章碎片分别由四位灰舌腐蚀者负责保管。这些灰舌腐蚀者本都是氏族中的萨满祭司，如今却转而与他们曾经崇拜与侍奉的元素为敌，唉……$B$B气之腐蚀者哈鲁姆目前在灵翼小径；地之腐蚀者埃肯尼和火之腐蚀者乌拉鲁，曾有人看见他们在古尔丹之手附近的魔能熔池旁出没；水之腐蚀者拉坎恩据说在库斯卡岗哨附近。$B$B杀死他们，取回全部的勋章碎片。',Objectives_loc4='从哈鲁姆、埃肯尼、拉坎恩和乌拉鲁手中夺得他们的勋章碎片，并把这些碎片交给影月谷群星圣殿的奥术师塞里斯。$B$B为占星者阵营完成任务将降低你在奥尔多阵营中的声望等级。',OfferRewardText_loc4='没错!这就是四个勋章碎片。现在，来将它们结合在一起……',RequestItemsText_loc4='你已经取回四个勋章碎片了吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10686,'守望者的牢笼','你取回的碎片只能拼凑出半块卡拉波勋章。另一半必定在灰舌破碎者的首领阿卡玛手中。$B$B派你去执行这项任务令我心中隐隐有些不安，因为阿卡玛是个邪恶而狡诈的家伙。$B$B据说，他甚至还和氏族中那些最卑劣残忍的成员——灰舌死誓者一起在守望者牢笼中设立了刑讯室。$B$B现在，我要你立刻前往刑讯室寻找阿卡玛的下落。如果有必要的话，你可以将他的副官萨诺鲁抓来审问。','奥术师塞里斯要求你进入巴尔里废墟以南的守望者牢笼，从萨诺鲁口中审问出阿卡玛的下落。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。','我们早就在等待你，$N。阿卡玛说过你一定会来。') ON DUPLICATE KEY UPDATE Title_loc4='守望者的牢笼',Details_loc4='你取回的碎片只能拼凑出半块卡拉波勋章。另一半必定在灰舌破碎者的首领阿卡玛手中。$B$B派你去执行这项任务令我心中隐隐有些不安，因为阿卡玛是个邪恶而狡诈的家伙。$B$B据说，他甚至还和氏族中那些最卑劣残忍的成员——灰舌死誓者一起在守望者牢笼中设立了刑讯室。$B$B现在，我要你立刻前往刑讯室寻找阿卡玛的下落。如果有必要的话，你可以将他的副官萨诺鲁抓来审问。',Objectives_loc4='奥术师塞里斯要求你进入巴尔里废墟以南的守望者牢笼，从萨诺鲁口中审问出阿卡玛的下落。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。',OfferRewardText_loc4='我们早就在等待你，$N。阿卡玛说过你一定会来。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10687,'卡拉波训练场','据斥候回报，一支由日怒血精灵新兵组成的大部队目前正朝卡拉波废墟前进。原本，如此大规模的军事行动势必会构成强烈的军事威胁，但是我们相信此事另有内情。$B$B他们的服饰和战斗风格很像伊利丹麾下的部队。我可不想自乱阵脚。前往卡拉波废墟取回他们的武器，这样我们就能搞清楚状况了。','群星圣殿的拉瑞萨·射日者要你前往群星圣殿东北方的卡拉波废墟，从恶魔猎手学员和恶魔猎手新兵身上夺取8柄日怒阔剑。$B$B为占星者完成任务将会降低你在奥尔多阵营中的声望等级。','让我们仔细地看一下这些武器，$N。嗯……这令人感到相当的不安。','你已经完成我要求的工作了吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='卡拉波训练场',Details_loc4='据斥候回报，一支由日怒血精灵新兵组成的大部队目前正朝卡拉波废墟前进。原本，如此大规模的军事行动势必会构成强烈的军事威胁，但是我们相信此事另有内情。$B$B他们的服饰和战斗风格很像伊利丹麾下的部队。我可不想自乱阵脚。前往卡拉波废墟取回他们的武器，这样我们就能搞清楚状况了。',Objectives_loc4='群星圣殿的拉瑞萨·射日者要你前往群星圣殿东北方的卡拉波废墟，从恶魔猎手学员和恶魔猎手新兵身上夺取8柄日怒阔剑。$B$B为占星者完成任务将会降低你在奥尔多阵营中的声望等级。',OfferRewardText_loc4='让我们仔细地看一下这些武器，$N。嗯……这令人感到相当的不安。',RequestItemsText_loc4='你已经完成我要求的工作了吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4,ObjectiveText1_loc4) VALUES (10688,'必要的混乱','这些武器足以证明我们的担忧不是没有道理。伊利丹确实在卡拉波废墟训练恶魔猎手，我们必须阻止他进一步扩大势力。$B$B$N，别被恶魔猎手这名字给迷惑了，总有一天这帮家伙会像对付恶魔那样来对付我们的。$B$B目前，还有一批日怒术士在卡拉波废墟召唤并奴役恶魔，用于新兵训练。他们曾召唤出一个名叫阿萨洛斯的深渊领主，不过阿萨洛斯过于强大，并不适合新兵的训练课程，术士们只得不断地放逐他。设法令阿萨洛斯摆脱放逐，这场混乱必定能为我们赢得了解敌情的时间。','拉瑞萨·射日者要你返回卡拉波废墟，设法令阿萨洛斯摆脱放逐状态。$B$B为占星者完成任务将会降低你在奥尔多阵营中的声望等级。','那应该可以给我们一些时间……希望它足够让我们获得更多的情报。','你已经完成我要求的工作了吗，$N?','释放阿萨洛斯') ON DUPLICATE KEY UPDATE Title_loc4='必要的混乱',Details_loc4='这些武器足以证明我们的担忧不是没有道理。伊利丹确实在卡拉波废墟训练恶魔猎手，我们必须阻止他进一步扩大势力。$B$B$N，别被恶魔猎手这名字给迷惑了，总有一天这帮家伙会像对付恶魔那样来对付我们的。$B$B目前，还有一批日怒术士在卡拉波废墟召唤并奴役恶魔，用于新兵训练。他们曾召唤出一个名叫阿萨洛斯的深渊领主，不过阿萨洛斯过于强大，并不适合新兵的训练课程，术士们只得不断地放逐他。设法令阿萨洛斯摆脱放逐，这场混乱必定能为我们赢得了解敌情的时间。',Objectives_loc4='拉瑞萨·射日者要你返回卡拉波废墟，设法令阿萨洛斯摆脱放逐状态。$B$B为占星者完成任务将会降低你在奥尔多阵营中的声望等级。',OfferRewardText_loc4='那应该可以给我们一些时间……希望它足够让我们获得更多的情报。',RequestItemsText_loc4='你已经完成我要求的工作了吗，$N?',ObjectiveText1_loc4='释放阿萨洛斯';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4) VALUES (10689,'奥图里斯','如今，选择恶魔猎手之路的人已经非常罕见了，毕竟，他们受到了自己族人太多的猜忌，而且要找到不愿意追随伊利丹的恶魔猎手就更是难上加难。$B$B不过，据说纳格兰就有这样一位名叫奥图里斯的英雄人物。他对所有的恶魔都恨之入骨，如果你能说服他，让他相信我们和他有着共同的目的，他必定会伸出援手。$B$B前往纳格兰西部寻找奥图里斯。他或许会告诉我们关于恶魔猎手训练场的事。','前往纳格兰西部寻找受难者奥图里斯。$B$B为占星者完成任务将会降低你在奥尔多阵营中的声望等级。','你已经走很长的路了，陌生人。我惊讶到底是谁听说过我而派你过来。') ON DUPLICATE KEY UPDATE Title_loc4='奥图里斯',Details_loc4='如今，选择恶魔猎手之路的人已经非常罕见了，毕竟，他们受到了自己族人太多的猜忌，而且要找到不愿意追随伊利丹的恶魔猎手就更是难上加难。$B$B不过，据说纳格兰就有这样一位名叫奥图里斯的英雄人物。他对所有的恶魔都恨之入骨，如果你能说服他，让他相信我们和他有着共同的目的，他必定会伸出援手。$B$B前往纳格兰西部寻找奥图里斯。他或许会告诉我们关于恶魔猎手训练场的事。',Objectives_loc4='前往纳格兰西部寻找受难者奥图里斯。$B$B为占星者完成任务将会降低你在奥尔多阵营中的声望等级。',OfferRewardText_loc4='你已经走很长的路了，陌生人。我惊讶到底是谁听说过我而派你过来。';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10690,'兽穴之母','悬赏！$B$B雷玛，兽穴之母，雷神要塞正南方锯齿山地区的主要守卫者。$B$B向东出城，过桥后横穿血槌峡谷便可找到她。她就隐蔽在山岭南部边缘一处隧道的尽头。$B$B将她的死亡消息告知希尔瓦纳的指挥官萨卡斯·天影以换取报酬。','杀死雷玛。','难以相信。你独自一人杀死瑞玛了吗?$B$B以你的外表，我认为你能。你知道，我们正在寻找年轻、强壮的$C，像你那样，在这周遭帮忙，特别是我们与巨魔们持续有的那些问题。确定在那可能性上你会与我做后续联系。$B$B好的，你已经明确赢得我发布在那张通缉布告上的赏金。$B$B请，选择你想要的。','今天我可以帮你什么呢?') ON DUPLICATE KEY UPDATE Title_loc4='兽穴之母',Details_loc4='悬赏！$B$B雷玛，兽穴之母，雷神要塞正南方锯齿山地区的主要守卫者。$B$B向东出城，过桥后横穿血槌峡谷便可找到她。她就隐蔽在山岭南部边缘一处隧道的尽头。$B$B将她的死亡消息告知希尔瓦纳的指挥官萨卡斯·天影以换取报酬。',Objectives_loc4='杀死雷玛。',OfferRewardText_loc4='难以相信。你独自一人杀死瑞玛了吗?$B$B以你的外表，我认为你能。你知道，我们正在寻找年轻、强壮的$C，像你那样，在这周遭帮忙，特别是我们与巨魔们持续有的那些问题。确定在那可能性上你会与我做后续联系。$B$B好的，你已经明确赢得我发布在那张通缉布告上的赏金。$B$B请，选择你想要的。',RequestItemsText_loc4='今天我可以帮你什么呢?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10691,'返回群星圣殿','这本书……我可以用它使我的力量增强十倍……不！那样做只会令我的灵魂堕落腐化，这是必然的结局。$N，回到将你派来的人那里去吧。$B$B你们现在可以利用这本恶魔名册击败瓦雷迪斯。你们必须要在他变身为恶魔形态时焚毁恶魔名册，这是唯一能削弱他的力量的方法。','与影月谷群星圣殿的拉瑞萨·射日者谈一谈。$B$B为占星者完成任务将会降低你在奥尔多阵营中的声望等级。','许多人会愿意为你带来的这本书付出很高的价格。我们得消毁这本书真是可惜。','你有什么要给我看的吗?') ON DUPLICATE KEY UPDATE Title_loc4='返回群星圣殿',Details_loc4='这本书……我可以用它使我的力量增强十倍……不！那样做只会令我的灵魂堕落腐化，这是必然的结局。$N，回到将你派来的人那里去吧。$B$B你们现在可以利用这本恶魔名册击败瓦雷迪斯。你们必须要在他变身为恶魔形态时焚毁恶魔名册，这是唯一能削弱他的力量的方法。',Objectives_loc4='与影月谷群星圣殿的拉瑞萨·射日者谈一谈。$B$B为占星者完成任务将会降低你在奥尔多阵营中的声望等级。',OfferRewardText_loc4='许多人会愿意为你带来的这本书付出很高的价格。我们得消毁这本书真是可惜。',RequestItemsText_loc4='你有什么要给我看的吗?';
INSERT INTO locales_quest(entry,Title_loc4,Details_loc4,Objectives_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10692,'阻止瓦雷迪斯','我们当然必须摧毁这个邪恶的神器，但在那之前，可以先利用它来削弱瓦雷迪斯的力量。$B$B要彻底毁掉卡拉波废墟的训练场，就必须杀掉瓦雷迪斯，以及他手下的恶魔猎手阿兰蒂恩、瑟拉斯和奈萨里尔。$B$B召集你的朋友，一起返回卡拉波废墟。根据奥图里斯的指示击败瓦雷迪斯。希望这办法能起作用，否则……我只能说跟你合作愉快了。','拉瑞萨·射日者要你前往卡拉波废墟，杀死阿兰蒂恩、瑟拉斯、奈萨里尔和瓦雷迪斯。在瓦雷迪斯变身为恶魔形态时利用恶魔名册削弱他的力量。完成任务后将恶魔名册交给拉瑞萨·射日者。$B$B为占星者完成任务将会降低你在奥尔多阵营中的声望等级。','做得好，$N。在杀死瓦瑞迪斯时，你已结束了伊利丹最危险的计划之一。$B$B在这之后你的名字将确定会四处传播。$B$B请允许我取走恶魔之名宝典的遗稿。我保证它将被正确地……处理。','你已经完成我要求的工作了吗，$N?') ON DUPLICATE KEY UPDATE Title_loc4='阻止瓦雷迪斯',Details_loc4='我们当然必须摧毁这个邪恶的神器，但在那之前，可以先利用它来削弱瓦雷迪斯的力量。$B$B要彻底毁掉卡拉波废墟的训练场，就必须杀掉瓦雷迪斯，以及他手下的恶魔猎手阿兰蒂恩、瑟拉斯和奈萨里尔。$B$B召集你的朋友，一起返回卡拉波废墟。根据奥图里斯的指示击败瓦雷迪斯。希望这办法能起作用，否则……我只能说跟你合作愉快了。',Objectives_loc4='拉瑞萨·射日者要你前往卡拉波废墟，杀死阿兰蒂恩、瑟拉斯、奈萨里尔和瓦雷迪斯。在瓦雷迪斯变身为恶魔形态时利用恶魔名册削弱他的力量。完成任务后将恶魔名册交给拉瑞萨·射日者。$B$B为占星者完成任务将会降低你在奥尔多阵营中的声望等级。',OfferRewardText_loc4='做得好，$N。在杀死瓦瑞迪斯时，你已结束了伊利丹最危险的计划之一。$B$B在这之后你的名字将确定会四处传播。$B$B请允许我取走恶魔之名宝典的遗稿。我保证它将被正确地……处理。',RequestItemsText_loc4='你已经完成我要求的工作了吗，$N?';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10693,'一枚荣誉徽章','很好，你的贡献已经被记录在册，而你也得到了不错的评价。继续好好干，$C。$B$B如果你有更多徽章的话，我随时可以帮你进一步提高声望。','如果你只有一枚荣誉徽章，我可以用它来帮助你提高在暴风城的知名度。$B$B请注意，你最好一次交给我十枚荣誉徽章，这样你的知名度会获得更大的提高。我们提供针对一枚荣誉徽章的交换服务是为了方便那些没有足够荣誉徽章的冒险者。$B$B总之，如果你想要用一枚荣誉徽章来换取声望的话，我随时在这里等着你。') ON DUPLICATE KEY UPDATE Title_loc4='一枚荣誉徽章',OfferRewardText_loc4='很好，你的贡献已经被记录在册，而你也得到了不错的评价。继续好好干，$C。$B$B如果你有更多徽章的话，我随时可以帮你进一步提高声望。',RequestItemsText_loc4='如果你只有一枚荣誉徽章，我可以用它来帮助你提高在暴风城的知名度。$B$B请注意，你最好一次交给我十枚荣誉徽章，这样你的知名度会获得更大的提高。我们提供针对一枚荣誉徽章的交换服务是为了方便那些没有足够荣誉徽章的冒险者。$B$B总之，如果你想要用一枚荣誉徽章来换取声望的话，我随时在这里等着你。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4,RequestItemsText_loc4) VALUES (10694,'十枚荣誉徽章','非常好!你肯定做出了巨大的牺牲才能获得这些荣誉徽章，为此你将得到充分的肯定。正是许许多多像你一样的冒险者让一切都变得不同的。$B$B如果你还有更多荣誉徽章的话，尽管来找我，我很高兴能为你做点什么。','完成了自己的任务并得到荣誉徽章的冒险者可以把他们的徽章交给我，你每次把10枚徽章交给我，我都可以用它们来显着提升你在暴风城的声望。当然，我也接受单枚徽章的交换申请，但是这对于声望的提升效果就会逊色许多。虽然我们不会忘记每一位冒险者的努力，但是贡献越大，回报就越大。$B$B如果你有足够的荣誉徽章要给我的话，随时来找我。') ON DUPLICATE KEY UPDATE Title_loc4='十枚荣誉徽章',OfferRewardText_loc4='非常好!你肯定做出了巨大的牺牲才能获得这些荣誉徽章，为此你将得到充分的肯定。正是许许多多像你一样的冒险者让一切都变得不同的。$B$B如果你还有更多荣誉徽章的话，尽管来找我，我很高兴能为你做点什么。',RequestItemsText_loc4='完成了自己的任务并得到荣誉徽章的冒险者可以把他们的徽章交给我，你每次把10枚徽章交给我，我都可以用它们来显着提升你在暴风城的声望。当然，我也接受单枚徽章的交换申请，但是这对于声望的提升效果就会逊色许多。虽然我们不会忘记每一位冒险者的努力，但是贡献越大，回报就越大。$B$B如果你有足够的荣誉徽章要给我的话，随时来找我。';
