INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4) VALUES (10729,'紫罗兰法师之路','你对你的决定有把握吗，$N?这可不是你可以随便决定的事喔。$B$B紫罗兰徽记会随着力量而成长，只要你继续对紫罗兰之眼证明你自己。') ON DUPLICATE KEY UPDATE Title_loc4='紫罗兰法师之路',OfferRewardText_loc4='你对你的决定有把握吗，$N?这可不是你可以随便决定的事喔。$B$B紫罗兰徽记会随着力量而成长，只要你继续对紫罗兰之眼证明你自己。';
INSERT INTO locales_quest(entry,Title_loc4,OfferRewardText_loc4) VALUES (10730,'紫罗兰治愈者之路','你对你的决定有把握吗，$N?这可不是你可以随便决定的事喔。$B$B紫罗兰徽记会随着力量而成长，只要你继续对紫罗兰之眼证明你自己。') ON DUPLICATE KEY UPDATE Title_loc4='紫罗兰治愈者之路',OfferRewardText_loc4='你对你的决定有把握吗，$N?这可不是你可以随便决定的事喔。$B$B紫罗兰徽记会随着力量而成长，只要你继续对紫罗兰之眼证明你自己。';
