INSERT INTO locales_page_text(entry,Text_loc4) VALUES (1370,'01001101 01100101 01110011 01110011 01100001 01100111 01100101 00100000 01110100 01101111 00100000 01000011 01100001 01110011 01110100 01110000 01101001 01110000 01100101 00111010 00100000 01111001 01101111 01110101 01110010 00100000 01101100 01100001 01110101 01101110 01100100 01110010 01111001 00100111 01110011 00100000 01110010 01100101 01100001 01100100 01111001 00100000 01100110 01101111 01110010 00100000 01110000 01101001 01100011 01101011 01110101 01110000 00101110 ') ON DUPLICATE KEY UPDATE Text_loc4='01001101 01100101 01110011 01110011 01100001 01100111 01100101 00100000 01110100 01101111 00100000 01000011 01100001 01110011 01110100 01110000 01101001 01110000 01100101 00111010 00100000 01111001 01101111 01110101 01110010 00100000 01101100 01100001 01110101 01101110 01100100 01110010 01111001 00100111 01110011 00100000 01110010 01100101 01100001 01100100 01111001 00100000 01100110 01101111 01110010 00100000 01110000 01101001 01100011 01101011 01110101 01110000 00101110 ';
INSERT INTO locales_page_text(entry,Text_loc4) VALUES (1371,'<HTML>
INSERT INTO locales_page_text(entry,Text_loc4) VALUES (1391,'<HTML>
INSERT INTO locales_page_text(entry,Text_loc4) VALUES (1392,'尼尔斯修士:$B$B我的葡萄得救了!$N，也就是这封信的携带者，勇敢地闯入我那满是盗贼的园子，然后带着我的葡萄杀了出来。虽然迪菲亚兄弟会的人依然在河岸上巡逻，但是我所有的收成几乎全都保住了。$B$B你可以在你的商店中再次供应葡萄了。$B$B愿圣光保佑我们，$B- 米莉·奥斯沃斯') ON DUPLICATE KEY UPDATE Text_loc4='尼尔斯修士:$B$B我的葡萄得救了!$N，也就是这封信的携带者，勇敢地闯入我那满是盗贼的园子，然后带着我的葡萄杀了出来。虽然迪菲亚兄弟会的人依然在河岸上巡逻，但是我所有的收成几乎全都保住了。$B$B你可以在你的商店中再次供应葡萄了。$B$B愿圣光保佑我们，$B- 米莉·奥斯沃斯';
INSERT INTO locales_page_text(entry,Text_loc4) VALUES (1430,'尼尔斯修士:$B$B我的葡萄得救了!$N，也就是这封信的携带者，勇敢地闯入我那满是盗贼的园子，然后带着我的葡萄杀了出来。虽然迪菲亚兄弟会的人依然在河岸上巡逻，但是我所有的收成几乎全都保住了。$B$B你可以在你的商店中再次供应葡萄了。$B$B愿圣光保佑我们，$B- 米莉·奥斯沃斯') ON DUPLICATE KEY UPDATE Text_loc4='尼尔斯修士:$B$B我的葡萄得救了!$N，也就是这封信的携带者，勇敢地闯入我那满是盗贼的园子，然后带着我的葡萄杀了出来。虽然迪菲亚兄弟会的人依然在河岸上巡逻，但是我所有的收成几乎全都保住了。$B$B你可以在你的商店中再次供应葡萄了。$B$B愿圣光保佑我们，$B- 米莉·奥斯沃斯';
INSERT INTO locales_page_text(entry,Text_loc4) VALUES (1431,'沃弗克·铁壶$B$B沃弗克在黑铁酒窖的储藏室工作，他为黑暗守卫者做出的牺牲意义重大。$B$B愿他的灵魂坚定而顽强。') ON DUPLICATE KEY UPDATE Text_loc4='沃弗克·铁壶$B$B沃弗克在黑铁酒窖的储藏室工作，他为黑暗守卫者做出的牺牲意义重大。$B$B愿他的灵魂坚定而顽强。';
INSERT INTO locales_page_text(entry,Text_loc4) VALUES (1432,'比塞克·雷眉$B$B比塞克的游荡将他引入了黑石深渊，山脉的秘密在召唤着他。$B$B愿他的灵魂永远不要踌躇。') ON DUPLICATE KEY UPDATE Text_loc4='比塞克·雷眉$B$B比塞克的游荡将他引入了黑石深渊，山脉的秘密在召唤着他。$B$B愿他的灵魂永远不要踌躇。';
INSERT INTO locales_page_text(entry,Text_loc4) VALUES (1433,'尤格尔·锤手$B$B尤格尔是一位技巧高超的凿工，当他还没有遇到黑暗之钥的时候，他在工匠大厅中雕琢伟大的作品。') ON DUPLICATE KEY UPDATE Text_loc4='尤格尔·锤手$B$B尤格尔是一位技巧高超的凿工，当他还没有遇到黑暗之钥的时候，他在工匠大厅中雕琢伟大的作品。';
INSERT INTO locales_page_text(entry,Text_loc4) VALUES (1434,'希姆雷尔·暗齿$B$B当黑暗之钥的疯狂占据希姆雷尔时，只有死者的尖叫可以使他平静。$B$B希姆雷尔总是在竞技场旁坐着。愿我们的血腥搏杀可以平息他心中的怒气。') ON DUPLICATE KEY UPDATE Text_loc4='希姆雷尔·暗齿$B$B当黑暗之钥的疯狂占据希姆雷尔时，只有死者的尖叫可以使他平静。$B$B希姆雷尔总是在竞技场旁坐着。愿我们的血腥搏杀可以平息他心中的怒气。';
INSERT INTO locales_page_text(entry,Text_loc4) VALUES (1435,'奥弗加特·石拳$B$B丧命于黑暗守卫者奥弗加特锤下的挑战者不计其数。$B$B西部兵营的士兵们在他走过时卑躬屈膝。他们之中有谁敢直视奥弗加特的双眼并看到黑暗之钥的秘密呢?') ON DUPLICATE KEY UPDATE Text_loc4='奥弗加特·石拳$B$B丧命于黑暗守卫者奥弗加特锤下的挑战者不计其数。$B$B西部兵营的士兵们在他走过时卑躬屈膝。他们之中有谁敢直视奥弗加特的双眼并看到黑暗之钥的秘密呢?';
INSERT INTO locales_page_text(entry,Text_loc4) VALUES (1436,'佩沃尔·铁足$B$B黑暗守卫者佩沃尔是我们最为尊重的侍徒。他携带黑暗之钥的时间远远超过其他黑暗守卫者，这使他付出了惊人的代价。$B$B他的牺牲让我们感到惋惜，对他的怀念会一直留在我们心中……自从黑暗占据了他。') ON DUPLICATE KEY UPDATE Text_loc4='佩沃尔·铁足$B$B黑暗守卫者佩沃尔是我们最为尊重的侍徒。他携带黑暗之钥的时间远远超过其他黑暗守卫者，这使他付出了惊人的代价。$B$B他的牺牲让我们感到惋惜，对他的怀念会一直留在我们心中……自从黑暗占据了他。';
INSERT INTO locales_page_text(entry,Text_loc4) VALUES (1470,'佩沃尔・铁足$B$B 黑暗守护者佩沃尔是我们最为尊重的信徒。他携带黑暗之钥的时间远远超过其它黑暗守护者，这使他付出了惊人的代价。$B$B 他的牺牲让我们感到惋惜，对他的怀念会一直留在我们心中……自从黑暗占据了他。') ON DUPLICATE KEY UPDATE Text_loc4='佩沃尔・铁足$B$B 黑暗守护者佩沃尔是我们最为尊重的信徒。他携带黑暗之钥的时间远远超过其它黑暗守护者，这使他付出了惊人的代价。$B$B 他的牺牲让我们感到惋惜，对他的怀念会一直留在我们心中……自从黑暗占据了他。';
INSERT INTO locales_page_text(entry,Text_loc4) VALUES (1471,'所罗门镇长:$B$B这封命令的携带者已经被授予暴风城官方代表的资格。您可以让$g他:她;寻找黑龙军团和黑石兽人之间的联系。如果发现了此类证据，请让这个代表把证据带回暴风城，亲自交给我，届时我再酌情派遣部队来协助湖畔镇。$B$B此致，$B$B$B$B伯瓦尔·弗塔根公爵') ON DUPLICATE KEY UPDATE Text_loc4='所罗门镇长:$B$B这封命令的携带者已经被授予暴风城官方代表的资格。您可以让$g他:她;寻找黑龙军团和黑石兽人之间的联系。如果发现了此类证据，请让这个代表把证据带回暴风城，亲自交给我，届时我再酌情派遣部队来协助湖畔镇。$B$B此致，$B$B$B$B伯瓦尔·弗塔根公爵';
