INSERT INTO locales_page_text(entry,Text_loc4) VALUES (2171,'菲尔拉蕾·迅箭$B血色十字军游侠队长$B奎尔萨拉斯的公民$B失踪于银松森林') ON DUPLICATE KEY UPDATE Text_loc4='菲尔拉蕾·迅箭$B血色十字军游侠队长$B奎尔萨拉斯的公民$B失踪于银松森林';
INSERT INTO locales_page_text(entry,Text_loc4) VALUES (2172,'费伦·玛库斯血色修道院的高阶修士 $B斯坦索姆的市民$B在第一次血色修道院防御战中牺牲') ON DUPLICATE KEY UPDATE Text_loc4='费伦·玛库斯血色修道院的高阶修士 $B斯坦索姆的市民$B在第一次血色修道院防御战中牺牲';
INSERT INTO locales_page_text(entry,Text_loc4) VALUES (2173,'哈萨尔·图塞特$B血色十字军的圣骑士$B艾泽拉斯的公民 - 白银之手骑士团的圣骑士$B失踪于被诅咒的城市斯坦索姆') ON DUPLICATE KEY UPDATE Text_loc4='哈萨尔·图塞特$B血色十字军的圣骑士$B艾泽拉斯的公民 - 白银之手骑士团的圣骑士$B失踪于被诅咒的城市斯坦索姆';
